async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(7319);
  noiseSeed(7319);
}

function draw() {
  translate(-width / 2, -height / 2);
  background(PAL.paper);

  // Precompute key geometries
  const geom = buildHelmetGeometry();

  // 1. Aged ivory sheet, foxing, margins & technical construction grid
  drawPaperAndGrid(geom);

  // 2. Ambient drop shadows on the textbook sheet
  drawPageShadows(geom);

  // 3. Far-side hollow interior visible through front face opening
  drawFarSideInterior(geom);

  // 4. Outer shell: Glossy Candy-Apple Red Gelcoat (around Window 1)
  drawOuterGelcoatShell(geom);

  // 5. Cutaway Layer 2: Fibreglass Reinforced Plastic (FRP) Weave (Window 1 \ Window 2)
  drawFibreglassLayer(geom);

  // 6. Cutaway Layer 3: Expanded Polystyrene (EPS) Foam (Window 2 \ Window 3 + 3D step wall)
  drawEpsFoamLayer(geom);

  // 7. Cutaway Layer 4: Quilted Comfort Liner & Strap Anchor (Inside Window 3)
  drawQuiltedLinerLayer(geom);

  // 8. Cut edges of windows & the Three Hinged Paper Flaps (folded out to the right)
  drawCutEdgesAndFlaps(geom);

  // 9. Chrome/Rubber Edge Trim, Visor Snaps & Hanging Chin Strap with D-Rings
  drawTrimSnapsAndStrap(geom);

  // 10. Didactic Leader Lines, Numbered Margin Circles, Scale Bar & Legend Block
  drawDidacticAnnotations(geom);

  noLoop();
}

// ============================================================================
// GEOMETRY & PARAMETRIC DOME MAPPING
// ============================================================================

function buildHelmetGeometry() {
  // Parametric mapping for the side cutaway zone (u: 0..1 left-to-right, v: 0..1 top-to-bottom)
  function domePt(u, v) {
    // Top curve T(u) from front-top (405, 280) over crown (585, 245) to back-top (760, 315)
    const tx = lerp(405, 760, u) + Math.sin(u * Math.PI) * 8;
    const ty = lerp(280, 315, u) - Math.sin(u * Math.PI) * 48;

    // Bottom curve B(u) from jaw-side (425, 685) across ear-skirt (595, 710) to rear nape (750, 665)
    const bx = lerp(425, 750, u);
    const by = lerp(685, 665, u) + Math.sin(u * Math.PI) * 32;

    // Meridian bow along v
    const bowX = Math.sin(v * Math.PI) * (10 + 36 * (u - 0.25));
    const bowY = Math.sin(u * Math.PI) * (v - 0.5) * 8;

    return [
      lerp(tx, bx, v) + bowX,
      lerp(ty, by, v) + bowY
    ];
  }

  function makeWindowPoly(u0, u1, v0, v1, steps = 16) {
    const pts = [];
    // Top edge: u0 -> u1 at v0
    for (let i = 0; i <= steps; i++) {
      pts.push(domePt(lerp(u0, u1, i / steps), v0));
    }
    // Right edge (hinge): v0 -> v1 at u1
    for (let i = 1; i <= steps; i++) {
      pts.push(domePt(u1, lerp(v0, v1, i / steps)));
    }
    // Bottom edge: u1 -> u0 at v1
    for (let i = 1; i <= steps; i++) {
      pts.push(domePt(lerp(u1, u0, i / steps), v1));
    }
    // Left edge: v1 -> v0 at u0
    for (let i = 1; i < steps; i++) {
      pts.push(domePt(u0, lerp(v1, v0, i / steps)));
    }
    return pts;
  }

  // Three nested cutaway windows
  const win1 = makeWindowPoly(0.00, 0.96, 0.02, 0.98, 18); // Red gelcoat cutout
  const win2 = makeWindowPoly(0.16, 0.84, 0.15, 0.85, 16); // Fibreglass cutout
  const win3 = makeWindowPoly(0.33, 0.72, 0.28, 0.73, 14); // EPS foam outer cutout

  // Inner boundary of EPS foam (stepped inward by (+15, +7) to show thick 3D foam wall)
  const win3Inner = win3.map((p, idx) => {
    // Hinge side (right edge) tapers less than left/top cut wall
    const total = win3.length;
    const isRight = idx >= 14 && idx <= 28;
    const dx = isRight ? -2 : 15;
    const dy = isRight ? 0 : 7;
    return [p[0] + dx, p[1] + dy];
  });

  // Outer shell silhouette control points
  const topCrown = [
    [258, 392], [278, 336], [322, 278], [392, 232],
    [478, 206], [568, 202], [658, 222], [738, 266],
    [796, 332], [832, 412], [842, 498], [830, 588],
    [796, 675]
  ];
  const bottomSkirt = [
    [796, 675], [735, 712], [655, 738], [565, 752],
    [485, 755], [422, 748]
  ];
  const nearFaceOpening = [
    [422, 748], [386, 692], [362, 624], [350, 552],
    [342, 486], [312, 434], [258, 392]
  ];
  const farFaceOpening = [
    [258, 392], [242, 442], [244, 512], [262, 586],
    [298, 658], [352, 718], [422, 748]
  ];

  const shellOutline = [
    ...topCrown,
    ...bottomSkirt.slice(1),
    ...nearFaceOpening.slice(1, -1)
  ];

  // Build the 3 folded paper flaps (hinged on right edges of win1, win2, win3)
  function buildFlapGeometry(uHinge, v0, v1, widthOut, curlSize, tabV) {
    const steps = 16;
    const hingePts = [];
    for (let i = 0; i <= steps; i++) {
      hingePts.push(domePt(uHinge, lerp(v0, v1, i / steps)));
    }
    const topH = hingePts[0];
    const botH = hingePts[steps];

    // Outer edge of folded flap (curved in 3D perspective to the right)
    const outerPts = [];
    for (let i = 0; i <= steps; i++) {
      const t = i / steps;
      const hp = hingePts[i];
      const arch = Math.sin(t * Math.PI) * (widthOut * 0.16);
      const perspectY = (t - 0.5) * (widthOut * 0.08);
      outerPts.push([
        hp[0] + widthOut + arch,
        hp[1] + perspectY - 6
      ]);
    }

    // Semicircular finger pull-tab on the outer edge around tabV
    const poly = [];
    // Hinge from bottom to top
    for (let i = steps; i >= 0; i--) poly.push(hingePts[i]);
    // Top edge from hinge to outer corner (with slight upward paper lift)
    for (let i = 1; i <= 6; i++) {
      const s = i / 6;
      // Stop slightly early if top-right corner curls
      const endP = [outerPts[0][0] - curlSize * 0.7, outerPts[0][1] + curlSize * 0.15];
      poly.push([
        lerp(topH[0], endP[0], s),
        lerp(topH[1], endP[1], s) - Math.sin(s * Math.PI) * 8
      ]);
    }
    // Diagonal bevel across curled top-right corner
    const curlRight = [outerPts[3][0], outerPts[3][1]];
    poly.push(curlRight);

    // Outer edge down, inserting finger pull-tab
    for (let i = 4; i <= steps; i++) {
      const t = i / steps;
      const op = outerPts[i];
      if (Math.abs(t - tabV) < 0.13) {
        const local = (t - (tabV - 0.13)) / 0.26;
        const tabBulge = Math.sin(local * Math.PI) * 26;
        poly.push([op[0] + tabBulge, op[1]]);
      } else {
        poly.push(op);
      }
    }

    // Bottom edge from outer corner back to bottom hinge
    for (let i = 5; i >= 1; i--) {
      const s = i / 6;
      poly.push([
        lerp(botH[0], outerPts[steps][0], s),
        lerp(botH[1], outerPts[steps][1], s) + Math.sin(s * Math.PI) * 6
      ]);
    }

    // Curled corner triangle (shows front surface material!)
    const curlTip = [outerPts[0][0] - curlSize * 1.15, outerPts[0][1] + curlSize * 0.85];
    const curlTop = [outerPts[0][0] - curlSize * 0.7, outerPts[0][1] + curlSize * 0.15];
    const curlPoly = [curlTop, curlRight, curlTip];

    return { hingePts, outerPts, poly, curlPoly, topH, botH };
  }

  const flap1 = buildFlapGeometry(0.96, 0.02, 0.98, 225, 44, 0.42);
  const flap2 = buildFlapGeometry(0.84, 0.15, 0.85, 185, 36, 0.56);
  const flap3 = buildFlapGeometry(0.72, 0.28, 0.73, 148, 28, 0.68);

  return {
    domePt,
    win1, win2, win3, win3Inner,
    topCrown, bottomSkirt, nearFaceOpening, farFaceOpening, shellOutline,
    flap1, flap2, flap3
  };
}

// ============================================================================
// LOW-LEVEL DRAWING & GEOMETRY HELPERS
// ============================================================================

function drawPolyFill(pts, col, alpha = 150, bleed = 0.08, tex = 0.35) {
  if (!pts || pts.length < 3) return;
  brush.noStroke();
  brush.fill(col, alpha);
  brush.fillBleed(bleed, "out");
  brush.fillTexture(tex, 0.25);
  brush.beginShape(0);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(CLOSE);
  brush.noFill();
}

function drawPolyWash(pts, col, alpha = 180) {
  if (!pts || pts.length < 3) return;
  brush.noStroke();
  brush.wash(col, alpha);
  brush.beginShape(0);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(CLOSE);
  brush.noWash();
}

function drawPath(pts, brushName, col, weight = 1, closed = false, curvature = 0.25) {
  if (!pts || pts.length < 2) return;
  brush.noFill();
  brush.set(brushName, col, weight);
  const list = closed ? [...pts, pts[0]] : pts;
  if (list.length === 2 || curvature === 0) {
    for (let i = 0; i < list.length - 1; i++) {
      brush.line(list[i][0], list[i][1], list[i + 1][0], list[i + 1][1]);
    }
  } else {
    brush.spline(list, curvature);
  }
}

function drawDashedPath(pts, brushName, col, weight = 0.8, dashLen = 10, gapLen = 7) {
  brush.noFill();
  brush.set(brushName, col, weight);
  for (let i = 0; i < pts.length - 1; i++) {
    const x1 = pts[i][0], y1 = pts[i][1];
    const x2 = pts[i + 1][0], y2 = pts[i + 1][1];
    const d = dist(x1, y1, x2, y2);
    const step = dashLen + gapLen;
    const count = Math.max(1, Math.floor(d / step));
    for (let k = 0; k < count; k++) {
      const t0 = (k * step) / d;
      const t1 = Math.min(1, (k * step + dashLen) / d);
      if (t1 > t0) {
        brush.line(lerp(x1, x2, t0), lerp(y1, y2, t0), lerp(x1, x2, t1), lerp(y1, y2, t1));
      }
    }
  }
}

function pointInPoly(x, y, poly) {
  let inside = false;
  for (let i = 0, j = poly.length - 1; i < poly.length; j = i++) {
    const xi = poly[i][0], yi = poly[i][1];
    const xj = poly[j][0], yj = poly[j][1];
    const intersect = ((yi > y) !== (yj > y)) &&
      (x < (xj - xi) * (y - yi) / ((yj - yi) || 1e-6) + xi);
    if (intersect) inside = !inside;
  }
  return inside;
}

function drawClippedLine(x1, y1, x2, y2, includePoly, excludePoly, brushName, col, weight) {
  const d = dist(x1, y1, x2, y2);
  const steps = Math.max(4, Math.ceil(d / 4));
  let inRun = false;
  let sx = 0, sy = 0;
  brush.set(brushName, col, weight);
  for (let i = 0; i <= steps; i++) {
    const t = i / steps;
    const px = lerp(x1, x2, t);
    const py = lerp(y1, y2, t);
    const ok = (!includePoly || pointInPoly(px, py, includePoly)) &&
               (!excludePoly || !pointInPoly(px, py, excludePoly));
    if (ok && !inRun) {
      inRun = true;
      sx = px; sy = py;
    } else if (!ok && inRun) {
      inRun = false;
      const prevT = (i - 1) / steps;
      const ex = lerp(x1, x2, prevT);
      const ey = lerp(y1, y2, prevT);
      if (dist(sx, sy, ex, ey) > 1.5) brush.line(sx, sy, ex, ey);
    } else if (ok && i === steps && inRun) {
      if (dist(sx, sy, px, py) > 1.5) brush.line(sx, sy, px, py);
    }
  }
}

function drawText(str, x, y, h, brushName = "rotring", col = PAL.ink, weight = 0.35, tracking = 0.35) {
  const charW = h * 0.68;
  let cx = x;
  brush.noFill();
  brush.set(brushName, col, weight);
  for (let idx = 0; idx < str.length; idx++) {
    const ch = str[idx];
    if (ch === " ") {
      cx += charW * 0.9;
      continue;
    }
    const g = GLYPHS[ch] || GLYPHS[ch.toUpperCase()];
    if (g) {
      for (let s = 0; s < g.length; s++) {
        const strokePts = g[s];
        for (let p = 0; p < strokePts.length - 1; p++) {
          const x1 = cx + strokePts[p][0] * charW;
          const y1 = y + strokePts[p][1] * h;
          const x2 = cx + strokePts[p + 1][0] * charW;
          const y2 = y + strokePts[p + 1][1] * h;
          brush.line(x1, y1, x2, y2);
        }
      }
    }
    cx += charW * (1 + tracking);
  }
}

// ============================================================================
// 1. PAPER SHEET, FOXING & TECHNICAL CONSTRUCTION GRID
// ============================================================================

function drawPaperAndGrid(geom) {
  // Subtle aged watercolor blooms around margins
  const foxBlooms = [
    [[45, 45], [340, 45], [280, 210], [45, 260]],
    [[880, 45], [1155, 45], [1155, 270], [940, 190]],
    [[45, 920], [240, 990], [290, 1155], [45, 1155]],
    [[910, 960], [1155, 890], [1155, 1155], [850, 1155]],
    [[480, 45], [760, 45], [720, 115], [510, 105]]
  ];
  for (const b of foxBlooms) {
    drawPolyFill(b, PAL.paperWarm, 55, 0.35, 0.55);
  }

  // Foxing spots (vintage textbook paper charm)
  const foxSpots = [
    [115, 130, 18], [1085, 160, 22], [95, 830, 15], [1095, 760, 19],
    [185, 1085, 24], [520, 90, 14], [1040, 1090, 16], [85, 420, 12],
    [1115, 480, 14], [610, 1110, 18]
  ];
  for (const [fx, fy, fr] of foxSpots) {
    brush.noStroke();
    brush.fill(PAL.paperFox, 38);
    brush.fillBleed(0.4, "out");
    brush.circle(fx, fy, fr, 0.35);
    brush.noFill();
  }

  // Fine foxing stipple near edges
  brush.set("spray", PAL.paperFox, 0.45);
  brush.line(70, 80, 240, 95);
  brush.line(960, 85, 1120, 110);
