// ============================================================================
// 5. CUTAWAY LAYER 2: FIBREGLASS WEAVE (WINDOW 1 \ WINDOW 2)
// ============================================================================

function drawFibreglassLayer(geom) {
  // Fill Window 1 around Window 2 using 4 strips (Top, Bottom, Left, Right)
  const w1T = geom.win1.slice(0, 19);
  const w1R = geom.win1.slice(18, 37);
  const w1B = geom.win1.slice(36, 55);
  const w1L = [geom.win1[0], ...geom.win1.slice(54).reverse()];

  const w2T = geom.win2.slice(0, 17);
  const w2R = geom.win2.slice(16, 33);
  const w2B = geom.win2.slice(32, 49);
  const w2L = [geom.win2[0], ...geom.win2.slice(48).reverse()];

  const frpTop = [...w1T, ...[...w2T].reverse()];
  const frpRight = [...w1R, ...[...w2R].reverse()];
  const frpBot = [...w1B, ...[...w2B].reverse()];
  const frpLeft = [...w1L, ...[...w2L].reverse()];

  for (const strip of [frpTop, frpRight, frpBot, frpLeft]) {
    drawPolyFill(strip, PAL.frpLight, 170, 0.05, 0.35);
    drawPolyFill(strip, PAL.frpMid, 115, 0.08, 0.42);
  }

  // Subtle green-amber fibreglass resin tint in mid-zone
  drawPolyFill(frpTop, PAL.frpSage, 55, 0.1, 0.3);
  drawPolyFill(frpLeft, PAL.frpAmber, 75, 0.1, 0.35);

  // Cast shadow inside Window 1 from the cut Red Gelcoat edge (top & left edge overhang)
  const gelcoatShadow = [
    ...w1L.slice(0, 14),
    ...w1L.slice(0, 14).reverse().map(p => [p[0] + 16, p[1] + 10]),
  ];
  drawPolyFill(gelcoatShadow, PAL.shadowWash, 85, 0.12, 0.35);

  const gelcoatShadowTop = [
    ...w1T.slice(0, 16),
    ...w1T.slice(0, 16).reverse().map(p => [p[0] + 8, p[1] + 15])
  ];
  drawPolyFill(gelcoatShadowTop, PAL.shadowWash, 85, 0.12, 0.35);

  // Hyperreal 3D-mapped orthogonal basketweave roving (warp & weft glass-fibre bundles)
  const N = 26;
  for (let iu = 0; iu < N; iu++) {
    for (let iv = 0; iv < N; iv++) {
      const u0 = iu / N, u1 = (iu + 1) / N;
      const v0 = iv / N, v1 = (iv + 1) / N;
      const uc = (u0 + u1) * 0.5;
      const vc = (v0 + v1) * 0.5;
      const center = geom.domePt(uc, vc);

      if (!pointInPoly(center[0], center[1], geom.win1)) continue;
      if (pointInPoly(center[0], center[1], geom.win2)) continue;

      const isWarp = (iu + iv) % 2 === 0;
      // Draw 3 parallel glass-fibre bundle strands per weave square
      for (let s = 0.22; s <= 0.78; s += 0.28) {
        let pA, pB;
        if (isWarp) {
          pA = geom.domePt(u0, lerp(v0, v1, s));
          pB = geom.domePt(u1, lerp(v0, v1, s));
        } else {
          pA = geom.domePt(lerp(u0, u1, s), v0);
          pB = geom.domePt(lerp(u0, u1, s), v1);
        }
        brush.set("2H", isWarp ? PAL.frpDark : PAL.frpAmber, 0.34);
        brush.line(pA[0], pA[1], pB[0], pB[1]);
      }

      // Highlight glint on the crown of each woven roving bundle
      const hA = isWarp ? geom.domePt(lerp(u0, u1, 0.25), vc) : geom.domePt(uc, lerp(v0, v1, 0.25));
      const hB = isWarp ? geom.domePt(lerp(u0, u1, 0.75), vc) : geom.domePt(uc, lerp(v0, v1, 0.75));
      brush.set("rotring", "#FFFBF0", 0.38);
      brush.line(hA[0], hA[1], hB[0], hB[1]);

      // Dark resin interstitial pinhole at corner of weave square
      const corner = geom.domePt(u0, v0);
      brush.set("rotring", PAL.frpDark, 0.52);
      brush.line(corner[0], corner[1], corner[0] + 1.5, corner[1] + 1.5);
    }
  }
}

// ============================================================================
// 6. CUTAWAY LAYER 3: GREY EPS FOAM (WINDOW 2 \ WINDOW 3 + 3D BEVEL WALL)
// ============================================================================

function drawEpsFoamLayer(geom) {
  const w2T = geom.win2.slice(0, 17);
  const w2R = geom.win2.slice(16, 33);
  const w2B = geom.win2.slice(32, 49);
  const w2L = [geom.win2[0], ...geom.win2.slice(48).reverse()];

  const w3T = geom.win3.slice(0, 15);
  const w3R = geom.win3.slice(14, 29);
  const w3B = geom.win3.slice(28, 43);
  const w3L = [geom.win3[0], ...geom.win3.slice(42).reverse()];

  const epsTop = [...w2T, ...[...w3T].reverse()];
  const epsRight = [...w2R, ...[...w3R].reverse()];
  const epsBot = [...w2B, ...[...w3B].reverse()];
  const epsLeft = [...w2L, ...[...w3L].reverse()];

  // Base cool pastel pearl-grey & slate-blue watercolor washes
  for (const strip of [epsTop, epsRight, epsBot, epsLeft]) {
    drawPolyFill(strip, PAL.epsLight, 180, 0.05, 0.35);
    drawPolyFill(strip, PAL.epsMid, 125, 0.08, 0.4);
  }

  // Shadow cast by Fibreglass cut edge onto EPS Foam (top & left edge of Window 2)
  const frpShadowLeft = [
    ...w2L.slice(0, 13),
    ...w2L.slice(0, 13).reverse().map(p => [p[0] + 14, p[1] + 9])
  ];
  const frpShadowTop = [
    ...w2T.slice(0, 14),
    ...w2T.slice(0, 14).reverse().map(p => [p[0] + 8, p[1] + 13])
  ];
  drawPolyFill(frpShadowLeft, PAL.shadowWash, 90, 0.12, 0.35);
  drawPolyFill(frpShadowTop, PAL.shadowWash, 90, 0.12, 0.35);

  // 3D Thick Molded EPS Foam Cut Wall around Window 3 (connecting win3 to win3Inner)
  const wallLeft = [
    ...w3L,
    ...geom.win3Inner.slice(42).reverse(),
    geom.win3Inner[0]
  ];
  const wallTop = [
    ...w3T,
    ...geom.win3Inner.slice(0, 15).reverse()
  ];
  drawPolyFill(wallLeft, PAL.epsSlate, 185, 0.04, 0.35);
  drawPolyFill(wallLeft, PAL.epsDark, 95, 0.06, 0.4);
  drawPolyFill(wallTop, PAL.epsSlate, 165, 0.04, 0.35);

  // Cellular Expanded Polystyrene (EPS) Bead Mosaic on the surface of Layer 3
  const cols = 22, rows = 22;
  const grid = [];
  for (let i = 0; i <= cols; i++) {
    grid[i] = [];
    for (let j = 0; j <= rows; j++) {
      const u = lerp(0.15, 0.85, i / cols) + (noise(i * 0.7, j * 0.7) - 0.5) * 0.018;
      const v = lerp(0.14, 0.86, j / rows) + (noise(i * 0.7 + 50, j * 0.7 + 50) - 0.5) * 0.018;
      grid[i][j] = geom.domePt(u, v);
    }
  }

  for (let i = 0; i < cols; i++) {
    for (let j = 0; j < rows; j++) {
      const p00 = grid[i][j];
      const p10 = grid[i + 1][j];
      const p11 = grid[i + 1][j + 1];
      const p01 = grid[i][j + 1];
      const cx = (p00[0] + p10[0] + p11[0] + p01[0]) * 0.25;
      const cy = (p00[1] + p10[1] + p11[1] + p01[1]) * 0.25;

      if (!pointInPoly(cx, cy, geom.win2)) continue;
      if (pointInPoly(cx, cy, geom.win3)) continue;

      // Chamfered 6-sided polygonal foam bead
      const mTop = [(p00[0] + p10[0]) * 0.5, (p00[1] + p10[1]) * 0.5];
      const mRight = [(p10[0] + p11[0]) * 0.5, (p10[1] + p11[1]) * 0.5];
      const mBot = [(p01[0] + p11[0]) * 0.5, (p01[1] + p11[1]) * 0.5];
      const mLeft = [(p00[0] + p01[0]) * 0.5, (p00[1] + p01[1]) * 0.5];

      const beadPts = [
        [lerp(p00[0], cx, 0.15), lerp(p00[1], cy, 0.15)],
        mTop,
        [lerp(p10[0], cx, 0.15), lerp(p10[1], cy, 0.15)],
        mRight,
        [lerp(p11[0], cx, 0.15), lerp(p11[1], cy, 0.15)],
        mBot,
        [lerp(p01[0], cx, 0.15), lerp(p01[1], cy, 0.15)],
        mLeft
      ];

      drawPath(beadPts, "2H", PAL.epsDark, 0.3, true, 0.15);

      // Specular highlight on top-left of bead & shadow on bottom-right
      brush.set("rotring", "#FFFFFF", 0.35);
      brush.line(mLeft[0] + 1.5, mLeft[1] - 1, mTop[0] + 1, mTop[1] + 1.5);
      brush.set("2H", PAL.epsDark, 0.32);
      brush.line(mBot[0] - 1, mBot[1] - 1, mRight[0] - 1.5, mRight[1] - 0.5);

      // Occasional molded micro-ventilation dimple in the EPS foam
      if ((i * 7 + j * 13) % 19 === 0) {
        brush.set("rotring", PAL.inkMid, 0.45);
        brush.circle(cx, cy, 2.2, 0.1);
      }
    }
  }

  // Cross-sectioned foam cell lines along the 16px 3D bevel wall of Window 3
  brush.set("2H", PAL.epsDark, 0.35);
  for (let i = 0; i < 14; i++) {
    const a1 = geom.win3[i];
    const b1 = geom.win3Inner[i];
    brush.line(a1[0], a1[1], b1[0], b1[1]);
    const a2 = geom.win3[42 + i];
    const b2 = geom.win3Inner[42 + i];
    if (a2 && b2) brush.line(a2[0], a2[1], b2[0], b2[1]);
  }
  drawPath(geom.win3Inner, "rotring", PAL.inkMid, 0.45, true, 0.1);
}

// ============================================================================
// 7. CUTAWAY LAYER 4: QUILTED COMFORT LINER & STRAP ANCHOR (INSIDE WINDOW 3)
// ============================================================================

function drawQuiltedLinerLayer(geom) {
  // Base pastel dusty-blue & warm oatmeal-taupe fabric washes inside win3Inner
  drawPolyFill(geom.win3Inner, PAL.linerTaupe, 175, 0.05, 0.38);
  drawPolyFill(geom.win3Inner, PAL.linerBlue, 130, 0.08, 0.42);

  // Deep shadow cast by the thick 16px EPS foam wall onto the liner
  const innerL = [geom.win3Inner[0], ...geom.win3Inner.slice(42).reverse()];
  const innerT = geom.win3Inner.slice(0, 15);
  const linerShadowL = [
    ...innerL.slice(0, 12),
    ...innerL.slice(0, 12).reverse().map(p => [p[0] + 18, p[1] + 10])
  ];
  const linerShadowT = [
    ...innerT.slice(0, 13),
    ...innerT.slice(0, 13).reverse().map(p => [p[0] + 8, p[1] + 16])
  ];
  drawPolyFill(linerShadowL, PAL.shadowWash, 110, 0.12, 0.38);
  drawPolyFill(linerShadowT, PAL.shadowWash, 110, 0.12, 0.38);

  // Diamond Quilting & Pillow Shading inside Window 3
  // Diagonal seams in (u, v) space
  const dSteps = 10;
  for (let k = -6; k <= 12; k++) {
    // Diagonal family 1: u + v = const
    const pts1 = [];
    // Diagonal family 2: u - v = const
    const pts2 = [];
    for (let s = 0; s <= dSteps; s++) {
      const u = lerp(0.32, 0.73, s / dSteps);
      const vA = 0.28 + (k * 0.055) - (u - 0.32) * 1.1;
      const vB = 0.28 + (k * 0.055) + (u - 0.32) * 1.1;
      pts1.push(geom.domePt(u, vA));
      pts2.push(geom.domePt(u, vB));
    }

    for (let s = 0; s < dSteps; s++) {
      // Seam valley line + parallel coral double-stitching
      drawClippedLine(pts1[s][0], pts1[s][1], pts1[s + 1][0], pts1[s + 1][1], geom.win3Inner, null, "2H", PAL.linerShadow, 0.45);
      drawClippedLine(pts1[s][0] + 2.5, pts1[s][1] + 1.5, pts1[s + 1][0] + 2.5, pts1[s + 1][1] + 1.5, geom.win3Inner, null, "rotring", PAL.stitchCoral, 0.32);

      drawClippedLine(pts2[s][0], pts2[s][1], pts2[s + 1][0], pts2[s + 1][1], geom.win3Inner, null, "2H", PAL.linerShadow, 0.45);
      drawClippedLine(pts2[s][0] + 2.5, pts2[s][1] - 1.5, pts2[s + 1][0] + 2.5, pts2[s + 1][1] - 1.5, geom.win3Inner, null, "rotring", PAL.stitchCoral, 0.32);
    }
  }

  // Puff highlights & breathable perforations inside each quilted diamond
  for (let u = 0.38; u <= 0.68; u += 0.055) {
    for (let v = 0.34; v <= 0.66; v += 0.055) {
      const p = geom.domePt(u, v);
      if (pointInPoly(p[0], p[1], geom.win3Inner)) {
        brush.set("cpencil", "#FFFDF8", 0.55);
        brush.line(p[0] - 4, p[1] - 2, p[0] + 3, p[1] - 4);
        brush.set("2H", PAL.linerShadow, 0.35);
        brush.line(p[0] - 2, p[1] + 5, p[0] + 5, p[1] + 3);
      }
    }
  }

  // Internal Chin-Strap Anchor Webbing & Steel Dome Rivet at bottom of Window 3
  const anchorTop = geom.domePt(0.51, 0.57);
  const anchorBot = geom.domePt(0.49, 0.73);
  const anchorPoly = [
    [anchorTop[0] - 18, anchorTop[1]],
    [anchorTop[0] + 18, anchorTop[1]],
    [anchorBot[0] + 20, anchorBot[1] + 4],
    [anchorBot[0] - 20, anchorBot[1] + 4]
  ];
  drawPolyFill(anchorPoly, PAL.strapGrey, 195, 0.03, 0.3);
  drawPath(anchorPoly, "rotring", PAL.ink, 0.5, true, 0);

  // Herringbone webbing ribs on internal anchor
  for (let y = anchorTop[1] + 6; y < anchorBot[1]; y += 5) {
    drawClippedLine(anchorTop[0] - 16, y, anchorTop[0], y - 4, geom.win3Inner, null, "2H", PAL.strapDark, 0.35);
    drawClippedLine(anchorTop[0], y - 4, anchorTop[0] + 16, y, geom.win3Inner, null, "2H", PAL.strapDark, 0.35);
  }

  // Steel anchor rivet & washer
  const rx = anchorTop[0], ry = anchorTop[1] + 18;
  brush.noStroke();
  brush.wash("#DDE4EA", 220);
  brush.circle(rx, ry, 11, 0.08);
  brush.noWash();
  brush.set("rotring", PAL.ink, 0.55);
  brush.circle(rx, ry, 11, 0.08);
  brush.circle(rx, ry, 6.5, 0.08);
  brush.line(rx - 4, ry - 4, rx + 4, ry + 4);
}

// ============================================================================
// 8. CUT EDGES & THREE HINGED LIFT-THE-FLAP PAPER FLAPS
// ============================================================================

function drawCutEdgesAndFlaps(geom) {
  // Helper to draw a thin white die-cut paper edge along the non-hinge sides of a window
  function drawPaperCutRim(winPoly, hingeStartIdx, hingeEndIdx, thickness = 3.2) {
    const rimPts = [];
    for (let i = hingeEndIdx; i < winPoly.length; i++) rimPts.push(winPoly[i]);
    for (let i = 0; i <= hingeStartIdx; i++) rimPts.push(winPoly[i]);

    // White cardstock bevel strip
    const innerRim = rimPts.map(p => [p[0] + thickness, p[1] + thickness * 0.65]);
    const bevelPoly = [...rimPts, ...innerRim.reverse()];
    drawPolyWash(bevelPoly, "#FFFDF9", 235);
    drawPath(rimPts, "rotring", PAL.ink, 0.62, false, 0.15);
    drawPath(innerRim.reverse(), "rotring", PAL.inkLight, 0.35, false, 0.15);
  }

  // Draw cut rims for Window 1, Window 2, and Window 3
  drawPaperCutRim(geom.win1, 18, 36, 3.8);
  drawPaperCutRim(geom.win2, 16, 32, 3.2);
  drawPaperCutRim(geom.win3, 14, 28, 2.6);

  // Helper to render each of the 3 folded paper flaps on the right
  function renderSingleFlap(flap, flapIndex, frontTint, backTint, labelStr, subStr) {
    // 1. Cast shadow beneath this flap onto the layer/flap to its left/below
    const castShadow = flap.poly.map(p => [p[0] - 10, p[1] + 15]);
    drawPolyFill(castShadow, PAL.shadowWash, 78, 0.18, 0.4);

    // 2. Opaque ivory cardstock wash so the flap cleanly covers whatever is underneath
    drawPolyWash(flap.poly, PAL.flapBack, 242);
    drawPolyFill(flap.poly, backTint, 48, 0.08, 0.35);

    // 3. Double-line paper thickness along the outer edge of the lifted flap
    const outerThickness = flap.poly.map(p => [p[0] + 2.8, p[1] + 2.2]);
    drawPath(outerThickness, "rotring", PAL.inkLight, 0.35, true, 0.12);
    drawPath(flap.poly, "rotring", PAL.ink, 0.58, true, 0.12);

    // 4. Printed technical backside texture on the lifted flap
    const hLen = flap.hingePts.length - 1;
    for (let i = 2; i < hLen - 1; i += 2) {
      const pL = flap.hingePts[i];
      const pR = flap.outerPts[i];
      const x1 = lerp(pL[0], pR[0], 0.12);
      const y1 = lerp(pL[1], pR[1], 0.12);
      const x2 = lerp(pL[0], pR[0], 0.85);
      const y2 = lerp(pL[1], pR[1], 0.85);
      drawClippedLine(x1, y1, x2, y2, flap.poly, null, "2H", PAL.construction, 0.28);
    }

    // Material-specific ghosted reverse pattern on the back of each flap
    if (flapIndex === 1) {
      // Flap 1 underside: faint rose contour arcs & specular ghost
      for (let t = 0.2; t <= 0.8; t += 0.15) {
        const pts = [];
        for (let i = 1; i < hLen; i++) {
          pts.push([
            lerp(flap.hingePts[i][0], flap.outerPts[i][0], t),
            lerp(flap.hingePts[i][1], flap.outerPts[i][1], t)
          ]);
        }
        drawDashedPath(pts, "2H", PAL.redPastel, 0.35, 7, 5);
      }
    } else if (flapIndex === 2) {
      // Flap 2 underside: golden resin cross-weave ghost
      for (let t = 0.22; t <= 0.78; t += 0.14) {
        const pTop = [lerp(flap.topH[0], flap.outerPts[0][0], t), lerp(flap.topH[1], flap.outerPts[0][1], t) + 12];
        const pBot = [lerp(flap.botH[0], flap.outerPts[hLen][0], t), lerp(flap.botH[1], flap.outerPts[hLen][1], t) - 12];
        drawClippedLine(pTop[0], pTop[1], pBot[0], pBot[1], flap.poly, null, "2H", PAL.frpAmber, 0.3);
      }
    } else if (flapIndex === 3) {
      // Flap 3 underside: molded ventilation ribs on back of EPS foam
      for (let i = 3; i <= hLen - 3; i += 3) {
        const pL = flap.hingePts[i];
        const pR = flap.outerPts[i];
        const mx1 = lerp(pL[0], pR[0], 0.22), my1 = lerp(pL[1], pR[1], 0.22);
        const mx2 = lerp(pL[0], pR[0], 0.76), my2 = lerp(pL[1], pR[1], 0.76);
        brush.set("rotring", PAL.epsSlate, 0.42);
        brush.line(mx1, my1 - 3, mx2, my2 - 3);
        brush.line(mx1, my1 + 3, mx2, my2 + 3);
      }
    }

    // 5. Curled top-right corner showing the front material of the flap!
    drawPolyWash(flap.curlPoly, "#FFFDF9", 240);
    drawPolyFill(flap.curlPoly, frontTint, 185, 0.04, 0.35);
    drawPath(flap.curlPoly, "rotring", PAL.ink, 0.55, true, 0.1);

    // 6. Dashed hinge score/fold line along the left edge of the flap
    drawDashedPath(flap.hingePts, "rotring", PAL.inkMid, 0.48, 8, 6);

    // 7. Stencil label box & Roman numeral on the finger pull-tab
    const midIdx = Math.floor(hLen * 0.52);
    const labelX = lerp(flap.hingePts[midIdx][0], flap.outerPts[midIdx][0], 0.24);
    const labelY = lerp(flap.hingePts[midIdx][1], flap.outerPts[midIdx][1], 0.24);
    drawText(labelStr, labelX, labelY - 12, 9.5, "rotring", PAL.ink, 0.34, 0.28);
    drawText(subStr, labelX, labelY + 4, 7.5, "rotring", PAL.inkMid, 0.26, 0.25);

    // Finger pull-tab semicircular notch indicator
    const tabIdx = Math.floor(hLen * (flapIndex === 1 ? 0.42 : flapIndex === 2 ? 0.56 : 0.68));
    const tabPt = flap.outerPts[tabIdx];
    brush.set("rotring", PAL.inkMid, 0.38);
    brush.circle(tabPt[0] + 10, tabPt[1], 10, 0.08);
    const roman = flapIndex === 1 ? "I" : flapIndex === 2 ? "II" : "III";
    drawText(roman, tabPt[0] + (flapIndex === 3 ? 4 : 6), tabPt[1] - 4, 8, "rotring", PAL.ink, 0.35, 0.2);
  }

  // Render Flaps 1 -> 2 -> 3 in stacking order
  renderSingleFlap(geom.flap1, 1, PAL.redLuminous, PAL.redHi, "FLAP I", "GELCOAT 0.6mm");
  renderSingleFlap(geom.flap2, 2, PAL.frpMid, PAL.frpLight, "FLAP II", "FRP WEAVE 3.2mm");
  renderSingleFlap(geom.flap3, 3, PAL.epsSlate, PAL.epsLight, "FLAP III", "EPS FOAM 28mm");
}

// ============================================================================
// 9. CHROME/RUBBER EDGE TRIM, VISOR SNAPS & HANGING CHIN STRAP
// ============================================================================

function drawTrimSnapsAndStrap(geom) {
  // 1. Vulcanized Black Rubber & Chrome Beading Trim around Face Opening & Bottom Skirt
  const trimSpine = [
    ...geom.nearFaceOpening.slice().reverse(),
    ...geom.bottomSkirt.slice(1)
  ];

  // Outer rubber moulding strip (11px wide)
  const trimOuter = [];
  const trimInner = [];
  for (let i = 0; i < trimSpine.length; i++) {
    const p = trimSpine[i];
    // Normal pointing inward toward helmet dome center (560, 480)
    const dx = 560 - p[0], dy = 480 - p[1];
    const len = Math.hypot(dx, dy) || 1;
    const nx = dx / len, ny = dy / len;
    trimOuter.push([p[0] - nx * 4, p[1] - ny * 4]);
    trimInner.push([p[0] + nx * 9, p[1] + ny * 9]);
  }
  const rubberPoly = [...trimOuter, ...[...trimInner].reverse()];
  drawPolyWash(rubberPoly, "#3A3840", 230);

  // Chrome inner bead strip
  const chromeInner = trimSpine.map(p => {
    const dx = 560 - p[0], dy = 480 - p[1];
    const len = Math.hypot(dx, dy) || 1;
    return [p[0] + (dx / len) * 4.5, p[1] + (dy / len) * 4.5];
  });
  drawPath(chromeInner, "rotring", "#EDF4FA", 1.15, false, 0.2);
  drawPath(trimOuter, "rotring", PAL.ink, 0.65, false, 0.2);
  drawPath(trimInner, "rotring", PAL.ink, 0.55, false, 0.2);

  // Far-side edge trim along the far face opening
  drawPath(geom.farFaceOpening, "rotring", "#3A3840", 1.4, false, 0.2);
  drawPath(geom.farFaceOpening, "rotring", "#DCE6F0", 0.5, false, 0.2);

  // 2. Three Chrome Visor Snap Studs along the Brow & Temple
  function drawChromeSnap(x, y, rx, ry, angle) {
    push();
    translate(x, y);
    rotate(angle);
    // Cast shadow on red gelcoat
    brush.noStroke();
    brush.fill(PAL.redDeep, 140);
    brush.circle(4, 5, rx, 0.1);
    brush.noFill();
    // Chrome base flange
    brush.wash("#E4ECF4", 240);
    brush.circle(0, 0, rx, 0.08);
    brush.noWash();
    brush.set("rotring", PAL.ink, 0.55);
    brush.circle(0, 0, rx, 0.08);
    brush.circle(0, 0, rx * 0.65, 0.08);
    // Inner socket cavity
    brush.wash("#464E58", 220);
    brush.circle(0, 0, rx * 0.35, 0.08);
    brush.noWash();
    // Bright specular glint
    brush.set("rotring", "#FFFFFF", 0.75);
    brush.line(-rx * 0.55, -rx * 0.35, -rx * 0.15, -rx * 0.65);
    pop();
  }

  drawChromeSnap(278, 366, 11, 14, -22); // Center-brow snap
  drawChromeSnap(335, 405, 13, 15, -12); // Left-temple snap
  drawChromeSnap(362, 505, 11, 13, -5);  // Cheek-shield snap

  // 3. Hanging Nylon Chin Strap, Padded Chin Cup, Steel D-Rings & Red Pull-Tab
  // Padded leather/velour chin-strap sleeve emerging from below the jaw
  const sleevePoly = [
    [445, 750], [522, 752], [516, 845], [452, 842]
  ];
  drawPolyWash(sleevePoly, PAL.linerTaupe, 235);
  drawPolyFill(sleevePoly, PAL.linerShadow, 95, 0.06, 0.35);
  drawPath(sleevePoly, "rotring", PAL.ink, 0.6, true, 0.08);

  // Stitching & dome rivet on the leather sleeve
  drawDashedPath([[454, 756], [460, 836]], "rotring", PAL.stitchCoral, 0.38, 6, 4);
  drawDashedPath([[513, 756], [508, 836]], "rotring", PAL.stitchCoral, 0.38, 6, 4);
  drawChromeSnap(485, 782, 9.5, 9.5, 0);

  // Main tubular nylon webbing strap hanging down (y: 842..1020)
  const webbingPoly = [
    [458, 842], [510, 844], [524, 995], [498, 1022], [470, 998]
  ];
  drawPolyWash(webbingPoly, PAL.strapGrey, 240);
  drawPolyFill(webbingPoly, PAL.strapDark, 90, 0.05, 0.35);
  drawPath(webbingPoly, "rotring", PAL.ink, 0.62, true, 0.08);

  // Herringbone nylon weave texture along the strap
  brush.set("2H", PAL.ink, 0.34);
  for (let y = 848; y <= 995; y += 5.5) {
    const t = (y - 842) / 160;
    const xL = lerp(460, 472, t);
    const xR = lerp(508, 522, t);
    const xM = (xL + xR) * 0.5;
    brush.line(xL, y, xM, y - 4);
    brush.line(xM, y - 4, xR, y);
  }

  // Anodized Steel Double D-Rings at y ≈ 905..945
  const dRing1 = [
    [448, 895], [526, 892], [532, 926], [446, 929]
  ];
  const dRing2 = [
    [444, 915], [530, 912], [534, 948], [442, 952]
  ];
  for (const dr of [dRing1, dRing2]) {
    drawPath(dr, "rotring", PAL.ink, 1.35, true, 0.18);
    drawPath(dr, "rotring", "#EBF3FA", 0.65, true, 0.18);
  }

  // Pastel Coral-Red Quick-Release Fabric Pull-Tab attached to the lower D-ring
  const pullTab = [
    [528, 924], [588, 912], [594, 938], [532, 944]
  ];
  drawPolyWash(pullTab, PAL.redLuminous, 230);
  drawPath(pullTab, "rotring", PAL.ink, 0.52, true, 0.05);
  drawText("PULL", 542, 922, 8.5, "rotring", "#FFFDF8", 0.32, 0.25);

  // Crisp final technical contour around the entire outer helmet silhouette
  drawPath(geom.topCrown, "rotring", PAL.ink, 0.72, false, 0.22);
}

