function drawDidacticAnnotations(geom) {
  // Helper to draw a textbook leader line (target dot -> angled leader -> horizontal shelf -> numbered circle)
  function drawCallout(numStr, tx, ty, elbowX, elbowY, cx, cy, tintCol, title, subtitle, alignRight = false) {
    // Small target dot with white halo on the anatomical feature
    brush.noStroke();
    brush.wash(PAL.paper, 240);
    brush.circle(tx, ty, 4.5, 0.05);
    brush.wash(PAL.ink, 240);
    brush.circle(tx, ty, 2.6, 0.05);
    brush.noWash();

    // Crisp technical leader line
    brush.set("rotring", PAL.ink, 0.42);
    brush.line(tx, ty, elbowX, elbowY);
    brush.line(elbowX, elbowY, cx, cy);

    // Double-ring numbered margin circle with pastel layer tint
    const r = 16;
    brush.noStroke();
    brush.wash(PAL.paper, 245);
    brush.circle(cx, cy, r, 0.06);
    brush.noWash();
    brush.fill(tintCol, 130);
    brush.fillBleed(0.05, "in");
    brush.circle(cx, cy, r - 2.5, 0.06);
