    // Stencil numeral inside circle
    drawText(numStr, cx - 4.5, cy - 6.5, 13, "rotring", PAL.ink, 0.48, 0.2);

    // Marginal technical caption next to the circle
    const textX = alignRight ? cx - r - 8 - title.length * 7.5 : cx + r + 10;
    drawText(title, textX, cy - 10, 9.5, "rotring", PAL.ink, 0.35, 0.28);
    drawText(subtitle, textX, cy + 4, 7.8, "rotring", PAL.inkMid, 0.26, 0.24);
  }

  // 8 Numbered Textbook Callouts around the margin
  drawCallout("1", 495, 228, 395, 150, 295, 150, PAL.redPastel, "GELCOAT SHELL", "CANDY-APPLE POLYURETHANE", true);
  drawCallout("2", 278, 366, 210, 315, 115, 315, "#DCE6F0", "VISOR SNAP STUD", "CHROME-PLATED BRASS", false);
  drawCallout("3", 295, 555, 215, 555, 115, 555, PAL.linerTaupe, "ACOUSTIC RECESS", "QUILTED CHEEK PADDING", false);
  drawCallout("4", 396, 712, 265, 745, 115, 745, "#B0B8C0", "BEADED EDGE TRIM", "VULCANIZED EPDM & CHROME", false);
  drawCallout("5", 495, 918, 370, 945, 115, 945, PAL.strapGrey, "RETENTION STRAP", "NYLON WEBBING & D-RINGS", false);
  drawCallout("6", 575, 292, 655, 148, 725, 148, PAL.frpMid, "FRP LAMINATE", "BIAXIAL FIBREGLASS WEAVE", false);
  drawCallout("7", 650, 355, 765, 215, 835, 215, PAL.epsMid, "EPS IMPACT CORE", "EXPANDED POLYSTYRENE BEADS", false);
  drawCallout("8", 612, 515, 755, 775, 835, 775, PAL.linerBlue, "COMFORT LINER", "DIAMOND-STITCHED FOAM PAD", false);

  // Top Textbook Plate Header
  drawText("PLATE XIV  -  PROTECTIVE HEADGEAR ANATOMY", 78, 78, 11.5, "rotring", PAL.ink, 0.42, 0.32);
  drawText("FIG. 4.12 : THREE-STAGE HINGED CUTAWAY DISSECTION", 665, 78, 10, "rotring", PAL.inkMid, 0.34, 0.28);
  brush.set("rotring", PAL.inkLight, 0.35);
  brush.line(78, 98, 1122, 98);

  // Bottom-Left Metric Scale Bar & Orthographic Elevation Key (x: 82..420, y: 1035..1120)
  const sx = 82, sy = 1075, sw = 240;
  brush.set("rotring", PAL.ink, 0.48);
  brush.rect(sx, sy, sw, 10, "corner");
