    const bx = sx + i * (sw / 6);
    if (i % 2 === 0) {
      drawPolyWash([[bx, sy], [bx + sw / 6, sy], [bx + sw / 6, sy + 10], [bx, sy + 10]], PAL.ink, 210);
    }
    brush.set("rotring", PAL.ink, 0.42);
    brush.line(bx, sy - 5, bx, sy + 10);
  }
  brush.line(sx + sw, sy - 5, sx + sw, sy + 10);
  drawText("SCALE 1:2   0      50     100    150 mm", sx, sy - 18, 8.5, "rotring", PAL.ink, 0.32, 0.25);
  drawText("TOTAL COMPOSITE WALL THICKNESS : 43.8 mm", sx, sy + 20, 8.2, "rotring", PAL.inkMid, 0.3, 0.25);

  // Bottom-Right Cross-Sectional Layer Legend Box (x: 645..1122, y: 865..1120)
  const lx = 645, ly = 865, lw = 477, lh = 255;
  drawPolyWash([[lx, ly], [lx + lw, ly], [lx + lw, ly + lh], [lx, ly + lh]], PAL.paperWarm, 95);
  brush.set("rotring", PAL.ink, 0.52);
  brush.rect(lx, ly, lw, lh, "corner");
  brush.set("rotring", PAL.inkLight, 0.28);
  brush.rect(lx + 5, ly + 5, lw - 10, lh - 10, "corner");

  drawText("STRATIGRAPHIC LAYER SCHEDULE (LIFT-FLAP KEY)", lx + 18, ly + 18, 9.5, "rotring", PAL.ink, 0.38, 0.28);
  brush.set("rotring", PAL.inkLight, 0.32);
  brush.line(lx + 18, ly + 35, lx + lw - 18, ly + 35);

  const layers = [
    { code: "I", col: PAL.redLuminous, name: "EXTERIOR GELCOAT", spec: "0.6 mm GLOSS POLYURETHANE LACQUER" },
    { code: "II", col: PAL.frpMid, name: "STRUCTURAL SHELL", spec: "3.2 mm WOVEN FIBREGLASS ROVING (FRP)" },
    { code: "III", col: PAL.epsMid, name: "IMPACT ABSORBER", spec: "28.0 mm HIGH-DENSITY EPS BEAD FOAM" },
    { code: "IV", col: PAL.linerBlue, name: "CRANIAL COMFORT", spec: "12.0 mm QUILTED OPEN-CELL URETHANE" }
  ];

  for (let i = 0; i < layers.length; i++) {
    const item = layers[i];
    const iy = ly + 48 + i * 48;
    const swPoly = [[lx + 20, iy], [lx + 72, iy], [lx + 72, iy + 32], [lx + 20, iy + 32]];
    drawPolyFill(swPoly, item.col, 165, 0.04, 0.35);
    brush.set("rotring", PAL.ink, 0.45);
    brush.rect(lx + 20, iy, 52, 32, "corner");

    // Micro-texture inside legend swatch
    if (i === 0) {
      brush.set("rotring", "#FFFFFF", 0.65);
      brush.line(lx + 26, iy + 8, lx + 64, iy + 8);
    } else if (i === 1) {
      brush.set("2H", PAL.frpDark, 0.32);
      for (let gx = lx + 26; gx <= lx + 66; gx += 8) brush.line(gx, iy + 3, gx, iy + 29);
      for (let gy = iy + 6; gy <= iy + 28; gy += 8) brush.line(lx + 23, gy, lx + 69, gy);
    } else if (i === 2) {
      brush.set("2H", PAL.epsDark, 0.32);
      for (let gx = lx + 28; gx <= lx + 64; gx += 11) {
        for (let gy = iy + 9; gy <= iy + 25; gy += 11) {
          brush.circle(gx, gy, 4.5, 0.15);
        }
      }
    } else if (i === 3) {
      brush.set("rotring", PAL.stitchCoral, 0.35);
      brush.line(lx + 22, iy + 28, lx + 46, iy + 4);
      brush.line(lx + 46, iy + 4, lx + 70, iy + 28);
    }

    drawText(item.code + " : " + item.name, lx + 86, iy + 4, 9, "rotring", PAL.ink, 0.35, 0.26);
    drawText(item.spec, lx + 86, iy + 19, 7.6, "rotring", PAL.inkMid, 0.26, 0.24);
  }
}

// Hyperreal Cockerel in a Glaring Kabuki Mie Pose
// Rendered with p5.js v2 + p5.brush in WEBGL

function safeLine(x1, y1, x2, y2) {
  if (dist(x1, y1, x2, y2) > 0.6) {
    brush.line(x1, y1, x2, y2);
  }
}

function safeSpline(pts, curv = 0.5) {
  if (!pts || pts.length < 3) return;
  let clean = [pts[0]];
  for (let i = 1; i < pts.length; i++) {
    let prev = clean[clean.length - 1];
    if (dist(prev[0], prev[1], pts[i][0], pts[i][1]) > 1.0) {
      clean.push(pts[i]);
    }
  }
  if (clean.length >= 3) {
    brush.spline(clean, curv);
  } else if (clean.length === 2) {
    safeLine(clean[0][0], clean[0][1], clean[1][0], clean[1][1]);
  }
}

function evalQuad(p0, p1, p2, t) {
  let u = 1 - t;
  return [
    u * u * p0[0] + 2 * u * t * p1[0] + t * t * p2[0],
    u * u * p0[1] + 2 * u * t * p1[1] + t * t * p2[1]
  ];
}

function evalCubic(p0, p1, p2, p3, t) {
  let u = 1 - t;
  return [
    u * u * u * p0[0] + 3 * u * u * t * p1[0] + 3 * u * t * t * p2[0] + t * t * t * p3[0],
    u * u * u * p0[1] + 3 * u * u * t * p1[1] + 3 * u * t * t * p2[1] + t * t * t * p3[1]
  ];
}

function cubicTangent(p0, p1, p2, p3, t) {
  let u = 1 - t;
  let dx = 3 * u * u * (p1[0] - p0[0]) + 6 * u * t * (p2[0] - p1[0]) + 3 * t * t * (p3[0] - p2[0]);
  let dy = 3 * u * u * (p1[1] - p0[1]) + 6 * u * t * (p2[1] - p1[1]) + 3 * t * t * (p3[1] - p2[1]);
  let len = Math.hypot(dx, dy) || 1;
  return [dx / len, dy / len];
}

const FLOOR_Y = 780;
const VP_X = 555;
const VP_Y = 360;

// Kabuki Hikimaku Curtain Bands (Black, Persimmon, Dark Green in muted earth tones)
const CURTAIN_BANDS = [
  { x1: 0,    x2: 112,  type: "black",     base: "#171514", mid: "#211e1b", light: "#2e2822", dark: "#0e0c0b" },
  { x1: 112,  x2: 242,  type: "green",     base: "#1e3528", mid: "#284534", light: "#385c45", dark: "#13231a" },
  { x1: 242,  x2: 368,  type: "black",     base: "#171514", mid: "#211e1b", light: "#2e2822", dark: "#0e0c0b" },
  { x1: 368,  x2: 512,  type: "persimmon", base: "#b04724", mid: "#c4562e", light: "#d96c3f", dark: "#853116" },
  { x1: 512,  x2: 638,  type: "black",     base: "#171514", mid: "#211e1b", light: "#302923", dark: "#0e0c0b" },
  { x1: 638,  x2: 782,  type: "green",     base: "#1e3528", mid: "#294635", light: "#3a5e47", dark: "#13231a" },
  { x1: 782,  x2: 908,  type: "black",     base: "#171514", mid: "#211e1b", light: "#2c2620", dark: "#0e0c0b" },
  { x1: 908,  x2: 1054, type: "persimmon", base: "#b04724", mid: "#c4562e", light: "#d6683b", dark: "#853116" },
  { x1: 1054, x2: 1200, type: "black",     base: "#171514", mid: "#201d1a", light: "#29241e", dark: "#0e0c0b" }
];

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(8472);
  noiseSeed(8472);
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#1a1612");

  // 1. Flat, hard-edged marker stage curtain (Hikimaku) flattened by frontal footlight
  drawHikimakuCurtain();

  // 2. Polished Hinoki cypress floorboards with converging plank seams, grain & reflections
  drawCypressFloorboards();

  // 3. Cast shadows of the crowing cockerel on the stage floor
  drawStageShadows();

  // 4. Cockerel Tail: Rectrices, fluffy coverts, and hyperreal iridescent sickle plumes
  drawCockerelTail();

  // 5. Cockerel Body: Puffed breast, thighs, saddle feathers, and tensed wing
  drawCockerelBodyAndWing();

  // 6. Scaly Yellow Legs, Cockspurs, and gripping Talons on the polished cypress floor
  drawScalyYellowLegs();

  // 7. Flaring Iridescent Neck Hackles
  drawNeckHackles();

  // 8. Head, Open Screaming Beak, Kumadori Scarlet Comb & Wattles, and Fierce Eye with White-Pen Highlight
  drawHeadKumadoriAndEye();

  // 9. Raking Frontal Footlight Rim Highlights & Theatrical Stage Atmosphere
  drawFootlightHighlights();

  noLoop();
}

// ============================================================================
// 1. HIKIMAKU STAGE CURTAIN (FLAT, HARD-EDGED MARKER FIELDS)
// ============================================================================
function drawHikimakuCurtain() {
  brush.noField();
  brush.noFill();

  // Base solid washes per band for crisp, hard-edged graphic flatness
  for (let b of CURTAIN_BANDS) {
    brush.noStroke();
    brush.wash(b.base, 255);
    brush.rect(b.x1, 0, b.x2 - b.x1, FLOOR_Y, "corner");
    brush.noWash();
  }

  // Dense vertical marker passes inside each clipped band
  for (let b of CURTAIN_BANDS) {
    brush.clip([b.x1, 0, b.x2, FLOOR_Y]);

    // Primary flat marker layer
    brush.set("marker", b.base, 2.8);
    for (let x = b.x1 + 4; x < b.x2; x += 12) {
      safeLine(x, -10, x + random(-1.5, 1.5), FLOOR_Y + 10);
    }

    // Mid-tone marker layer (strong frontal footlight flattening lower 65% of curtain)
    brush.set("marker", b.mid, 2.4);
    for (let x = b.x1 + 6; x < b.x2; x += 14) {
      let distFromCenter = abs(x - 610);
      let topReach = map(distFromCenter, 0, 620, 180, 460) + random(-25, 25);
      safeLine(x, topReach, x, FLOOR_Y + 8);
    }

    // Brighter frontal footlight wash on lower central curtain
    brush.set("marker", b.light, 2.0);
    for (let x = b.x1 + 8; x < b.x2; x += 16) {
      let distFromCenter = abs(x - 610);
      if (distFromCenter < 480) {
        let topReach = map(distFromCenter, 0, 480, 410, 740) + random(-20, 20);
        if (topReach < FLOOR_Y - 15) {
          safeLine(x, topReach, x, FLOOR_Y + 5);
        }
      }
    }

    // Upper theatre shadow & subtle flat marker pleat columns near top header
    brush.set("marker", b.dark, 2.2);
    for (let x = b.x1 + 5; x < b.x2; x += 18) {
      let len = random(90, 220) + map(abs(x - 600), 0, 600, 0, 140);
      safeLine(x, -10, x, len);
    }
    // Two crisp vertical fold shadow strips per band (still flat marker style)
    let foldX1 = lerp(b.x1, b.x2, 0.28);
    let foldX2 = lerp(b.x1, b.x2, 0.76);
    brush.set("marker", b.dark, 1.5);
    safeLine(foldX1, 0, foldX1, FLOOR_Y);
    safeLine(foldX2, 0, foldX2, FLOOR_Y * 0.65);

    // Subtle crisp textile warp lines with rotring to enhance hyperreal scale against marker
    brush.set("2H", b.dark, 0.25);
    for (let x = b.x1 + 3; x < b.x2; x += 9) {
      safeLine(x, 0, x, FLOOR_Y);
    }

    brush.noClip();
  }

  // Razor-sharp hard-edged seams between the marker bands
  for (let i = 1; i < CURTAIN_BANDS.length; i++) {
    let sx = CURTAIN_BANDS[i].x1;
    brush.set("rotring", "#0d0b0a", 0.55);
    safeLine(sx, 0, sx, FLOOR_Y);
  }

  // Subtle flat silhouette shadow of the cockerel projected high and wide on the lower curtain
  brush.clip([0, 480, 1200, FLOOR_Y]);
  brush.set("marker", "#0f0d0b", 2.2);
  for (let x = 220; x <= 790; x += 14) {
    let topY = 780;
    if (x < 480) {
      topY = map(x, 220, 480, 720, 585) + sin(x * 2) * 12;
    } else if (x < 680) {
      topY = map(x, 480, 680, 585, 550);
    } else {
      topY = map(x, 680, 790, 550, 750);
    }
    safeLine(x, topY, x, FLOOR_Y);
  }
  brush.noClip();
}

// ============================================================================
// 2. POLISHED HINOKI CYPRESS FLOORBOARDS (CONVERGING PLANK SEAMS)
// ============================================================================
function drawCypressFloorboards() {
  brush.clip([0, FLOOR_Y, 1200, 1200]);

  // Base warm cypress wood under-wash
  brush.noStroke();
  brush.wash("#8f673f", 255);
  brush.rect(0, FLOOR_Y, 1200, 1200 - FLOOR_Y, "corner");
  brush.noWash();

  // Define converging plank rays originating at (VP_X, VP_Y)
  // Compute x intersections at y = FLOOR_Y and y = 1200
  let bottomXs = [-520, -290, -80, 110, 285, 445, 595, 745, 905, 1080, 1275, 1490, 1740];
  let planks = [];
  for (let i = 0; i < bottomXs.length - 1; i++) {
    let bx1 = bottomXs[i];
    let bx2 = bottomXs[i + 1];
    let tTop = (FLOOR_Y - VP_Y) / (1200 - VP_Y);
    let tx1 = VP_X + (bx1 - VP_X) * tTop;
    let tx2 = VP_X + (bx2 - VP_X) * tTop;
    planks.push({ tx1, tx2, bx1, bx2, idx: i });
  }

  // Plank-by-plank tonal variation + marker base pass
  let plankTones = [
    "#734f2d", "#875f38", "#9c7044", "#b08252", "#c49662",
    "#d1a470", "#d9ad79", "#c99b67", "#b58654", "#9e7143",
    "#865d35", "#704c2a"
  ];

  for (let p of planks) {
    let col = plankTones[p.idx % plankTones.length];
    brush.set("marker", col, 2.5);
    for (let s = 0.04; s <= 0.96; s += 0.07) {
      let xTop = lerp(p.tx1, p.tx2, s);
      let xBot = lerp(p.bx1, p.bx2, s);
      safeLine(xTop, FLOOR_Y, xBot, 1200);
    }
  }

  // Polished floor vertical reflections of the curtain stripes (subtle marker glazes)
  for (let b of CURTAIN_BANDS) {
    let reflCol = b.type === "persimmon" ? "#9e4d2a" : (b.type === "green" ? "#3c523b" : "#30261d");
    brush.set("marker", reflCol, 1.8);
    for (let x = b.x1 + 8; x < b.x2; x += 22) {
      let reachY = FLOOR_Y + random(95, 210);
      safeLine(x, FLOOR_Y, x + (x - VP_X) * 0.08, reachY);
    }
  }

  // Polished floor reflection of the cockerel's golden/scarlet body and yellow legs
  brush.set("marker", "#b87c32", 1.8);
  for (let x = 480; x <= 770; x += 14) {
    safeLine(x, FLOOR_Y + 80, x + random(-6, 6), min(1190, FLOOR_Y + random(240, 390)));
  }
  brush.set("cpencil", "#d99b38", 1.1);
  for (let x = 510; x <= 790; x += 9) {
    safeLine(x, 890, x, random(1040, 1185));
  }

  // Frontal footlight luminous pool on the polished cypress boards
  let footlightRings = [
    { rx: 520, ry: 210, col: "#b88954", step: 14 },
    { rx: 390, ry: 165, col: "#cfa26b", step: 12 },
    { rx: 270, ry: 120, col: "#e0b882", step: 10 },
    { rx: 165, ry: 75,  col: "#edd0a1", step: 9 }
  ];
  for (let ring of footlightRings) {
    brush.set("cpencil", ring.col, 1.3);
    for (let dy = -ring.ry; dy <= ring.ry; dy += ring.step) {
      let py = 985 + dy;
      if (py > FLOOR_Y + 4 && py < 1198) {
        let halfW = ring.rx * sqrt(max(0, 1 - (dy * dy) / (ring.ry * ring.ry)));
        safeLine(635 - halfW, py, 635 + halfW, py);
      }
    }
  }

  // Hyperreal Hinoki wood grain: cathedral arches & longitudinal fibers per plank
  for (let p of planks) {
    let knotT = random(0.28, 0.78); // Position of cathedral heartwood along plank
    let knotS = random(0.35, 0.65);
    let grainDark = p.idx % 2 === 0 ? "#593a1e" : "#664324";
    let grainMid  = p.idx % 2 === 0 ? "#7d5530" : "#8a6038";
    let grainLite = "#ebc999";

    // Longitudinal grain fibers following perspective
    for (let g = 0; g < 26; g++) {
      let sBase = map(g, 0, 25, 0.05, 0.95);
      let pts = [];
      let steps = 14;
      for (let k = 0; k <= steps; k++) {
        let u = k / steps;
        let y = lerp(FLOOR_Y, 1200, u);
        let leftX = lerp(p.tx1, p.bx1, u);
        let rightX = lerp(p.tx2, p.bx2, u);

        // Cathedral arch deflection around knotT
        let distU = u - knotT;
        let arch = exp(-distU * distU * 18) * (sBase - knotS) * 0.42;
        let waviness = (noise(p.idx * 10 + g * 0.3, u * 4) - 0.5) * 0.06;
        let s = constrain(sBase + arch + waviness, 0.02, 0.98);
        let x = lerp(leftX, rightX, s);
        pts.push([x, y]);
      }

      if (g % 3 === 0) {
        brush.set("2H", grainDark, 0.45);
      } else if (g % 3 === 1) {
        brush.set("cpencil", grainMid, 0.55);
      } else {
        brush.set("2H", grainLite, 0.35);
      }
      safeSpline(pts, 0.4);
    }

    // Inner nested cathedral loops on central planks
    if (p.idx >= 2 && p.idx <= 9) {
      brush.set("2H", grainDark, 0.42);
      for (let loop = 1; loop <= 5; loop++) {
        let loopPts = [];
        let spanU = loop * 0.065;
        let spanS = loop * 0.065;
        for (let a = -90; a <= 90; a += 30) {
          let u = constrain(knotT + sin(a) * spanU, 0.02, 0.98);
          let s = constrain(knotS + cos(a) * spanS * (loop % 2 === 0 ? 1 : -1), 0.06, 0.94);
          let y = lerp(FLOOR_Y, 1200, u);
          let lx = lerp(p.tx1, p.bx1, u);
          let rx = lerp(p.tx2, p.bx2, u);
          loopPts.push([lerp(lx, rx, s), y]);
        }
        safeSpline(loopPts, 0.5);
      }
    }
  }

  // Horizontal polished wax sheen streaks across the boards (raking footlight reflection)
  brush.set("2H", "#f7e4c3", 0.4);
  for (let i = 0; i < 65; i++) {
    let y = random(FLOOR_Y + 12, 1190);
    let cx = random(220, 1020);
    let halfLen = map(abs(cx - 630), 0, 550, 95, 25) * random(0.6, 1.3);
    safeLine(cx - halfLen, y, cx + halfLen, y);
  }

  // Converging Plank Seams + Bevel Highlights
  for (let i = 0; i < planks.length; i++) {
    let p = planks[i];
    // Dark recessed plank seam
    brush.set("rotring", "#1f1208", 0.85);
    safeLine(p.tx1, FLOOR_Y, p.bx1, 1200);
    brush.set("2B", "#3b2310", 0.65);
    safeLine(p.tx1 + 1.2, FLOOR_Y, p.bx1 + 1.8, 1200);

    // Bright specular bevel edge catching the frontal footlight
    brush.set("rotring", "#f2d8b1", 0.45);
    safeLine(p.tx1 + 2.5, FLOOR_Y, p.bx1 + 3.5, 1200);

    // Occasional horizontal plank butt-joint across individual boards
    if (i % 2 === 1 && i >= 2 && i <= 9) {
      let uJoint = (i * 0.23) % 0.65 + 0.18;
      let jy = lerp(FLOOR_Y, 1200, uJoint);
      let jx1 = lerp(p.tx1, p.bx1, uJoint);
      let jx2 = lerp(p.tx2, p.bx2, uJoint);
      brush.set("rotring", "#241509", 0.75);
      safeLine(jx1, jy, jx2, jy);
      brush.set("rotring", "#f5dec0", 0.45);
      safeLine(jx1, jy + 2, jx2, jy + 2);
    }
  }

  // Back stage shadow where curtain meets polished cypress floor
  brush.set("charcoal", "#170f08", 1.2);
  safeLine(0, FLOOR_Y + 1, 1200, FLOOR_Y + 1);
  brush.set("rotring", "#0d0804", 0.9);
  safeLine(0, FLOOR_Y, 1200, FLOOR_Y);

  brush.noClip();
}

// ============================================================================
// 3. STAGE CAST SHADOWS FROM FRONTAL FOOTLIGHT
// ============================================================================
function drawStageShadows() {
  // Footlight is low & frontal at roughly (640, 1220), so shadows angle backward toward y = FLOOR_Y
  // Right leg (viewer's left, foot at ~535, 885) cast shadow
  brush.set("charcoal", "#24160b", 0.95);
  for (let s = 0; s <= 1; s += 0.06) {
    let sx1 = lerp(485, 595, s);
    let sy1 = lerp(885, 918, s);
    let sx2 = lerp(430, 545, s);
    let sy2 = FLOOR_Y + 4;
    safeLine(sx1, sy1, sx2, sy2);
  }

  // Left leg (viewer's right, foot at ~720, 920) cast shadow
  for (let s = 0; s <= 1; s += 0.05) {
    let sx1 = lerp(665, 805, s);
    let sy1 = lerp(920, 958, s);
    let sx2 = lerp(635, 760, s);
    let sy2 = FLOOR_Y + 4;
    safeLine(sx1, sy1, sx2, sy2);
  }

  // Deep contact shadow directly beneath both feet and talons
  let contactZones = [
    // Viewer's left foot toes
    [535, 885, 610, 902], [535, 885, 586, 925], [530, 885, 495, 923], [526, 878, 476, 890],
    // Viewer's right foot toes
    [718, 918, 808, 963], [724, 916, 814, 933], [710, 918, 690, 982], [705, 910, 652, 927]
  ];
  brush.set("2B", "#140b05", 1.3);
  for (let cz of contactZones) {
    safeLine(cz[0], cz[1] + 3, cz[2], cz[3] + 3);
    safeLine(cz[0], cz[1] + 5, cz[2], cz[3] + 5);
  }
}

// ============================================================================
// 4. HYPERREAL IRIDESCENT TAIL FEATHERS (RECTRICES, COVERTS & SICKLES)
// ============================================================================
function drawCockerelTail() {
  // A. Stiff dark main tail blades (Rectrices) forming the structural fan underneath
  let rectrices = [
    { p0: [480, 520], p1: [370, 390], p2: [230, 310], w: 22 },
    { p0: [475, 530], p1: [350, 420], p2: [205, 355], w: 24 },
    { p0: [470, 540], p1: [335, 455], p2: [190, 405], w: 24 },
    { p0: [468, 552], p1: [325, 490], p2: [185, 460], w: 22 },
    { p0: [465, 565], p1: [325, 525], p2: [195, 515], w: 20 },
    { p0: [465, 578], p1: [335, 560], p2: [220, 568], w: 18 }
  ];

  for (let r of rectrices) {
    let steps = 55;
    for (let i = 0; i <= steps; i++) {
      let t = i / steps;
      let pt = evalQuad(r.p0, r.p1, r.p2, t);
      let nextPt = evalQuad(r.p0, r.p1, r.p2, min(1, t + 0.02));
      let ang = atan2(nextPt[1] - pt[1], nextPt[0] - pt[0]);
      let vaneW = r.w * sin(t * 165 + 15);

      // Upper vane (dark sumi-brown/black)
      brush.set("2H", "#141110", 0.55);
      let ux = pt[0] + cos(ang + 135) * vaneW;
      let uy = pt[1] + sin(ang + 135) * vaneW;
      safeLine(pt[0], pt[1], ux, uy);

      // Lower vane (catching subtle bronze/green footlight)
      let lCol = t > 0.35 && i % 3 === 0 ? "#243b2f" : "#1c1714";
      brush.set("2H", lCol, 0.55);
      let lx = pt[0] + cos(ang - 135) * (vaneW * 0.9);
      let ly = pt[1] + sin(ang - 135) * (vaneW * 0.9);
      safeLine(pt[0], pt[1], lx, ly);
    }
    // Stiff central shaft (rachis)
    brush.set("rotring", "#2b221b", 0.5);
    safeSpline([r.p0, r.p1, r.p2], 0.5);
  }

  // B. Fluffy smoky-umber downy tail coverts at the base of the tail
  for (let i = 0; i < 95; i++) {
    let bx = random(420, 515);
    let by = random(525, 645);
    let len = random(28, 62);
    let ang = random(155, 225);
    let ex = bx + cos(ang) * len;
    let ey = by + sin(ang) * len;
    let col = by > 600 ? "#4a382b" : (i % 3 === 0 ? "#2e241d" : "#1c1714");
    brush.set("cpencil", col, 0.65);
    safeSpline([[bx, by], [(bx + ex) / 2, (by + ey) / 2 + random(4, 12)], [ex, ey]], 0.5);
  }

  // C. Sweeping Greater and Lesser Sickle Feathers (Iridescent Black, Emerald, Teal, Bronze)
  let sickles = [
    // Towering top arch sickles
    { p0: [485, 488], p1: [445, 210], p2: [285, 130], p3: [155, 315], w: 28, hue: "emerald" },
    { p0: [480, 495], p1: [420, 195], p2: [240, 145], p3: [115, 375], w: 32, hue: "teal" },
    { p0: [478, 502], p1: [400, 225], p2: [210, 185], p3: [105, 445], w: 30, hue: "emerald" },
    { p0: [475, 508], p1: [385, 255], p2: [195, 240], p3: [112, 515], w: 28, hue: "bronze" },
    { p0: [472, 515], p1: [375, 290], p2: [195, 300], p3: [128, 580], w: 28, hue: "teal" },
    { p0: [470, 522], p1: [365, 325], p2: [205, 355], p3: [155, 635], w: 26, hue: "emerald" },
    { p0: [468, 530], p1: [365, 360], p2: [225, 410], p3: [190, 678], w: 25, hue: "bronze" },
    // Inner & lesser cascading sickles
    { p0: [495, 482], p1: [470, 265], p2: [345, 175], p3: [235, 320], w: 24, hue: "teal" },
    { p0: [492, 490], p1: [450, 295], p2: [320, 235], p3: [215, 405], w: 25, hue: "emerald" },
    { p0: [488, 500], p1: [430, 330], p2: [305, 305], p3: [225, 485], w: 24, hue: "bronze" },
    { p0: [485, 512], p1: [415, 375], p2: [305, 375], p3: [245, 560], w: 23, hue: "emerald" },
    { p0: [482, 525], p1: [405, 415], p2: [315, 440], p3: [275, 625], w: 22, hue: "teal" },
    { p0: [480, 538], p1: [405, 455], p2: [335, 500], p3: [315, 672], w: 20, hue: "bronze" },
    { p0: [485, 548], p1: [420, 490], p2: [368, 545], p3: [358, 695], w: 18, hue: "emerald" }
  ];

  for (let s of sickles) {
    drawIridescentSickle(s);
  }
}

function drawIridescentSickle(s) {
  let steps = 82;
  let spinePts = [];

  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    // Slight biological splits in the feather vane
    if (abs(t - 0.42) < 0.015 || abs(t - 0.74) < 0.012) continue;

    let pt = evalCubic(s.p0, s.p1, s.p2, s.p3, t);
    if (i % 4 === 0 || i === steps) spinePts.push(pt);

    let tan = cubicTangent(s.p0, s.p1, s.p2, s.p3, t);
    let ang = atan2(tan[1], tan[0]);

    // Taper profile of sickle feather
    let env = sin(pow(t, 0.75) * 180);
    let w = s.w * env;

    // Determine iridescence based on angle of feather relative to frontal footlight
    let iridZone = t > 0.18 && t < 0.86;
    let upperCol = "#11100f";
    let lowerCol = "#141210";

    if (iridZone) {
      let shimmer = sin(t * 540 + s.p3[0]);
      if (s.hue === "emerald") {
        upperCol = shimmer > 0.1 ? "#1b4d38" : "#12291f";
        lowerCol = shimmer > -0.2 ? "#2c7554" : "#193d2d";
      } else if (s.hue === "teal") {
        upperCol = shimmer > 0.1 ? "#19484f" : "#112629";
        lowerCol = shimmer > -0.2 ? "#286e75" : "#183b40";
      } else {
        upperCol = shimmer > 0.1 ? "#4a3219" : "#1f160e";
        lowerCol = shimmer > -0.2 ? "#8c5b26" : "#3d2914";
      }
    }

    // Draw upper barb
    let uAng = ang + 142;
    let ux = pt[0] + cos(uAng) * w * 0.95;
    let uy = pt[1] + sin(uAng) * w * 0.95;
    brush.set("2H", upperCol, 0.48);
    safeLine(pt[0], pt[1], ux, uy);

    // Draw lower barb (facing frontal footlight -> stronger iridescence)
    let lAng = ang - 138;
    let lx = pt[0] + cos(lAng) * w * 1.08;
    let ly = pt[1] + sin(lAng) * w * 1.08;
    brush.set("2H", lowerCol, 0.52);
    safeLine(pt[0], pt[1], lx, ly);

    // Specular footlight glint along the outer half of the lower barbs
    if (iridZone && i % 3 === 0) {
      let glintCol = s.hue === "bronze" ? "#deb068" : (s.hue === "teal" ? "#7fc4c2" : "#82cca4");
      brush.set("rotring", glintCol, 0.28);
      let gx1 = lerp(pt[0], lx, 0.52);
      let gy1 = lerp(pt[1], ly, 0.52);
      safeLine(gx1, gy1, lx, ly);
    }
  }

  // Dark glossy central rachis shaft with subtle highlight
  brush.set("rotring", "#0c0b0a", 0.55);
  safeSpline(spinePts, 0.5);
  brush.set("rotring", "#456355", 0.25);
  safeSpline(spinePts.slice(2, -2), 0.5);
}

// ============================================================================
// 5. COCKEREL BODY, BREAST, THIGHS, SADDLE HACKLES & TENSED WING
// ============================================================================
function drawCockerelBodyAndWing() {
  // A. Solid dark core underbody wash so no background bleeds through
  brush.noStroke();
  brush.wash("#14100d", 255);
  brush.beginShape(0.3);
  brush.vertex(520, 420);
  brush.vertex(685, 445);
  brush.vertex(748, 560);
  brush.vertex(715, 675);
  brush.vertex(695, 760);
  brush.vertex(645, 750);
  brush.vertex(635, 685);
  brush.vertex(595, 685);
  brush.vertex(565, 742);
  brush.vertex(535, 735);
  brush.vertex(535, 650);
  brush.vertex(470, 580);
  brush.endShape(true);
  brush.noWash();

  // B. Feathered Drumsticks (Tibiotarsus Thighs)
  // Right thigh (viewer's left: braced back)
  drawFeatheredThigh(565, 635, 555, 748, 34, 18, false);
  // Left thigh (viewer's right: planted forward, catching strong frontal footlight)
  drawFeatheredThigh(675, 635, 695, 766, 40, 21, true);

  // C. Puffed Breast & Underbody Contour Feathers (Raked from below by footlight)
  // Drawn from bottom (abdomen) upward to upper chest so overlapping rows shingle naturally
  for (let row = 0; row < 15; row++) {
    let tRow = row / 14; // 0 = bottom abdomen (685), 1 = upper chest (465)
    let yCenter = lerp(680, 468, tRow);
    let xLeft = lerp(555, 625, sin(tRow * 120));
    let xRight = lerp(695, 748, sin(tRow * 145 + 15));

    let numFeathers = floor(map(xRight - xLeft, 80, 185, 7, 14));
    for (let j = 0; j < numFeathers; j++) {
      let s = (j + (row % 2) * 0.45) / numFeathers;
      if (s > 1) continue;
      let fx = lerp(xLeft, xRight, s);
      let fy = yCenter + sin(s * 180) * 12 + random(-3, 3);
      let fw = random(16, 23);
      let fh = random(20, 28);

      // Dark velvety sumi-black & beetle-green feather core
      brush.set("cpencil", "#141110", 0.85);
      for (let a = -70; a <= 70; a += 20) {
        let ang = 85 + a * 0.45;
        safeLine(fx, fy - fh * 0.4, fx + cos(ang) * fw, fy + sin(ang) * fh * 0.65);
      }

      // Iridescent green/bronze mid-vane
      let midCol = s > 0.45 ? "#4a2e18" : "#1a3328";
      brush.set("2H", midCol, 0.55);
      for (let a = -55; a <= 55; a += 22) {
        let ang = 85 + a * 0.45;
        safeLine(fx + cos(ang) * fw * 0.4, fy, fx + cos(ang) * fw * 0.95, fy + sin(ang) * fh * 0.62);
      }

      // Strong frontal footlight raking across the lower curved edge of each breast feather!
      if (s > 0.25) {
        let rimCol = s > 0.68 ? "#e8b968" : "#b87430";
        brush.set("rotring", rimCol, 0.42);
        let pL = [fx - fw * 0.55, fy + fh * 0.35];
        let pM = [fx + 2, fy + fh * 0.65];
        let pR = [fx + fw * 0.65, fy + fh * 0.28];
        safeSpline([pL, pM, pR], 0.5);
      }
    }
  }

  // D. Weeping Saddle Hackles cascading over the lower back and tail base
  for (let i = 0; i < 115; i++) {
    let t = i / 114;
    let sx = lerp(555, 445, pow(t, 0.85)) + random(-10, 10);
    let sy = lerp(455, 515, t) + random(-8, 8);
    let len = random(75, 145) * (0.7 + 0.5 * sin(t * 180));
    let dropAng = lerp(128, 162, t) + random(-8, 8);

    let p0 = [sx, sy];
    let p1 = [sx + cos(dropAng - 14) * len * 0.5, sy + sin(dropAng - 14) * len * 0.5];
    let p2 = [sx + cos(dropAng + 8) * len, sy + sin(dropAng + 8) * len];

    // Rich burnt copper, persimmon-ochre, and pale footlight gold
    let col = i % 4 === 0 ? "#8c3316" : (i % 4 === 1 ? "#c45b22" : (i % 4 === 2 ? "#de8d31" : "#f2c66d"));
    let w = i % 4 === 3 ? 0.38 : 0.62;
    brush.set(i % 4 === 3 ? "rotring" : "cpencil", col, w);
    safeSpline([p0, p1, p2], 0.5);
  }

  // E. Tensed Muscular Wing (Primaries, Secondaries, Speculum Coverts, Wing Bow)
  drawTensedWing();
}

function drawFeatheredThigh(xTop, yTop, xHock, yHock, wTop, wBot, isFront) {
  let rows = 14;
  for (let r = rows; r >= 0; r--) {
    let t = r / rows;
    let cx = lerp(xTop, xHock, t);
    let cy = lerp(yTop, yHock, t);
    let hw = lerp(wTop, wBot, t);

    for (let s = -1; s <= 1; s += 0.25) {
      let fx = cx + s * hw;
      let fy = cy + (1 - s * s) * 8;
      let col = "#1a1410";
      if (isFront && s > 0.15) {
        col = s > 0.55 ? "#d99b4e" : "#784820";
      } else if (!isFront && s > 0.35) {
        col = "#69411f";
      }
      brush.set("cpencil", col, 0.65);
      safeLine(fx, fy - 12, fx + s * 4, fy + 10);
    }
  }
}

function drawTensedWing() {
  // 1. Stiff Flight Feathers (Primaries & Secondaries) angling down toward hip/thigh
  let numPrimaries = 11;
  for (let i = 0; i < numPrimaries; i++) {
    let t = i / (numPrimaries - 1);
    let p0 = [lerp(565, 648, t), lerp(555, 545, t)];
    let p1 = [lerp(538, 615, t), lerp(618, 608, t)];
    let p2 = [lerp(515, 588, t), lerp(682, 658, t)];

    // Inner dark charcoal vane
    brush.set("cpencil", "#1f1814", 0.85);
    safeSpline([[p0[0] - 5, p0[1]], [p1[0] - 5, p1[1]], [p2[0] - 3, p2[1]]], 0.4);

    // Outer cinnamon-bay / raw sienna vane catching frontal footlight
    let bayCol = i % 2 === 0 ? "#b86b2b" : "#d48942";
    brush.set("cpencil", bayCol, 0.8);
    safeSpline([[p0[0] + 3, p0[1]], [p1[0] + 3, p1[1]], [p2[0] + 2, p2[1]]], 0.4);

    // Bright raking footlight edge & crisp quill shaft
    brush.set("rotring", "#f2cb85", 0.38);
    safeSpline([p0, p1, p2], 0.4);
  }

  // 2. Greater Secondary Coverts (Iridescent Metallic Blue-Green Speculum Bar)
  let specRows = 2;
  for (let r = specRows - 1; r >= 0; r--) {
    let count = 10;
    for (let i = 0; i < count; i++) {
      let s = i / (count - 1);
      let fx = lerp(558, 668, s) + r * 6;
      let fy = lerp(532, 542, s) + r * 24 - sin(s * 180) * 10;

      // Dark base
      brush.set("cpencil", "#111f1b", 0.85);
      for (let a = -35; a <= 35; a += 14) {
        safeLine(fx, fy - 12, fx + sin(a) * 14, fy + cos(a) * 18);
      }
      // Metallic teal-emerald sheen
      brush.set("2H", "#266657", 0.6);
      for (let a = -28; a <= 28; a += 14) {
        safeLine(fx + sin(a) * 5, fy, fx + sin(a) * 13, fy + cos(a) * 17);
      }
      // Specular mint-gold rim
      brush.set("rotring", "#8fd1b8", 0.35);
      safeSpline([[fx - 9, fy + 13], [fx, fy + 18], [fx + 9, fy + 13]], 0.5);
    }
  }

  // 3. Wing Bow / Shoulder (Lesser & Median Coverts in deep glossy claret, mahogany & copper)
  for (let r = 4; r >= 0; r--) {
    let tR = r / 4;
    let count = floor(lerp(6, 11, tR));
    for (let i = 0; i < count; i++) {
      let s = i / max(1, count - 1);
      let fx = lerp(562, 672, s);
      let fy = lerp(462, 518, tR) + sin(s * 180) * 8;

      let bowCol = (r + i) % 3 === 0 ? "#6e1f14" : ((r + i) % 3 === 1 ? "#99321b" : "#ba4922");
      brush.set("cpencil", bowCol, 0.78);
      for (let a = -36; a <= 36; a += 18) {
        safeLine(fx, fy - 10, fx + sin(a) * 13, fy + cos(a) * 15);
      }
      // Footlight copper highlight on lower edge of covert
      brush.set("rotring", "#eb9846", 0.35);
      safeSpline([[fx - 8, fy + 11], [fx, fy + 15], [fx + 8, fy + 11]], 0.5);
    }
  }
}

