function drawSingleRoosterLeg(leg) {
  // 1. Base yellow-ochre wash for shank (tarsometatarsus)
  let dx = leg.ankle[0] - leg.hock[0];
  let dy = leg.ankle[1] - leg.hock[1];
  let len = Math.hypot(dx, dy);
  let nx = -dy / len;
  let ny = dx / len;

  brush.noStroke();
  brush.wash("#c98a22", 255);
  brush.beginShape(0.1);
  brush.vertex(leg.hock[0] - nx * leg.wTop * 0.5, leg.hock[1] - ny * leg.wTop * 0.5);
  brush.vertex(leg.hock[0] + nx * leg.wTop * 0.5, leg.hock[1] + ny * leg.wTop * 0.5);
  brush.vertex(leg.ankle[0] + nx * leg.wBot * 0.5, leg.ankle[1] + ny * leg.wBot * 0.5);
  brush.vertex(leg.ankle[0] - nx * leg.wBot * 0.5, leg.ankle[1] - ny * leg.wBot * 0.5);
  brush.endShape(true);
  brush.noWash();

  // 2. Sharp Curved Horn Cockspur
  let sb = leg.spurBase;
  let st = leg.spurTip;
  let sm = [(sb[0] + st[0]) / 2, (sb[1] + st[1]) / 2 - 6];
  brush.set("cpencil", "#d9c296", 1.2);
  safeSpline([[sb[0], sb[1] - 7], sm, st], 0.5);
  brush.set("cpencil", "#8c622b", 1.1);
  safeSpline([[sb[0], sb[1] + 7], [sm[0], sm[1] + 6], st], 0.5);
  brush.set("rotring", "#331e09", 0.55);
  safeSpline([[sb[0], sb[1] - 8], sm, st], 0.5);
  safeSpline([[sb[0], sb[1] + 8], [sm[0], sm[1] + 7], st], 0.5);
  brush.set("rotring", "#fff6db", 0.45);
  safeSpline([[sb[0], sb[1] + 4], [sm[0], sm[1] + 4], st], 0.5);

  // 3. Overlapping Hexagonal Dorsal Scutes (Scales) down the Tarsus Shank
  let numScutes = 16;
  for (let i = 0; i < numScutes; i++) {
    let t0 = i / numScutes;
    let t1 = (i + 0.92) / numScutes;
    let cx0 = lerp(leg.hock[0], leg.ankle[0], t0);
    let cy0 = lerp(leg.hock[1], leg.ankle[1], t0);
    let cx1 = lerp(leg.hock[0], leg.ankle[0], t1);
    let cy1 = lerp(leg.hock[1], leg.ankle[1], t1);
    let hw = lerp(leg.wTop, leg.wBot, t0) * 0.52;

    // Lateral reddish-pink vascular flush along the scale groove (authentic breeding cockerel detail)
    brush.set("cpencil", "#b84325", 0.65);
    safeLine(cx0 - nx * hw * 0.85, cy0, cx1 - nx * hw * 0.85, cy1);

    // Two interlocking rows of front scutes (left & right plates)
    for (let side of [-1, 1]) {
      let sOffset = side === 1 ? 0.15 : -0.15;
      let scX = cx0 + nx * (side * hw * 0.45);
      let scY = cy0 + (cy1 - cy0) * (0.5 + sOffset);
      let plateW = hw * 0.48;
      let plateH = (len / numScutes) * 0.55;

      // Golden yellow fill of each scale
      let scaleCol = side === 1 ? "#edb937" : "#cf9121";
      brush.set("cpencil", scaleCol, 0.85);
      safeLine(scX - nx * plateW * 0.7, scY, scX + nx * plateW * 0.7, scY);

      // Dark umber lower overlap crease of the scute
      brush.set("rotring", "#422307", 0.52);
      let pL = [scX - nx * plateW, scY - plateH * 0.2];
      let pM = [scX + nx * 1.5, scY + plateH * 0.75];
      let pR = [scX + nx * plateW, scY - plateH * 0.1];
      safeSpline([pL, pM, pR], 0.45);

      // Waxy ivory-yellow specular highlight from the frontal footlight
      if (side === 1 || i % 2 === 0) {
        brush.set("rotring", "#fff2b8", 0.42);
        safeLine(scX - nx * plateW * 0.35, scY + plateH * 0.32, scX + nx * plateW * 0.55, scY + plateH * 0.18);
      }
    }
  }

  // Outer contour definition of the shank
  brush.set("rotring", "#2e1805", 0.65);
  safeLine(leg.hock[0] - nx * leg.wTop * 0.52, leg.hock[1], leg.ankle[0] - nx * leg.wBot * 0.52, leg.ankle[1]);
  safeLine(leg.hock[0] + nx * leg.wTop * 0.52, leg.hock[1], leg.ankle[0] + nx * leg.wBot * 0.52, leg.ankle[1]);

  // 4. Splayed Toes with Transverse Scutes and Curved Horn Claws
  for (let toe of leg.toes) {
    let p0 = toe.pts[0];
    let p1 = toe.pts[1];
    let p2 = toe.pts[2];

    // Base yellow toe body
    brush.set("cpencil", "#d99b26", 1.3);
    safeSpline([p0, p1, p2], 0.4);
    brush.set("cpencil", "#8c5612", 1.0);
    safeSpline([[p0[0], p0[1] + 4], [p1[0], p1[1] + 4], [p2[0], p2[1] + 4]], 0.4);

    // Individual dorsal toe scutes (scales)
    let toeScutes = 9;
    for (let k = 0; k < toeScutes; k++) {
      let u = k / toeScutes;
      let tp = evalQuad(p0, p1, p2, u);
      let tpNext = evalQuad(p0, p1, p2, min(1, u + 0.08));
      let tang = atan2(tpNext[1] - tp[1], tpNext[0] - tp[0]);
      let tw = toe.w * (1 - u * 0.32) * 0.55;

      let sx1 = tp[0] + cos(tang - 90) * tw;
      let sy1 = tp[1] + sin(tang - 90) * tw;
      let sx2 = tp[0] + cos(tang) * 5;
      let sy2 = tp[1] + sin(tang) * 5;
      let sx3 = tp[0] + cos(tang + 90) * tw;
      let sy3 = tp[1] + sin(tang + 90) * tw;

      brush.set("rotring", "#3d2006", 0.5);
      safeSpline([[sx1, sy1], [sx2, sy2], [sx3, sy3]], 0.45);

      brush.set("rotring", "#fff4c2", 0.38);
      safeLine(tp[0] + cos(tang - 45) * tw * 0.5, tp[1] - 1.5, tp[0] + cos(tang + 45) * tw * 0.5, tp[1] + 1.5);
    }

    // Sharp curved keratin claw at toe tip
    let cTip = toe.claw;
    let cMid = [(p2[0] + cTip[0]) / 2, (p2[1] + cTip[1]) / 2 - 3.5];
    brush.set("cpencil", "#2b1d12", 0.95);
    safeSpline([[p2[0], p2[1] - 3], cMid, cTip], 0.5);
    brush.set("rotring", "#140c06", 0.65);
    safeSpline([[p2[0], p2[1] - 4], cMid, cTip], 0.5);
    safeLine(p2[0], p2[1] + 3, cTip[0], cTip[1]);
    // Specular ivory highlight on top of claw
    brush.set("rotring", "#f5e6c8", 0.38);
    safeSpline([[p2[0], p2[1] - 2], [cMid[0], cMid[1] + 1], cTip], 0.5);
  }
}

// ============================================================================
// 7. FLARING IRIDESCENT NECK HACKLES (MID-CROW ARCH)
// ============================================================================
function drawNeckHackles() {
  // Drawn from lower collar (y ~ 510) up to upper nape/throat (y ~ 285)
  // so upper hackles overlap lower ones naturally like roof tiles.
  let tiers = 16;
  for (let tier = 0; tier < tiers; tier++) {
    let u = tier / (tiers - 1); // 0 = lower collar, 1 = upper neck near head
    let count = floor(lerp(15, 9, u));

    for (let j = 0; j < count; j++) {
      let s = j / max(1, count - 1); // 0 = back of neck, 1 = front throat
      // Neck arch spine curves from (535, 420)..(695, 465) at bottom up to (552, 282)..(618, 315) at top
      let xBack = lerp(522, 548, u) - sin(u * 180) * 18;
      let xFront = lerp(698, 616, pow(u, 0.85)) + sin(u * 180) * 14;
      let bx = lerp(xBack, xFront, s) + random(-4, 4);
      let by = lerp(445, 285, u) + (s - 0.3) * 28 + random(-4, 4);

      let fLen = lerp(108, 46, u) * random(0.88, 1.12);
      // Flare angle: back hackles sweep down-left (135 deg), front hackles flare down-right (55 deg)
      let baseAng = lerp(136, 52, s) + sin(u * 180) * (s < 0.4 ? 14 : -10) + random(-5, 5);

      let p0 = [bx, by];
      let p1 = [bx + cos(baseAng - 8) * fLen * 0.48, by + sin(baseAng - 8) * fLen * 0.48];
      let p2 = [bx + cos(baseAng + 6) * fLen, by + sin(baseAng + 6) * fLen];

      // Color gradient:
      // Lower collar tips have dark beetle-green/black diamond spear-centers;
      // Mid ruff glows in golden-ochre, amber & copper;
      // Upper nape blazes in burnt persimmon & scarlet-orange.
      let baseCol, midCol, tipHighlight;
      if (u < 0.25) {
        baseCol = "#8c3b14";
        midCol = "#d98224";
        tipHighlight = "#f5cb6e";
      } else if (u < 0.68) {
        baseCol = "#a84418";
        midCol = "#e3962b";
        tipHighlight = "#fae08c";
      } else {
        baseCol = "#962412";
        midCol = "#cf4e1f";
        tipHighlight = "#f2a649";
      }

      // Outer feather barbs
      brush.set("cpencil", baseCol, 0.78);
      safeSpline([[p0[0] - 3, p0[1]], [p1[0] - 4, p1[1]], p2], 0.45);
      brush.set("cpencil", midCol, 0.72);
      safeSpline([[p0[0] + 3, p0[1]], [p1[0] + 4, p1[1]], p2], 0.45);

      // Dark iridescent black-green spear-point near tips of lower collar hackles
      if (u < 0.35 && j % 2 === 0) {
        let pMid = evalQuad(p0, p1, p2, 0.55);
        brush.set("rotring", "#14261d", 0.55);
        safeLine(pMid[0], pMid[1], p2[0], p2[1]);
      }

      // Luminous golden rachis shaft & raking frontal footlight edge
      brush.set("rotring", tipHighlight, 0.38);
      safeSpline([p0, p1, p2], 0.45);
    }
  }
}

// ============================================================================
// 8. HEAD, OPEN SCREAMING BEAK, KUMADORI COMB & WATTLES, AND FIERCE EYE
// ============================================================================
function drawHeadKumadoriAndEye() {
  // --------------------------------------------------------------------------
  // A. OPEN BEAK MID-CROW (SCREAMING POSTURE WITH LIFTED TONGUE)
  // --------------------------------------------------------------------------
  // 1. Mouth Cavity & Pharynx (between upper and lower mandibles)
  brush.noStroke();
  brush.wash("#4a0d0a", 255);
  brush.beginShape(0.2);
  brush.vertex(624, 268);
  brush.vertex(678, 258);
  brush.vertex(665, 290);
  brush.vertex(672, 312);
  brush.vertex(622, 298);
  brush.endShape(true);
  brush.noWash();

  // Tense pointed rooster tongue flung upward mid-crow
  let tBase = [626, 290];
