// Fingerboard central axis transform: origin at (260, -60), angle 60.42 deg
const FB_ORIGIN = { x: 260, y: -60 };
const FB_COS = Math.cos((60.42 * Math.PI) / 180); // ~0.4936
const FB_SIN = Math.sin((60.42 * Math.PI) / 180); // ~0.8697
// Perpendicular vector pointing from treble (left) toward bass (upper-right)
const FB_PX = FB_SIN;   // ~0.8697
const FB_PY = -FB_COS;  // ~-0.4936

function fbPoint(s, u) {
  // s: distance along fingerboard from top (-60 y), u: signed offset across (- = left/treble, + = right/bass)
  return [
    FB_ORIGIN.x + s * FB_COS + u * FB_PX,
    FB_ORIGIN.y + s * FB_SIN + u * FB_PY
  ];
}

function drawWashShape(pts, col, alpha, curvature = 0.35) {
  brush.noStroke();
  brush.noFill();
  brush.noHatch();
  brush.wash(col, alpha);
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(CLOSE);
  brush.noWash();
}

function drawWatercolorShape(pts, col, alpha, bleed = 0.22, tex = 0.55, border = 0.35, curvature = 0.4) {
  brush.noStroke();
  brush.noWash();
  brush.noHatch();
  brush.fill(col, alpha);
  brush.fillBleed(bleed, "out");
  brush.fillTexture(tex, border);
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(CLOSE);
  brush.noFill();
}

function jitterPts(pts, amt) {
  let out = [];
  for (let i = 0; i < pts.length; i++) {
    out.push([
      pts[i][0] + random(-amt, amt),
      pts[i][1] + random(-amt, amt)
    ]);
  }
  return out;
}

function sampleCatmullRom(pts, samplesPerSeg = 12) {
  if (pts.length < 2) return pts;
  let result = [];
  for (let i = 0; i < pts.length - 1; i++) {
    let p0 = pts[Math.max(0, i - 1)];
    let p1 = pts[i];
    let p2 = pts[i + 1];
    let p3 = pts[Math.min(pts.length - 1, i + 2)];
    for (let s = 0; s < samplesPerSeg; s++) {
      let t = s / samplesPerSeg;
      let t2 = t * t;
      let t3 = t2 * t;
      let x =
        0.5 *
        (2 * p1[0] +
          (-p0[0] + p2[0]) * t +
          (2 * p0[0] - 5 * p1[0] + 4 * p2[0] - p3[0]) * t2 +
          (-p0[0] + 3 * p1[0] - 3 * p2[0] + p3[0]) * t3);
      let y =
        0.5 *
        (2 * p1[1] +
          (-p0[1] + p2[1]) * t +
          (2 * p0[1] - 5 * p1[1] + 4 * p2[1] - p3[1]) * t2 +
          (-p0[1] + 3 * p1[1] - 3 * p2[1] + p3[1]) * t3);
      result.push([x, y]);
    }
  }
  result.push(pts[pts.length - 1]);
  return result;
}

