    [120, -30], [580, -30], [1180, 240], [1180, 1180], [160, 1180], [95, 580]
  ];
  drawWashShape(warmCorridor, "#21120e", 130, 0.4);
  drawWatercolorShape(jitterPts(warmCorridor, 30), "#2b1611", 95, 0.38, 0.6, 0.3, 0.45);

  // Layered organic watercolor blooms in Van Dyke brown, burnt umber & deep alizarin
  const glazeBatches = [
    { col: "#26130e", alpha: 75, bleed: 0.32, count: 6, cx: 520, cy: 520, rx: 420, ry: 460 },
    { col: "#331714", alpha: 65, bleed: 0.28, count: 6, cx: 580, cy: 460, rx: 340, ry: 360 },
    { col: "#180d0b", alpha: 90, bleed: 0.35, count: 5, cx: 260, cy: 820, rx: 320, ry: 340 },
    { col: "#140b0c", alpha: 95, bleed: 0.3, count: 5, cx: 960, cy: 840, rx: 280, ry: 320 }
  ];

  for (let b of glazeBatches) {
    for (let i = 0; i < b.count; i++) {
      let cx = b.cx + random(-160, 160);
      let cy = b.cy + random(-160, 160);
      let pts = [];
      let n = 8;
      for (let k = 0; k < n; k++) {
        let ang = (k / n) * 360;
        let r = 0.65 + 0.55 * noise(i * 10 + k * 0.7, cx * 0.005);
        pts.push([
          cx + cos(ang) * b.rx * r * 0.55,
          cy + sin(ang) * b.ry * r * 0.55
        ]);
      }
      drawWatercolorShape(pts, b.col, b.alpha, b.bleed, 0.6, 0.35, 0.45);
    }
  }

  // Subtle ambient background texture lines in dark charcoal & glazeBristle
  brush.field("celloGrain");
  brush.set("glazeBristle", "#1a1012", 1.4);
  for (let i = 0; i < 110; i++) {
    let x = random(0, 1200);
    let y = random(0, 1200);
    brush.flowLine(x, y, random(90, 240), 60 + random(-15, 15));
  }
  brush.noField();
}

