function renderCelloBody() {
  // 3A. Recessed flamed maple rib (side wall of the cello)
  let ribPoly = [...CELLO_RIB_LEFT, ...CELLO_TOP_EDGE.slice().reverse()];
  drawWashShape(ribPoly, "#1d100d", 210, 0.3);
  drawWatercolorShape(ribPoly, "#2d1511", 110, 0.15, 0.5, 0.4, 0.3);

  // Flamed maple curl stripes across the rib in subtle burnt umber & alizarin
  let ribOuter = sampleCatmullRom(CELLO_RIB_LEFT, 8);
  let ribInner = sampleCatmullRom(CELLO_TOP_EDGE, 8);
  let steps = Math.min(ribOuter.length, ribInner.length);
  for (let i = 0; i < steps; i += 2) {
    let p1 = ribOuter[i];
    let p2 = ribInner[i];
    let isAlizarin = i % 4 === 0;
    brush.set("cpencil", isAlizarin ? "#3b1716" : "#29140f", random(0.6, 1.1));
    brush.line(p1[0] + 3, p1[1], p2[0] - 3, p2[1]);
  }

  // 3B. Main Cello Spruce Belly (Arched Varnished Table)
  let bellyPoly = [
    ...CELLO_TOP_EDGE,
    [1180, 1230],
    [1180, 360],
    [680, -40]
  ];
  drawWashShape(bellyPoly, "#22120e", 215, 0.35);
  drawWatercolorShape(bellyPoly, "#2e1612", 115, 0.22, 0.55, 0.35, 0.35);

  // Deep alizarin crimson & burnt sienna antique varnish glazes over the arch of the belly
  const archGlazes = [
    // Warm alizarin glow along the left C-bout and upper bout arch
    {
      pts: [[220, 60], [390, 90], [450, 420], [360, 780], [240, 1080], [125, 960], [235, 540], [155, 220]],
      col: "#3b1615",
      alpha: 95
    },
    // Rich burnt umber & alizarin swell around the f-hole and beneath the fingerboard
    {
      pts: [[280, 380], [560, 440], [790, 880], [720, 1180], [230, 1180], [260, 680]],
      col: "#341812",
      alpha: 105
    },
    // Darker Van Dyke brown hollow near the C-bout channel and lower right
    {
      pts: [[580, 520], [1160, 480], [1160, 1200], [680, 1200]],
