  ];
  for (let g of archGlazes) {
    drawWatercolorShape(g.pts, g.col, g.alpha, 0.28, 0.58, 0.3, 0.45);
  }

  // 3C. Fine longitudinal spruce winter-grain lines across the cello belly
  for (let u = -340; u <= 220; u += 5.5) {
    let sStart = u < -140 ? map(u, -340, -140, 220, -20) : -20;
    let pA = fbPoint(sStart, u);
    let pB = fbPoint(1380, u);
    // Slight organic wave along the grain
    let mid1 = fbPoint(420, u + sin(u * 3) * 1.5);
    let mid2 = fbPoint(880, u - cos(u * 2) * 1.5);

    let grainCol = "#26130f";
    if (u > -240 && u < -60) {
      grainCol = random() < 0.45 ? "#3d1816" : "#331912";
    } else if (u >= -60 && u < 60) {
      grainCol = random() < 0.5 ? "#2f1512" : "#24120e";
    }
    brush.set("2H", grainCol, random(0.32, 0.58));
    brush.spline([pA, mid1, mid2, pB], 0.3);
  }

  // Cross-arch varnish modeling strokes (subtle horizontal-diagonal dry-brush glazes)
  for (let i = 0; i < 95; i++) {
