  // 3D. Double Purfling (inlaid ebony-maple-ebony strip 16px inside the outer spruce edge)
  let topCurve = sampleCatmullRom(CELLO_TOP_EDGE, 10);
  let purflingOuter = [];
  let purflingCenter = [];
  let purflingInner = [];
  for (let i = 0; i < topCurve.length; i++) {
    let p = topCurve[i];
    purflingOuter.push([p[0] + 15, p[1] + 2]);
    purflingCenter.push([p[0] + 17.5, p[1] + 2]);
    purflingInner.push([p[0] + 20, p[1] + 2]);
