  brush.set("rotring", "#100807", 0.55);
  brush.spline(purflingOuter, 0.4);
  brush.set("rotring", "#4e2218", 0.42);
  brush.spline(purflingCenter, 0.4);
  brush.set("rotring", "#100807", 0.5);
  brush.spline(purflingInner, 0.4);

