function getStringPoint(str, s) {
  let u;
  if (s <= 975) {
    u = map(s, -40, 975, str.uTop, str.uEnd);
  } else {
    u = map(s, 975, 1440, str.uEnd, str.uBridge);
  }
  // Subtle physical deflection where a finger presses the string onto the fingerboard
  for (let ps of str.pressS) {
    let distS = Math.abs(s - ps);
    if (distS < 45) {
      let pressFactor = Math.cos((distS / 45) * (Math.PI / 2));
      u += pressFactor * 2.2; // slight depression toward the fingerboard surface
    }
  }
  return fbPoint(s, u);
}

function isStringOccluded(str, s) {
  for (let r of str.occludeRanges) {
    if (s >= r[0] && s <= r[1]) return true;
  }
  return false;
}

function drawStringSegment(str, sStart, sEnd, isBrightForeground) {
  let ptsCore = [];
  let ptsShadow = [];
  let ptsRim = [];
  for (let s = sStart; s <= sEnd; s += 14) {
    let p = getStringPoint(str, s);
    ptsCore.push(p);
    // Cast shadow on fingerboard/belly to the right-down of the string
    let shadowOffset = s > 975 ? 11 : 4.5;
    ptsShadow.push([p[0] + shadowOffset, p[1] + shadowOffset * 0.4]);
    // Left (treble) edge of the string cylinder where the cadmium/silver rim light sits
    ptsRim.push([p[0] - str.weight * 0.9, p[1] + str.weight * 0.4]);
  }
  if (ptsCore.length < 2) return;

  // 1. Faint shadow of string on ebony / spruce belly
  brush.set("2B", "#080404", str.weight * 0.75);
  brush.spline(ptsShadow, 0.25);

  // 2. Dark metallic cylinder body of the string (burnt umber / warm gunmetal)
  brush.set("rotring", "#2b1915", str.weight * 1.15);
  brush.spline(ptsCore, 0.2);
  brush.set("rotring", "#472820", str.weight * 0.65);
  brush.spline(ptsCore, 0.2);

  // 3. Microscopic spiral windings (silver-wound texture)
  for (let s = sStart; s <= sEnd; s += str.windingSpacing) {
    let p = getStringPoint(str, s);
    let wHalf = str.weight * 1.35;
    let cWind = (Math.floor(s / str.windingSpacing) % 2 === 0) ? "#6e3b28" : "#22120e";
    if (isBrightForeground && random() < 0.4) {
      cWind = "#9c5433";
    }
    brush.set("needleSpec", cWind, 0.35);
    brush.line(
      p[0] - wHalf * FB_PX,
      p[1] - wHalf * FB_PY,
      p[0] + wHalf * FB_PX,
      p[1] + wHalf * FB_PY
    );
  }
}

function renderStringsBackLayer() {
  // Draw G and C strings (which pass beneath the arch of the hand)
  for (let idx of [2, 3]) {
    let str = STRINGS_SPEC[idx];
    // Upper segment above the hand
    drawStringSegment(str, -40, str.occludeRanges[0][0] + 15, false);
    // Lower segment emerging from beneath the pinky down toward the bridge
    drawStringSegment(str, str.occludeRanges[0][1] - 15, 1420, true);
  }
}

function renderStringsFrontLayer() {
  // Draw A and D strings in visible segments between the pressing fingers
  for (let idx of [0, 1]) {
    let str = STRINGS_SPEC[idx];
    let curS = -40;
    for (let r of str.occludeRanges) {
      if (r[0] > curS) {
        drawStringSegment(str, curS, r[0], true);
      }
      curS = r[1];
    }
    if (curS < 1420) {
      drawStringSegment(str, curS, 1420, true);
    }
  }
}

