function renderFingerForm(f, depthIndex) {
  let fullPoly = [...f.upperContour, ...f.lowerContour];

  // 1. Deep Van Dyke brown & burnt umber foundational occlusion wash so hand swallows into darkness
  drawWashShape(fullPoly, "#150b0a", 242, 0.35);

  // 2. Layered watercolor glaze inside the finger (burnt umber + warm alizarin crimson)
  drawWatercolorShape(fullPoly, "#281310", 135, 0.16, 0.55, 0.35, 0.35);

  // 3. Upper dorsal strip (just inside the lit contour) glazed with warm alizarin & burnt sienna-umber
  let upperLitStrip = [];
  for (let i = 0; i < f.upperContour.length; i++) {
    upperLitStrip.push(f.upperContour[i]);
  }
  for (let i = f.upperContour.length - 1; i >= 0; i--) {
    let p = f.upperContour[i];
    upperLitStrip.push([p[0] + 22, p[1] + 26]);
  }
  drawWatercolorShape(upperLitStrip, "#421816", 115, 0.22, 0.5, 0.3, 0.35);

  // 4. Lower palmar shadow strip in deep Van Dyke brown
  let lowerShadowStrip = [];
  for (let i = 0; i < f.lowerContour.length; i++) {
    lowerShadowStrip.push(f.lowerContour[i]);
  }
  for (let i = f.lowerContour.length - 1; i >= 0; i--) {
    let p = f.lowerContour[i];
    lowerShadowStrip.push([p[0] - 16, p[1] - 18]);
  }
  drawWashShape(lowerShadowStrip, "#0f0707", 190, 0.35);

  // 5. Anatomical cross-contour modeling along each phalanx (slight shifts between umber & alizarin)
  let upSamples = sampleCatmullRom(f.upperContour, 8);
  let loSamples = sampleCatmullRom(f.lowerContour.slice().reverse(), 8);
  let n = Math.min(upSamples.length, loSamples.length);

  for (let i = 2; i < n - 2; i++) {
    let pTop = upSamples[i];
    let pBot = loSamples[i];
    let midX = (pTop[0] + pBot[0]) * 0.5 + 6;
    let midY = (pTop[1] + pBot[1]) * 0.5 - 6;

    // Dorsal alizarin-umber highlight transition near top contour
    let pQuarter = [
      lerp(pTop[0], midX, 0.38),
      lerp(pTop[1], midY, 0.38)
    ];
    let dorsalCol = (i % 2 === 0) ? "#4f1c19" : "#3d1913";
    brush.set("cpencil", dorsalCol, random(0.55, 0.95));
    brush.spline([pTop, pQuarter, [midX, midY]], 0.35);

    // Core shadow transition into Van Dyke brown on the underside of the finger
    let palmarCol = (i % 3 === 0) ? "#261110" : "#180b0a";
    brush.set("charcoal", palmarCol, random(0.6, 1.0));
    brush.spline([[midX, midY], pBot], 0.3);
  }

  // 6. Knuckle prominences & dorsal skin folds (warm alizarin crimson blush over the joints)
  for (let k of f.knuckles) {
    let kx = k.pos[0];
    let ky = k.pos[1];
    let r = k.r;

    // Warm alizarin subsurface blush on the knuckle dome
    let kPoly = [];
    for (let a = 0; a < 360; a += 45) {
      kPoly.push([
        kx + cos(a) * r * 0.85,
        ky + sin(a) * r * 0.65 + 8
      ]);
    }
    drawWatercolorShape(kPoly, "#521c1a", 95, 0.25, 0.5, 0.3, 0.45);

    // Delicate elliptical skin wrinkles across the PIP/DIP knuckle joint
    for (let w = -2; w <= 2; w++) {
      let off = w * 3.2;
      let wrinklePts = [
        [kx - r * 0.45 + off * 0.4, ky + 4 + Math.abs(w) * 1.5],
        [kx + off * 0.6, ky + r * 0.42 + off],
        [kx + r * 0.48 + off * 0.4, ky + r * 0.78 + off * 0.8]
      ];
      let wCol = w < 0 ? "#68241d" : "#240e0d";
      brush.set("2B", wCol, 0.45);
      brush.spline(wrinklePts, 0.4);
    }
  }

  // 7. Deep crease line where adjacent fingers overlap
  brush.set("rotring", "#090404", 0.75);
  brush.spline(f.lowerContour.slice(0, 7), 0.35);
}

