function traceHairline(pts, intensity = 1.0, drawPeakGlints = true) {
  // Pass 1: Tight subsurface alizarin-sienna glow right inside/under the rim light
  let subPts = pts.map((p) => [p[0] + 1.8, p[1] + 1.8]);
  brush.set("subsurfacePen", "#822919", 0.95 * intensity);
  brush.spline(subPts, 0.38);

  // Pass 2: Deep cadmium red-orange halo
  brush.set("subsurfacePen", "#bf4618", 0.62 * intensity);
  brush.spline(pts, 0.38);

  // Pass 3: Crisp fine bright pen hairline in pure Cadmium Orange
  brush.set("hairlinePen", "#f26e1a", 0.82 * intensity);
  brush.spline(pts, 0.38);

  // Pass 4: Ultra-fine luminous cadmium core along the central 70% of the contour
  if (pts.length >= 3) {
    let corePts = pts.slice(0, Math.max(2, Math.floor(pts.length * 0.85)));
    brush.set("needleSpec", "#ff8e29", 0.72 * intensity);
    brush.spline(corePts, 0.38);
  }

  // Pass 5: Pinpoint incandescent cadmium-gold edge glints at the highest curvature apex
  if (drawPeakGlints && pts.length >= 3) {
    let midIdx = Math.floor(pts.length * 0.45);
    let apexPts = pts.slice(Math.max(0, midIdx - 1), Math.min(pts.length, midIdx + 2));
    if (apexPts.length >= 2) {
      brush.set("needleSpec", "#ffb34f", 0.65 * intensity);
      brush.spline(apexPts, 0.35);
    }
  }
}

