function renderStringRimSegment(str, segObj, strIdx) {
  let pts = segObj.map((o) => o.pt);

  // Warm subsurface copper-alizarin glow along the string
  brush.set("subsurfacePen", "#8f3219", 0.58);
  brush.spline(pts, 0.2);

  // Continuous fine bright pen line of Cadmium Orange along the lit left side of the string
  let orangeIntensity = strIdx === 0 ? 0.95 : strIdx === 1 ? 0.88 : 0.75;
  brush.set("hairlinePen", "#f5761a", orangeIntensity);
  brush.spline(pts, 0.2);

  // Silver-wound specular micro-beads along the lit edge (alternating warm silver & bright cadmium gold)
  for (let i = 0; i < segObj.length; i++) {
    let s = segObj[i].s;
    let p = segObj[i].pt;
    // Brightest near the finger contact zone and f-hole region (s between 240 and 1060)
    if (s > 120 && s < 1180) {
      let col = i % 3 === 0 ? "#e8cbb1" : i % 2 === 0 ? "#ff9c38" : "#f2711c";
      let w = strIdx <= 1 ? 0.52 : 0.62;
      brush.set("needleSpec", col, w);
      brush.line(
        p[0],
        p[1],
        p[0] + FB_COS * 3.2 + FB_PX * str.weight * 0.6,
        p[1] + FB_SIN * 3.2 + FB_PY * str.weight * 0.6
      );
    }
  }
}

