      weight = random(0.4, 0.68);
    }

    brush.set("needleSpec", speckCol, weight);
    let tinyLen = random(0.6, 2.2);
    let ang = random(0, 360);
    brush.line(
      baseX,
      baseY,
      baseX + cos(ang) * tinyLen,
      baseY + sin(ang) * tinyLen
    );
  }

  // A few delicate rosin specks resting directly on the lower end of the ebony fingerboard
  for (let i = 0; i < 38; i++) {
    let p = fbPoint(random(760, 972), random(-75, 70));
    let c = random(["#7a3b1e", "#b85c24", "#e6832e"]);
    brush.set("needleSpec", c, random(0.25, 0.48));
    brush.line(p[0], p[1], p[0] + 1.1, p[1] + 0.8);
  }

  // Final peripheral Van Dyke brown & dusky twilight vignette glazes to keep the edges hushed and intimate
  const cornerGlazes = [
    [[-40, -40], [280, -40], [110, 240], [-40, 420]],
    [[-40, 880], [105, 1080], [220, 1240], [-40, 1240]],
    [[960, -40], [1240, -40], [1240, 165], [1060, 155]],
    [[880, 940], [1240, 740], [1240, 1240], [680, 1240]]
  ];
  for (let cg of cornerGlazes) {
    drawWashShape(cg, "#0c0708", 155, 0.35);
  }
}

