// Bench curve definitions in 1200x1200 space
function getBenchY(x, curveId) {
  let u = x / 1200;
  let wave1 = sin(u * 360 - 25);
  let wave2 = cos(u * 270 + 15);
  let crestTop = 248 - 165 * u + 34 * wave1;
  let crestRidge = crestTop + 66 + 12 * wave2;
  let seatBack = 465 - 150 * u + 28 * sin(u * 290 - 15);
  let bullnoseTop = 895 - 145 * u + 44 * sin(u * 260 - 35);
  let bullnoseBot = bullnoseTop + 108 + 16 * cos(u * 260);
  let baseBot = bullnoseBot + 145;

  if (curveId === 0) return crestTop;
  if (curveId === 1) return crestRidge;
  if (curveId === 2) return seatBack;
  if (curveId === 3) return bullnoseTop;
  if (curveId === 4) return bullnoseBot;
  if (curveId === 5) return baseBot;
  return 0;
}

// Map parametric (s, t) within a bench zone to canvas (x, y)
function mapZonePoint(zoneId, s, t) {
  let x = s * 1200;
  // Slight perspective foreshortening sweep along the curved surface
  if (zoneId === "B") x += sin(t * 180) * 10;
  if (zoneId === "C") x += sin(t * 180) * 18 * (s - 0.3);
  if (zoneId === "D") x += sin(t * 180) * 12;

  let y0 = getBenchY(x, zoneId === "A" ? 0 : zoneId === "B" ? 1 : zoneId === "C" ? 2 : zoneId === "D" ? 3 : 4);
  let y1 = getBenchY(x, zoneId === "A" ? 1 : zoneId === "B" ? 2 : zoneId === "C" ? 3 : zoneId === "D" ? 4 : 5);
  let y = lerp(y0, y1, t);
  return [x, y];
}

// Anatomical ellipses making up the sleeping terrier (for silhouette, shadow & fur logic)
const DOG_PARTS = [
  // Rump & haunch (left)
  { name: "rump", cx: 435, cy: 555, rx: 92, ry: 82, rot: -15 },
  // Hind thigh & hock
