  // Collar tag
  { name: "tag", cx: 680, cy: 686, rx: 22, ry: 18, rot: -10, lifted: true }
];

function pointInRotatedEllipse(px, py, cx, cy, rx, ry, rotDeg, scale = 1.0) {
  let dx = px - cx;
  let dy = py - cy;
  let c = cos(-rotDeg);
  let s = sin(-rotDeg);
  let lx = dx * c - dy * s;
  let ly = dx * s + dy * c;
  let srx = rx * scale;
  let sry = ry * scale;
  return (lx * lx) / (srx * srx) + (ly * ly) / (sry * sry) <= 1.0;
}

function isInsideDogCastShadow(px, py) {
  // Short, crisp Mediterranean noon shadow offset (-18, +46), and slightly further for lifted paw
  for (let p of DOG_PARTS) {
    let ox = p.lifted ? -24 : -18;
    let oy = p.lifted ? 54 : 46;
    if (pointInRotatedEllipse(px - ox, py - oy, p.cx, p.cy, p.rx, p.ry, p.rot, 1.03)) {
      return true;
    }
  }
  return false;
}

function isInNoonShadow(x, y, zoneId, t) {
  if (zoneId === "C") {
    // Seat bed: shadowed by the sleeping terrier or very close to backrest lip
    if (t < 0.04) return true;
    return isInsideDogCastShadow(x, y);
  }
  if (zoneId === "B") {
    // Under the crest ridge overhang
    return t < 0.14;
  }
  if (zoneId === "D") {
    // Lower curve of the bullnose lip rolls away from noon sun into dusky shadow
    return t > 0.64;
  }
  if (zoneId === "E") {
    // Under-bench pedestal is in crisp overhang shadow
    return t < 0.72;
  }
  return false;
}

async function setup() {
