function draw() {
  translate(-width / 2, -height / 2);

  // 1. Draw Civic Park Plaza Ground (upper-left & lower corners beyond bench)
  drawParkPlaza();

  // 2. Draw Mortar / Concrete Bench Base Layers
  drawBenchMortarBase();

  // 3. Generate & Render Trencadís Ceramic Shards (batched watercolor + grout + chips + glaze)
  let allShards = generateAllBenchShards();
  renderShardsWatercolor(allShards);
  renderNoonCastShadowsOnBench();
  renderGroutAndShardDetails(allShards);

  // 4. Render the Hyperreal Sleeping Scruffy Terrier, Twitching Paw & Collar Tag
  renderTerrierUnderpainting();
  renderTerrierWatercolorVolumes();
  renderTerrierWiryFur();
  renderCollarAndTag();
  renderTwitchingPaw();
  renderTerrierFaceDetails();

  noLoop();
}

