// 2. BENCH MORTAR / GROUT BASE
// ============================================================================
function drawBenchMortarBase() {
  brush.noStroke();
  brush.noFill();

  // Full bench mortar bed in warm sunlit mortar
  brush.wash(PALETTE.groutSun, 255);
  brush.beginShape(0);
  for (let x = -20; x <= 1220; x += 40) brush.vertex(x, getBenchY(x, 0));
  for (let x = 1220; x >= -20; x -= 40) brush.vertex(x, getBenchY(x, 5));
  brush.endShape(CLOSE);

  // Slightly cooler mortar tone on backrest vertical face (Zone B)
  brush.wash(PALETTE.groutMid, 160);
  brush.beginShape(0);
  for (let x = -20; x <= 1220; x += 40) brush.vertex(x, getBenchY(x, 1));
  for (let x = 1220; x >= -20; x -= 40) brush.vertex(x, getBenchY(x, 2));
  brush.endShape(CLOSE);

  // Dusky twilight mortar in under-bench overhang (Zone D lower & Zone E)
  brush.wash(PALETTE.groutShadow, 235);
  brush.beginShape(0);
  for (let x = -20; x <= 1220; x += 40) {
    let p = mapZonePoint("D", x / 1200, 0.64);
    brush.vertex(p[0], p[1]);
  }
  for (let x = 1220; x >= -20; x -= 40) {
    let p = mapZonePoint("E", x / 1200, 0.75);
    brush.vertex(p[0], p[1]);
  }
  brush.endShape(CLOSE);

  // Dusky mortar under the sleeping dog's cast shadow
  brush.wash(PALETTE.groutShadow, 210);
  for (let p of DOG_PARTS) {
    let ox = p.lifted ? -24 : -18;
    let oy = p.lifted ? 54 : 46;
    drawEllipseShape(p.cx + ox, p.cy + oy, p.rx * 1.02, p.ry * 1.02, p.rot, 16);
  }
  brush.noWash();
}

function drawEllipseShape(cx, cy, rx, ry, rotDeg, steps = 18) {
  let c = cos(rotDeg);
  let s = sin(rotDeg);
  brush.beginShape(0.1);
  for (let i = 0; i < steps; i++) {
    let ang = (i / steps) * 360;
    let lx = cos(ang) * rx;
    let ly = sin(ang) * ry;
    let x = cx + lx * c - ly * s;
    let y = cy + lx * s + ly * c;
    brush.vertex(x, y);
  }
  brush.endShape(CLOSE);
}

// ============================================================================
// 3. TRENCADÍS CERAMIC SHARD GENERATOR & RENDERER
// ============================================================================
function generateAllBenchShards() {
  let zones = [
    { id: "A", cols: 24, rows: 2, grout: 3.2, highlightDir: -18 }, // Crest top roll
    { id: "B", cols: 24, rows: 4, grout: 3.6, highlightDir: 15 },  // Backrest concave face
    { id: "C", cols: 22, rows: 8, grout: 4.0, highlightDir: -25 }, // Seat bed
    { id: "D", cols: 24, rows: 3, grout: 3.4, highlightDir: -8 },  // Bullnose lip
    { id: "E", cols: 20, rows: 3, grout: 3.8, highlightDir: 12 }   // Under-bench base
  ];

  let shards = [];
  let colorFamilies = ["ultramarine", "cream", "saffron", "olive"];

  for (let z of zones) {
    // 1. Build jittered parameter grid (s, t)
    let grid = [];
    for (let i = 0; i <= z.cols; i++) {
      grid[i] = [];
      for (let j = 0; j <= z.rows; j++) {
        let s = -0.02 + (i / z.cols) * 1.04;
        let t = j / z.rows;
        if (i > 0 && i < z.cols) s += random(-0.34, 0.34) * (1.04 / z.cols);
        if (j > 0 && j < z.rows) t += random(-0.32, 0.32) * (1.0 / z.rows);
        let pt = mapZonePoint(z.id, s, t);
        grid[i][j] = { x: pt[0], y: pt[1], s, t };
      }
    }

    // 2. Convert each grid quad into 1 or 2 broken ceramic shards
    for (let i = 0; i < z.cols; i++) {
      for (let j = 0; j < z.rows; j++) {
        let p00 = grid[i][j];
        let p10 = grid[i + 1][j];
        let p11 = grid[i + 1][j + 1];
        let p01 = grid[i][j + 1];

        let rawPolys = [];
        let splitMode = random();

        if (splitMode < 0.42) {
          // Fracture across diagonal or mid-edge into two angular shards
          if (random() < 0.55) {
            // Diagonal fracture into 2 triangular/4-sided shards with slight midpoint kink
            let midX = (p00.x + p11.x) * 0.5 + random(-6, 6);
            let midY = (p00.y + p11.y) * 0.5 + random(-6, 6);
            rawPolys.push([p00, p10, p11, { x: midX, y: midY }]);
            rawPolys.push([p00, { x: midX, y: midY }, p11, p01]);
          } else {
            // Split top-to-bottom or left-to-right at angled fracture line
            let f1 = random(0.32, 0.68);
            let f2 = random(0.32, 0.68);
            let mTop = { x: lerp(p00.x, p10.x, f1), y: lerp(p00.y, p10.y, f1) };
            let mBot = { x: lerp(p01.x, p11.x, f2), y: lerp(p01.y, p11.y, f2) };
            rawPolys.push([p00, mTop, mBot, p01]);
            rawPolys.push([mTop, p10, p11, mBot]);
          }
        } else if (splitMode < 0.68) {
          // Corner chip fracture: 5-sided shard + small triangular wedge shard
          let f1 = random(0.38, 0.62);
          let f2 = random(0.38, 0.62);
          let mA = { x: lerp(p00.x, p10.x, f1), y: lerp(p00.y, p10.y, f1) };
          let mB = { x: lerp(p10.x, p11.x, f2), y: lerp(p10.y, p11.y, f2) };
          rawPolys.push([p00, mA, mB, p11, p01]);
          rawPolys.push([mA, p10, mB]);
        } else {
          // Keep as irregular 4-sided broken shard
          rawPolys.push([p00, p10, p11, p01]);
        }

        // Choose a ceramic family with playful spatial clustering
        let nVal = noise(i * 0.45 + z.id.charCodeAt(0), j * 0.45);
        let baseFamIdx = floor(nVal * 4.99) % 4;

        for (let poly of rawPolys) {
          // Compute centroid
          let cx = 0, cy = 0;
          for (let v of poly) { cx += v.x; cy += v.y; }
          cx /= poly.length;
          cy /= poly.length;

          // Skip shards completely hidden deep inside the solid core of the dog's torso
          // (Saves render budget while keeping all perimeter & near-edge shards intact!)
          let deepUnderDog =
            pointInRotatedEllipse(cx, cy, 555, 548, 95, 68, 6) ||
            pointInRotatedEllipse(cx, cy, 435, 555, 68, 56, -15) ||
            pointInRotatedEllipse(cx, cy, 755, 565, 55, 48, 14);
          if (deepUnderDog) continue;

          // Inset vertices toward centroid to leave soft pencil grout channel
          let insetVerts = [];
          for (let v of poly) {
            let dx = v.x - cx;
            let dy = v.y - cy;
            let d = sqrt(dx * dx + dy * dy);
            let shrink = min(z.grout * random(0.85, 1.25), d * 0.35);
            let ratio = (d - shrink) / max(d, 0.001);
            insetVerts.push([
              cx + dx * ratio + random(-0.9, 0.9),
              cy + dy * ratio + random(-0.9, 0.9)
            ]);
          }

          let tApprox = (j + 0.5) / z.rows;
          let shadowed = isInNoonShadow(cx, cy, z.id, tApprox);

          // Pick color family (cluster with neighbor or play with contrast)
          let famName = random() < 0.62 ? colorFamilies[baseFamIdx] : random(colorFamilies);
          let fam = PALETTE.shards[famName];
          let colorHex = shadowed ? random(fam.shadow) : random(fam.sun);

          shards.push({
            zoneId: z.id,
            tApprox,
            rawPoly: poly,
            verts: insetVerts,
            cx,
            cy,
            famName,
            colorHex,
            chipColor: fam.chip,
            shadowed,
            highlightDir: z.highlightDir
          });
        }
      }
    }
  }
  return shards;
}

function renderShardsWatercolor(shards) {
  // Batch shards by exact colorHex for maximum p5.brush watercolor fill speed
  let batches = {};
  for (let s of shards) {
    if (!batches[s.colorHex]) batches[s.colorHex] = [];
    batches[s.colorHex].push(s);
  }

  brush.noStroke();
  brush.fillBleed(0.035, "in");
  brush.fillTexture(0.42, 0.28);

  for (let colorHex of Object.keys(batches)) {
    let group = batches[colorHex];
    // Slightly higher opacity for deep ultramarine/shadow shards, airy glaze for sunlit ones
    brush.fill(colorHex, 215);
    for (let s of group) {
      brush.beginShape(0.06);
      for (let v of s.verts) {
        brush.vertex(v[0], v[1]);
      }
      brush.endShape(CLOSE);
    }
  }
  brush.noFill();
}

function renderNoonCastShadowsOnBench() {
  // Crisp, short Mediterranean noon shadow cutting sharply across the mosaic tiles
  brush.noStroke();
  brush.fill(PALETTE.noonShadow, 105);
  brush.fillBleed(0.02, "in");
  brush.fillTexture(0.35, 0.45);

  for (let p of DOG_PARTS) {
    let ox = p.lifted ? -24 : -18;
    let oy = p.lifted ? 54 : 46;
    drawEllipseShape(p.cx + ox, p.cy + oy, p.rx * 1.01, p.ry * 1.01, p.rot, 16);
  }

  // Crisp shadow under backrest crest lip (top of Zone B)
  brush.fill(PALETTE.noonShadow, 90);
  brush.beginShape(0.05);
  for (let x = -20; x <= 1220; x += 60) {
    let p = mapZonePoint("B", x / 1200, 0);
    brush.vertex(p[0], p[1]);
  }
