function renderGroutAndShardDetails(shards) {
  // Pass 1: Soft pencil grey grout lines winding through the mortar channels
  brush.set("2B", PALETTE.pencilDark, 0.58);
  for (let s of shards) {
    let n = s.rawPoly.length;
    for (let k = 0; k < n; k++) {
      // Draw half the raw edges to avoid double-drawing shared mortar seams
      let a = s.rawPoly[k];
      let b = s.rawPoly[(k + 1) % n];
      if (a.x < b.x || (abs(a.x - b.x) < 1 && a.y < b.y)) {
        brush.line(a.x, a.y, b.x, b.y);
      }
    }
  }

  // Secondary softer HB graphite pass on shard rims for tactile mortar recession
  brush.set("HB", PALETTE.pencilLight, 0.45);
  for (let s of shards) {
    let v = s.verts;
    let n = v.length;
    for (let k = 0; k < n; k++) {
      if (random() < 0.65) {
        let a = v[k];
        let b = v[(k + 1) % n];
        brush.line(a[0], a[1], b[0], b[1]);
      }
    }
  }

  // Pass 2: Dark bottom/left tile thickness bevel (ceramic depth)
  brush.set("cpencil", PALETTE.pencilDeep, 0.52);
  for (let s of shards) {
    let v = s.verts;
    let n = v.length;
    for (let k = 0; k < n; k++) {
      let a = v[k];
      let b = v[(k + 1) % n];
      let mx = (a[0] + b[0]) * 0.5;
      let my = (a[1] + b[1]) * 0.5;
      // Lower or left-facing edge gets a crisp dark tile-thickness shadow
      if (my > s.cy + 2 || mx < s.cx - 4) {
        brush.line(a[0], a[1], b[0], b[1]);
      }
    }
  }

  // Pass 3: Chipped ceramic bisque edge on upper/fractured rims of each shard
  for (let s of shards) {
    if (s.shadowed && random() < 0.5) continue;
    brush.set("cpencil", s.chipColor, s.shadowed ? 0.45 : 0.68);
    let v = s.verts;
    let n = v.length;
    for (let k = 0; k < n; k++) {
      let a = v[k];
      let b = v[(k + 1) % n];
      let mx = (a[0] + b[0]) * 0.5;
      let my = (a[1] + b[1]) * 0.5;
      // Upper/right sunlit fracture edges show chipped unglazed ceramic rim
      if (my < s.cy + 1 && mx >= s.cx - 8) {
        brush.line(a[0], a[1], lerp(a[0], b[0], 0.85), lerp(a[1], b[1], 0.85));
        // Occasional tiny triangular chip nick at vertex
        if (random() < 0.35) {
          brush.line(a[0], a[1], lerp(a[0], s.cx, 0.18), lerp(a[1], s.cy, 0.18));
        }
      }
    }
  }

  // Pass 4: Glazed white specular highlight on each shard!
  // Brightest on crest roll (Zone A) and bullnose lip (Zone D), crisp on seat (Zone C)
  for (let s of shards) {
    let v = s.verts;
    if (v.length < 3) continue;

    // Find upper-most edge or sun-facing vertex for the specular glaze streak
    let v0 = v[0];
    let v1 = v[1];
    let pA = [
      lerp(v0[0], s.cx, 0.26),
      lerp(v0[1], s.cy, 0.26)
    ];
    let pB = [
      lerp(v1[0], s.cx, 0.28),
      lerp(v1[1], s.cy, 0.28)
    ];

    if (s.shadowed) {
      // Subtle dusky twilight sky reflection in shadowed shards
      if (random() < 0.65) {
        brush.set("cpencil", "#9ba8c7", 0.55);
        brush.line(pA[0], pA[1], pB[0], pB[1]);
      }
    } else {
      // Bright glazed white highlight
      let isHighGlare = (s.zoneId === "A") || (s.zoneId === "D" && s.tApprox < 0.48);
      brush.set("glaze_spec", "#ffffff", isHighGlare ? 1.05 : 0.72);
      brush.line(pA[0], pA[1], pB[0], pB[1]);

      // Sharp white pinpoint glint on the ceramic glaze
      brush.set("fine_whisker", "#ffffff", isHighGlare ? 1.15 : 0.85);
      let gx = lerp(pA[0], pB[0], 0.35);
      let gy = lerp(pA[1], pB[1], 0.35);
      brush.line(gx, gy, gx + 5, gy - 1.5);
    }
  }
}

