// Helper to draw dense, hyperreal V-clumped wiry terrier fur across an anatomical region
function drawFurClumpRegion(cfg) {
  let c = cos(cfg.rot);
  let s = sin(cfg.rot);

  for (let i = 0; i < cfg.count; i++) {
    // Sample inside ellipse with radial falloff so edges are feathery and scruffy
    let r = sqrt(random()) * random(0.85, 1.08);
    let theta = random(360);
    let lx = cos(theta) * cfg.rx * r;
    let ly = sin(theta) * cfg.ry * r;
    let x = cfg.cx + lx * c - ly * s;
    let y = cfg.cy + lx * s + ly * c;

    // Normalized vertical position in region (-1 = top sunlit crest, +1 = bottom shadow)
    let normY = ly / cfg.ry;

    // Pick hair color based on anatomical lighting & saddle grizzle
    let col;
    if (cfg.topLit && normY < -0.42 && random() < 0.68) {
      col = random() < 0.55 ? PALETTE.dogFurSunTip : PALETTE.dogFurCream;
    } else if (cfg.saddleGrizzle && normY > -0.45 && normY < 0.25 && random() < 0.62) {
      col = random() < 0.5 ? PALETTE.dogFurCharcoal : PALETTE.dogSaddleGrizzle;
    } else if (normY > 0.48 && random() < 0.65) {
      col = random() < 0.5 ? PALETTE.dogShadowCool : PALETTE.dogShadowDeep;
    } else {
      col = random(cfg.colors);
    }

    let w = random(cfg.weights);
    brush.set("wiry_hair", col, w);

    // Compute local flow angle with organic noise curl
    let nAng = (noise(x * 0.012, y * 0.012) - 0.5) * cfg.angleSpread * 2.2;
    let ang = cfg.baseAngle + nAng + normY * 18;
    let len = random(cfg.lenMin, cfg.lenMax);

    // Draw kinked wiry hair (2-segment spline or crisp line)
    let mx = x + cos(ang) * (len * 0.52);
    let my = y + sin(ang) * (len * 0.52);
    let kink = random(-16, 16);
    let ex = mx + cos(ang + kink) * (len * 0.48);
    let ey = my + sin(ang + kink) * (len * 0.48);

    brush.line(x, y, mx, my);
    brush.line(mx, my, ex, ey);

    // Occasional converging sister hair to form a classic scruffy terrier V-tuft
    if (random() < 0.35) {
      let sx = x + random(-5, 5);
      let sy = y + random(-5, 5);
      brush.line(sx, sy, ex + random(-2, 2), ey + random(-2, 2));
    }
  }
}

