function drawEllipseOutline(cx, cy, rx, ry, rotDeg, steps = 20) {
  let c = cos(rotDeg);
  let s = sin(rotDeg);
  let prevX = 0, prevY = 0;
  for (let i = 0; i <= steps; i++) {
    let ang = (i / steps) * 360;
    let lx = cos(ang) * rx;
    let ly = sin(ang) * ry;
    let x = cx + lx * c - ly * s;
    let y = cy + lx * s + ly * c;
    if (i > 0) brush.line(prevX, prevY, x, y);
    prevX = x;
    prevY = y;
  }
}

