// ============================================================================
// 1. CARPET PAGE & FLAGSTONE GEOMETRY
// ============================================================================
function buildFlagstoneLayout() {
  flagstones = [];
  borderCells = [];

  // Stepped rectilinear flagstone pavement arranged around the carpet-page grid
  // Outer margin stones (top, bottom, left, right)
  const outerRects = [
    // Top margin stones
    { x: 18, y: 18, w: 210, h: 66, kind: "stone", tone: 0 },
    { x: 242, y: 18, w: 280, h: 52, kind: "stone", tone: 1 },
    { x: 536, y: 18, w: 128, h: 52, kind: "lapis_gap" },
    { x: 678, y: 18, w: 280, h: 52, kind: "stone", tone: 0 },
    { x: 972, y: 18, w: 210, h: 66, kind: "stone", tone: 2 },
    // Bottom margin stones
    { x: 18, y: 1116, w: 210, h: 66, kind: "stone", tone: 1 },
    { x: 242, y: 1130, w: 265, h: 52, kind: "stone", tone: 0 },
    { x: 521, y: 1130, w: 158, h: 52, kind: "lapis_gap" },
    { x: 693, y: 1130, w: 265, h: 52, kind: "stone", tone: 2 },
    { x: 972, y: 1116, w: 210, h: 66, kind: "stone", tone: 0 },
    // Left margin stones
    { x: 18, y: 98, w: 66, h: 140, kind: "stone", tone: 2 },
    { x: 18, y: 252, w: 52, h: 270, kind: "stone", tone: 0 },
    { x: 18, y: 536, w: 52, h: 128, kind: "lapis_gap" },
    { x: 18, y: 678, w: 52, h: 270, kind: "stone", tone: 1 },
    { x: 18, y: 962, w: 66, h: 140, kind: "stone", tone: 0 },
    // Right margin stones
    { x: 1116, y: 98, w: 66, h: 140, kind: "stone", tone: 1 },
    { x: 1130, y: 252, w: 52, h: 270, kind: "stone", tone: 2 },
    { x: 1130, y: 536, w: 52, h: 128, kind: "lapis_gap" },
    { x: 1130, y: 678, w: 52, h: 270, kind: "stone", tone: 0 },
    { x: 1116, y: 962, w: 66, h: 140, kind: "stone", tone: 1 }
  ];

  // Interior flagstone grid (seen beneath the hose coils) with 14px mortar gaps
  const cols = [150, 315, 468, 578, 622, 732, 885, 1050];
  const rows = [150, 315, 468, 578, 622, 732, 885, 1050];
  const gap = 14;

  for (let r = 0; r < rows.length - 1; r++) {
    for (let c = 0; c < cols.length - 1; c++) {
      let x1 = cols[c] + gap * 0.5;
      let y1 = rows[r] + gap * 0.5;
      let w = cols[c + 1] - cols[c] - gap;
      let h = rows[r + 1] - rows[r] - gap;

      // Cruciform central spines and diagonal corner bays become lapis or vellum cells
      let isCrossArm = (r === 3 || c === 3);
      let isCornerCell = (r === 0 || r === 6) && (c === 0 || c === 6);
      let isInnerRing = (r >= 2 && r <= 4 && c >= 2 && c <= 4);

      if (isCrossArm || isCornerCell) {
        flagstones.push({
          x: x1,
          y: y1,
          w: w,
          h: h,
          kind: (r + c) % 2 === 0 ? "lapis_cell" : "vellum_cell",
          tone: (r * 3 + c) % 3
        });
      } else {
        // Subdivide larger flagstones into realistic masonry slabs with narrow lapis/vellum gaps
        if (w > 120 && h > 120 && !isInnerRing) {
          let splitV = (r + c) % 2 === 0;
          if (splitV) {
            let w1 = Math.floor(w * 0.54) - 6;
            flagstones.push({ x: x1, y: y1, w: w1, h: h, kind: "stone", tone: (r + c) % 3 });
            flagstones.push({ x: x1 + w1 + 2, y: y1, w: 8, h: h, kind: (r % 2 === 0) ? "lapis_gap" : "vellum_gap" });
            flagstones.push({ x: x1 + w1 + 12, y: y1, w: w - w1 - 12, h: h, kind: "stone", tone: (r + c + 1) % 3 });
          } else {
            let h1 = Math.floor(h * 0.48) - 6;
            flagstones.push({ x: x1, y: y1, w: w, h: h1, kind: "stone", tone: (r + c) % 3 });
            flagstones.push({ x: x1, y: y1 + h1 + 2, w: w, h: 8, kind: (c % 2 === 0) ? "lapis_gap" : "vellum_gap" });
            flagstones.push({ x: x1, y: y1 + h1 + 12, w: w, h: h - h1 - 12, kind: "stone", tone: (r + c + 2) % 3 });
          }
        } else {
          flagstones.push({
            x: x1,
            y: y1,
            w: w,
            h: h,
            kind: isInnerRing ? ((r + c) % 2 === 0 ? "lapis_cell" : "vellum_cell") : "stone",
            tone: (r + c) % 3
          });
        }
      }
    }
  }

  // Horizontal & vertical mortar channels between rows/cols filled with flat lapis & vellum watercolor
  for (let r = 1; r < rows.length - 1; r++) {
    let y = rows[r] - gap * 0.5 + 1;
    for (let c = 0; c < cols.length - 1; c++) {
      let x = cols[c] + gap * 0.5;
      let w = cols[c + 1] - cols[c] - gap;
      flagstones.push({
        x: x,
        y: y,
        w: w,
        h: gap - 2,
        kind: (r + c) % 2 === 0 ? "lapis_gap" : "vellum_gap"
      });
    }
  }
  for (let c = 1; c < cols.length - 1; c++) {
    let x = cols[c] - gap * 0.5 + 1;
    for (let r = 0; r < rows.length - 1; r++) {
      let y = rows[r] + gap * 0.5;
      let h = rows[r + 1] - rows[r] - gap;
      flagstones.push({
        x: x,
        y: y,
        w: gap - 2,
        h: h,
        kind: (r + c + 1) % 2 === 0 ? "lapis_gap" : "vellum_gap"
      });
    }
  }

  for (let o of outerRects) flagstones.push(o);

  // Carpet-page stepped border frame compartments (between 84..144 and 1056..1116)
  const stepSegments = 16;
  const spanStart = 236;
  const spanEnd = 964;
  const stepLen = (spanEnd - spanStart) / stepSegments;
  for (let i = 0; i < stepSegments; i++) {
    let s = spanStart + i * stepLen;
    let isLapis = i % 2 === 0;
    // Top border band
    borderCells.push({ x: s + 2, y: 92, w: stepLen - 4, h: 42, lapis: isLapis });
    // Bottom border band
    borderCells.push({ x: s + 2, y: 1066, w: stepLen - 4, h: 42, lapis: !isLapis });
    // Left border band
    borderCells.push({ x: 92, y: s + 2, w: 42, h: stepLen - 4, lapis: !isLapis });
    // Right border band
    borderCells.push({ x: 1066, y: s + 2, w: 42, h: stepLen - 4, lapis: isLapis });
  }
}

function drawFlagstonesAndGaps() {
  brush.noStroke();
  brush.noHatch();

  // BATCH 1: Flat Vellum-Cream Watercolor fills for stones & vellum gaps
  brush.fillBleed(0.03, "out");
  brush.fillTexture(0.55, 0.35);

  const vellumTones = ["#eee4ca", "#e4d8ba", "#dfd1b0"];
  for (let t = 0; t < 3; t++) {
    brush.fill(vellumTones[t], 175);
    for (let f of flagstones) {
      if (f.kind === "stone" && f.tone === t) {
        brush.rect(f.x, f.y, f.w, f.h);
      }
    }
  }

  brush.fill("#f6efe0", 215);
  for (let f of flagstones) {
    if (f.kind === "vellum_gap" || f.kind === "vellum_cell") {
      brush.rect(f.x, f.y, f.w, f.h);
    }
  }
  for (let b of borderCells) {
    if (!b.lapis) {
      brush.rect(b.x, b.y, b.w, b.h);
    }
  }

  // BATCH 2: Flat Lapis-Blue Watercolor fills for stone gaps, cross arms, and border cells
  brush.fillBleed(0.025, "in");
  brush.fillTexture(0.68, 0.48);
  brush.fill("#1d3e6e", 215);
  for (let f of flagstones) {
    if (f.kind === "lapis_gap") {
      brush.rect(f.x, f.y, f.w, f.h);
    }
  }
  for (let b of borderCells) {
    if (b.lapis) {
      brush.rect(b.x, b.y, b.w, b.h);
    }
  }

  brush.fill("#254d85", 200);
  for (let f of flagstones) {
    if (f.kind === "lapis_cell") {
      brush.rect(f.x, f.y, f.w, f.h);
    }
  }

  // Stepped corner turret lapis recesses
  const corners = [
    [92, 92],
    [972, 92],
    [972, 972],
    [92, 972]
  ];
  brush.fill("#173259", 220);
  for (let [cx, cy] of corners) {
    brush.rect(cx, cy, 136, 136);
  }
  brush.fill("#efe5cc", 210);
  for (let [cx, cy] of corners) {
    brush.rect(cx + 22, cy + 22, 92, 92);
  }
  brush.fill("#22487d", 215);
  for (let [cx, cy] of corners) {
    brush.rect(cx + 38, cy + 38, 60, 60);
  }

  brush.noFill();

  // Chalky mineral texture and stone pores on the flagstones
  for (let f of flagstones) {
    if (f.kind === "stone") {
      // Subtle dry-pigment hatching for limestone planar grain
      brush.hatchStyle("2H", "#c7b999", 0.7);
      brush.hatch(14, (f.tone * 45 + 15) % 180, { rand: 0.08 });
      brush.noStroke();
      brush.rect(f.x + 4, f.y + 4, f.w - 8, f.h - 8);
      brush.noHatch();

      // Hairline stone fissures & mineral flecks
      if (random() < 0.65) {
        brush.set("2H", "#9e8e70", 0.65);
        let sx = f.x + random(15, f.w - 15);
        let sy = f.y + random(15, f.h - 15);
        let ang = random(-35, 35);
        let len = random(18, Math.min(55, f.w * 0.5));
        brush.line(sx, sy, sx + cos(ang) * len, sy + sin(ang) * len);
      }
    } else if (f.kind === "lapis_gap" || f.kind === "lapis_cell") {
      // Chalky ultramarine mineral granulation inside lapis gaps
      brush.set("cpencil", "#3e6ca8", 0.85);
      let nStrokes = Math.max(2, Math.floor((f.w * f.h) / 900));
      for (let k = 0; k < nStrokes; k++) {
        let px = f.x + random(3, Math.max(4, f.w - 3));
        let py = f.y + random(3, Math.max(4, f.h - 3));
        brush.line(px - 3, py, px + 3, py);
      }
    }
  }

  // Crisp sepia ink masonry edges around stone slabs and gaps
  brush.set("rotring", "#3a271b", 0.65);
  for (let f of flagstones) {
    brush.rect(f.x, f.y, f.w, f.h);
  }
  for (let b of borderCells) {
    brush.rect(b.x, b.y, b.w, b.h);
  }
}

// ============================================================================
// 2. KNOTWORK TOPOLOGY & STRICT INTERLACE ENGINE
// ============================================================================
function buildCarpetKnotHose() {
  const cx = 600;
  const cy = 600;
  let ctrlPts = [];

  // Start at the bottom carpet-page entrance (brass female spigot coupling)
  ctrlPts.push([658, 1052]);
  ctrlPts.push([634, 998]);

  // Quadrant template in local (u, v) coordinates:
  // Every quadrant has a stepped corner turret knot, outer border weave,
  // diagonal lattice, cardinal axis cross-lock, and inner rosette lobe.
  const quadTemplate = [
    [340, 0],
    [330, 95],
    [230, 185],
    [215, 310],
    [290, 405],
    [435, 435], // Corner turret apex
    [405, 290],
    [295, 250],
    [165, 265], // Crosses [230,185]-[215,310]
    [112, 368], // Tight hairpin (kink candidate)
    [210, 415],
    [332, 345], // Crosses [215,310]-[290,405]
    [405, 175], // Crosses [405,290]-[295,250]
    [275, 110], // Crosses [330,95]-[230,185]
    [175, 80],
    [130, -56], // Dips across cardinal axis into previous quadrant
    [230, -56],
    [250, 46],  // Returns across cardinal axis
    [145, 155], // Crosses [275,110]-[175,80]
    [76, 96],
    [16, 175],  // Interlocks with adjacent quadrant's cardinal loop
    [95, 245],
    [55, 392]
  ];

  // Rotate quadrant template through k = 0, 1, 2, 3
  // k=0: e1=(0,1) Down, e2=(-1,0) Left  -> Bottom-Left Quadrant
  // k=1: e1=(-1,0) Left, e2=(0,-1) Up   -> Top-Left Quadrant
  // k=2: e1=(0,-1) Up, e2=(1,0) Right   -> Top-Right Quadrant
  // k=3: e1=(1,0) Right, e2=(0,1) Down  -> Bottom-Right Quadrant
  const dirs = [
    { e1: [0, 1], e2: [-1, 0] },
    { e1: [-1, 0], e2: [0, -1] },
    { e1: [0, -1], e2: [1, 0] },
    { e1: [1, 0], e2: [0, 1] }
  ];

  for (let k = 0; k < 4; k++) {
    let { e1, e2 } = dirs[k];
    let limit = (k === 3) ? 20 : quadTemplate.length;
    for (let m = 0; m < limit; m++) {
      let [u, v] = quadTemplate[m];
      let px = cx + u * e1[0] + v * e2[0];
      let py = cy + u * e1[1] + v * e2[1];
      ctrlPts.push([px, py]);
    }
  }

  // After Quadrant 3's inner lobe, weave through the central cruciform sanctuary
  // and terminate in the central machined brass twist-nozzle
  ctrlPts.push([542, 668]);
  ctrlPts.push([518, 558]);
  ctrlPts.push([588, 512]);
  ctrlPts.push([672, 558]);
  ctrlPts.push([652, 650]);
  ctrlPts.push([576, 622]);
  ctrlPts.push([612, 578]); // Base of the brass twist-nozzle

  // Sample uniform arc-length Catmull-Rom spline at ds = 2.5 px
  let denseRaw = [];
  for (let i = 0; i < ctrlPts.length - 1; i++) {
    let p0 = ctrlPts[Math.max(0, i - 1)];
    let p1 = ctrlPts[i];
    let p2 = ctrlPts[i + 1];
    let p3 = ctrlPts[Math.min(ctrlPts.length - 1, i + 2)];
    let segSteps = 48;
    for (let s = 0; s < segSteps; s++) {
      let t = s / segSteps;
      let pt = evalCatmullRom(p0, p1, p2, p3, t);
      denseRaw.push(pt);
    }
  }
  denseRaw.push(ctrlPts[ctrlPts.length - 1]);

  // Resample to strict uniform spacing ds = 2.5 px
  const ds = 2.5;
  hosePts = [];
  let accum = 0;
  hosePts.push({ x: denseRaw[0][0], y: denseRaw[0][1], s: 0 });
  for (let i = 1; i < denseRaw.length; i++) {
    let dx = denseRaw[i][0] - denseRaw[i - 1][0];
    let dy = denseRaw[i][1] - denseRaw[i - 1][1];
    let d = Math.hypot(dx, dy);
    if (d < 1e-5) continue;
    accum += d;
    while (accum >= ds) {
      accum -= ds;
      let overshoot = accum / d;
      let px = denseRaw[i][0] - dx * overshoot;
      let py = denseRaw[i][1] - dy * overshoot;
      hosePts.push({ x: px, y: py, s: hosePts.length * ds });
    }
  }

  // Compute tangents, normals, and curvature to identify realistic kink locations
  const N = hosePts.length;
  for (let i = 0; i < N; i++) {
    let iPrev = Math.max(0, i - 3);
    let iNext = Math.min(N - 1, i + 3);
    let dx = hosePts[iNext].x - hosePts[iPrev].x;
    let dy = hosePts[iNext].y - hosePts[iPrev].y;
    let len = Math.hypot(dx, dy) || 1;
    hosePts[i].tx = dx / len;
    hosePts[i].ty = dy / len;
    hosePts[i].nx = -dy / len;
    hosePts[i].ny = dx / len;
    hosePts[i].r = 20.5; // Base hose radius (41 px diameter)
  }

  // Locate 3 sharp hairpin bends for hyperreal garden hose kinks
  kinkIndices = [];
  const candidateWindows = [
    [Math.floor(N * 0.08), Math.floor(N * 0.22)],
    [Math.floor(N * 0.32), Math.floor(N * 0.48)],
    [Math.floor(N * 0.56), Math.floor(N * 0.74)]
  ];
  for (let [wStart, wEnd] of candidateWindows) {
    let bestIdx = -1;
    let maxCurv = -1;
    for (let i = wStart; i < wEnd; i++) {
      let dtx = hosePts[i + 4].tx - hosePts[i - 4].tx;
      let dty = hosePts[i + 4].ty - hosePts[i - 4].ty;
      let curv = Math.hypot(dtx, dty);
      if (curv > maxCurv) {
        maxCurv = curv;
        bestIdx = i;
      }
    }
    if (bestIdx > 0) kinkIndices.push(bestIdx);
  }

  // Pinch hose radius at each kink with realistic side-shoulder bulge
  for (let kIdx of kinkIndices) {
    for (let i = Math.max(0, kIdx - 22); i <= Math.min(N - 1, kIdx + 22); i++) {
      let u = (i - kIdx) / 7.5;
      let pinch = -0.31 * Math.exp(-u * u) + 0.08 * Math.exp(-0.35 * (u * u - 2.2) * (u * u - 2.2));
      hosePts[i].r = 20.5 * (1 + pinch);
    }
  }

  // Detect all self-intersections of the hose centerline
  let rawCrossings = [];
  const minIdxSep = 38;
  for (let i = 0; i < N - 2; i++) {
    let ax1 = hosePts[i].x, ay1 = hosePts[i].y;
    let ax2 = hosePts[i + 1].x, ay2 = hosePts[i + 1].y;
    for (let j = i + minIdxSep; j < N - 2; j++) {
      let bx1 = hosePts[j].x, by1 = hosePts[j].y;
      let bx2 = hosePts[j + 1].x, by2 = hosePts[j + 1].y;
      if (Math.abs(ax1 - bx1) > 10 && Math.abs(ay1 - by1) > 10) continue;
      let hit = segmentIntersection(ax1, ay1, ax2, ay2, bx1, by1, bx2, by2);
      if (hit) {
        // Avoid duplicate detections of adjacent micro-segments
        let dup = false;
        for (let c of rawCrossings) {
          if (Math.abs(c.i - i) < 12 && Math.abs(c.j - j) < 12) {
            dup = true;
            break;
          }
        }
        if (!dup) {
          rawCrossings.push({ i: i, j: j, x: hit.x, y: hit.y, signI: 0 });
        }
      }
    }
  }

  // Assign strict over-under alternating interlace logic (Tait's theorem walk)
  let visits = [];
  for (let cIdx = 0; cIdx < rawCrossings.length; cIdx++) {
    visits.push({ idx: rawCrossings[cIdx].i, cIdx: cIdx, first: true });
    visits.push({ idx: rawCrossings[cIdx].j, cIdx: cIdx, first: false });
  }
  visits.sort((a, b) => a.idx - b.idx);

  let expectedSign = 1;
  for (let v of visits) {
    let c = rawCrossings[v.cIdx];
    if (c.signI === 0) {
      c.signI = v.first ? expectedSign : -expectedSign;
      expectedSign = -expectedSign;
    } else {
      let actualSign = v.first ? c.signI : -c.signI;
      expectedSign = -actualSign;
    }
  }

  crossings = rawCrossings.map((c) => ({
    underIdx: c.signI < 0 ? c.i : c.j,
    overIdx: c.signI < 0 ? c.j : c.i,
    x: c.x,
    y: c.y
  }));

  // Pre-link each hose sample near an under-pass to its over-passing partner
  for (let i = 0; i < N; i++) {
    hosePts[i].overPartners = [];
  }
  for (let c of crossings) {
    for (let i = Math.max(0, c.underIdx - 28); i <= Math.min(N - 1, c.underIdx + 28); i++) {
      hosePts[i].overPartners.push(c.overIdx);
    }
  }
}

function evalCatmullRom(p0, p1, p2, p3, t) {
  let t2 = t * t;
  let t3 = t2 * t;
  let x =
    0.5 *
    (2 * p1[0] +
      (-p0[0] + p2[0]) * t +
      (2 * p0[0] - 5 * p1[0] + 4 * p2[0] - p3[0]) * t2 +
      (-p0[0] + 3 * p1[0] - 3 * p2[0] + p3[0]) * t3);
  let y =
    0.5 *
    (2 * p1[1] +
      (-p0[1] + p2[1]) * t +
      (2 * p0[1] - 5 * p1[1] + 4 * p2[1] - p3[1]) * t2 +
      (-p0[1] + 3 * p1[1] - 3 * p2[1] + p3[1]) * t3);
  return [x, y];
}

function segmentIntersection(x1, y1, x2, y2, x3, y3, x4, y4) {
  let denom = (y4 - y3) * (x2 - x1) - (x4 - x3) * (y2 - y1);
  if (Math.abs(denom) < 1e-7) return null;
  let ua = ((x4 - x3) * (y1 - y3) - (y4 - y3) * (x1 - x3)) / denom;
  let ub = ((x2 - x1) * (y1 - y3) - (y2 - y1) * (x1 - x3)) / denom;
  if (ua >= 0 && ua <= 1 && ub >= 0 && ub <= 1) {
    return { x: x1 + ua * (x2 - x1), y: y1 + ua * (y2 - y1) };
  }
  return null;
}

// Fast exact occlusion check: returns true if point (px, py) on strand sample idx
// lies underneath an over-passing hose strand.
function isPointOccluded(px, py, idx, margin = 0.6) {
  let partners = hosePts[idx].overPartners;
  if (!partners || partners.length === 0) return false;
  const N = hosePts.length;
  for (let p = 0; p < partners.length; p++) {
    let oIdx = partners[p];
    let kStart = Math.max(0, oIdx - 22);
    let kEnd = Math.min(N - 1, oIdx + 22);
    for (let k = kStart; k <= kEnd; k++) {
      let dx = px - hosePts[k].x;
      let dy = py - hosePts[k].y;
      let rLim = hosePts[k].r + margin;
      if (dx * dx + dy * dy < rLim * rLim) {
        return true;
      }
    }
  }
  return false;
}

// Helper to draw a longitudinal filament along the hose at normalized lateral offset uNorm in [-1, 1]
// Automatically splits into unoccluded spline ribbons at every UNDER-crossing!
function drawHoseFilament(uNorm, stepStride, pressureFn, margin = 0.5, startIdx = 0, endIdx = -1) {
  const N = hosePts.length;
  if (endIdx < 0) endIdx = N - 1;
  let run = [];

  const flushRun = () => {
    if (run.length >= 3) {
      brush.spline(run, 0.25);
    } else if (run.length === 2) {
      brush.line(run[0][0], run[0][1], run[1][0], run[1][1]);
    }
    run = [];
  };

  for (let i = startIdx; i <= endIdx; i += stepStride) {
    let pt = hosePts[i];
    let offset = uNorm * pt.r;
    let px = pt.x + pt.nx * offset;
    let py = pt.y + pt.ny * offset;

    if (isPointOccluded(px, py, i, margin)) {
      // Refine exact entry boundary with 1-step precision if we were just inside a run
      if (run.length > 0 && stepStride > 1) {
        for (let sub = i - stepStride + 1; sub < i; sub++) {
          let spt = hosePts[sub];
          let spx = spt.x + spt.nx * (uNorm * spt.r);
          let spy = spt.y + spt.ny * (uNorm * spt.r);
          if (!isPointOccluded(spx, spy, sub, margin)) {
            run.push([spx, spy, pressureFn ? pressureFn(sub) : 1.0]);
          } else {
            break;
          }
        }
      }
      flushRun();
    } else {
      // If starting a new run right after an occlusion, back-step to capture exact exit edge
      if (run.length === 0 && i > startIdx && stepStride > 1) {
        for (let sub = i - stepStride + 1; sub < i; sub++) {
          let spt = hosePts[sub];
          let spx = spt.x + spt.nx * (uNorm * spt.r);
          let spy = spt.y + spt.ny * (uNorm * spt.r);
          if (!isPointOccluded(spx, spy, sub, margin)) {
            run.push([spx, spy, pressureFn ? pressureFn(sub) : 1.0]);
          }
        }
      }
      run.push([px, py, pressureFn ? pressureFn(i) : 1.0]);
    }
  }
  flushRun();
}

// ============================================================================
// 3. SHADOWS & RED-LEAD (MINIUM) STIPPLE DOTS
// ============================================================================
function drawHoseDropShadows() {
  brush.noFill();
  brush.noHatch();

  // Soft umber-slate contact shadow offset (+4.5, +5.5) beneath the hose on the flagstones
  const N = hosePts.length;
  const shadowOffsets = [-0.65, -0.2, 0.25, 0.7];
  brush.set("marker", "#241d17", 2.4);
  for (let u of shadowOffsets) {
    let run = [];
    for (let i = 0; i < N; i += 4) {
      let pt = hosePts[i];
      let px = pt.x + pt.nx * (u * pt.r) + 4.5;
      let py = pt.y + pt.ny * (u * pt.r) + 5.5;
      run.push([px, py, 0.85]);
    }
    if (run.length >= 3) brush.spline(run, 0.25);
  }
}

function drawRedLeadDots() {
  brush.noFill();
  brush.noHatch();

  // Build spatial grid of hose centerline points for fast distance queries
  const cellSize = 40;
  const grid = new Map();
  for (let i = 0; i < hosePts.length; i += 2) {
    let gx = Math.floor(hosePts[i].x / cellSize);
    let gy = Math.floor(hosePts[i].y / cellSize);
    let key = gx + "," + gy;
    if (!grid.has(key)) grid.set(key, []);
    grid.get(key).push(hosePts[i]);
  }

  function isClearOfHose(px, py, minDist) {
    let gx = Math.floor(px / cellSize);
    let gy = Math.floor(py / cellSize);
    let minD2 = minDist * minDist;
    for (let dx = -1; dx <= 1; dx++) {
      for (let dy = -1; dy <= 1; dy++) {
        let bucket = grid.get((gx + dx) + "," + (gy + dy));
        if (!bucket) continue;
        for (let pt of bucket) {
          let d2 = (px - pt.x) * (px - pt.x) + (py - pt.y) * (py - pt.y);
          if (d2 < minD2) return false;
        }
      }
    }
    return true;
  }

  // Row 1 & Row 2 of tiny red-lead (minium) dots hugging both outer contours of the hose
  const dotColors = ["#d6381e", "#e34a2b"];
  for (let row = 0; row < 2; row++) {
    let distOut = row === 0 ? 28.5 : 35.5;
    let clearReq = row === 0 ? 26.8 : 33.5;
    let step = row === 0 ? 4 : 6;
    brush.set("minium_dot", dotColors[row], row === 0 ? 1.05 : 0.82);

    for (let side of [-1, 1]) {
      for (let i = 4; i < hosePts.length - 4; i += step) {
        let pt = hosePts[i];
        let px = pt.x + pt.nx * side * distOut;
        let py = pt.y + pt.ny * side * distOut;
        if (px < 92 || px > 1108 || py < 92 || py > 1108) continue;
        if (isClearOfHose(px, py, clearReq)) {
          brush.line(px - 0.4, py - 0.4, px + 0.4, py + 0.4);
        }
      }
    }
  }

  // Red-lead dot rows tracing the carpet-page frame perimeter and corner turrets
  brush.set("minium_dot", "#d93b20", 1.0);
  const frameDotStep = 10.5;
  for (let d = 232; d <= 968; d += frameDotStep) {
    // Outer and inner border lines
    brush.line(d, 85, d + 0.4, 85.4);
    brush.line(d, 141, d + 0.4, 141.4);
    brush.line(d, 1059, d + 0.4, 1059.4);
    brush.line(d, 1115, d + 0.4, 1115.4);

    brush.line(85, d, 85.4, d + 0.4);
    brush.line(141, d, 141.4, d + 0.4);
    brush.line(1059, d, 1059.4, d + 0.4);
    brush.line(1115, d, 1115.4, d + 0.4);
  }

  // Dots around the four corner turrets
  const turretBoxes = [
    [85, 85, 148, 148],
    [967, 85, 148, 148],
    [967, 967, 148, 148],
    [85, 967, 148, 148]
  ];
  for (let [bx, by, bw, bh] of turretBoxes) {
    for (let t = 0; t <= bw; t += 10) {
      brush.line(bx + t, by, bx + t + 0.4, by + 0.4);
      brush.line(bx + t, by + bh, bx + t + 0.4, by + bh + 0.4);
      brush.line(bx, by + t, bx + 0.4, by + t + 0.4);
      brush.line(bx + bw, by + t, bx + bw + 0.4, by + t + 0.4);
    }
  }
}

// ============================================================================
// 4. HYPERREAL GARDEN HOSE RENDERING (VERDIGRIS, ORPIMENT YELLOW, SEPIA INK)
// ============================================================================
function drawGardenHoseBody() {
  brush.noFill();
  brush.noHatch();

  // Layer 1: Opaque mineral underpainting across the cylinder width so no stone gap bleeds through
  const underBands = [
    { u: -0.82, col: "#1e4d41", w: 2.3 },
    { u: -0.58, col: "#2b6959", w: 2.5 },
    { u: -0.32, col: "#3c8571", w: 2.6 },
    { u: -0.06, col: "#669c68", w: 2.6 },
    { u: 0.20, col: "#448c77", w: 2.6 },
    { u: 0.48, col: "#2f6e5d", w: 2.5 },
    { u: 0.78, col: "#1b453a", w: 2.3 }
  ];

  for (let b of underBands) {
    brush.set("marker", b.col, b.w);
    drawHoseFilament(b.u, 3, () => 0.95, 0.4);
  }

  // Layer 2: Chalky mineral pigment modeling (Verdigris shadow -> Verdigris midtone -> Orpiment Yellow crown)
  // Using directional illumination from upper-left (-0.707, -0.707) plus cylindrical crown sheen
  const chalkBands = [
    { u: -0.90, brush: "cpencil", col: "#15382f", w: 1.4 },
    { u: -0.74, brush: "mineral_chalk", col: "#23594b", w: 1.25 },
    { u: -0.54, brush: "mineral_chalk", col: "#347b68", w: 1.35 },
    { u: -0.36, brush: "mineral_chalk", col: "#549c7e", w: 1.35 },
    { u: -0.20, brush: "mineral_chalk", col: "#9ab558", w: 1.3 },
    { u: -0.06, brush: "mineral_chalk", col: "#dfb13b", w: 1.25 }, // Orpiment yellow crown
    { u: 0.08, brush: "mineral_chalk", col: "#cfa034", w: 1.2 },   // Warm orpiment flank
    { u: 0.24, brush: "mineral_chalk", col: "#6fa16e", w: 1.3 },
    { u: 0.44, brush: "mineral_chalk", col: "#3c806d", w: 1.35 },
    { u: 0.66, brush: "mineral_chalk", col: "#265c4d", w: 1.3 },
    { u: 0.86, brush: "cpencil", col: "#163b31", w: 1.45 }
  ];

  for (let b of chalkBands) {
    brush.set(b.brush, b.col, b.w);
    drawHoseFilament(
      b.u,
      3,
      (idx) => 0.85 + 0.25 * Math.sin(idx * 0.07 + b.u * 4),
      0.5
    );
  }
}

function drawHoseBraidedMesh() {
  // Hyperreal reinforced garden hose helical cord mesh visible beneath the translucent vinyl skin
  const N = hosePts.length;

  // Dark verdigris helical reinforcement threads
  brush.set("2H", "#1d4a3f", 0.72);
  for (let i = 6; i < N - 10; i += 5) {
    let pt1 = hosePts[i];
    let pt2 = hosePts[i + 4];
    let phase = (i * 0.42) % (Math.PI * 2);
    let u1 = Math.sin(phase) * 0.86;
    let u2 = Math.sin(phase + 0.95) * 0.86;

    let x1 = pt1.x + pt1.nx * (u1 * pt1.r);
    let y1 = pt1.y + pt1.ny * (u1 * pt1.r);
    let x2 = pt2.x + pt2.nx * (u2 * pt2.r);
    let y2 = pt2.y + pt2.ny * (u2 * pt2.r);

    if (!isPointOccluded(x1, y1, i, 0.8) && !isPointOccluded(x2, y2, i + 4, 0.8)) {
      brush.line(x1, y1, x2, y2);
    }

    // Counter-helix thread for diamond braid
    let u3 = Math.cos(phase) * 0.86;
    let u4 = Math.cos(phase + 0.95) * 0.86;
    let x3 = pt1.x + pt1.nx * (u3 * pt1.r);
    let y3 = pt1.y + pt1.ny * (u3 * pt1.r);
    let x4 = pt2.x + pt2.nx * (u4 * pt2.r);
    let y4 = pt2.y + pt2.ny * (u4 * pt2.r);

    if (!isPointOccluded(x3, y3, i, 0.8) && !isPointOccluded(x4, y4, i + 4, 0.8)) {
      brush.line(x3, y3, x4, y4);
    }
  }

  // Luminous orpiment-yellow & pale verdigris braided highlights along the upper cylinder
  brush.set("2H", "#f0cb5b", 0.78);
  for (let i = 8; i < N - 10; i += 6) {
    let pt1 = hosePts[i];
    let pt2 = hosePts[i + 3];
    let phase = (i * 0.42) % (Math.PI * 2);
    let u1 = Math.sin(phase) * 0.42 - 0.08;
    let u2 = Math.sin(phase + 0.75) * 0.42 - 0.08;

    let x1 = pt1.x + pt1.nx * (u1 * pt1.r);
    let y1 = pt1.y + pt1.ny * (u1 * pt1.r);
    let x2 = pt2.x + pt2.nx * (u2 * pt2.r);
    let y2 = pt2.y + pt2.ny * (u2 * pt2.r);

    if (!isPointOccluded(x1, y1, i, 0.8) && !isPointOccluded(x2, y2, i + 3, 0.8)) {
      brush.line(x1, y1, x2, y2);
    }
  }
}

function drawCrossingCastShadows() {
  // Deep three-dimensional occlusion shadow cast by every OVER-strand onto its UNDER-strand
  const N = hosePts.length;

  for (let c of crossings) {
    let uIdx = c.underIdx;
    let oIdx = c.overIdx;

    // Sample points along the UNDER-strand right outside the OVER-strand's boundary
    for (let pass = 0; pass < 2; pass++) {
      let minDist = pass === 0 ? 20.8 : 23.5;
      let maxDist = pass === 0 ? 29.0 : 35.0;
      brush.set("cpencil", pass === 0 ? "#19120c" : "#15362d", pass === 0 ? 1.45 : 1.15);

      for (let i = Math.max(2, uIdx - 22); i <= Math.min(N - 3, uIdx + 22); i++) {
        let pt = hosePts[i];
        // Find minimum distance from pt to the OVER-strand centerline
        let bestD = 999;
        for (let k = Math.max(0, oIdx - 18); k <= Math.min(N - 1, oIdx + 18); k++) {
          let d = Math.hypot(pt.x - hosePts[k].x, pt.y - hosePts[k].y);
          if (d < bestD) bestD = d;
        }

        if (bestD >= minDist && bestD <= maxDist) {
          // Draw cross-contour shadow hatch across the UNDER-strand cylinder
          let x1 = pt.x - pt.nx * (pt.r * 0.9);
          let y1 = pt.y - pt.ny * (pt.r * 0.9);
          let x2 = pt.x + pt.nx * (pt.r * 0.9);
          let y2 = pt.y + pt.ny * (pt.r * 0.9);
          if (!isPointOccluded(x1, y1, i, 0.5) && !isPointOccluded(x2, y2, i, 0.5)) {
            brush.line(x1, y1, x2, y2);
          }
        }
      }
    }
  }
}

function drawHoseSpecularAndKinks() {
  // 1. Continuous hyperreal sheen along the hose crown (Orpiment yellow + mineral white-gold)
  brush.set("cpencil", "#f3cd59", 1.35);
  drawHoseFilament(-0.12, 3, (i) => 0.8 + 0.35 * Math.cos(i * 0.05), 0.7);

  brush.set("cpencil", "#fff6d6", 1.05);
  drawHoseFilament(
    -0.16,
    3,
    (i) => {
      // Modulate specular sheen by orientation to top-left light source
      let lightDot = -hosePts[i].nx * 0.707 - hosePts[i].ny * 0.707;
      return Math.max(0.25, 0.65 + 0.55 * lightDot);
    },
    0.8
  );

  // Subtle secondary reflected rim light along the lower cylinder edge
  brush.set("2H", "#7abfa8", 0.85);
  drawHoseFilament(0.72, 4, () => 0.75, 0.7);

  // 2. Render hyperreal pinched kinks at kinkIndices
  for (let kIdx of kinkIndices) {
    let pt = hosePts[kIdx];
    let ptPrev = hosePts[Math.max(0, kIdx - 6)];
    let ptNext = hosePts[Math.min(hosePts.length - 1, kIdx + 6)];

    if (isPointOccluded(pt.x, pt.y, kIdx, 2.0)) continue;

    // Dark verdigris & sepia V-buckle crease across the pinched waist
    brush.set("cpencil", "#142e26", 1.6);
    let cx1 = pt.x - pt.nx * (pt.r * 0.95);
    let cy1 = pt.y - pt.ny * (pt.r * 0.95);
    let cx2 = pt.x + pt.nx * (pt.r * 0.95);
    let cy2 = pt.y + pt.ny * (pt.r * 0.95);
    brush.line(cx1, cy1, cx2, cy2);

    // Diagonal pinch folds radiating from the kink apex
    brush.set("rotring", "#24160e", 0.95);
    brush.line(
      ptPrev.x - ptPrev.nx * (ptPrev.r * 0.75),
      ptPrev.y - ptPrev.ny * (ptPrev.r * 0.75),
      cx2,
      cy2
    );
    brush.line(
      ptNext.x - ptNext.nx * (ptNext.r * 0.75),
      ptNext.y - ptNext.ny * (ptNext.r * 0.75),
      cx2,
      cy2
    );

    // Stress-whitened Orpiment Yellow & chalk-cream ridges flanking the kink fold
    brush.set("cpencil", "#f5ce52", 1.5);
    for (let side of [-4, 4]) {
      let spt = hosePts[kIdx + side];
      brush.line(
        spt.x - spt.nx * (spt.r * 0.65),
        spt.y - spt.ny * (spt.r * 0.65),
        spt.x + spt.nx * (spt.r * 0.55),
        spt.y + spt.ny * (spt.r * 0.55)
      );
    }
    brush.set("cpencil", "#fff9e2", 1.2);
    brush.line(
      ptPrev.x - ptPrev.nx * (ptPrev.r * 0.3),
      ptPrev.y - ptPrev.ny * (ptPrev.r * 0.3),
      pt.x - pt.nx * (pt.r * 0.5),
      pt.y - pt.ny * (pt.r * 0.5)
    );
  }
}

function drawDriedMudCrusts() {
  // Crusty patches and splatters of dried suburban garden mud on the hose and stones
  const N = hosePts.length;
  const mudIntervals = [
    [120, 175],
    [340, 395],
    [610, 670],
    [920, 985],
    [1280, 1340],
    [1640, 1705],
    [2010, 2070],
    [2390, 2450],
    [2760, 2820]
  ];

  for (let [mStart, mEnd] of mudIntervals) {
    if (mEnd >= N) continue;

    // Base dried clay & raw umber mud crust along lower flank of the hose
    brush.set("mineral_chalk", "#6e5843", 1.35);
    drawHoseFilament(0.45, 2, () => 0.9, 0.6, mStart, mEnd);

    brush.set("cpencil", "#9c8368", 1.15);
    drawHoseFilament(0.32, 2, () => 0.85, 0.6, mStart + 4, mEnd - 4);

    // Pale dry silt cracks and tiny mud crumbs
    brush.set("2H", "#c4b093", 0.85);
    for (let i = mStart; i <= mEnd; i += 4) {
      let pt = hosePts[i];
      let u = random(0.1, 0.78);
      let mx = pt.x + pt.nx * (u * pt.r);
      let my = pt.y + pt.ny * (u * pt.r);
      if (!isPointOccluded(mx, my, i, 0.8)) {
        let ang = random(0, 180);
        brush.line(mx - cos(ang) * 3.5, my - sin(ang) * 3.5, mx + cos(ang) * 3.5, my + sin(ang) * 3.5);
      }
    }

    // Fine sepia outline around cracked mud flakes
    brush.set("rotring", "#3b281a", 0.55);
    for (let i = mStart + 3; i <= mEnd - 3; i += 6) {
      let pt = hosePts[i];
      let mx = pt.x + pt.nx * (0.52 * pt.r);
      let my = pt.y + pt.ny * (0.52 * pt.r);
      if (!isPointOccluded(mx, my, i, 0.8)) {
        brush.circle(mx, my, random(2.2, 4.5), 0.35);
      }
    }
  }
}

function drawHoseSepiaOutlines() {
  // Crisp sepia ink outlines on both edges of the hose, strictly clipped at every under-crossing
  brush.set("rotring", "#23150d", 1.25);
  drawHoseFilament(-1.0, 2, () => 1.0, 0.25);
  drawHoseFilament(1.0, 2, () => 1.0, 0.25);

