function drawBrassNozzle() {
  // Hyperreal machined brass twist-nozzle at the terminal end of the hose in the central sanctuary
  let lastPt = hosePts[hosePts.length - 1];
  let ang = atan2(lastPt.ty, lastPt.tx);

  push();
  translate(lastPt.x, lastPt.y);
  rotate(ang);

  // 1. Cast shadow beneath the heavy brass nozzle
  brush.noStroke();
  brush.fill("#17120d", 165);
  brush.fillBleed(0.06);
  brush.beginShape(0.2);
  brush.vertex(2, -18);
  brush.vertex(88, -12);
  brush.vertex(96, 18);
  brush.vertex(4, 26);
  brush.endShape(CLOSE);
  brush.noFill();

  // 2. Machined Brass Sections along the nozzle axis (x from -4 to 88):
  // Section A: Ribbed collar (-4..18, radius 21)
  // Section B: Knurled twist barrel (18..50, radius 23)
  // Section C: Tapered cone body (50..76, radius 21 -> 13)
  // Section D: Adjustable spray tip crown (76..88, radius 15)
  const slices = 38;
  for (let s = 0; s <= slices; s++) {
    let u = (s / slices) * 2 - 1; // -1 to +1 across cylinder diameter
    // Metallic cylindrical reflectance (bright gold-white core, rich orpiment-brass mid, dark umber-gold edge, warm reflected rim)
    let col;
    if (u < -0.75) col = "#3b2607";
    else if (u < -0.48) col = "#7d5614";
    else if (u < -0.22) col = "#c99528";
    else if (u < 0.02) col = "#f2ce5b";
    else if (u < 0.22) col = "#fff8db";
    else if (u < 0.48) col = "#deb03c";
    else if (u < 0.76) col = "#875d16";
    else col = "#4a320a";

    brush.set("cpencil", col, 1.45);
    // Collar (-4..18)
    brush.line(-4, u * 20, 18, u * 20);
    // Knurled grip barrel (18..50)
    brush.line(18, u * 22.5, 50, u * 22.5);
    // Tapered cone (50..76)
    brush.line(50, u * 20.5, 76, u * 13.0);
    // Spray head crown (76..88)
    brush.line(76, u * 15.0, 88, u * 14.5);
  }

  // 3. Verdigris patina nestled in the machined grooves of the brass nozzle
  brush.set("cpencil", "#357d6a", 1.1);
  for (let gx of [6, 12, 18, 50, 76]) {
    let h = gx === 76 ? 14 : 20;
