  }

  // 4. Diamond knurling texture on the twist-barrel (x in 20..48)
  brush.set("rotring", "#3d2712", 0.58);
  for (let kx = 20; kx <= 44; kx += 4) {
    brush.line(kx, -21, kx + 6, 21);
