  }

  // 5. Crisp sepia ink mechanical contours and rings
  brush.set("rotring", "#21130b", 1.2);
  brush.rect(-4, -20.5, 22, 41);
  brush.rect(18, -22.5, 32, 45);
  brush.beginShape(0);
  brush.vertex(50, -20.5);
  brush.vertex(76, -13.0);
  brush.vertex(76, 13.0);
  brush.vertex(50, 20.5);
  brush.endShape(CLOSE);
  brush.rect(76, -15.0, 12, 30.0);

  // Machined collar grooves
  brush.set("rotring", "#2a190f", 0.85);
  brush.line(5, -20.5, 5, 20.5);
  brush.line(11, -20.5, 11, 20.5);
  brush.line(82, -15.0, 82, 15.0);

  // Intense linear specular bar along the tapered brass cone
  brush.set("cpencil", "#ffffff", 1.35);
  brush.line(-2, 2.5, 16, 2.5);
  brush.line(52, 2.2, 74, 1.5);
  brush.line(78, 1.8, 86, 1.8);

  // 6. Hyperreal water droplet trembling at the brass nozzle aperture + fallen bead on stone
  // Droplet 1: clinging to nozzle tip (x=94, y=2)
  brush.noStroke();
  brush.fill("#1d456b", 160);
  brush.circle(95, 3, 6.5);
  brush.fill("#8fd4c9", 185);
  brush.circle(93.5, 1.5, 4.5);
