// Bottle diagonal axis transform
const O_PT = { x: 88, y: 82 };
const AXIS_DEG = 44.4;
const COS_A = Math.cos((AXIS_DEG * Math.PI) / 180);
const SIN_A = Math.sin((AXIS_DEG * Math.PI) / 180);

function bottlePt(s, r) {
  return [
    O_PT.x + s * COS_A - r * SIN_A,
    O_PT.y + s * SIN_A + r * COS_A
  ];
}

function cylPt(s, R, phiDeg, tilt = 0.27, twistS = 0, radialWarp = 0) {
  let phi = (phiDeg * Math.PI) / 180;
  let rad = R + radialWarp;
  let r = rad * Math.sin(phi);
  let sOff = -rad * tilt * Math.cos(phi) + twistS;
  return bottlePt(s + sOff, r);
}

function lerpPt(p1, p2, t) {
  return [p1[0] + (p2[0] - p1[0]) * t, p1[1] + (p2[1] - p1[1]) * t];
}

function distPt(p1, p2) {
  return Math.hypot(p2[0] - p1[0], p2[1] - p1[1]);
}

function offsetSeg(p1, p2, d) {
  let dx = p2[0] - p1[0];
  let dy = p2[1] - p1[1];
  let len = Math.hypot(dx, dy) || 1;
  let nx = -dy / len;
  let ny = dx / len;
  return [
    [p1[0] + nx * d, p1[1] + ny * d],
    [p2[0] + nx * d, p2[1] + ny * d]
  ];
}

function drawPoly(pts, curvature = 0) {
  if (!pts || pts.length < 3) return;
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
}

