    let ang = -45.6 + random(-8, 8);
    let len = random(120, 340);
    brush.line(
      x1,
      y1,
      x1 + len * Math.cos((ang * Math.PI) / 180),
      y1 + len * Math.sin((ang * Math.PI) / 180)
    );
  }
}

// =============================================================================
// 2. CRUSHED BOTTLE MESH DEFINITION
// =============================================================================
function buildBottleMesh() {
  // 11 axial stations (s from 228 at neck ring to 1500 at cropped petaloid base)
  // 7 lateral stations per ring (j = 0 is lower-left silhouette, j = 6 is upper-right silhouette)
  const rawStations = [
    // i = 0: Neck support flange base (s ~ 228)
    {
      s: [228, 222, 217, 215, 217, 222, 228],
      r: [-74, -50, -25, 0, 25, 50, 74],
      stress: [0.85, 0.75, 0.92, 0.80, 0.92, 0.75, 0.85]
    },
    // i = 1: Conical shoulder dome with radial stretch pleats (s ~ 318)
    {
      s: [324, 314, 305, 302, 308, 316, 326],
      r: [-184, -126, -62, 4, 68, 130, 186],
      stress: [0.88, 0.65, 0.90, 0.58, 0.88, 0.62, 0.90]
    },
    // i = 2: Upper shoulder bumper rib (s ~ 415)
    {
      s: [425, 412, 398, 404, 394, 410, 422],
      r: [-256, -178, -88, 12, 96, 182, 252],
      stress: [0.95, 0.78, 0.96, 0.72, 0.94, 0.76, 0.92]
    },
    // i = 3: Upper crush pinch & Yoshimura buckle (s ~ 520)
    {
      s: [534, 515, 528, 504, 522, 508, 528],
      r: [-198, -142, -52, 28, 114, 198, 274],
      stress: [1.0, 0.86, 1.0, 0.94, 0.82, 0.95, 1.0]
    },
    // i = 4: Warped Rib #1 & diagonal torsion ridge (s ~ 635)
    {
      s: [642, 622, 646, 628, 612, 636, 648],
      r: [-264, -182, -84, 18, 108, 162, 204],
      stress: [0.96, 0.92, 0.84, 1.0, 0.96, 0.88, 0.98]
    },
    // i = 5: Deep central waist crush (maximum compression zone, s ~ 750)
    {
      s: [762, 744, 730, 756, 738, 752, 766],
      r: [-212, -134, -36, 46, 126, 194, 258],
      stress: [0.98, 1.0, 0.92, 1.0, 0.95, 0.86, 0.94]
    },
    // i = 6: Warped Rib #2 & counter-buckle (s ~ 870)
    {
      s: [884, 868, 886, 858, 876, 862, 882],
      r: [-184, -118, -22, 64, 148, 218, 282],
      stress: [1.0, 0.88, 0.98, 0.90, 1.0, 0.84, 0.96]
    },
    // i = 7: Lower diamond crush basin (s ~ 995)
    {
      s: [1006, 988, 976, 1004, 984, 998, 1012],
      r: [-268, -186, -86, 14, 108, 184, 242],
      stress: [0.94, 0.96, 0.82, 0.98, 0.86, 0.94, 0.92]
    },
    // i = 8: Lower stiffening bumper rib above base (s ~ 1128)
    {
      s: [1138, 1122, 1110, 1118, 1108, 1124, 1140],
      r: [-278, -192, -94, 4, 98, 194, 284],
      stress: [0.90, 0.78, 0.92, 0.74, 0.92, 0.80, 0.90]
    },
    // i = 9: Upper petaloid molded base (cropped at bottom-right, s ~ 1280)
    {
      s: [1292, 1272, 1258, 1266, 1256, 1274, 1294],
      r: [-290, -198, -98, 0, 98, 198, 292],
      stress: [0.88, 0.94, 0.76, 0.92, 0.76, 0.94, 0.88]
    },
    // i = 10: Lower petaloid base feet extending off bottom-right edge (s ~ 1470)
    {
      s: [1480, 1455, 1440, 1448, 1440, 1455, 1480],
      r: [-276, -188, -92, 0, 92, 188, 276],
      stress: [0.85, 0.90, 0.80, 0.90, 0.80, 0.90, 0.85]
    }
  ];

  const V = [];
  const S = [];
  for (let i = 0; i < rawStations.length; i++) {
    let rowV = [];
    let rowS = [];
    for (let j = 0; j < 7; j++) {
      rowV.push(bottlePt(rawStations[i].s[j], rawStations[i].r[j]));
      rowS.push(rawStations[i].stress[j]);
    }
    V.push(rowV);
    S.push(rowS);
  }

  // Diagonal triangulation pattern per quad (i, j):
  // 0 = split V[i][j] -> V[i+1][j+1], 1 = split V[i][j+1] -> V[i+1][j]
  const diagPattern = [
    [0, 0, 0, 1, 1, 1], // i=0..1 (shoulder radial fan)
    [0, 1, 0, 1, 0, 1], // i=1..2 (shoulder to upper rib)
    [1, 0, 1, 0, 1, 0], // i=2..3 (upper crush diamond)
    [0, 1, 0, 0, 1, 0], // i=3..4 (torsion fold)
    [1, 0, 1, 1, 0, 1], // i=4..5 (central waist crush)
    [0, 1, 0, 1, 0, 1], // i=5..6 (counter-buckle)
    [1, 0, 1, 0, 1, 0], // i=6..7 (lower crush diamond)
    [0, 1, 0, 1, 0, 1], // i=7..8 (lower rib recovery)
    [0, 0, 1, 0, 1, 1], // i=8..9 (petaloid upper base)
    [1, 0, 1, 0, 1, 0]  // i=9..10 (petaloid lower base)
  ];

  // Assign sequence & extinction focus shift per facet so the bottle has rich variety
  const seqNames = ["HIGH_WARM", "BLOOM_GOLD", "SECOND_ORDER", "FIRST_ORDER", "VIOLET_WARM"];
  const facets = [];
  const creases = [];

  for (let i = 0; i < 10; i++) {
    for (let j = 0; j < 6; j++) {
      let p00 = V[i][j];
      let p10 = V[i][j + 1];
      let p01 = V[i + 1][j];
      let p11 = V[i + 1][j + 1];

      let s00 = S[i][j];
      let s10 = S[i][j + 1];
      let s01 = S[i + 1][j];
      let s11 = S[i + 1][j + 1];

      let split = diagPattern[i][j];

      // Choose sequence based on location (more FIRST_ORDER near edges, HIGH_WARM & SECOND_ORDER in crushed waist)
      let seqA, seqB;
      if (j === 0 || j === 5) {
        seqA = (i >= 2 && i <= 7) ? SEQS.BLOOM_GOLD : SEQS.FIRST_ORDER;
        seqB = (i >= 3 && i <= 6) ? SEQS.VIOLET_WARM : SEQS.FIRST_ORDER;
      } else if (i >= 2 && i <= 7) {
        seqA = ((i + j) % 3 === 0) ? SEQS.SECOND_ORDER : SEQS.HIGH_WARM;
        seqB = ((i + j) % 2 === 0) ? SEQS.BLOOM_GOLD : SEQS.VIOLET_WARM;
      } else {
        seqA = SEQS.BLOOM_GOLD;
        seqB = SEQS.HIGH_WARM;
      }

      if (split === 0) {
        facets.push({
          pts: [p00, p10, p11],
          vStress: [s00, s10, s11],
          eStress: [(s00 + s10) * 0.5, (s10 + s11) * 0.5, (s11 + s00) * 0.55],
          seq: seqA,
          focusShift: [0.05, 0.18, 0.05],
          row: i,
          col: j
        });
        facets.push({
          pts: [p00, p11, p01],
          vStress: [s00, s11, s01],
          eStress: [(s00 + s11) * 0.55, (s11 + s01) * 0.5, (s01 + s00) * 0.5],
          seq: seqB,
          focusShift: [0.06, 0.06, 0.16],
          row: i,
          col: j
        });
        creases.push({ a: p00, b: p11, stress: (s00 + s11) * 0.5, type: "diag" });
      } else {
        facets.push({
          pts: [p00, p10, p01],
          vStress: [s00, s10, s01],
          eStress: [(s00 + s10) * 0.5, (s10 + s01) * 0.55, (s01 + s00) * 0.5],
          seq: seqA,
          focusShift: [0.15, 0.05, 0.08],
          row: i,
          col: j
        });
        facets.push({
          pts: [p10, p11, p01],
          vStress: [s10, s11, s01],
          eStress: [(s10 + s11) * 0.5, (s11 + s01) * 0.5, (s01 + s10) * 0.55],
          seq: seqB,
          focusShift: [0.06, 0.16, 0.06],
          row: i,
          col: j
        });
        creases.push({ a: p10, b: p01, stress: (s10 + s01) * 0.5, type: "diag" });
      }

      // Horizontal and longitudinal edges
      if (i > 0) {
        creases.push({ a: p00, b: p10, stress: (s00 + s10) * 0.5, type: "ring", ring: i });
      }
      if (j > 0) {
        creases.push({ a: p00, b: p01, stress: (s00 + s01) * 0.5, type: "long", col: j });
      }
    }
  }

  return { V, S, facets, creases, rawStations };
}

