// =============================================================================
// 4. FRONT FACET ISOCHROMATIC WATERCOLOUR ZONES
// =============================================================================
function buildFacetContour(facet, t) {
  const [A, B, C] = facet.pts;
  const [sA, sB, sC] = facet.vStress;
  const [eAB, eBC, eCA] = facet.eStress;
  const [fA, fB, fC] = facet.focusShift;

  // Extinction focus F shifted away from high-stress vertices
  let wA = 1 / (0.35 + sA) + fA;
  let wB = 1 / (0.35 + sB) + fB;
  let wC = 1 / (0.35 + sC) + fC;
  let sumW = wA + wB + wC;
  wA /= sumW;
  wB /= sumW;
  wC /= sumW;

  const F = [
    A[0] * wA + B[0] * wB + C[0] * wC,
    A[1] * wA + B[1] * wB + C[1] * wC
  ];

  if (t <= 0.0001) {
    return [A, B, C];
  }

  const edges = [
    { P0: A, P1: B, v0: sA, v1: sB, eS: eAB },
    { P0: B, P1: C, v0: sB, v1: sC, eS: eBC },
    { P0: C, P1: A, v0: sC, v1: sA, eS: eCA }
  ];

  const sub = 6; // 6 segments per edge -> 18 points around loop
  const contour = [];

  for (let ei = 0; ei < 3; ei++) {
    let ed = edges[ei];
    for (let k = 0; k < sub; k++) {
      let u = k / sub;
      let Pm = lerpPt(ed.P0, ed.P1, u);

      // Smoothly vary exponent gamma(u): smaller at vertices (blooms wide in corners),
      // larger at edge midpoints (hugs the straight fold crease)
      let midFactor = Math.pow(Math.sin(u * Math.PI), 1.35);
      let vStressHere = (1 - u) * ed.v0 + u * ed.v1;
      let gammaCorner = 0.54 / (0.65 + 0.35 * vStressHere);
      let gammaEdge = 1.24 / (0.65 + 0.35 * ed.eS);
      let gamma = gammaCorner * (1 - midFactor) + gammaEdge * midFactor;

      let d = Math.pow(t, gamma);
      contour.push(lerpPt(Pm, F, d));
    }
  }

  return contour;
}

function drawFrontFacetBands(mesh) {
  const facets = mesh.facets;
  // 10 concentric band levels from t = 0 (outer crease triangle) to t = 0.88 (extinction core)
  const tLevels = [0.0, 0.085, 0.175, 0.27, 0.37, 0.475, 0.58, 0.69, 0.79, 0.885];

  for (let k = 0; k < tLevels.length; k++) {
    let t = tLevels[k];
    let batches = {};

    for (let f = 0; f < facets.length; f++) {
      let facet = facets[f];
      let seq = facet.seq;
      let col = seq[Math.min(k, seq.length - 1)];
      let poly = buildFacetContour(facet, t);
      if (!batches[col]) batches[col] = [];
      batches[col].push({ poly, curvature: k === 0 ? 0 : 0.12 });
    }

    // Use rich watercolor fill texture on prominent interior bands (k = 1..6)
    let useWatercolor = k >= 1 && k <= 6;
    let drawBorder = k >= 1 && k <= 8;

    let colorKeys = Object.keys(batches);
    for (let c = 0; c < colorKeys.length; c++) {
      let col = colorKeys[c];
      let items = batches[col];
      let lightCol = UNDER[col];
      let borderCol = EDGE_TONE[col] || "#111118";

      // Pass A: Opaque luminous under-wash so colors stay pure and glowing over black
      if (lightCol) {
        brush.noStroke();
        brush.noFill();
        brush.wash(lightCol, 236);
        for (let m = 0; m < items.length; m++) {
          drawPoly(items[m].poly, items[m].curvature);
        }
        brush.noWash();
      }

      // Pass B: Saturated wash + crisp watercolor fill with inward-only micro-bleed
      brush.noStroke();
      brush.wash(col, useWatercolor ? 192 : 246);
      if (useWatercolor && col !== PAL.EXT_BLACK && col !== PAL.GREY_VOID) {
        brush.fill(col, 155);
        brush.fillBleed(0.008, "in");
        brush.fillTexture(0.78, 0.88);
      } else {
        brush.noFill();
      }
      for (let m = 0; m < items.length; m++) {
        drawPoly(items[m].poly, items[m].curvature);
      }
      brush.noFill();
      brush.noWash();

      // Pass C: Razor-sharp watercolor boundary line
      if (drawBorder) {
        brush.set("rotring", borderCol, 0.16);
        for (let m = 0; m < items.length; m++) {
          drawPoly(items[m].poly, items[m].curvature);
        }
        brush.noStroke();
      }
    }
  }
}

// =============================================================================
// 5. WARPED CIRCUMFERENTIAL STIFFENING RIBS
// =============================================================================
function drawWarpedBottleRibs(mesh) {
  const V = mesh.V;
  // Rings 2, 4, 6, 8 are the molded horizontal stiffening grooves of the PET bottle
  const ribRings = [
    { row: 2, halfW: 9.5, cols: [PAL.VIOLET_ELEC, PAL.MAGENTA_VIVID, PAL.AMBER_GOLD, PAL.STRAW_YELLOW] },
    { row: 4, halfW: 11.0, cols: [PAL.CYAN_BRIGHT, PAL.VIOLET_ELEC, PAL.MAGENTA_VIVID, PAL.WARM_WHITE] },
    { row: 6, halfW: 11.0, cols: [PAL.VIOLET_ELEC, PAL.MAGENTA_VIVID, PAL.STRAW_YELLOW, PAL.WARM_WHITE] },
    { row: 8, halfW: 10.0, cols: [PAL.CYAN_BRIGHT, PAL.MAGENTA_VIVID, PAL.AMBER_GOLD, PAL.STRAW_YELLOW] }
  ];

  for (let r = 0; r < ribRings.length; r++) {
    let rib = ribRings[r];
    let rowPts = V[rib.row];

    // Draw 4 nested ribbon layers along the rib groove
    for (let b = 0; b < rib.cols.length; b++) {
      let col = rib.cols[b];
      let hw = rib.halfW * (1 - b * 0.23);
      let upper = [];
      let lower = [];

      for (let j = 0; j < rowPts.length; j++) {
        let p = rowPts[j];
        upper.push([p[0] - COS_A * hw, p[1] - SIN_A * hw]);
        lower.push([p[0] + COS_A * hw, p[1] + SIN_A * hw]);
      }

      let poly = upper.concat(lower.reverse());
      let lightCol = UNDER[col];

      brush.noStroke();
      brush.noFill();
      if (lightCol) {
        brush.wash(lightCol, 230);
        drawPoly(poly, 0.06);
      }
      brush.wash(col, 225);
      drawPoly(poly, 0.06);
      brush.noWash();

      brush.set("rotring", EDGE_TONE[col], 0.16);
      drawPoly(poly, 0.06);
      brush.noStroke();
    }
  }
}

// =============================================================================
// 6. HIGH-STRESS CREASE PLUMES & PINCH-VERTEX INTERFERENCE PETALS
// =============================================================================
function drawCreasePlumesAndVertices(mesh) {
  const V = mesh.V;
  const S = mesh.S;
  const creases = mesh.creases;

  // A. Lanceolate birefringent plumes straddling the sharpest diagonal & longitudinal folds
  const plumeLayers = [
    { scale: 1.0, col: PAL.VIOLET_ELEC },
    { scale: 0.72, col: PAL.MAGENTA_VIVID },
    { scale: 0.46, col: PAL.AMBER_GOLD },
    { scale: 0.24, col: PAL.WARM_WHITE }
  ];

  for (let l = 0; l < plumeLayers.length; l++) {
    let layer = plumeLayers[l];
    let col = layer.col;
    let lightCol = UNDER[col];
    let polys = [];

    for (let c = 0; c < creases.length; c++) {
      let cr = creases[c];
      if (cr.stress < 0.89 || cr.type === "ring") continue;

      let pA = cr.a;
      let pB = cr.b;
      let dx = pB[0] - pA[0];
      let dy = pB[1] - pA[1];
      let len = Math.hypot(dx, dy) || 1;
      let nx = -dy / len;
      let ny = dx / len;

      let maxW = (cr.stress - 0.75) * 34 * layer.scale;
      let p1 = lerpPt(pA, pB, 0.08);
      let p2 = lerpPt(pA, pB, 0.32);
      let p3 = lerpPt(pA, pB, 0.50);
      let p4 = lerpPt(pA, pB, 0.68);
      let p5 = lerpPt(pA, pB, 0.92);

      polys.push([
        p1,
        [p2[0] + nx * maxW * 0.72, p2[1] + ny * maxW * 0.72],
        [p3[0] + nx * maxW, p3[1] + ny * maxW],
        [p4[0] + nx * maxW * 0.72, p4[1] + ny * maxW * 0.72],
        p5,
        [p4[0] - nx * maxW * 0.72, p4[1] - ny * maxW * 0.72],
        [p3[0] - nx * maxW, p3[1] - ny * maxW],
        [p2[0] - nx * maxW * 0.72, p2[1] - ny * maxW * 0.72]
      ]);
    }

    brush.noStroke();
    brush.noFill();
    if (lightCol) {
      brush.wash(lightCol, 232);
      for (let p of polys) drawPoly(p, 0.15);
    }
    brush.wash(col, 225);
    for (let p of polys) drawPoly(p, 0.15);
    brush.noWash();

    brush.set("rotring", EDGE_TONE[col], 0.15);
    for (let p of polys) drawPoly(p, 0.15);
    brush.noStroke();
  }

  // B. Concentric multi-lobed stauroscopic interference rosettes at the high-stress knuckle vertices
  const vertexRings = [
    { rad: 24, col: PAL.CYAN_BRIGHT },
    { rad: 18, col: PAL.VIOLET_ELEC },
    { rad: 13, col: PAL.MAGENTA_VIVID },
    { rad: 8.5, col: PAL.STRAW_YELLOW },
    { rad: 4.5, col: PAL.WARM_WHITE }
  ];

  for (let r = 0; r < vertexRings.length; r++) {
    let ring = vertexRings[r];
    let col = ring.col;
    let lightCol = UNDER[col];
    let starPolys = [];

    for (let i = 2; i <= 8; i++) {
      for (let j = 1; j <= 5; j++) {
        if (S[i][j] < 0.90) continue;
        let center = V[i][j];
        let pts = [];
        let lobes = 4;
        for (let k = 0; k < lobes * 2; k++) {
          let ang = (k * 180) / lobes + AXIS_DEG + (i * 17 + j * 29);
          let rad = (k % 2 === 0 ? ring.rad * 1.35 : ring.rad * 0.48) * S[i][j];
          pts.push([
            center[0] + rad * Math.cos((ang * Math.PI) / 180),
            center[1] + rad * Math.sin((ang * Math.PI) / 180)
          ]);
        }
        starPolys.push(pts);
      }
    }

    brush.noStroke();
    brush.noFill();
    if (lightCol) {
      brush.wash(lightCol, 235);
      for (let p of starPolys) drawPoly(p, 0.12);
    }
    brush.wash(col, 230);
    for (let p of starPolys) drawPoly(p, 0.12);
    brush.noWash();
  }
}

// =============================================================================
// 7. THREADED NECK, TAMPER RING & TRANSLUCENT CAP ASSEMBLY
// =============================================================================
function drawNeckAndCapAssembly() {
  // --- A. NECK CYLINDER BASE (`s = 58..224`, `R = 58`) ---
  const neckCols = [
    PAL.GREY_1ST,
    PAL.STRAW_YELLOW,
    PAL.AMBER_GOLD,
    PAL.MAGENTA_VIVID,
    PAL.VIOLET_ELEC,
    PAL.CYAN_BRIGHT,
    PAL.STRAW_PALE,
    PAL.GREY_DARK
  ];

  for (let st = 0; st < 8; st++) {
    let phi0 = -90 + st * 22.5;
    let phi1 = phi0 + 22.5;
    let col = neckCols[st];
    let lightCol = UNDER[col];

    let strip = [
      cylPt(58, 57, phi0, 0.26),
      cylPt(58, 57, phi1, 0.26),
      cylPt(222, 60, phi1, 0.26),
      cylPt(222, 60, phi0, 0.26)
    ];

    brush.noStroke();
    brush.noFill();
    if (lightCol) {
      brush.wash(lightCol, 230);
      drawPoly(strip, 0);
    }
    brush.wash(col, 200);
    brush.fill(col, 150);
    brush.fillBleed(0.008, "in");
    brush.fillTexture(0.78, 0.88);
    drawPoly(strip, 0);
    brush.noFill();
    brush.noWash();
  }

  // --- B. REAR HALF-TURNS OF THE HELICAL NECK THREADS ---
  const threadStarts = [74, 110, 146];
  const pitch = 34;

  for (let t = 0; t < threadStarts.length; t++) {
    let s0 = threadStarts[t];
    let pts = [];
    for (let phi = 90; phi <= 270; phi += 15) {
      let sHelix = s0 + pitch * ((phi - 90) / 360);
      pts.push(cylPt(sHelix - 5, 62, phi, 0.26));
    }
    for (let phi = 270; phi >= 90; phi -= 15) {
      let sHelix = s0 + pitch * ((phi - 90) / 360);
      pts.push(cylPt(sHelix + 5, 62, phi, 0.26));
    }
    brush.noStroke();
    brush.noFill();
    brush.wash(PAL.VIOLET_INDIGO, 165);
    drawPoly(pts, 0.15);
    brush.noWash();
  }

  // --- C. FRONT HALF-TURNS OF THE HELICAL NECK THREADS (blooming with interference bands) ---
  const threadBandSeq = [
    { halfW: 9.5, rad: 64, col: PAL.CYAN_BRIGHT },
    { halfW: 7.4, rad: 65.5, col: PAL.VIOLET_ELEC },
    { halfW: 5.4, rad: 67, col: PAL.MAGENTA_VIVID },
    { halfW: 3.5, rad: 68, col: PAL.AMBER_GOLD },
    { halfW: 1.8, rad: 68.8, col: PAL.WARM_WHITE }
  ];

  for (let b = 0; b < threadBandSeq.length; b++) {
    let band = threadBandSeq[b];
    let col = band.col;
    let lightCol = UNDER[col];

    for (let t = 0; t < threadStarts.length; t++) {
      let s0 = threadStarts[t];
      let upper = [];
      let lower = [];
      for (let phi = -96; phi <= 96; phi += 12) {
        let sHelix = s0 + pitch * ((phi + 90) / 360);
        upper.push(cylPt(sHelix - band.halfW, band.rad, phi, 0.26));
        lower.push(cylPt(sHelix + band.halfW, band.rad, phi, 0.26));
      }
      let poly = upper.concat(lower.reverse());

      brush.noStroke();
      brush.noFill();
      if (lightCol) {
        brush.wash(lightCol, 238);
        drawPoly(poly, 0.12);
      }
      brush.wash(col, 232);
      drawPoly(poly, 0.12);
      brush.noWash();

      brush.set("rotring", EDGE_TONE[col], 0.16);
      drawPoly(poly, 0.12);
      brush.noStroke();
    }
  }

  // --- D. TAMPER-EVIDENT SECURITY RING (`s = 180..204`, `R = 66`) ---
  const tamperCols = [PAL.STRAW_YELLOW, PAL.MAGENTA_VIVID, PAL.VIOLET_ELEC, PAL.AMBER_GOLD, PAL.CYAN_BRIGHT];
  for (let k = 0; k < 10; k++) {
    let phi0 = -90 + k * 18;
    let phi1 = phi0 + 14;
    let col = tamperCols[k % tamperCols.length];
    let seg = [
      cylPt(181, 66, phi0, 0.26),
      cylPt(181, 66, phi1, 0.26),
      cylPt(203, 66, phi1, 0.26),
      cylPt(203, 66, phi0, 0.26)
    ];
    brush.noStroke();
    brush.noFill();
    brush.wash(UNDER[col], 235);
    drawPoly(seg, 0);
    brush.wash(col, 230);
    drawPoly(seg, 0);
    brush.noWash();
  }

  // --- E. NECK SUPPORT FLANGE / TRANSFER RING (`s = 212..228`, `R = 80`) ---
  const flangeBands = [
    { s0: 211, s1: 229, R: 82, col: PAL.CYAN_BRIGHT },
    { s0: 213, s1: 227, R: 79, col: PAL.VIOLET_ELEC },
    { s0: 215, s1: 225, R: 76, col: PAL.MAGENTA_VIVID },
    { s0: 217, s1: 223, R: 73, col: PAL.STRAW_YELLOW },
    { s0: 219, s1: 221, R: 70, col: PAL.WARM_WHITE }
  ];

  for (let fb of flangeBands) {
    let upper = [];
    let lower = [];
    for (let phi = -95; phi <= 95; phi += 12) {
      upper.push(cylPt(fb.s0, fb.R, phi, 0.26));
      lower.push(cylPt(fb.s1, fb.R, phi, 0.26));
    }
    let poly = upper.concat(lower.reverse());
    brush.noStroke();
    brush.noFill();
    brush.wash(UNDER[fb.col], 235);
    drawPoly(poly, 0.1);
    brush.wash(fb.col, 230);
    drawPoly(poly, 0.1);
    brush.noWash();
  }

  // --- F. TRANSLUCENT RIBBED SCREW CAP (`s = -34..60`, `R = 68`) ---
  // 14 vertical knurl flutes across the front of the cap
  const capFluteCols = [
    PAL.GREY_1ST,
    PAL.STRAW_YELLOW,
    PAL.AMBER_GOLD,
    PAL.MAGENTA_VIVID,
    PAL.VIOLET_ELEC,
    PAL.CYAN_BRIGHT,
    PAL.WARM_WHITE,
    PAL.STRAW_YELLOW,
    PAL.WARM_ORANGE,
    PAL.MAGENTA_VIVID,
    PAL.VIOLET_ELEC,
    PAL.STRAW_PALE,
    PAL.AMBER_GOLD,
    PAL.GREY_1ST
  ];

  for (let k = 0; k < 14; k++) {
    let phi0 = -90 + (k * 180) / 14;
    let phi1 = -90 + ((k + 1) * 180) / 14;
    let col = capFluteCols[k];
    let lightCol = UNDER[col];

    let flute = [
      cylPt(-28, 66, phi0, 0.29),
      cylPt(-28, 66, phi1, 0.29),
      cylPt(58, 69, phi1, 0.29),
      cylPt(58, 69, phi0, 0.29)
    ];

    brush.noStroke();
    brush.noFill();
    if (lightCol) {
      brush.wash(lightCol, 235);
      drawPoly(flute, 0);
    }
    brush.wash(col, 200);
    brush.fill(col, 150);
    brush.fillBleed(0.008, "in");
    brush.fillTexture(0.76, 0.86);
    drawPoly(flute, 0);
    brush.noFill();
    brush.noWash();
  }

  // Cap top elliptical dome (`s = -28`, `R = 65`) seen in oblique perspective
  const domeRings = [
    { R: 65, col: PAL.VIOLET_ELEC },
    { R: 54, col: PAL.MAGENTA_VIVID },
    { R: 43, col: PAL.AMBER_GOLD },
    { R: 31, col: PAL.STRAW_YELLOW },
    { R: 19, col: PAL.WARM_WHITE },
    { R: 9, col: PAL.GREY_DARK }
  ];

  for (let dr of domeRings) {
    let ell = [];
    for (let phi = 0; phi < 360; phi += 20) {
      ell.push(cylPt(-28, dr.R, phi, 0.29));
    }
    brush.noStroke();
    brush.noFill();
    if (UNDER[dr.col]) {
      brush.wash(UNDER[dr.col], 235);
      drawPoly(ell, 0.18);
    }
    brush.wash(dr.col, 228);
    drawPoly(ell, 0.18);
    brush.noWash();
  }
}

// =============================================================================
// 8. FINE WHITE PEN FACETS, CREASES, DOUBLE-WALL CONTOURS & SPECULAR DETAILS
// =============================================================================
function drawFineWhitePenWork(mesh) {
  const V = mesh.V;
  const S = mesh.S;
  const creases = mesh.creases;

  // --- A. REAR-WALL GHOST CREASES (translucent cool grey-white seen through the bottle) ---
  brush.set("rotring", "#8b96b0", 0.22);
  for (let s = 340; s <= 1140; s += 130) {
    let rearPts = [];
    for (let phi = 102; phi <= 258; phi += 18) {
      rearPts.push(cylPt(s, 215, phi, 0.22));
    }
    brush.spline(rearPts, 0.35);
  }

  // --- B. WARPED CIRCUMFERENTIAL RIB GROOVE LIPS (double parallel white pen lines) ---
  const ribRows = [2, 4, 6, 8];
  for (let rIdx of ribRows) {
    let rowPts = V[rIdx];
    for (let j = 0; j < 6; j++) {
      let pA = rowPts[j];
      let pB = rowPts[j + 1];
      let [uA, uB] = offsetSeg(pA, pB, -8.5);
      let [lA, lB] = offsetSeg(pA, pB, 8.5);
      let [mA, mB] = offsetSeg(pA, pB, -3.2);

      brush.set("rotring", "#ffffff", 0.36);
      brush.line(uA[0], uA[1], uB[0], uB[1]);
      brush.line(lA[0], lA[1], lB[0], lB[1]);

      brush.set("rotring", "#d4dff2", 0.20);
      brush.line(mA[0], mA[1], mB[0], mB[1]);
    }
  }

  // --- C. PRIMARY FACET CREASE NETWORK & PLASTIC WALL-THICKNESS BEVELS ---
  for (let c = 0; c < creases.length; c++) {
    let cr = creases[c];
    let pA = cr.a;
    let pB = cr.b;

    // Main sharp dihedral fold line
    let w = cr.stress > 0.90 ? 0.52 : 0.36;
    brush.set("rotring", "#ffffff", w);
    brush.line(pA[0], pA[1], pB[0], pB[1]);

    // Secondary parallel line (2.8 - 4.2 px offset) showing the physical thickness of the clear PET sheet
    let bevelDist = cr.type === "diag" ? 3.8 : 2.8;
    let [bA, bB] = offsetSeg(pA, pB, bevelDist);
    brush.set("rotring", "#dbe4f7", 0.22);
    brush.line(bA[0], bA[1], bB[0], bB[1]);

    // Third hairline inner refraction line on major diagonal buckles
    if (cr.type === "diag" && cr.stress > 0.88) {
      let [rA, rB] = offsetSeg(pA, pB, -3.2);
      brush.set("2H", "#fffae8", 0.20);
      brush.line(rA[0], rA[1], rB[0], rB[1]);
    }
  }

  // --- D. PINCH-VERTEX STRESS-WHITENING & MICRO-CRAZING TICKS ---
  for (let i = 1; i <= 9; i++) {
    for (let j = 1; j <= 5; j++) {
      let center = V[i][j];
      let st = S[i][j];
      if (st < 0.84) continue;

      // Small triangular stress-buckle facet right at the vertex knuckle
      let kPts = [
        [center[0] - 9, center[1] - 3],
        [center[0] + 4, center[1] - 10],
        [center[0] + 10, center[1] + 5],
        [center[0] - 3, center[1] + 9]
      ];
      brush.set("rotring", "#ffffff", 0.30);
      drawPoly(kPts, 0);

      // Fine radiating micro-crazing hatches at the sharpest knuckles
      brush.set("rotring", "#eef4ff", 0.20);
      for (let h = 0; h < 7; h++) {
        let ang = AXIS_DEG + h * 51 + (i * 19 + j * 31);
        let r0 = 4;
        let r1 = (14 + (h % 3) * 7) * st;
        brush.line(
          center[0] + r0 * Math.cos((ang * Math.PI) / 180),
          center[1] + r0 * Math.sin((ang * Math.PI) / 180),
          center[0] + r1 * Math.cos((ang * Math.PI) / 180),
          center[1] + r1 * Math.sin((ang * Math.PI) / 180)
        );
      }
    }
  }

  // --- E. OUTER SILHOUETTE DOUBLE-WALL CONTOUR (showing physical wall thickness of clear PET) ---
  for (let i = 0; i < 10; i++) {
    // Left silhouette (j = 0)
    let lA = V[i][0];
    let lB = V[i + 1][0];
    let [lInA, lInB] = offsetSeg(lA, lB, -4.8);
    brush.set("rotring", "#ffffff", 0.58);
    brush.line(lA[0], lA[1], lB[0], lB[1]);
    brush.set("rotring", "#dce6fa", 0.28);
    brush.line(lInA[0], lInA[1], lInB[0], lInB[1]);

    // Right silhouette (j = 6)
    let rA = V[i][6];
    let rB = V[i + 1][6];
    let [rInA, rInB] = offsetSeg(rA, rB, 4.8);
    brush.set("rotring", "#ffffff", 0.58);
    brush.line(rA[0], rA[1], rB[0], rB[1]);
    brush.set("rotring", "#dce6fa", 0.28);
    brush.line(rInA[0], rInA[1], rInB[0], rInB[1]);
  }

  // --- F. AXIAL STRETCH MARKS & PETALOID BASE FLUTES ---
  brush.set("rotring", "#d8e2f5", 0.20);
  for (let j = 1; j <= 5; j++) {
    // Shoulder stretch striations flowing down from neck flange (i = 0..2)
    let p0 = V[0][j];
    let p1 = V[1][j];
    let p2 = V[2][j];
    brush.spline([p0, p1, p2], 0.25);

    // Petaloid base molded valley grooves at bottom-right (i = 8..10)
    let b8 = V[8][j];
    let b9 = V[9][j];
    let b10 = V[10][j];
    let [b8L, b9L] = offsetSeg(b8, b9, -5);
    let [b8R, b9R] = offsetSeg(b8, b9, 5);
    brush.set("rotring", "#ffffff", 0.34);
    brush.line(b8L[0], b8L[1], b9L[0], b9L[1]);
    brush.line(b8R[0], b8R[1], b9R[0], b9R[1]);
    brush.line(b9[0], b9[1], b10[0], b10[1]);
  }

  // --- G. PRECISION WHITE PEN LINEWORK ON NECK, THREADS & CAP ---
  const threadStarts = [74, 110, 146];
  const pitch = 34;

  // Rear thread ghost lines
  brush.set("rotring", "#95a2bd", 0.20);
  for (let t = 0; t < threadStarts.length; t++) {
    let s0 = threadStarts[t];
    let pts = [];
    for (let phi = 95; phi <= 265; phi += 15) {
      let sHelix = s0 + pitch * ((phi - 90) / 360);
      pts.push(cylPt(sHelix, 62, phi, 0.26));
    }
    brush.spline(pts, 0.3);
  }

  // Front helical thread crest, upper flank & lower root lines
  for (let t = 0; t < threadStarts.length; t++) {
    let s0 = threadStarts[t];
    let crest = [];
    let upper = [];
    let lower = [];
    for (let phi = -96; phi <= 96; phi += 12) {
      let sHelix = s0 + pitch * ((phi + 90) / 360);
      crest.push(cylPt(sHelix, 69, phi, 0.26));
      upper.push(cylPt(sHelix - 7.5, 64, phi, 0.26));
      lower.push(cylPt(sHelix + 7.5, 64, phi, 0.26));
    }
    brush.set("rotring", "#ffffff", 0.50);
    brush.spline(crest, 0.35);
    brush.set("rotring", "#e0e9fa", 0.28);
    brush.spline(upper, 0.35);
    brush.spline(lower, 0.35);

    // Thread profile teeth on left (-96 deg) and right (+96 deg) neck silhouette
    let lTop = upper[0];
    let lCrest = crest[0];
    let lBot = lower[0];
    let rTop = upper[upper.length - 1];
    let rCrest = crest[crest.length - 1];
    let rBot = lower[lower.length - 1];

    brush.set("rotring", "#ffffff", 0.45);
    brush.line(lTop[0], lTop[1], lCrest[0], lCrest[1]);
    brush.line(lCrest[0], lCrest[1], lBot[0], lBot[1]);
    brush.line(rTop[0], rTop[1], rCrest[0], rCrest[1]);
    brush.line(rCrest[0], rCrest[1], rBot[0], rBot[1]);
  }

  // Neck vertical mold-parting seam & double wall silhouette
  let nL0 = cylPt(58, 58, -90, 0.26);
  let nL1 = cylPt(222, 60, -90, 0.26);
  let nR0 = cylPt(58, 58, 90, 0.26);
  let nR1 = cylPt(222, 60, 90, 0.26);
  let nLIn0 = cylPt(58, 51, -90, 0.26);
  let nLIn1 = cylPt(222, 53, -90, 0.26);
  let nRIn0 = cylPt(58, 51, 90, 0.26);
  let nRIn1 = cylPt(222, 53, 90, 0.26);

  brush.set("rotring", "#ffffff", 0.52);
  brush.line(nL0[0], nL0[1], nL1[0], nL1[1]);
  brush.line(nR0[0], nR0[1], nR1[0], nR1[1]);
  brush.set("rotring", "#d4e0f7", 0.26);
  brush.line(nLIn0[0], nLIn0[1], nLIn1[0], nLIn1[1]);
  brush.line(nRIn0[0], nRIn0[1], nRIn1[0], nRIn1[1]);

  // Tamper-evident security ring bridges & slits (`s = 180..204`)
  for (let sRing of [180, 204]) {
    let rPts = [];
    for (let phi = -95; phi <= 95; phi += 12) {
      rPts.push(cylPt(sRing, 67, phi, 0.26));
    }
    brush.set("rotring", "#ffffff", 0.38);
    brush.spline(rPts, 0.3);
  }
  brush.set("rotring", "#ffffff", 0.26);
  for (let k = 0; k <= 10; k++) {
    let phi = -90 + k * 18;
    let p0 = cylPt(175, 64, phi, 0.26);
    let p1 = cylPt(204, 67, phi, 0.26);
    brush.line(p0[0], p0[1], p1[0], p1[1]);
  }

  // Neck support flange (`s = 212..228`) double rim
  for (let sFlange of [211, 220, 229]) {
    let fPts = [];
    for (let phi = -96; phi <= 96; phi += 12) {
      fPts.push(cylPt(sFlange, 82, phi, 0.26));
    }
    brush.set("rotring", sFlange === 220 ? "#ffffff" : "#dce6fa", sFlange === 220 ? 0.50 : 0.30);
    brush.spline(fPts, 0.3);
  }

  // Cap vertical knurl ridges & elliptical top dome (`s = -28..58`)
  brush.set("rotring", "#ffffff", 0.28);
  for (let k = 0; k <= 14; k++) {
    let phi = -90 + (k * 180) / 14;
    let cTop = cylPt(-28, 66.5, phi, 0.29);
    let cBot = cylPt(58, 69.5, phi, 0.29);
    brush.line(cTop[0], cTop[1], cBot[0], cBot[1]);
  }

  for (let rad of [66.5, 55, 36, 16]) {
    let ell = [];
    for (let phi = 0; phi <= 360; phi += 15) {
      ell.push(cylPt(-28, rad, phi, 0.29));
    }
    brush.set("rotring", rad > 60 ? "#ffffff" : "#d8e2f7", rad > 60 ? 0.48 : 0.24);
    brush.spline(ell, 0.35);
  }

  // Cap lower skirt rim (`s = 58`)
  let skirtPts = [];
  for (let phi = -95; phi <= 95; phi += 12) {
    skirtPts.push(cylPt(58, 70, phi, 0.29));
  }
  brush.set("rotring", "#ffffff", 0.50);
  brush.spline(skirtPts, 0.35);
}

