async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(SEED);
  noiseSeed(SEED);

  // Custom fine acid-etching spray brush for frosted glass micro-grain
  brush.add("frost_grain", {
    type: "spray",
    weight: 14,
    scatter: 3.8,
    opacity: 22,
    spacing: 0.65,
    pressure: [0.6, 1.2, 0.6],
    noise: 0.9
  });

  // Custom ultra-fine dermal needle brush for papillary ridges and meniscus details
  brush.add("dermal_fine", {
    type: "default",
    weight: 0.42,
    scatter: 0.04,
    sharpness: 0.92,
    grain: 4,
    opacity: 165,
    spacing: 0.12,
    pressure: [0.4, 1.0, 0.35],
    noise: 0.25
  });

  // Custom soft vapor mist brush
  brush.add("vapor_mist", {
    type: "spray",
    weight: 28,
    scatter: 6.5,
    opacity: 14,
    spacing: 0.9,
    pressure: [0.4, 1.0, 0.4],
    noise: 1.0
  });

  // Gentle vertical-drift vector field for steamed glass atmosphere
  brush.addField("cold_glass", (t, field) => {
    for (let col = 0; col < field.length; col++) {
      for (let row = 0; row < field[0].length; row++) {
        let nx = col * 0.07;
        let ny = row * 0.07;
        field[col][row] = 88 + (noise(nx, ny, t) - 0.5) * 18;
      }
    }
    return field;
  });
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#dde8e4");

  // 1. Base atmospheric bathroom washes behind the frosted glass
  drawAtmosphericGround();

  // 2. Veiled silhouette and mass of the receding hand & palm behind glass
  drawVeiledHandAndPalm();

  // 3. Veiled toiletries on the shelf (Amber bottle, Tumbler, Toothbrush, Razor, Shelf)
  drawVeiledAmberBottle();
  drawVeiledTumblerAndToothbrush();
  drawVeiledRazor();
  drawVeiledGlassShelf();

  // 4. Acid-etched frosted glass veil (granular spray mist in celadon, milk white, diluted amber)
  drawAcidEtchedFrostVeil();

  // 5. Razor-sharp Focus #1: Flattened, blanched fingertips pressed against the glass
  drawPressedFingertips();

  // 6. Razor-sharp Focus #2: Condensation channels & beads carving clear paths through the frost
  drawCondensationChannelsAndBeads();

  // 7. Ambient micro-condensation & cold vignette finish
  drawMicroCondensationAndColdEdge();

  noLoop();
