// ============================================================================
// 5. RAZOR-SHARP FOCUS #1: FLATTENED, BLANCHED FINGERTIPS ON THE GLASS
// ============================================================================
function drawPressedFingertips() {
  for (let idx = 0; idx < FINGERS.length; idx++) {
    let f = FINGERS[idx];
    drawSinglePressedFingertip(f, idx);
  }
}

function drawSinglePressedFingertip(f, idx) {
  push();
  translate(f.cx, f.cy);
  rotate(f.angle);

  // 1. Outer optical moisture/warmth halo where skin meets cold acid-etched glass
  brush.noStroke();
  brush.fillBleed(0.22, "out");
  brush.fillTexture(0.25, 0.2);

  brush.fill("#9eb5ae", 72);
  drawRotatedOval(0, 4, f.rx * 1.48, f.ry * 1.44, 24);

  // 2. Distal finger contour just behind the flattened contact pad (semi-focused transition)
  brush.fill("#cfa098", 110);
  drawRotatedOval(0, 8, f.rx * 1.32, f.ry * 1.30, 24);

  // 3. Compressed capillary flush ring (blood pushed to the perimeter of the flattened pad)
  brush.fillBleed(0.12, "in");
  brush.fill("#cf766b", 155);
  drawRotatedOval(0, 0, f.rx * 1.14, f.ry * 1.12, 28);

  brush.fill("#de8c80", 165);
  drawRotatedOval(0, 0, f.rx * 1.04, f.ry * 1.03, 28);

  // 4. Blanched central contact pad (pressure forces blood out -> creamy ivory/parchment)
  brush.fillBleed(0.06, "in");
  brush.fill("#f5ded0", 210);
  drawRotatedOval(0, -1, f.rx * 0.90, f.ry * 0.89, 28);

  brush.fill("#fbf0e6", 220);
  drawRotatedOval(0, -2, f.rx * 0.74, f.ry * 0.74, 26);

  // Intense blanched pressure core
  brush.fill("#fff8f0", 170);
  drawRotatedOval(0, -4, f.rx * 0.48, f.ry * 0.50, 20);

  brush.noFill();

  // 5. Crisp optical contact boundary ring (skin oil wetting the frost edge)
  brush.set("2H", "#8b6b67", 0.45);
  drawOvalOutline(0, 0, f.rx * 1.06, f.ry * 1.05, 36);

  brush.set("dermal_fine", "#b86b60", 0.55);
  drawOvalOutline(0, 0, f.rx * 0.97, f.ry * 0.96, 36);

  // 6. Distal interphalangeal joint flexion creases at the base of the pad
  let creaseY = f.ry * 0.86;
  brush.set("dermal_fine", "#9e5c53", 0.58);
  brush.spline([
    [-f.rx * 0.78, creaseY - 4, 0.3],
    [-f.rx * 0.25, creaseY + 3, 0.9],
    [f.rx * 0.28, creaseY + 2, 0.9],
    [f.rx * 0.76, creaseY - 5, 0.3]
  ], 0.5);

  brush.set("dermal_fine", "#b87970", 0.42);
  brush.spline([
    [-f.rx * 0.65, creaseY + 5, 0.3],
    [0, creaseY + 9, 0.8],
    [f.rx * 0.62, creaseY + 4, 0.3]
  ], 0.5);

  // 7. Hyper-detailed friction ridges (dermatoglyphics) & sweat pores across the flattened pad
  drawFingerprintRidgesAndPores(f, idx);

  // 8. Tiny vapor micro-beads condensing right outside the warm finger margin
  brush.set("rotring", "#ffffff", 0.55);
  for (let a = 0; a < 360; a += 8) {
    if (random() < 0.65) {
      let rMult = random(1.08, 1.26);
      let mx = cos(a) * f.rx * rMult;
      let my = sin(a) * f.ry * rMult;
      brush.line(mx, my, mx + 0.8, my + 0.8);
    }
  }

  pop();
}

function drawFingerprintRidgesAndPores(f, idx) {
  let rx = f.rx * 0.93;
  let ry = f.ry * 0.92;
  let coreY = f.ry * 0.08;

  // Generate concentric papillary ridge paths tailored to finger type (whorl, loop, arch)
  let numRidges = 26;
  for (let r = 1; r <= numRidges; r++) {
    let normR = r / numRidges;
    // Choose ridge color: paler warm rose-taupe in the blanched center, deeper coral-rose at the flushed margin
    let ridgeCol = normR < 0.58 ? "#c99589" : (normR < 0.82 ? "#b8766a" : "#9e5a50");
    let ridgeWeight = normR < 0.65 ? 0.36 : 0.44;

    // Sample points along the papillary ridge contour
    let pts = [];
    let aStart = -162;
    let aEnd = 162;
    let stepA = 9;

    for (let a = aStart; a <= aEnd; a += stepA) {
      // Natural bifurcation / ridge breaks and pore gaps
      let radX = normR * rx;
      let radY = normR * ry;

      // Warp geometry to create authentic dermatoglyphic loop/whorl/arch flow
      let theta = a;
      if (f.type === "whorl") {
        theta += (1 - normR) * 28 * sin(a * 2);
      } else if (f.type === "loopL") {
        theta += (1 - normR) * 22;
      } else if (f.type === "loopR") {
        theta -= (1 - normR) * 22;
      }

      let px = sin(theta) * radX;
      let py = coreY - cos(theta) * radY;

      // Subtle arch pinch near the bottom of the pad
      if (py > coreY) {
        py = lerp(py, coreY + (py - coreY) * 0.72, 0.45);
      }

      // Clip strictly inside the flattened contact oval
      let insideCheck = (px * px) / (rx * rx) + (py * py) / (ry * ry);
      if (insideCheck <= 0.98) {
        pts.push([px, py, 0.75]);
      } else {
        if (pts.length >= 3) {
          drawRidgeSegmentWithPores(pts, ridgeCol, ridgeWeight);
        }
        pts = [];
      }

      // Occasional natural ridge termination / bifurcation
      if (pts.length >= 5 && random() < 0.14) {
        drawRidgeSegmentWithPores(pts, ridgeCol, ridgeWeight);
        pts = [];
      }
    }
    if (pts.length >= 3) {
      drawRidgeSegmentWithPores(pts, ridgeCol, ridgeWeight);
    }
  }

  // Fine white moisture/skin-crest highlights & crossing micro-creases on the pad
  brush.set("dermal_fine", "#fffcf7", 0.35);
  for (let k = 0; k < 7; k++) {
    let y1 = random(-ry * 0.55, ry * 0.55);
    let xSpan = rx * sqrt(max(0.05, 1 - (y1 * y1) / (ry * ry))) * 0.65;
    let x1 = random(-xSpan, 0);
    let x2 = random(0, xSpan);
    brush.line(x1, y1, x2, y1 + random(-8, 8));
  }
}

function drawRidgeSegmentWithPores(pts, col, w) {
  brush.set("dermal_fine", col, w);
  brush.spline(pts, 0.45);

  // Microscopic sweat pores (acrosyringia) dotting the crest of the papillary ridge
  brush.set("rotring", "#fffaf2", 0.42);
  for (let i = 1; i < pts.length - 1; i += 2) {
    if (random() < 0.55) {
      let p = pts[i];
      brush.line(p[0], p[1], p[0] + 0.45, p[1] + 0.45);
    }
  }
}

// ============================================================================
// 6. RAZOR-SHARP FOCUS #2: CONDENSATION CHANNELS & BEADS
// ============================================================================
function drawCondensationChannelsAndBeads() {
  for (let tr of CONDENSATION_TRACKS) {
    drawSingleCondensationTrack(tr);
  }

  // Additional isolated sharp condensation beads with short trailing tails
  const extraBeads = [
    { x: 228, y: 545, r: 7.5, tail: 38 },
    { x: 384, y: 635, r: 9.0, tail: 54 },
    { x: 425, y: 485, r: 6.5, tail: 32 },
    { x: 552, y: 515, r: 8.0, tail: 46 },
    { x: 758, y: 575, r: 8.5, tail: 52 },
    { x: 848, y: 670, r: 7.5, tail: 42 },
    { x: 1045, y: 595, r: 8.0, tail: 48 },
    { x: 308, y: 465, r: 6.5, tail: 28 }
  ];

  for (let b of extraBeads) {
    drawShortCondensationTail(b.x, b.y - b.tail, b.y, b.r * 0.65);
    drawSharpWaterBead(b.x, b.y, b.r);
  }
}

function drawSingleCondensationTrack(tr) {
  let stepY = 5;
  let path = [];

  for (let y = tr.y1; y <= tr.y2; y += stepY) {
    let t = (y - tr.y1) / (tr.y2 - tr.y1);
    // Natural surface-tension meander down the glass
    let meander =
      (noise(tr.seed, y * 0.012) - 0.5) * 18 +
      (noise(tr.seed + 50, y * 0.045) - 0.5) * 5;
    let cx = tr.x0 + meander;
    // Channel widens slightly as it gathers moisture on the way down, with slight pinch variations
    let w = lerp(tr.w0, tr.w1, pow(t, 0.75)) * (0.82 + 0.35 * noise(tr.seed + 100, y * 0.04));
    path.push({ x: cx, y: y, w: w });
  }

  // Carve the clear channel through the frost by rendering the sharp, un-frosted scene colors inside!
  for (let i = 0; i < path.length - 1; i++) {
    let p0 = path[i];
    let p1 = path[i + 1];

    // Sample un-diffused color behind the glass at left, center, and right of the cylindrical water lens
    let colCenter = getUnfrostedColorAt(p0.x, p0.y, 0);
    let colLeft = getUnfrostedColorAt(p0.x - p0.w * 0.35, p0.y, -12);
    let colRight = getUnfrostedColorAt(p0.x + p0.w * 0.35, p0.y, 12);

    // Paint crisp refracted interior strips
    brush.set("marker", colLeft, 0.55);
    brush.line(p0.x - p0.w * 0.25, p0.y, p1.x - p1.w * 0.25, p1.y);

    brush.set("marker", colRight, 0.55);
    brush.line(p0.x + p0.w * 0.25, p0.y, p1.x + p1.w * 0.25, p1.y);

    brush.set("marker", colCenter, 0.65);
    brush.line(p0.x, p0.y, p1.x, p1.y);
  }

  // Razor-sharp meniscus edges and specular highlights along the carved track
  for (let i = 0; i < path.length - 1; i++) {
    let p0 = path[i];
    let p1 = path[i + 1];
    let hw0 = p0.w * 0.5;
    let hw1 = p1.w * 0.5;

    // Dark outer meniscus refraction shadow cutting into the frost
    brush.set("rotring", "#4e6962", 0.52);
    brush.line(p0.x - hw0, p0.y, p1.x - hw1, p1.y);

    brush.set("rotring", "#637d76", 0.45);
    brush.line(p0.x + hw0, p0.y, p1.x + hw1, p1.y);

    // Bright specular ridge along the left inner meniscus
    if (i % 2 === 0) {
      brush.set("rotring", "#ffffff", 0.55);
      brush.line(p0.x - hw0 * 0.62, p0.y, p1.x - hw1 * 0.62, p1.y);
    }

    // Subtle secondary caustic glint on the right inner wall
    if (i % 3 === 0) {
      brush.set("2H", "#e6f5f0", 0.38);
      brush.line(p0.x + hw0 * 0.55, p0.y, p1.x + hw1 * 0.55, p1.y);
    }
  }

  // Occasional small residual satellite beads left inside the carved track
  for (let i = 6; i < path.length - 8; i += 14) {
    if (noise(tr.seed, i) > 0.48) {
      let pb = path[i];
      drawSharpWaterBead(pb.x, pb.y, pb.w * 0.46);
    }
  }

  // Plump terminal condensation bead at the bottom of the carved channel
  let last = path[path.length - 1];
  drawSharpWaterBead(last.x, last.y + tr.dropR * 0.35, tr.dropR);
}

function drawShortCondensationTail(x, y1, y2, halfW) {
  let step = 4;
  for (let y = y1; y < y2; y += step) {
    let t = (y - y1) / (y2 - y1);
    let w = lerp(1.5, halfW, t);
    let col = getUnfrostedColorAt(x, y, 0);
    brush.set("marker", col, 0.5);
    brush.line(x, y, x, y + step);

    brush.set("rotring", "#536e67", 0.42);
    brush.line(x - w, y, x - w, y + step);
    brush.line(x + w, y, x + w, y + step);

    brush.set("rotring", "#ffffff", 0.45);
    brush.line(x - w * 0.5, y, x - w * 0.5, y + step);
  }
}

function drawSharpWaterBead(cx, cy, r) {
  // 1. Cast shadow / dark meniscus beneath the bottom of the heavy droplet
  brush.noStroke();
  brush.wash("#3c544e", 155);
  drawTeardropBead(cx + 0.8, cy + r * 0.22, r * 0.98, r * 1.12);
  brush.noWash();

  // 2. Clear refracted interior of the bead (inverted/magnified lens sample of what is behind)
  let colUpper = getUnfrostedColorAt(cx, cy + r * 0.6, 15);
  let colCenter = getUnfrostedColorAt(cx, cy, 0);
  let colLower = getUnfrostedColorAt(cx, cy - r * 0.6, -15);

  brush.noStroke();
  brush.wash(colUpper, 225);
  drawTeardropBead(cx, cy, r * 0.95, r * 1.12);

  brush.wash(colCenter, 210);
  brush.circle(cx, cy + r * 0.1, r * 0.72, 0.05);

  brush.wash(colLower, 195);
  brush.circle(cx + r * 0.12, cy + r * 0.26, r * 0.48, 0.05);
  brush.noWash();

  // 3. Crisp dark outer rim where surface tension meets the etched glass
  brush.set("rotring", "#2f453f", 0.58);
  strokeTeardropBead(cx, cy, r * 0.96, r * 1.12);

  // 4. Secondary lower-right internal caustic reflection
  brush.set("dermal_fine", "#e8f7f3", 0.6);
  brush.arc(cx + r * 0.05, cy + r * 0.08, r * 0.68, 20, 88);

  // 5. Razor-sharp primary specular highlight on upper-left curvature
  brush.set("rotring", "#ffffff", 0.85);
  brush.arc(cx - r * 0.06, cy + r * 0.04, r * 0.70, 195, 258);

  brush.set("rotring", "#ffffff", 1.1);
  brush.line(
    cx - r * 0.48,
    cy - r * 0.36,
    cx - r * 0.34,
    cy - r * 0.54
  );
}

// ============================================================================
// DETERMINISTIC OPTICAL SCENE LOOKUP (UN-FROSTED REALITY BEHIND GLASS)
// ============================================================================
function getUnfrostedColorAt(x, y, refractX) {
  let sx = x + refractX;
  let sy = y;

  // 1. Check Glass Shelf (sharp emerald plate-glass edge)
  if (sy >= SHELF.y1 && sy <= SHELF.y2 && sx >= SHELF.x1 && sx <= SHELF.x2) {
    if (sy < SHELF.y1 + 6) return "#eefaf6";
    if (sy > SHELF.y2 - 7) return "#274d42";
    return "#48786a";
  }

  // 2. Check Amber Shampoo Bottle (vivid, rich un-diffused cognac & honey amber)
  if (sx >= BOTTLE.x1 && sx <= BOTTLE.x2 && sy >= BOTTLE.yTop && sy <= BOTTLE.yBot) {
    // Apothecary Cream Label
    if (sx >= BOTTLE.labelX1 && sx <= BOTTLE.labelX2 && sy >= BOTTLE.labelY1 && sy <= BOTTLE.labelY2) {
      // Crisp dark brown typography lines on the label
      if (abs(sy - 558) < 3.5 || abs(sy - 582) < 3.0 || abs(sy - 692) < 2.5) return "#3d2718";
      if (sy > 608 && sy < 672 && (int(sy) % 14 < 3) && sx > 235 && sx < 375) return "#543824";
      // Subtle warm border rule of label
      if (sx < BOTTLE.labelX1 + 6 || sx > BOTTLE.labelX2 - 6) return "#c79a63";
      return "#fcf6eb";
    }
    // Specular highlight down left side of amber glass
    if (sx >= 214 && sx <= 234) return "#f7c97e";
    // Deep cognac right edge & bottom meniscus
    if (sx > 368 || sy > 760) return "#7a3609";
    // Glowing golden liquid bottom-left
    if (sy > 705 && sx < 305) return "#e8942c";
    return "#b85c14";
  }

  // Bottle Neck & Pump
  if (sx >= BOTTLE.neckX1 && sx <= BOTTLE.neckX2 && sy >= BOTTLE.neckYTop && sy < BOTTLE.yTop) {
    return sx < 292 ? "#d97e26" : "#873e0a";
  }
  if (sx >= 268 && sx <= 382 && sy >= 282 && sy < BOTTLE.neckYTop) {
    return sy < 298 ? "#52463f" : "#2e2520";
  }

  // 3. Check Safety Razor on the shelf
  if (sx >= 456 && sx <= 648 && sy >= 738 && sy <= 786) {
    if (sx < 502) return sy < 758 ? "#f0f7fa" : "#4b6269";
    if (sy >= 756 && sy <= 784) return sy < 768 ? "#c2dce0" : "#58767d";
  }

  // 4. Check Toothbrush & Tumbler
  // Toothbrush diagonal shaft
  let tbT = (sy - 350) / (770 - 350);
  if (tbT >= 0 && tbT <= 1) {
    let tbX = lerp(1022, 860, tbT);
    if (abs(sx - tbX) < 11) {
      if (sy < 430) return "#f5faf8";
      return sx < tbX ? "#f0b5ab" : "#c76f63";
    }
  }
  // Tumbler glass
  if (sx >= TUMBLER.topX1 && sx <= TUMBLER.topX2 && sy >= TUMBLER.yTop && sy <= TUMBLER.yBot) {
    if (sy < TUMBLER.yTop + 8) return "#f2fafa";
    if (sy > TUMBLER.baseY) return "#6b939c";
    if (int(sx) % 24 < 5) return "#e1f0f2";
    return "#95b8bf";
  }

  // 5. Check Hand / Palm / Fingers behind the glass
  for (let f of FINGERS) {
    let d = dist(sx, sy, f.cx, f.cy);
    if (d < f.rx * 1.25) return "#e39e93";
  }
  if (dist(sx, sy, 610, 665) < 155) {
    return sx < 585 ? "#d9a59c" : "#bf877e";
  }

  // 6. Default un-frosted interior bathroom wall (cool celadon-slate shadow)
  if (sy > SHELF.y2 && sy < 880) return "#7f9c94";
  return sy < 450 ? "#cadbd5" : "#aec4bc";
}

// ============================================================================
// 7. AMBIENT MICRO-CONDENSATION & TACTILE COLD FINISH
// ============================================================================
function drawMicroCondensationAndColdEdge() {
  // Hundreds of tiny pinprick moisture glints scattered in the cold corners and around the shelf
  brush.set("rotring", "#ffffff", 0.48);
  for (let i = 0; i < 240; i++) {
    let x = random(25, 1175);
    let y = random(25, 1175);
    // Avoid drawing inside the pressed fingertip pads
    if (!isInsideAnyFingertip(x, y)) {
      brush.line(x, y, x + 0.9, y + 0.9);
    }
  }

  brush.set("2H", "#7c9991", 0.42);
  for (let i = 0; i < 180; i++) {
    let x = random(25, 1175);
    let y = random(25, 1175);
    if (!isInsideAnyFingertip(x, y)) {
      brush.line(x, y + 1.1, x + 0.9, y + 1.4);
    }
  }

  // Subtle cold edge mist around the perimeter of the window pane
  brush.noStroke();
  brush.fillBleed(0.45, "in");
  brush.fill("#b8ccc5", 45);
  brush.rect(600, 32, 1200, 64, "center");
  brush.rect(600, 1168, 1200, 64, "center");
  brush.noFill();
}

// ============================================================================
// GEOMETRY HELPERS
// ============================================================================
function isInsideAnyFingertip(x, y) {
  for (let f of FINGERS) {
    let dx = x - f.cx;
    let dy = y - f.cy;
    if ((dx * dx) / (f.rx * f.rx * 1.2) + (dy * dy) / (f.ry * f.ry * 1.2) <= 1) {
      return true;
    }
  }
  return false;
}

function drawRotatedOval(cx, cy, rx, ry, steps) {
  brush.beginShape(0.45);
  for (let i = 0; i < steps; i++) {
    let a = (i / steps) * 360;
    // Slight anatomical flattening at the tip and base of a pressed finger pad
    let rMod = 1 - 0.04 * cos(a * 2);
    brush.vertex(cx + cos(a) * rx * rMod, cy + sin(a) * ry * rMod);
  }
  brush.endShape( true );
}

function drawOvalOutline(cx, cy, rx, ry, steps) {
  let pts = [];
  for (let i = 0; i <= steps; i++) {
    let a = (i / steps) * 360;
    let rMod = 1 - 0.04 * cos(a * 2);
    pts.push([cx + cos(a) * rx * rMod, cy + sin(a) * ry * rMod, 0.7]);
  }
  brush.spline(pts, 0.45);
}

function drawSoftBlob(cx, cy, rx, ry, steps) {
  brush.beginShape(0.5);
  for (let i = 0; i < steps; i++) {
    let a = (i / steps) * 360;
    let n = 0.88 + 0.24 * noise(cx * 0.01 + cos(a), cy * 0.01 + sin(a));
    brush.vertex(cx + cos(a) * rx * n, cy + sin(a) * ry * n);
  }
  brush.endShape(true);
}

function drawCustomQuad(x1, y1, x2, y2, x3, y3, x4, y4) {
  brush.beginShape(0.15);
  brush.vertex(x1, y1);
  brush.vertex(x2, y2);
  brush.vertex(x3, y3);
  brush.vertex(x4, y4);
  brush.endShape(true);
}

function drawTeardropBead(cx, cy, rx, ry) {
  brush.beginShape(0.45);
  let steps = 18;
  for (let i = 0; i < steps; i++) {
    let a = (i / steps) * 360;
    // Teardrop profile: fuller and heavier at bottom (sin(a) > 0), slightly tapered at top
    let widthScale = 1 + 0.18 * sin(a);
    let px = cx + cos(a) * rx * widthScale;
    let py = cy + sin(a) * ry;
    brush.vertex(px, py);
  }
  brush.endShape(true);
}

function strokeTeardropBead(cx, cy, rx, ry) {
  let pts = [];
  let steps = 20;
  for (let i = 0; i <= steps; i++) {
    let a = (i / steps) * 360;
    let widthScale = 1 + 0.18 * sin(a);
    let px = cx + cos(a) * rx * widthScale;
    let py = cy + sin(a) * ry;
    pts.push([px, py, 0.8]);
  }
  brush.spline(pts, 0.45);
}

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  angleMode(DEGREES);
  brush.scaleBrushes(3);
  randomSeed(7391);
  noiseSeed(7391);

  // Custom brushes tailored for mechanical marker wedges, hyperreal micro-detail, and coarse grit
  brush.add("chisel_marker", {
    type: "marker",
    weight: 6,
    scatter: 0.04,
    opacity: 190,
    spacing: 0.35,
    pressure: [0.95, 1.0, 0.95],
    markerTip: false,
    noise: 0.15
  });

  brush.add("micro_needle", {
    type: "default",
    weight: 0.32,
    scatter: 0.02,
    sharpness: 0.92,
    grain: 0.25,
    opacity: 210,
    spacing: 0.4,
    pressure: [0.6, 1.1, 0.4],
    noise: 0.2
  });

  brush.add("brindle_rake", {
    type: "custom",
    weight: 2.2,
    scatter: 0.35,
    opacity: 145,
    spacing: 0.45,
    pressure: [0.3, 1.2, 0.2],
    tip: (_m) => {
      _m.rect(-2.0, -0.3, 1.2, 0.6);
      _m.rect(-0.2, -0.3, 1.4, 0.6);
      _m.rect(1.6, -0.3, 1.0, 0.6);
    },
    rotate: "natural",
    markerTip: false
  });

  brush.add("coarse_grit", {
    type: "spray",
    weight: 11,
    scatter: 3.8,
    opacity: 165,
    spacing: 1.4,
    pressure: [1.2, 0.7, 0.2],
    noise: 0.9
  });

  // Ballistic vector field curving from lower-left to upper-right
  brush.addField("ballistic_drive", (t, field) => {
    for (let col = 0; col < field.length; col++) {
      for (let row = 0; row < field[0].length; row++) {
        let nx = col / field.length;
        let ny = row / field[0].length;
        let baseAngle = -36 + nx * 16 + (ny - 0.5) * 10;
        let gritWave = sin(nx * 180 - ny * 120) * 3.5;
        field[col][row] = baseAngle + gritWave;
      }
    }
    return field;
  });
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#141821");

  // 1. Dusky twilight stadium & diagonal sand track atmosphere
  drawTwilightTrack();

  // 2. Background marker wedges & mechanical chronophotographic registration lines
  drawMarkerWedgesBack();

  // 3. Fractured & overlapping hindleg sequence (lower-left drive)
  drawFracturedHindlegs();

  // 4. Fractured & overlapping foreleg sequence (upper-right reach)
  drawFracturedForelegs();

  // 5. Midground marker wedges slicing through limbs and torso
  drawMarkerWedgesMid();

  // 6. Greyhound torso, deep chest, tucked loin, racing vest shards & curved brindle streaks
  drawTorsoAndBrindleStreaks();

  // 7. HYPERREAL FOCUS: Muscular neck, pinned ear, taut cheek, eye, jaws, and wet nose
  drawHyperrealNeckAndHead();

  // 8. Foreground marker wedges, charcoal force bundles & coarse arcs of kicked grit
  drawForceBundlesAndKickedGrit();

  noLoop();
}

// =============================================================================
// HELPERS FOR GEOMETRIC SHAPES & WEDGES
// =============================================================================
function drawSharpPoly(pts) {
  brush.beginShape(0);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
}

function drawWedge(pts, fillCol, fillAlpha, hatchCol, hatchDist, hatchAngle, borderCol, borderWeight) {
  brush.noField();
  if (fillCol) {
    brush.wash(fillCol, fillAlpha);
  } else {
    brush.noWash();
  }
  if (hatchCol) {
    brush.hatchStyle("rotring", hatchCol, 0.7);
    brush.hatch(hatchDist, hatchAngle, { rand: 0.03, gradient: 0.35 });
  } else {
    brush.noHatch();
  }
  if (borderCol) {
    brush.set("chisel_marker", borderCol, borderWeight || 0.7);
  } else {
    brush.noStroke();
  }
  drawSharpPoly(pts);
  brush.noWash();
  brush.noHatch();
  brush.noStroke();
}

// =============================================================================
// 1. DUSKY TWILIGHT SKY & DIAGONAL SAND TRACK
// =============================================================================
function drawTwilightTrack() {
  brush.noField();
  brush.noStroke();

  // Deep cold twilight sky plane (upper-left to mid-right)
  brush.wash("#18202c", 220);
  drawSharpPoly([[0, 0], [1200, 0], [1200, 520], [0, 960]]);

  // Secondary steel-slate atmospheric band
  brush.fill("#253042", 110);
  brush.fillBleed(0.35, "out");
  brush.fillTexture(0.55, 0.2);
  drawSharpPoly([[0, 320], [1200, 80], [1200, 660], [0, 1080]]);
  brush.noFill();

  // Dusky sand track plane driving diagonally
  brush.wash("#2a2320", 230);
  drawSharpPoly([[0, 830], [1200, 360], [1200, 1200], [0, 1200]]);

  // Warm umber & twilight ochre track compression zones
  brush.fill("#423328", 125);
  brush.fillBleed(0.28, "in");
  brush.fillTexture(0.65, 0.35);
  drawSharpPoly([[0, 910], [1200, 440], [1200, 980], [0, 1200]]);

  brush.fill("#5e4632", 90);
  drawSharpPoly([[0, 980], [880, 560], [1200, 620], [280, 1200], [0, 1200]]);
  brush.noFill();
  brush.noWash();

  // Diagonal track speed-scouring lines in cold steel, umber, and charcoal
  for (let i = 0; i < 65; i++) {
    let t = i / 65;
    let yLeft = 720 + t * 560 + random(-18, 18);
    let yRight = yLeft - 470 + random(-35, 35);
    let col = i % 4 === 0 ? "#4a586b" : i % 3 === 0 ? "#6b533e" : "#1c1817";
    let w = random(0.4, 1.5);
    brush.set(i % 2 === 0 ? "charcoal" : "2B", col, w);
    brush.line(0, yLeft, 1200, yRight);
  }

  // Chronophotographic vertical/diagonal timing grid lines in the dusky background
  for (let i = 0; i < 14; i++) {
    let xBase = 90 + i * 82;
    brush.set("rotring", i % 3 === 0 ? "#5e2524" : "#344154", 0.35);
    brush.line(xBase, 60, xBase - 140, 1140);
    // Small mechanical scale ticks
    for (let k = 0; k < 8; k++) {
      let ty = 140 + k * 120;
      let tx = xBase - (ty - 60) * (140 / 1080);
      brush.line(tx - 6, ty - 2, tx + 6, ty + 2);
    }
  }
}

