// =============================================================================
// 3. FRACTURED & OVERLAPPING HINDLEG POSITIONS (CHRONOPHOTOGRAPHIC DRIVE)
// =============================================================================
function drawSingleHindlegPhase(hipX, hipY, phaseT, alphaScale, isPrimary) {
  // phaseT from 0 (compressed forward under belly) to 1 (full violent extension back-left)
  let stifleX = hipX + lerp(35, -35, phaseT);
  let stifleY = hipY + lerp(95, 115, phaseT);

  let hockX = stifleX + lerp(-95, -155, phaseT);
  let hockY = stifleY + lerp(85, 125, phaseT);

  let pawX = hockX + lerp(20, -90, phaseT);
  let pawY = hockY + lerp(115, 130, phaseT);

  let thighBackX = hipX + lerp(-45, -85, phaseT);
  let thighBackY = hipY + lerp(40, 55, phaseT);

  let darkCol = isPrimary ? "#171414" : "#242933";
  let midCol = isPrimary ? "#6e533e" : "#485463";
  let highlightCol = isPrimary ? "#b89065" : "#7e8e9e";
  let accentRed = "#c9271e";

  // Thigh & Gaskin polygon
  let legPoly = [
    [hipX - 25, hipY - 15],
    [hipX + 42, hipY + 10],
    [stifleX + 24, stifleY],
    [hockX + 18, hockY - 8],
    [pawX + 14, pawY - 6],
    [pawX - 18, pawY + 6],
    [hockX - 16, hockY + 8],
    [thighBackX, thighBackY]
  ];

  brush.noField();
  brush.wash(midCol, floor(185 * alphaScale));
  brush.hatchStyle("2B", darkCol, 0.8);
  brush.hatch(isPrimary ? 4.5 : 6.5, -48 + phaseT * 25, { rand: 0.08, gradient: 0.4 });
  brush.set(isPrimary ? "charcoal" : "rotring", darkCol, isPrimary ? 1.1 : 0.7);
  drawSharpPoly(legPoly);
  brush.noWash();
  brush.noHatch();

  // Internal mechanical/anatomical bone vectors & tendon planes
  brush.set("rotring", isPrimary ? "#d99b38" : "#8fa1b5", 0.65);
  brush.line(hipX, hipY, stifleX, stifleY);
  brush.line(stifleX, stifleY, hockX, hockY);
  brush.line(hockX, hockY, pawX, pawY);

  // Calcaneal (Achilles) tendon taut line
  brush.set("pen", highlightCol, isPrimary ? 1.1 : 0.7);
  brush.line(thighBackX + 10, thighBackY + 15, hockX - 14, hockY + 4);
  brush.line(hockX - 14, hockY + 4, pawX - 10, pawY);

  // Joint registration circles & signal-red stress ticks
  if (!isPrimary || phaseT > 0.6) {
    brush.set("rotring", accentRed, 0.6);
    brush.circle(hockX, hockY, 9, 0.15);
    brush.circle(stifleX, stifleY, 11, 0.15);
  }

  // Brindle muscle striations across thigh
  if (isPrimary) {
    for (let s = 0; s < 16; s++) {
      let st = s / 15;
      let sx1 = lerp(hipX - 20, thighBackX, st);
      let sy1 = lerp(hipY, thighBackY + 25, st);
      let sx2 = lerp(hipX + 35, stifleX + 15, st);
      let sy2 = lerp(hipY + 15, stifleY + 5, st);
      brush.set("cpencil", s % 2 === 0 ? "#120f0f" : "#9e7750", 0.9);
      brush.spline([[sx1, sy1, 0.4], [(sx1 + sx2) * 0.5 + 8, (sy1 + sy2) * 0.5 - 6, 1.1], [sx2, sy2, 0.3]], 0.5);
    }
  }

  // Claws & digits tearing into the track
  for (let c = -1; c <= 1; c++) {
    brush.set("pen", "#0d0d12", 1.1);
    brush.line(pawX + c * 7, pawY, pawX + c * 9 + 18, pawY + 9);
    brush.set("rotring", "#d4c3b0", 0.6);
    brush.line(pawX + c * 9 + 14, pawY + 7, pawX + c * 9 + 25, pawY + 12);
  }
}

function drawFracturedHindlegs() {
  // 6 overlapping chronophotographic phases of the hindlimbs
  let phases = [
    { hx: 410, hy: 585, t: 0.12, a: 0.48, prim: false },
    { hx: 385, hy: 580, t: 0.32, a: 0.58, prim: false },
    { hx: 365, hy: 575, t: 0.52, a: 0.68, prim: false },
    { hx: 350, hy: 570, t: 0.72, a: 0.80, prim: false },
    { hx: 342, hy: 572, t: 0.88, a: 0.92, prim: true },  // Far primary hindleg
    { hx: 325, hy: 558, t: 1.02, a: 1.00, prim: true }   // Near primary hindleg at full stretch
  ];

  for (let p of phases) {
    drawSingleHindlegPhase(p.hx, p.hy, p.t, p.a, p.prim);
  }

  // Fractured whip-tail positions sweeping back from the croup (310, 555)
  let tailAngles = [0.0, 0.35, 0.7, 1.0];
  for (let i = 0; i < tailAngles.length; i++) {
    let ta = tailAngles[i];
    let isMain = i === 3;
    brush.set(isMain ? "charcoal" : "2B", isMain ? "#181515" : "#4b5869", isMain ? 1.8 : 0.9);
    let tPts = [
      [315, 552, 1.4],
      [230 - ta * 25, 595 + ta * 35, 1.1],
      [150 - ta * 35, 625 + ta * 70, 0.8],
      [85 - ta * 20, 610 + ta * 115, 0.3]
    ];
    brush.spline(tPts, 0.65);
    if (isMain) {
      brush.set("cpencil", "#9c7652", 1.0);
      brush.spline([
        [315, 556, 1.0],
        [228 - ta * 25, 600 + ta * 35, 0.9],
        [148 - ta * 35, 630 + ta * 70, 0.6]
      ], 0.65);
    }
  }
}

// =============================================================================
// 4. FRACTURED & OVERLAPPING FORELEG POSITIONS (UPPER-RIGHT REACH)
// =============================================================================
function drawSingleForelegPhase(shX, shY, phaseT, alphaScale, isPrimary) {
  // phaseT from 0 (swept back under chest) to 1 (hyper-extended forward reach)
  let elbowX = shX + lerp(-45, -18, phaseT);
  let elbowY = shY + lerp(78, 68, phaseT);

  let wristX = elbowX + lerp(-15, 195, phaseT);
  let wristY = elbowY + lerp(135, -32, phaseT);

  let pawX = wristX + lerp(12, 92, phaseT);
  let pawY = wristY + lerp(58, -14, phaseT);

  let darkCol = isPrimary ? "#161313" : "#262e3a";
  let midCol = isPrimary ? "#785a43" : "#4c5b6e";
  let lightCol = isPrimary ? "#cfa87e" : "#8ea0b5";

  let forePoly = [
    [shX - 22, shY - 12],
    [shX + 32, shY + 8],
    [elbowX + 26, elbowY - 6],
    [wristX + 8, wristY - 9],
    [pawX + 18, pawY - 6],
    [pawX - 6, pawY + 12],
    [wristX - 10, wristY + 10],
    [elbowX - 24, elbowY + 14]
  ];

  brush.noField();
  brush.wash(midCol, floor(180 * alphaScale));
  brush.hatchStyle("2B", darkCol, 0.75);
  brush.hatch(isPrimary ? 4.5 : 6.5, -18 + phaseT * 12, { rand: 0.06, gradient: 0.35 });
  brush.set(isPrimary ? "charcoal" : "rotring", darkCol, isPrimary ? 1.05 : 0.65);
  drawSharpPoly(forePoly);
  brush.noWash();
  brush.noHatch();

  // Sharp highlight along dorsal edge of outstretched forearm
  brush.set("cpencil", lightCol, isPrimary ? 1.1 : 0.7);
  brush.line(elbowX + 20, elbowY - 6, wristX + 6, wristY - 8);
  brush.line(wristX + 6, wristY - 8, pawX + 14, pawY - 5);

  // Tendon & bone axis lines
  brush.set("rotring", isPrimary ? "#e03428" : "#7b8ea3", 0.55);
  brush.line(shX, shY, elbowX, elbowY);
  brush.line(elbowX, elbowY, wristX, wristY);
  brush.line(wristX, wristY, pawX, pawY);

  // Carpal joint & outreaching knuckles/claws
  brush.set("rotring", "#d99226", 0.5);
  brush.circle(wristX, wristY, 8, 0.12);

  for (let c = -1; c <= 1; c++) {
    brush.set("pen", "#121012", 1.15);
    brush.line(pawX, pawY + c * 5, pawX + 22, pawY + c * 6 - 3);
    // Razor-sharp claws slicing forward
    brush.set("rotring", "#e6d8c5", 0.65);
    brush.line(pawX + 18, pawY + c * 6 - 2, pawX + 31, pawY + c * 6 - 5);
  }
}

