// =============================================================================
// 6. TORSO, DEEP CHEST, RACING JACKET SHARDS & CURVED BRINDLE STREAKS
// =============================================================================
function drawTorsoAndBrindleStreaks() {
  brush.noField();

  // Main aerodynamic torso silhouette: pelvis -> arched loin -> withers -> neck base -> deep brisket -> tucked flank
  let torsoPoly = [
    [310, 552], // Croup / pelvis tip
    [395, 505], // Lumbar arch
    [495, 468], // Mid spine
    [605, 438], // Thoracic spine
    [705, 405], // Withers / top of shoulder
    [775, 482], // Front of chest / prosternum
    [695, 558], // Deepest keel of sternum/brisket
    [590, 568], // Posterior sternum
    [495, 535], // Tucked-up abdomen / flank
    [415, 542], // Inguinal tuck
    [340, 588]  // Ischial tuberosity / hip
  ];

  // Base warm brindle-ochre & twilight-umber body wash
  brush.wash("#6b4f3a", 230);
  brush.hatchStyle("cpencil", "#2b1f18", 0.9);
  brush.hatch(4.0, -26, { rand: 0.08, gradient: 0.25 });
  brush.set("charcoal", "#171313", 1.2);
  drawSharpPoly(torsoPoly);
  brush.noWash();
  brush.noHatch();

  // Deep shadow under the brisket & ribcage keel
  brush.wash("#1f1918", 210);
  drawSharpPoly([
    [560, 520], [755, 470], [775, 482], [695, 558], [590, 568], [495, 535]
  ]);

  // Cool twilight sky reflection along the dorsal spine, loin, and croup
  brush.wash("#7a8c9e", 145);
  drawSharpPoly([
    [310, 552], [395, 505], [495, 468], [605, 438], [705, 405],
    [695, 428], [590, 460], [485, 492], [385, 528]
  ]);
  brush.noWash();

  // Fractured Racing Number Jacket Shards (Signal Red & Stark Steel White) over ribcage/shoulder
  drawWedge(
    [[545, 452], [685, 408], [722, 488], [585, 522]],
    "#d4241c", 225, "#6e0d09", 4.5, -24, "#ff4a40", 0.85
  );
  drawWedge(
    [[595, 442], [665, 420], [688, 472], [615, 494]],
    "#dde4ed", 220, "#8596ab", 5, 65, "#1a1f29", 0.8
  );
  // Geometric "7" / mechanical racing cipher inside jacket shard
  brush.set("chisel_marker", "#141820", 1.1);
  brush.line(612, 448, 654, 434);
  brush.line(654, 434, 635, 482);

  // Ribcage & Intercostal Serratus Planes
  for (let r = 0; r < 8; r++) {
    let rx = 490 + r * 24;
    let ryTop = 472 - r * 6;
    let ryBot = 538 + sin(r * 25) * 18;
    brush.set("2B", r % 2 === 0 ? "#1a1514" : "#9c7550", 0.85);
    brush.spline([
      [rx, ryTop, 0.4],
      [rx + 14, (ryTop + ryBot) * 0.5, 1.2],
      [rx - 8, ryBot, 0.4]
    ], 0.55);
  }

  // PARALLEL CURVED BRINDLE STREAKS:
  // Streaking the coat into dense, percussive parallel momentum lines curving along the body
  let streakColors = [
    "#120e0e", "#1f1816", "#332620", "#8c6542",
    "#b88958", "#d9a66c", "#6c7d8f", "#242c38"
  ];

  for (let i = 0; i < 135; i++) {
    let v = i / 134; // 0 = dorsal spine, 1 = ventral belly/chest
    let startX = lerp(260, 340, v) + random(-35, 25);
    let startY = lerp(545, 605, v) + random(-8, 8);

    let mid1X = lerp(430, 480, v) + random(-15, 15);
    let mid1Y = lerp(480, 545, v) + random(-6, 6);

    let mid2X = lerp(590, 645, v) + random(-15, 15);
    let mid2Y = lerp(440, 558, v) + random(-6, 6);

    let endX = lerp(725, 775, v) + random(-15, 25);
    let endY = lerp(400, 505, v) + random(-6, 6);

    // Alternating dark brindle tiger stripes and sunlit ochre/steel fur streaks
    let bandNoise = sin(i * 28 + noise(i * 0.15) * 90);
    let col;
    if (bandNoise > 0.25) {
      col = i % 2 === 0 ? "#110e0e" : "#261d1a";
    } else if (bandNoise < -0.35) {
      col = v < 0.28 ? "#95a8bd" : "#d4a26a";
    } else {
      col = streakColors[i % streakColors.length];
    }

    let bName = i % 4 === 0 ? "brindle_rake" : i % 2 === 0 ? "cpencil" : "charcoal";
    let w = i % 4 === 0 ? 0.85 : random(0.6, 1.25);
    brush.set(bName, col, w);
    brush.spline([
      [startX, startY, 0.3],
      [mid1X, mid1Y, 1.1],
      [mid2X, mid2Y, 1.2],
      [endX, endY, 0.5]
    ], 0.55);
  }

  // Scapula & Deltoid muscular definition at the shoulder transition (660, 420) - (765, 495)
  for (let s = 0; s < 28; s++) {
    let st = s / 27;
    let sx1 = lerp(655, 715, st);
    let sy1 = lerp(418, 405, st);
    let sx2 = lerp(695, 772, st);
    let sy2 = lerp(515, 482, st);
    let isDark = sin(s * 42) > 0;
    brush.set("cpencil", isDark ? "#171313" : "#c79a67", 0.85);
    brush.spline([
      [sx1, sy1, 0.5],
      [(sx1 + sx2) * 0.5 + 12, (sy1 + sy2) * 0.5 - 8, 1.2],
      [sx2, sy2, 0.4]
    ], 0.5);
  }
}

