  brush.wash("#755842", 240);
  drawSharpPoly(neckPoly);

  // Dorsal neck cold skylight plane
  brush.wash("#8799ad", 155);
  drawSharpPoly([
    [695, 408], [755, 355], [818, 312],
    [832, 332], [770, 376], [712, 428]
  ]);

  // Deep jugular furrow & sternocephalicus muscle belly shadow
  brush.wash("#241b18", 215);
  drawSharpPoly([
    [725, 452], [835, 362], [860, 376], [748, 474]
  ]);
  brush.noWash();

  // Dense micro-fur & brindle striations along the neck muscles
