  for (let a = 0; a < 360; a += 18) {
    let irx1 = 907 + cos(a) * 3.5;
    let iry1 = 308.5 + sin(a) * 3.5;
    let irx2 = 907 + cos(a) * 8.2;
    let iry2 = 308.5 + sin(a) * 7.5;
