  // Velvet-black pupil focused forward-right & dark limbal ring
  brush.wash("#050508", 255);
  drawSharpPoly([
    [904, 305], [909, 303], [913, 307], [912, 312], [907, 313], [903, 309]
  ]);
  brush.noWash();

  // Dark palpebral eyelid rims & medial tear caruncle (924, 307)
  brush.set("pen", "#07070a", 1.15);
  brush.spline([[885, 312, 0.9], [898, 299, 1.3], [914, 299, 1.2], [924, 307, 1.0]], 0.5);
  brush.spline([[885, 312, 0.9], [899, 319, 1.1], [913, 318, 1.1], [924, 307, 1.0]], 0.5);

  // Crisp upper eyelid fold & lower orbital rim highlight
  brush.set("micro_needle", "#120d0d", 1.0);
  brush.spline([[882, 307, 0.7], [898, 294, 1.2], [917, 295, 1.0], [926, 304, 0.7]], 0.5);
