// =============================================================================
// 8. FOREGROUND MARKER WEDGES, CHARCOAL FORCE BUNDLES & KICKED GRIT ARCS
// =============================================================================
function drawForceBundlesAndKickedGrit() {
  brush.noField();

  // Sharp foreground marker wedges slicing across the lower track and behind the dog
  drawWedge(
    [[20, 1020], [460, 740], [478, 768], [45, 1055]],
    "#e02b22", 225, null, 0, 0, "#ff5c52", 0.85
  );
  drawWedge(
    [[310, 910], [860, 590], [885, 625], [340, 950]],
    "#6b7e94", 205, "#1d242e", 5.5, -30, "#a3b7cc", 0.8
  );
  drawWedge(
    [[480, 740], [960, 495], [975, 518], [495, 765]],
    "#e09b2b", 210, "#593804", 5, -27, "#ffd06b", 0.75
  );

  // BUNDLES OF CHARCOAL FORCE LINES:
  // Percussive, combative sheaves of straight & slightly curved charcoal lines slicing the composition
  let bundles = [
    { x1: 20, y1: 1060, x2: 720, y2: 590, count: 22, spread: 42, col1: "#0d0f14", col2: "#3b4654" },
    { x1: 110, y1: 820, x2: 780, y2: 410, count: 18, spread: 34, col1: "#141112", col2: "#c9271e" },
    { x1: 420, y1: 680, x2: 1170, y2: 350, count: 20, spread: 38, col1: "#0f1218", col2: "#d48e24" },
    { x1: 180, y1: 640, x2: 720, y2: 360, count: 15, spread: 28, col1: "#171a21", col2: "#7d8fa3" }
  ];

  for (let b of bundles) {
    for (let i = 0; i < b.count; i++) {
      let off1 = random(-b.spread, b.spread);
      let off2 = off1 * random(0.4, 1.15) + random(-10, 10);
      let sx = b.x1 + random(-35, 35);
      let sy = b.y1 + off1;
      let ex = b.x2 + random(-35, 35);
      let ey = b.y2 + off2;

      let isAccent = i % 6 === 0;
      let col = isAccent ? b.col2 : b.col1;
      let bType = i % 3 === 0 ? "charcoal" : i % 2 === 0 ? "2B" : "rotring";
      let w = bType === "charcoal" ? random(0.9, 1.8) : random(0.45, 1.0);

      brush.set(bType, col, w);
      brush.spline([
        [sx, sy, 0.4],
        [(sx + ex) * 0.5, (sy + ey) * 0.5 - 12, 1.2],
        [ex, ey, 0.3]
      ], 0.35);
    }
  }

  // COARSE ARCS OF KICKED GRIT & BALLISTIC SAND DEBRIS:
  // Activated along the custom vector field and parabolic arcs from the paw strikes
  brush.field("ballistic_drive");
  let gritColors = ["#141110", "#2e241e", "#6e533b", "#b88a56", "#d9bc9c", "#6c7d91", "#d42b22"];

  for (let g = 0; g < 95; g++) {
    let gx = random(30, 880);
    let gy = 1060 - (gx / 880) * 520 + random(-95, 130);
    let gCol = gritColors[g % gritColors.length];
    brush.set(g % 3 === 0 ? "coarse_grit" : "spray", gCol, random(0.7, 1.6));
    brush.flowLine(gx, gy, random(45, 160), random(-42, -16));
  }
  brush.noField();

  // Sharp angular sand clods, flying pebbles, and percussive grit ticks along parabolic arcs
  let strikeOrigins = [
    [115, 995], [195, 945], [275, 885], [355, 815], [610, 745], [735, 675]
  ];

  for (let orig of strikeOrigins) {
    let ox = orig[0];
    let oy = orig[1];
    for (let p = 0; p < 36; p++) {
      let dist = random(15, 320);
      let ang = random(-172, -118); // Thrown violently backward & upward
      let gx = ox + cos(ang) * dist;
      let gy = oy + sin(ang) * dist + (dist * dist) * 0.0009; // Gravity drop

      let col = gritColors[p % gritColors.length];
      if (p % 4 === 0) {
        // Hard angular clod of track dirt
        brush.wash(col, 225);
        brush.noStroke();
        let sz = random(3, 9);
        drawSharpPoly([
          [gx, gy],
          [gx + sz, gy - sz * 0.6],
          [gx + sz * 0.7, gy + sz * 0.8],
          [gx - sz * 0.5, gy + sz * 0.4]
        ]);
        brush.noWash();
      } else {
        // Ballistic grit streak
        brush.set(p % 2 === 0 ? "charcoal" : "pen", col, random(0.6, 1.5));
        brush.line(gx, gy, gx + random(8, 24), gy - random(4, 14));
      }
    }
  }
}

