// ============================================================================
// GEOMETRY & DRAWING HELPERS
// ============================================================================

function drawPolyFill(pts, col, opacity, bleed = 0.04, tex = 0.25) {
  brush.noStroke();
  brush.noHatch();
  brush.noMass();
  brush.fill(col, opacity);
  brush.fillBleed(bleed, "out");
  brush.fillTexture(tex, 0.2);
  brush.beginShape(0);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
  brush.noFill();
}

function drawPolyWash(pts, col, opacity) {
  brush.noStroke();
  brush.noHatch();
  brush.noMass();
  brush. noFill();
  brush.wash(col, opacity);
  brush.beginShape(0);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
  brush.noWash();
}

function drawPolyStroke(pts, closeShape = true) {
  brush.beginShape(0);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(closeShape);
}

function getSpandrelPoints(cornerX, cornerY, sx, sy, size, steps = 28) {
  // Creates a stately scalloped carpet spandrel polygon in one corner of the inner field
  let pts = [[cornerX, cornerY]];
  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let ang = t * 90;
    // Carpet ogee / scalloped profile connecting (cornerX + sx*size, cornerY) to (cornerX, cornerY + sy*size)
    let baseR = size * (1 - 0.14 * sin(ang * 2) - 0.04 * cos(ang * 6));
    let px = cornerX + sx * (size - baseR * cos(ang) * 0.42) * (1 - t) + sx * ( baseR * cos(ang) ) * t;
    // Simpler exact Quarter-Medallion concave/scalloped arch:
    let u = cos(ang);
    let v = sin(ang);
    let scallop = 1.0 - 0.08 * sin(ang * 4) - 0.03 * abs(sin(ang * 8));
    let r = size * scallop;
    let x = cornerX + sx * r * u;
    let y = cornerY + sy * r * v;
    pts.push([x, y]);
  }
  return pts;
}

// ============================================================================
// 1. OUTER SAND & TOWEL FRINGES
// ============================================================================

function drawOuterSandAndFringes() {
  // Subtle dry sand washes around the outer margin
  brush.noStroke();
  brush.fill(PAL.sandWarm, 65);
  brush.fillBleed(0.15, "out");
  brush.fillTexture(0.35, 0.15);
  brush.rect(0, 0, 1200, 74, "corner");
  brush.rect(0, 1126, 1200, 74, "corner");
  brush.rect(0, 74, 74, 1052, "corner");
  brush.rect(1126, 74, 74, 1052, "corner");
  brush.noFill();

  // High-contrast cast shadow of the thick towel edge around (72, 72, 1056, 1056)
  drawPolyWash([[76, 1128], [1134, 1128], [1134, 1138], [76, 1138]], PAL.sandShadow, 170);
  drawPolyWash([[1128, 76], [1138, 76], [1138, 1138], [1128, 1138]], PAL.sandShadow, 170);

  // Stippled sand grains in the outer margin
  brush.set("spray", PAL.sandDark, 0.8);
  for (let i = 0; i < 36; i++) {
    let pos = i / 36 * 1140 + 30;
    brush.line(pos, 22, pos + 15, 25);
    brush.line(pos, 1172, pos + 15, 1175);
    brush.line(22, pos, 25, pos + 15);
    brush.line(1172, pos, 1175, pos + 15);
  }

  // Symmetrical knotted cotton towel fringes along top (y=72 -> 18) and bottom (y=1128 -> 1182)
  // Plus shorter knotted fringes along left and right edges for a complete carpet-medallion frame
  drawFringeBank(74, 1126, 72, -1, true);   // Top fringes
  drawFringeBank(74, 1126, 1128, 1, true);  // Bottom fringes
  drawFringeBank(74, 1126, 72, -1, false);  // Left fringes
  drawFringeBank(74, 1126, 1128, 1, false); // Right fringes
}

function drawFringeBank(startPos, endPos, edgeCoord, dir, isHorizontal) {
  let step = 9;
  let count = floor((endPos - startPos) / step);

  for (let i = 0; i <= count; i++) {
    let p = startPos + i * step;
    let len = isHorizontal ? random(38, 50) : random(24, 34);
    let sway = sin(i * 17) * 3.5 + random(-2, 2);

    // Determine stripe color alignment so fringe knots echo the border stripes
    let isDarkKnot = (i % 8 === 0 || i % 8 === 4);
    let knotCol = isDarkKnot ? PAL.indigo : PAL.cream;

    let x0 = isHorizontal ? p : edgeCoord;
    let y0 = isHorizontal ? edgeCoord : p;
    let xMid = isHorizontal ? p + sway * 0.4 : edgeCoord + dir * len * 0.45;
    let yMid = isHorizontal ? edgeCoord + dir * len * 0.45 : p + sway * 0.4;
    let x1 = isHorizontal ? p + sway : edgeCoord + dir * len;
    let y1 = isHorizontal ? edgeCoord + dir * len : p + sway;

    // Cast shadow of fringe cord on dry sand
    brush.set("rotring", PAL.sandShadow, 0.9);
    brush.spline([[x0 + 2.5, y0 + 2.5], [xMid + 3, yMid + 3], [x1 + 3.5, y1 + 3.5]], 0.4);

    // Cream cotton cord body
    brush.set("cpencil", PAL.creamShade, 1.3);
    brush.spline([[x0, y0], [xMid, yMid], [x1, y1]], 0.4);
    brush.set("pen", PAL.cream, 0.9);
    brush.spline([[x0, y0], [xMid, yMid], [x1, y1]], 0.4);

    // Frayed splayed tip threads (3 micro strands per tassel cord)
    brush.set("2H", PAL.inkSoft, 0.4);
    for (let s = -1; s <= 1; s++) {
      let fx = isHorizontal ? x1 + s * 2.4 + random(-1, 1) : x1 + dir * random(4, 9);
      let fy = isHorizontal ? y1 + dir * random(4, 9) : y1 + s * 2.4 + random(-1, 1);
      brush.line(x1, y1, fx, fy);
    }

    // Macramé diamond lattice & knot at base of fringe
    if (i < count) {
      let nx = isHorizontal ? p + step * 0.5 : edgeCoord + dir * 7;
      let ny = isHorizontal ? edgeCoord + dir * 7 : p + step * 0.5;
      brush.set("rotring", PAL.inkSoft, 0.45);
      brush.line(x0, y0, nx, ny);
      if (isHorizontal) {
        brush.line(p + step, y0, nx, ny);
      } else {
        brush.line(x0, p + step, nx, ny);
      }
    }

    // Knotted bead
    brush.set("pen", knotCol, 1.1);
    let kx = isHorizontal ? x0 : x0 + dir * 3;
    let ky = isHorizontal ? y0 + dir * 3 : y0;
    brush.line(kx - 1.5, ky - 1.5, kx + 1.5, ky + 1.5);
  }
}

// ============================================================================
// 2. RECTANGULAR BORDER OF BEACH-TOWEL STRIPES
// ============================================================================

function drawTowelBorderFrame() {
  const B_OUT = 72;
  const B_IN = 216;
  const W_OUT = 1200 - B_OUT * 2; // 1056

  // Base cream woven towel ground for the border frame
  // Drawn as 4 mitered trapezoids to keep the center open and batch fills cleanly
  let topTrap = [[B_OUT, B_OUT], [1200 - B_OUT, B_OUT], [1200 - B_IN, B_IN], [B_IN, B_IN]];
  let botTrap = [[B_IN, 1200 - B_IN], [1200 - B_IN, 1200 - B_IN], [1200 - B_OUT, 1200 - B_OUT], [B_OUT, 1200 - B_OUT]];
  let leftTrap = [[B_OUT, B_OUT], [B_IN, B_IN], [B_IN, 1200 - B_IN], [B_OUT, 1200 - B_OUT]];
  let rightTrap = [[1200 - B_IN, B_IN], [1200 - B_OUT, B_OUT], [1200 - B_OUT, 1200 - B_OUT], [1200 - B_IN, 1200 - B_IN]];

  drawPolyFill(topTrap, PAL.cream, 220, 0.02, 0.2);
  drawPolyFill(botTrap, PAL.cream, 220, 0.02, 0.2);
  drawPolyFill(leftTrap, PAL.cream, 220, 0.02, 0.2);
  drawPolyFill(rightTrap, PAL.cream, 220, 0.02, 0.2);

  // Concentric Guard Stripes (like a classic carpet border woven into beach-towel stripes)
  // Guard band definitions: [offsetFromOuter, thickness, color, opacity]
  const bands = [
    [0, 10, PAL.indigo, 215],
    [10, 6, PAL.cream, 180],
    [16, 12, PAL.madder, 210],
    [28, 6, PAL.ochre, 190],
    // Main wide stripe zone is from 34 to 110 (thickness 76)
    [110, 6, PAL.ochre, 190],
    [116, 12, PAL.madder, 210],
    [128, 6, PAL.cream, 180],
    [134, 10, PAL.indigo, 215]
  ];

  // Batch guard bands by color
  for (let b of bands) {
    let o1 = B_OUT + b[0];
    let o2 = o1 + b[1];
    let col = b[2];
    let op = b[3];
    // Top, Bottom, Left, Right mitered strips
    drawPolyFill([[o1, o1], [1200 - o1, o1], [1200 - o2, o2], [o2, o2]], col, op, 0.015, 0.22);
    drawPolyFill([[o2, 1200 - o2], [1200 - o2, 1200 - o2], [1200 - o1, 1200 - o1], [o1, 1200 - o1]], col, op, 0.015, 0.22);
    drawPolyFill([[o1, o1], [o2, o2], [o2, 1200 - o2], [o1, 1200 - o1]], col, op, 0.015, 0.22);
    drawPolyFill([[1200 - o2, o2], [1200 - o1, o1], [1200 - o1, 1200 - o1], [1200 - o2, 1200 - o2]], col, op, 0.015, 0.22);
  }

  // Main Border Zone (offset 34 to 110 -> coordinate 106 to 182):
  // High-contrast orthogonal beach-towel blocks alternating Madder Red, Indigo, and Cream with carpet geometry
  const M1 = B_OUT + 34; // 106
  const M2 = B_OUT + 110; // 182
  const span = 1200 - M2 * 2; // 836
  const numBlocks = 22;
  const blkSize = span / numBlocks; // 38px per stripe block

  // Corner Miter Medallion Squares in the 4 corners [M1..M2, M1..M2]
  const corners = [
    [M1, M1],
    [1200 - M2, M1],
    [1200 - M2, 1200 - M2],
    [M1, 1200 - M2]
  ];
  for (let c of corners) {
    let cx = c[0], cy = c[1], cw = M2 - M1;
    drawPolyFill([[cx, cy], [cx + cw, cy], [cx + cw, cy + cw], [cx, cy + cw]], PAL.indigo, 225, 0.02, 0.25);
    // Inner madder diamond in each corner block
    let mx = cx + cw / 2, my = cy + cw / 2, r = cw * 0.38;
    drawPolyFill([[mx, my - r], [mx + r, my], [mx, my + r], [mx - r, my]], PAL.madder, 220, 0.02, 0.25);
    let r2 = cw * 0.16;
    drawPolyFill([[mx, my - r2], [mx + r2, my], [mx, my + r2], [mx - r2, my]], PAL.cream, 235, 0.01, 0.15);
  }

  // Alternating beach-towel stripes along Top, Bottom, Left, Right main border
  for (let pass = 0; pass < 2; pass++) {
    let targetCol = pass === 0 ? PAL.indigo : PAL.madder;
    for (let i = 0; i < numBlocks; i++) {
      if (i % 2 !== 0) continue; // Even blocks get colored, odd blocks stay cream with fine inner stripes
      let isIndigo = (i % 4 === 0);
      if ((pass === 0 && !isIndigo) || (pass === 1 && isIndigo)) continue;

      let p1 = M2 + i * blkSize;
      let p2 = p1 + blkSize;

      // Top & Bottom stripe blocks
      drawPolyFill([[p1, M1], [p2, M1], [p2, M2], [p1, M2]], targetCol, 215, 0.02, 0.25);
      drawPolyFill([[p1, 1200 - M2], [p2, 1200 - M2], [p2, 1200 - M1], [p1, 1200 - M1]], targetCol, 215, 0.02, 0.25);

      // Left & Right stripe blocks
      drawPolyFill([[M1, p1], [M2, p1], [M2, p2], [M1, p2]], targetCol, 215, 0.02, 0.25);
      drawPolyFill([[1200 - M2, p1], [1200 - M1, p1], [1200 - M1, p2], [1200 - M2, p2]], targetCol, 215, 0.02, 0.25);
    }
  }

  // Fine pen detail, woven carpet-towel motifs in the odd cream blocks, and terry-cloth texture
  brush.set("rotring", PAL.ink, 0.45);
  for (let i = 0; i < numBlocks; i++) {
    let p1 = M2 + i * blkSize;
    let p2 = p1 + blkSize;
    let pm = (p1 + p2) * 0.5;

    // Crisp stripe divider lines
    brush.line(p1, M1, p1, M2);
    brush.line(p1, 1200 - M2, p1, 1200 - M1);
    brush.line(M1, p1, M2, p1);
    brush.line(1200 - M2, p1, 1200 - M1, p1);

    if (i % 2 === 1) {
      // Twin narrow woven pinstripes inside the cream towel stripe + small geometric diamond
      let sCol = (i % 4 === 1) ? PAL.madder : PAL.indigo;
      brush.set("pen", sCol, 0.9);
      brush.line(p1 + 7, M1, p1 + 7, M2);
      brush.line(p2 - 7, M1, p2 - 7, M2);
      brush.line(p1 + 7, 1200 - M2, p1 + 7, 1200 - M1);
      brush.line(p2 - 7, 1200 - M2, p2 - 7, 1200 - M1);

      brush.line(M1, p1 + 7, M2, p1 + 7);
      brush.line(M1, p2 - 7, M2, p2 - 7);
      brush.line(1200 - M2, p1 + 7, 1200 - M1, p1 + 7);
      brush.line(1200 - M2, p2 - 7, 1200 - M1, p2 - 7);

      // Small stepped carpet lozenge at center of cream stripe
      let ymTop = (M1 + M2) * 0.5;
      let ymBot = 1200 - ymTop;
      drawPolyStroke([[pm, ymTop - 14], [pm + 9, ymTop], [pm, ymTop + 14], [pm - 9, ymTop]], true);
      drawPolyStroke([[pm, ymBot - 14], [pm + 9, ymBot], [pm, ymBot + 14], [pm - 9, ymBot]], true);
      drawPolyStroke([[ymTop - 14, pm], [ymTop, pm + 9], [ymTop + 14, pm], [ymTop, pm - 9]], true);
      drawPolyStroke([[ymBot - 14, pm], [ymBot, pm + 9], [ymBot + 14, pm], [ymBot, pm - 9]], true);
      brush.set("rotring", PAL.ink, 0.45);
    }
  }

  // Crisp pen borders for all guard bands & mitered corners
  const guardCoords = [72, 82, 88, 100, 106, 182, 188, 200, 206, 216];
  brush.set("rotring", PAL.ink, 0.55);
  for (let g of guardCoords) {
    drawPolyStroke([[g, g], [1200 - g, g], [1200 - g, 1200 - g], [g, 1200 - g]], true);
  }
  // Miter lines at the 4 corners
  brush.set("rotring", PAL.ink, 0.65);
  brush.line(B_OUT, B_OUT, B_IN, B_IN);
  brush.line(1200 - B_OUT, B_OUT, 1200 - B_IN, B_IN);
  brush.line(1200 - B_OUT, 1200 - B_OUT, 1200 - B_IN, 1200 - B_IN);
  brush.line(B_OUT, 1200 - B_OUT, B_IN, 1200 - B_IN);

  // Reciprocal sawtooth / dogtooth carpet guard motif in the cream guard bands (82..88 and 200..206)
  brush.set("rotring", PAL.indigoDeep, 0.4);
  for (let d = 92; d < 1108; d += 12) {
    brush.line(d, 82, d + 6, 88);
    brush.line(d + 6, 88, d + 12, 82);
    brush.line(d, 1118, d + 6, 1112);
    brush.line(d + 6, 1112, d + 12, 1118);
    brush.line(82, d, 88, d + 6);
    brush.line(88, d + 6, 82, d + 12);
    brush.line(1118, d, 1112, d + 6);
    brush.line(1112, d + 6, 1118, d + 12);
  }

  // Terry-cloth weave texture hatching across the border
  brush.noStroke();
  brush.noFill();
  brush.hatchStyle("2H", PAL.creamShade, 0.35);
  brush.hatch(9, 0, { rand: 0.08 });
  drawPolyStroke(topTrap, true);
  drawPolyStroke(botTrap, true);
  brush.noHatch();
}

// ============================================================================
// 3. INNER FIELD & FOUR IVORY SPANDRELS OF DRY SAND
// ============================================================================

function drawInnerFieldAndSpandrels() {
  const F1 = 216;
  const F2 = 984;
  const FW = F2 - F1; // 768
  const nStripes = 16;
  const sw = FW / nStripes; // 48px vertical beach towel stripes inside the field

  // Base cream wash for inner field
  drawPolyFill([[F1, F1], [F2, F1], [F2, F2], [F1, F2]], PAL.cream, 225, 0.02, 0.25);

  // Batch vertical beach-towel stripes in the inner field (alternating Indigo, Cream, Madder, Cream)
  // Pass 0: Indigo stripes; Pass 1: Madder stripes; Pass 2: Ochre pinstripes
  for (let i = 0; i < nStripes; i++) {
    if (i % 4 !== 0) continue;
    let x1 = F1 + i * sw;
    let x2 = x1 + sw;
    drawPolyFill([[x1, F1], [x2, F1], [x2, F2], [x1, F2]], PAL.indigo, 205, 0.02, 0.25);
  }
  for (let i = 0; i < nStripes; i++) {
    if (i % 4 !== 2) continue;
    let x1 = F1 + i * sw;
    let x2 = x1 + sw;
    drawPolyFill([[x1, F1], [x2, F1], [x2, F2], [x1, F2]], PAL.madder, 200, 0.02, 0.25);
  }

  // Fine woven terry-cloth lines and ochre pinstripes on the cream towel stripes
  for (let i = 0; i < nStripes; i++) {
    let x1 = F1 + i * sw;
    let x2 = x1 + sw;
    let xm = (x1 + x2) * 0.5;
    brush.set("rotring", PAL.ink, 0.4);
    brush.line(x1, F1, x1, F2);
    if (i % 2 === 1) {
      brush.set("pen", PAL.ochre, 0.75);
      brush.line(xm - 5, F1, xm - 5, F2);
      brush.line(xm + 5, F1, xm + 5, F2);
      // Subtle vertical terry loop texture lines
      brush.set("2H", PAL.creamShade, 0.35);
      for (let ty = F1 + 8; ty < F2; ty += 18) {
        brush.line(x1 + 8, ty, x2 - 8, ty);
      }
    }
  }

  // --------------------------------------------------------------------------
  // THE FOUR CORNERS: IVORY SPANDRELS OF DRY SAND
  // --------------------------------------------------------------------------
  const spSize = 278;
  const spTL = getSpandrelPoints(F1, F1, 1, 1, spSize);
  const spTR = getSpandrelPoints(F2, F1, -1, 1, spSize);
  const spBR = getSpandrelPoints(F2, F2, -1, -1, spSize);
  const spBL = getSpandrelPoints(F1, F2, 1, -1, spSize);

  const allSpandrels = [
    { pts: spTL, cx: F1, cy: F1, sx: 1, sy: 1 },
    { pts: spTR, cx: F2, cy: F1, sx: -1, sy: 1 },
    { pts: spBR, cx: F2, cy: F2, sx: -1, sy: -1 },
    { pts: spBL, cx: F1, cy: F2, sx: 1, sy: -1 }
  ];

  // Cast shadow of the raised sand spandrel / braided edge onto the striped towel
  for (let sp of allSpandrels) {
    let shadowPts = sp.pts.map(p => [
      constrain(p[0] + sp.sx * 6, F1, F2),
      constrain(p[1] + sp.sy * 6, F1, F2)
    ]);
    drawPolyWash(shadowPts, PAL.indigoDeep, 150);
  }

  // Flat, even ivory watercolour wash for the four dry sand spandrels
  for (let sp of allSpandrels) {
    drawPolyFill(sp.pts, PAL.sandLight, 248, 0.02, 0.22);
    // Secondary warm sand contour glaze inside the corner
    let innerPts = getSpandrelPoints(sp.cx, sp.cy, sp.sx, sp.sy, spSize * 0.86);
    drawPolyFill(innerPts, PAL.sandWarm, 110, 0.04, 0.3);
  }

  // Sculpted sand rim & carpet-spandrel decorative braided border along the scalloped arch
  for (let sp of allSpandrels) {
    let rimPts = getSpandrelPoints(sp.cx, sp.cy, sp.sx, sp.sy, spSize - 11);
    brush.set("cpencil", PAL.sandMid, 1.4);
    drawPolyStroke(rimPts.slice(1), false);

    brush.set("rotring", PAL.sandShadow, 0.65);
    drawPolyStroke(sp.pts.slice(1), false);
    drawPolyStroke(rimPts.slice(1), false);

    // Braided carpet-spandrel cord ticks between sp.pts and rimPts
    brush.set("rotring", PAL.madderDeep, 0.45);
    for (let k = 1; k < sp.pts.length - 1; k++) {
      brush.line(sp.pts[k][0], sp.pts[k][1], rimPts[k + 1][0], rimPts[k + 1][1]);
    }

    // Wind-blown sand ripples & hyperreal stippled sand grains in each spandrel
    drawSpandrelSandTexture(sp.cx, sp.cy, sp.sx, sp.sy, spSize);
  }

  // --------------------------------------------------------------------------
  // HYPERREAL OBJECTS IN THE FOUR SAND SPANDRELS
  // --------------------------------------------------------------------------
  // 1. Top-Left Spandrel: Pair of bare footprints pressed into the dry sand
  drawFootprint(292, 338, -38, 1.0, true);   // Left foot
  drawFootprint(365, 272, -44, 0.94, false); // Right foot stepping ahead

  // 2. Bottom-Right Spandrel: Deep heel-to-toe footprint + sand ripples
  drawFootprint(892, 875, 138, 1.02, true);

  // 3. Bottom-Left Spandrel: Hyperreal striped/madder & indigo beach flip-flop
  drawFlipFlop(308, 892, -45);

  // 4. Top-Right Spandrel: Hyperreal coiled cable with metallic connectors
  drawCoiledCable(892, 306);
}

function drawSpandrelSandTexture(cx, cy, sx, sy, size) {
  // Subtle wind ripples in the dry sand
  brush.set("2H", PAL.sandMid, 0.55);
  for (let r = 45; r < size - 25; r += 26) {
    let ripplePts = [];
    for (let a = 8; a <= 82; a += 6) {
      let rad = r + sin(a * 5 + r) * 2.5;
      ripplePts.push([cx + sx * rad * cos(a), cy + sy * rad * sin(a)]);
    }
    brush.spline(ripplePts, 0.4);
  }

  // Dense stippled sand grains (spray + crisp rotring micro-specks for high-contrast realism)
  brush.set("spray", PAL.sandDark, 0.65);
  for (let i = 0; i < 14; i++) {
    let a = random(8, 82);
    let d = random(25, size - 25);
    let gx = cx + sx * d * cos(a);
    let gy = cy + sy * d * sin(a);
    brush.line(gx, gy, gx + sx * 8, gy + sy * 8);
  }

  brush.set("rotring", PAL.sandShadow, 0.45);
  for (let i = 0; i < 130; i++) {
    let a = random(4, 86);
    let d = random(16, size - 16);
    let gx = cx + sx * d * cos(a);
    let gy = cy + sy * d * sin(a);
    brush.line(gx, gy, gx + 0.8, gy + 0.8);
  }

  brush.set("pen", PAL.white, 0.55);
  for (let i = 0; i < 65; i++) {
    let a = random(5, 85);
    let d = random(18, size - 20);
    let gx = cx + sx * d * cos(a);
    let gy = cy + sy * d * sin(a);
    brush.line(gx, gy, gx + 0.9, gy + 0.9);
  }
}

function drawFootprint(x, y, angleDeg, sc, isLeft) {
  push();
  translate(x, y);
  rotate(angleDeg);
  scale(sc);
  let flip = isLeft ? 1 : -1;

  // Raised displaced sand ridge around the footprint (sunlit rim)
  let rimPts = [
    [0, -44], [flip * 18, -38], [flip * 22, -14], [flip * 16, 10],
    [flip * 17, 34], [0, 44], [-flip * 14, 34], [-flip * 10, 8],
    [-flip * 18, -14], [-flip * 16, -38]
  ];
  drawPolyFill(rimPts, PAL.white, 150, 0.05, 0.2);

  // Sole & heel depression (warm mid-sand shadow)
  let solePts = [
    [0, -35], [flip * 14, -30], [flip * 17, -12], [flip * 11, 8],
    [flip * 12, 28], [0, 36], [-flip * 10, 28], [-flip * 5, 8],
    [-flip * 13, -12], [-flip * 12, -30]
  ];
  drawPolyFill(solePts, PAL.sandMid, 210, 0.04, 0.35);

  // Deep shadow on the north-west crater walls (ball of foot and heel cup)
  let ballShadow = [
    [-flip * 11, -28], [0, -34], [flip * 13, -28], [flip * 14, -14],
    [0, -18], [-flip * 12, -14]
  ];
  drawPolyFill(ballShadow, PAL.sandDark, 195, 0.04, 0.4);

  let heelShadow = [
    [-flip * 8, 16], [0, 14], [flip * 10, 18], [flip * 9, 31],
    [0, 34], [-flip * 8, 28]
  ];
  drawPolyFill(heelShadow, PAL.sandDark, 185, 0.04, 0.4);

  // Five distinct toe indentations
  const toes = [
    { tx: -flip * 11, ty: -45, rx: 5.5, ry: 7.0 }, // Big toe
    { tx: -flip * 2,  ty: -47, rx: 3.6, ry: 5.0 },
    { tx:  flip * 5,  ty: -45, rx: 3.4, ry: 4.6 },
    { tx:  flip * 11, ty: -41, rx: 3.1, ry: 4.1 },
    { tx:  flip * 16, ty: -35, rx: 2.8, ry: 3.5 }  // Little toe
  ];

  for (let t of toes) {
    let tPts = [];
    for (let a = 0; a < 360; a += 45) {
      tPts.push([t.tx + cos(a) * t.rx, t.ty + sin(a) * t.ry]);
    }
    drawPolyFill(tPts, PAL.sandDark, 210, 0.02, 0.3);
    brush.set("rotring", PAL.sandShadow, 0.45);
    brush.arc(t.tx, t.ty, t.rx, 180, 360);
    brush.set("pen", PAL.white, 0.5);
    brush.arc(t.tx, t.ty, t.rx + 1.2, 0, 160);
  }

  // Fine pen contour hatching & stipple inside the footprint craters
  brush.set("rotring", PAL.sandShadow, 0.4);
  for (let h = -30; h <= -12; h += 3.5) {
    brush.line(-10, h, 10, h + 1.5);
  }
  for (let h = 18; h <= 32; h += 3.5) {
    brush.line(-7, h, 8, h + 1);
  }
  drawPolyStroke(solePts, true);

  pop();
}

function drawFlipFlop(x, y, angleDeg) {
  push();
  translate(x, y);
  rotate(angleDeg);

  // Build realistic flip-flop sole outline
  let solePts = [
    [0, -68], [16, -64], [25, -48], [27, -22], [22, 6],
    [23, 38], [18, 58], [0, 66], [-18, 58], [-23, 38],
    [-22, 6], [-27, -22], [-25, -48], [-16, -64]
  ];

  // 1. Sharp high-contrast cast shadow on dry sand
  let shadPts = solePts.map(p => [p[0] + 7, p[1] + 8]);
  drawPolyWash(shadPts, PAL.sandShadow, 200);

  // 2. White/cream EVA foam midsole rim (side thickness)
  let midPts = solePts.map(p => [p[0] + 2.2, p[1] + 2.5]);
  drawPolyFill(midPts, PAL.cream, 240, 0.01, 0.15);

  // 3. Deep Indigo footbed with Madder Red heel/toe accent stripes
  drawPolyFill(solePts, PAL.indigo, 235, 0.02, 0.25);

  // Sun-faded madder red inner graphic inset on footbed
  let insetPts = solePts.map(p => [p[0] * 0.82, p[1] * 0.88]);
  drawPolyFill(insetPts, PAL.madder, 215, 0.02, 0.25);

  // Subtle dark heel wear imprint on the footbed
  let heelWear = [];
  for (let a = 0; a < 360; a += 30) {
    heelWear.push([cos(a) * 11, 36 + sin(a) * 15]);
  }
  drawPolyWash(heelWear, PAL.indigoDeep, 110);

  // 4. Fine diamond grip texture etched onto the rubber footbed
  brush.set("2H", PAL.indigoDeep, 0.35);
  for (let ty = -52; ty <= 50; ty += 6) {
    let halfW = ty < 0 ? 19 - abs(ty + 25) * 0.18 : 16 - abs(ty - 30) * 0.15;
    brush.line(-halfW, ty, halfW, ty);
  }
  // Crisp outer & inner sole pen contours
  brush.set("rotring", PAL.ink, 0.65);
  drawPolyStroke(midPts, true);
  drawPolyStroke(solePts, true);
  brush.set("rotring", PAL.cream, 0.45);
  drawPolyStroke(insetPts, true);

  // Small rectangular woven label at heel
  drawPolyFill([[-8, 28], [8, 28], [8, 36], [-8, 36]], PAL.cream, 230, 0.01, 0.1);
  brush.set("rotring", PAL.indigoDeep, 0.45);
  drawPolyStroke([[-8, 28], [8, 28], [8, 36], [-8, 36]], true);
  brush.line(-5, 32, 5, 32);

  // 5. Cast shadow of the arched Y-strap onto the footbed
  let strapShadL = [[4, -36], [-18, 12], [-22, 18], [0, -28]];
  let strapShadR = [[4, -36], [24, 12], [20, 18], [0, -28]];
  drawPolyWash(strapShadL, PAL.indigoDeep, 195);
  drawPolyWash(strapShadR, PAL.indigoDeep, 195);

  // 6. Molded 3D Y-shaped rubber thong strap (Cream & Brass/Ochre highlight)
  let strapL = [[0, -42], [-4, -36], [-23, 8], [-19, 15], [0, -28]];
  let strapR = [[0, -42], [4, -36], [23, 8], [19, 15], [0, -28]];
  drawPolyFill(strapL, PAL.cream, 245, 0.01, 0.15);
  drawPolyFill(strapR, PAL.cream, 245, 0.01, 0.15);

  brush.set("rotring", PAL.ink, 0.65);
  drawPolyStroke(strapL, true);
  drawPolyStroke(strapR, true);

  // Center ridge along the molded rubber straps & brass toe-post button
  brush.set("rotring", PAL.inkSoft, 0.45);
  brush. spline([[0, -37], [-11, -12], [-21, 11]], 0.3);
  brush.spline([[0, -37], [11, -12], [21, 11]], 0.3);

  brush.set("pen", PAL.madder, 1.2);
  brush.circle(0, -36, 4.5, 0.05);
  brush.set("rotring", PAL.ink, 0.6);
  brush.circle(0, -36, 4.5, 0.05);
  brush.set("pen", PAL.white, 0.7);
  brush.line(-1.5, -37.5, 1, -37.5);

  // Sprinkling of dry sand grains clinging to the flip-flop edge
  brush.set("pen", PAL.sandLight, 0.65);
  for (let i = 0; i < 24; i++) {
    let sx = random(-18, 18);
    let sy = random(-50, 50);
    brush.line(sx, sy, sx + 0.9, sy + 0.9);
  }

  pop();
}

function drawCoiledCable(x, y) {
  push();
  translate(x, y);

  // Coiled braided USB / headphone cable resting in 4 neat overlapping loops on the top-right sand spandrel
  const loops = [
    { cx: -6, cy: 4, rx: 48, ry: 38, rot: -32 },
    { cx: 4, cy: -4, rx: 44, ry: 35, rot: -18 },
    { cx: -2, cy: 8, rx: 40, ry: 33, rot: -45 },
    { cx: 6, cy: 2, rx: 35, ry: 28, rot: -25 }
  ];

  for (let lp of loops) {
    let pts = [];
    let shadPts = [];
    for (let a = 0; a <= 360; a += 15) {
      let lx = cos(a) * lp.rx;
      let ly = sin(a) * lp.ry;
      let rx = lp.cx + lx * cos(lp.rot) - ly * sin(lp.rot);
      let ry = lp.cy + lx * sin(lp.rot) + ly * cos(lp.rot);
      pts.push([rx, ry]);
      // Cast shadow varies with cable lift above sand
      let lift = 3.5 + 3.0 * sin(a * 2 + lp.rot);
      shadPts.push([rx + lift, ry + lift + 1]);
    }

    // Cast shadow on dry sand
    brush.set("pen", PAL.sandShadow, 1.3);
    brush.spline(shadPts, 0.5);

    // Cable dark indigo-charcoal braided outer jacket
    brush.set("pen", PAL.indigoDeep, 1.65);
    brush.spline(pts, 0.5);

    // Metallic/ivory specular weave along the top of the cable
    brush.set("2H", PAL.cream, 0.55);
    brush.spline(pts.slice(0, 14), 0.5);
  }

  // Two free ends emerging from the coil with hyperreal anodized brass & white connectors
  let tail1 = [[-36, 24], [-56, 36], [-72, 28]];
  let tail2 = [[32, -22], [52, -32], [62, -14]];

  brush.set("pen", PAL.sandShadow, 1.3);
  brush.spline(tail1.map(p => [p[0] + 4, p[1] + 5]), 0.4);
  brush.spline(tail2.map(p => [p[0] + 4, p[1] + 5]), 0.4);

  brush.set("pen", PAL.indigoDeep, 1.65);
  brush.spline(tail1, 0.4);
  brush.spline(tail2, 0.4);

  // Connector 1 (at -72, 28, angled)
  drawCablePlug(-72, 28, 155);
  // Connector 2 (at 62, -14, angled)
  drawCablePlug(62, -14, 70);

  // Small velcro/leather cable tie clasping the top of the coil
  drawPolyFill([[-24, -36], [-10, -24], [-16, -17], [-30, -29]], PAL.madder, 235, 0.01, 0.2);
  brush.set("rotring", PAL.ink, 0.6);
  drawPolyStroke([[-24, -36], [-10, -24], [-16, -17], [-30, -29]], true);

  pop();
}

function drawCablePlug(px, py, rotDeg) {
  push();
  translate(px, py);
  rotate(rotDeg);

  // Shadow
  drawPolyWash([[2, -3], [24, -3], [24, 9], [2, 9]], PAL.sandShadow, 180);
  // Strain relief collar
  drawPolyFill([[-6, -3], [2, -3], [2, 3], [-6, 3]], PAL.indigoMid, 230, 0.01, 0.1);
  // White/cream housing shell
  drawPolyFill([[2, -5.5], [18, -5.5], [18, 5.5], [2, 5.5]], PAL.cream, 245, 0.01, 0.1);
  // Gold-plated metallic tip
  drawPolyFill([[18, -3.5], [28, -3.5], [28, 3.5], [18, 3.5]], PAL.ochreLight, 240, 0.01, 0.1);

  brush.set("rotring", PAL.ink, 0.55);
  drawPolyStroke([[-6, -3], [2, -3], [2, 3], [-6, 3]], true);
  drawPolyStroke([[2, -5.5], [18, -5.5], [18, 5.5], [2, 5.5]], true);
  drawPolyStroke([[18, -3.5], [28, -3.5], [28, 3.5], [18, 3.5]], true);
  brush.line(23, -3.5, 23, 3.5);

  pop();
}

// ============================================================================
// 4. INNER RING OF DETAILED SHADE CAST ONTO THE TOWEL
// ============================================================================

function drawParasolShadeRing() {
  const N_RIBS = 16;
  const SX = CX + 9;
  const SY = CY + 11;
  const R_SHADE_OUT = 398;
  const R_SHADE_IN = 358;

  // Build scalloped outer shade boundary matching the 16 parasol panels
  let shadeOuterPts = [];
  let shadeInnerPts = [];
  for (let i = 0; i < N_RIBS; i++) {
    let a1 = i * (360 / N_RIBS);
    let a2 = (i + 1) * (360 / N_RIBS);
    let steps = 8;
    for (let s = 0; s < steps; s++) {
      let t = s / steps;
      let ang = a1 + t * (a2 - a1);
      let scallop = sin(t * 180) * 14;
      let rOut = R_SHADE_OUT - scallop;
      let rIn = R_SHADE_IN - scallop * 0.7;
      shadeOuterPts.push([SX + cos(ang) * rOut, SY + sin(ang) * rOut]);
      shadeInnerPts.push([SX + cos(ang) * rIn, SY + sin(ang) * rIn]);
    }
  }

  // 1. Translucent warm penumbra & transmitted madder/indigo edge glow
  drawPolyFill(shadeOuterPts, PAL.shadeOuter, 155, 0.04, 0.3);

  // 2. Deep high-contrast core umbra shade ring
  drawPolyFill(shadeInnerPts, PAL.shadeDeep, 185, 0.03, 0.25);

  // 3. Detailed towel stripe architecture and cross-hatched terry weave visible inside the shade ring
  const F1 = 216, F2 = 984, sw = (F2 - F1) / 16;
  brush.set("rotring", PAL.indigoDeep, 0.55);
  for (let i = 0; i <= 16; i++) {
    let lx = F1 + i * sw;
    // Intersect vertical line lx with the circle of radius R_SHADE_OUT
    let dx = lx - SX;
    if (abs(dx) < R_SHADE_OUT - 4) {
      let halfH = sqrt(R_SHADE_OUT * R_SHADE_OUT - dx * dx);
      brush.line(lx, SY - halfH, lx, SY + halfH);
    }
  }

  // Fine cross-hatched shadow lines around the visible annulus of the shade ring (r = 325 to 398)
  brush.set("2H", PAL.shadeDeep, 0.45);
  for (let a = 0; a < 360; a += 2) {
    let r1 = 330;
    let r2 = R_SHADE_OUT - abs(sin((a % 22.5) / 22.5 * 180)) * 14;
    let x1 = SX + cos(a) * r1;
    let y1 = SY + sin(a) * r1;
    let x2 = SX + cos(a) * r2;
    let y2 = SY + sin(a) * r2;
    brush.line(x1, y1, x2, y2);
  }

  // 4. Crisp silhouette shadows of the 16 frayed tassels cast onto the towel at the shade rim!
  for (let i = 0; i < N_RIBS; i++) {
    let ang = i * (360 / N_RIBS);
    let tx = SX + cos(ang) * (R_SHADE_OUT + 2);
    let ty = SY + sin(ang) * (R_SHADE_OUT + 2);
    brush.set("pen", PAL.shadeDeep, 1.3);
    brush.line(SX + cos(ang) * (R_SHADE_OUT - 10), SY + sin(ang) * (R_SHADE_OUT - 10), tx + cos(ang) * 18, ty + sin(ang) * 18);

    // Splayed shadow filaments of the frayed tassel threads
    brush.set("rotring", PAL.shadeDeep, 0.55);
    for (let f = -4; f <= 4; f++) {
      let fang = ang + f * 4.5;
      let flen = 22 + (f % 2 === 0 ? 7 : 0);
      brush.line(tx, ty, tx + cos(fang) * flen, ty + sin(fang) * flen);
    }
  }

  // Crisp pen outline of the shade boundary
  brush.set("rotring", PAL.shadeDeep, 0.5);
  drawPolyStroke(shadeOuterPts, true);
}

// ============================================================================
// 5. CENTRAL MEDALLION: OVERHEAD STRIPED BEACH PARASOL
// ============================================================================

function drawParasolMedallion() {
  const N_RIBS = 16;
  const R_CANOPY = 342;
  const R_VALANCE = 286;
  const R_CROWN = 92;
  const R_FINIAL = 28;

  // Precompute panel geometry for all 16 radial gores
  let madderPanels = [];
  let madderFadedCenters = [];
  let indigoPanels = [];
  let indigoFadedCenters = [];
  let crownPatches = [];

  for (let i = 0; i < N_RIBS; i++) {
    let a1 = i * (360 / N_RIBS);
    let a2 = (i + 1) * (360 / N_RIBS);
    let amid = (a1 + a2) * 0.5;

    // Outer scalloped edge between rib i and rib i+1
    let pts = [[CX + cos(a1) * R_FINIAL, CY + sin(a1) * R_FINIAL]];
    let steps = 10;
    for (let s = 0; s <= steps; s++) {
      let t = s / steps;
      let ang = a1 + t * (a2 - a1);
      let scallop = sin(t * 180) * 11;
      let r = R_CANOPY - scallop;
      pts.push([CX + cos(ang) * r, CY + sin(ang) * r]);
    }
    pts.push([CX + cos(a2) * R_FINIAL, CY + sin(a2) * R_FINIAL]);

    // Sun-faded central zone inside each panel (bleached by overhead sun, leaving darker saturated seams)
    let fadePts = [
      [CX + cos(a1 + 2.5) * (R_CROWN + 12), CY + sin(a1 + 2.5) * (R_CROWN + 12)],
      [CX + cos(a1 + 2.0) * (R_VALANCE - 10), CY + sin(a1 + 2.0) * (R_VALANCE - 10)],
      [CX + cos(amid) * (R_VALANCE - 4), CY + sin(amid) * (R_VALANCE - 4)],
      [CX + cos(a2 - 2.0) * (R_VALANCE - 10), CY + sin(a2 - 2.0) * (R_VALANCE - 10)],
      [CX + cos(a2 - 2.5) * (R_CROWN + 12), CY + sin(a2 - 2.5) * (R_CROWN + 12)]
    ];

    // Inner medallion star-crown reinforcement patch
    let cPts = [
      [CX + cos(a1) * R_FINIAL, CY + sin(a1) * R_FINIAL],
      [CX + cos(a1) * R_CROWN, CY + sin(a1) * R_CROWN],
      [CX + cos(amid) * (R_CROWN + 16), CY + sin(amid) * (R_CROWN + 16)],
      [CX + cos(a2) * R_CROWN, CY + sin(a2) * R_CROWN],
      [CX + cos(a2) * R_FINIAL, CY + sin(a2) * R_FINIAL]
    ];
    crownPatches.push({ pts: cPts, isMadder: i % 2 === 0 });

    if (i % 2 === 0) {
      madderPanels.push(pts);
      madderFadedCenters.push(fadePts);
    } else {
      indigoPanels.push(pts);
      indigoFadedCenters.push(fadePts);
    }
  }

  // --------------------------------------------------------------------------
  // BATCH WATERCOLOUR PASSES FOR PARASOL PANELS
  // --------------------------------------------------------------------------
  // 1. Base Madder Red panels
  for (let p of madderPanels) {
    drawPolyFill(p, PAL.madder, 232, 0.025, 0.28);
  }
  // 2. Base Indigo panels
  for (let p of indigoPanels) {
    drawPolyFill(p, PAL.indigo, 238, 0.025, 0.28);
  }
  // 3. Sun-faded bleached centers on Madder panels
  for (let fp of madderFadedCenters) {
    drawPolyFill(fp, PAL.madderFaded, 135, 0.06, 0.35);
  }
  // 4. Sun-faded bleached centers on Indigo panels
  for (let fp of indigoFadedCenters) {
    drawPolyFill(fp, PAL.indigoFaded, 135, 0.06, 0.35);
  }

  // 5. Inner Medallion Star-Crown Reinforcement (alternating counter-changed Cream & Ochre-Gold trim)
  for (let cp of crownPatches) {
    let col = cp.isMadder ? PAL.madderDeep : PAL.indigoDeep;
    drawPolyFill(cp.pts, col, 175, 0.02, 0.25);
  }

  // --------------------------------------------------------------------------
  // HYPERREAL CANVAS WEAVE, TENSION FOLDS & SUN-FADED SEAMS
  // --------------------------------------------------------------------------
  for (let i = 0; i < N_RIBS; i++) {
    let a1 = i * (360 / N_RIBS);
    let a2 = (i + 1) * (360 / N_RIBS);
    let amid = (a1 + a2) * 0.5;
    let isMadder = (i % 2 === 0);

    // 1. Orthogonal canvas weave hatching inside each triangular gore
    brush.set("2H", isMadder ? PAL.madderDeep : PAL.indigoDeep, 0.32);
    for (let r = R_CROWN + 14; r < R_CANOPY - 14; r += 11) {
      let spanAng = 9.2;
      let xL = CX + cos(amid - spanAng) * r;
      let yL = CY + sin(amid - spanAng) * r;
      let xR = CX + cos(amid + spanAng) * r;
      let yR = CY + sin(amid + spanAng) * r;
      brush.line(xL, yL, xR, yR);
    }

    // 2. Parabolic fabric tension creases near the rib tips and valance seam
    brush.set("rotring", isMadder ? PAL.madderDeep : PAL.indigoDeep, 0.42);
    for (let c = 1; c <= 3; c++) {
      let cr = R_VALANCE - c * 22;
      let p1 = [CX + cos(a1 + 1.2) * (cr + 12), CY + sin(a1 + 1.2) * (cr + 12)];
      let pMid = [CX + cos(amid) * (cr - 6), CY + sin(amid) * (cr - 6)];
      let p2 = [CX + cos(a2 - 1.2) * (cr + 12), CY + sin(a2 - 1.2) * (cr + 12)];
      brush.spline([p1, pMid, p2], 0.45);
    }

    // Sunlit ridge highlights along the taut canvas center line
    brush.set("2H", PAL.cream, 0.45);
    brush.line(
      CX + cos(amid) * (R_CROWN + 20),
      CY + sin(amid) * (R_CROWN + 20),
      CX + cos(amid) * (R_VALANCE - 8),
      CY + sin(amid) * (R_VALANCE - 8)
    );

    // 3. Concentric valance seam tape at R_VALANCE (carpet medallion inner ring)
    let v1 = [CX + cos(a1) * R_VALANCE, CY + sin(a1) * R_VALANCE];
    let vMid = [CX + cos(amid) * (R_VALANCE - 5), CY + sin(amid) * (R_VALANCE - 5)];
    let v2 = [CX + cos(a2) * R_VALANCE, CY + sin(a2) * R_VALANCE];

    // Shadow under the valance flap
    brush.set("pen", PAL.indigoDeep, 1.1);
    brush.spline([
      [v1[0] + cos(a1) * 3, v1[1] + sin(a1) * 3],
      [vMid[0] + cos(amid) * 3, vMid[1] + sin(amid) * 3],
      [v2[0] + cos(a2) * 3, v2[1] + sin(a2) * 3]
    ], 0.4);

    // Cream woven binding tape along the valance seam & outer scalloped hem
    brush.set("pen", PAL.cream, 1.35);
    brush.spline([v1, vMid, v2], 0.4);

    let h1 = [CX + cos(a1) * R_CANOPY, CY + sin(a1) * R_CANOPY];
    let hMid = [CX + cos(amid) * (R_CANOPY - 11), CY + sin(amid) * (R_CANOPY - 11)];
    let h2 = [CX + cos(a2) * R_CANOPY, CY + sin(a2) * R_CANOPY];
    brush.set("pen", PAL.cream, 1.5);
    brush.spline([h1, hMid, h2], 0.45);

    brush.set("rotring", PAL.ink, 0.55);
    brush.spline([v1, vMid, v2], 0.4);
    brush.spline([h1, hMid, h2], 0.45);

    // Small decorative fringe loop ticks along the scalloped outer hem
    brush.set("2H", PAL.cream, 0.55);
    for (let s = 1; s < 9; s++) {
      let t = s / 9;
      let ang = a1 + t * (a2 - a1);
      let r = R_CANOPY - sin(t * 180) * 11;
      brush.line(CX + cos(ang) * r, CY + sin(ang) * r, CX + cos(ang) * (r + 5), CY + sin(ang) * (r + 5));
    }

    // Star-crown outline
    let cMid = [CX + cos(amid) * (R_CROWN + 16), CY + sin(amid) * (R_CROWN + 16)];
    let c1 = [CX + cos(a1) * R_CROWN, CY + sin(a1) * R_CROWN];
    let c2 = [CX + cos(a2) * R_CROWN, CY + sin(a2) * R_CROWN];
    brush.set("pen", PAL.ochreLight, 1.1);
    brush.line(c1[0], c1[1], cMid[0], cMid[1]);
    brush.line(cMid[0], cMid[1], c2[0], c2[1]);
    brush.set("rotring", PAL.ink, 0.55);
    brush.line(c1[0], c1[1], cMid[0], cMid[1]);
    brush.line(cMid[0], cMid[1], c2[0], c2[1]);
  }

  // --------------------------------------------------------------------------
  // 16 RADIAL SUN-FADED SEAMS WITH DOUBLE STITCHING & BRASS EYELETS
  // --------------------------------------------------------------------------
  for (let i = 0; i < N_RIBS; i++) {
    let ang = i * (360 / N_RIBS);
    let perp = ang + 90;
    let xStart = CX + cos(ang) * R_FINIAL;
    let yStart = CY + sin(ang) * R_FINIAL;
    let xEnd = CX + cos(ang) * R_CANOPY;
    let yEnd = CY + sin(ang) * R_CANOPY;

    // Dark puckered seam shadow on the away-from-sun side
    brush.set("rotring", PAL.indigoDeep, 0.75);
    brush.line(
      xStart + cos(perp) * 2.2,
      yStart + sin(perp) * 2.2,
      xEnd + cos(perp) * 2.2,
      yEnd + sin(perp) * 2.2
    );

    // Sun-faded bleached canvas ridge along the raised radial rib seam
    brush.set("pen", PAL.cream, 1.35);
    brush.line(xStart, yStart, xEnd, yEnd);

    // Fine dark center seam split and double-row running stitches
    brush.set("rotring", PAL.ink, 0.45);
    brush.line(xStart, yStart, xEnd, yEnd);

    brush.set("2H", PAL.inkSoft, 0.35);
    for (let d = R_FINIAL + 8; d < R_CANOPY - 6; d += 9) {
      let sx1 = CX + cos(ang) * d;
      let sy1 = CY + sin(ang) * d;
      let sx2 = CX + cos(ang) * (d + 4.5);
      let sy2 = CY + sin(ang) * (d + 4.5);
      brush.line(sx1 - cos(perp) * 1.8, sy1 - sin(perp) * 1.8, sx2 - cos(perp) * 1.8, sy2 - sin(perp) * 1.8);
      brush.line(sx1 + cos(perp) * 1.8, sy1 + sin(perp) * 1.8, sx2 + cos(perp) * 1.8, sy2 + sin(perp) * 1.8);
    }

    // Brass grommet / eyelet at each rib tip where the tassel attaches
    let gx = CX + cos(ang) * (R_CANOPY - 3);
    let gy = CY + sin(ang) * (R_CANOPY - 3);
    brush.set("pen", PAL.ochreLight, 1.1);
    brush.circle(gx, gy, 3.2, 0.05);
    brush.set("rotring", PAL.ink, 0.55);
    brush.circle(gx, gy, 3.2, 0.05);

    // ------------------------------------------------------------------------
    // FRAYED TASSELS AT EACH RIB TIP (WITH EXTRA-FRAYED HERO TASSEL)
    // ------------------------------------------------------------------------
    let isHeroTassel = (i === 4 || i === 12 || i === 0 || i === 8);
    drawRibTassel(CX + cos(ang) * R_CANOPY, CY + sin(ang) * R_CANOPY, ang, isHeroTassel);
  }

  // --------------------------------------------------------------------------
  // HYPERREAL WIND-BLOWN SAND GRAINS ON THE PARASOL CANVAS & SEAMS
  // --------------------------------------------------------------------------
  // Tiny clusters of golden-ivory sand grains with sharp dark micro-shadows caught along the seams & valleys
  for (let g = 0; g < 220; g++) {
    // Bias sand grains toward the seams and lower windward panels
    let ribIdx = floor(random(N_RIBS));
    let baseAng = ribIdx * (360 / N_RIBS) + random(-6, 6);
    let dist = random(55, R_CANOPY - 18);
    let sx = CX + cos(baseAng) * dist;
    let sy = CY + sin(baseAng) * dist;

    // Micro cast shadow of the sand grain
    brush.set("rotring", PAL.indigoDeep, 0.5);
    brush.line(sx + 0.9, sy + 0.9, sx + 1.8, sy + 1.8);

    // Sunlit quartz/ivory sand grain highlight
    brush.set("pen", g % 3 === 0 ? PAL.white : PAL.sandLight, 0.65);
    brush.line(sx, sy, sx + 1.0, sy + 1.0);
  }
}

function drawRibTassel(tx, ty, ang, isHero) {
  push();
  translate(tx, ty);
  rotate(ang);

  let len = isHero ? 42 : 30;
  let spread = isHero ? 22 : 14;

  // 1. Braided loop cord emerging from brass grommet
  brush.set("rotring", PAL.ink, 0.6);
  brush.line(0, 0, 7, 0);

  // 2. Knotted macramé head of the tassel
  let headPts = [[5, -4.5], [13, -5.5], [15, 0], [13, 5.5], [5, 4.5]];
  drawPolyFill(headPts, PAL.cream, 245, 0.01, 0.15);
  brush.set("rotring", PAL.ink, 0.55);
  drawPolyStroke(headPts, true);

  // Madder red & gold thread collar binding the neck of the tassel
  drawPolyFill([[12, -4.5], [16, -4.5], [16, 4.5], [12, 4.5]], PAL.madder, 235, 0.01, 0.1);
  brush.set("pen", PAL.ochreLight, 0.85);
  brush.line(12.5, -4.5, 12.5, 4.5);
  brush.line(15.5, -4.5, 15.5, 4.5);

  // 3. Frayed, kinked cotton skirt strands splaying outward over the dark shade ring
  let nStrands = isHero ? 19 : 12;
  for (let s = 0; s < nStrands; s++) {
    let f = map(s, 0, nStrands - 1, -1, 1);
    let yEnd = f * spread + random(-2.5, 2.5);
    let xEnd = 16 + len * (1 - 0.18 * f * f) + random(-4, 6);
    let xMid = 16 + (xEnd - 16) * 0.52;
    let yMid = f * spread * 0.45 + sin(s * 53) * 2.8;

    // Dark shadow underside of each frayed cotton thread
    brush.set("rotring", PAL.ink, 0.45);
    brush.spline([[16, f * 3.5 + 0.8], [xMid, yMid + 0.9], [xEnd, yEnd + 1.0]], 0.45);

    // Bright sunlit ivory/cream cotton strand
    brush.set("pen", s % 2 === 0 ? PAL.cream : PAL.white, 0.65);
    brush.spline([[16, f * 3.5], [xMid, yMid], [xEnd, yEnd]], 0.45);

    // Extra unraveled micro-fibers at the tips of the hero frayed tassels
    if (isHero && s % 2 === 0) {
      brush.set("2H", PAL.cream, 0.35);
      brush.line(xEnd, yEnd, xEnd + random(4, 9), yEnd + random(-4, 4));
      brush.line(xEnd, yEnd, xEnd + random(3, 7), yEnd + random(-3, 3));
    }
  }

  pop();
}

// ============================================================================
// 6. CENTRAL TURNED BRASS FINIAL
// ============================================================================

function drawBrassFinial() {
  // 1. Cast shadow of the tall central finial cap onto the south-east canvas crown
  let finialShad = [];
  for (let a = 0; a < 360; a += 20) {
    finialShad.push([CX + 6 + cos(a) * 31, CY + 7 + sin(a) * 31]);
  }
  drawPolyWash(finialShad, PAL.indigoDeep, 195);

  // 2. Waterproof dark rubber gasket ring (r = 29)
  let gasketPts = [];
  for (let a = 0; a < 360; a += 15) {
    gasketPts.push([CX + cos(a) * 29, CY + sin(a) * 29]);
  }
  drawPolyFill(gasketPts, PAL.ink, 240, 0.01, 0.15);

  // 3. Scalloped / 8-lobed antique brass base flange (r = 24)
  let flangePts = [];
  for (let a = 0; a < 360; a += 10) {
    let r = 23.5 + 1.5 * cos(a * 8);
    flangePts.push([CX + cos(a) * r, CY + sin(a) * r]);
  }
  drawPolyFill(flangePts, PAL.brassMid, 245, 0.01, 0.15);

  // 4. Machined hexagonal brass collar nut (r = 17)
  let hexPts = [];
  for (let a = 0; a < 360; a += 60) {
    hexPts.push([CX + cos(a + 15) * 17, CY + sin(a + 15) * 17]);
  }
  drawPolyFill(hexPts, PAL.brassDark, 230, 0.01, 0.15);

  // 5. Turned spherical brass finial knob (r = 12)
  let knobPts = [];
  for (let a = 0; a < 360; a += 20) {
    knobPts.push([CX + cos(a) * 12, CY + sin(a) * 12]);
  }
  drawPolyFill(knobPts, PAL.ochreLight, 245, 0.01, 0.1);

  // 6. High-contrast metallic reflections, dark bronze core rings, and pure white specular glints
  brush.set("pen", PAL.brassDark, 1.3);
  brush.arc(CX, CY, 20, 20, 175);
  brush.arc(CX, CY, 10, 30, 195);

  brush.set("pen", PAL.brassBright, 1.4);
  brush.arc(CX, CY, 21, 195, 340);
  brush.arc(CX, CY, 13, 200, 330);

  brush.set("pen", PAL.white, 1.5);
  brush.arc(CX, CY, 21.5, 215, 275);
  brush.arc(CX, CY, 9.5, 210, 285);
  brush.circle(CX - 3.5, CY - 3.5, 2.2, 0.02);

  // Crisp technical pen outlines for all concentric finial rings
  brush.set("rotring", PAL.ink, 0.65);
  drawPolyStroke(gasketPts, true);
  drawPolyStroke(flangePts, true);
  drawPolyStroke(hexPts, true);
  brush.circle(CX, CY, 12, 0.02);
  brush.circle(CX, CY, 4.5, 0.02);
}

