// ============================================================================
// GEOMETRY & BRUSH HELPERS
// ============================================================================

function resetBrushModes() {
  brush.noStroke();
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.noMass();
  brush.noField();
}

function drawPoly(pts, curvature = 0.2) {
  if (!pts || pts.length < 3) return;
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
}

function drawOpenSpline(pts, curvature = 0.35) {
  if (!pts || pts.length < 2) return;
  brush.spline(pts, curvature);
}

function getOvalPoints(cx, cy, rx, ry, rotDeg = 0, numPts = 40, startDeg = 0, endDeg = 360) {
  let pts = [];
  let cRot = cos(rotDeg);
  let sRot = sin(rotDeg);
  let span = endDeg - startDeg;
  let count = abs(span - 360) < 0.01 ? numPts : numPts + 1;
  for (let i = 0; i < count; i++) {
    let a = startDeg + (i / numPts) * span;
    let lx = rx * cos(a);
    let ly = ry * sin(a);
    let gx = cx + lx * cRot - ly * sRot;
    let gy = cy + lx * sRot + ly * cRot;
    pts.push([gx, gy]);
  }
  return pts;
}

function drawOvalShape(cx, cy, rx, ry, rotDeg = 0, numPts = 40, curvature = 0.25) {
  let pts = getOvalPoints(cx, cy, rx, ry, rotDeg, numPts);
  drawPoly(pts, curvature);
}

function getGlassWallPolygon(t0, t1, rScale0 = 1.0, rScale1 = 1.0) {
  let x0 = lerp(GLASS.baseX, GLASS.rimX, t0);
  let y0 = lerp(GLASS.baseY, GLASS.rimY, t0);
  let rx0 = lerp(GLASS.baseRx, GLASS.rimRx, t0) * rScale0;
  let ry0 = lerp(GLASS.baseRy, GLASS.rimRy, t0) * rScale0;

  let x1 = lerp(GLASS.baseX, GLASS.rimX, t1);
  let y1 = lerp(GLASS.baseY, GLASS.rimY, t1);
  let rx1 = lerp(GLASS.baseRx, GLASS.rimRx, t1) * rScale1;
  let ry1 = lerp(GLASS.baseRy, GLASS.rimRy, t1) * rScale1;

  // Bottom arc (front side: 0 to 180 deg in rotated frame)
  let bottomArc = getOvalPoints(x0, y0, rx0, ry0, GLASS.rot, 28, 0, 180);
  // Top arc (back side: 180 to 360 deg, or full oval)
  let topArc = getOvalPoints(x1, y1, rx1, ry1, GLASS.rot, 28, 180, 360);
  return bottomArc.concat(topArc);
}

function getBoomerangPoints(cx, cy, s, rotDeg, bend = 0.42, asym = 1.15) {
  // Iconic 1957 Skylark / atomic boomerang silhouette
  let local = [
    [-1.05 * asym, -0.22],
    [-0.55 * asym, -0.32],
    [-0.05, -0.36 - bend * 0.4],
    [0.32, -0.26 - bend * 0.25],
    [0.72, 0.05],
    [1.02, 0.46],
    [1.08, 0.56],
    [0.95, 0.58],
    [0.52, 0.24],
    [0.14, -0.04 - bend * 0.15],
    [-0.12, -0.10 - bend * 0.2],
    [-0.52 * asym, -0.12],
    [-1.02 * asym, -0.14],
    [-1.10 * asym, -0.18]
  ];
  let c = cos(rotDeg);
  let sn = sin(rotDeg);
  let pts = [];
  for (let i = 0; i < local.length; i++) {
    let lx = local[i][0] * s;
    let ly = local[i][1] * s;
    pts.push([cx + lx * c - ly * sn, cy + lx * sn + ly * c]);
  }
  return pts;
}

function getKidneyPoints(cx, cy, rx, ry, rotDeg, indent = 0.38, numPts = 32) {
  let pts = [];
  let c = cos(rotDeg);
  let s = sin(rotDeg);
  for (let i = 0; i < numPts; i++) {
    let a = (i / numPts) * 360;
    let pinch = sin(a) > 0 ? 1 - indent * pow(sin(a), 2) : 1 + 0.12 * pow(sin(a), 2);
    let lx = rx * cos(a) * (1 + 0.08 * sin(2 * a));
    let ly = ry * sin(a) * pinch;
    pts.push([cx + lx * c - ly * s, cy + lx * s + ly * c]);
  }
  return pts;
}

