function generateLaminateData() {
  let palette = [PAL.turquoise, PAL.salmon, PAL.mustard, PAL.charcoal];
  let step = 128;
  let idx = 0;
  for (let gy = -40; gy < height + 80; gy += step) {
    for (let gx = -40; gx < width + 80; gx += step) {
      let jx = gx + random(-28, 28);
      let jy = gy + random(-28, 28);
      let col = palette[(idx + floor( random(4) )) % 4];
      let sc = random(46, 72);
      let ang = random(360);
      let bend = random(0.32, 0.55);
      boomerangs.push({
        cx: jx,
        cy: jy,
        scale: sc,
        angle: ang,
        bend: bend,
        color: col,
        hasEcho: random() < 0.65,
        echoAngleOffset: random(-14, 14),
        echoShiftX: random(-16, 16),
        echoShiftY: random(-16, 16),
        echoColor: palette[(idx + 2) % 4]
      });

      // Secondary interlocking smaller boomerang
      if (random() < 0.85) {
        boomerangs.push({
          cx: jx + random(35, 68),
          cy: jy + random(25, 65),
          scale: random(32, 50),
          angle: ang + random(110, 210),
          bend: random(0.3, 0.5),
          color: palette[(idx + 1) % 4],
          hasEcho: random() < 0.45,
          echoAngleOffset: random(-10, 10),
          echoShiftX: random(-12, 12),
          echoShiftY: random(-12, 12),
          echoColor: PAL.charcoal
        });
      }

      // Atomic kidney pebbles & gold/pastel dots
      confettiDots.push({
        x: gx + random(10, step - 10),
        y: gy + random(10, step - 10),
        rx: random(7, 15),
        ry: random(5, 10),
        rot: random(360),
        color: palette[(idx + 3) % 4]
      });
      idx++;
    }
  }
}

function drawFormicaSurface() {
  resetBrushModes();

  // Subtle warm Formica base sheen panels
  brush.wash(PAL.formicaWarm, 85);
  brush.rect(0, 0, width, height, "corner");
  brush.noWash();

  // Bright upper-right showroom light falloff on the Formica
  brush.wash(PAL.formicaSheen, 110);
  drawOvalShape(880, 260, 680, 560, -25, 44, 0.3);
  brush.noWash();

  // Fine mid-century linen-weave micro-hatching on the Formica
  brush.hatchStyle("2H", "#E2D9C5", 0.55);
  brush.hatch(14, 15, { rand: 0.03 });
  brush.rect(0, 0, width, height, "corner");
  brush.hatch(18, 105, { rand: 0.03 });
  brush.rect(0, 0, width, height, "corner");
  brush.noHatch();

  // Batch draw boomerang gouache fills by color for speed and clean layering
  let colorOrder = [PAL.mustard, PAL.salmon, PAL.turquoise, PAL.charcoal];
  for (let c = 0; c < colorOrder.length; c++) {
    let targetCol = colorOrder[c];
    let op = targetCol === PAL.charcoal ? 205 : 225;
    brush.wash(targetCol, op);
    for (let i = 0; i < boomerangs.length; i++) {
      let b = boomerangs[i];
      if (b.color === targetCol) {
        let pts = getBoomerangPoints(b.cx, b.cy, b.scale, b.angle, b.bend);
        drawPoly(pts, 0.35);
      }
    }
    for (let i = 0; i < confettiDots.length; i++) {
      let d = confettiDots[i];
      if (d.color === targetCol) {
        let kPts = getKidneyPoints(d.x, d.y, d.rx, d.ry, d.rot, 0.35, 18);
        drawPoly(kPts, 0.3);
      }
    }
    brush.noWash();
  }

  // Crisp graphic 1957 echo-boomerangs (hairline ink & colored pencil outlines)
  for (let i = 0; i < boomerangs.length; i++) {
    let b = boomerangs[i];
    if (b.hasEcho) {
      let ePts = getBoomerangPoints(
        b.cx + b.echoShiftX,
        b.cy + b.echoShiftY,
        b.scale * 0.92,
        b.angle + b.echoAngleOffset,
        b.bend
      );
      brush.set("rotring", b.echoColor, 0.55);
      drawPoly(ePts, 0.35);
    }
  }

  // Subtle gouache texture highlights on select boomerangs
  brush.set("cpencil", PAL.formicaSheen, 0.5);
  for (let i = 0; i < boomerangs.length; i += 3) {
    let b = boomerangs[i];
    let pts = getBoomerangPoints(b.cx, b.cy, b.scale * 0.7, b.angle, b.bend);
    drawOpenSpline(pts.slice(1, 6), 0.35);
  }
  resetBrushModes();
}

