  }

  // Meniscus foam/bubble ring & bright turquoise-white liquid rim
  let menArc1 = getOvalPoints(GLASS.liqX, GLASS.liqY, GLASS.liqRx, GLASS.liqRy, GLASS.rot, 36, -20, 195);
  brush.set("gouacheFlat", PAL.white, 0.95);
  drawOpenSpline(menArc1, 0.3);

  let menArc2 = getOvalPoints(GLASS.liqX, GLASS.liqY, GLASS.liqRx * 0.97, GLASS.liqRy * 0.97, GLASS.rot, 36, 170, 355);
  brush.set("razorInk", PAL.turquoiseDeep, 0.75);
  drawOpenSpline(menArc2, 0.3);

  resetBrushModes();
}

function drawIceCubeFractureNetwork(cube, seedOffset) {
  let cx = cube.cx;
  let cy = cube.cy;

  // 1. Planar internal frost veil (stepped geometric fracture plane inside the cube)
  let veilPts = [
    [cx - 38, cy - 18],
    [cx - 8, cy - 32],
    [cx + 34, cy - 6],
    [cx + 18, cy + 28],
    [cx - 24, cy + 16]
  ];
  brush.wash(PAL.white, 170);
  drawPoly(veilPts, 0.1);
  brush.noWash();

  // Fine parallel cleavage striations across the internal fracture plane
  brush.hatchStyle("2H", PAL.turquoiseDeep, 0.45);
  brush.hatch(4.5, 32 + seedOffset * 25, { rand: 0.08 });
  drawPoly(veilPts, 0.1);
  brush.noHatch();

  // 2. Jagged branching crystal fracture lines (dark refraction + razor white edge)
  for (let b = 0; b < 7; b++) {
    let ang = b * 52 + seedOffset * 19;
    let len = random(28, 54);
    let p0 = [cx + random(-14, 14), cy + random(-14, 14)];
    let p1 = [p0[0] + cos(ang) * (len * 0.45), p0[1] + sin(ang) * (len * 0.45)];
    let p2 = [p1[0] + cos(ang + random(-28, 28)) * (len * 0.55), p1[1] + sin(ang + random(-28, 28)) * (len * 0.55)];

    brush.set("razorInk", PAL.charcoal, 0.55);
    drawOpenSpline([p0, p1, p2], 0.1);

    brush.set("cpencil", PAL.white, 0.65);
    drawOpenSpline(
      [
        [p0[0] + 1.5, p0[1] - 1.5],
        [p1[0] + 1.5, p1[1] - 1.5],
        [p2[0] + 1.5, p2[1] - 1.5]
      ],
      0.1
    );

    // Secondary feather-cracks branching off main fracture
    if (b % 2 === 0) {
      let bAng = ang + 42;
      let pBranch = [p1[0] + cos(bAng) * 18, p1[1] + sin(bAng) * 18];
      brush.set("razorInk", PAL.ink, 0.45);
      brush.line(p1[0], p1[1], pBranch[0], pBranch[1]);
    }
  }

  // 3. Trapped freezing micro-bubbles in radial trails inside the ice core
  for (let m = 0; m < 16; m++) {
    let bx = cx + random(-36, 36);
    let by = cy + random(-28, 32);
    let br = random(1.2, 3.6);
    brush.wash(PAL.white, 240);
    brush.circle(bx, by, br);
    brush.noWash();
    brush.set("razorInk", PAL.charcoalMid, 0.35);
    brush.circle(bx, by, br);
  }
}

// ============================================================================
// 5. GLASS RIM & THIN BLACK PEN KIDNEY-SHAPED CONTOURS
// ============================================================================

function drawGlassRimAndContours() {
  resetBrushModes();

  // Outer & inner ellipses of the top glass lip (showing ~11px thick crystal glass rim)
  let outerRim = getOvalPoints(GLASS.rimX, GLASS.rimY, GLASS.rimRx, GLASS.rimRy, GLASS.rot, 56);
  let innerRim = getOvalPoints(GLASS.rimX, GLASS.rimY, GLASS.rimRx - 12, GLASS.rimRy - 11, GLASS.rot, 56);

  // Draw glass lip ring segments in turquoise, charcoal, and bright white gouache
  let lipSegments = [
    { a0: -35, a1: 55, col: PAL.turquoiseGlow, op: 210 },
    { a0: 55, a1: 145, col: PAL.white, op: 240 },
    { a0: 145, a1: 225, col: PAL.charcoal, op: 205 },
    { a0: 225, a1: 325, col: PAL.turquoise, op: 215 }
  ];

  for (let i = 0; i < lipSegments.length; i++) {
    let seg = lipSegments[i];
    let outArc = getOvalPoints(GLASS.rimX, GLASS.rimY, GLASS.rimRx, GLASS.rimRy, GLASS.rot, 20, seg.a0, seg.a1);
    let inArc = getOvalPoints(GLASS.rimX, GLASS.rimY, GLASS.rimRx - 12, GLASS.rimRy - 11, GLASS.rot, 20, seg.a1, seg.a0);
    brush.wash(seg.col, seg.op);
    drawPoly(outArc.concat(inArc), 0.25);
    brush.noWash();
  }

  // THIN BLACK PEN KIDNEY-SHAPED CONTOURS tracing the glass edges, rim, and refractions
  brush.set("razorInk", PAL.ink, 0.85);
  drawPoly(outerRim, 0.25);
  brush.set("razorInk", PAL.ink, 0.65);
  drawPoly(innerRim, 0.25);

  // Outer left and right silhouette contours of the highball glass cylinder
  let cRot = cos(GLASS.rot);
  let sRot = sin(GLASS.rot);
  let leftRimPt = [GLASS.rimX - GLASS.rimRx * cRot, GLASS.rimY - GLASS.rimRx * sRot];
  let leftBasePt = [GLASS.baseX - GLASS.baseRx * cRot, GLASS.baseY - GLASS.baseRx * sRot];
  let rightRimPt = [GLASS.rimX + GLASS.rimRx * cRot, GLASS.rimY + GLASS.rimRx * sRot];
  let rightBasePt = [GLASS.baseX + GLASS.baseRx * cRot, GLASS.baseY + GLASS.baseRx * sRot];

  brush.set("razorInk", PAL.ink, 0.9);
  brush.line(leftRimPt[0], leftRimPt[1], leftBasePt[0], leftBasePt[1]);
  brush.line(rightRimPt[0], rightRimPt[1], rightBasePt[0], rightBasePt[1]);

  // Bottom base outer ink contour
  let baseBottomArc = getOvalPoints(GLASS.baseX, GLASS.baseY, GLASS.baseRx, GLASS.baseRy, GLASS.rot, 36, 0, 180);
  brush.set("razorInk", PAL.ink, 0.95);
  drawOpenSpline(baseBottomArc, 0.3);

  // Iconic 1957 kidney-shaped ink contour loops tracing glass wall highlights & sham edges
  let kidneyContours = [
    // Left cylindrical wall elongated kidney reflection loop
    { cx: 318, cy: 552, rx: 14, ry: 88, rot: 16, indent: 0.45, fillCol: PAL.white, fillOp: 165 },
    // Right cylindrical wall elongated kidney reflection loop
    { cx: 672, cy: 562, rx: 16, ry: 95, rot: 16, indent: 0.48, fillCol: PAL.white, fillOp: 195 },
    // Front rim kidney reflection
    { cx: 485, cy: 642, rx: 82, ry: 15, rot: -12, indent: 0.52, fillCol: PAL.turquoiseLight, fillOp: 150 },
    // Lower sham kidney contour loops
    { cx: 438, cy: 718, rx: 74, ry: 14, rot: 14, indent: 0.50, fillCol: PAL.white, fillOp: 210 },
    { cx: 548, cy: 692, rx: 56, ry: 13, rot: -28, indent: 0.46, fillCol: PAL.salmonLight, fillOp: 175 },
    // Rim highlight kidney loops
    { cx: 435, cy: 632, rx: 64, ry: 11, rot: 18, indent: 0.55, fillCol: null, fillOp: 0 },
    { cx: 615, cy: 602, rx: 52, ry: 12, rot: -32, indent: 0.50, fillCol: null, fillOp: 0 },
    { cx: 365, cy: 268, rx: 78, ry: 10, rot: -22, indent: 0.58, fillCol: PAL.white, fillOp: 220 },
    { cx: 652, cy: 312, rx: 68, ry: 10, rot: 34, indent: 0.55, fillCol: PAL.white, fillOp: 220 }
  ];

  for (let i = 0; i < kidneyContours.length; i++) {
    let kc = kidneyContours[i];
    let kPts = getKidneyPoints(kc.cx, kc.cy, kc.rx, kc.ry, kc.rot, kc.indent, 30);
    if (kc.fillCol) {
      brush.wash(kc.fillCol, kc.fillOp);
      drawPoly(kPts, 0.35);
      brush.noWash();
    }
    brush.set("razorInk", PAL.ink, 0.72);
    drawPoly(kPts, 0.35);
  }

  resetBrushModes();
}

// ============================================================================
// 6. PHOTOGRAPHIC CONDENSATION DROPLETS & COLD SWEAT MIST
// ============================================================================

function drawCondensationMistAndDroplets() {
  resetBrushModes();

  // A. Velvety micro-condensation mist across the front cylindrical wall of the glass
  // Sample points on the front half of the glass cylinder between t = 0.08 and t = 0.92
  for (let i = 0; i < 360; i++) {
    let t = random(0.06, 0.94);
    let ang = random(8, 172); // front-facing wall of cylinder
    let cx = lerp(GLASS.baseX, GLASS.rimX, t);
    let cy = lerp(GLASS.baseY, GLASS.rimY, t);
    let rx = lerp(GLASS.baseRx, GLASS.rimRx, t);
    let ry = lerp(GLASS.baseRy, GLASS.rimRy, t);
    let pt = getOvalPoints(cx, cy, rx, ry, GLASS.rot, 1, ang, ang)[0];

    let mr = random(1.2, 2.6);
    brush.wash(i % 3 === 0 ? PAL.white : PAL.iceCyan, 175);
    brush.circle(pt[0], pt[1], mr);
    brush.noWash();
  }

  // B. 3 vertical condensation rivulet tracks (where heavy drops slid down the cold glass)
  let rivulets = [
    { tTop: 0.78, tBot: 0.32, ang: 52 },
    { tTop: 0.85, tBot: 0.44, ang: 118 },
    { tTop: 0.64, tBot: 0.18, ang: 84 }
  ];

  for (let i = 0; i < rivulets.length; i++) {
    let rv = rivulets[i];
    let trackPts = [];
    for (let s = 0; s <= 8; s++) {
      let t = lerp(rv.tTop, rv.tBot, s / 8);
      let cx = lerp(GLASS.baseX, GLASS.rimX, t);
      let cy = lerp(GLASS.baseY, GLASS.rimY, t);
      let rx = lerp(GLASS.baseRx, GLASS.rimRx, t);
      let ry = lerp(GLASS.baseRy, GLASS.rimRy, t);
      let p = getOvalPoints(cx, cy, rx, ry, GLASS.rot, 1, rv.ang + sin(s * 45) * 1.8, rv.ang)[0];
      trackPts.push(p);
    }
    brush.set("gouacheFlat", PAL.turquoiseDeep, 0.55);
    drawOpenSpline(trackPts, 0.35);
    brush.set("cpencil", PAL.white, 0.65);
    let offsetTrack = trackPts.map(p => [p[0] + 2.2, p[1] - 1.2]);
    drawOpenSpline(offsetTrack, 0.35);

    // Heavy terminal droplet at the bottom of each rivulet
    let endPt = trackPts[trackPts.length - 1];
    drawSingleHyperrealDroplet(endPt[0], endPt[1], 11.5, PAL.turquoiseGlow, true);
  }

  // C. ~135 Hero & Medium Photographic Condensation Droplets on the glass wall
  // Use Poisson-like grid sampling in (t, ang) cylinder coordinates so droplets don't overlap messily
  let dropPalette = [PAL.turquoiseGlow, PAL.turquoiseLight, PAL.salmonLight, PAL.mustardLight, PAL.limeCell4, PAL.iceWhite];
  let idx = 0;
  for (let t = 0.08; t <= 0.90; t += 0.085) {
    for (let ang = 14; ang <= 166; ang += 13) {
      let jt = constrain(t + random(-0.032, 0.032), 0.05, 0.93);
      let jAng = ang + random(-4.8, 4.8);

      let cx = lerp(GLASS.baseX, GLASS.rimX, jt);
      let cy = lerp(GLASS.baseY, GLASS.rimY, jt);
      let rx = lerp(GLASS.baseRx, GLASS.rimRx, jt);
      let ry = lerp(GLASS.baseRy, GLASS.rimRy, jt);
      let pt = getOvalPoints(cx, cy, rx, ry, GLASS.rot, 1, jAng, jAng)[0];

      let rad = random(3.8, 10.2);
      // Make a few drops extra plump
      if ((idx * 7) % 19 === 0) rad = random(10.5, 13.8);

      let refCol = dropPalette[idx % dropPalette.length];
      drawSingleHyperrealDroplet(pt[0], pt[1], rad, refCol, rad > 6.5);
      idx++;
    }
  }

  // D. Escaped condensation water droplets sitting on the Formica laminate around the glass base
  let tableDrops = [
    { x: 278, y: 695, r: 11, col: PAL.turquoiseLight },
    { x: 302, y: 725, r: 6.5, col: PAL.salmonLight },
    { x: 635, y: 745, r: 12.5, col: PAL.turquoiseGlow },
    { x: 662, y: 722, r: 5.5, col: PAL.mustardLight },
    { x: 545, y: 815, r: 9.5, col: PAL.turquoiseLight },
    { x: 412, y: 838, r: 8.0, col: PAL.limeCell4 },
    { x: 602, y: 785, r: 4.5, col: PAL.white }
  ];
  for (let i = 0; i < tableDrops.length; i++) {
    let td = tableDrops[i];
    drawSingleHyperrealDroplet(td.x, td.y, td.r, td.col, true);
  }

  resetBrushModes();
}

function drawSingleHyperrealDroplet(x, y, r, internalColor, detailed) {
  // 1. Cast shadow to the lower-left (light from upper-right)
  let shX = x - r * 0.36;
  let shY = y + r * 0.38;
  brush.wash(PAL.shadowDark, 195);
  drawOvalShape(shX, shY, r * 0.92, r * 0.82, -18, 16, 0.3);
  brush.noWash();

  // 2. Plump tear/kidney droplet body (dark refracted upper-right base)
  let dropPts = getKidneyPoints(x, y, r, r * 0.88, -35, 0.18, 18);
  brush.wash(PAL.charcoal, 215);
  drawPoly(dropPts, 0.35);
  brush.noWash();

  // 3. Refracted glowing belly on the lower-left interior of the droplet lens
  let bellyX = x - r * 0.18;
  let bellyY = y + r * 0.18;
  brush.wash(internalColor, 235);
  drawOvalShape(bellyX, bellyY, r * 0.72, r * 0.58, -38, 14, 0.35);
  brush.noWash();

  if (detailed) {
    // Secondary hot caustic crescent at the bottom-left edge of the droplet
    let caustX = x - r * 0.28;
    let caustY = y + r * 0.28;
    brush.wash(PAL.white, 210);
    drawOvalShape(caustX, caustY, r * 0.42, r * 0.24, -40, 12, 0.35);
    brush.noWash();

    // Thin black pen kidney contour hugging the droplet edge
    brush.set("razorInk", PAL.ink, 0.48);
    drawPoly(dropPts, 0.35);
  }

  // 4. Pinpoint pure white specular glint on the upper-right dome of the droplet
  let glintX = x + r * 0.28;
  let glintY = y - r * 0.28;
  brush.wash(PAL.white, 255);
  brush.circle(glintX, glintY, max(1.4, r * 0.26));
  brush.noWash();
}

// ============================================================================
// 7. CUT LIME WEDGE ON THE LAMINATE (HYPERREALISTIC PULP CELLS)
// ============================================================================

function drawCutLimeWedge() {
  resetBrushModes();

  // A. Freshly squeezed translucent lime juice puddle on the Formica beside the wedge
  let puddlePts = getKidneyPoints(708, 882, 76, 38, -14, 0.42, 32);
  brush.wash(PAL.limeCell5, 145);
  drawPoly(puddlePts, 0.35);
  brush.noWash();

  let puddleInner = getKidneyPoints(704, 885, 52, 24, -14, 0.45, 26);
  brush.wash(PAL.white, 165);
  drawPoly(puddleInner, 0.35);
  brush.noWash();

  brush.set("razorInk", PAL.limeRindMid, 0.5);
  drawPoly(puddlePts, 0.35);

  // Small juice beads around the lime wedge
  drawSingleHyperrealDroplet(618, 868, 7.5, PAL.limeCell4, true);
  drawSingleHyperrealDroplet(642, 912, 5.2, PAL.limeCell5, true);
  drawSingleHyperrealDroplet(858, 922, 6.8, PAL.limeCell4, true);

  // B. Geometry of the Cut Lime Wedge centered around (820, 795)
  // Left tip: A(668, 768), Right tip: B(968, 818), Top apex ridge: C(812, 726), Bottom rind belly: D(825, 892)
  let tipL = [668, 768];
  let tipR = [968, 818];
  let apex = [812, 726];

  // 1. Curved outer green lime rind (bottom-right belly visible beneath the cut face)
  let rindOuterArc = [];
  let rindInnerArc = [];
  let numRindPts = 32;
  for (let i = 0; i <= numRindPts; i++) {
    let t = i / numRindPts;
    let a = t * 180; // 0 to 180 deg
    let baseX = lerp(tipL[0], tipR[0], t);
    let baseY = lerp(tipL[1], tipR[1], t);
    let bulge = sin(a);
    // Outer green skin contour
    rindOuterArc.push([baseX + bulge * 14, baseY + bulge * 108]);
    // Inner boundary where green rind meets white pith
    rindInnerArc.push([baseX + bulge * 10, baseY + bulge * 88]);
  }

  let fullRindPoly = rindOuterArc.concat(rindInnerArc.slice().reverse());
  brush.wash(PAL.limeRindMid, 240);
  drawPoly(fullRindPoly, 0.25);
  brush.noWash();

  // Deeper shadow band along the lower-left curve of the lime rind
  let rindShadowPoly = rindOuterArc.slice(0, 20).concat(rindInnerArc.slice(0, 20).reverse());
  brush.wash(PAL.limeRindDark, 210);
  drawPoly(rindShadowPoly, 0.25);
  brush.noWash();

  // Bright chartreuse sheen on the upper-right curve of the rind
  let rindBrightPoly = rindOuterArc.slice(18, 31).concat(rindInnerArc.slice(18, 31).reverse());
  brush.wash(PAL.limeRindBright, 195);
  drawPoly(rindBrightPoly, 0.25);
  brush.noWash();

  // Hundreds of dimpled essential-oil glands on the green lime rind
  for (let i = 2; i < numRindPts - 2; i++) {
    let pOut = rindOuterArc[i];
    let pIn = rindInnerArc[i];
    for (let k = 0; k < 4; k++) {
      let f = random(0.15, 0.85);
      let gx = lerp(pIn[0], pOut[0], f) + random(-3, 3);
      let gy = lerp(pIn[1], pOut[1], f) + random(-2, 2);
      brush.wash(PAL.limeRindDark, 220);
      brush.circle(gx, gy, random(1.4, 2.6));
      brush.noWash();
      if (k === 0) {
        brush.wash(PAL.limeCell5, 190);
        brush.circle(gx + 0.8, gy - 0.8, 1.1);
        brush.noWash();
      }
    }
  }

  // 2. Creamy-white Pith (Albedo) framing the two flat cut faces of the lime wedge
  // Primary front-facing cut face: bounded by tipL -> apex -> tipR -> rindInnerArc
  let primaryFaceOutline = [tipL, [742, 742], apex, [892, 768], tipR].concat(rindInnerArc.slice().reverse());
  brush.wash(PAL.limePith, 245);
  drawPoly(primaryFaceOutline, 0.2);
  brush.noWash();

  // Secondary upper-back cut face (sloping away from apex toward top-left):
  let backArch = [
    tipL,
    [712, 726],
    [768, 704],
    [835, 702],
    [905, 734],
    tipR,
    [892, 768],
    apex,
    [742, 742]
  ];
  brush.wash(PAL.limePithShadow, 235);
  drawPoly(backArch, 0.22);
  brush.noWash();

  // Subtle green rind edge peeking along the very back arch
  let backRind = [
    tipL,
    [710, 720],
    [768, 697],
    [836, 695],
    [908, 728],
    tipR,
    [905, 734],
    [835, 702],
    [768, 704],
    [712, 726]
  ];
  brush.wash(PAL.limeRindMid, 230);
  drawPoly(backRind, 0.22);
  brush.noWash();

  // 3. EVERY LIME-PULP CELL (JUICE VESICLES) RENDERED TO PHOTOGRAPHIC PRECISION
  // The primary cut face radiates from the central core axis near `apex (812, 734)` out to the pith inner curve.
  let coreCenter = [814, 738];
  let pithInnerArc = [];
  for (let i = 0; i <= numRindPts; i++) {
    let t = i / numRindPts;
    let a = t * 180;
    let baseX = lerp(tipL[0] + 14, tipR[0] - 14, t);
    let baseY = lerp(tipL[1] + 2, tipR[1] - 2, t);
    let bulge = sin(a);
    pithInnerArc.push([baseX + bulge * 8, baseY + bulge * 74]);
  }

  // Divide the primary cut face into 5 radial carpellary segments separated by narrow pith septa
  let segBounds = [
    [1, 6],
    [7, 12],
    [13, 19],
    [20, 25],
    [26, 31]
  ];

  let vesicleColors = [PAL.limeCell1, PAL.limeCell2, PAL.limeCell3, PAL.limeCell4, PAL.limeCellDeep];

  for (let s = 0; s < segBounds.length; s++) {
    let iStart = segBounds[s][0];
    let iEnd = segBounds[s][1];

    // Segment base wash (deep translucent citrus green)
    let segPoly = [
      [lerp(coreCenter[0], pithInnerArc[iStart][0], 0.14), lerp(coreCenter[1], pithInnerArc[iStart][1], 0.14)]
    ];
    for (let i = iStart; i <= iEnd; i++) {
      segPoly.push(pithInnerArc[i]);
    }
    segPoly.push([lerp(coreCenter[0], pithInnerArc[iEnd][0], 0.14), lerp(coreCenter[1], pithInnerArc[iEnd][1], 0.14)]);

    brush.wash(PAL.limeCellDeep, 225);
    drawPoly(segPoly, 0.22);
    brush.noWash();

    // Pack individual tear-drop juice vesicles (pulp cells) in radial tiers inside this segment
    let radialSteps = 6;
    for (let rStep = 0; rStep < radialSteps; rStep++) {
      let r0 = 0.16 + (rStep / radialSteps) * 0.78;
      let r1 = r0 + (0.78 / radialSteps) * 0.92;
      let rMid = (r0 + r1) * 0.5;

      // More cells near the wide outer rim, fewer near the narrow core
      let angularSubsteps = floor(map(rStep, 0, radialSteps - 1, 5, 11));
      for (let aStep = 0; aStep < angularSubsteps; aStep++) {
        let f0 = (aStep + 0.08) / angularSubsteps;
        let f1 = (aStep + 0.92) / angularSubsteps;
        let fMid = (f0 + f1) * 0.5;

        // Interpolate along the segment's outer arc
        let idx0 = lerp(iStart, iEnd, f0);
        let idx1 = lerp(iStart, iEnd, f1);
        let idxM = lerp(iStart, iEnd, fMid);

        let outerP0 = sampleArcPoint(pithInnerArc, idx0);
        let outerP1 = sampleArcPoint(pithInnerArc, idx1);
        let outerPM = sampleArcPoint(pithInnerArc, idxM);

        // Construct plump spindle / tear-drop juice vesicle polygon
        let vTipIn = [lerp(coreCenter[0], outerPM[0], r0), lerp(coreCenter[1], outerPM[1], r0)];
        let vSideL = [lerp(coreCenter[0], outerP0[0], rMid), lerp(coreCenter[1], outerP0[1], rMid)];
        let vTipOut = [lerp(coreCenter[0], outerPM[0], r1), lerp(coreCenter[1], outerPM[1], r1)];
        let vSideR = [lerp(coreCenter[0], outerP1[0], rMid), lerp(coreCenter[1], outerP1[1], rMid)];

        let cellCol = vesicleColors[(s + rStep + aStep) % vesicleColors.length];
        brush.wash(cellCol, 220);
        drawPoly([vTipIn, vSideL, vTipOut, vSideR], 0.42);
        brush.noWash();

        // Translucent bright core inside every pulp vesicle
        let cIn = [lerp(vTipIn[0], vTipOut[0], 0.25), lerp(vTipIn[1], vTipOut[1], 0.25)];
        let cOut = [lerp(vTipIn[0], vTipOut[0], 0.78), lerp(vTipIn[1], vTipOut[1], 0.78)];
        let cL = [lerp(vSideL[0], vSideR[0], 0.32), lerp(vSideL[1], vSideR[1], 0.32)];
        brush.wash(PAL.limeCell5, 175);
        drawPoly([cIn, cL, cOut], 0.35);
        brush.noWash();

        // Wet specular micro-glint on pulp cells
        if ((rStep + aStep) % 2 === 0) {
          brush.set("cpencil", PAL.white, 0.48);
          brush.line(cIn[0], cIn[1], cOut[0], cOut[1]);
        }
      }
    }
  }

  // Also pack foreshortened pulp vesicles on the upper-back secondary cut face
  let backSegs = [
    [[718, 735], [755, 712], [798, 725]],
    [[762, 710], [825, 707], [812, 726]],
    [[832, 708], [895, 736], [822, 730]]
  ];
  for (let b = 0; b < backSegs.length; b++) {
    let bs = backSegs[b];
    brush.wash(PAL.limeCell3, 215);
    drawPoly(bs, 0.25);
    brush.noWash();

    // Foreshortened vesicles on upper cut face
    for (let k = 0; k < 14; k++) {
      let u = random(0.15, 0.75);
      let v = random(0.15, 1 - u);
      let w = 1 - u - v;
      let vx = u * bs[0][0] + v * bs[1][0] + w * bs[2][0];
      let vy = u * bs[0][1] + v * bs[1][1] + w * bs[2][1];
      brush.wash(k % 2 === 0 ? PAL.limeCell4 : PAL.limeCell5, 195);
      drawOvalShape(vx, vy, 5.5, 2.4, -12, 10, 0.35);
      brush.noWash();
    }
  }

  // Creamy pith septa membranes & central core highlight ridge
  for (let s = 0; s < segBounds.length; s++) {
    let iSep = segBounds[s][0];
    let pOut = pithInnerArc[iSep];
    brush.set("gouacheFlat", PAL.limePith, 0.65);
    brush.line(coreCenter[0], coreCenter[1], pOut[0], pOut[1]);
  }

  // Central wedge ridge (where the two flat knife-cuts meet)
  brush.set("gouacheFlat", PAL.limePith, 0.85);
  drawOpenSpline([tipL, [742, 742], apex, [892, 768], tipR], 0.25);

  // Crisp black pen kidney-style contour accents around the lime wedge rind and cut corners
  brush.set("razorInk", PAL.ink, 0.75);
  drawOpenSpline(rindOuterArc, 0.3);
  brush.set("razorInk", PAL.ink, 0.55);
  drawOpenSpline([tipL, [710, 720], [768, 697], [836, 695], [908, 728], tipR], 0.25);

  resetBrushModes();
}

function sampleArcPoint(arcArray, floatIdx) {
  let i0 = constrain(floor(floatIdx), 0, arcArray.length - 1);
  let i1 = constrain(ceil(floatIdx), 0, arcArray.length - 1);
  let frac = floatIdx - i0;
  return [
    lerp(arcArray[i0][0], arcArray[i1][0], frac),
    lerp(arcArray[i0][1], arcArray[i1][1], frac)
  ];
}

