  }

  resetBrushModes();
}

function drawSputnikStar(cx, cy, radius, rotDeg = 8, hasOrbitalRing = true) {
  resetBrushModes();

  // Soft turquoise-white halation glow behind the star core
  brush.wash(PAL.turquoiseLight, 130);
  brush.circle(cx, cy, radius * 0.24);
  brush.noWash();

  // Sharp four-pointed Sputnik star polygon (needle-sharp rays + concave waist)
  let pts = [];
  let waist = radius * 0.085;
  for (let i = 0; i < 8; i++) {
    let a = rotDeg + i * 45;
    let r = i % 2 === 0 ? radius * (i % 4 === 0 ? 1.0 : 0.78) : waist;
    pts.push([cx + r * cos(a), cy + r * sin(a)]);
  }

  // Crisp ink shadow offset slightly for 1957 print-catalogue pop
  let shadowPts = pts.map(p => [p[0] + 1.8, p[1] + 1.8]);
  brush.wash(PAL.charcoal, 145);
  drawPoly(shadowPts, 0.05);
  brush.noWash();

  // Pure white gouache four-pointed star body
  brush.wash(PAL.white, 255);
  drawPoly(pts, 0.05);
  brush.noWash();

  // Diagonal secondary 45-degree atomic cross ticks
  for (let i = 0; i < 4; i++) {
    let a = rotDeg + 45 + i * 90;
    let rIn = radius * 0.12;
    let rOut = radius * 0.34;
    brush.set("razorInk", PAL.white, 0.75);
    brush.line(cx + rIn * cos(a), cy + rIn * sin(a), cx + rOut * cos(a), cy + rOut * sin(a));
  }

  // Razor-sharp extended Sputnik antennae needles with detached satellite bead
  for (let i = 0; i < 4; i++) {
    let a = rotDeg + i * 90;
    let tipR = i % 2 === 0 ? radius * 1.18 : radius * 0.94;
    brush.set("razorInk", PAL.white, 0.65);
    brush.line(cx, cy, cx + tipR * cos(a), cy + tipR * sin(a));

    // Tiny satellite dot past the needle tip
    let dotR = tipR + 6;
    brush.wash(PAL.white, 245);
    brush.circle(cx + dotR * cos(a), cy + dotR * sin(a), 1.8);
    brush.noWash();
  }

  if (hasOrbitalRing) {
    // Iconic 1957 Sputnik orbital ring around the star core
    brush.set("razorInk", PAL.ink, 0.45);
    drawOvalShape(cx, cy, radius * 0.28, radius * 0.14, rotDeg - 28, 24, 0.3);
    brush.set("cpencil", PAL.white, 0.65);
    drawOvalShape(cx, cy, radius * 0.26, radius * 0.13, rotDeg - 28, 24, 0.3);
  }
}

// Hyperrealist Two-Drum Risograph Overprint:
// Chopsticks lifting a tangle of instant ramen from a steaming bowl
// Fluorescent Pink + Teal -> Dark Plum Overprint, Reserved Bare-Paper Steam

const PAPER = "#FAF5E8";
const PAPER_WARM = "#F3ECDC";
const PINK = "#FF1E7A";       // Drum 1: Fluorescent Pink
const PINK_MID = "#FF5C9E";
const PINK_SOFT = "#FF94BE";
const TEAL = "#008E97";       // Drum 2: Riso Teal
const TEAL_MID = "#28AEB5";
const TEAL_SOFT = "#7AD0D4";
const PLUM = "#210930";       // Overprint: Deep Dark Plum
const PLUM_MID = "#3E1452";
const PLUM_SOFT = "#5E2473";

// Deliberate two-drum misregistration offsets (in 1200x1200 canvas units)
const PINK_DX = 7.5;
const PINK_DY = -5.0;
const TEAL_DX = -6.5;
const TEAL_DY = 5.0;

let steamPlumes = [];

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(4289);
