  });

  initSteamPlumes();
}

function draw() {
  translate(-width / 2, -height / 2);
  background(PAPER);
  brush.noField();
  brush.noFill();
  brush.noHatch();
  brush.noWash();

  // 1. Paper tooth & subtle uncoated riso texture
  drawPaperGrain();

  // 2. Two-drum angled halftone background with reserved bare-paper steam
  drawRisoBackgroundHalftone();

  // 3. Back rim of bowl & Nori sheets (behind the noodle waterfall)
  drawBowlBackAndRim();
  drawNoriSheets();

  // 4. Steaming broth base & submerged noodle coils
  drawBrothBase();
