  drawForegroundBowlNoodles();

  // 7. Photorealistic Oil Beads floating across the broth surface
  drawBrothOilBeads();

  // 8. Back Chopstick + Deep shadow core of the lifted noodle tangle
  drawBackChopstick();
  drawLiftedNoodleCascade();
  drawFrontChopstick();
  drawTopClampedNoodles();

