  drawSuspendedDroplets();

  // 11. Front exterior wall of the ceramic bowl (overlapping lower broth edge)
  drawBowlFrontExterior();

  // 12. Reserved bare-paper Steam Wisps weaving through the scene
  drawSteamReservations();

  // 13. Print registration marks & riso border details
  drawRisoPrintMarks();

  noLoop();
