// ============================================================================
// STEAM FIELD GEOMETRY (Reserved Bare Paper)
// ============================================================================
function initSteamPlumes() {
  steamPlumes = [
    { baseX: 310, yStart: 780, yEnd: 55, amp: 58, freq: 0.52, phase: 15, widthBase: 42, widthTop: 95 },
    { baseX: 465, yStart: 720, yEnd: 35, amp: 48, freq: 0.62, phase: 110, widthBase: 34, widthTop: 88 },
    { baseX: 645, yStart: 740, yEnd: 40, amp: 64, freq: 0.48, phase: 220, widthBase: 38, widthTop: 105 },
    { baseX: 835, yStart: 770, yEnd: 65, amp: 52, freq: 0.55, phase: 310, widthBase: 40, widthTop: 92 },
    { baseX: 545, yStart: 520, yEnd: 45, amp: 42, freq: 0.75, phase: 60, widthBase: 28, widthTop: 72 }
  ];
}

function getSteamPoint(plume, y) {
  let t = constrain(map(y, plume.yStart, plume.yEnd, 0, 1), 0, 1);
  let wave = sin(t * 360 * plume.freq + plume.phase) * plume.amp * pow(t, 0.7)
           + cos(t * 720 * plume.freq - plume.phase * 0.5) * (plume.amp * 0.35);
  let cx = plume.baseX + wave;
  let w = lerp(plume.widthBase, plume.widthTop, pow(t, 0.85)) * sin(t * 180);
  // Pinch and billow organically
  w *= 0.75 + 0.35 * sin(t * 540 + plume.phase);
  return { x: cx, w: max(8, w), t: t };
}

function steamIntensity(x, y) {
  let maxVal = 0;
  for (let p of steamPlumes) {
    if (y > p.yStart || y < p.yEnd) continue;
    let sp = getSteamPoint(p, y);
    let d = abs(x - sp.x);
    if (d < sp.w) {
      let v = pow(1 - d / sp.w, 1.4);
      if (v > maxVal) maxVal = v;
    }
    // Secondary tendril split
    let tendrilX = sp.x + sin(sp.t * 420 + p.phase) * sp.w * 0.85;
    let d2 = abs(x - tendrilX);
    let w2 = sp.w * 0.48;
    if (d2 < w2) {
      let v2 = pow(1 - d2 / w2, 1.5) * 0.85;
      if (v2 > maxVal) maxVal = v2;
    }
  }
  return maxVal;
}

// ============================================================================
// 1. PAPER GRAIN & 2. RISO HALFTONE BACKGROUND
// ============================================================================
function drawPaperGrain() {
  brush.set("riso_coarse", PAPER_WARM, 1.2);
  for (let i = 0; i < 160; i++) {
    let x1 = random(40, 1160);
    let y1 = random(40, 1160);
    let ang = random(360);
    let len = random(40, 140);
    brush.line(x1, y1, x1 + cos(ang) * len, y1 + sin(ang) * len);
  }
}

function drawRisoBackgroundHalftone() {
  // Background frame: x in [70, 1130], y in [65, 920]
  // Uses true angled halftone dot rows for Teal (15 deg) and Pink (75 deg)
  // Knocked out wherever steamIntensity(x, y) is high!

  // Pass A: Teal Drum Halftone lines/dots
  let step = 16;
  for (let y = 70; y < 860; y += step) {
    for (let x = 75; x < 1125; x += step) {
      let jx = x + random(-3, 3) + TEAL_DX;
      let jy = y + random(-3, 3) + TEAL_DY;

      // Bowl interior mask check
      let inBowl = sq((x - 600) / 465) + sq((y - 775) / 195) < 0.95;
      if (inBowl && y > 620) continue;

      let sVal = steamIntensity(x, y);
      if (sVal > 0.42) continue; // Reserved bare paper for steam!

      // Vignette & aura around the lifted noodles
      let distCenter = dist(x, y, 560, 420);
      let density = map(distCenter, 80, 560, 0.95, 0.25, true);
      density *= (1 - sVal * 1.4);

      if (random() < density) {
        let w = map(density, 0.2, 0.95, 0.5, 1.35);
        brush.set("riso_dot", TEAL, w);
        brush.line(jx, jy, jx + 5, jy + 1.5);
      }
    }
  }

  // Pass B: Pink Drum Halftone dots (misregistered the other way)
  for (let y = 70; y < 860; y += step) {
    for (let x = 75; x < 1125; x += step) {
      let jx = x + random(-3, 3) + PINK_DX;
      let jy = y + random(-3, 3) + PINK_DY;

      let inBowl = sq((x - 600) / 465) + sq((y - 775) / 195) < 0.95;
      if (inBowl && y > 620) continue;

      let sVal = steamIntensity(x, y);
      if (sVal > 0.38) continue;

      // Warm glow concentrated around the middle-left and noodle aura
      let distAura = dist(x, y, 540, 460);
      let density = map(distAura, 60, 520, 0.92, 0.18, true);
      density *= (1 - sVal * 1.5);

      if (random() < density) {
        let w = map(density, 0.18, 0.92, 0.45, 1.3);
        brush.set("riso_dot", PINK, w);
        brush.line(jx, jy, jx + 1.5, jy + 5);
      }
    }
  }

  // Pass C: Dark Plum Overprint where both drums are dense around the noodle column & steam edges
  for (let y = 90; y < 740; y += 18) {
    for (let x = 140; x < 1060; x += 18) {
      let sVal = steamIntensity(x, y);
      if (sVal > 0.30) continue;

      let dNoodle = dist(x, y, 550, 430);
      if (dNoodle < 360) {
        let prob = map(dNoodle, 40, 360, 0.82, 0.05, true) * (1 - sVal * 1.8);
        if (random() < prob) {
          brush.set("riso_stipple", PLUM, map(prob, 0, 0.85, 0.5, 1.25));
          brush.line(x, y, x + random(-8, 8), y + random(-8, 8));
        }
      }
    }
  }

  // Crisp steam boundary contrast stipple (makes bare-paper steam pop off the riso grain)
  for (let p of steamPlumes) {
    for (let y = p.yEnd + 20; y < p.yStart - 40; y += 10) {
      let sp = getSteamPoint(p, y);
      let lx = sp.x - sp.w - 4;
      let rx = sp.x + sp.w + 4;
      if (y < 660) {
        brush.set("riso_stipple", TEAL, 0.75);
        brush.line(lx + TEAL_DX * 0.6, y + TEAL_DY * 0.6, lx + TEAL_DX * 0.6, y + 7);
        brush.set("riso_stipple", PINK, 0.75);
        brush.line(rx + PINK_DX * 0.6, y + PINK_DY * 0.6, rx + PINK_DX * 0.6, y + 7);
      }
    }
  }
}

// ============================================================================
// 3. BOWL BACK RIM & NORI SHEETS
// ============================================================================
function drawEllipseArc(cx, cy, rx, ry, aStart, aEnd, steps, brushName, col, weight, dx = 0, dy = 0) {
  let pts = [];
  for (let i = 0; i <= steps; i++) {
    let a = lerp(aStart, aEnd, i / steps);
    pts.push([cx + cos(a) * rx + dx, cy + sin(a) * ry + dy]);
  }
  brush.set(brushName, col, weight);
  brush.spline(pts, 0.5);
}

function drawBowlBackAndRim() {
  let cx = 600, cy = 770;
  let rx = 475, ry = 198;

  // Back inner wall of the bowl (visible above the broth from 185 to 355 deg)
  for (let rRatio = 0.89; rRatio <= 1.0; rRatio += 0.015) {
    let curRx = rx * rRatio;
    let curRy = ry * rRatio;
    let shiftY = map(rRatio, 0.89, 1.0, 18, 0);
    drawEllipseArc(cx, cy + shiftY, curRx, curRy, 185, 355, 36, "riso_knockout", PAPER, 1.6);
  }

  // Rim lip misregistration: Teal drum, Pink drum, Plum overlap
  drawEllipseArc(cx, cy, rx, ry, 180, 360, 40, "riso_line", TEAL, 1.8, TEAL_DX, TEAL_DY);
  drawEllipseArc(cx, cy, rx, ry, 180, 360, 40, "riso_line", PINK, 1.8, PINK_DX, PINK_DY);
  drawEllipseArc(cx, cy, rx, ry, 180, 360, 40, "riso_line", PLUM, 2.2, 0, 0);

  // Inner rim line
  drawEllipseArc(cx, cy + 7, rx - 14, ry - 6, 182, 358, 40, "riso_line", TEAL, 1.1, TEAL_DX * 0.5, TEAL_DY * 0.5);
  drawEllipseArc(cx, cy + 7, rx - 14, ry - 6, 182, 358, 40, "riso_line", PINK, 1.1, PINK_DX * 0.5, PINK_DY * 0.5);
  drawEllipseArc(cx, cy + 7, rx - 14, ry - 6, 182, 358, 40, "riso_line", PLUM, 1.3, 0, 0);

  // Classic Ramen Donburi Raimon (Greek-key / spiral fret) motifs along inner back rim
  for (let a = 198; a <= 342; a += 12) {
    if (a > 205 && a < 245) continue; // obscured by Nori
    let mx = cx + cos(a) * (rx - 28);
    let my = cy + 14 + sin(a) * (ry - 14);
    drawRaimonSpiral(mx, my, 11, a + 90);
  }
}

function drawRaimonSpiral(x, y, sz, rotAngle) {
  let ptsPink = [];
  let ptsTeal = [];
  for (let t = 0; t <= 12; t++) {
    let r = map(t, 0, 12, sz, 1.5);
    let ang = t * 75 + rotAngle;
    let px = x + cos(ang) * r;
    let py = y + sin(ang) * r * 0.55;
    ptsPink.push([px + PINK_DX * 0.4, py + PINK_DY * 0.4]);
    ptsTeal.push([px + TEAL_DX * 0.4, py + TEAL_DY * 0.4]);
  }
  brush.set("riso_line", PINK, 0.85);
  brush.spline(ptsPink, 0.2);
  brush.set("riso_line", TEAL, 0.85);
  brush.spline(ptsTeal, 0.2);
}

function drawNoriSheets() {
  // Two crisp roasted seaweed sheets tucked at upper-left of bowl
  let sheets = [
    { x0: 195, y0: 540, x1: 345, y1: 495, x2: 395, y2: 715, x3: 255, y3: 745 },
    { x0: 275, y0: 505, x1: 435, y1: 480, x2: 460, y2: 710, x3: 325, y3: 730 }
  ];

  for (let s of sheets) {
    // 1. Misregistered Teal Ghost
    drawQuadHatch(s, TEAL_DX, TEAL_DY, TEAL, 45, 7, 1.0);
    // 2. Misregistered Pink Ghost
    drawQuadHatch(s, PINK_DX, PINK_DY, PINK, -35, 7, 1.0);
    // 3. Dense Dark Plum Overprint Body
    drawQuadHatch(s, 0, 0, PLUM, 15, 5, 1.35);
    drawQuadHatch(s, 0, 0, PLUM, 105, 6, 1.15);

    // Pressed grid texture of roasted nori
    for (let u = 0.08; u <= 0.92; u += 0.07) {
      let tx = lerp(s.x0, s.x1, u);
      let ty = lerp(s.y0, s.y1, u);
      let bx = lerp(s.x3, s.x2, u);
      let by = lerp(s.y3, s.y2, u);
      brush.set("riso_stipple", PLUM, 1.1);
      brush.line(tx, ty, bx, by);
    }
    // Crisp bare-paper highlights on the glossy roasted surface
    for (let v = 0.15; v < 0.7; v += 0.18) {
      let lx = lerp(s.x0, s.x3, v);
      let ly = lerp(s.y0, s.y3, v);
      let rx = lerp(s.x1, s.x2, v);
      let ry = lerp(s.y1, s.y2, v);
      brush.set("riso_dot", TEAL_SOFT, 0.65);
      brush.line(lerp(lx, rx, 0.2), lerp(ly, ry, 0.2), lerp(lx, rx, 0.75), lerp(ly, ry, 0.75));
    }
  }
}

function drawQuadHatch(q, dx, dy, col, _ang, stepPx, w) {
  let steps = 28;
  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let xA = lerp(q.x0, q.x3, t) + dx;
    let yA = lerp(q.y0, q.y3, t) + dy;
    let xB = lerp(q.x1, q.x2, t) + dx;
    let yB = lerp(q.y1, q.y2, t) + dy;
    brush.set("riso_stipple", col, w);
    brush.line(xA, yA, xB, yB);
  }
  // Crisp edge outline
  brush.set("riso_line", col, w * 0.9);
  brush.spline([
    [q.x3 + dx, q.y3 + dy],
    [q.x0 + dx, q.y0 + dy],
    [q.x1 + dx, q.y1 + dy],
    [q.x2 + dx, q.y2 + dy]
  ], 0.1);
}

// ============================================================================
// 4. STEAMING BROTH BASE & SUBMERGED NOODLE BED
// ============================================================================
function drawBrothBase() {
  let cx = 600, cy = 790;
  let rx = 432, ry = 172;

  // Fill broth ellipse with rich layered Pink, Teal, and Plum riso spray/stipple
  for (let y = cy - ry; y <= cy + ry; y += 7) {
    let dyNorm = (y - cy) / ry;
    if (abs(dyNorm) >= 1) continue;
    let halfW = rx * sqrt(1 - dyNorm * dyNorm);
    let xLeft = cx - halfW;
    let xRight = cx + halfW;

    // Pink Drum pass (emulsified spicy/rich broth glow)
    brush.set("riso_coarse", PINK, 1.35);
    brush.line(xLeft + PINK_DX, y + PINK_DY, xRight + PINK_DX, y + PINK_DY);

    // Teal Drum pass (deep umami shadow tone)
    if (int(y) % 14 < 7) {
      brush.set("riso_stipple", TEAL, 1.15);
      brush.line(xLeft + TEAL_DX, y + TEAL_DY, xRight + TEAL_DX, y + TEAL_DY);
    }

    // Dark Plum depth in the center and around garnishes
    let centerSpan = halfW * 0.78;
    brush.set("riso_stipple", PLUM_MID, 1.2);
    brush.line(cx - centerSpan, y, cx + centerSpan, y);
  }

  // Deep shadow pool directly beneath the lifted noodle waterfall
  for (let i = 0; i < 45; i++) {
    let a = random(360);
    let r = random(20, 175);
    let sx = 565 + cos(a) * r;
    let sy = 775 + sin(a) * r * 0.42;
    brush.set("riso_stipple", PLUM, 1.45);
    brush.line(sx - 25, sy, sx + 25, sy);
  }
}

// ============================================================================
// HYPERREALIST WAVY INSTANT RAMEN STRAND RENDERER
// ============================================================================
function drawRamenStrand(guidePts, waveAmp, waveCycles, thickness, phase, brightness = 1.0) {
  // 1. Densify guide curve
  let totalSteps = 75;
  let dense = [];
  let nSeg = guidePts.length - 1;
  for (let i = 0; i <= totalSteps; i++) {
    let u = (i / totalSteps) * nSeg;
    let idx = min(floor(u), nSeg - 1);
    let f = u - idx;
    // Catmull-Rom / smooth interpolation
    let p0 = guidePts[max(0, idx - 1)];
    let p1 = guidePts[idx];
    let p2 = guidePts[min(nSeg, idx + 1)];
    let p3 = guidePts[min(nSeg, idx + 2)];

    let f2 = f * f;
    let f3 = f2 * f;
    let x = 0.5 * ((2 * p1[0]) + (-p0[0] + p2[0]) * f + (2 * p0[0] - 5 * p1[0] + 4 * p2[0] - p3[0]) * f2 + (-p0[0] + 3 * p1[0] - 3 * p2[0] + p3[0]) * f3);
    let y = 0.5 * ((2 * p1[1]) + (-p0[1] + p2[1]) * f + (2 * p0[1] - 5 * p1[1] + 4 * p2[1] - p3[1]) * f2 + (-p0[1] + 3 * p1[1] - 3 * p2[1] + p3[1]) * f3);
    dense.push({ x, y, t: i / totalSteps });
  }

  // 2. Displace along normal with authentic squared-sinusoid instant noodle crimp
  let centerPts = [];
  let leftEdge = [];
  let rightEdge = [];
  let pinkBody = [];
  let tealEdge = [];
  let highlightPts = [];

  for (let i = 0; i <= totalSteps; i++) {
    let pPrev = dense[max(0, i - 1)];
    let pNext = dense[min(totalSteps, i + 1)];
    let tx = pNext.x - pPrev.x;
    let ty = pNext.y - pPrev.y;
    let len = max(0.001, sqrt(tx * tx + ty * ty));
    let nx = -ty / len;
    let ny = tx / len;

    let t = dense[i].t;
    // Instant ramen crimp: fundamental + 3rd harmonic for squared-off kinks
    let ang = t * 360 * waveCycles + phase;
    let env = sin(t * 180) * 0.45 + 0.55;
    let kink = (0.82 * sin(ang) + 0.22 * sin(3 * ang)) * waveAmp * env;

    let cx = dense[i].x + nx * kink;
    let cy = dense[i].y + ny * kink;
    centerPts.push({ x: cx, y: cy, ang: ang });
  }

  // Recompute exact normals along the crimped noodle path
  for (let i = 0; i <= totalSteps; i++) {
    let cPrev = centerPts[max(0, i - 1)];
    let cNext = centerPts[min(totalSteps, i + 1)];
    let tx = cNext.x - cPrev.x;
    let ty = cNext.y - cPrev.y;
    let len = max(0.001, sqrt(tx * tx + ty * ty));
    let nx = -ty / len;
    let ny = tx / len;

    let halfT = thickness * 0.5;
    let cx = centerPts[i].x;
    let cy = centerPts[i].y;

    leftEdge.push([cx - nx * halfT, cy - ny * halfT]);
    rightEdge.push([cx + nx * halfT, cy + ny * halfT]);
    pinkBody.push([cx - nx * halfT * 0.25 + PINK_DX * 0.38, cy - ny * halfT * 0.25 + PINK_DY * 0.38]);
    tealEdge.push([cx + nx * halfT * 0.45 + TEAL_DX * 0.38, cy + ny * halfT * 0.45 + TEAL_DY * 0.38]);
    highlightPts.push([cx - nx * halfT * 0.22, cy - ny * halfT * 0.22]);
  }

  // Layer A: Dark Plum occlusion crevice shadow underneath the strand
  brush.set("riso_line", PLUM, thickness * 0.16);
  brush.spline(rightEdge, 0.45);

  // Layer B: Teal Drum shadow side (misregistered)
  brush.set("riso_stipple", TEAL, thickness * 0.11);
  brush.spline(tealEdge, 0.45);

  // Layer C: Fluorescent Pink Drum warm starch body (misregistered)
  brush.set("riso_stipple", brightness > 0.85 ? PINK : PINK_MID, thickness * 0.13);
  brush.spline(pinkBody, 0.45);

  // Layer D: Bare-paper core knockout (gives solid opaque noodle volume)
  if (brightness > 0.65) {
    brush.set("riso_knockout", PAPER, thickness * 0.14 * brightness);
    brush.spline(highlightPts, 0.45);
  }

  // Layer E: Fine Pink & Plum contour edges defining the exact photographic kink
  brush.set("riso_line", PINK, 0.72);
  brush.spline(leftEdge, 0.45);
  brush.set("riso_line", PLUM_MID, 0.82);
  brush.spline(rightEdge, 0.45);

  // Layer F: Wet glossy specular glints on the convex wave crests
  if (brightness > 0.8) {
    for (let i = 4; i < totalSteps - 4; i += 2) {
      let cVal = abs(cos(centerPts[i].ang));
      if (cVal < 0.28) {
        let pA = highlightPts[i - 1];
        let pB = highlightPts[i + 1];
        brush.set("riso_knockout", PAPER, 1.15);
        brush.line(pA[0], pA[1], pB[0], pB[1]);
      }
    }
  }
}

