function drawNarutomaki(cx, cy, radius, aspect, rotDeg) {
  let teeth = 28;
  let outerPts = [];
  let bottomWallPts = [];

  for (let i = 0; i <= teeth * 2; i++) {
    let a = (i / (teeth * 2)) * 360 + rotDeg;
    let r = (i % 2 === 0) ? radius : radius * 0.86;
    let px = cx + cos(a) * r;
    let py = cy + sin(a) * r * aspect;
    outerPts.push([px, py]);
    if (sin(a - rotDeg) > -0.15) {
      bottomWallPts.push([px, py + 14]);
    }
  }

  // 1. Cast shadow in broth
  for (let i = 0; i < outerPts.length - 1; i++) {
    brush.set("riso_stipple", PLUM, 1.6);
    brush.line(outerPts[i][0] + 5, outerPts[i][1] + 18, outerPts[i + 1][0] + 5, outerPts[i + 1][1] + 18);
  }

  // 2. 3D scalloped cylindrical ridges along bottom edge (Teal + Pink misregistration)
  for (let i = 0; i < outerPts.length; i++) {
    let p = outerPts[i];
    if (p[1] > cy - 4) {
      brush.set("riso_line", TEAL, 1.15);
      brush.line(p[0] + TEAL_DX * 0.35, p[1] + TEAL_DY * 0.35, p[0] + TEAL_DX * 0.35, p[1] + 14);
      brush.set("riso_line", PLUM_MID, 1.0);
      brush.line(p[0], p[1], p[0], p[1] + 13);
    }
  }

  // 3. Bare-paper knockout for the bright white fishcake face
  for (let s = 0.06; s <= 0.92; s += 0.055) {
    let ring = outerPts.map(pt => [
       lerp(cx, pt[0], s),
      lerp(cy, pt[1], s)
    ]);
    brush.set("riso_knockout", PAPER, 1.9);
    brush.spline(ring, 0.25);
  }

  // 4. Crisp scalloped outline with slight Teal and Pink ghosting
  let tealRim = outerPts.map(pt => [pt[0] + TEAL_DX * 0.35, pt[1] + TEAL_DY * 0.35]);
  let pinkRim = outerPts.map(pt => [pt[0] + PINK_DX * 0.35, pt[1] + PINK_DY * 0.35]);
  brush.set("riso_line", TEAL, 0.9);
  brush.spline(tealRim, 0.15);
  brush.set("riso_line", PINK_MID, 0.85);
  brush.spline(pinkRim, 0.15);
  brush.set("riso_line", PLUM, 1.1);
  brush.spline(outerPts, 0.15);

  // 5. The Iconic Narutomaki Pink Spiral Swirl in the center!
  let spiralPink = [];
  let spiralPlum = [];
  let spiralTeal = [];
  let maxTurns = 2.65;
  let steps = 55;
  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let ang = t * 360 * maxTurns + rotDeg;
    let r = t * (radius * 0.56);
    let sx = cx + cos(ang) * r;
    let sy = cy + sin(ang) * r * aspect;
    spiralPink.push([sx + PINK_DX * 0.3, sy + PINK_DY * 0.3]);
    spiralPlum.push([sx, sy]);
    spiralTeal.push([sx + TEAL_DX * 0.25, sy + TEAL_DY * 0.25]);
  }
  brush.set("riso_stipple", TEAL_MID, 0.9);
  brush.spline(spiralTeal, 0.5);
  brush.set("riso_stipple", PINK, 1.95);
  brush.spline(spiralPink, 0.5);
  brush.set("riso_line", PINK, 1.7);
  brush.spline(spiralPlum, 0.5);
  brush.set("riso_line", PLUM_MID, 0.95);
  brush.spline(spiralPlum, 0.5);
}

