// ============================================================================
// 8. CHOPSTICKS & THE LIFTED TANGLE OF INSTANT RAMEN
// ============================================================================
function drawChopstickBody(xTip, yTip, xBase, yBase, wTip, wBase) {
  let dx = xBase - xTip;
  let dy = yBase - yTip;
  let len = sqrt(dx * dx + dy * dy);
  let nx = -dy / len;
  let ny = dx / len;

  let pTL = [xTip + nx * wTip * 0.5, yTip + ny * wTip * 0.5];
  let pBL = [xTip - nx * wTip * 0.5, yTip - ny * wTip * 0.5];
  let pTR = [xBase + nx * wBase * 0.5, yBase + ny * wBase * 0.5];
  let pBR = [xBase - nx * wBase * 0.5, yBase - ny * wBase * 0.5];

  // 1. Misregistered Teal drum shadow
  for (let s = 0; s <= 1; s += 0.18) {
    let sx0 = lerp(pTL[0], pBL[0], s) + TEAL_DX * 0.65;
    let sy0 = lerp(pTL[1], pBL[1], s) + TEAL_DY * 0.65;
    let sx1 = lerp(pTR[0], pBR[0], s) + TEAL_DX * 0.65;
    let sy1 = lerp(pTR[1], pBR[1], s) + TEAL_DY * 0.65;
    brush.set("riso_stipple", TEAL, 1.1);
    brush.line(sx0, sy0, sx1, sy1);
  }

  // 2. Misregistered Pink drum wood tone
  for (let s = 0; s <= 1; s += 0.18) {
    let sx0 = lerp(pTL[0], pBL[0], s) + PINK_DX * 0.65;
    let sy0 = lerp(pTL[1], pBL[1], s) + PINK_DY * 0.65;
    let sx1 = lerp(pTR[0], pBR[0], s) + PINK_DX * 0.65;
    let sy1 = lerp(pTR[1], pBR[1], s) + PINK_DY * 0.65;
    brush.set("riso_stipple", PINK, 1.1);
    brush.line(sx0, sy0, sx1, sy1);
  }

  // 3. Bare-paper knockout along top facet of bamboo chopstick
  for (let s = 0.08; s <= 0.62; s += 0.12) {
    let sx0 = lerp(pTL[0], pBL[0], s);
    let sy0 = lerp(pTL[1], pBL[1], s);
    let sx1 = lerp(pTR[0], pBR[0], s);
    let sy1 = lerp(pTR[1], pBR[1], s);
    brush.set("riso_knockout", PAPER, 1.65);
    brush.line(sx0, sy0, sx1, sy1);
  }

  // 4. Dark Plum lower facet & wood-grain striations
  for (let s = 0.58; s <= 1.0; s += 0.14) {
    let sx0 = lerp(pTL[0], pBL[0], s);
    let sy0 = lerp(pTL[1], pBL[1], s);
    let sx1 = lerp(pTR[0], pBR[0], s);
    let sy1 = lerp(pTR[1], pBR[1], s);
    brush.set("riso_line", PLUM, 1.25);
    brush.line(sx0, sy0, sx1, sy1);
  }

  // Sharp architectural edges of the chopstick
  brush.set("riso_line", PLUM, 1.5);
  brush.line(pTL[0], pTL[1], pTR[0], pTR[1]);
  brush.line(pBL[0], pBL[1], pBR[0], pBR[1]);
  brush.line(pTL[0], pTL[1], pBL[0], pBL[1]);
}

