// ============================================================================
// 9. SCALLION RINGS (NEGI) — PHOTOGRAPHICALLY ACCURATE TORUS RINGS
// ============================================================================
function drawScallionRing(cx, cy, rx, ry, thickness, tiltDeg) {
  let steps = 24;
  let outerPts = [];
  let innerPts = [];
  let tealPts = [];
  let pinkPts = [];
  let bottomCyl = [];

  let cT = cos(tiltDeg);
  let sT = sin(tiltDeg);

  for (let i = 0; i <= steps; i++) {
    let a = (i / steps) * 360;
    let lx = cos(a) * rx;
    let ly = sin(a) * ry;
    let ox = cx + lx * cT - ly * sT;
    let oy = cy + lx * sT + ly * cT;

    let ilx = cos(a) * (rx * 0.56);
    let ily = sin(a) * (ry * 0.56);
    let ix = cx + ilx * cT - ily * sT;
    let iy = cy + ilx * sT + ily * cT;

    outerPts.push([ox, oy]);
    innerPts.push([ix, iy]);
    tealPts.push([ox + TEAL_DX * 0.45, oy + TEAL_DY * 0.45]);
    pinkPts.push([ox + PINK_DX * 0.35, oy + PINK_DY * 0.35]);
    bottomCyl.push([ox, oy + thickness]);
  }

  // 1. Dark Plum shadow & inner hole depth
  brush.set("riso_line", PLUM, 1.5);
  brush.spline(bottomCyl, 0.4);
  brush.set("riso_stipple", PLUM, 1.2);
  brush.spline(innerPts, 0.4);

  // 2. Misregistered Pink Ghost
  brush.set("riso_line", PINK_MID, 0.9);
  brush.spline(pinkPts, 0.4);

  // 3. Punchy Teal Drum body (Negi green translated into Riso Teal!)
  brush.set("riso_stipple", TEAL, 1.65);
  brush.spline(tealPts, 0.4);
  brush.set("riso_line", TEAL, 1.55);
  brush.spline(outerPts, 0.4);
  brush.set("riso_line", TEAL, 1.3);
  brush.spline(innerPts, 0.4);

  // 4. Cellular ring highlight in bare paper along top cut surface
  let hlPts = [];
  for (let i = 0; i <= steps; i++) {
    hlPts.push([
      lerp(outerPts[i][0], innerPts[i][0], 0.45),
      lerp(outerPts[i][1], innerPts[i][1], 0.45)
    ]);
  }
  brush.set("riso_knockout", PAPER, 1.15);
  brush.spline(hlPts, 0.4);

  // 5. Crisp Plum outer contour
  brush.set("riso_line", PLUM, 1.0);
  brush.spline(outerPts, 0.4);
}

