// ============================================================================
// 11. FRONT EXTERIOR CERAMIC WALL OF THE RAMEN BOWL
// ============================================================================
function drawBowlFrontExterior() {
  let cx = 600, cy = 770;
  let rxTop = 475, ryTop = 198;
  let cyFoot = 1095, rxFoot = 215, ryFoot = 64;

  // 1. Knock out bare paper for the front rim lip (from 0 to 180 degrees)
  for (let off = -6; off <= 12; off += 3) {
    drawEllipseArc(cx, cy + off, rxTop - off * 0.4, ryTop - off * 0.2, 2, 178, 45, "riso_knockout", PAPER, 2.2);
  }

  // 2. Ceramic bowl body curves (from front rim down to the foot ring)
  let bodyRings = 26;
  for (let i = 1; i <= bodyRings; i++) {
    let t = i / bodyRings;
    // Bowl profile curve (rounded belly tapering to foot)
    let belly = sin(t * 90);
    let curRx = lerp(rxTop, rxFoot, pow(t, 1.25)) + belly * 12;
    let curRy = lerp(ryTop, ryFoot, pow(t, 1.1));
    let curCy = lerp(cy + 10, cyFoot, pow(t, 0.92));

    // Reserve paper first so the bowl exterior is opaque over background
    drawEllipseArc(cx, curCy, curRx, curRy, 4, 176, 40, "riso_knockout", PAPER, 2.4);

    // Teal Drum shading on the bowl exterior (stronger on right & lower curve)
    let tealStart = lerp(8, 25, t);
    let tealEnd = lerp(172, 165, t);
    drawEllipseArc(cx + TEAL_DX, curCy + TEAL_DY, curRx, curRy, tealStart, tealEnd, 38, "riso_stipple", TEAL, map(t, 0, 1, 0.85, 1.65));

    // Pink Drum ornamental bands & warm ceramic halftone reflection
    if (i === 4 || i === 5 || i === 15 || i === 16 || i > 20) {
      drawEllipseArc(cx + PINK_DX, curCy + PINK_DY, curRx, curRy, 10, 170, 38, "riso_stipple", PINK, 1.55);
    } else if (i % 2 === 0) {
      drawEllipseArc(cx + PINK_DX, curCy + PINK_DY, curRx, curRy, 18, 125, 30, "riso_dot", PINK_MID, 0.95);
    }

    // Dark Plum overprint in the lower belly shadow and under the rim lip
    if (i <= 2 || i === 5 || i === 16 || i >= 19) {
      drawEllipseArc(cx, curCy, curRx, curRy, 12, 168, 38, "riso_line", PLUM, map(t, 0, 1, 1.1, 1.85));
    }
  }

  // 3. Vertical ceramic fluting / ribs along the bowl exterior
  for (let a = 16; a <= 164; a += 6) {
    let x1 = cx + cos(a) * rxTop;
    let y1 = cy + 12 + sin(a) * ryTop;
    let xMid = cx + cos(a) * (lerp(rxTop, rxFoot, 0.55) + 10);
    let yMid = lerp(cy + 12, cyFoot, 0.52) + sin(a) * lerp(ryTop, ryFoot, 0.55);
    let x2 = cx + cos(a) * rxFoot;
    let y2 = cyFoot + sin(a) * ryFoot;

    // Misregistered Teal & Pink fluting ribs
    brush.set("riso_stipple", TEAL, 0.85);
    brush.spline([[x1 + TEAL_DX, y1 + TEAL_DY], [xMid + TEAL_DX, yMid + TEAL_DY], [x2 + TEAL_DX, y2 + TEAL_DY]], 0.4);

    if (a % 12 === 4) {
      brush.set("riso_stipple", PINK, 0.9);
      brush.spline([[x1 + PINK_DX, y1 + PINK_DY], [xMid + PINK_DX, yMid + PINK_DY], [x2 + PINK_DX, y2 + PINK_DY]], 0.4);
      brush.set("riso_line", PLUM_MID, 0.95);
      brush.spline([[x1, y1], [xMid, yMid], [x2, y2]], 0.4);
    }
  }

  // 4. Bowl Foot Ring (Koudai) at the base + cast shadow on table
  for (let s = 8; s <= 36; s += 5) {
    drawEllipseArc(cx + TEAL_DX, cyFoot + s + TEAL_DY, rxFoot + s * 0.9, ryFoot + s * 0.35, 10, 170, 32, "riso_coarse", TEAL, 1.3);
    drawEllipseArc(cx + PINK_DX, cyFoot + s + PINK_DY, rxFoot + s * 0.9, ryFoot + s * 0.35, 10, 170, 32, "riso_coarse", PINK, 1.25);
    drawEllipseArc(cx, cyFoot + s, rxFoot + s * 0.7, ryFoot + s * 0.28, 18, 162, 30, "riso_stipple", PLUM, 1.6);
  }

  // Foot ring cylinder
  for (let h = 0; h <= 26; h += 4) {
    drawEllipseArc(cx, cyFoot + h, rxFoot, ryFoot, 5, 175, 32, "riso_line", PLUM, 1.5);
    drawEllipseArc(cx + PINK_DX * 0.6, cyFoot + h + PINK_DY * 0.6, rxFoot, ryFoot, 5, 175, 32, "riso_stipple", PINK, 1.1);
  }

  // 5. Crisp Front Rim Lip Highlight & Misregistered Ghosting
  drawEllipseArc(cx, cy, rxTop, ryTop, 0, 180, 48, "riso_line", TEAL, 1.85, TEAL_DX, TEAL_DY);
  drawEllipseArc(cx, cy, rxTop, ryTop, 0, 180, 48, "riso_line", PINK, 1.85, PINK_DX, PINK_DY);
  drawEllipseArc(cx, cy + 3, rxTop - 3, ryTop - 2, 2, 178, 48, "riso_knockout", PAPER, 2.1, 0, 0);
  drawEllipseArc(cx, cy, rxTop, ryTop, 0, 180, 48, "riso_line", PLUM, 2.2, 0, 0);
  drawEllipseArc(cx, cy + 9, rxTop - 12, ryTop - 5, 2, 178, 48, "riso_line", PLUM, 1.6, 0, 0);
}

// ============================================================================
// 12. RESERVED BARE-PAPER STEAM WISPS (Weaving in front of bowl & noodles)
// ============================================================================
function drawSteamReservations() {
  // Reinforce the curling bare-paper steam plumes so they cleanly reserve bare paper
  // where they rise out of the bowl and drift across the nori, chopsticks, and noodles
  for (let p of steamPlumes) {
    let spineLeft = [];
    let spineRight = [];
    let spineCenter = [];
    let tendrilPts = [];

    for (let y = p.yStart; y >= p.yEnd; y -= 14) {
      let sp = getSteamPoint(p, y);
      spineCenter.push([sp.x, y]);
      spineLeft.push([sp.x - sp.w * 0.55, y]);
      spineRight.push([sp.x + sp.w * 0.55, y]);

      let tx = sp.x + sin(sp.t * 420 + p.phase) * sp.w * 0.85;
      tendrilPts.push([tx, y]);

      // Billowing bare-paper knockout strokes across the plume width
      if (y < 760) {
        let alphaWeight = sin(sp.t * 180) * 1.7 + 0.4;
        brush.set("riso_knockout", PAPER, alphaWeight);
        brush.line(sp.x - sp.w * 0.45, y, sp.x + sp.w * 0.45, y - 6);
      }
    }

    // Smooth bare-paper ribbon spines
    brush.set("riso_knockout", PAPER, 2.3);
    brush.spline(spineCenter, 0.5);
    brush.set("riso_knockout", PAPER, 1.5);
    brush.spline(spineLeft, 0.5);
    brush.set("riso_knockout", PAPER, 1.5);
    brush.spline(spineRight, 0.5);
    brush.set("riso_knockout", PAPER, 1.35);
    brush.spline(tendrilPts, 0.5);

    // Delicate grainy stipple along the outer boundary of the bare-paper steam
    let tealGhost = spineLeft.map(pt => [pt[0] - 8 + TEAL_DX * 0.5, pt[1] + TEAL_DY * 0.5]);
    let pinkGhost = spineRight.map(pt => [pt[0] + 8 + PINK_DX * 0.5, pt[1] + PINK_DY * 0.5]);
    brush.set("riso_stipple", TEAL_MID, 0.65);
    brush.spline(tealGhost, 0.5);
    brush.set("riso_stipple", PINK_MID, 0.65);
    brush.spline(pinkGhost, 0.5);
  }
}

// ============================================================================
// 13. RISOGRAPH REGISTRATION MARKS & PRINT BORDER
// ============================================================================
function drawRisoPrintMarks() {
  // Subtle two-drum registration targets in the four corners & color step bars
  let corners = [
    [55, 55], [1145, 55], [55, 1145], [1145, 1145]
  ];

  for (let [cx, cy] of corners) {
    // Teal Drum target (shifted by TEAL_DX * 0.5, TEAL_DY * 0.5)
    let tx = cx + TEAL_DX * 0.45;
    let ty = cy + TEAL_DY * 0.45;
    brush.set("riso_line", TEAL, 0.9);
    brush.line(tx - 16, ty, tx + 16, ty);
    brush.line(tx, ty - 16, tx, ty + 16);
    drawEllipseArc(tx, ty, 9, 9, 0, 360, 16, "riso_line", TEAL, 0.85);

    // Pink Drum target (shifted by PINK_DX * 0.5, PINK_DY * 0.5)
    let px = cx + PINK_DX * 0.45;
    let py = cy + PINK_DY * 0.45;
    brush.set("riso_line", PINK, 0.9);
    brush.line(px - 16, py, px + 16, py);
    brush.line(px, py - 16, px, py + 16);
    drawEllipseArc(px, py, 9, 9, 0, 360, 16, "riso_line", PINK, 0.85);
  }

  // Two-drum misregistered frame rule
  let m = 68;
  brush.set("riso_line", TEAL, 0.95);
  brush.line(m + TEAL_DX * 0.5, m + TEAL_DY * 0.5, 1200 - m + TEAL_DX * 0.5, m + TEAL_DY * 0.5);
  brush.line(m + TEAL_DX * 0.5, 1200 - m + TEAL_DY * 0.5, 1200 - m + TEAL_DX * 0.5, 1200 - m + TEAL_DY * 0.5);
  brush.line(m + TEAL_DX * 0.5, m + TEAL_DY * 0.5, m + TEAL_DX * 0.5, 1200 - m + TEAL_DY * 0.5);
  brush.line(1200 - m + TEAL_DX * 0.5, m + TEAL_DY * 0.5, 1200 - m + TEAL_DX * 0.5, 1200 - m + TEAL_DY * 0.5);

  brush.set("riso_line", PINK, 0.95);
  brush.line(m + PINK_DX * 0.5, m + PINK_DY * 0.5, 1200 - m + PINK_DX * 0.5, m + PINK_DY * 0.5);
  brush.line(m + PINK_DX * 0.5, 1200 - m + PINK_DY * 0.5, 1200 - m + PINK_DX * 0.5, 1200 - m + PINK_DY * 0.5);
  brush.line(m + PINK_DX * 0.5, m + PINK_DY * 0.5, m + PINK_DX * 0.5, 1200 - m + PINK_DY * 0.5);
  brush.line(1200 - m + PINK_DX * 0.5, m + PINK_DY * 0.5, 1200 - m + PINK_DX * 0.5, 1200 - m + PINK_DY * 0.5);
}

