  brush.add("swelling_contour", {
    type: "default",
    weight: 3.1,
    scatter: 0.16,
    sharpness: 0.58,
    grain: 11,
    opacity: 235,
    spacing: 0.11,
    pressure: [0.22, 1.55, 0.85, 1.45, 0.18],
    noise: 0.65
  });

  brush.add("mural_charcoal", {
    type: "default",
    weight: 2.1,
    scatter: 0.38,
    sharpness: 0.34,
    grain: 15,
    opacity: 175,
    spacing: 0.16,
    pressure: [0.25, 1.35, 0.2],
    noise: 0.85
  });

  brush.add("sculpt_hatch", {
    type: "default",
    weight: 0.78,
    scatter: 0.1,
    sharpness: 0.72,
    grain: 8,
    opacity: 190,
    spacing: 0.14,
    pressure: [0.15, 1.15, 0.15],
    noise: 0.45
  });

  brush.add("flour_chalk", {
    type: "default",
    weight: 1.35,
    scatter: 0.62,
    sharpness: 0.25,
    grain: 18,
    opacity: 165,
    spacing: 0.2,
    pressure: [0.2, 1.25, 0.18],
    noise: 0.9
  });

  brush.add("dust_stipple", {
    type: "spray",
    weight: 1.0,
    scatter: 2.6,
    opacity: 155,
    spacing: 0.55,
    pressure: [0.4, 1.2, 0.3],
    noise: 1.0
  });

  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(8472);
  noiseSeed(8472);

  // Custom diagonal mural flow field following the rhythmic diagonal
  brush.addField("mural_diagonal", (t, field) => {
    for (let col = 0; col < field.length; col++) {
      for (let row = 0; row < field[0].length; row++) {
        let nx = col / field.length;
        let ny = row / field[0].length;
        let baseAngle = -38 + sin(nx * 180 + ny * 140) * 14 + (noise(nx * 3, ny * 3) - 0.5) * 22;
        field[col][row] = baseAngle;
      }
    }
    return field;
  });
}

function draw() {
  translate(-width / 2, -height / 2);
  background(PAL.blackDeep);

  // Ensure valid active brush state at all times
  brush.set("mural_charcoal", PAL.black, 1);

  // 1. Monumental Public Wall Fresco Fragment & High-Contrast Chiaroscuro Ground
  drawFrescoWallFragment();

  // 2. Monumental Torso, Shoulders & Traditional Woven Huipil
  drawTorsoAndGarment();

  // 3. Low-Angle Neck & Heroic Sculpted Head
  drawNeckAndHead();

  // 4. The Smoking Clay Comal, Hearth Embers & Cooking Tortillas
  drawComalAndCookingTortillas();

  // 5. Lower-Left Stacked Tortillas & Earthen Cloth (Diagonal Anchor)
  drawStackedTortillas();

  // 6. Looming Heroic Forearms & Hands Pressing Tortilla on the Comal
  drawHeroicArmsAndHands();

  // 7. Rising Sculptural Steam, Flour Dust & Final Fresco Fractures
  drawSteamAndFlourDust();
  drawFrescoCracksAndEdgeFrame();

  noLoop();
}

// ============================================================================
// GEOMETRY & SCULPTURAL RENDERING HELPERS
// ============================================================================

function drawFilledPoly(pts, curvature = 0.25) {
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(CLOSE);
}

function evalPolyline(pts, t) {
  t = constrain(t, 0, 1);
  let n = pts.length - 1;
  let f = t * n;
  let idx = min(floor(f), n - 1);
  let frac = f - idx;
  let p0 = pts[idx];
  let p1 = pts[idx + 1];
  let x = lerp(p0[0], p1[0], frac);
  let y = lerp(p0[1], p1[1], frac);
  let dx = p1[0] - p0[0];
  let dy = p1[1] - p0[1];
  let len = max(0.0001, hypot(dx, dy));
  return {
    x,
    y,
    tx: dx / len,
    ty: dy / len,
    nx: -dy / len,
    ny: dx / len
  };
}

function evalRadius(radii, t) {
  t = constrain(t, 0, 1);
  let n = radii.length - 1;
  let f = t * n;
  let idx = min(floor(f), n - 1);
  let frac = f - idx;
  return lerp(radii[idx], radii[idx + 1], frac);
}

/**
 * Renders a 3D cylindrical anatomical form (forearm, finger segment, neck, etc.)
 * using earth-pigment washes, cross-contour 3D curvature hatching, rhombic mesh,
 * core shadow, terre-verte reflected light, maize/flour highlights, and swelling contours.
 */
function sculptAnatomicalCylinder(spinePts, radii, opts = {}) {
  let steps = opts.steps || 48;
  let bulgeDir = opts.bulgeDir !== undefined ? opts.bulgeDir : 1;
  let bulgeAmt = opts.bulgeAmt !== undefined ? opts.bulgeAmt : 0.26;
  let flipLight = opts.flipLight || false;
  let topContour = [];
  let botContour = [];
  let polyPts = [];

  for (let i = 0; i <= 24; i++) {
    let t = i / 24;
    let f = evalPolyline(spinePts, t);
    let r = evalRadius(radii, t);
    let wobble = (noise(f.x * 0.015, f.y * 0.015) - 0.5) * 4;
    topContour.push([f.x + f.nx * (r + wobble), f.y + f.ny * (r + wobble)]);
    botContour.push([f.x - f.nx * (r - wobble), f.y - f.ny * (r - wobble)]);
  }
  for (let i = 0; i < topContour.length; i++) polyPts.push(topContour[i]);
  for (let i = botContour.length - 1; i >= 0; i--) polyPts.push(botContour[i]);

  // 1. Opaque Wash & Watercolor Underpainting
  brush.noStroke();
  brush.wash(opts.baseColor || PAL.sienna, opts.baseAlpha || 185);
  drawFilledPoly(polyPts, 0.25);
  brush.noWash();

  // Shadow half polygon
  let shadowPoly = [];
  for (let i = 0; i <= 16; i++) {
    let t = i / 16;
    let f = evalPolyline(spinePts, t);
    let r = evalRadius(radii, t);
    let u0 = flipLight ? -0.95 : 0.05;
    shadowPoly.push([f.x + f.nx * r * u0, f.y + f.ny * r * u0]);
  }
  for (let i = 16; i >= 0; i--) {
    let t = i / 16;
    let f = evalPolyline(spinePts, t);
    let r = evalRadius(radii, t);
    let u1 = flipLight ? -0.05 : 0.98;
    shadowPoly.push([f.x + f.nx * r * u1, f.y + f.ny * r * u1]);
  }
  brush.fill(opts.shadowColor || PAL.blackChar, opts.shadowAlpha || 125);
  brush.fillBleed(0.18, "in");
  brush.fillTexture(0.55, 0.35);
  drawFilledPoly(shadowPoly, 0.25);
  brush.noFill();

  // 2. Cross-Contour 3D Ring Hatching across the cylinder
  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let f = evalPolyline(spinePts, t);
    let r = evalRadius(radii, t);
    let jitterT = (random() - 0.5) * 0.015;
    let ft = evalPolyline(spinePts, constrain(t + jitterT, 0, 1));

    // Helper to build a 3D curved cross-contour arc between uStart and uEnd
    let makeArc = (uStart, uEnd, segs = 6) => {
      let pts = [];
      for (let s = 0; s <= segs; s++) {
        let u = lerp(uStart, uEnd, s / segs);
        let z = sqrt(max(0, 1 - u * u));
        let bow = z * r * bulgeAmt * bulgeDir;
        let px = ft.x + ft.nx * (u * r) + ft.tx * bow;
        let py = ft.y + ft.ny * (u * r) + ft.ty * bow;
        let pr = sin((s / segs) * 180) * 1.1 + 0.25;
        pts.push([px, py, pr]);
      }
      return pts;
    };

    let sgn = flipLight ? -1 : 1;

    // A. Terre Verte Reflected Light on Underside Edge
    if (i % 2 === 0) {
      brush.set("sculpt_hatch", i % 4 === 0 ? PAL.terreMid : PAL.terreVerte, 0.85);
      brush.spline(makeArc(0.62 * sgn, 0.98 * sgn, 5), 0.45);
    }

    // B. Deep Core Shadow & Burnt Sienna Dark Zone
    brush.set("sculpt_hatch", i % 3 === 0 ? PAL.siennaDark : PAL.black, 0.95);
    brush.spline(makeArc(0.12 * sgn, 0.82 * sgn, 6), 0.45);

    if (i % 2 === 1) {
      brush.set("mural_charcoal", PAL.blackDeep, 0.65);
      brush.spline(makeArc(0.25 * sgn, 0.72 * sgn, 5), 0.45);
    }

    // C. Burnt Sienna & Indian Red Halftone Transition
    brush.set("sculpt_hatch", i % 2 === 0 ? PAL.sienna : PAL.indianRed, 0.8);
    brush.spline(makeArc(-0.42 * sgn, 0.32 * sgn, 6), 0.45);

    // D. Maize Yellow & Flour Dust Lit Ridge
    brush.set("sculpt_hatch", i % 3 === 0 ? PAL.maizeBright : PAL.maize, 0.8);
    brush.spline(makeArc(-0.92 * sgn, -0.18 * sgn, 6), 0.45);

    if (opts.flourHighlight && i % 2 === 0) {
      brush.set("flour_chalk", i % 4 === 0 ? PAL.flour : PAL.maizePale, 0.72);
      brush.spline(makeArc(-0.86 * sgn, -0.32 * sgn, 5), 0.45);
    }
  }

  // 3. Longitudinal Muscle-Fiber / Rhombic Cross-Hatching
  let longStrands = opts.longStrands || 18;
  for (let k = 0; k < longStrands; k++) {
    let u = map(k, 0, longStrands - 1, -0.88, 0.88);
    let sgn = flipLight ? -1 : 1;
    let uOriented = u * sgn;
    let col = PAL.sienna;
    let br = "sculpt_hatch";
    let w = 0.65;
    if (uOriented > 0.25) {
      col = k % 3 === 0 ? PAL.terreDark : PAL.black;
      w = 0.8;
    } else if (uOriented > -0.2) {
      col = k % 2 === 0 ? PAL.indianRed : PAL.siennaDark;
      w = 0.7;
    } else {
      col = k % 2 === 0 ? PAL.maize : PAL.siennaLight;
      w = 0.6;
    }
    brush.set(br, col, w);
    let strandPts = [];
    for (let s = 0; s <= 12; s++) {
      let t = s / 12;
      let f = evalPolyline(spinePts, t);
      let r = evalRadius(radii, t);
      let wave = sin(t * 360 + k * 35) * 0.05;
      let uu = constrain(u + wave, -0.95, 0.95);
      strandPts.push([f.x + f.nx * uu * r, f.y + f.ny * uu * r, 0.35 + sin(t * 180) * 0.75]);
    }
    brush.spline(strandPts, 0.35);
  }

  // 4. Broad, Swelling Contour Lines Enclosing the Form
  if (opts.drawContours !== false) {
    brush.set("swelling_contour", PAL.blackDeep, opts.contourWeight || 1.05);
    brush.spline(topContour, 0.35);
    brush.set("swelling_contour", PAL.blackDeep, (opts.contourWeight || 1.05) * 1.15);
    brush.spline(botContour, 0.35);

    // Secondary warm sienna inner contour
    brush.set("mural_charcoal", PAL.siennaDark, 0.7);
    let innerTop = topContour.map(p => [p[0] + 2, p[1] + 3, 0.7]);
    brush.spline(innerTop, 0.35);
  }
}

