// ============================================================================
// 4. THE SMOKING COMAL, HEARTH EMBERS & COOKING TORTILLAS
// ============================================================================

function drawEllipseRing(cx, cy, rx, ry, numPts = 40) {
  let pts = [];
  for (let i = 0; i < numPts; i++) {
    let a = (i / numPts) * 360;
    pts.push([cx + cos(a) * rx, cy + sin(a) * ry]);
  }
  return pts;
}

function drawTortillaDisc(cx, cy, rx, ry, opts = {}) {
  let puff = opts.puff || 0;
  let thickness = opts.thickness || 9;
  let rot = opts.rot || 0;

  // Bottom rim thickness (cast shadow + toasted edge)
  let botPts = [];
  let topPts = [];
  let steps = 36;
  for (let i = 0; i < steps; i++) {
    let a = (i / steps) * 360;
    let radMod = 1 + (noise(cx * 0.02 + cos(a) * 1.5, cy * 0.02 + sin(a) * 1.5) - 0.5) * 0.08;
    let x = cx + cos(a + rot) * rx * radMod;
    let y = cy + sin(a + rot) * ry * radMod;
    // Slight dome puff on top half
    let domeOffset = sin(a) < 0 ? sin(a) * puff : 0;
    topPts.push([x, y + domeOffset]);
    botPts.push([x, y + thickness]);
  }

  // Cast shadow on comal or tortilla below
  brush.noStroke();
  brush.wash(PAL.blackDeep, 195);
  let shadowPts = botPts.map(p => [p[0] + 4, p[1] + 5]);
  drawFilledPoly(shadowPts, 0.25);

  // Edge thickness band
  brush.wash(PAL.siennaDark, 230);
  drawFilledPoly(botPts, 0.25);

  // Main masa top surface
  brush.wash(opts.baseColor || PAL.maizePale, 240);
  drawFilledPoly(topPts, 0.25);
  brush.noWash();

  // Golden toasted patches & Terre Verte / Sienna shading
  brush.fillBleed(0.22, "in");
  brush.fill(PAL.maize, 130);
  drawFilledPoly(drawEllipseRing(cx + rx * 0.08, cy - puff * 0.3, rx * 0.82, ry * 0.78, 24), 0.3);
  if (puff > 8) {
    // Shadow around base of puffed dome
    brush.fill(PAL.sienna, 115);
    drawFilledPoly(drawEllipseRing(cx, cy + ry * 0.15, rx * 0.75, ry * 0.65, 24), 0.3);
  }
  brush.noFill();

  // Sculptural cross-contour hatching across the tortilla surface (showing flat or puffed dome)
  let hatchCount = opts.hatchCount || 28;
  for (let i = 0; i < hatchCount; i++) {
    let u = map(i, 0, hatchCount - 1, -0.9, 0.9);
    let halfW = sqrt(max(0, 1 - u * u)) * rx * 0.92;
    let yBase = cy + u * ry * 0.9;
    let domeLift = (1 - u * u) * puff * 0.85;
    let col = i % 3 === 0 ? PAL.maizeDeep : (u < 0 ? PAL.flour : PAL.siennaLight);
    brush.set("sculpt_hatch", col, 0.68);
    brush.spline([
      [cx - halfW, yBase, 0.3],
      [cx, yBase - domeLift, 1.0],
      [cx + halfW, yBase, 0.3]
    ], 0.35);
  }

  // Hyperreal Char Spots (blistered Lamp Black centers with Burnt Sienna & Indian Red halos)
  let charSpots = opts.charSpots || 22;
  for (let c = 0; c < charSpots; c++) {
    let rFrac = sqrt(random(0.04, 0.82));
    let ang = random(360);
    let sx = cx + cos(ang) * rx * rFrac;
    let sy = cy + sin(ang) * ry * rFrac - (1 - rFrac * rFrac) * puff * 0.7;
    let spotRx = random(3.5, 13) * (1 - rFrac * 0.3);
    let spotRy = spotRx * (ry / rx) * random(0.9, 1.35);

    // Toasted sienna/Indian red blister halo
    brush.noStroke();
    brush.wash(c % 2 === 0 ? PAL.sienna : PAL.indianRed, 195);
    drawFilledPoly(drawEllipseRing(sx, sy, spotRx * 1.45, spotRy * 1.45, 12), 0.3);
    // Crisp Lamp Black char center
    brush.wash(PAL.blackDeep, 240);
    drawFilledPoly(drawEllipseRing(sx, sy, spotRx, spotRy, 12), 0.3);
    brush.noWash();

    // Blister rim highlight (maize/flour)
    brush.set("sculpt_hatch", PAL.maizePale, 0.65);
    brush.arc(sx, sy, spotRx * 1.2, -160, -20);
  }

  // Masa grain & flour stipple
  brush.set("dust_stipple", PAL.flour, 0.85);
  for (let s = 0; s < 16; s++) {
    let a = random(360);
    let d = random(0.1, 0.85);
    brush.line(
      cx + cos(a) * rx * d, cy + sin(a) * ry * d,
      cx + cos(a) * rx * d + 8, cy + sin(a) * ry * d + 2
    );
  }

  // Swelling organic tortilla rim contour
  brush.set("swelling_contour", PAL.blackDeep, 0.85);
  brush.spline([...topPts, topPts[0]], 0.3);
  brush.set("mural_charcoal", PAL.siennaDark, 0.75);
  brush.spline(botPts.slice(0, floor(steps * 0.55)), 0.3);
}

function drawComalAndCookingTortillas() {
  let comalCx = 650;
  let comalCy = 918;
  let comalRx = 485;
  let comalRy = 148;

  // 1. Hearth Stones & Glowing Embers Underneath the Comal
  brush.noStroke();
  brush.wash(PAL.blackDeep, 245);
  drawFilledPoly([[160, 930], [1145, 930], [1160, 1165], [140, 1165]], 0.2);
  brush.noWash();

  // Glowing Maize Yellow, Burnt Sienna & Indian Red firelight beneath comal rim
  brush.fillBleed(0.32, "out");
  brush.fill(PAL.indianRed, 175);
  drawFilledPoly([[320, 995], [980, 995], [1040, 1145], [260, 1145]], 0.3);
  brush.fill(PAL.siennaWarm, 185);
  drawFilledPoly([[380, 1015], [920, 1015], [960, 1125], [340, 1125]], 0.3);
  brush.fill(PAL.maizeBright, 200);
  drawFilledPoly([[450, 1030], [850, 1030], [880, 1100], [420, 1100]], 0.3);
  brush.noFill();

  // Ember hatching & blackened hearth stones (tenamaztles)
  for (let i = 0; i < 65; i++) {
    let x = random(280, 1020);
    let y = random(1005, 1135);
    let col = abs(x - 650) < 220
      ? (random() < 0.5 ? PAL.maizeBright : PAL.siennaLight)
      : (random() < 0.6 ? PAL.blackDeep : PAL.indianDark);
    brush.set("mural_charcoal", col, random(0.8, 1.5));
    brush.line(x, y, x + random(-35, 35), y + random(-12, 12));
  }

  // 2. Comal Outer Clay Rim & Soot-Blackened Surface
  let outerRim = drawEllipseRing(comalCx, comalCy + 16, comalRx + 16, comalRy + 18, 48);
  let innerBed = drawEllipseRing(comalCx, comalCy, comalRx, comalRy, 48);

  brush.noStroke();
  brush.wash(PAL.siennaDark, 240);
  drawFilledPoly(outerRim, 0.25);
  brush.wash(PAL.blackDeep, 245);
  drawFilledPoly(innerBed, 0.25);
  brush.noWash();

  // Concentric iron/clay surface texture, lime-water residue & soot char on comal
  for (let r = 0.15; r <= 0.98; r += 0.032) {
    let aStart = random(0, 360);
    let aSpan = random(70, 220);
    let pts = [];
    for (let s = 0; s <= 14; s++) {
      let a = aStart + (s / 14) * aSpan;
      pts.push([
        comalCx + cos(a) * comalRx * r,
        comalCy + sin(a) * comalRy * r,
        0.3 + sin((s / 14) * 180) * 0.8
      ]);
    }
    let col = r > 0.82
      ? (random() < 0.5 ? PAL.sienna : PAL.terreDark)
      : (random() < 0.35 ? PAL.terrePale : (random() < 0.5 ? PAL.plasterDark : PAL.blackChar));
    brush.set("sculpt_hatch", col, random(0.65, 1.1));
    brush.spline(pts, 0.35);
  }

  // Front lip of the comal rim catching warm firelight from below and flour dust on top
  for (let i = 0; i < 36; i++) {
    let a = map(i, 0, 35, 12, 168);
    let x1 = comalCx + cos(a) * comalRx;
    let y1 = comalCy + sin(a) * comalRy;
    let x2 = comalCx + cos(a) * (comalRx + 16);
    let y2 = comalCy + 16 + sin(a) * (comalRy + 18);
    brush.set("sculpt_hatch", i % 2 === 0 ? PAL.siennaLight : PAL.maize, 0.9);
    brush.line(x1, y1, x2, y2);
  }
  brush.set("swelling_contour", PAL.blackDeep, 1.35);
  brush.spline([...outerRim, outerRim[0]], 0.3);
  brush.set("flour_chalk", PAL.maizePale, 0.9);
  brush.spline(innerBed.slice(2, 24), 0.3);

  // 3. Three Tortillas Cooking on the Comal
  // Back-left tortilla
  drawTortillaDisc(425, 836, 118, 36, {
    puff: 6,
    thickness: 7,
    charSpots: 18,
    hatchCount: 22
  });

  // Right-side puffing tortilla (domed high with hot steam inside)
  drawTortillaDisc(915, 902, 144, 48, {
    puff: 26,
    thickness: 9,
    charSpots: 28,
    hatchCount: 30
  });

  // Center foreground tortilla (being actively pressed by her heroic hands)
  drawTortillaDisc(608, 868, 174, 55, {
    puff: 4,
    thickness: 10,
    charSpots: 32,
    hatchCount: 34
  });
}

