function drawSteamAndFlourDust() {
  // Rhythmic Diagonal Plumes of Steam rising from the Comal toward Upper-Right
  let steamPlumes = [
    // Main heroic plume rising from right tortilla & hands up to top-right
    {
      spine: [[895, 885], [835, 740], [925, 555], [855, 365], [985, 195], [1085, 65]],
      radii: [32, 68, 92, 115, 135, 150]
    },
    // Central plume rising from beneath her pressing hands past her right shoulder
    {
      spine: [[615, 835], [665, 695], [755, 520], [720, 330], [835, 155], [935, 45]],
      radii: [26, 54, 76, 95, 112, 125]
    },
    // Left-center secondary wisp rising from back-left tortilla and stacked tortillas
    {
      spine: [[415, 825], [475, 685], [565, 535], [645, 375], [715, 205]],
      radii: [20, 42, 58, 72, 85]
    }
  ];

  // 1. Batched Translucent Steam Watercolor Washes
  brush.noStroke();
  brush.fillBleed(0.35, "out");
  brush.fillTexture(0.6, 0.25);

  for (let p of steamPlumes) {
    let leftEdge = [];
    let rightEdge = [];
    for (let i = 0; i <= 18; i++) {
      let t = i / 18;
      let f = evalPolyline(p.spine, t);
      let r = evalRadius(p.radii, t) * (0.7 + 0.4 * sin(t * 540));
      leftEdge.push([f.x + f.nx * r, f.y + f.ny * r]);
      rightEdge.push([f.x - f.nx * r, f.y - f.ny * r]);
    }
    let poly = [...leftEdge, ...rightEdge.reverse()];
    brush.fill(PAL.flour, 38);
    drawFilledPoly(poly, 0.35);
    brush.fill(PAL.terrePale, 28);
    drawFilledPoly(poly, 0.35);
  }
  brush.noFill();

  // 2. Sculptural Charcoal & Chalk Curling Vapor Ribbons
  for (let pIdx = 0; pIdx < steamPlumes.length; pIdx++) {
    let p = steamPlumes[pIdx];
    let ribbonCount = 46;
    for (let rIdx = 0; rIdx < ribbonCount; rIdx++) {
      let uBase = map(rIdx, 0, ribbonCount - 1, -1.0, 1.0);
      let tStart = random(0, 0.55);
      let tEnd = constrain(tStart + random(0.32, 0.65), 0.15, 1.0);
      let pts = [];
      let segs = 10;
      for (let s = 0; s <= segs; s++) {
        let t = lerp(tStart, tEnd, s / segs);
        let f = evalPolyline(p.spine, t);
        let rad = evalRadius(p.radii, t);
        let swirl = sin(t * 520 + rIdx * 40) * 0.48;
        let u = uBase + swirl;
        let px = f.x + f.nx * (u * rad);
        let py = f.y + f.ny * (u * rad);
        let pr = sin((s / segs) * 180) * 1.15 + 0.2;
        pts.push([px, py, pr]);
      }

      // Interleave bright flour/maize chalk highlights with terre-verte halftones and dark charcoal eddies
      if (rIdx % 5 === 0) {
        // Negative-space charcoal eddy that gives the steam 3D volume
        brush.set("mural_charcoal", PAL.blackChar, 0.72);
      } else if (uBase < -0.15) {
        brush.set("flour_chalk", rIdx % 2 === 0 ? PAL.flour : PAL.maizePale, 0.85);
      } else if (uBase < 0.35) {
        brush.set("sculpt_hatch", rIdx % 2 === 0 ? PAL.plaster : PAL.terrePale, 0.75);
      } else {
        brush.set("sculpt_hatch", PAL.terreMid, 0.7);
      }
      brush.spline(pts, 0.45);
    }
  }

  // 3. Airborne Flour Dust & Luminous Hearth Motes along the Diagonal
  for (let i = 0; i < 140; i++) {
    let t = random(0, 1);
    let baseX = lerp(160, 1080, t) + random(-180, 180);
    let baseY = lerp(1040, 120, t) + random(-140, 140);
    if (baseX > 50 && baseX < 1150 && baseY > 50 && baseY < 1140) {
      let col = i % 4 === 0 ? PAL.maizeBright : PAL.flour;
      brush.set("dust_stipple", col, random(0.65, 1.35));
      brush.line(baseX, baseY, baseX + random(4, 14), baseY - random(2, 10));
    }
  }
}

