// ============================================================================
// ANATOMICAL COORDINATE SYSTEM & GEOMETRY HELPERS
// ============================================================================

const EX = 496;
const EY = 334;
const R_MAX = 42;
const M_COLS = 16;

// Anterior (front) profile control points: top of cere -> lores -> chin -> throat -> puffed breast
const LEFT_PROFILE = [
  { s: 0.00, x: 330, y: 302 },
  { s: 0.06, x: 322, y: 362 },
  { s: 0.13, x: 332, y: 434 },
  { s: 0.21, x: 386, y: 498 },
  { s: 0.30, x: 372, y: 576 },
  { s: 0.45, x: 318, y: 702 },
  { s: 0.65, x: 254, y: 878 },
  { s: 0.85, x: 210, y: 1062 },
  { s: 1.00, x: 192, y: 1225 },
  { s: 1.10, x: 184, y: 1320 }
];

// Posterior (back) profile control points: occiput -> nape -> dorsal neck curve
const RIGHT_PROFILE = [
  { s: 0.00, x: 758, y: 226 },
  { s: 0.08, x: 830, y: 304 },
  { s: 0.16, x: 884, y: 394 },
  { s: 0.28, x: 940, y: 516 },
  { s: 0.45, x: 1006, y: 676 },
  { s: 0.65, x: 1078, y: 866 },
  { s: 0.85, x: 1142, y: 1056 },
  { s: 1.00, x: 1186, y: 1225 },
  { s: 1.10, x: 1212, y: 1320 }
];

function evalProfile(pts, s) {
  let sc = constrain(s, pts[0].s, pts[pts.length - 1].s);
  let idx = 0;
  for (let i = 0; i < pts.length - 1; i++) {
    if (sc >= pts[i].s && sc <= pts[i + 1].s) {
      idx = i;
      break;
    }
  }
  let p0 = pts[max(0, idx - 1)];
  let p1 = pts[idx];
  let p2 = pts[idx + 1];
  let p3 = pts[min(pts.length - 1, idx + 2)];
  let t = (sc - p1.s) / max(0.0001, p2.s - p1.s);
  let t2 = t * t;
  let t3 = t2 * t;
  // Catmull-Rom spline evaluation
  let x = 0.5 * (
    (2 * p1.x) +
    (-p0.x + p2.x) * t +
    (2 * p0.x - 5 * p1.x + 4 * p2.x - p3.x) * t2 +
    (-p0.x + 3 * p1.x - 3 * p2.x + p3.x) * t3
  );
  let y = 0.5 * (
    (2 * p1.y) +
    (-p0.y + p2.y) * t +
    (2 * p0.y - 5 * p1.y + 4 * p2.y - p3.y) * t2 +
    (-p0.y + 3 * p1.y - 3 * p2.y + p3.y) * t3
  );
  return { x, y };
}

function rowToS(r) {
  let rn = max(0, (r + 1.2) / (R_MAX + 1.2));
  return Math.pow(rn, 1.28) * 1.04 - 0.015;
}

// Maps continuous (s_row, u) in [0, 1] x [0, 1] to 2D canvas coordinates
function mapSurface(s, u) {
  let uc = constrain(u, 0, 1);
  // Blend cylindrical foreshortening near silhouette edges with linear interior
  let theta = (uc - 0.5) * Math.PI * 0.92;
  let uCyl = (Math.sin(theta) / Math.sin(0.46 * Math.PI) + 1) * 0.5;
  let uEff = lerp(uc, uCyl, 0.68);

  let pL = evalProfile(LEFT_PROFILE, s);
  let pR = evalProfile(RIGHT_PROFILE, s);

  let bx = lerp(pL.x, pR.x, uEff);
  let by = lerp(pL.y, pR.y, uEff);

  // Cranial dome arch near s = 0 transitions smoothly to downward neck catenary dip for s > 0.16
  let domeWeight = Math.exp(-Math.pow(max(0, s + 0.015) / 0.105, 1.65));
  let neckWeight = constrain((s - 0.14) / 0.86, 0, 1);

  let sinArch = Math.sin(uEff * Math.PI);
  let dyDome = -114 * Math.pow(sinArch, 0.82) * domeWeight;
  let dxDome = -24 * Math.sin(uEff * Math.PI * 2) * domeWeight;

  // Neck catenary dip follows the 3D puffed cylinder
  let dipAmp = 76 * Math.pow(neckWeight, 0.88);
  let dyNeck = dipAmp * Math.pow(sinArch, 0.95);
  let dxNeck = -14 * Math.sin(uEff * Math.PI) * neckWeight;

  return {
    x: bx + dxDome + dxNeck,
    y: by + dyDome + dyNeck
  };
}

// Maps lattice (r, c) with subtle organic feather variation
function mapLattice(r, c) {
  let s = rowToS(r);
  let u = constrain(c / M_COLS, 0, 1);
  let pt = mapSurface(s, u);
  let edgeFade = Math.sin(u * Math.PI);
  let nX = (noise(r * 0.35 + 10, c * 0.35 + 20) - 0.5) * 3.2 * edgeFade;
  let nY = (noise(r * 0.35 + 50, c * 0.35 + 80) - 0.5) * 3.2 * edgeFade;
  return { x: pt.x + nX, y: pt.y + nY, s, u };
}

// Normalized elliptical distance to the eye center (1.0 = outer edge of orbital skin ring)
function getEyeDist(x, y) {
  let dx = x - EX;
  let dy = y - EY;
  let ang = -8 * Math.PI / 180;
  let rx = dx * Math.cos(ang) - dy * Math.sin(ang);
  let ry = dx * Math.sin(ang) + dy * Math.cos(ang);
  return Math.sqrt((rx / 71) * (rx / 71) + (ry / 66) * (ry / 66));
}

