// Continuous soap-bubble phase field across the neck
function getThinFilmPhase(s, u) {
  // Base progression down the neck following feather curvature
  let p = (s - 0.14) * 5.2;
  // Soap-bubble wave modulation across neck curvature
  p += 0.38 * Math.sin(u * Math.PI * 2.0 - 0.4) * Math.sin(s * 9.0);
  p += 0.24 * Math.cos(u * Math.PI * 3.2 + s * 6.5);

  // Vortex swirl 1 on upper-mid puffed neck
  let d1s = (s - 0.42) * 2.4;
  let d1u = (u - 0.38) * 1.8;
  let r1 = Math.sqrt(d1s * d1s + d1u * d1u);
  p += 0.65 * Math.exp(-r1 * r1 * 3.2) * Math.cos(r1 * 5.5);

  // Vortex swirl 2 on lower-mid neck
  let d2s = (s - 0.74) * 2.2;
  let d2u = (u - 0.56) * 1.7;
  let r2 = Math.sqrt(d2s * d2s + d2u * d2u);
  p += 0.72 * Math.exp(-r2 * r2 * 2.8) * Math.sin(r2 * 5.0 + 0.8);

  // Subtle organic Perlin drift
  p += 0.32 * (noise(s * 3.5 + 4, u * 3.5 + 9) - 0.5);
  return p;
}

function getFilmColorIdx(phase) {
  let cyc = ((phase % 1.0) + 1.0) % 1.0;
  return Math.floor(cyc * 4) % 4;
}

