  // 6. Powdery white cere & dark horn beak in hard graphite
  drawBeakAndCere();

  // 7. Fleshy orbital skin ring, glassy amber iris ring, and hard white highlight
  drawGlassyAmberEye();

  noLoop();
}

// ============================================================================
// STEP 1 & 2: BACKGROUND & PIGEON UNDERPAINTING
// ============================================================================

function drawSlateBackgroundGround() {
  // Subtle matte slate-grey wash on background so the plain slate grey feels rich and grounded
  brush.noStroke();
  brush.noFill();
  brush.wash("#626D78", 95);
  brush.rect(0, 0, width, height, "corner");
  brush.noWash();
}

function getHeadNeckSilhouettePoints() {
  let pts = [];
  // Top dome from forehead (s=0, u=0) over crown to occiput (s=0, u=1)
  for (let i = 0; i <= 28; i++) {
    let u = i / 28;
    pts.push(mapSurface(0.0, u));
  }
  // Down posterior (right) neck contour
  for (let i = 1; i <= 36; i++) {
    let s = (i / 36) * 1.02;
    pts.push(mapSurface(s, 1.0));
  }
  // Up anterior (left) breast, throat, chin, and lores contour
  for (let i = 36; i >= 1; i--) {
    let s = (i / 36) * 1.02;
    pts.push(mapSurface(s, 0.0));
  }
  return pts;
}

function drawPigeonUnderpainting() {
  let silPts = getHeadNeckSilhouettePoints();

  // Opaque warm ivory/dove-paper base so transparent watercolors glow over the neck
  brush.noStroke();
  brush.noFill();
  brush.wash("#ECE9E2", 250);
  brush.beginShape(0.2);
  for (let p of silPts) {
    brush.vertex(p.x, p.y);
  }
  brush.endShape(CLOSE);
  brush.noWash();

  // Soft dove-grey watercolor shading on the head, cheek, and cylinder edges
  brush.noStroke();
  brush.fillBleed(0.22, "in");
  brush.fillTexture(0.45, 0.35);

  // Head and cheek soft pastel dove-grey undertone
  brush.fill("#C8CDD4", 75);
  brush.beginShape(0.35);
  for (let i = 0; i <= 20; i++) {
    let p = mapSurface(0.0, i / 20);
    brush.vertex(p.x, p.y);
  }
  for (let i = 0; i <= 10; i++) {
    let p = mapSurface(0.16, 1.0 - i / 10);
    brush.vertex(p.x, p.y);
  }
  brush.endShape(CLOSE);

  // Right dorsal neck cylinder turn shading
  brush.fill("#BEC4CC", 65);
  brush.beginShape(0.3);
  for (let i = 0; i <= 24; i++) {
    let s = (i / 24) * 1.0;
    let p = mapSurface(s, 1.0);
    brush.vertex(p.x, p.y);
  }
  for (let i = 24; i >= 0; i--) {
    let s = (i / 24) * 1.0;
    let p = mapSurface(s, 0.76);
    brush.vertex(p.x, p.y);
  }
  brush.endShape(CLOSE);

  // Left throat hollow & lower breast edge turn shading
  brush.fill("#C4C9D1", 60);
  brush.beginShape(0.3);
  for (let i = 0; i <= 24; i++) {
    let s = 0.12 + (i / 24) * 0.88;
    let p = mapSurface(s, 0.0);
    brush.vertex(p.x, p.y);
  }
  for (let i = 24; i >= 0; i--) {
    let s = 0.12 + (i / 24) * 0.88;
    let p = mapSurface(s, 0.20);
    brush.vertex(p.x, p.y);
  }
  brush.endShape(CLOSE);

  brush.noFill();
}

// ============================================================================
// STEP 3: TRANSPARENT WATERCOLOUR THIN-FILM BANDS & EDGE POOLING
// ============================================================================

function getBandCurveS(sBase, u) {
  // Soap-bubble thin-film wave & swirl distortion along the feather curvature
  let wave1 = 0.022 * Math.sin(u * Math.PI * 2.0 + sBase * 11.0);
  let wave2 = 0.014 * Math.cos(u * Math.PI * 3.0 - sBase * 8.5);
  // Swirl pinch around mid-neck soap-bubble centers
  let d1 = Math.hypot((sBase - 0.42) * 2.0, (u - 0.38) * 1.6);
  let swirl1 = 0.028 * Math.exp(-d1 * d1 * 4.0) * Math.sin(u * Math.PI * 4.0);
  let d2 = Math.hypot((sBase - 0.74) * 2.0, (u - 0.56) * 1.6);
  let swirl2 = -0.030 * Math.exp(-d2 * d2 * 3.8) * Math.cos(u * Math.PI * 3.5);
  return sBase + wave1 + wave2 + swirl1 + swirl2;
}

function drawThinFilmWatercolourBands() {
  brush.noStroke();

  // Group flowing soap-bubble bands by our 4 thin-film colors for optimal watercolor caching
  let primaryBatches = [[], [], [], []];
  let secondaryBatches = [[], [], [], []];
  let poolBatches = [[], [], [], []];

  // A. Construct 28 curving thin-film bands flowing across the neck (s from 0.14 to 1.02)
  const N_BANDS = 28;
  for (let b = 0; b < N_BANDS; b++) {
    let s0 = 0.145 + (b / N_BANDS) * 0.875;
    let s1 = 0.145 + ((b + 1.18) / N_BANDS) * 0.875; // slight overlap so bands bleed softly where they meet

    // Split each band into 2 lateral soap-bubble segments so color can shift along the band swirl
    for (let seg = 0; seg < 2; seg++) {
      let uStart = seg === 0 ? 0.01 : 0.44;
      let uEnd = seg === 0 ? 0.56 : 0.99;
      let uMid = 0.5 * (uStart + uEnd);
      let sMid = 0.5 * (s0 + s1);

      let phase = getThinFilmPhase(sMid, uMid);
      let cIdx = getFilmColorIdx(phase);

      let poly = [];
      let steps = 14;
      for (let i = 0; i <= steps; i++) {
        let u = lerp(uStart, uEnd, i / steps);
        let sc = getBandCurveS(s0, u);
        poly.push(mapSurface(sc, u));
      }
      for (let i = steps; i >= 0; i--) {
        let u = lerp(uStart, uEnd, i / steps);
        let sc = getBandCurveS(s1, u);
        poly.push(mapSurface(sc, u));
      }
      primaryBatches[cIdx].push(poly);
    }
  }

  // B. Add 6 swirling soap-bubble vortex eyes (nested elliptical thin-film rings on the neck)
  const swirls = [
    { s: 0.34, u: 0.34, rs: 0.055, ru: 0.18, cIdx: 1 }, // Magenta swirl
    { s: 0.34, u: 0.34, rs: 0.028, ru: 0.09, cIdx: 2 }, // Bronze core
    { s: 0.55, u: 0.62, rs: 0.065, ru: 0.21, cIdx: 3 }, // Bottle green swirl
    { s: 0.55, u: 0.62, rs: 0.032, ru: 0.10, cIdx: 0 }, // Violet core
    { s: 0.79, u: 0.42, rs: 0.070, ru: 0.22, cIdx: 0 }, // Violet swirl
    { s: 0.79, u: 0.42, rs: 0.035, ru: 0.11, cIdx: 1 }  // Magenta core
  ];

  for (let sw of swirls) {
    let poly = [];
    let steps = 20;
    for (let i = 0; i < steps; i++) {
      let ang = (i / steps) * Math.PI * 2;
      let s = sw.s + Math.sin(ang) * sw.rs + 0.008 * Math.cos(ang * 2);
      let u = sw.u + Math.cos(ang) * sw.ru;
      poly.push(mapSurface(s, constrain(u, 0.03, 0.97)));
    }
    secondaryBatches[sw.cIdx].push(poly);
  }

  // C. Construct scalloped feather-edge watercolor pooling ribbons along feather rows
  for (let r = 9; r <= R_MAX - 1; r++) {
    let isOdd = (r % 2) === 1;
    let cStart = isOdd ? 1 : 0;
    let cEnd = isOdd ? M_COLS - 1 : M_COLS - 1;

    // Group into pairs of adjacent feathers so watercolor pools right along the scalloped tips
    for (let c = cStart; c <= cEnd; c += 2) {
      let cCenter = isOdd ? c : c + 0.5;
      if (cCenter < 0.6 || cCenter > M_COLS - 0.6) continue;

      let sSample = rowToS(r + 0.6);
      let uSample = cCenter / M_COLS;
      let cIdx = getFilmColorIdx(getThinFilmPhase(sSample, uSample));

      // Crescent polygon hugging the distal lower margin of feather (r, cCenter)
      let poly = [];
      // Outer lower rim from left corner through tip to right corner
      for (let k = -4; k <= 4; k++) {
        let frac = k / 4; // -1 to 1
        let sRim = 1.0 - Math.abs(frac);
        let colF = cCenter + Math.sign(frac) * 0.46 * (1 - Math.pow(sRim, 1.65));
        let rowF = r + Math.pow(sRim, 0.78);
        poly.push(mapLattice(rowF, colF));
      }
      // Inner crescent edge slightly higher up inside the feather tip
      for (let k = 4; k >= -4; k--) {
        let frac = k / 4;
        let sRim = 1.0 - Math.abs(frac);
        let colF = cCenter + Math.sign(frac) * 0.42 * (1 - Math.pow(sRim, 1.65));
        let rowF = r - 0.28 + Math.pow(sRim, 0.78) * 0.88;
        poly.push(mapLattice(rowF, colF));
      }
      poolBatches[cIdx].push(poly);
    }
  }

  // Execute batched watercolor passes:
  // Pass 1: Softly bleeding soap-bubble thin-film bands
  brush.fillBleed(0.34, "out");
  brush.fillTexture(0.55, 0.42);
  for (let cIdx = 0; cIdx < 4; cIdx++) {
    brush.fill(FILM_PALETTE[cIdx].wash, 82);
    for (let poly of primaryBatches[cIdx]) {
      brush.beginShape(0.45);
      for (let pt of poly) {
        brush.vertex(pt.x, pt.y);
      }
      brush.endShape(CLOSE);
    }
  }

  // Pass 2: Soap-bubble swirl cores with luminous pastel glow
  brush.fillBleed(0.38, "out");
  brush.fillTexture(0.50, 0.40);
  for (let cIdx = 0; cIdx < 4; cIdx++) {
    brush.fill(FILM_PALETTE[cIdx].washLight, 92);
    for (let poly of secondaryBatches[cIdx]) {
      brush.beginShape(0.5);
      for (let pt of poly) {
        brush.vertex(pt.x, pt.y);
      }
      brush.endShape(CLOSE);
    }
  }

  // Pass 3: Pooled pigment at feather edges (high border intensity, inward bleed)
  brush.fillBleed(0.14, "in");
  brush.fillTexture(0.78, 0.88);
  for (let cIdx = 0; cIdx < 4; cIdx++) {
    brush.fill(FILM_PALETTE[cIdx].pool, 56);
    for (let poly of poolBatches[cIdx]) {
      brush.beginShape(0.35);
      for (let pt of poly) {
        brush.vertex(pt.x, pt.y);
      }
      brush.endShape(CLOSE);
    }
  }

  brush.noFill();
}

// ============================================================================
// STEP 4: HARD GRAPHITE FEATHER MAPPING & PHOTOGRAPHIC BARBS
// ============================================================================

function drawAllFeathersAndBarbs() {
  // Batch strokes by brush & tonal value to keep rendering fast and crisp
  let barbDark = [];     // Deep shadow barbs under overlaps (#262B31)
  let barbMidDark = [];  // Crisp structural graphite barbs (#414750)
  let barbMidLight = []; // Delicate hard 2H graphite barbs (#636B75)
  let barbSheen = [];    // Silvery specular highlight barbs (#F4F2EE)
  let filmSheenBatches = [[], [], [], []]; // Iridescent pastel barb highlights on neck
  let wcPoolRims = [[], [], [], []];       // Watercolor pooled rim curves at feather tips

  let tuckShadows = [];  // 2B graphite shadow creases under overlapping upper feathers
  let rachisDark = [];   // Central feather shafts in hard graphite
  let rachisLight = [];  // Specular highlight beside each shaft
  let rimDark = [];      // Mapped hard-graphite distal feather edges (shadow side)
  let rimMid = [];       // Mapped hard-graphite distal feather edges (lit side)

  for (let r = 0; r <= R_MAX; r++) {
    let isOdd = (r % 2) === 1;
    let count = isOdd ? M_COLS + 1 : M_COLS;

    for (let idx = 0; idx < count; idx++) {
      let c = isOdd ? idx : idx + 0.5;
      if (c < 0.25 || c > M_COLS - 0.25) continue;

      let centerPt = mapLattice(r, c);
      // Skip main-grid feathers inside the eye & periorbital ring zone
      if (getEyeDist(centerPt.x, centerPt.y) < 1.34) continue;

      let isNeck = centerPt.s >= 0.145;
      let filmIdx = 0;
      if (isNeck) {
        filmIdx = getFilmColorIdx(getThinFilmPhase(centerPt.s, centerPt.u));
      }

      // 1. Central Rachis (Shaft) from top notch (r - 0.92, c) to tip (r + 0.94, c)
      let rStart = max(-0.4, r - 0.90);
      let rEnd = r + 0.94;
      let pShaft0 = mapLattice(rStart, c);
      let pShaftMid = mapLattice(0.5 * (rStart + rEnd), c);
      let pShaft1 = mapLattice(rEnd, c);

      if (getEyeDist(pShaft0.x, pShaft0.y) > 1.28 && getEyeDist(pShaft1.x, pShaft1.y) > 1.28) {
        rachisDark.push([pShaft0.x, pShaft0.y, pShaftMid.x, pShaftMid.y]);
        rachisDark.push([pShaftMid.x, pShaftMid.y, pShaft1.x, pShaft1.y]);
        rachisLight.push([pShaft0.x - 0.9, pShaft0.y, pShaft1.x - 0.7, pShaft1.y]);
      }

      // 2. Photographic Barbs radiating from the rachis on both left (side=-1) and right (side=+1) vanes
      // Number of barbs scales with feather size from head (11 per side) to lower neck (18 per side)
      let nBarbs = Math.floor(lerp(11, 18, constrain(centerPt.s, 0, 1)));
      let barbSlope = lerp(0.55, 0.72, constrain(centerPt.s, 0, 1));

      for (let side of [-1, 1]) {
        for (let b = 0; b < nBarbs; b++) {
          let frac = b / (nBarbs - 1); // 0 near top notch, 1 near distal tip
          let row0 = lerp(r - 0.82, r + 0.82, frac);

          // At row0 along the shaft, solve for how far out (tBarb in [0, 0.48]) the barb travels
          // before hitting either the upper overlap boundary (rowMin) or the lower rim (rowMax)
          let p0 = mapLattice(row0, c);
          if (getEyeDist(p0.x, p0.y) < 1.30) continue;

          // Binary/analytic clip of barb length in lattice space
          let tMax = 0.47 * Math.sin(Math.pow(frac, 0.65) * Math.PI * 0.96);
          if (tMax < 0.04) continue;

          let row1 = row0 + tMax * barbSlope * (1.0 - 0.35 * frac);
          // Clamp row1 to the exact analytical feather cell boundaries at tMax
          let sLow = Math.pow(max(0, 1 - 2 * tMax), 1 / 1.65);
          let rowMaxBound = r + Math.pow(sLow, 0.78);
          let sUp = Math.pow(min(1, 2 * tMax), 1 / 1.65);
          let rowMinBound = (r - 1) + Math.pow(sUp, 0.78);

          if (row0 < rowMinBound - 0.05 || row0 > rowMaxBound) continue;
          row1 = constrain(row1, rowMinBound, rowMaxBound);

          let col1 = c + side * tMax;
          let pMid = mapLattice(lerp(row0, row1, 0.52), c + side * tMax * 0.52);
          let p1 = mapLattice(row1, col1);

          // Photographic 3D dome lighting across the feather vane:
          // - Top of feather (frac < 0.24): deep cast shadow tucked under the feather above
          // - Upper-mid dome (frac in [0.28, 0.58], especially left lit vane): specular sheen
          // - Distal zone (frac > 0.68): crisp hard graphite sub-terminal definition
          if (frac < 0.24) {
            barbDark.push([p0.x, p0.y, p1.x, p1.y]);
          } else if (frac >= 0.30 && frac <= 0.56 && (side === -1 || frac < 0.44)) {
            barbMidLight.push([p0.x, p0.y, pMid.x, pMid.y]);
            if (isNeck && (b % 2 === 0)) {
              filmSheenBatches[filmIdx].push([pMid.x, pMid.y, p1.x, p1.y]);
            } else {
              barbSheen.push([pMid.x, pMid.y, p1.x, p1.y]);
            }
          } else if (frac > 0.70) {
            barbMidDark.push([p0.x, p0.y, pMid.x, pMid.y]);
            barbDark.push([pMid.x, pMid.y, p1.x, p1.y]);
          } else {
            barbMidLight.push([p0.x, p0.y, pMid.x, pMid.y]);
            barbMidDark.push([pMid.x, pMid.y, p1.x, p1.y]);
          }
        }
      }

      // 3. Upper overlap shadow crease (where this feather tucks under the two feathers of row r-1)
      if (r >= 1) {
        for (let side of [-1, 1]) {
          let pNotch = mapLattice(r - 0.92, c);
          let pMidUp = mapLattice(r - 0.36, c + side * 0.24);
          let pCorner = mapLattice(r + 0.02, c + side * 0.46);
          if (getEyeDist(pNotch.x, pNotch.y) > 1.32 && getEyeDist(pCorner.x, pCorner.y) > 1.32) {
            tuckShadows.push([pNotch.x, pNotch.y, pMidUp.x, pMidUp.y]);
            tuckShadows.push([pMidUp.x, pMidUp.y, pCorner.x, pCorner.y]);
          }
        }
      }

      // 4. Hard graphite mapped distal margin (LeftCorner -> Tip -> RightCorner)
      let rimPts = [];
      let rimSteps = 6;
      for (let k = -rimSteps; k <= rimSteps; k++) {
        let uRim = k / rimSteps; // -1 to 1
        let sRim = 1.0 - Math.abs(uRim);
        // Tiny occasional natural barb nick in the feather rim
        let nick = (k === 2 && ((r * 7 + idx * 13) % 11 === 0)) ? -0.09 : 0;
        let colF = c + Math.sign(uRim) * 0.48 * (1 - Math.pow(sRim, 1.65));
        let rowF = r + Math.pow(sRim, 0.78) + nick;
        rimPts.push(mapLattice(rowF, colF));
      }

      for (let k = 0; k < rimPts.length - 1; k++) {
        let a = rimPts[k];
        let b = rimPts[k + 1];
        if (getEyeDist(a.x, a.y) < 1.30 || getEyeDist(b.x, b.y) < 1.30) continue;
        // Left/bottom-left rim is lit, right/bottom-right rim has stronger shadow weight
        if (k < rimSteps - 1) {
          rimMid.push([a.x, a.y, b.x, b.y]);
        } else {
          rimDark.push([a.x, a.y, b.x, b.y]);
        }
      }

      // 5. Watercolor pooled pigment rim inside the distal feather margin on the neck
      if (isNeck && r < R_MAX) {
        let poolSpline = [];
        for (let k = 1; k <= rimSteps * 2 - 1; k += 2) {
          let pt = rimPts[k];
          if (getEyeDist(pt.x, pt.y) > 1.35) {
            poolSpline.push([pt.x, pt.y - 2.2, 0.85]);
          }
        }
        if (poolSpline.length >= 3) {
          wcPoolRims[filmIdx].push(poolSpline);
        }
      }
    }
  }

  // Render pooled watercolor rims at feather edges first so crisp graphite sits cleanly over/with them
  for (let cIdx = 0; cIdx < 4; cIdx++) {
    brush.set("wc_pool", FILM_PALETTE[cIdx].pool, 1.0);
    for (let sp of wcPoolRims[cIdx]) {
      brush.spline(sp, 0.45);
    }
  }

  // Render photographic barbs in batched tonal passes
  brush.set("graphite_2H", "#646C76", 0.9);
  for (let seg of barbMidLight) {
    brush.line(seg[0], seg[1], seg[2], seg[3]);
  }

  brush.set("graphite_2H", "#3E454E", 1.0);
  for (let seg of barbMidDark) {
    brush.line(seg[0], seg[1], seg[2], seg[3]);
  }

  brush.set("graphite_2H", "#23282E", 1.08);
  for (let seg of barbDark) {
    brush.line(seg[0], seg[1], seg[2], seg[3]);
  }

  // Silvery & pastel-iridescent specular barb highlights
  brush.set("barb_sheen", "#F5F3EE", 0.95);
  for (let seg of barbSheen) {
    brush.line(seg[0], seg[1], seg[2], seg[3]);
  }

  for (let cIdx = 0; cIdx < 4; cIdx++) {
    brush.set("barb_sheen", FILM_PALETTE[cIdx].sheen, 1.05);
    for (let seg of filmSheenBatches[cIdx]) {
      brush.line(seg[0], seg[1], seg[2], seg[3]);
    }
  }

  // Render deep overlap tuck shadows under upper feather rows
  brush.set("graphite_2B", "#1F242A", 0.95);
  for (let seg of tuckShadows) {
    brush.line(seg[0], seg[1], seg[2], seg[3]);
  }

  // Render central rachis shafts & adjacent highlights
  brush.set("graphite_2H", "#2C323A", 1.05);
  for (let seg of rachisDark) {
    brush.line(seg[0], seg[1], seg[2], seg[3]);
  }

  brush.set("barb_sheen", "#FAF8F4", 0.85);
  for (let seg of rachisLight) {
    brush.line(seg[0], seg[1], seg[2], seg[3]);
  }

  // Render hard graphite mapped feather margins
  brush.set("graphite_HB", "#3F464F", 0.92);
  for (let seg of rimMid) {
    brush.line(seg[0], seg[1], seg[2], seg[3]);
  }

  brush.set("graphite_HB", "#20252B", 1.08);
  for (let seg of rimDark) {
    brush.line(seg[0], seg[1], seg[2], seg[3]);
  }

  // Add scalloped profile edge feathers along the crown, throat, puffed breast, and nape
  drawSilhouetteEdgeFeathers();
}

function drawSilhouetteEdgeFeathers() {
  // Crown and forehead fine contour feather tips
  brush.set("graphite_HB", "#2A3038", 0.9);
  for (let i = 1; i < 28; i++) {
    let u0 = (i - 0.5) / 28;
    let u1 = (i + 0.5) / 28;
    let p0 = mapSurface(0.0, u0);
    let pMid = mapSurface(-0.008, 0.5 * (u0 + u1));
    let p1 = mapSurface(0.0, u1);
    brush.line(p0.x, p0.y, pMid.x, pMid.y);
    brush.line(pMid.x, pMid.y, p1.x, p1.y);
  }

  // Puffed throat & breast scalloped silhouette edge (left contour)
  for (let i = 4; i < 42; i++) {
    let s0 = (i / 42) * 1.0;
    let s1 = ((i + 1) / 42) * 1.0;
    let p0 = mapSurface(s0, 0.0);
    let pMid = mapSurface(0.5 * (s0 + s1), 0.0);
    let p1 = mapSurface(s1, 0.0);
    // Scalloped bulge outward on each overlapping breast feather
    let outX = pMid.x - lerp(2.0, 5.5, s0);
    let outY = pMid.y + 1.5;
    brush.set("graphite_HB", "#282E36", 0.95);
    brush.line(p0.x, p0.y, outX, outY);
    brush.line(outX, outY, p1.x, p1.y);
    // Fine edge barbs
    brush.set("graphite_2H", "#464E58", 0.8);
    brush.line(p0.x + 6, p0.y - 3, outX, outY);
  }

  // Nape & dorsal neck scalloped silhouette edge (right contour)
  for (let i = 0; i < 40; i++) {
    let s0 = (i / 40) * 1.0;
    let s1 = ((i + 1) / 40) * 1.0;
    let p0 = mapSurface(s0, 1.0);
    let pMid = mapSurface(0.5 * (s0 + s1), 1.0);
    let p1 = mapSurface(s1, 1.0);
    let outX = pMid.x + lerp(2.0, 5.0, s0);
    let outY = pMid.y + 1.0;
    brush.set("graphite_HB", "#1E232A", 1.05);
    brush.line(p0.x, p0.y, outX, outY);
    brush.line(outX, outY, p1.x, p1.y);
  }
}

// ============================================================================
// STEP 5: PERIORBITAL TINY FEATHER RINGS AROUND THE EYE
// ============================================================================

function drawPeriorbitalFeathers() {
  let angTilt = -8 * Math.PI / 180;
  let cosT = Math.cos(angTilt);
  let sinT = Math.sin(angTilt);

  function mapEyePolar(rNorm, thetaDeg) {
    let rad = thetaDeg * Math.PI / 180;
    let lx = Math.cos(rad) * 71 * rNorm;
    let ly = Math.sin(rad) * 66 * rNorm;
    return {
      x: EX + lx * cosT - ly * sinT,
      y: EY + lx * sinT + ly * cosT
    };
  }

  // 4 concentric staggered rings of tiny scale-feathers from rNorm = 1.38 inward to 0.98
  const rings = [
    { rIn: 1.24, rOut: 1.42, count: 38 },
    { rIn: 1.13, rOut: 1.28, count: 36 },
    { rIn: 1.04, rOut: 1.17, count: 34 },
    { rIn: 0.97, rOut: 1.08, count: 32 }
  ];

  for (let rIdx = 0; rIdx < rings.length; rIdx++) {
    let rg = rings[rIdx];
    let stepDeg = 360 / rg.count;
    let offsetDeg = (rIdx % 2) * (stepDeg * 0.5);

    for (let k = 0; k < rg.count; k++) {
      let aCenter = k * stepDeg + offsetDeg;
      let aLeft = aCenter - stepDeg * 0.48;
      let aRight = aCenter + stepDeg * 0.48;

      let pBase = mapEyePolar(rg.rIn, aCenter);
      let pLeft = mapEyePolar(lerp(rg.rIn, rg.rOut, 0.45), aLeft);
      let pTip = mapEyePolar(rg.rOut, aCenter);
      let pRight = mapEyePolar(lerp(rg.rIn, rg.rOut, 0.45), aRight);

      // Tiny radiating barbs inside each periorbital feather
      brush.set("graphite_2H", "#4A525C", 0.85);
      for (let b = -2; b <= 2; b++) {
        let aBarb = aCenter + b * (stepDeg * 0.16);
        let pb0 = mapEyePolar(rg.rIn + 0.02, aCenter + b * 1.2);
        let pb1 = mapEyePolar(rg.rOut - 0.02 * Math.abs(b), aBarb);
        brush.line(pb0.x, pb0.y, pb1.x, pb1.y);
      }

      // Crisp hard graphite scalloped rim
      brush.set("graphite_HB", "#252A30", 0.88);
      brush.line(pLeft.x, pLeft.y, pTip.x, pTip.y);
      brush.line(pTip.x, pTip.y, pRight.x, pRight.y);

      // Dark overlap shadow at base
      brush.set("graphite_2B", "#1D2126", 0.75);
      brush.line(pLeft.x, pLeft.y, pBase.x, pBase.y);
    }
  }
}

