function drawGlassyAmberEye() {
  let angTilt = -8 * Math.PI / 180;
  let cosT = Math.cos(angTilt);
  let sinT = Math.sin(angTilt);

  function eyePt(rx, ry, deg) {
    let rad = deg * Math.PI / 180;
    let lx = Math.cos(rad) * rx;
    let ly = Math.sin(rad) * ry;
    return {
      x: EX + lx * cosT - ly * sinT,
      y: EY + lx * sinT + ly * cosT
    };
  }

  // 1. Bare Fleshy Orbital Skin Ring (Eye-Cere, rx=70, ry=65 down to rx=50, ry=48)
  brush.noStroke();
  brush.noFill();
  brush.wash("#DFD9D0", 252);
  brush.beginShape(0.3);
  for (let a = 0; a < 360; a += 10) {
    let p = eyePt(70, 65, a);
    brush.vertex(p.x, p.y);
  }
  brush.endShape(CLOSE);
  brush.noWash();

  // Shadow shading on orbital skin ring
  brush.fillBleed(0.15, "in");
  brush.fillTexture(0.55, 0.45);
  brush.fill("#A8A096", 90);
  brush.beginShape(0.3);
  for (let a = 0; a < 360; a += 12) {
    let rMod = (a > 160 && a < 340) ? 1.0 : 0.92;
    let p = eyePt(70 * rMod, 65 * rMod, a);
    brush.vertex(p.x, p.y);
  }
  brush.endShape(CLOSE);
  brush.noFill();

  // Concentric fleshy grooves & radial wrinkles on the orbital ring
  for (let ringR of [0.98, 0.87, 0.77]) {
    brush.set("graphite_2H", "#5E5954", 0.9);
    let pts = [];
    for (let a = 0; a <= 360; a += 12) {
      let p = eyePt(70 * ringR, 65 * ringR, a);
      pts.push([p.x, p.y, 0.9]);
    }
    brush.spline(pts, 0.4);
  }

  // Radial skin creases and pebbled papillae highlights around the orbital ring
  for (let a = 0; a < 360; a += 6) {
    let pIn = eyePt(50, 48, a);
    let pMid = eyePt(60, 56, a + 1.5);
    let pOut = eyePt(70, 65, a);
    brush.set("graphite_2H", "#69635E", 0.82);
    brush.line(pIn.x, pIn.y, pMid.x, pMid.y);
    brush.line(pMid.x, pMid.y, pOut.x, pOut.y);

    if (a % 12 === 0) {
      let pHi = eyePt(56, 53, a + 3);
      brush.set("barb_sheen", "#F7F4EE", 1.1);
      brush.line(pHi.x, pHi.y, pHi.x + 1.8, pHi.y - 1.2);
    }
  }

  // 2. Dark Palpebral Eyelid Rim (rx=50, ry=48)
  brush.noStroke();
  brush.noFill();
  brush.wash("#1A1615", 255);
  brush.beginShape(0.25);
  for (let a = 0; a < 360; a += 10) {
    let p = eyePt(50.5, 48.5, a);
    brush.vertex(p.x, p.y);
  }
  brush.endShape(CLOSE);

  // 3. The Iris — Glassy Amber Ring (rx=47.5, ry=46)
  // Brilliant golden-amber base wash
  brush.wash("#F8AA1E", 255);
  brush.beginShape(0.25);
  for (let a = 0; a < 360; a += 10) {
    let p = eyePt(47.5, 46.0, a);
    brush.vertex(p.x, p.y);
  }
  brush.endShape(CLOSE);

  // Luminous canary-gold inner iris ring around the pupil
  brush.wash("#FFD03B", 245);
  brush.beginShape(0.25);
  for (let a = 0; a < 360; a += 12) {
    let p = eyePt(34.5, 33.5, a);
    brush.vertex(p.x, p.y);
  }
  brush.endShape(CLOSE);
  brush.noWash();

  // Rich fiery vermilion-amber watercolor glaze on the outer half of the iris ring
  brush.fillBleed(0.22, "in");
  brush.fillTexture(0.55, 0.50);
  brush.fill("#D94410", 135);
  brush.beginShape(0.3);
  for (let a = 0; a <= 360; a += 12) {
    let p = eyePt(47.5, 46.0, a);
    brush.vertex(p.x, p.y);
  }
  brush.endShape(CLOSE);

  // Bright golden-amber inner glow wash
  brush.fill("#FFCA28", 115);
  brush.beginShape(0.3);
  for (let a = 0; a <= 360; a += 12) {
    let p = eyePt(33.0, 32.0, a);
    brush.vertex(p.x, p.y);
  }
  brush.endShape(CLOSE);
  brush.noFill();

  // Intricate radial iris stroma fibers & capillary filaments
  for (let a = 0; a < 360; a += 2.5) {
    let radWobble = Math.sin(a * 7 * Math.PI / 180) * 2.5;
    let pPupil = eyePt(21.5, 21.5, a);
    let pMid = eyePt(34.0, 33.0, a + radWobble);
    let pOuter = eyePt(46.8, 45.2, a);

    // Outer fiery amber-crimson fibers
    brush.set("graphite_2H", (a % 5 === 0) ? "#8C2206" : "#C83B0E", 0.95);
    brush.line(pMid.x, pMid.y, pOuter.x, pOuter.y);

    // Inner glowing gold & warm amber fibers
    brush.set("barb_sheen", (a % 5 === 0) ? "#FFF08A" : "#F59818", 1.0);
    brush.line(pPupil.x, pPupil.y, pMid.x, pMid.y);
  }

  // Concentric collarette ring & dark limbal ring for deep 3D corneal convexity
  brush.set("graphite_HB", "#22120C", 1.35);
  for (let a = 0; a < 360; a += 10) {
    let p0 = eyePt(47.2, 45.8, a);
    let p1 = eyePt(47.2, 45.8, a + 10);
    brush.line(p0.x, p0.y, p1.x, p1.y);
  }

  // Upper corneal cast shadow from the upper eyelid
  brush.noStroke();
  brush.fillBleed(0.15, "in");
  brush.fillTexture(0.3, 0.2);
  brush.fill("#26120A", 92);
  brush.beginShape(0.3);
  for (let a = 185; a <= 355; a += 10) {
    let p = eyePt(47.5, 46.0, a);
    brush.vertex(p.x, p.y);
  }
  for (let a = 355; a >= 185; a -= 15) {
    let p = eyePt(40.0, 26.0, a);
    brush.vertex(p.x, p.y);
  }
  brush.endShape(CLOSE);

  // Subtle lower-right glassy sky reflection crescent on the amber iris
  brush.fill("#E8F2FA", 72);
  brush.beginShape(0.35);
  for (let a = 18; a <= 84; a += 8) {
    let p = eyePt(41.5, 40.0, a);
    brush.vertex(p.x, p.y);
  }
  for (let a = 84; a >= 18; a -= 8) {
    let p = eyePt(30.5, 29.5, a);
    brush.vertex(p.x, p.y);
  }
  brush.endShape(CLOSE);
  brush.noFill();

  // 4. The Pupil (Deep velvety jet-black center, rx=21.2, ry=21.8)
  brush.noStroke();
  brush.noFill();
  brush.wash("#09090B", 255);
  brush.beginShape(0.25);
  for (let a = 0; a < 360; a += 10) {
    let p = eyePt(21.2, 21.8, a);
    brush.vertex(p.x, p.y);
  }
  brush.endShape(CLOSE);
  brush.noWash();

  // Crisp pupillary ruff ring
  brush.set("graphite_HB", "#381808", 0.95);
  for (let a = 0; a < 360; a += 12) {
    let p0 = eyePt(21.6, 22.2, a);
    let p1 = eyePt(21.6, 22.2, a + 12);
    brush.line(p0.x, p0.y, p1.x, p1.y);
  }

  // 5. THE HARD WHITE HIGHLIGHT (Razor-sharp curved specular window reflection)
  let hiPts = [];
  for (let a = 202; a <= 252; a += 5) {
    hiPts.push(eyePt(36.5, 35.5, a));
  }
  for (let a = 252; a >= 202; a -= 5) {
    hiPts.push(eyePt(16.5, 16.5, a));
  }

  brush.noStroke();
  brush.noFill();
  brush.wash("#FFFFFF", 255);
  brush.beginShape(0.15);
  for (let p of hiPts) {
    brush.vertex(p.x, p.y);
  }
  brush.endShape(CLOSE);

  // Secondary crisp satellite catchlight dot just past the main highlight
  let satCenter = eyePt(27.0, 26.5, 264);
  brush.wash("#FFFFFF", 255);
  brush.circle(satCenter.x, satCenter.y, 4.2, 0.05);
  brush.noWash();

  // Reinforce the hard white highlight with dense pure-white glass_pen strokes for maximum brilliance
  brush.set("glass_pen", "#FFFFFF", 1.2);
  for (let rHi = 17.5; rHi <= 35.5; rHi += 1.2) {
    for (let a = 203; a < 251; a += 6) {
      let p0 = eyePt(rHi, rHi * 0.97, a);
      let p1 = eyePt(rHi, rHi * 0.97, a + 6);
      brush.line(p0.x, p0.y, p1.x, p1.y);
    }
  }

  // Tiny wet tear-film sparkle along the lower eyelid margin
  brush.set("glass_pen", "#F4F8FC", 0.9);
  for (let a = 45; a <= 125; a += 10) {
    let p0 = eyePt(48.2, 46.5, a);
    let p1 = eyePt(48.2, 46.5, a + 7);
    brush.line(p0.x, p0.y, p1.x, p1.y);
  }
}

