function project(X, Y, Z) {
  let dx = X - CAM.x;
  let dy = Y - CAM.y;
  let dz = Z - CAM.z;
  let yc = dy * cosP - dz * sinP;
  let zc = dy * sinP + dz * cosP;
  if (zc < 25) zc = 25;
  let s = CAM.focal / zc;
  return {
    x: CAM.cx + dx * s,
    y: CAM.cy - yc * s,
    s: s,
    zc: zc
  };
}

function queuePoly(batchName, pts3d, is2D = false) {
  let pts = is2D ? pts3d : pts3d.map(p => project(p[0], p[1], p[2]));
  // Cull polygons completely off-screen
  let minX = 99999, maxX = -99999, minY = 99999, maxY = -99999;
  for (let p of pts) {
    if (p.x < minX) minX = p.x;
    if (p.x > maxX) maxX = p.x;
    if (p.y < minY) minY = p.y;
    if (p.y > maxY) maxY = p.y;
  }
  if (maxX < -120 || minX > 1320 || maxY < -120 || minY > 1320) return;
  if ((maxX - minX) < 1.5 && (maxY - minY) < 1.5) return;
  fillBatches[batchName].push(pts);
}

function drawPolyShape(pts, curv = 0.02) {
  if (!pts || pts.length < 3) return;
  brush.beginShape(curv);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i].x, pts[i].y);
  }
  brush.endShape(true);
}

function flushBatch(batchName, curv = 0.02) {
  let list = fillBatches[batchName];
  if (!list || list.length === 0) return;
  let def = BATCH_DEFS[batchName];
  brush.noStroke();
  brush.noHatch();
  brush.noMass();
  brush.fill(def.col, def.op);
  brush.fillBleed(def.bleed, "out");
  brush.fillTexture(def.tex, def.border);
  for (let pts of list) {
    drawPolyShape(pts, curv);
  }
  brush.noFill();
  fillBatches[batchName] = [];
}

function line3D(x1, y1, z1, x2, y2, z2) {
  let p1 = project(x1, y1, z1);
  let p2 = project(x2, y2, z2);
  if ((p1.x < -80 && p2.x < -80) || (p1.x > 1280 && p2.x > 1280) ||
      (p1.y < -80 && p2.y < -80) || (p1.y > 1280 && p2.y > 1280)) return;
  brush.line(p1.x, p1.y, p2.x, p2.y);
}

function draw() {
  translate(-width / 2, -height / 2);

  // Cool architectural paper tone
  background("#dfe5eb");
  brush.noField();

  // =========================================================================
  // 1. ATMOSPHERIC GROUND & BASE WATERCOLOR WASHES
  // =========================================================================
  buildBaseAtmosphere();

  // =========================================================================
  // 2. SMOKY CHARCOAL UPPER VAULT & RECEDING ROOF TRUSSES
  // =========================================================================
  buildSmokyVaultAndTrusses();

  // =========================================================================
  // 3. CONCRETE FLOOR SLAB, REFLECTIONS & EXPANSION JOINTS
  // =========================================================================
  buildConcreteFloor();

  // =========================================================================
  // 4. TOWERING SHELVING CANYON, PALLETS & SHRINK-WRAPPED GOODS
  // =========================================================================
  buildWarehouseCanyon();

  // =========================================================================
  // 5. COLD SHAFTS OF SKYLIGHT & DRIFTING DUST WASHES
  // =========================================================================
  buildSkylightShaftsAndDust();

  // =========================================================================
  // 6. TOP-OF-IMAGE SMUDGED INFINITY VEIL
  // =========================================================================
  buildTopSmudgedInfinity();

  // =========================================================================
  // 7. FOREGROUND RACK SHARPENING & HANGING PLACARDS
  // =========================================================================
  buildForegroundRackDetails();

  // =========================================================================
  // 8. THE LONE SHOPPER & TROLLEY (HYPERREAL PENCIL ANCHOR)
  // =========================================================================
  buildLoneShopperAndTrolley();

  noLoop();
}

// ---------------------------------------------------------------------------
// STAGE 1: Base Atmospheric Washes
// ---------------------------------------------------------------------------
function buildBaseAtmosphere() {
  // Queue large atmospheric zones
  // Deep smoky ceiling vault
  queuePoly("vaultDeep", [
    { x: -40, y: -40 }, { x: 1240, y: -40 },
    { x: 1240, y: 270 }, { x: -40, y: 270 }
  ], true);

  queuePoly("vaultMid", [
    { x: -40, y: 180 }, { x: 1240, y: 180 },
    { x: 1020, y: 540 }, { x: 180, y: 540 }
  ], true);

  // Left and right canyon shadow walls
  queuePoly("vaultMid", [
    { x: -40, y: 180 }, { x: 380, y: 180 },
    { x: 470, y: 900 }, { x: -40, y: 1080 }
  ], true);

  queuePoly("vaultMid", [
    { x: 800, y: 180 }, { x: 1240, y: 180 },
    { x: 1240, y: 1080 }, { x: 700, y: 900 }
  ], true);

  // Central aisle depth haze
  queuePoly("vaultHaze", [
    { x: 420, y: 380 }, { x: 750, y: 380 },
    { x: 680, y: 895 }, { x: 490, y: 895 }
  ], true);

  // Foreground dark concrete corners
  queuePoly("rackShadow", [
    { x: -40, y: 960 }, { x: 380, y: 940 },
    { x: 240, y: 1240 }, { x: -40, y: 1240 }
  ], true);

  queuePoly("rackShadow", [
    { x: 790, y: 940 }, { x: 1240, y: 960 },
    { x: 1240, y: 1240 }, { x: 920, y: 1240 }
  ], true);

  // Pale ochre & cool grey skylight pools on floor and center canyon
  queuePoly("ochreDust", [
    { x: 430, y: 120 }, { x: 730, y: 120 },
    { x: 830, y: 980 }, { x: 360, y: 980 }
  ], true);

  queuePoly("skyBeamOchre", [
    { x: 350, y: 910 }, { x: 810, y: 910 },
    { x: 890, y: 1060 }, { x: 290, y: 1060 }
  ], true);

  flushBatch("vaultDeep", 0.05);
  flushBatch("vaultMid", 0.05);
  flushBatch("vaultHaze", 0.05);
  flushBatch("rackShadow", 0.04);
  flushBatch("ochreDust", 0.06);
  flushBatch("skyBeamOchre", 0.06);
}

// ---------------------------------------------------------------------------
// STAGE 2: Smoky Charcoal Vault & Roof Trusses
// ---------------------------------------------------------------------------
function buildSmokyVaultAndTrusses() {
  // Dry charcoal mass in the upper vault
  brush.noStroke();
  brush.noFill();
  brush.noHatch();

  brush.mass("charcoal", "#1c232d", {
    precision: 0.25,
    strength: 0.65,
    gradient: 0.75,
    outline: false
  });
  drawPolyShape([
    { x: -20, y: -20 }, { x: 1220, y: -20 },
    { x: 1220, y: 220 }, { x: 780, y: 310 },
    { x: 400, y: 310 }, { x: -20, y: 220 }
  ], 0.04);

  brush.mass("charcoal", "#2b3542", {
    precision: 0.3,
    strength: 0.45,
    gradient: 0.8,
    outline: false
  });
  drawPolyShape([
    { x: 240, y: 160 }, { x: 940, y: 160 },
    { x: 740, y: 490 }, { x: 430, y: 490 }
  ], 0.04);
  brush.noMass();

  // Glowing skylight bays high in the ceiling vault (Y = 820)
  for (let z = 620; z <= 2300; z += 320) {
    queuePoly("wrapBright", [
      [-68, 820, z], [68, 820, z],
      [68, 820, z + 150], [-68, 820, z + 150]
    ]);
    queuePoly("ochreDust", [
      [-92, 815, z - 20], [92, 815, z - 20],
      [92, 815, z + 170], [-92, 815, z + 170]
    ]);
  }
  flushBatch("ochreDust", 0.02);
  flushBatch("wrapBright", 0.02);

  // Receding steel roof trusses (Y = 755 to 815)
  for (let z = 540; z <= 2550; z += 160) {
    let pMid = project(0, 760, z);
    if (pMid.y < 25 || pMid.y > 620) continue;
    let fade = constrain(map(pMid.y, 40, 480, 0.25, 0.9), 0.2, 0.95);
    let bName = pMid.y < 200 ? "charcoal" : "2B";
    let col = pMid.y < 220 ? "#3b4754" : "#252f3b";

    brush.set(bName, col, 0.55 * fade);
    // Bottom & top chords of roof truss
    line3D(-220, 755, z, 220, 755, z);
    line3D(-220, 810, z, 220, 810, z);

    // Web diagonals
    brush.set(bName, col, 0.38 * fade);
    let step = 44;
    for (let x = -176; x < 176; x += step) {
      line3D(x, 755, z, x + step * 0.5, 810, z);
      line3D(x + step * 0.5, 810, z, x + step, 755, z);
    }
  }

  // Longitudinal purlins in the vault
  brush.set("2B", "#313d4b", 0.4);
  for (let x of [-110, -55, 0, 55, 110]) {
    line3D(x, 812, 550, x, 812, 2500);
  }
}

// ---------------------------------------------------------------------------
// STAGE 3: Polished Concrete Floor, Reflections & Saw-Cut Joints
// ---------------------------------------------------------------------------
function buildConcreteFloor() {
  // Distant end-of-aisle abyss & exit glimmer at horizon (VX=585, VY=884)
  queuePoly("vaultDeep", [
    [-140, 0, 2650], [140, 0, 2650],
    [140, 680, 2650], [-140, 680, 2650]
  ]);
  flushBatch("vaultDeep", 0.01);

  // Floor base shading bands along Z
  queuePoly("slateMid", [
    [-135, 0, 200], [135, 0, 200],
    [135, 0, 2650], [-135, 0, 2650]
  ]);
  // Dark reflective margins along the base of left and right racks
  queuePoly("slateDark", [
    [-135, 0, 200], [-82, 0, 200],
    [-82, 0, 2400], [-135, 0, 2400]
  ]);
  queuePoly("slateDark", [
    [82, 0, 200], [135, 0, 200],
    [135, 0, 2400], [82, 0, 2400]
  ]);

  // Luminous skylight reflection pools on the concrete floor
  let lightPoolsZ = [
    [470, 770],
    [1020, 1320],
    [1620, 1950]
  ];
  for (let [zA, zB] of lightPoolsZ) {
    queuePoly("ochreDust", [
      [-85, 0, zA], [95, 0, zA],
      [95, 0, zB], [-85, 0, zB]
    ]);
    queuePoly("wrapBright", [
      [-52, 0, zA + 35], [62, 0, zA + 35],
      [62, 0, zB - 35], [-52, 0, zB - 35]
    ]);
  }

  flushBatch("slateMid", 0.01);
  flushBatch("slateDark", 0.01);
  flushBatch("ochreDust", 0.03);
  flushBatch("wrapBright", 0.03);

  // Vertical specular streaks on the polished concrete floor
  for (let i = 0; i < 110; i++) {
    let fx = random(-130, 130);
    let fz = random(240, 2100);
    let pTop = project(fx, 0, fz + 80);
    let pBot = project(fx, 0, fz - 40);
    let isLightPool = ( abs(fx) < 75 && ((fz > 470 && fz < 780) || (fz > 1020 && fz < 1320)) );
    if (isLightPool) {
      brush.set("plastic_glint", i % 2 === 0 ? "#eef4fa" : "#e8dfc9", random(0.35, 0.75));
    } else if (abs(fx) > 85) {
      brush.set("2B", "#232c37", random(0.4, 0.8));
    } else {
      brush.set("HB", "#627182", random(0.3, 0.55));
    }
    brush.line(pTop.x, pTop.y, pTop.x, pBot.y);
  }

  // Concrete saw-cut expansion joints (perspective grid on Y = 0)
  for (let x of [-90, -45, 0, 45, 90]) {
    brush.set("2H", x === 0 ? "#38434f" : "#515f6e", x === 0 ? 0.55 : 0.35);
    line3D(x, 0, 190, x, 0, 2400);
  }
  for (let z = 220; z <= 2200; z += 130) {
    let w = map(z, 220, 2200, 0.65, 0.22);
    brush.set("2H", "#434f5c", w);
    line3D(-135, 0, z, 135, 0, z);
    // Subtle pale highlight lip on the near edge of foreground slab joints
    if (z < 850) {
      brush.set("fine_needle", "#dce5ed", w * 0.65);
      line3D(-120, 0, z + 1.5, 120, 0, z + 1.5);
    }
  }
}

// ---------------------------------------------------------------------------
// STAGE 4: Towering Shelving Canyon, Pallets & Shrink-Wrapped Goods
// ---------------------------------------------------------------------------
function buildWarehouseCanyon() {
  const tierY = [0, 74, 148, 222, 298, 376, 456, 538, 622, 708];
  const bayLen = 130;
  const zStart = 180;
  const numBays = 17;

  // Store stroke instructions to execute right after batched fills
  let strokeOps = [];

  for (let b = numBays - 1; b >= 0; b--) {
    let z0 = zStart + b * bayLen;
    let z1 = z0 + bayLen;

    for (let side of [-1, 1]) {
      let xIn = side * 135;
      let xOut = side * 255;

      for (let t = 0; t < tierY.length - 1; t++) {
        let y0 = tierY[t];
        let y1 = tierY[t + 1];
        let beamH = t === 0 ? 0 : 5.5;
        let palletY = y0 + beamH;

        // Check projected screen position of this bay slot
        let pCenter = project(xIn, (y0 + y1) * 0.5, (z0 + z1) * 0.5);
        if (pCenter.y < -90 || pCenter.y > 1260) continue;
        if (pCenter.x < -160 || pCenter.x > 1360) continue;

        // Sharpness factor: dissolves toward top (y < 240) and sharpens toward bottom
        let clarity = constrain(map(pCenter.y, 90, 960, 0.0, 1.0), 0.0, 1.0);
        let depthFade = constrain(map(z0, 180, 2350, 1.0, 0.18), 0.18, 1.0);
        let detail = clarity * depthFade;

        // Each bay holds 2 pallets side-by-side along Z
        for (let pIdx = 0; pIdx < 2; pIdx++) {
          let pz0 = z0 + 6 + pIdx * 60;
          let pz1 = pz0 + 52;
          let pxIn = side * 137;
          let pxOut = side * 238;

          // Deterministic cargo variation
          let seedVal = (b * 37 + t * 13 + pIdx * 7 + (side > 0 ? 101 : 0)) % 100;
          if (seedVal < 6 && t > 4) continue; // Rare empty high slot

          let cargoH = (y1 - palletY - 10) * map(seedVal % 11, 0, 10, 0.68, 0.94);
          let cBottom = palletY + (t === 0 ? 7 : 6.5);
          let cTop = cBottom + cargoH;

          // Is this pallet inside one of the diagonal skylight shafts?
          let inSkylight = (
            (pz0 > 440 && pz0 < 780 && y0 < 520) ||
            (pz0 > 1000 && pz0 < 1340 && y0 < 580)
          ) && (side === 1 || y0 < 260);

          // 1. Queue 3D Cargo Faces into Watercolor Batches
          let cargoType = seedVal % 4; // 0,1: Shrink-wrapped, 2: Cartons, 3: Strapped/Drums
          let frontBatch = "slateDark";
          let aisleBatch = "slateMid";

          if (pCenter.y < 220) {
            frontBatch = "vaultDeep";
            aisleBatch = "vaultMid";
          } else if (cargoType === 0 || cargoType === 1) {
            frontBatch = inSkylight ? "slateMid" : "slateDark";
            aisleBatch = inSkylight ? (seedVal % 3 === 0 ? "wrapBright" : "wrapCool") : "slateLight";
          } else if (cargoType === 2) {
            frontBatch = "taupeDark";
            aisleBatch = inSkylight ? "kraftCool" : "taupeMid";
          } else {
            frontBatch = "rackShadow";
            aisleBatch = inSkylight ? "slateLight" : "slateMid";
          }

          // Camera-facing depth face (at Z = pz0)
          queuePoly(frontBatch, [
            [pxIn, cBottom, pz0], [pxOut, cBottom, pz0],
            [pxOut, cTop, pz0], [pxIn, cTop, pz0]
          ]);

          // Aisle-facing inner face (at X = pxIn)
          queuePoly(aisleBatch, [
            [pxIn, cBottom, pz0], [pxIn, cBottom, pz1],
            [pxIn, cTop, pz1], [pxIn, cTop, pz0]
          ]);

          // Underside or top face depending on eye level (CAM.y = 46)
          if (cBottom > CAM.y + 15 && pIdx === 0) {
            queuePoly("rackShadow", [
              [xIn, y0, z0], [xOut, y0, z0],
              [xOut, y0, z1], [xIn, y0, z1]
            ]);
          }

          // Record detailed line/texture operations for this pallet
          if (detail > 0.12) {
            strokeOps.push({
              type: "pallet",
              side, pxIn, pxOut, pz0, pz1,
              y0, palletY, cBottom, cTop,
              cargoType, detail, clarity, inSkylight, seedVal
            });
          }
        }

        // Record structural steel rack beams & uprights
        strokeOps.push({
          type: "rack",
          side, xIn, xOut, z0, z1, y0, y1, beamH, t, b, detail, clarity, pY: pCenter.y
        });
      }
    }
  }

  // Flush all queued pallet & rack watercolor batches in tonal order!
  flushBatch("vaultDeep", 0.02);
  flushBatch("vaultMid", 0.02);
  flushBatch("rackShadow", 0.01);
  flushBatch("slateDark", 0.015);
  flushBatch("taupeDark", 0.015);
  flushBatch("slateMid", 0.015);
  flushBatch("taupeMid", 0.015);
  flushBatch("slateLight", 0.015);
  flushBatch("kraftCool", 0.015);
  flushBatch("wrapCool", 0.02);
  flushBatch("wrapBright", 0.02);

  // Execute recorded structural and hyperreal cargo strokes (back-to-front)
  for (let op of strokeOps) {
    if (op.type === "pallet") {
      drawPalletAndCargoDetail(op);
    } else if (op.type === "rack") {
      drawRackStructure(op);
    }
  }
}

function drawPalletAndCargoDetail(op) {
  let { side, pxIn, pxOut, pz0, pz1, palletY, cBottom, cTop, cargoType, detail, clarity, inSkylight, seedVal } = op;

  // Choose brush based on vertical clarity (top = smudged charcoal, bottom = crisp pencil)
  let mainBrush = clarity < 0.32 ? "charcoal" : (detail > 0.58 ? "fine_needle" : "HB");
  let wScale = clarity < 0.32 ? 0.45 : map(detail, 0.1, 1.0, 0.35, 0.95);

  // 1. WOODEN PALLET BASE (visible timber stringers & dark fork-entry slots)
  if (detail > 0.22) {
    let pH = cBottom - palletY;
    // Top & bottom timber deckboards along aisle face
    brush.set(mainBrush, "#6e5f4f", wScale * 0.85);
    line3D(pxIn, palletY + 0.8, pz0, pxIn, palletY + 0.8, pz1);
    line3D(pxIn, cBottom - 0.6, pz0, pxIn, cBottom - 0.6, pz1);
    // Front depth edge of pallet
    line3D(pxIn, palletY + 0.8, pz0, pxOut, palletY + 0.8, pz0);
    line3D(pxIn, cBottom - 0.6, pz0, pxOut, cBottom - 0.6, pz0);

    // Two dark rectangular fork-entry tunnels between the 3 wood blocks
    let slot1A = pz0 + 8, slot1B = pz0 + 21;
    let slot2A = pz0 + 31, slot2B = pz0 + 44;
    brush.set(detail > 0.5 ? "rotring" : "2B", "#161d26", wScale * 1.15);
    for (let [sA, sB] of [[slot1A, slot1B], [slot2A, slot2B]]) {
      line3D(pxIn, palletY + pH * 0.38, sA, pxIn, palletY + pH * 0.38, sB);
      line3D(pxIn, palletY + pH * 0.62, sA, pxIn, palletY + pH * 0.62, sB);
    }
    // Pale timber block ends (left, center, right stringers)
    if (detail > 0.42 && inSkylight) {
      brush.set("plastic_glint", "#dfd3be", wScale * 0.65);
      line3D(pxIn, palletY + pH * 0.5, pz0 + 1, pxIn, palletY + pH * 0.5, pz0 + 6);
      line3D(pxIn, palletY + pH * 0.5, pz0 + 23, pxIn, palletY + pH * 0.5, pz0 + 29);
      line3D(pxIn, palletY + pH * 0.5, pz0 + 46, pxIn, palletY + pH * 0.5, pz1 - 1);
    }
  }

  // 2. CARGO EDGES & HYPERREAL SURFACE DETAIL
  let edgeCol = clarity < 0.35 ? "#35414f" : "#222b36";
  brush.set(mainBrush, edgeCol, wScale * 0.85);

  // Outer 3D wireframe silhouette of the pallet load
  line3D(pxIn, cBottom, pz0, pxIn, cTop, pz0);     // Near vertical corner
  line3D(pxIn, cTop, pz0, pxIn, cTop, pz1);        // Top aisle edge
  line3D(pxIn, cBottom, pz1, pxIn, cTop, pz1);     // Far vertical corner
  line3D(pxIn, cTop, pz0, pxOut, cTop, pz0);       // Top depth edge

  if (cargoType === 0 || cargoType === 1) {
    // SHRINK-WRAPPED PALLET GOODS
    // Internal stacked carton seams faintly visible beneath plastic wrap
    let layers = 2 + (seedVal % 3);
    brush.set("2H", "#4b5866", wScale * 0.6);
    for (let l = 1; l < layers; l++) {
      let ly = lerp(cBottom, cTop, l / layers);
      line3D(pxIn, ly, pz0 + 2, pxIn, ly, pz1 - 2);
      line3D(pxIn, ly, pz0, pxOut * 0.85, ly, pz0);
    }
    // Vertical carton division
    let midZ = (pz0 + pz1) * 0.5;
    line3D(pxIn, cBottom + 2, midZ, pxIn, cTop - 2, midZ);

    // Taut diagonal shrink-wrap tension folds & specular highlights!
    if (clarity > 0.28) {
      let glintCol = inSkylight ? "#f2f7fc" : "#cad6e2";
      brush.set("plastic_glint", glintCol, wScale * (inSkylight ? 0.95 : 0.65));
      // Diagonal X-creases across aisle face
      line3D(pxIn, cBottom + 3, pz0 + 2, pxIn, cTop - 3, pz1 - 3);
      line3D(pxIn, cTop - 4, pz0 + 3, pxIn, cBottom + 4, pz1 - 2);
      // Bright specular highlight along the near vertical wrapped corner (Z = pz0)
      line3D(pxIn, cBottom + 2, pz0 + 0.8, pxIn, cTop - 2, pz0 + 0.8);

      // Horizontal overlapping plastic film band glints
      if (detail > 0.45) {
        brush.set("fine_needle", "#ffffff", wScale * 0.75);
        let bandY1 = lerp(cBottom, cTop, 0.35);
        let bandY2 = lerp(cBottom, cTop, 0.72);
        line3D(pxIn, bandY1, pz0, pxIn, bandY1 + 3, pz1);
        line3D(pxIn, bandY2, pz0, pxIn, bandY2 - 2, pz1);
        // Diagonal tension pull on the depth face
        line3D(pxIn, cBottom + 4, pz0, lerp(pxIn, pxOut, 0.65), cTop - 4, pz0);
      }
    }
  } else if (cargoType === 2) {
    // STEPPED CORRUGATED CARTON STACK WITH SHIPPING LABELS
    let rows = 3;
    let cols = 2;
    brush.set(mainBrush, "#2a3038", wScale * 0.8);
    for (let r = 1; r < rows; r++) {
      let ry = lerp(cBottom, cTop, r / rows);
      line3D(pxIn, ry, pz0, pxIn, ry, pz1);
      line3D(pxIn, ry, pz0, pxOut, ry, pz0);
    }
    for (let c = 1; c < cols; c++) {
      let cz = lerp(pz0, pz1, c / cols);
      line3D(pxIn, cBottom, cz, pxIn, cTop, cz);
    }
    // White barcode/shipping labels on cartons
    if (detail > 0.38) {
      for (let r = 0; r < rows; r++) {
        for (let c = 0; c < cols; c++) {
          let ly = lerp(cBottom, cTop, (r + 0.55) / rows);
          let lz = lerp(pz0, pz1, (c + 0.35) / cols);
          brush.set("plastic_glint", "#edf2f7", wScale * 1.1);
          line3D(pxIn, ly, lz, pxIn, ly, lz + 6);
          if (detail > 0.62) {
            brush.set("fine_needle", "#1a222b", wScale * 0.6);
            line3D(pxIn, ly - 0.7, lz + 1, pxIn, ly - 0.7, lz + 5);
          }
        }
      }
    }
  } else {
    // STRAPPED BULK CRATE OR CYLINDRICAL DRUMS
    // Dark vertical nylon strapping bands + white edge protectors
    let s1 = lerp(pz0, pz1, 0.28);
    let s2 = lerp(pz0, pz1, 0.72);
    brush.set(detail > 0.5 ? "rotring" : "2B", "#141a22", wScale * 1.05);
    line3D(pxIn, cBottom, s1, pxIn, cTop, s1);
    line3D(pxIn, cBottom, s2, pxIn, cTop, s2);
    line3D(pxIn, cTop, s1, lerp(pxIn, pxOut, 0.5), cTop, s1);
    // White cardboard corner protectors under the straps
    if (detail > 0.35) {
      brush.set("plastic_glint", "#e6edf5", wScale * 0.85);
      line3D(pxIn, cTop - 1, s1 - 1.5, pxIn, cTop - 1, s1 + 1.5);
      line3D(pxIn, cTop - 1, s2 - 1.5, pxIn, cTop - 1, s2 + 1.5);
      line3D(pxIn, cBottom + 2, pz0, pxIn, cTop - 2, pz0);
    }
  }
}

function drawRackStructure(op) {
  let { side, xIn, xOut, z0, z1, y0, y1, beamH, t, detail, clarity, pY } = op;
  if (pY < 55) return; // Fully dissolved at very top edge

  let bName = clarity < 0.3 ? "charcoal" : (detail > 0.6 ? "fine_needle" : "2B");
  let w = clarity < 0.3 ? 0.5 : map(detail, 0.1, 1.0, 0.4, 1.1);

  // 1. Upright steel column at Z = z0 (front post & rear post + diagonal web bracing)
  let postCol = clarity < 0.35 ? "#2e3946" : "#1c242e";
  brush.set(bName, postCol, w * 1.1);
  line3D(xIn, y0, z0, xIn, y1, z0);

  // Double-line thickness of front steel column for mid/foreground bays
  if (detail > 0.32) {
    let postW = side * 3.8;
    line3D(xIn + postW, y0, z0, xIn + postW, y1, z0);
    line3D(xIn, y0, z0 + 3.2, xIn, y1, z0 + 3.2);

    // Internal diagonal truss bracing between front (xIn) and back (xOut) upright posts
    brush.set("2H", "#323e4d", w * 0.72);
    line3D(xOut, y0, z0, xOut, y1, z0);
    let yMid = (y0 + y1) * 0.5;
    line3D(xIn, y0, z0, xOut, yMid, z0);
    line3D(xOut, yMid, z0, xIn, y1, z0);
  }

  // Teardrop punch holes along foreground upright columns
  if (detail > 0.62) {
    brush.set("fine_needle", "#0f141a", w * 0.75);
    for (let hy = y0 + 8; hy < y1 - 4; hy += 9) {
      line3D(xIn + side * 1.8, hy, z0, xIn + side * 1.8, hy + 3.2, z0);
    }
    // Cold specular edge highlight on the upright column
    brush.set("plastic_glint", "#b8c7d6", w * 0.45);
    line3D(xIn, y0 + 6, z0, xIn, y1 - 2, z0);
  }

  // 2. Horizontal load beam at Y = y0 (for t > 0)
  if (t > 0) {
    // Muted industrial ochre-rust beam tone in light, cool slate-umber in shadow
    let beamCol = clarity < 0.35 ? "#464d57" : (detail > 0.45 ? "#7a6652" : "#59544f");
    brush.set(bName, beamCol, w * 1.05);
    line3D(xIn, y0, z0, xIn, y0, z1);
    line3D(xIn, y0 + beamH, z0, xIn, y0 + beamH, z1);

    // Crisp dark shadow line under the load beam
    if (detail > 0.28) {
      brush.set(detail > 0.6 ? "rotring" : "2B", "#161d26", w * 0.9);
      line3D(xIn, y0 - 0.8, z0, xIn, y0 - 0.8, z1);
    }
    // Pale ochre top-edge catchlight on the beam
    if (detail > 0.42) {
      brush.set("plastic_glint", "#d8cbb8", w * 0.55);
      line3D(xIn, y0 + beamH, z0 + 2, xIn, y0 + beamH, z1 - 2);
    }
  }

  // 3. Floor-level bolted footplate & faded ochre column guard (t === 0)
  if (t === 0 && detail > 0.38) {
    brush.set("plastic_glint", "#bfa67a", w * 1.3);
    line3D(xIn, 0, z0 - 2, xIn, 16, z0 - 2);
    line3D(xIn, 0, z0 + 4, xIn, 16, z0 + 4);
    brush.set("fine_needle", "#1a2028", w * 0.9);
    line3D(xIn - side * 4, 0, z0 - 4, xIn + side * 6, 0, z0 + 6);
  }
}

// ---------------------------------------------------------------------------
// STAGE 5: Cold Shafts of Skylight & Drifting Dust Washes
// ---------------------------------------------------------------------------
function buildSkylightShaftsAndDust() {
  // Three volumetric diagonal shafts cutting down from upper-left/center vault to right/floor
  const shafts = [
    // Primary foreground/midground shaft illuminating the lone shopper at Z ≈ 590
    { zA: 490, zB: 750, xTopL: -58, xTopR: 48, xBotL: -72, xBotR: 132, main: true },
    // Mid-canyon shaft
    { zA: 1040, zB: 1310, xTopL: -52, xTopR: 52, xBotL: -55, xBotR: 130, main: false },
    // Deep-canyon shaft
    { zA: 1640, zB: 1940, xTopL: -48, xTopR: 48, xBotL: -45, xBotR: 125, main: false }
  ];

  for (let sh of shafts) {
    let zMid = (sh.zA + sh.zB) * 0.5;
    // Layered grey wash
    queuePoly("skyBeamGrey", [
      [sh.xTopL, 810, zMid], [sh.xTopR, 810, zMid],
      [sh.xBotR, 0, sh.zB], [sh.xBotL, 0, sh.zA]
    ]);
    // Layered pale ochre dust wash inside the core of the beam
    queuePoly("skyBeamOchre", [
      [sh.xTopL + 14, 790, zMid], [sh.xTopR - 10, 790, zMid],
      [sh.xBotR - 18, 0, sh.zB - 20], [sh.xBotL + 18, 0, sh.zA + 20]
    ]);
  }

  flushBatch("skyBeamGrey", 0.04);
  flushBatch("skyBeamOchre", 0.04);

  // Diagonal volumetric light rays & drifting dust motes
  for (let sh of shafts) {
    let zMid = (sh.zA + sh.zB) * 0.5;
    let numRays = sh.main ? 28 : 16;
    for (let i = 0; i < numRays; i++) {
      let frac = i / (numRays - 1);
      let xT = lerp(sh.xTopL, sh.xTopR, frac) + random(-6, 6);
      let xB = lerp(sh.xBotL, sh.xBotR, frac) + random(-8, 8);
      let yStart = random(580, 810);
      let yEnd = random(0, 260);
      let zRay = lerp(sh.zA, sh.zB, random(0.2, 0.8));

      let p1 = project(xT, yStart, zMid);
      let p2 = project(xB, yEnd, zRay);

      // Soft smudge rays + fine pencil rays
      if (i % 3 === 0) {
        brush.set("smudge_charcoal", i % 2 === 0 ? "#e6dec8" : "#dce6f0", random(0.22, 0.45));
        brush.line(p1.x, p1.y, p2.x, p2.y);
      } else {
        brush.set("plastic_glint", i % 2 === 0 ? "#efe7d3" : "#e3edf7", random(0.25, 0.55));
        brush.line(p1.x, p1.y, p2.x, p2.y);
      }
    }

    // Drifting dust motes suspended in the light beam
    let moteCount = sh.main ? 65 : 30;
    for (let m = 0; m < moteCount; m++) {
      let t = random(0.05, 0.95);
      let my = lerp(20, 720, t);
      let mx = lerp(lerp(sh.xBotL, sh.xBotR, random()), lerp(sh.xTopL, sh.xTopR, random()), t);
      let mz = random(sh.zA, sh.zB);
      let pm = project(mx, my, mz);
      if (pm.y > 60 && pm.y < 1080) {
        brush.set("spray", m % 2 === 0 ? "#f2ebd9" : "#ebf3fa", random(0.3, 0.75));
        brush.line(pm.x, pm.y, pm.x + random(-4, 4), pm.y + random(-4, 4));
      }
    }
  }
}

// ---------------------------------------------------------------------------
// STAGE 6: Top-of-Image Smudged Infinity
// ---------------------------------------------------------------------------
function buildTopSmudgedInfinity() {
  // Dissolve the top 220px of the canvas into soft, smudged charcoal & slate haze
  for (let i = 0; i < 38; i++) {
    let y = pow(random(), 1.6) * 240;
    let x1 = random(-60, 900);
    let x2 = x1 + random(180, 520);
    let col = y < 95 ? "#1e2631" : (y < 165 ? "#2f3b4a" : "#495869");
    // Leave a misty luminous opening around the central skylights (x = 460..720)
    if (x1 > 420 && x2 < 760 && y > 70) {
      col = "#8c9aa8";
    }
    brush.set("smudge_charcoal", col, map(y, 0, 240, 1.35, 0.45));
    brush.line(x1, y, x2, y + random(-18, 18));
  }

  // Smudged vertical charcoal passes along the upper left and right rack rims
  for (let i = 0; i < 24; i++) {
    let sideX = i % 2 === 0 ? random(20, 430) : random(750, 1180);
    let y1 = random(-20, 120);
    let y2 = y1 + random(120, 260);
    brush.set("smudge_charcoal", "#242e3b", random(0.6, 1.2));
    brush.line(sideX, y1, sideX + random(-25, 25), y2);
  }
}

// ---------------------------------------------------------------------------
// STAGE 7: Foreground Rack Sharpening & Hanging Aisle Placards
// ---------------------------------------------------------------------------
function buildForegroundRackDetails() {
  // Hanging aisle bay placards jutting slightly into the aisle at Y = 88
  for (let z of [310, 570, 830]) {
    for (let side of [-1, 1]) {
      let x0 = side * 135;
      let x1 = side * 124;
      let pA = project(x0, 92, z);
      let pB = project(x1, 92, z);
      let pC = project(x1, 81, z);
      let pD = project(x0, 81, z);

      brush.noStroke();
      brush.wash("#e6ecf2", 215);
      drawPolyShape([pA, pB, pC, pD], 0);
      brush.noWash();

      brush.set("fine_needle", "#1a222c", 0.75);
      brush.line(pA.x, pA.y, pB.x, pB.y);
      brush.line(pB.x, pB.y, pC.x, pC.y);
      brush.line(pC.x, pC.y, pD.x, pD.y);
      // Tiny placard code glyph lines
      let midY = (pA.y + pC.y) * 0.5;
      brush.line(lerp(pA.x, pB.x, 0.25), midY, lerp(pA.x, pB.x, 0.75), midY);
    }
  }

  // Loose hanging shrink-wrap plastic tails catching skylight in foreground
  let tails = [
    { side: -1, y: 152, z: 360, len: 18 },
    { side: 1,  y: 150, z: 485, len: 15 },
    { side: 1,  y: 76,  z: 340, len: 14 },
    { side: -1, y: 226, z: 510, len: 16 }
  ];
  for (let tl of tails) {
    let p1 = project(tl.side * 136, tl.y, tl.z);
    let p2 = project(tl.side * 131, tl.y - tl.len * 0.6, tl.z + 4);
    let p3 = project(tl.side * 133, tl.y - tl.len, tl.z + 2);
    brush.set("plastic_glint", "#eef5fc", 0.85);
    brush.spline([[p1.x, p1.y, 0.8], [p2.x, p2.y, 1.1], [p3.x, p3.y, 0.3]], 0.5);
  }
}

// ---------------------------------------------------------------------------
// STAGE 8: The Lone Shopper & Trolley (Hyperreal Pencil Anchor)
// ---------------------------------------------------------------------------
function buildLoneShopperAndTrolley() {
  // Position in the luminous pool of skylight at Z ≈ 585, X ≈ -16
  const sx = -18;
  const sz = 595;

  // 1. FLOOR REFLECTION & CAST SHADOW ON POLISHED CONCRETE
  let pFoot = project(sx, 0, sz);
  let pCartFront = project(sx + 24, 0, sz - 34);

  // Soft vertical reflection of shopper & trolley in the wet-look concrete slab
  for (let i = 0; i < 18; i++) {
    let rx = pFoot.x + map(i, 0, 17, -14, 38);
    let ry1 = pFoot.y + 2;
    let ry2 = pFoot.y + (i < 8 ? random(45, 78) : random(20, 42));
    brush.set("HB", i < 8 ? "#222b36" : "#3a4654", random(0.45, 0.85));
    brush.line(rx, ry1, rx, ry2);
  }

  // Crisp cast shadow to the left-front (cast by the overhead right/center skylight)
  let sh1 = project(sx - 4, 0, sz + 2);
  let sh2 = project(sx + 10, 0, sz - 30);
  let sh3 = project(sx - 44, 0, sz - 38);
  let sh4 = project(sx - 52, 0, sz - 4);
  brush.noStroke();
  brush.wash("#222b36", 135);
  drawPolyShape([sh1, sh2, sh3, sh4], 0.05);
  brush.noWash();

  // Cross-hatched graphite shadow core right beneath shoes and caster wheels
  brush.set("fine_needle", "#12171f", 0.85);
  for (let k = 0; k < 14; k++) {
    let yOff = k * 1.4;
    brush.line(pFoot.x - 16 - k * 1.2, pFoot.y + yOff, pCartFront.x + 8, pCartFront.y + yOff * 0.6);
  }

  // 2. THE WAREHOUSE TROLLEY (in front-right of shopper, angled slightly along aisle)
  // Trolley bounding coordinates: X from -9 to +13, Z from 548 to 586, Y from 0 to 41
  const cx0 = -9, cx1 = 13;
  const cz0 = 548, cz1 = 586; // cz0 is front (closer to camera), cz1 is rear (handle end)

  // Four caster wheels (Y = 0 to 6.5)
  const wheels = [
    [cx0 + 1.5, cz0 + 4], [cx1 - 1.5, cz0 + 4],
    [cx0 + 1.5, cz1 - 4], [cx1 - 1.5, cz1 - 4]
  ];
  for (let [wx, wz] of wheels) {
    let pw = project(wx, 3.0, wz);
    // Dark rubber wheel disc
    brush.set("rotring", "#10151c", 1.15);
    brush.circle(pw.x, pw.y, 4.2, 0.15);
    brush.set("fine_needle", "#10151c", 0.95);
    brush.circle(pw.x, pw.y, 2.2, 0.1);
    // Metallic caster fork bracket
    brush.set("fine_needle", "#cfd9e3", 0.85);
    line3D(wx, 3.2, wz, wx, 7.0, wz);
  }

  // Lower tubular chassis frame (Y = 7)
  brush.set("fine_needle", "#2b3542", 1.05);
  line3D(cx0, 7, cz0, cx1, 7, cz0);
  line3D(cx1, 7, cz0, cx1, 7, cz1);
  line3D(cx0, 7, cz0, cx0, 7, cz1);
  line3D(cx0, 7, cz1, cx1, 7, cz1);
  // Specular glint on lower frame
  brush.set("fine_needle", "#dce6f0", 0.65);
  line3D(cx0, 7.5, cz0, cx1, 7.5, cz0);
  line3D(cx1, 7.5, cz0, cx1, 7.5, cz1);

  // Two small bulk cartons sitting inside the trolley basket (Y = 17 to 29)
  let b1A = project(cx0 + 2, 17, cz0 + 4);
  let b1B = project(cx1 - 2, 17, cz0 + 4);
  let b1C = project(cx1 - 2, 28, cz0 + 4);
  let b1D = project(cx0 + 2, 28, cz0 + 4);
  let b1E = project(cx1 - 2, 28, cz0 + 22);
  let b1F = project(cx1 - 2, 17, cz0 + 22);

  brush.noStroke();
  brush.wash("#52585e", 210);
  drawPolyShape([b1A, b1B, b1C, b1D], 0);
  brush.wash("#8c8377", 210);
  drawPolyShape([b1B, b1F, b1E, b1C], 0);
  brush.noWash();

  // Wire basket geometry (bottom at Y = 16.5, top rim at Y = 36 front to 39 rear)
  // Rear handle uprights rising from (cx0, 7, cz1) and (cx1, 7, cz1) to handlebar at Y = 41.5
  brush.set("fine_needle", "#252f3b", 1.1);
  line3D(cx0, 7, cz1, cx0 - 1, 41.5, cz1 + 3);
  line3D(cx1, 7, cz1, cx1 + 1, 41.5, cz1 + 3);

  // Basket main rim & base wires
  line3D(cx0, 16.5, cz0 + 2, cx1, 16.5, cz0 + 2);
  line3D(cx1, 16.5, cz0 + 2, cx1, 16.5, cz1);
  line3D(cx0, 16.5, cz0 + 2, cx0, 16.5, cz1);

  line3D(cx0 - 1, 35.5, cz0, cx1 + 1, 35.5, cz0);
  line3D(cx1 + 1, 35.5, cz0, cx1, 39, cz1);
  line3D(cx0 - 1, 35.5, cz0, cx0, 39, cz1);
  line3D(cx0, 39, cz1, cx1, 39, cz1);

  // Corner struts of basket
  line3D(cx0, 16.5, cz0 + 2, cx0 - 1, 35.5, cz0);
  line3D(cx1, 16.5, cz0 + 2, cx1 + 1, 35.5, cz0);

  // Fine vertical & horizontal steel mesh wires of the basket
  for (let i = 1; i <= 6; i++) {
    let f = i / 7;
    // Side vertical wires
    let wz = lerp(cz0 + 1, cz1, f);
    let wyTop = lerp(35.5, 39, f);
    brush.set("fine_needle", i % 2 === 0 ? "#424f5e" : "#e3ecf5", 0.52);
    line3D(cx1 + 0.5 * (1 - f), 16.5, wz, cx1 + (1 - f), wyTop, wz);
    line3D(cx0 - 0.5 * (1 - f), 16.5, wz, cx0 - (1 - f), wyTop, wz);
  }
  for (let i = 1; i <= 4; i++) {
    let f = i / 5;
    let wx = lerp(cx0, cx1, f);
    brush.set("fine_needle", i % 2 === 0 ? "#384452" : "#dce6f0", 0.5);
    line3D(wx, 16.5, cz0 + 2, wx, 35.5, cz0);
  }
  // Horizontal basket ribs with bright skylight catchlights
  for (let hy of [22, 28, 33]) {
    brush.set("fine_needle", "#36424f", 0.55);
    line3D(cx0 - 0.5, hy, cz0 + 1, cx1 + 0.5, hy, cz0 + 1);
    brush.set("fine_needle", "#eef5fc", 0.55);
    line3D(cx1 + 0.5, hy, cz0 + 1, cx1, hy + 1.5, cz1);
  }
  // Top rim bright metallic highlight
  brush.set("fine_needle", "#f5f9fc", 0.85);
  line3D(cx0 - 1, 35.8, cz0, cx1 + 1, 35.8, cz0);
  line3D(cx1 + 1, 35.8, cz0, cx1, 39.3, cz1);

  // Handlebar at Y = 41.5, Z = cz1 + 3
  brush.set("rotring", "#141a22", 1.25);
  line3D(cx0 - 1, 41.5, cz1 + 3, cx1 + 1, 41.5, cz1 + 3);
  brush.set("fine_needle", "#e8eef5", 0.7);
  line3D(cx0, 42.0, cz1 + 3, cx1, 42.0, cz1 + 3);

  // 3. THE LONE SHOPPER (Standing at X = sx = -18, Z = sz = 595, Y = 0 to 67)
  // Project key anatomical landmarks onto 2D canvas for intricate graphite modeling
  let pAnkleL = project(sx - 3.5, 2.5, sz + 2);
  let pAnkleR = project(sx + 4.0, 2.5, sz - 2);
  let pKneeL  = project(sx - 3.2, 16.5, sz + 1);
  let pKneeR  = project(sx + 3.8, 16.5, sz - 2);
  let pHipL   = project(sx - 4.8, 31.5, sz + 1);
  let pHipR   = project(sx + 5.2, 31.5, sz - 1);
  let pShldrL = project(sx - 6.5, 53.5, sz + 2);
  let pShldrR = project(sx + 6.8, 54.0, sz - 2);
  let pNeck   = project(sx + 0.5, 56.0, sz);
  let pHead   = project(sx + 1.2, 62.5, sz - 1); // Head tilted slightly up and right
  let pElbowR = project(sx + 8.5, 44.5, sz - 4);
  let pHandR  = project(cx0 + 4.5, 41.8, cz1 + 3); // Right hand resting on trolley bar
  let pElbowL = project(sx - 7.2, 43.0, sz + 2);
  let pHandL  = project(sx - 5.5, 33.5, sz - 1);   // Left hand near coat pocket

  // A. Shoes / Boots
  brush.noStroke();
  brush.wash("#12171e", 240);
  drawPolyShape([
    { x: pAnkleL.x - 4, y: pAnkleL.y - 2 },
    { x: pAnkleL.x + 5, y: pAnkleL.y - 2 },
    { x: pAnkleL.x + 7, y: pAnkleL.y + 4 },
    { x: pAnkleL.x - 5, y: pAnkleL.y + 4 }
  ], 0.1);
  drawPolyShape([
    { x: pAnkleR.x - 3, y: pAnkleR.y - 2 },
    { x: pAnkleR.x + 6, y: pAnkleR.y - 2 },
    { x: pAnkleR.x + 9, y: pAnkleR.y + 4 },
    { x: pAnkleR.x - 4, y: pAnkleR.y + 4 }
  ], 0.1);
  brush.noWash();
  // Pale rubber shoe soles
  brush.set("fine_needle", "#cfd8e2", 0.8);
  brush.line(pAnkleL.x - 4, pAnkleL.y + 4, pAnkleL.x + 6, pAnkleL.y + 4);
  brush.line(pAnkleR.x - 3, pAnkleR.y + 4, pAnkleR.x + 8, pAnkleR.y + 4);

  // B. Trousers (Left & Right legs in deep slate-charcoal with rim light on right)
  brush.noStroke();
  brush.wash("#1d2530", 235);
  // Left leg polygon
  drawPolyShape([
    { x: pHipL.x - 2, y: pHipL.y },
    { x: pHipL.x + 8, y: pHipL.y },
    { x: pKneeL.x + 5, y: pKneeL.y },
    { x: pAnkleL.x + 4, y: pAnkleL.y },
    { x: pAnkleL.x - 4, y: pAnkleL.y },
    { x: pKneeL.x - 4, y: pKneeL.y }
  ], 0.05);
  // Right leg polygon
  drawPolyShape([
    { x: pHipR.x - 7, y: pHipR.y },
    { x: pHipR.x + 3, y: pHipR.y },
    { x: pKneeR.x + 5, y: pKneeR.y },
    { x: pAnkleR.x + 4, y: pAnkleR.y },
    { x: pAnkleR.x - 4, y: pAnkleR.y },
    { x: pKneeR.x - 4, y: pKneeR.y }
  ], 0.05);
  brush.noWash();

  // Graphite drapery & trouser folds
  brush.set("fine_needle", "#0d1218", 0.9);
  brush.line(pHipL.x - 2, pHipL.y, pAnkleL.x - 4, pAnkleL.y);
  brush.line(pHipL.x + 6, pHipL.y + 4, pAnkleL.x + 3, pAnkleL.y);
  brush.line(pHipR.x - 4, pHipR.y + 4, pAnkleR.x - 3, pAnkleR.y);
  brush.line(pHipR.x + 3, pHipR.y, pAnkleR.x + 4, pAnkleR.y);
  // Rim-lit right trouser edge catching the skylight
  brush.set("fine_needle", "#cad6e2", 0.85);
  brush.line(pHipR.x + 3, pHipR.y + 2, pKneeR.x + 4.5, pKneeR.y);
  brush.line(pKneeR.x + 4.5, pKneeR.y, pAnkleR.x + 4, pAnkleR.y - 1);

  // C. Winter Jacket / Coat Torso & Arms
  let coatHemL = { x: pHipL.x - 4, y: pHipL.y + 5 };
  let coatHemR = { x: pHipR.x + 5, y: pHipR.y + 4 };
  let collarL  = { x: pNeck.x - 6, y: pNeck.y + 2 };
  let collarR  = { x: pNeck.x + 6, y: pNeck.y + 1 };

  // Core dark jacket wash
  brush.noStroke();
  brush.wash("#19222d", 242);
  drawPolyShape([
    { x: pShldrL.x - 2, y: pShldrL.y + 2 },
    collarL, collarR,
    { x: pShldrR.x + 2, y: pShldrR.y + 1 },
    { x: pElbowR.x + 3, y: pElbowR.y },
    { x: pHandR.x + 2, y: pHandR.y + 2 },
    { x: pHandR.x - 3, y: pHandR.y + 3 },
    { x: pElbowR.x - 4, y: pElbowR.y + 3 },
    coatHemR, coatHemL,
    { x: pHandL.x - 3, y: pHandL.y },
    { x: pElbowL.x - 3, y: pElbowL.y }
  ], 0.04);

  // Skylight illuminated shoulder & upper back plane
  brush.wash("#6b7c8e", 175);
  drawPolyShape([
    collarL, collarR,
    { x: pShldrR.x + 2, y: pShldrR.y + 1 },
    { x: pElbowR.x + 2, y: pElbowR.y - 1 },
    { x: pShldrR.x - 5, y: pShldrR.y + 10 },
    { x: pShldrL.x + 2, y: pShldrL.y + 7 }
  ], 0.05);
  brush.noWash();

  // Fine graphite hatching & structural folds on the jacket
  brush.set("fine_needle", "#0c1017", 0.95);
  // Left contour & left sleeve
  brush.line(pShldrL.x - 2, pShldrL.y + 2, pElbowL.x - 3, pElbowL.y);
  brush.line(pElbowL.x - 3, pElbowL.y, pHandL.x - 2, pHandL.y);
  brush.line(pShldrL.x + 4, pShldrL.y + 10, coatHemL.x, coatHemL.y);
  // Coat bottom hem & center seam
  brush.line(coatHemL.x, coatHemL.y, coatHemR.x, coatHemR.y);
  brush.line(pNeck.x + 1, pNeck.y + 2, (coatHemL.x + coatHemR.x) * 0.5 + 2, coatHemR.y);

  // Right arm reaching to trolley handle
  brush.line(pShldrR.x + 2, pShldrR.y + 1, pElbowR.x + 2, pElbowR.y);
  brush.line(pElbowR.x + 2, pElbowR.y, pHandR.x + 1, pHandR.y);
  brush.line(pShldrR.x - 2, pShldrR.y + 9, pElbowR.x - 3, pElbowR.y + 3);
  brush.line(pElbowR.x - 3, pElbowR.y + 3, pHandR.x - 2, pHandR.y + 2);

  // Dense graphite cross-hatching on the shadow side of the coat (left half of torso)
  brush.set("fine_needle", "#111720", 0.72);
  for (let h = 0; h < 18; h++) {
    let ty = lerp(pShldrL.y + 3, coatHemL.y - 2, h / 17);
    brush.line(pShldrL.x - 1, ty, pNeck.x + random(-1, 3), ty + 3);
  }

  // Crisp luminous skylight rim highlights on collar, shoulders, right sleeve, and hand!
  brush.set("fine_needle", "#edf4fa", 1.05);
  brush.line(collarL.x + 1, collarL.y - 1, collarR.x + 1, collarR.y - 1);
  brush.line(collarR.x, collarR.y, pShldrR.x + 2, pShldrR.y + 1);
  brush.line(pShldrR.x + 2, pShldrR.y + 1, pElbowR.x + 2, pElbowR.y);
  brush.line(pElbowR.x + 2, pElbowR.y, pHandR.x, pHandR.y - 1);

  // Pale ochre secondary highlight on upper back/shoulder
  brush.set("fine_needle", "#e8dfc9", 0.85);
  brush.line(collarL.x + 2, collarL.y + 1, pShldrR.x, pShldrR.y + 3);
  brush.line(pShldrL.x, pShldrL.y + 2, collarL.x, collarL.y);

  // Right hand gripping the trolley bar
  brush.noStroke();
  brush.wash("#dfd3c3", 235);
  brush.circle(pHandR.x, pHandR.y, 2.8, 0.1);
  brush.noWash();
  brush.set("fine_needle", "#2b2622", 0.7);
  brush.arc(pHandR.x, pHandR.y, 2.8, 0, 180);

  // D. Head & Upturned Gaze (looking up toward the towering right canyon wall)
  brush.noStroke();
  // Illuminated upturned face/profile on right side of head
  brush.wash("#dfd5c6", 235);
  drawPolyShape([
    { x: pHead.x, y: pHead.y - 6 },
    { x: pHead.x + 6.5, y: pHead.y - 4.5 }, // Upturned nose/forehead profile
    { x: pHead.x + 6.0, y: pHead.y + 1.5 }, // Chin tilted up
    { x: pNeck.x + 2.5, y: pNeck.y + 1 },
    { x: pNeck.x - 2.5, y: pNeck.y + 1 }
  ], 0.08);

  // Dark hair / cap crown on back-left of head
  brush.wash("#161d26", 245);
  drawPolyShape([
    { x: pHead.x - 6.5, y: pHead.y - 2 },
    { x: pHead.x - 4.0, y: pHead.y - 7.5 },
    { x: pHead.x + 3.5, y: pHead.y - 7.5 },
    { x: pHead.x + 1.0, y: pHead.y - 1.5 },
    { x: pNeck.x - 3.0, y: pNeck.y + 1 }
  ], 0.1);
  brush.noWash();

  // Crisp graphite definition of the head, ear, jawline, and skylight crown highlight
  brush.set("fine_needle", "#121820", 0.9);
  brush.line(pHead.x - 6.2, pHead.y - 2, pNeck.x - 3, pNeck.y + 1);
  brush.line(pHead.x + 6.2, pHead.y - 4.5, pHead.x + 5.8, pHead.y + 1.2);
  brush.line(pHead.x + 5.8, pHead.y + 1.2, pNeck.x + 2.0, pNeck.y + 0.5);

  // Bright skylight highlight on crown of head and upturned forehead/bridge of nose
  brush.set("fine_needle", "#f5f9fc", 1.05);
  brush.line(pHead.x - 3.5, pHead.y - 7.8, pHead.x + 3.8, pHead.y - 7.2);
  brush.line(pHead.x + 3.8, pHead.y - 7.2, pHead.x + 6.5, pHead.y - 4.2);
}

