// =============================================================================
// CORE RENDERING & ENGRAVING UTILITIES
// =============================================================================

function fillPoly(pts, col, opacity, bleed = 0.04, tex = 0.42, border = 0.32, dir = "in") {
  if (!pts || pts.length < 3) return;
  brush.noStroke();
  brush.noHatch();
  brush.fill(col, opacity);
  brush.fillBleed(bleed, dir);
  brush.fillTexture(tex, border);
  brush.beginShape(0);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
  brush.noFill();
}

function hatchPoly(pts, angle, dist, col = PALETTE.inkDark, weight = 0.75, crossAngle = null, crossDist = null, opts = {}) {
  if (!pts || pts.length < 3) return;
  let poly = new brush.Polygon(pts);
  brush.noFill();
  brush.noStroke();
  let bName = opts.brush || "engraver";
  brush.set(bName, col, weight);
  brush.hatchStyle(bName, col, weight);
  poly.hatch(dist, angle, {
    rand: opts.rand !== undefined ? opts.rand : 0.018,
    continuous: false,
    gradient: opts.gradient || 0
  });
  if (crossAngle !== null) {
    let cbName = opts.crossBrush || "etch_needle";
    brush.set(cbName, col, weight * 0.82);
    brush.hatchStyle(cbName, col, weight * 0.82);
    poly.hatch(crossDist || dist * 1.18, crossAngle, {
      rand: opts.rand !== undefined ? opts.rand : 0.018,
      continuous: false,
      gradient: opts.gradient || 0
    });
  }
  brush.noHatch();
}

// Strokes a crystal facet with directional lighting & glassy ridge highlights
function strokeFacet(pts, baseWeight = 0.85, highlightRidges = true) {
  if (!pts || pts.length < 2) return;
  brush.noFill();
  brush.noHatch();
  for (let i = 0; i < pts.length; i++) {
    let p1 = pts[i];
    let p2 = pts[(i + 1) % pts.length];
    let dx = p2[0] - p1[0];
    let dy = p2[1] - p1[1];
    let len = sqrt(dx * dx + dy * dy);
    if (len < 1) continue;
    // Outward normal approximation
    let nx = dy / len;
    let ny = -dx / len;
    let lightDot = nx * LIGHT.x + ny * LIGHT.y;

    if (lightDot > 0.15) {
      // Lit edge: delicate slate line + sharp white adjacent ridge
      brush.set("etch_needle", PALETTE.inkMid, baseWeight * 0.75);
      brush.line(p1[0], p1[1], p2[0], p2[1]);
      if (highlightRidges && len > 8) {
        let ox = -nx * 1.1;
        let oy = -ny * 1.1;
        brush.set("gouache_white", PALETTE.white, baseWeight * 0.95);
        brush.line(
          p1[0] + dx * 0.08 + ox,
          p1[1] + dy * 0.08 + oy,
          p2[0] - dx * 0.08 + ox,
          p2[1] - dy * 0.08 + oy
        );
      }
    } else {
      // Shadowed edge: crisp dark engraving burin
      brush.set("engraver", PALETTE.inkDeep, baseWeight * 1.15);
      brush.line(p1[0], p1[1], p2[0], p2[1]);
    }
  }
}

// Shades a planar crystal facet based on its 3D surface normal
function renderCrystalFacet(pts, nx, ny, nz, paletteObj, hatchBaseAngle = 30, opacityScale = 1.0) {
  let nLen = sqrt(nx * nx + ny * ny + nz * nz) || 1;
  nx /= nLen; ny /= nLen; nz /= nLen;
  let dotL = nx * LIGHT.x + ny * LIGHT.y + nz * LIGHT.z; // -1 to 1

  // 1. Hand-tinted mineral watercolor wash inside the facet
  if (dotL > 0.45) {
    // High-light facet: very pale wash, leaving crystalline brightness
    fillPoly(pts, paletteObj.pale, 45 * opacityScale, 0.03, 0.35, 0.25);
  } else if (dotL > 0.05) {
    fillPoly(pts, paletteObj.light, 75 * opacityScale, 0.04, 0.45, 0.35);
  } else if (dotL > -0.35) {
    fillPoly(pts, paletteObj.mid, 95 * opacityScale, 0.04, 0.5, 0.4);
  } else {
    fillPoly(pts, paletteObj.deep, 115 * opacityScale, 0.05, 0.55, 0.45);
  }

  // 2. Engraved crystallographic cross-hatching
  if (dotL > 0.55) {
    // Nearly specular face: only a few partial cleavage lines near edges
    hatchPoly(pts, hatchBaseAngle, 9.5, PALETTE.inkLight, 0.55, null, null, {
      brush: "etch_needle",
      gradient: 0.7
    });
  } else if (dotL > 0.2) {
    hatchPoly(pts, hatchBaseAngle, 5.2, PALETTE.inkMid, 0.65, null, null, {
      brush: "etch_needle",
      gradient: 0.35
    });
  } else if (dotL > -0.15) {
    hatchPoly(pts, hatchBaseAngle, 3.6, PALETTE.inkDark, 0.72, hatchBaseAngle + 28, 5.2, {
      gradient: 0.2
    });
  } else if (dotL > -0.45) {
    hatchPoly(pts, hatchBaseAngle, 2.7, PALETTE.inkDark, 0.82, hatchBaseAngle + 32, 3.4);
  } else {
    // Deep shadow face: three-layer copperplate hatching
    hatchPoly(pts, hatchBaseAngle, 2.2, PALETTE.inkDeep, 0.9, hatchBaseAngle + 30, 2.7);
    hatchPoly(pts, hatchBaseAngle - 25, 4.2, PALETTE.inkDeep, 0.7, null, null, {
      brush: "etch_needle"
    });
  }

  // 3. Facet edges & specular ridge
  strokeFacet(pts, 0.85, dotL > 0.0);
}

// Draws scholarly cast shadow with refracted colored caustic core
function drawSpecimenShadow(silhouettePts, dx, dy, causticCol, causticAlpha = 70) {
  let outerPts = silhouettePts.map(p => [p[0] + dx * 1.12, p[1] + dy * 1.12]);
  let umbraPts = silhouettePts.map(p => [p[0] + dx * 0.62, p[1] + dy * 0.62]);

  // Compute centroid of shifted shadow for caustic focus
  let cx = 0, cy = 0;
  for (let p of outerPts) { cx += p[0]; cy += p[1]; }
  cx /= outerPts.length; cy /= outerPts.length;

  let causticPts = outerPts.map(p => [
    lerp(cx + dx * 0.15, p[0], 0.52),
    lerp(cy + dy * 0.15, p[1], 0.52)
  ]);

  // Soft slate penumbra
  fillPoly(outerPts, PALETTE.shadowWash, 48, 0.09, 0.4, 0.2, "out");
  // Refracted jewel caustic inside shadow
  if (causticCol) {
    fillPoly(causticPts, causticCol, causticAlpha, 0.08, 0.35, 0.2, "in");
  }
  // Inner umbra near base of sweet
  fillPoly(umbraPts, PALETTE.shadowUmbra, 68, 0.05, 0.45, 0.3, "in");

  // Engraved horizontal & acute diagonal shadow hatching
  hatchPoly(outerPts, -8, 3.3, PALETTE.inkMid, 0.65, null, null, {
    brush: "etch_needle",
    gradient: 0.3
  });
  hatchPoly(umbraPts, -8, 2.3, PALETTE.inkDark, 0.78, -34, 3.0);

  // Crisp contact occlusion along lower-right contour
  brush.set("engraver", PALETTE.inkDeep, 1.35);
  for (let i = 0; i < silhouettePts.length; i++) {
    let p1 = silhouettePts[i];
    let p2 = silhouettePts[(i + 1) % silhouettePts.length];
    let mx = (p1[0] + p2[0]) * 0.5;
    let my = (p1[1] + p2[1]) * 0.5;
    if (mx > cx - dx * 1.2 && my > cy - dy * 1.2) {
      brush.line(p1[0] + 1.5, p1[1] + 2.0, p2[0] + 1.5, p2[1] + 2.0);
    }
  }
}

// Draws an internal trapped air bubble (vesicle) inside translucent boiled sugar
function drawVesicle(x, y, r, jewelCol = null, stretch = 1.0, rot = -30) {
  push();
  translate(x, y);
  rotate(rot);

  // Subtle internal refraction tint
  if (jewelCol && r > 3) {
    let bPts = [];
    for (let a = 0; a < 360; a += 45) {
      bPts.push([cos(a) * r * stretch, sin(a) * r]);
    }
    fillPoly(bPts, jewelCol, 55, 0.02, 0.2, 0.2);
  }

  // Dark upper-left refractive rim
  brush.set("etch_needle", PALETTE.inkDeep, map(r, 1.5, 10, 0.55, 0.95, true));
  let rimPts = [];
  for (let a = 145; a <= 325; a += 30) {
    rimPts.push([cos(a) * r * stretch, sin(a) * r]);
  }
  brush.spline(rimPts, 0.5);

  // Lower-right faint rim
  brush.set("etch_needle", PALETTE.inkMid, 0.5);
  let lowPts = [];
  for (let a = -35; a <= 145; a += 30) {
    lowPts.push([cos(a) * r * stretch, sin(a) * r]);
  }
  brush.spline(lowPts, 0.5);

  // Lower-right internal caustic crescent + upper-left specular pinpoint
  brush.set("gouache_white", PALETTE.white, map(r, 1.5, 10, 0.65, 1.25, true));
  let cPts = [];
  for (let a = 15; a <= 115; a += 25) {
    cPts.push([cos(a) * r * 0.72 * stretch, sin(a) * r * 0.72]);
  }
  brush.spline(cPts, 0.5);

  // Pinpoint highlight
  let hx = cos(225) * r * 0.48 * stretch;
  let hy = sin(225) * r * 0.48;
  brush.line(hx - 0.8, hy - 0.8, hx + 0.8, hy + 0.8);

  pop();
}

// Scatters tiny 3D isometric sugar granules around a specimen on the paper
function drawLooseSugarCrystals(cx, cy, count, rx, ry, palObj) {
  for (let i = 0; i < count; i++) {
    let ang = random(360);
    let distR = random(0.78, 1.22);
    // Bias granules toward the lower-right & sides
    let gx = cx + cos(ang) * rx * distR;
    let gy = cy + sin(ang) * ry * distR + random(4, 14);
    let sz = random(2.8, 7.2);
    let rot = random(360);

    // Tiny granule shadow
    brush.set("engraver", PALETTE.shadowUmbra, 1.1);
    brush.line(gx + 1, gy + sz * 0.6, gx + sz * 1.1, gy + sz * 0.9);

    // 3 isometric rhomb vertices around center
    let topFace = [], leftFace = [], rightFace = [];
    let pCenter = [gx, gy];
    let pTop = [gx + cos(rot - 90) * sz, gy + sin(rot - 90) * sz * 0.85];
    let pRight = [gx + cos(rot - 30) * sz, gy + sin(rot - 30) * sz * 0.85];
    let pBotRight = [gx + cos(rot + 30) * sz, gy + sin(rot + 30) * sz * 0.85];
    let pBot = [gx + cos(rot + 90) * sz, gy + sin(rot + 90) * sz * 0.85];
    let pBotLeft = [gx + cos(rot + 150) * sz, gy + sin(rot + 150) * sz * 0.85];
    let pLeft = [gx + cos(rot - 150) * sz, gy + sin(rot - 150) * sz * 0.85];

    topFace = [pCenter, pLeft, pTop, pRight];
    leftFace = [pCenter, pBotLeft, pBot, pLeft];
    rightFace = [pCenter, pRight, pBotRight, pBot];

    if (sz > 4.2 && palObj) {
      fillPoly(topFace, palObj.pale, 60, 0.01, 0.2, 0.2);
      fillPoly(rightFace, palObj.mid, 85, 0.01, 0.2, 0.2);
    }

    // Crisp micro-engraving
    brush.set("etch_needle", PALETTE.inkDark, 0.65);
    strokeFacet(topFace, 0.55, false);
    strokeFacet(leftFace, 0.6, false);
    strokeFacet(rightFace, 0.68, false);

    // Tiny specular spark on center vertex
    brush.set("gouache_white", PALETTE.white, 0.95);
    brush.line(gx - 0.9, gy - 0.9, gx + 0.9, gy + 0.4);
  }
}

// Draws curved skylight window reflection on glossy domed sweets
function drawGlossyWindowHighlight(cx, cy, rx, ry, startAng = 200, endAng = 252, widthBand = 7) {
  let midAng = (startAng + endAng) * 0.5;
  // Two panes of window reflection separated by a mullion gap
  let spans = [
    [startAng, midAng - 2.5],
    [midAng + 2.5, endAng]
  ];

  for (let sp of spans) {
    for (let rOff = 0; rOff <= widthBand; rOff += 1.4) {
      let t = rOff / widthBand;
      let w = sin(t * 180) * 1.35 + 0.45;
      brush.set("gouache_white", PALETTE.white, w);
      let pts = [];
      for (let a = sp[0]; a <= sp[1]; a += 4) {
        pts.push([cx + cos(a) * (rx - rOff), cy + sin(a) * (ry - rOff)]);
      }
      if (pts.length >= 2) brush.spline(pts, 0.5);
    }
  }

  // Secondary lower-right rim bounce reflection
  brush.set("gouache_white", PALETTE.creamWhite, 0.75);
  let rimPts = [];
  for (let a = 20; a <= 68; a += 6) {
    rimPts.push([cx + cos(a) * (rx * 0.9), cy + sin(a) * (ry * 0.9)]);
  }
  brush.spline(rimPts, 0.5);
}

// =============================================================================
// PAPER GROUND & VICTORIAN COPPERPLATE BORDER
// =============================================================================

function drawPaperAndPlateFrame() {
  // Subtle aged paper wash around outer border
  let marginTop = [[0, 0], [1200, 0], [1130, 72], [70, 72]];
  let marginBot = [[70, 1128], [1130, 1128], [1200, 1200], [0, 1200]];
  let marginLeft = [[0, 0], [70, 72], [70, 1128], [0, 1200]];
  let marginRight = [[1130, 72], [1200, 0], [1200, 1200], [1130, 1128]];
  fillPoly(marginTop, PALETTE.paperTone, 42, 0.15, 0.5, 0.2, "out");
  fillPoly(marginBot, PALETTE.paperTone, 48, 0.15, 0.5, 0.2, "out");
  fillPoly(marginLeft, PALETTE.paperTone, 42, 0.15, 0.5, 0.2, "out");
  fillPoly(marginRight, PALETTE.paperTone, 48, 0.15, 0.5, 0.2, "out");

  // Copperplate debossed plate-mark (sunken bevel at x:70..1130, y:72..1128)
  // Top and Left inner shadow of plate depression
  brush.set("etch_needle", PALETTE.inkLight, 0.75);
  brush.line(70, 72, 1130, 72);
  brush.line(70, 72, 70, 1128);
  brush.set("etch_needle", PALETTE.inkFaint, 0.55);
  brush.line(71.5, 73.5, 1128.5, 73.5);
  brush.line(71.5, 73.5, 71.5, 1126.5);

  // Bottom and Right highlight of plate depression
  brush.set("gouache_white", PALETTE.white, 1.1);
  brush.line(70, 1128, 1130, 1128);
  brush.line(1130, 72, 1130, 1128);
  brush.set("etch_needle", PALETTE.inkFaint, 0.45);
  brush.line(70, 1129.5, 1130, 1129.5);
  brush.line(1131.5, 72, 1131.5, 1129.5);

  // Outer heavy engraved rule (x: 92..1108, y: 98..1098)
  brush.set("engraver", PALETTE.inkDeep, 1.35);
  brush.line(92, 98, 1108, 98);
  brush.line(1108, 98, 1108, 1098);
  brush.line(1108, 1098, 92, 1098);
  brush.line(92, 1098, 92, 98);

  // Inner fine engraved rule (x: 99..1101, y: 105..1091)
  brush.set("etch_needle", PALETTE.inkDark, 0.75);
  brush.line(99, 105, 1101, 105);
  brush.line(1101, 105, 1101, 1091);
  brush.line(1101, 1091, 99, 1091);
  brush.line(99, 1091, 99, 105);

  // Corner botanical/mineralogical rosette ticks
  let corners = [[92, 98, 1, 1], [1108, 98, -1, 1], [1108, 1098, -1, -1], [92, 1098, 1, -1]];
  brush.set("etch_needle", PALETTE.inkDark, 0.7);
  for (let [cx, cy, sx, sy] of corners) {
    brush.line(cx, cy, cx + sx * 7, cy + sy * 7);
  }

  // Faint scholarly grid intersection hairlines (micro-crosses between specimens)
  let gxList = [438, 762];
  let gyList = [432, 748];
  brush.set("etch_needle", PALETTE.inkFaint, 0.5);
  for (let gx of gxList) {
    for (let gy of gyList) {
      brush.line(gx - 8, gy, gx + 8, gy);
      brush.line(gx, gy - 8, gx, gy + 8);
    }
  }

  // Subtle paper fiber grain & occasional antique foxing marks in outer margin
  brush.set("etch_needle", "#c8bfab", 0.45);
  for (let i = 0; i < 95; i++) {
    let fx = random(20, 1180);
    let fy = random(20, 1180);
    if (fx > 110 && fx < 1090 && fy > 115 && fy < 1080 && random() < 0.7) continue;
    let flen = random(3, 10);
    let fang = random(360);
    brush.line(fx, fy, fx + cos(fang) * flen, fy + sin(fang) * flen);
  }
}

// =============================================================================
// SPECIMEN 1: AMETHYST ROCK CANDY DRUSE ON TWINE (FIG. 1)
// =============================================================================

function drawSpecimen1_AmethystDruse(cx, cy) {
  // Helper to build a 3D monoclinic crystal prism projecting from (ox, oy)
  function makePrism(ox, oy, ang, len, w, zTilt) {
    let ca = cos(ang), sa = sin(ang);
    let na = -sa, nb = ca; // normal vector
    // Base points
    let bL = [ox + na * w * 0.5, oy + nb * w * 0.5];
    let bC = [ox + ca * w * 0.18 + na * w * 0.08, oy + sa * w * 0.18 + nb * w * 0.08];
    let bR = [ox - na * w * 0.5, oy - nb * w * 0.5];
    // Shoulder points
    let sL = [bL[0] + ca * len * 0.76, bL[1] + sa * len * 0.76];
    let sC = [bC[0] + ca * len * 0.82, bC[1] + sa * len * 0.82];
    let sR = [bR[0] + ca * len * 0.74, bR[1] + sa * len * 0.74];
    // Chisel termination apexes
    let tL = [ox + ca * len * 0.98 + na * w * 0.2, oy + sa * len * 0.98 + nb * w * 0.2];
    let tR = [ox + ca * len * 1.02 - na * w * 0.16, oy + sa * len * 1.02 - nb * w * 0.16];

    let faceLeft = [bL, sL, sC, bC];
    let faceRight = [bC, sC, sR, bR];
    let termLeft = [sL, tL, tR, sC];
    let termRight = [sC, tR, sR];

    return {
      ang, len, w, zTilt,
      facets: [
        { pts: faceLeft, nx: na * 0.7 + ca * -0.1, ny: nb * 0.7 + sa * -0.1, nz: 0.65 + zTilt, hAng: ang + 90 },
        { pts: faceRight, nx: -na * 0.75 + ca * -0.1, ny: -nb * 0.75 + sa * -0.1, nz: 0.55 - zTilt, hAng: ang + 90 },
        { pts: termLeft, nx: ca * 0.65 + na * 0.3, ny: sa * 0.65 + nb * 0.3, nz: 0.65, hAng: ang + 25 },
        { pts: termRight, nx: ca * 0.75 - na * 0.4, ny: sa * 0.75 - nb * 0.4, nz: 0.45, hAng: ang - 30 }
      ],
      outline: [bL, sL, tL, tR, sR, bR]
    };
  }

  // Overall shadow silhouette
  let silPts = [];
  for (let a = 0; a < 360; a += 20) {
    let r = 74 + 18 * cos(a * 3 + 20) + 10 * sin(a * 5);
    silPts.push([cx + cos(a) * r * 1.05, cy + sin(a) * r * 0.88]);
  }
  drawSpecimenShadow(silPts, 16, 20, PALETTE.amethyst.caustic, 72);

  // 1. Protruding fibrous cotton twine (top-left & bottom-right)
  function drawTwineSegment(x1, y1, x2, y2, frayedEnd) {
    let steps = 16;
    for (let s = -2; s <= 2; s++) {
      let pts = [];
      for (let i = 0; i <= steps; i++) {
        let t = i / steps;
        let px = lerp(x1, x2, t);
        let py = lerp(y1, y2, t);
        let wave = sin(t * 540 + s * 45) * 3.2;
        pts.push([px - wave * 0.6 + s * 0.9, py + wave * 0.8 + s * 0.7]);
      }
      brush.set("etch_needle", s < 0 ? "#8a7f6d" : PALETTE.inkDark, 0.75);
      brush.spline(pts, 0.5);
    }
    if (frayedEnd) {
      for (let f = 0; f < 9; f++) {
        let fa = atan2(y2 - y1, x2 - x1) + random(-42, 42);
        let fl = random(8, 22);
        brush.set("etch_needle", f % 2 === 0 ? PALETTE.inkMid : "#786e5c", 0.55);
        brush.line(x2, y2, x2 + cos(fa) * fl, y2 + sin(fa) * fl);
      }
    }
  }
  drawTwineSegment(cx - 50, cy - 38, cx - 102, cy - 78, true);
  drawTwineSegment(cx + 48, cy + 36, cx + 104, cy + 74, true);

  // 2. Define 13 interlocking monoclinic amethyst sugar prisms (sorted back to front)
  let prismSpecs = [
    // Back layer
    [-18, -12, 205, 86, 34, -0.25],
    [12, -16, 315, 88, 36, -0.2],
    [-25, 10, 145, 82, 34, -0.22],
    [22, 14, 25, 85, 36, -0.2],
    [0, -20, 260, 92, 40, -0.15],
    // Mid layer
    [-10, 15, 98, 86, 42, -0.05],
    [-32, -6, 175, 78, 38, 0.05],
    [26, -6, 348, 82, 40, 0.0],
    [15, 18, 58, 80, 38, -0.08],
    // Front central dominant crystals
    [-8, -6, 232, 76, 46, 0.22],
    [10, -8, 288, 78, 44, 0.18],
    [-6, 8, 122, 72, 44, 0.15],
    [12, 6, 12, 70, 42, 0.12]
  ];

  // Deep core amethyst wash
  fillPoly(silPts.map(p => [lerp(cx, p[0], 0.58), lerp(cy, p[1], 0.58)]), PALETTE.amethyst.deep, 95, 0.06, 0.5, 0.3);

  // Ghost of twine visible inside the crystal core
  brush.set("etch_needle", PALETTE.amethyst.deep, 1.1);
  brush.line(cx - 55, cy - 42, cx + 55, cy + 42);

  for (let idx = 0; idx < prismSpecs.length; idx++) {
    let [dx, dy, ang, len, w, zt] = prismSpecs[idx];
    let pr = makePrism(cx + dx, cy + dy, ang, len, w, zt);
    for (let f of pr.facets) {
      renderCrystalFacet(f.pts, f.nx, f.ny, f.nz, PALETTE.amethyst, f.hAng, idx > 8 ? 1.05 : 0.9);
    }

    // Internal phantom crystal growth chevrons & step striations
    let ca = cos(ang), sa = sin(ang);
    let na = -sa, nb = ca;
    brush.set("etch_needle", PALETTE.amethyst.deep, 0.55);
    for (let st = 0.35; st <= 0.68; st += 0.16) {
      let px = cx + dx + ca * len * st;
      let py = cy + dy + sa * len * st;
      brush.line(px + na * w * 0.35, py + nb * w * 0.35, px + ca * 9, py + sa * 9);
      brush.line(px + ca * 9, py + sa * 9, px - na * w * 0.35, py - nb * w * 0.35);
    }
  }

  // Internal tiny vesicles in main crystals
  drawVesicle(cx - 22, cy - 28, 3.2, PALETTE.amethyst.light);
  drawVesicle(cx + 18, cy - 32, 2.5, PALETTE.amethyst.light);
  drawVesicle(cx + 28, cy + 12, 3.8, PALETTE.amethyst.light);

  // Loose detached amethyst sugar crystals on paper
  drawLooseSugarCrystals(cx, cy, 11, 88, 76, PALETTE.amethyst);
}

// =============================================================================
// SPECIMEN 2: GARNET ACIDULATED DROP WITH CONCHOIDAL FRACTURE (FIG. 2)
// =============================================================================

function drawSpecimen2_GarnetAcidDrop(cx, cy) {
  let rx = 88, ry = 78;
  // Build lozenge contour with a jagged conchoidal fracture bite on the right (-38° to +52°)
  let bodyPts = [];
  let fracInnerPts = [];
  for (let a = 52; a <= 322; a += 8) {
    bodyPts.push([cx + cos(a) * rx, cy + sin(a) * ry]);
  }
  // Scalloped conchoidal fracture edge from 322° (-38°) to +52°
  for (let a = -38; a <= 52; a += 6) {
    let indent = 24 * sin(map(a, -38, 52, 0, 180)) + 4 * cos(a * 6);
    let p = [cx + cos(a) * (rx - indent), cy + sin(a) * (ry - indent * 0.85)];
    bodyPts.push(p);
    fracInnerPts.push(p);
  }

  // Detached crescent shard resting to the lower-right
  let sx = cx + 92, sy = cy + 38;
  let shardPts = [
    [sx - 12, sy - 24],
    [sx + 14, sy - 16],
    [sx + 22, sy + 8],
    [sx + 6, sy + 26],
    [sx - 14, sy + 14],
    [sx - 6, sy - 4]
  ];

  // 1. Cast shadows with fiery Garnet caustic core!
  drawSpecimenShadow(bodyPts, 16, 20, PALETTE.garnet.caustic, 85);
  drawSpecimenShadow(shardPts, 9, 12, PALETTE.garnet.caustic, 65);

  // 2. Hand-tinted Garnet washes on main lozenge
  fillPoly(bodyPts, PALETTE.garnet.light, 78, 0.04, 0.45, 0.35);

  // Thick torus rim wash (darker on bottom-right, luminous on top-left)
  let rimShadowPts = [];
  for (let a = 35; a <= 175; a += 10) rimShadowPts.push([cx + cos(a) * rx * 0.96, cy + sin(a) * ry * 0.96]);
  for (let a = 175; a >= 35; a -= 10) rimShadowPts.push([cx + cos(a) * rx * 0.56, cy + sin(a) * ry * 0.56]);
  fillPoly(rimShadowPts, PALETTE.garnet.deep, 98, 0.05, 0.5, 0.4);

  // Central biconcave depression (inverted lighting: upper-left of well is in shadow, lower-right catches refracted glow!)
  let wellPts = [];
  let wellShadowPts = [];
  let wellGlowPts = [];
  for (let a = 0; a < 360; a += 12) {
    wellPts.push([cx - 6 + cos(a) * rx * 0.52, cy - 2 + sin(a) * ry * 0.52]);
  }
  for (let a = 135; a <= 315; a += 12) {
    wellShadowPts.push([cx - 6 + cos(a) * rx * 0.52, cy - 2 + sin(a) * ry * 0.52]);
  }
  for (let a = 315; a >= 135; a -= 15) {
    wellShadowPts.push([cx - 6 + cos(a) * rx * 0.18, cy - 2 + sin(a) * ry * 0.18]);
  }
  for (let a = -45; a <= 135; a += 12) {
    wellGlowPts.push([cx - 6 + cos(a) * rx * 0.48, cy - 2 + sin(a) * ry * 0.48]);
  }
  fillPoly(wellPts, PALETTE.garnet.mid, 72, 0.04, 0.45, 0.3);
  fillPoly(wellShadowPts, PALETTE.garnet.deep, 110, 0.04, 0.5, 0.4);
  fillPoly(wellGlowPts, PALETTE.garnet.pale, 65, 0.04, 0.35, 0.25);

  // 3. Conchoidal fracture face on right side of lozenge (thickness of sugar wall)
  let fracOuterPts = [];
  for (let i = fracInnerPts.length - 1; i >= 0; i--) {
    let p = fracInnerPts[i];
    fracOuterPts.push([p[0] + 15, p[1] + 9]);
  }
  let fracFacePts = fracInnerPts.concat(fracOuterPts);
  fillPoly(fracFacePts, PALETTE.garnet.mid, 95, 0.03, 0.4, 0.35);

  // Concentric Wallner lines (conchoidal fracture ripples) on the broken glass wall
  brush.set("etch_needle", PALETTE.inkDeep, 0.68);
  for (let rStep = 0.15; rStep <= 0.92; rStep += 0.14) {
    let wPts = [];
    for (let i = 0; i < fracInnerPts.length; i++) {
      let pIn = fracInnerPts[i];
      let pOut = fracOuterPts[fracOuterPts.length - 1 - i];
      let bow = sin((i / fracInnerPts.length) * 180) * 3.5;
      wPts.push([
        lerp(pIn[0], pOut[0], rStep) + bow,
        lerp(pIn[1], pOut[1], rStep)
      ]);
    }
    brush.spline(wPts, 0.5);
  }
  // Radial hackle ticks along fracture edge
  for (let i = 0; i < fracInnerPts.length; i += 1) {
    let pIn = fracInnerPts[i];
    let pOut = fracOuterPts[fracOuterPts.length - 1 - i];
    brush.set("etch_needle", PALETTE.inkDark, 0.6);
    brush.line(pIn[0], pIn[1], lerp(pIn[0], pOut[0], 0.45), lerp(pIn[1], pOut[1], 0.45));
  }

  // 4. Curved meridian & latitude copperplate engraving modeling the torus & concave dimple
  // Latitude rings on shadow side of rim
  for (let rFrac = 0.56; rFrac <= 0.97; rFrac += 0.045) {
    let pts = [];
    let startA = map(rFrac, 0.56, 0.97, 45, 10);
    let endA = map(rFrac, 0.56, 0.97, 170, 200);
    for (let a = startA; a <= endA; a += 7) {
      pts.push([cx + cos(a) * rx * rFrac, cy + sin(a) * ry * rFrac]);
    }
    brush.set("engraver", PALETTE.inkDark, map(rFrac, 0.56, 0.97, 0.65, 0.95));
    brush.spline(pts, 0.5);
  }
  // Cross-hatching meridian curves around the torus rim
  for (let a = 30; a < 320; a += 6.5) {
    let rad = a;
    let lightFactor = cos(rad - 225); // 1 at top-left, -1 at bottom-right
    if (lightFactor > 0.68 && a % 13 < 6.5) continue; // Leave specular gap on top-left
    let rIn = 0.54;
    let rOut = 0.98;
    let mPts = [];
    for (let t = 0; t <= 1; t += 0.25) {
      let rCur = lerp(rIn, rOut, t);
      let curveShift = sin(t * 180) * 6;
      mPts.push([
        cx + cos(a + curveShift) * rx * rCur,
        cy + sin(a + curveShift) * ry * rCur
      ]);
    }
    brush.set(lightFactor > 0.2 ? "etch_needle" : "engraver",
              lightFactor > 0.2 ? PALETTE.inkMid : PALETTE.inkDeep,
              map(lightFactor, -1, 1, 0.9, 0.5));
    brush.spline(mPts, 0.5);
  }

  // Curved bowl hatching inside the central concavity
  for (let yOff = -36; yOff <= 36; yOff += 3.8) {
    let halfW = sqrt(max(0, sq(rx * 0.5) - sq(yOff * 1.12)));
    if (halfW < 6) continue;
    let bPts = [];
    for (let xStep = -halfW; xStep <= halfW; xStep += 6) {
      let dip = (1 - sq(xStep / halfW)) * 7;
      bPts.push([cx - 6 + xStep, cy - 2 + yOff + dip]);
    }
    let isShadowWell = yOff < 6;
    brush.set(isShadowWell ? "engraver" : "etch_needle",
              isShadowWell ? PALETTE.inkDeep : PALETTE.inkMid,
              isShadowWell ? 0.8 : 0.55);
    brush.spline(bPts, 0.5);
  }

  // 5. Internal trapped air bubbles (vesicles) suspended in the garnet glass!
  let bubbles = [
    [-28, -46, 5.5, 1.2, -20], [-14, -52, 3.0, 1.0, 0], [-42, -32, 2.4, 1.0, 0],
    [16, -42, 4.2, 1.3, 25], [26, -28, 2.8, 1.1, 40], [8, -12, 6.2, 1.15, -15],
    [-22, 8, 4.8, 1.0, 10], [-48, 18, 3.6, 1.25, 65], [-32, 38, 5.0, 1.1, 30],
    [6, 36, 3.2, 1.0, 0], [22, 22, 4.5, 1.2, -40], [-8, -28, 2.2, 1.0, 0],
    [32, -6, 3.5, 1.3, 80], [-56, -8, 4.0, 1.1, 75]
  ];
  for (let [bx, by, br, bst, brot] of bubbles) {
    drawVesicle(cx + bx, cy + by, br, PALETTE.garnet.pale, bst, brot);
  }

  // 6. Render the detached garnet shard
  fillPoly(shardPts, PALETTE.garnet.mid, 90, 0.03, 0.4, 0.35);
  hatchPoly(shardPts, 35, 2.8, PALETTE.inkDeep, 0.75, 70, 3.8);
  strokeFacet(shardPts, 0.85, true);
  drawVesicle(sx + 2, sy + 2, 2.8, PALETTE.garnet.pale);

  // 7. Outer contour, sugar dusting, and razor-sharp glassy highlights
  strokeFacet(bodyPts, 0.9, false);
  strokeFacet(fracFacePts, 0.95, true);

  // Sharp white gouache highlight along the conchoidal fracture ridge
  brush.set("gouache_white", PALETTE.white, 1.25);
  brush.spline(fracInnerPts, 0.4);

  // Studio skylight window reflection on upper-left rim + inner well rim highlight
  drawGlossyWindowHighlight(cx, cy, rx * 0.82, ry * 0.82, 200, 248, 7.5);
  drawGlossyWindowHighlight(cx - 6, cy - 2, rx * 0.44, ry * 0.44, 25, 72, 4.2);

  // Fine dusted icing/crystal sugar along left edge & on paper
  brush.set("sugar_stipple", PALETTE.white, 1.1);
  brush.arc(cx, cy, rx * 0.92, 145, 225);
  drawLooseSugarCrystals(cx, cy, 9, 98, 82, PALETTE.garnet);
}

// =============================================================================
// SPECIMEN 3: BERYL MINT HUMBUG — STRIATED CUSHION CRYSTAL (FIG. 3)
// =============================================================================

function drawSpecimen3_BerylHumbug(cx, cy) {
  let tilt = -14;
  let hw = 86, hh = 64;

  function rotPt(x, y) {
    return [
      cx + x * cos(tilt) - y * sin(tilt),
      cy + x * sin(tilt) + y * cos(tilt)
    ];
  }

  // Build pinched pillow/cushion contour
  let cushionPts = [];
  let steps = 40;
  for (let i = 0; i < steps; i++) {
    let a = (i / steps) * 360;
    let ca = cos(a), sa = sin(a);
    // Superellipse with pinched folded ends at left/right
    let rPinch = 1 + 0.08 * cos(a * 2) - 0.06 * cos(a * 4);
    let x = hw * signPow(ca, 0.72) * rPinch;
    let y = hh * signPow(sa, 0.82) * (1 - 0.14 * pow(ca, 4));
    cushionPts.push(rotPt(x, y));
  }

  // 1. Cast shadow with cool Beryl-Emerald caustic
  drawSpecimenShadow(cushionPts, 16, 20, PALETTE.beryl.caustic, 80);

  // 2. Construct 7 longitudinal curved humbug stripes converging toward pinched ends
  let stripeBounds = [-1.0, -0.68, -0.36, -0.05, 0.28, 0.58, 0.84, 1.0];
  function getStripeCurve(vFrac, nPts = 24) {
    let pts = [];
    for (let i = 0; i <= nPts; i++) {
      let u = map(i, 0, nPts, -1, 1); // left to right
      let x = u * hw;
      // Stripes pinch together at the twisted ends (u = -1 and u = 1)
      let envelope = sqrt(max(0, 1 - u * u * 0.82));
      let arch3D = (1 - u * u) * 10 * (1 - vFrac * vFrac * 0.5); // 3D dome bulge
      let y = vFrac * hh * envelope - arch3D * 0.45;
      pts.push(rotPt(x, y));
    }
    return pts;
  }

  for (let s = 0; s < stripeBounds.length - 1; s++) {
    let v1 = stripeBounds[s];
    let v2 = stripeBounds[s + 1];
    let topEdge = getStripeCurve(v1, 20);
    let botEdge = getStripeCurve(v2, 20).reverse();
    let polyPts = topEdge.concat(botEdge);
    let isBeryl = s % 2 === 0;
    let vMid = (v1 + v2) * 0.5;

    if (isBeryl) {
      // Translucent Beryl Green vitreous band
      let col = vMid < -0.2 ? PALETTE.beryl.light : (vMid < 0.35 ? PALETTE.beryl.mid : PALETTE.beryl.deep);
      fillPoly(polyPts, col, vMid > 0.3 ? 110 : 88, 0.03, 0.45, 0.35);

      // Transverse crystal cross-hatching on dark green bands
      let hDensity = map(vMid, -0.8, 0.8, 4.5, 2.3);
      hatchPoly(polyPts, tilt + 72, hDensity, PALETTE.inkDeep, 0.72,
                vMid > 0 ? tilt - 65 : null, 3.2);
    } else {
      // Pulled satin-sugar band (silky cool celadon-silver sheen)
      fillPoly(polyPts, PALETTE.beryl.pale, 52, 0.03, 0.3, 0.2);
      if (vMid > 0.2) {
        fillPoly(polyPts, PALETTE.shadowWash, 48, 0.03, 0.35, 0.25);
      }
    }

    // 3. Longitudinal microscopic air-tubule striations (chatoyant pulled sugar texture)
    let subLines = isBeryl ? 5 : 9;
    for (let k = 1; k < subLines; k++) {
      let vf = lerp(v1, v2, k / subLines);
      let curve = getStripeCurve(vf, 24);
      brush.set("etch_needle", isBeryl ? PALETTE.inkDeep : PALETTE.inkMid, isBeryl ? 0.6 : 0.52);
      brush.spline(curve, 0.5);
    }

    // Crisp stripe boundary line
    if (s > 0) {
      brush.set("engraver", PALETTE.inkDeep, 0.78);
      brush.spline(topEdge, 0.5);
    }
  }

  // 4. Pinched seam folds at left and right ends + small chipped corner facet on right
  for (let side of [-1, 1]) {
    for (let f = -3; f <= 3; f++) {
      let foldPts = [
        rotPt(side * hw * 0.98, f * 4),
        rotPt(side * hw * 0.78, f * 9),
        rotPt(side * hw * 0.62, f * 12)
      ];
      brush.set("engraver", PALETTE.inkDeep, 0.82);
      brush.spline(foldPts, 0.4);
    }
  }

  // Small chipped cleavage facet on lower-right corner showing internal stripe cross-section
  let chipPts = [
    rotPt(hw * 0.62, hh * 0.52),
    rotPt(hw * 0.92, hh * 0.22),
    rotPt(hw * 0.88, hh * 0.62),
    rotPt(hw * 0.68, hh * 0.74)
  ];
  fillPoly(chipPts, PALETTE.beryl.mid, 95, 0.02, 0.35, 0.3);
  hatchPoly(chipPts, tilt + 25, 2.5, PALETTE.inkDeep, 0.75);
  strokeFacet(chipPts, 0.9, true);

  // 5. Outer contour & chatoyant cat's-eye diagonal highlight band across the cushion!
  strokeFacet(cushionPts, 0.92, false);

  // Silky chatoyant sheen (bright gouache streaks running along the stripes in the upper-left light zone)
  for (let s = 0; s < stripeBounds.length - 1; s++) {
    let v1 = stripeBounds[s];
    let v2 = stripeBounds[s + 1];
    let isBeryl = s % 2 === 0;
    let streakCount = isBeryl ? 2 : 5;
    for (let k = 1; k <= streakCount; k++) {
      let vf = lerp(v1, v2, k / (streakCount + 1));
      if (vf > 0.45) continue;
      let pts = [];
      let uCenter = -0.28 - vf * 0.22;
      let uSpan = isBeryl ? 0.18 : 0.28;
      for (let u = uCenter - uSpan; u <= uCenter + uSpan; u += 0.06) {
        let envelope = sqrt(max(0, 1 - u * u * 0.82));
        let arch3D = (1 - u * u) * 10 * (1 - vf * vf * 0.5);
        let y = vf * hh * envelope - arch3D * 0.45;
        pts.push(rotPt(u * hw, y));
      }
      brush.set("gouache_white", PALETTE.white, isBeryl ? 1.25 : 0.95);
      brush.spline(pts, 0.5);
    }
  }

  drawLooseSugarCrystals(cx, cy, 8, 92, 74, PALETTE.beryl);
}

// =============================================================================
// SPECIMEN 4: CITRINE LEMON SHERBET PRISM WITH VESICLES (FIG. 4)
// =============================================================================

function drawSpecimen4_CitrinePrism(cx, cy) {
  let tilt = 22;
  let L = 92, W = 48;

  function rPt(x, y) {
    return [
      cx + x * cos(tilt) - y * sin(tilt),
      cy + x * sin(tilt) + y * cos(tilt)
    ];
  }

  // Octagonal prismatic tablet vertices: outer girdle (8 pts) and upper table (8 pts)
  let girdle = [
    rPt(-L, -W * 0.48),
    rPt(-L * 0.68, -W),
    rPt(L * 0.68, -W),
    rPt(L, -W * 0.48),
    rPt(L, W * 0.48),
    rPt(L * 0.68, W),
    rPt(-L * 0.68, W),
    rPt(-L, W * 0.48)
  ];

  // Slightly offset upper table to show 3D thickness & perspective
  let tShiftX = -4, tShiftY = -6;
  let tScaleX = 0.72, tScaleY = 0.62;
  let table = [
    rPt(-L * tScaleX + tShiftX, -W * 0.48 * tScaleY + tShiftY),
    rPt(-L * 0.68 * tScaleX + tShiftX, -W * tScaleY + tShiftY),
    rPt(L * 0.68 * tScaleX + tShiftX, -W * tScaleY + tShiftY),
    rPt(L * tScaleX + tShiftX, -W * 0.48 * tScaleY + tShiftY),
    rPt(L * tScaleX + tShiftX, W * 0.48 * tScaleY + tShiftY),
    rPt(L * 0.68 * tScaleX + tShiftX, W * tScaleY + tShiftY),
    rPt(-L * 0.68 * tScaleX + tShiftX, W * tScaleY + tShiftY),
    rPt(-L * tScaleX + tShiftX, W * 0.48 * tScaleY + tShiftY)
  ];

  // 1. Cast shadow with luminous Sulfur-Citrine caustic
  drawSpecimenShadow(girdle, 15, 20, PALETTE.citrine.caustic, 82);

  // 2. Internal pavilion facets visible through the transparent citrine tablet!
  let culetL = rPt(-L * 0.42 + 5, 6);
  let culetR = rPt(L * 0.42 + 5, 6);
  brush.set("etch_needle", PALETTE.citrine.deep, 0.65);
  brush.line(culetL[0], culetL[1], culetR[0], culetR[1]);
  for (let i = 0; i < 8; i++) {
    let target = (i === 0 || i === 1 || i === 6 || i === 7) ? culetL : culetR;
    brush.line(girdle[i][0], girdle[i][1], target[0], target[1]);
  }

  // 3. Render the 8 crown bevel facets + central table facet
  let normals = [
    [-0.85, -0.45, 0.35],
    [-0.15, -0.9, 0.4],
    [0.65, -0.65, 0.35],
    [0.9, -0.1, 0.3],
    [0.85, 0.45, 0.25],
    [0.15, 0.9, 0.25],
    [-0.65, 0.65, 0.3],
    [-0.9, 0.1, 0.35]
  ];
  let hatchAngles = [tilt + 90, tilt, tilt - 45, tilt + 90, tilt + 45, tilt, tilt - 45, tilt + 90];

  for (let i = 0; i < 8; i++) {
    let ni = (i + 1) % 8;
    let bevelPts = [girdle[i], girdle[ni], table[ni], table[i]];
    let [nx, ny, nz] = normals[i];
    renderCrystalFacet(bevelPts, nx, ny, nz, PALETTE.citrine, hatchAngles[i], 0.95);
  }

  // Central flat table facet
  renderCrystalFacet(table, -0.18, -0.22, 0.95, PALETTE.citrine, tilt + 18, 0.85);

  // 4. Internal effervescent sherbet powder inclusion & rising bubble stream!
  // Frosted sherbet core pocket inside the left half of the crystal
  let sherbetCore = [
    rPt(-L * 0.55, -W * 0.22),
    rPt(-L * 0.12, -W * 0.32),
    rPt(L * 0.05, W * 0.08),
    rPt(-L * 0.22, W * 0.34),
    rPt(-L * 0.58, W * 0.18)
  ];
  fillPoly(sherbetCore, PALETTE.creamWhite, 95, 0.08, 0.65, 0.4, "out");
  brush.set("sugar_stipple", PALETTE.white, 1.3);
  brush.line(sherbetCore[0][0], sherbetCore[0][1], sherbetCore[2][0], sherbetCore[2][1]);

  // Rising stream of effervescent vesicles frozen in the citrine glass
  let sherbetBubbles = [
    [-38, -8, 4.8], [-26, -14, 3.5], [-15, -4, 5.6], [-4, -18, 4.0],
    [8, -8, 6.2], [18, -22, 3.2], [24, 4, 4.5], [36, -12, 5.2],
    [46, 2, 3.8], [54, -8, 2.6], [-32, 14, 3.4], [12, 16, 3.0],
    [32, 18, 2.5], [-48, 4, 2.8], [62, 6, 2.2]
  ];
  for (let [bx, by, br] of sherbetBubbles) {
    let p = rPt(bx, by);
    drawVesicle(p[0], p[1], br, PALETTE.citrine.pale, 1.05, tilt - 25);
  }

  // Re-stroke table edges crisply over internal inclusions
  strokeFacet(table, 0.9, true);

  // 5. Scholarly crystallographic angle leader lines (a, b, c) at top-left!
  brush.set("etch_needle", PALETTE.inkMid, 0.6);
  let vA = girdle[0], vB = girdle[1], vC = table[1];
  drawDottedLine(vA[0], vA[1], vA[0] - 28, vA[1] - 16, 2.5);
  drawDottedLine(vB[0], vB[1], vB[0] - 12, vB[1] - 30, 2.5);
  drawDottedLine(vC[0], vC[1], vC[0] + 8, vC[1] - 32, 2.5);
  drawEngravedText("A", vA[0] - 35, vA[1] - 22, 7.5, 5, true, "center", PALETTE.inkMid);
  drawEngravedText("B", vB[0] - 15, vB[1] - 40, 7.5, 5, true, "center", PALETTE.inkMid);
  drawEngravedText("C", vC[0] + 10, vC[1] - 42, 7.5, 5, true, "center", PALETTE.inkMid);

  drawLooseSugarCrystals(cx, cy, 10, 95, 72, PALETTE.citrine);
}

// =============================================================================
// SPECIMEN 5: GRAND GEODE OF KANDIS — AQUAMARINE & BERYL ROSETTE (FIG. 5)
// =============================================================================

function drawSpecimen5_KandisGeode(cx, cy) {
  // Centerpiece rosette of large orthorhombic hopper-crystal prisms
  let silPts = [];
  for (let a = 0; a < 360; a += 15) {
    let r = 84 + 22 * cos(a * 4 - 15) + 12 * sin(a * 3);
    silPts.push([cx + cos(a) * r * 1.05, cy + sin(a) * r * 0.92]);
  }
  drawSpecimenShadow(silPts, 18, 22, PALETTE.aqua.caustic, 85);

  // Embedded wooden crystallizing skewer tip at bottom-left
  let stickPts = [
    [cx - 52, cy + 38],
    [cx - 98, cy + 74],
    [cx - 90, cy + 84],
    [cx - 44, cy + 48]
  ];
  fillPoly(stickPts, "#9c8867", 85, 0.02, 0.4, 0.3);
  hatchPoly(stickPts, -38, 2.2, PALETTE.inkDark, 0.72);
  strokeFacet(stickPts, 0.8, false);

  // Deep central geode core wash (amethyst-beryl transition)
  fillPoly(silPts.map(p => [lerp(cx, p[0], 0.52), lerp(cy, p[1], 0.52)]), PALETTE.beryl.deep, 105, 0.06, 0.5, 0.35);

  // Helper to draw an orthorhombic crystal with stepped "hopper" cavity on its main face
  function drawHopperCrystal(ox, oy, ang, len, w, palObj, zBoost = 0, hasHopper = true) {
    let ca = cos(ang), sa = sin(ang);
    let na = -sa, nb = ca;

    let bL = [ox + na * w * 0.5, oy + nb * w * 0.5];
    let bR = [ox - na * w * 0.5, oy - nb * w * 0.5];
    let sL = [bL[0] + ca * len * 0.78, bL[1] + sa * len * 0.78];
    let sR = [bR[0] + ca * len * 0.78, bR[1] + sa * len * 0.78];
    let tip = [ox + ca * len, oy + sa * len];

    // Inner table for main face + bevel sides
    let inB_L = [ox + ca * len * 0.1 + na * w * 0.3, oy + sa * len * 0.1 + nb * w * 0.3];
    let inB_R = [ox + ca * len * 0.1 - na * w * 0.3, oy + sa * len * 0.1 - nb * w * 0.3];
    let inS_L = [ox + ca * len * 0.72 + na * w * 0.3, oy + sa * len * 0.72 + nb * w * 0.3];
    let inS_R = [ox + ca * len * 0.72 - na * w * 0.3, oy + sa * len * 0.72 - nb * w * 0.3];
    let inTip = [ox + ca * len * 0.86, oy + sa * len * 0.86];

    let bevelLeft = [bL, sL, inS_L, inB_L];
    let bevelRight = [bR, inB_R, inS_R, sR];
    let termLeft = [sL, tip, inTip, inS_L];
    let termRight = [sR, inS_R, inTip, tip];
    let mainTable = [inB_L, inS_L, inTip, inS_R, inB_R];

    renderCrystalFacet(bevelLeft, na * 0.8, nb * 0.8, 0.4 + zBoost, palObj, ang + 90);
    renderCrystalFacet(bevelRight, -na * 0.8, -nb * 0.8, 0.4 + zBoost, palObj, ang + 90);
    renderCrystalFacet(termLeft, ca * 0.7 + na * 0.4, sa * 0.7 + nb * 0.4, 0.5 + zBoost, palObj, ang + 35);
    renderCrystalFacet(termRight, ca * 0.7 - na * 0.4, sa * 0.7 - nb * 0.4, 0.4 + zBoost, palObj, ang - 35);
    renderCrystalFacet(mainTable, ca * 0.15, sa * 0.15, 0.88 + zBoost, palObj, ang);

    // Hopper crystal stepped concentric depressions inside mainTable!
    if (hasHopper) {
      let cxTable = ox + ca * len * 0.45;
      let cyTable = oy + sa * len * 0.45;
      for (let step = 1; step <= 3; step++) {
        let sc = 1 - step * 0.24;
        let stepPts = mainTable.map(p => [
          lerp(cxTable, p[0], sc),
          lerp(cyTable, p[1], sc)
        ]);
        if (step === 2) {
          fillPoly(stepPts, palObj.mid, 65, 0.02, 0.3, 0.25);
        }
        strokeFacet(stepPts, 0.65, true);
      }
    }
  }

  // Outer ring of 8 large crystals
  let outerCrystals = [
    [-12, -10, 212, 98, 42, PALETTE.aqua, -0.1, true],
    [10, -14, 262, 95, 40, PALETTE.beryl, -0.08, true],
    [16, -8, 318, 96, 42, PALETTE.aqua, -0.12, true],
    [20, 8, 12, 92, 38, PALETTE.beryl, -0.1, true],
    [12, 16, 62, 90, 40, PALETTE.aqua, -0.15, true],
    [-10, 14, 118, 88, 38, PALETTE.aqua, -0.12, false],
    [-20, 4, 168, 92, 40, PALETTE.beryl, -0.05, true]
  ];
  for (let c of outerCrystals) {
    drawHopperCrystal(cx + c[0], cy + c[1], c[2], c[3], c[4], c[5], c[6], c[7]);
  }

  // Inner crown of 5 dominant high-relief crystals
  let innerCrystals = [
    [-8, -6, 238, 76, 44, PALETTE.aqua, 0.18, true],
    [10, -6, 294, 78, 42, PALETTE.beryl, 0.15, true],
    [12, 8, 38, 72, 40, PALETTE.aqua, 0.12, true],
    [-8, 8, 142, 70, 38, PALETTE.amethyst, 0.14, false],
    [0, -2, 345, 58, 36, PALETTE.aqua, 0.25, true]
  ];
  for (let c of innerCrystals) {
    drawHopperCrystal(cx + c[0], cy + c[1], c[2], c[3], c[4], c[5], c[6], c[7]);
  }

  // Internal vesicles & loose crystals
  drawVesicle(cx - 24, cy - 34, 4.0, PALETTE.aqua.pale);
  drawVesicle(cx + 28, cy - 22, 3.4, PALETTE.beryl.pale);
  drawVesicle(cx + 16, cy + 28, 3.8, PALETTE.aqua.pale);
  drawLooseSugarCrystals(cx, cy, 14, 98, 86, PALETTE.aqua);
}

// =============================================================================
// SPECIMEN 6: CONCHOIDAL BARLEY SUGAR TWIST — HELICOIDAL ROD (FIG. 6)
// =============================================================================

function drawSpecimen6_BarleyTwist(cx, cy) {
  let tilt = -34;
  let rodLen = 192;
  let rodR = 30;
  let numLobes = 5;

  function rPt(x, y) {
    return [
      cx + x * cos(tilt) - y * sin(tilt),
      cy + x * sin(tilt) + y * cos(tilt)
    ];
  }

  // Build overall scalloped silhouette for shadow
  let silTop = [], silBot = [];
  for (let i = 0; i <= 40; i++) {
    let t = i / 40;
    let x = lerp(-rodLen * 0.5, rodLen * 0.5, t);
    let pinch = abs(sin(t * numLobes * 180));
    let rCur = rodR * (0.76 + 0.28 * pinch);
    silTop.push(rPt(x, -rCur));
    silBot.unshift(rPt(x, rCur));
  }
  let rodSil = silTop.concat(silBot);

  // Detached broken ring-fragment beside lower-right end
  let fx = cx + 62, fy = cy + 68;
  let fragPts = [];
  for (let a = 0; a < 360; a += 30) {
    let rad = 18 + 4 * cos(a * 2);
    fragPts.push([fx + cos(a) * rad * 1.15, fy + sin(a) * rad * 0.78]);
  }

  // 1. Cast shadows with golden-citrine ribbon caustics!
  drawSpecimenShadow(rodSil, 16, 20, PALETTE.citrine.caustic, 82);
  drawSpecimenShadow(fragPts, 10, 13, PALETTE.citrine.caustic, 68);

  // 2. Render each helicoidal spiral lobe along the rod
  let lobeLen = rodLen / numLobes;
  for (let k = 0; k < numLobes; k++) {
    let xStart = -rodLen * 0.5 + k * lobeLen;
    let xEnd = xStart + lobeLen;

    // Construct S-curved helicoidal lobe polygon
    let lobeTop = [], lobeBot = [];
    let steps = 16;
    for (let i = 0; i <= steps; i++) {
      let u = i / steps;
      let x = lerp(xStart, xEnd, u);
      let swell = sin(u * 180);
      let yTop = -rodR * (0.74 + 0.28 * swell);
      let yBot = rodR * (0.74 + 0.28 * swell);
      lobeTop.push(rPt(x, yTop));
      lobeBot.unshift(rPt(x + lobeLen * 0.18 * sin(u * 180), yBot));
    }
    let lobePts = lobeTop.concat(lobeBot);

    // Base citrine wash + cool smoky amethyst-slate trough shadow
    fillPoly(lobePts, PALETTE.citrine.light, 82, 0.03, 0.45, 0.35);

    // Shadow half of the cylindrical lobe
    let shadowHalf = [];
    for (let i = 0; i <= steps; i++) {
      let u = i / steps;
      let x = lerp(xStart, xEnd, u);
      let swell = sin(u * 180);
      shadowHalf.push(rPt(x + lobeLen * 0.08 * swell, -rodR * 0.05));
    }
    shadowHalf = shadowHalf.concat(lobeBot);
    fillPoly(shadowHalf, PALETTE.citrine.deep, 95, 0.04, 0.5, 0.4);
    fillPoly(shadowHalf, PALETTE.amethyst.mid, 45, 0.04, 0.4, 0.3);

    // Internal back-side refraction band seen through the glass rod!
    let refPts = [];
    for (let i = 0; i <= steps; i++) {
      let u = i / steps;
      let x = lerp(xStart, xEnd, u);
      let y = map(u, 0, 1, rodR * 0.55, -rodR * 0.55);
      refPts.push(rPt(x, y));
    }
    brush.set("etch_needle", PALETTE.citrine.deep, 0.85);
    brush.spline(refPts, 0.5);

    // Curved helicoidal engraving lines modeling the spiral torsion
    for (let v = -0.88; v <= 0.88; v += 0.13) {
      if (v > -0.58 && v < -0.18) continue; // Leave specular highlight channel!
      let hPts = [];
      for (let i = 0; i <= 12; i++) {
        let u = i / 12;
        let x = lerp(xStart, xEnd, u);
        let swell = sin(u * 180);
        let y = v * rodR * (0.74 + 0.28 * swell) + sin(u * 180 - 40) * 6.5;
        hPts.push(rPt(x, y));
      }
      let isDark = v > 0.05;
      brush.set(isDark ? "engraver" : "etch_needle",
                isDark ? PALETTE.inkDeep : PALETTE.inkMid,
                map(v, -0.9, 0.9, 0.55, 0.92));
      brush.spline(hPts, 0.5);
    }

    // Deep spiral groove seam between lobes
    if (k > 0) {
      let seamPts = [];
      for (let s = -1; s <= 1; s += 0.2) {
        seamPts.push(rPt(xStart + s * 9, s * rodR * 0.78));
      }
      brush.set("engraver", PALETTE.inkDeep, 1.05);
      brush.spline(seamPts, 0.5);
    }

    // Outer lobe contour
    strokeFacet(lobePts, 0.85, false);

    // Brilliant spiral ribbon highlight along the upper-left crest of each lobe!
    for (let hOff = -0.48; hOff <= -0.26; hOff += 0.07) {
      let hiPts = [];
      for (let i = 2; i <= 14; i++) {
        let u = i / 16;
        let x = lerp(xStart, xEnd, u);
        let swell = sin(u * 180);
        let y = hOff * rodR * (0.74 + 0.28 * swell) + sin(u * 180 - 40) * 5;
        hiPts.push(rPt(x, y));
      }
      brush.set("gouache_white", PALETTE.white, hOff === -0.34 ? 1.35 : 0.85);
      brush.spline(hiPts, 0.5);
    }

    // Internal stretched air bubbles following the spiral twist
    let bPt = rPt(lerp(xStart, xEnd, 0.52), (k % 2 === 0 ? -4 : 6));
    drawVesicle(bPt[0], bPt[1], 3.2, PALETTE.citrine.pale, 1.85, tilt + 28);
  }

  // 3. Conchoidal snapped fracture planes at both ends of the rod
  for (let endSign of [-1, 1]) {
    let ex = endSign * rodLen * 0.5;
    let endPts = [];
    for (let a = 0; a < 360; a += 20) {
      endPts.push(rPt(ex + cos(a) * 9, sin(a) * rodR * 0.76));
    }
    fillPoly(endPts, endSign < 0 ? PALETTE.citrine.pale : PALETTE.citrine.mid, 92, 0.02, 0.35, 0.3);
    // Concentric conchoidal fracture rings on snapped end
    brush.set("etch_needle", PALETTE.inkDeep, 0.65);
    for (let rFrac = 0.3; rFrac <= 0.85; rFrac += 0.25) {
      let ring = [];
      for (let a = 0; a <= 360; a += 30) {
        ring.push(rPt(ex + cos(a) * 9 * rFrac, sin(a) * rodR * 0.76 * rFrac));
      }
      brush.spline(ring, 0.5);
    }
    strokeFacet(endPts, 0.9, true);
  }

  // 4. Render the detached broken barley-sugar ring fragment
  fillPoly(fragPts, PALETTE.citrine.mid, 88, 0.03, 0.4, 0.35);
  hatchPoly(fragPts, tilt + 45, 2.6, PALETTE.inkDeep, 0.75, tilt + 80, 3.6);
  strokeFacet(fragPts, 0.85, true);

  drawLooseSugarCrystals(cx, cy, 8, 96, 80, PALETTE.citrine);
}

// =============================================================================
// SPECIMEN 7: DICHROIC TOURMALINE PEAR DROP (FIG. 7)
// =============================================================================

function drawSpecimen7_TourmalinePearDrop(cx, cy) {
  let tilt = -32;
  let len = 94;

  function rPt(u, v) {
    return [
      cx + u * cos(tilt) - v * sin(tilt),
      cy + u * sin(tilt) + v * cos(tilt)
    ];
  }

  // Pyriform (tear-drop) profile function: t in [-1 (tapered apex), +1 (bulbous belly)]
  function halfWidth(t) {
    // Smooth tear-drop curve
    let s = (t + 1) * 0.5; // 0 at tip, 1 at base
    return 66 * pow(s, 0.58) * sqrt(max(0, 1 - s * 0.82)) * 1.42;
  }

  // Outer mold flange seam (pinched equatorial ridge around the pear drop)
  let flangePts = [];
  let bodyPts = [];
  let steps = 28;
  for (let i = 0; i <= steps; i++) {
    let t = map(i, 0, steps, -1, 1);
    let u = t * len;
    let w = halfWidth(t);
    bodyPts.push(rPt(u, -w));
    flangePts.push(rPt(u * 1.05, -(w + 5.5)));
  }
  for (let i = steps; i >= 0; i--) {
    let t = map(i, 0, steps, -1, 1);
    let u = t * len;
    let w = halfWidth(t);
    bodyPts.push(rPt(u, w));
    flangePts.push(rPt(u * 1.05, w + 5.5));
  }

  // 1. Cast shadow with split Dichroic Caustic (Beryl at apex, Garnet at belly!)
  drawSpecimenShadow(flangePts, 16, 20, PALETTE.garnet.caustic, 78);
  let apexCaustic = [];
  for (let i = 0; i < 12; i++) apexCaustic.push([flangePts[i][0] + 16, flangePts[i][1] + 20]);
  fillPoly(apexCaustic, PALETTE.beryl.caustic, 68, 0.06, 0.3, 0.2);

  // 2. Translucent pinched mold flange rim
  fillPoly(flangePts, PALETTE.garnet.pale, 55, 0.03, 0.35, 0.3);
  hatchPoly(flangePts, tilt + 90, 3.2, PALETTE.inkMid, 0.6);
  strokeFacet(flangePts, 0.78, true);

  // 3. Dichroic Watermelon-Tourmaline Washes (Beryl Green apex -> Rose-Garnet belly)
  let apexZone = [], midZone = [], bellyZone = [], bellyShadow = [];
  for (let i = 0; i <= steps; i++) {
    let t = map(i, 0, steps, -1, 1);
    let u = t * len, w = halfWidth(t);
    if (t <= 0.05) apexZone.push(rPt(u, -w));
    if (t >= -0.35 && t <= 0.45) midZone.push(rPt(u, -w));
    if (t >= 0.0) bellyZone.push(rPt(u, -w));
    if (t >= -0.2) bellyShadow.push(rPt(u, w * 0.05));
  }
  for (let i = steps; i >= 0; i--) {
    let t = map(i, 0, steps, -1, 1);
    let u = t * len, w = halfWidth(t);
    if (t <= 0.05) apexZone.push(rPt(u, w));
    if (t >= -0.35 && t <= 0.45) midZone.push(rPt(u, w));
    if (t >= 0.0) bellyZone.push(rPt(u, w));
    if (t >= -0.2) bellyShadow.push(rPt(u, w));
  }

  fillPoly(apexZone, PALETTE.beryl.light, 85, 0.06, 0.45, 0.3);
  fillPoly(midZone, PALETTE.beryl.pale, 55, 0.08, 0.4, 0.2);
  fillPoly(bellyZone, PALETTE.garnet.light, 88, 0.06, 0.45, 0.35);
  fillPoly(bellyShadow, PALETTE.garnet.deep, 98, 0.05, 0.5, 0.4);

  // 4. 3D Curved meridian and latitude copperplate cross-hatching
  // Meridians running from pinched tip to bulbous base
  for (let vFrac = -0.92; vFrac <= 0.92; vFrac += 0.11) {
    if (vFrac > -0.62 && vFrac < -0.22) continue; // Specular highlight gap
    let mPts = [];
    for (let i = 1; i < steps; i++) {
      let t = map(i, 0, steps, -1, 1);
      let u = t * len;
      let w = halfWidth(t);
      mPts.push(rPt(u, vFrac * w));
    }
    let isDark = vFrac > 0.08;
    brush.set(isDark ? "engraver" : "etch_needle",
              isDark ? PALETTE.inkDeep : PALETTE.inkMid,
              map(vFrac, -0.9, 0.9, 0.5, 0.9));
    brush.spline(mPts, 0.5);
  }

  // Curved latitude cross-hatching ribs
  for (let i = 3; i < steps - 1; i += 2) {
    let t = map(i, 0, steps, -1, 1);
    let u = t * len;
    let w = halfWidth(t);
    let latPts = [];
    let startV = -0.15; // Cross-hatch on shadow side
    for (let vf = startV; vf <= 0.95; vf += 0.15) {
      let bulge = sqrt(max(0, 1 - vf * vf)) * 11;
      latPts.push(rPt(u + bulge, vf * w));
    }
    brush.set("engraver", PALETTE.inkDark, 0.72);
    brush.spline(latPts, 0.5);
  }

  // 5. Internal bubbles & glossy skylight reflection
  let pBubbles = [
    [-0.45, -0.2, 3.2], [-0.15, 0.15, 4.5], [0.12, -0.1, 5.2],
    [0.35, 0.25, 4.0], [0.48, -0.25, 3.6], [0.22, 0.45, 2.8],
    [-0.28, -0.35, 2.4], [0.58, 0.1, 3.0]
  ];
  for (let [bt, bv, br] of pBubbles) {
    let w = halfWidth(bt);
    let pt = rPt(bt * len, bv * w);
    drawVesicle(pt[0], pt[1], br, bt < 0 ? PALETTE.beryl.pale : PALETTE.garnet.pale, 1.15, tilt);
  }

  // Body seam contour
  strokeFacet(bodyPts, 0.88, false);

  // Curved studio window highlight along the upper-left slope of the Pear Drop
  for (let seg of [[-0.55, -0.08], [0.02, 0.58]]) {
    for (let vf = -0.52; vf <= -0.32; vf += 0.06) {
      let hPts = [];
      for (let t = seg[0]; t <= seg[1]; t += 0.08) {
        hPts.push(rPt(t * len, vf * halfWidth(t)));
      }
      brush.set("gouache_white", PALETTE.white, vf === -0.4 ? 1.35 : 0.85);
      brush.spline(hPts, 0.5);
    }
  }

  // Frosted sugar dusting & loose granules
  drawLooseSugarCrystals(cx, cy, 9, 92, 78, PALETTE.garnet);
}

// =============================================================================
// SPECIMEN 8: RHOMBOHEDRAL SUGAR SPAR (DOUBLE-REFRACTING BLOCK) (FIG. 8)
// =============================================================================

function drawSpecimen8_SugarSparRhomb(cx, cy) {
  // 3D Rhombohedron (Iceland Spar / Cleavage Sugar Block)
  // Top face vertices
  let T_back = [cx - 8, cy - 78];
  let T_left = [cx - 84, cy - 32];
  let T_front = [cx - 2, cy + 8];
  let T_right = [cx + 78, cy - 40];

  // Bottom face vertices (shifted down and slightly right-forward by cleavage vector)
  let dx = 8, dy = 68;
  let B_back = [T_back[0] + dx, T_back[1] + dy];
  let B_left = [T_left[0] + dx, T_left[1] + dy];
  let B_front = [T_front[0] + dx, T_front[1] + dy];
  let B_right = [T_right[0] + dx, T_right[1] + dy];

  let topFace = [T_back, T_right, T_front, T_left];
  let leftFace = [T_left, T_front, B_front, B_left];
  let rightFace = [T_front, T_right, B_right, B_front];
  let outerSil = [T_back, T_right, B_right, B_front, B_left, T_left];

  // Small detached cleaved rhomb resting at lower-left
  let sm = 0.28, sx = cx - 86, sy = cy + 54;
  let smSil = outerSil.map(p => [sx + (p[0] - cx) * sm, sy + (p[1] - cy) * sm]);

  // 1. Cast shadows with cool Celestine-Aquamarine caustic
  drawSpecimenShadow(outerSil, 16, 20, PALETTE.aqua.caustic, 75);
  drawSpecimenShadow(smSil, 8, 10, PALETTE.aqua.caustic, 55);

  // 2. Birefringence / Double Refraction Demonstration!
  // Reference line on the paper entering from top-left and exiting bottom-right
  brush.set("engraver", PALETTE.inkDeep, 0.9);
  brush.line(cx - 102, cy - 52, T_left[0] + 18, T_left[1] - 11);
  brush.line(B_right[0] - 24, B_right[1] + 14, cx + 98, cy + 52);

  // Inside the transparent crystal, the line & cross "+" split into TWO (ordinary & extraordinary rays)!
  // Ordinary ray
  brush.set("engraver", PALETTE.inkDark, 0.8);
  brush.line(T_left[0] + 18, T_left[1] - 11, B_right[0] - 24, B_right[1] + 14);
  // Extraordinary (displaced) ray
  brush.set("etch_needle", PALETTE.inkMid, 0.75);
  brush.line(T_left[0] + 24, T_left[1] - 18, B_right[0] - 18, B_right[1] + 5);

  // Doubled calibration cross "+" seen through the center of the crystal
  let crX = cx - 14, crY = cy - 12;
  brush.set("engraver", PALETTE.inkDark, 0.85);
  brush.line(crX - 11, crY, crX + 11, crY);
  brush.line(crX, crY - 11, crX, crY + 11);
  // Second refracted image of the cross offset by (+9, -7)
  brush.set("etch_needle", PALETTE.inkMid, 0.75);
  brush.line(crX + 9 - 11, crY - 7, crX + 9 + 11, crY - 7);
  brush.line(crX + 9, crY - 7 - 11, crX + 9, crY - 7 + 11);

  // 3. Rear hidden edges of the rhombohedron visible through the crystal
  brush.set("etch_needle", PALETTE.inkLight, 0.65);
  drawDottedLine(T_back[0], T_back[1], B_back[0], B_back[1], 3.2);
  drawDottedLine(B_left[0], B_left[1], B_back[0], B_back[1], 3.2);
  drawDottedLine(B_right[0], B_right[1], B_back[0], B_back[1], 3.2);

  // 4. Internal iridescent cleavage fracture plane (Newton's rings of Garnet, Citrine & Beryl!)
  let iridCrack = [
    [cx - 32, cy - 28],
    [cx + 26, cy - 42],
    [cx + 42, cy - 8],
    [cx - 8, cy + 16]
  ];
  fillPoly(iridCrack, PALETTE.citrine.light, 58, 0.05, 0.35, 0.25);
  fillPoly(iridCrack.map(p => [p[0] + 5, p[1] + 4]), PALETTE.garnet.light, 52, 0.05, 0.35, 0.25);
  fillPoly(iridCrack.map(p => [p[0] + 10, p[1] + 8]), PALETTE.beryl.light, 55, 0.05, 0.35, 0.25);
  // Concentric interference fringes inside the internal crack
  brush.set("etch_needle", PALETTE.inkMid, 0.55);
  for (let f = 0.25; f <= 0.85; f += 0.2) {
    let ring = iridCrack.map(p => [lerp(cx + 6, p[0], f), lerp(cy - 14, p[1], f)]);
    brush.spline(ring.concat([ring[0]]), 0.4);
  }

  // 5. Render the 3 visible outer rhombohedral faces
  renderCrystalFacet(topFace, -0.25, -0.35, 0.9, PALETTE.aqua, -28, 0.75);
  renderCrystalFacet(leftFace, -0.72, 0.42, 0.45, PALETTE.aqua, 28, 0.88);
  renderCrystalFacet(rightFace, 0.78, 0.48, -0.25, PALETTE.amethyst, -32, 0.95);

  // 6. Stepped cleavage notch at the front-top vertex (showing rhombohedral cleavage law)
  let step1 = [
    [T_front[0] - 18, T_front[1] - 10],
    [T_front[0] + 18, T_front[1] - 11],
    [T_front[0] + 20, T_front[1] + 12],
    [T_front[0] - 16, T_front[1] + 12]
  ];
  fillPoly(step1, PALETTE.aqua.mid, 85, 0.02, 0.35, 0.3);
  hatchPoly(step1, -28, 2.4, PALETTE.inkDeep, 0.72);
  strokeFacet(step1, 0.85, true);

  // Render the small detached cleavage rhomb
  fillPoly(smSil, PALETTE.aqua.light, 82, 0.02, 0.35, 0.3);
  hatchPoly(smSil, 28, 2.5, PALETTE.inkDark, 0.7);
  strokeFacet(smSil, 0.8, true);

  // Crisp outer & front ridges with intense white gouache highlights
  strokeFacet(topFace, 0.95, true);
  strokeFacet(leftFace, 0.95, true);
  strokeFacet(rightFace, 0.95, true);

  drawLooseSugarCrystals(cx, cy, 8, 96, 80, PALETTE.aqua);
}

// =============================================================================
// SPECIMEN 9: BOTRYOIDAL SOUR VIOLET & BLACKBERRY CLUSTER (FIG. 9)
// =============================================================================

function drawSpecimen9_BotryoidalViolets(cx, cy) {
  // Botryoidal aggregate of fused glossy sugar spheres
  let spheres = [
    // Back ring
    [-46, -34, 26], [0, -48, 28], [44, -32, 26],
    [-58, 6, 26], [56, 8, 27], [-38, 42, 25], [38, 42, 26], [0, 50, 27],
    // Mid ring
    [-26, -18, 30], [24, -18, 29], [-30, 18, 29], [28, 20, 30],
    // Central crown domes
    [0, -2, 34]
  ];

  // Overall scalloped silhouette
  let silPts = [];
  for (let a = 0; a < 360; a += 12) {
    let maxR = 68;
    let px = cx + cos(a) * maxR;
    let py = cy + sin(a) * maxR;
    // Project outward to envelope of spheres
    let bestD = 0;
    for (let [sx, sy, sr] of spheres) {
      let d = (sx * cos(a) + sy * sin(a)) + sr;
      if (d > bestD) bestD = d;
    }
    silPts.push([cx + cos(a) * bestD, cy + sin(a) * bestD * 0.94]);
  }

  // Detached single botryoidal hemisphere resting at lower-left
  let dxSphere = cx - 84, dySphere = cy + 54, drSphere = 21;
  let detPts = [];
  for (let a = 0; a < 360; a += 24) {
    detPts.push([dxSphere + cos(a) * drSphere, dySphere + sin(a) * drSphere * 0.9]);
  }

  // 1. Cast shadows with deep Royal Amethyst caustic
  drawSpecimenShadow(silPts, 16, 20, PALETTE.amethyst.caustic, 82);
  drawSpecimenShadow(detPts, 9, 12, PALETTE.amethyst.caustic, 65);

  // Helper to render one glossy botryoidal sugar dome
  function renderBotryoidDome(sx, sy, sr, isCrown = false) {
    let dPts = [];
    for (let a = 0; a < 360; a += 20) {
      dPts.push([sx + cos(a) * sr, sy + sin(a) * sr]);
    }

    // Base amethyst wash + deep garnet-violet shadow crescent
    fillPoly(dPts, isCrown ? PALETTE.amethyst.light : PALETTE.amethyst.mid, 88, 0.03, 0.45, 0.35);

    let crescent = [];
    for (let a = -25; a <= 155; a += 18) crescent.push([sx + cos(a) * sr, sy + sin(a) * sr]);
    for (let a = 155; a >= -25; a -= 22) crescent.push([sx + cos(a) * sr * 0.25, sy + sin(a) * sr * 0.25]);
    fillPoly(crescent, PALETTE.amethyst.deep, 110, 0.04, 0.5, 0.4);
    fillPoly(crescent, PALETTE.garnet.deep, 55, 0.04, 0.4, 0.3);

    // Spherical contour-following engraving arcs
    for (let rFrac = 0.28; rFrac <= 0.94; rFrac += 0.13) {
      let arcPts = [];
      let aStart = map(rFrac, 0.28, 0.94, 15, -35);
      let aEnd = map(rFrac, 0.28, 0.94, 145, 195);
      for (let a = aStart; a <= aEnd; a += 12) {
        arcPts.push([
          sx + cos(a) * sr * rFrac + 2,
          sy + sin(a) * sr * rFrac + 2
        ]);
      }
      brush.set("engraver", PALETTE.inkDeep, map(rFrac, 0.28, 0.94, 0.6, 0.9));
      brush.spline(arcPts, 0.5);
    }

    // Cross-hatching meridian curves on shadow side of dome
    for (let a = -15; a <= 145; a += 22) {
      let mPts = [];
      for (let t = 0.2; t <= 0.96; t += 0.25) {
        mPts.push([
          sx + cos(a + t * 18) * sr * t,
          sy + sin(a + t * 18) * sr * t
        ]);
      }
      brush.set("etch_needle", PALETTE.inkDeep, 0.68);
      brush.spline(mPts, 0.5);
    }

    // Crisp dome contour
    strokeFacet(dPts, 0.85, false);

    // Sharp glossy skylight reflection on each individual dome!
    drawGlossyWindowHighlight(sx, sy, sr * 0.72, sr * 0.72, 202, 250, sr * 0.16);
  }

  // 2. Render all domes back-to-front
  for (let i = 0; i < spheres.length; i++) {
    let [ox, oy, sr] = spheres[i];
    renderBotryoidDome(cx + ox, cy + oy, sr, i >= 8);
  }

  // Render detached dome at lower-left
  renderBotryoidDome(dxSphere, dySphere, drSphere, false);

  // 3. Encrusted granulated sugar crystals sparkling in the crevices between domes!
  let crevices = [
    [-26, -34], [24, -34], [-40, -4], [40, -4],
    [-16, -18], [16, -18], [-18, 18], [18, 18],
    [-32, 32], [32, 32], [0, 34], [0, -32]
  ];
  for (let [gx, gy] of crevices) {
    drawLooseSugarCrystals(cx + gx, cy + gy, 3, 6, 6, PALETTE.amethyst);
  }

  drawLooseSugarCrystals(cx, cy, 10, 94, 82, PALETTE.amethyst);
}

