};

function drawEngravedText(str, x, y, h, tracking = 4.5, italic = false, align = "center", col = PALETTE.inkDark, weight = 0.65) {
  let wChar = h * 0.68;
  let step = wChar + tracking;
  let totalW = 0;
  for (let i = 0; i < str.length; i++) {
    let ch = str[i];
    if (ch === " ") totalW += wChar * 0.65;
    else if (ch === "." || ch === ",") totalW += wChar * 0.45 + tracking * 0.6;
    else totalW += step;
  }

  let curX = x;
  if (align === "center") curX -= totalW * 0.5;
  else if (align === "right") curX -= totalW;

  let slant = italic ? h * 0.24 : 0;
  brush.set("etch_needle", col, weight);

  for (let i = 0; i < str.length; i++) {
    let ch = str[i].toUpperCase();
    if (ch === " ") {
      curX += wChar * 0.65;
      continue;
    }
    let strokes = GLYPHS[ch];
    if (strokes) {
      for (let st of strokes) {
        for (let k = 0; k < st.length - 1; k++) {
          let p1 = st[k], p2 = st[k + 1];
          let x1 = curX + p1[0] * wChar + (1 - p1[1]) * slant;
          let y1 = y + p1[1] * h;
          let x2 = curX + p2[0] * wChar + (1 - p2[1]) * slant;
          let y2 = y + p2[1] * h;
          brush.line(x1, y1, x2, y2);
        }
      }
    }
    if (ch === "." || ch === ",") curX += wChar * 0.45 + tracking * 0.6;
    else curX += step;
  }
}

function drawDottedLine(x1, y1, x2, y2, gap = 3.5) {
  let d = dist(x1, y1, x2, y2);
  let steps = floor(d / gap);
  for (let i = 0; i <= steps; i++) {
    let t = i / max(1, steps);
    let px = lerp(x1, x2, t);
    let py = lerp(y1, y2, t);
    brush.line(px - 0.4, py - 0.4, px + 0.4, py + 0.4);
  }
}

function signPow(val, exp) {
  return (val >= 0 ? 1 : -1) * pow(abs(val), exp);
}

