  drawAllParterreBeds();

  // 4. Clipped boxwood-green felt racks / topiary bridges (lower layer)
  drawFeltRacksUnder();

  // 5. Symmetrical cutlery: central stacked spoons, flanking forks, knives & axial pieces
  drawCentralStackedSpoons();
