// =============================================================================
// LOW-LEVEL DRAWING HELPERS (Safe state management for p5.brush)
// =============================================================================

function resetBrushState() {
  brush.noStroke();
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.noMass();
}

function fillPoly(pts, col, alpha = 140, bleed = 0.06, tex = 0.35, border = 0.25, curv = 0) {
  resetBrushState();
  brush.fill(col, alpha);
  brush.fillBleed(bleed, "out");
  brush.fillTexture(tex, border);
  brush.beginShape(curv);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
  resetBrushState();
}

function washPoly(pts, col, alpha = 160, curv = 0) {
  resetBrushState();
  brush.wash(col, alpha);
  brush.beginShape(curv);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
  resetBrushState();
}

function strokePoly(pts, bName, col, weight = 0.5, curv = 0, closed = true) {
  resetBrushState();
  brush.set(bName, col, weight);
  brush.beginShape(curv);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(closed);
  resetBrushState();
}

function ruledLine(x1, y1, x2, y2, bName = "2H", col = PAL.graphiteMid, weight = 0.45) {
  resetBrushState();
  brush.set(bName, col, weight);
  brush.line(x1, y1, x2, y2);
}

function ruledSpline(pts, bName = "2H", col = PAL.graphiteMid, weight = 0.45, curv = 0.5) {
  resetBrushState();
  brush.set(bName, col, weight);
  brush.spline(pts, curv);
}

function rectPts(x, y, w, h) {
  return [
    [x, y],
    [x + w, y],
    [x + w, y + h],
    [x, y + h]
  ];
}

function chamferRectPts(x, y, w, h, c) {
  return [
    [x + c, y],
    [x + w - c, y],
    [x + w, y + c],
    [x + w, y + h - c],
    [x + w - c, y + h],
    [x + c, y + h],
    [x, y + h - c],
    [x, y + c]
  ];
}

function bastionRectPts(x, y, w, h, c, step = 6) {
  // Formal French parterre bed with stepped corner bastions
  return [
    [x + c, y],
    [x + w - c, y],
    [x + w - c, y + step],
    [x + w - step, y + c],
    [x + w, y + c],
    [x + w, y + h - c],
    [x + w - step, y + h - c],
    [x + w - c, y + h - step],
    [x + w - c, y + h],
    [x + c, y + h],
    [x + c, y + h - step],
    [x + step, y + h - c],
    [x, y + h - c],
    [x, y + c],
    [x + step, y + c],
    [x + c, y + step]
  ];
}

function ellipsePts(cx, cy, rx, ry, n = 24) {
  let pts = [];
  for (let i = 0; i < n; i++) {
    let a = (i / n) * 360;
    pts.push([cx + cos(a) * rx, cy + sin(a) * ry]);
  }
  return pts;
}

// =============================================================================
// 1. ARCHIVAL SHEET & ARCHITECTURAL MARGIN
// =============================================================================

function drawArchivalSheet() {
  // Soft warm paper edge washes
  fillPoly(rectPts(36, 36, 1128, 1128), PAL.paperWarm, 55, 0.12, 0.25, 0.15);

  // Subtle woven linen texture across sheet
  resetBrushState();
  brush.set("2H", "#ded5c5", 0.22);
  for (let y = 45; y <= 1155; y += 30) {
    brush.line(45, y, 1155, y);
  }
  for (let x = 45; x <= 1155; x += 30) {
    brush.line(x, 45, x, 1155);
  }

  // Outer architectural double border
  strokePoly(rectPts(38, 38, 1124, 1124), "2H", PAL.graphiteMid, 0.55);
  strokePoly(rectPts(46, 46, 1108, 1108), "2H", PAL.graphiteLight, 0.35);

  // Scale graduation ticks inside the 8px border band (top & bottom)
  for (let x = 60; x <= 1140; x += 10) {
    let isMajor = (x - 600) % 50 === 0;
    let tickLen = isMajor ? 8 : 4;
    let col = isMajor ? PAL.graphiteMid : PAL.graphiteFaint;
    let w = isMajor ? 0.4 : 0.25;
    ruledLine(x, 38, x, 38 + tickLen, "2H", col, w);
    ruledLine(x, 1162 - tickLen, x, 1162, "2H", col, w);
  }
  for (let y = 60; y <= 1140; y += 10) {
    let isMajor = (y - 600) % 50 === 0;
    let tickLen = isMajor ? 8 : 4;
    let col = isMajor ? PAL.graphiteMid : PAL.graphiteFaint;
    let w = isMajor ? 0.4 : 0.25;
    ruledLine(38, y, 38 + tickLen, y, "2H", col, w);
    ruledLine(1162 - tickLen, y, 1162, y, "2H", col, w);
  }

  // Corner registration medallions
  let corners = [
    [46, 46],
    [1154, 46],
    [1154, 1154],
    [46, 1154]
  ];
  for (let [cx, cy] of corners) {
    resetBrushState();
    brush.set("2H", PAL.graphiteMid, 0.38);
    brush.circle(cx, cy, 6, 0.05);
    ruledLine(cx - 10, cy, cx + 10, cy, "2H", PAL.graphiteMid, 0.35);
    ruledLine(cx, cy - 10, cx, cy + 10, "2H", PAL.graphiteMid, 0.35);
  }
}

