function getCompartments() {
  return [
    // Central Spine
    { id: "N_AXIAL", x: 476, y: 128, w: 248, h: 176, inset: 15, corner: 24 },
    { id: "C_CANAL", x: 476, y: 324, w: 248, h: 520, inset: 15, corner: 26 },
