function drawAllParterreBeds() {
  let beds = getCompartments();

  // Pass 1: Pale linen gravel-path base wash in all 9 compartments
  for (let b of beds) {
    fillPoly(rectPts(b.x, b.y, b.w, b.h), PAL.linenLight, 155, 0.04, 0.3, 0.2);
    // Subtle recessed perimeter shading inside wooden walls
    washPoly(rectPts(b.x, b.y, b.w, 6), PAL.linenDark, 120);
    washPoly(rectPts(b.x, b.y + b.h - 5, b.w, 5), PAL.linenDark, 90);
  }

  // Pass 2: Raked gravel grooves & symmetrical crumb/grit trails in the perimeter channels
  for (let b of beds) {
    drawRakedGravelPath(b);
  }

  // Pass 3: Muted sap-green / boxwood felt base watercolor washes
  for (let b of beds) {
    let fx = b.x + b.inset;
    let fy = b.y + b.inset;
    let fw = b.w - b.inset * 2;
    let fh = b.h - b.inset * 2;
    let feltPts = bastionRectPts(fx, fy, fw, fh, b.corner, 6);

    // Shadow of raised felt pad onto gravel channel
    let padShadow = bastionRectPts(fx - 2, fy + 2, fw + 4, fh + 2, b.corner, 6);
    washPoly(padShadow, "#b5a892", 130);

    // Primary boxwood sap-green watercolor wash
    fillPoly(feltPts, PAL.feltBase, 165, 0.07, 0.42, 0.3);

    // Inner clipped parterre lawn panel in deeper sap green
    let inPts = chamferRectPts(fx + 10, fy + 10, fw - 20, fh - 20, b.corner - 4);
    fillPoly(inPts, PAL.feltDeep, 85, 0.08, 0.45, 0.25);
  }

  // Pass 4: Dense, fine pencil stippling & clipped boxwood topiary detailing
  for (let b of beds) {
    drawBoxwoodFeltStippling(b);
  }
}

function drawRakedGravelPath(b) {
  let { x, y, w, h, inset, corner } = b;

  // Draw 4 concentric raked lines in the perimeter gravel walk around the felt pad
  for (let r = 3.5; r < inset - 1.5; r += 3.5) {
    let rx = x + r;
    let ry = y + r;
    let rw = w - r * 2;
    let rh = h - r * 2;
    let rc = max(4, corner - (inset - r) * 0.7);
    let rPts = chamferRectPts(rx, ry, rw, rh, rc);
    strokePoly(rPts, "2H", "#b5a893", 0.32, 0, true);
  }

  // Diagonal corner rake fans (like Karesansui / French gravel parterre corners)
  let cSize = inset + corner * 0.75;
  let cornerFans = [
    [x, y, 1, 1],
    [x + w, y, -1, 1],
    [x + w, y + h, -1, -1],
    [x, y + h, 1, -1]
  ];
  for (let [cx, cy, sx, sy] of cornerFans) {
    for (let d = 6; d <= cSize; d += 4.5) {
      ruledLine(cx + sx * d, cy + sy * 2, cx + sx * 2, cy + sy * d, "2H", "#aba08c", 0.28);
    }
  }

  // Crumbs & grit arranged along the raked gravel paths
  // For strict bilateral symmetry, generate in local mirror-paired coordinates
  drawSymmetricalCrumbsInBed(b);
}

function drawSymmetricalCrumbsInBed(b) {
  // Only generate when processing Left or Central beds; mirror Left onto Right automatically
  if (b.id.startsWith("R_")) return;

  let isCenter = b.id.startsWith("N_") || b.id.startsWith("C_") || b.id.startsWith("S_");
  let { x, y, w, h, inset, corner } = b;

  // Collect crumb coordinates in the perimeter channel
  let crumbs = [];

  // Corner grit pockets (richer accumulation where a brush/rake sweeps into corners)
  let topY = y + 4;
  let botY = y + h - 4;
  let leftX = x + 4;

  // Generate 28 crumb particles on the left half of this bed
  for (let i = 0; i < 28; i++) {
    let px, py;
    if (i < 12) {
      // Corner pocket cluster (top-left or bottom-left)
      let isTop = i % 2 === 0;
      let u = random(2, inset + corner * 0.65);
      let v = random(2, inset + corner * 0.65 - u * 0.65);
      px = x + u;
      py = isTop ? y + v : y + h - v;
    } else if (i < 20) {
      // Along vertical gravel channel
      px = x + random(3, inset - 2.5);
      py = y + random(inset, h - inset);
    } else {
      // Along top/bottom horizontal gravel channel (left half)
      px = x + random(inset, w * 0.48);
      py = (i % 2 === 0) ? y + random(3, inset - 2.5) : y + h - random(3, inset - 2.5);
    }

    let kind = i % 4; // 0: gold toast crumb, 1: dark crust grit, 2: salt crystal, 3: graphite speck
    let sz = random(1.4, 3.2);
    crumbs.push({ px, py, kind, sz });
  }

  for (let c of crumbs) {
    renderCrumbParticle(c.px, c.py, c.kind, c.sz);
    if (isCenter) {
      // Mirror across x = 600 within central compartment
      renderCrumbParticle(1200 - c.px, c.py, c.kind, c.sz);
    } else {
      // Mirror within this Left wing bed AND mirror to the Right wing bed!
      let localMirrorX = x + w - (c.px - x);
      renderCrumbParticle(localMirrorX, c.py, c.kind, c.sz);
      renderCrumbParticle(1200 - c.px, c.py, c.kind, c.sz);
      renderCrumbParticle(1200 - localMirrorX, c.py, c.kind, c.sz);
    }
  }
}

function renderCrumbParticle(x, y, kind, sz) {
  resetBrushState();
  if (kind === 0) {
    // Golden toast crumb with tiny cast shadow
    brush.set("2H", PAL.crumbDark, sz * 0.35);
    brush.line(x - 0.5, y + 1, x + sz * 0.6, y + 1.2);
    brush.set("cpencil", PAL.crumbGold, sz * 0.55);
    brush.line(x - sz * 0.4, y, x + sz * 0.4, y - 0.3);
  } else if (kind === 1) {
    // Dark roasted grit fleck
    brush.set("HB", PAL.crumbDark, sz * 0.42);
    brush.line(x - sz * 0.3, y - 0.2, x + sz * 0.3, y + 0.2);
  } else if (kind === 2) {
    // Salt crystal cube highlight + shadow edge
    brush.set("2H", PAL.graphiteLight, sz * 0.3);
    brush.line(x - 0.6, y + 0.8, x + 0.8, y + 0.8);
    brush.set("cpencil", PAL.crumbSalt, sz * 0.55);
    brush.line(x - 0.5, y - 0.2, x + 0.6, y - 0.2);
  } else {
    // Fine pepper / mineral grit
    brush.set("2H", PAL.graphiteMid, sz * 0.32);
    brush.line(x - 0.4, y, x + 0.4, y);
  }
}

function drawBoxwoodFeltStippling(b) {
  let fx = b.x + b.inset;
  let fy = b.y + b.inset;
  let fw = b.w - b.inset * 2;
  let fh = b.h - b.inset * 2;
  let feltPts = bastionRectPts(fx, fy, fw, fh, b.corner, 6);
  let innerPts = chamferRectPts(fx + 7, fy + 7, fw - 14, fh - 14, b.corner - 3);

  // 1. Fine cross-hatch foundation inside felt pad to give woven baize structure
  resetBrushState();
  brush.hatchStyle("2H", PAL.feltStippleMid, 0.32);
  brush.hatch(7, 45, { rand: 0.08 });
  brush.beginShape(0);
  for (let p of innerPts) brush.vertex(p[0], p[1]);
  brush.endShape(true);
  resetBrushState();

  // 2. Spray stipple mist along the felt interior for dense velvet/boxwood grain
  resetBrushState();
  brush.set("spray", PAL.feltStippleDark, 0.42);
  for (let sy = fy + 16; sy <= fy + fh - 16; sy += 24) {
    brush.line(fx + 18, sy, fx + fw - 18, sy);
  }

  // 3. Dense, rhythmic hand-stippled pencil dots across the boxwood liner
  // Symmetrically mirrored across the bed centerline
  let midX = fx + fw / 2;
  let stepX = 9.5;
  let stepY = 9.5;

  for (let py = fy + 10; py <= fy + fh - 10; py += stepY) {
    for (let dx = 4.5; dx <= fw / 2 - 8; dx += stepX) {
      // Check corner chamfer clearance
      let distTop = py - fy;
      let distBot = (fy + fh) - py;
      let distSide = fw / 2 - dx;
      if (distTop + distSide < b.corner + 4) continue;
      if (distBot + distSide < b.corner + 4) continue;

      let jx = (noise(dx * 0.1, py * 0.1) - 0.5) * 4.5;
      let jy = (noise(py * 0.1, dx * 0.1) - 0.5) * 4.5;
      let xL = midX - dx + jx;
      let xR = midX + dx - jx;
      let yP = py + jy;

      let nVal = noise(dx * 0.08, py * 0.08);
      let col = nVal > 0.58 ? PAL.feltStippleLight : (nVal < 0.38 ? PAL.feltStippleDark : PAL.feltStippleMid);
      let bType = nVal > 0.55 ? "cpencil" : "2H";
      let w = nVal > 0.58 ? 0.48 : 0.36;

      resetBrushState();
      brush.set(bType, col, w);
      brush.line(xL - 1.1, yP - 0.4, xL + 1.1, yP + 0.4);
      brush.line(xR + 1.1, yP - 0.4, xR - 1.1, yP + 0.4);
    }
  }

  // 4. Clipped formal parterre borders & corner topiary sentinel roundels
  strokePoly(feltPts, "HB", PAL.feltShadow, 0.52);
  strokePoly(innerPts, "2H", PAL.feltStippleDark, 0.38);

  // Corner topiary roundels (clipped boxwood balls at the 4 inner corners)
  let rOff = b.corner + 2;
  let roundels = [
    [fx + rOff, fy + rOff],
    [fx + fw - rOff, fy + rOff],
    [fx + fw - rOff, fy + fh - rOff],
    [fx + rOff, fy + fh - rOff]
  ];
  for (let [rx, ry] of roundels) {
    washPoly(ellipsePts(rx, ry, 5.5, 5.5, 14), PAL.feltDeep, 190);
     washPoly(ellipsePts(rx - 1.2, ry - 1.2, 2.5, 2.5, 10), PAL.feltLight, 180);
    resetBrushState();
    brush.set("2H", PAL.feltShadow, 0.38);
    brush.circle(rx, ry, 5.5, 0.05);
  }

  // Central parterre axis broderie lines inside the Central Grand Canal bed
  if (b.id === "C_CANAL") {
    // Two internal clipped boxwood hedge strips separating central soup spoons from flanking teaspoons
    for (let hx of [558, 642]) {
      let hedge = chamferRectPts(hx - 4, fy + 24, 8, fh - 48, 3);
      washPoly(hedge, PAL.feltDeep, 185);
      washPoly(rectPts(hx - 2, fy + 28, 3, fh - 56), PAL.feltLight, 150);
      strokePoly(hedge, "2H", PAL.feltShadow, 0.38);
    }
  }
}

