function drawFeltRacksUnder() {
  // Horizontal slotted felt bridges across the Upper Fork Beds (y = 304..330)
  // and Lower Knife Beds (y = 888..912)
  let hBridges = [
    // Upper Fork racks (Left & Right)
    { x: 168, y: 304, w: 272, h: 26, slots: [204, 244, 284, 324, 364, 404] },
    { x: 760, y: 304, w: 272, h: 26, slots: [796, 836, 876, 916, 956, 996] },
    // Lower Knife racks (Left & Right)
    { x: 168, y: 888, w: 272, h: 24, slots: [204, 244, 284, 324, 364, 404] },
    { x: 760, y: 888, w: 272, h: 24, slots: [796, 836, 876, 916, 956, 996] }
  ];

  for (let br of hBridges) {
    // Cast shadow onto lower felt pad
    washPoly(rectPts(br.x + 2, br.y + 4, br.w - 4, br.h + 2), PAL.feltShadow, 130);
