    fillPoly(rectPts(br.x, br.y, br.w, br.h), PAL.feltBase, 190, 0.03, 0.3, 0.2);
    // Top highlight bezel (clipped topiary crown)
    washPoly(rectPts(br.x + 2, br.y + 2, br.w - 4, 5), PAL.feltLight, 175);
    washPoly(rectPts(br.x + 2, br.y + br.h - 5, br.w - 4, 5), PAL.feltDeep, 170);

    // Stipple texture along bridge
    for (let sx = br.x + 8; sx <= br.x + br.w - 8; sx += 7) {
      ruledLine(sx - 1, br.y + 11, sx + 1, br.y + 13, "2H", PAL.feltStippleDark, 0.35);
    }

    // Dark recessed slots where each fork neck / knife bolster sits
    for (let cx of br.slots) {
      washPoly(rectPts(cx - 5, br.y, 10, br.h), PAL.feltShadow, 190);
      ruledLine(cx - 5, br.y, cx - 5, br.y + br.h, "2H", PAL.graphiteDark, 0.38);
      ruledLine(cx + 5, br.y, cx + 5, br.y + br.h, "2H", PAL.graphiteDark, 0.38);
    }

    strokePoly(rectPts(br.x, br.y, br.w, br.h), "HB", PAL.feltShadow, 0.48);
  }

  // Vertical slotted felt bridges in Middle Horizontal Fork Beds (Left: x = 312..334, Right: x = 866..888)
  let vBridges = [
    { x: 312, y: 551, w: 22, h: 114, slots: [584, 632] },
    { x: 866, y: 551, w: 22, h: 114, slots: [584, 632] }
  ];
  for (let vb of vBridges) {
    washPoly(rectPts(vb.x + 2, vb.y + 3, vb.w, vb.h), PAL.feltShadow, 130);
    fillPoly(rectPts(vb.x, vb.y, vb.w, vb.h), PAL.feltBase, 190, 0.03, 0.3, 0.2);
    washPoly(rectPts(vb.x + 2, vb.y + 2, 5, vb.h - 4), PAL.feltLight, 170);
    for (let sy of vb.slots) {
      washPoly(rectPts(vb.x, sy - 4, vb.w, 8), PAL.feltShadow, 190);
      ruledLine(vb.x, sy - 4, vb.x + vb.w, sy - 4, "2H", PAL.graphiteDark, 0.35);
      ruledLine(vb.x, sy + 4, vb.x + vb.w, sy + 4, "2H", PAL.graphiteDark, 0.35);
    }
    strokePoly(rectPts(vb.x, vb.y, vb.w, vb.h), "HB", PAL.feltShadow, 0.45);
  }
}

function drawFeltRackStrapsOver() {
  // Clipped boxwood-green felt retaining bolster tabs flanking the central spoon stack at y = 558..582
  let straps = [
