function drawCentralStackedSpoons() {
  // 1. Flanking columns of 7 nested teaspoons (x = 524 and x = 676)
  // Oriented with handles at top and bowls cascading downward for baroque counter-rhythm
  for (let side of [-1, 1]) {
    let cx = 600 + side * 76; // 524 and 676
    for (let i = 0; i < 7; i++) {
      let by = 528 + i * 38; // Bowl center y: 528 .. 756
      drawStackedTeaspoonInverted(cx, by, i === 0);
    }
  }

  // 2. Grand Central Spine of 9 Stacked Soup/Table Spoons along x = 600
  // Oriented with oval bowls at top and sculpted Hanoverian handles cascading downward
  for (let i = 0; i < 9; i++) {
    let bowlCY = 392 + i * 31; // 392 .. 640, handle tip reaches 808
    drawStackedSoupSpoon(600, bowlCY, i);
  }
}

function drawStackedSoupSpoon(cx, bowlCY, idx) {
  let rx = 24;
  let ry = 35;
  let neckY = bowlCY + ry - 2;
  let handleTipY = bowlCY + 168;

  // 1. Cast / occlusion shadow onto felt or underlying spoon
  let shBowl = ellipsePts(cx, bowlCY + 4, rx + 2.5, ry + 2.5, 24);
  washPoly(shBowl, PAL.feltShadow, 135);

  let shHandle = [
    [cx - 5, neckY + 4],
    [cx + 5, neckY + 4],
    [cx + 10.5, handleTipY - 12],
    [cx, handleTipY + 4],
    [cx - 10.5, handleTipY - 12]
  ];
  washPoly(shHandle, PAL.feltShadow, 125);

  // 2. Handle stem & Hanoverian flared tip (drawn before bowl of next spoon overlaps it)
  let handlePts = [
    [cx - 4.2, neckY - 2],
    [cx + 4.2, neckY - 2],
    [cx + 5.2, neckY + 45],
    [cx + 9.2, handleTipY - 16],
    [cx + 6.5, handleTipY - 4],
    [cx, handleTipY],
    [cx - 6.5, handleTipY - 4],
    [cx - 9.2, handleTipY - 16],
    [cx - 5.2, neckY + 45]
  ];
  fillPoly(handlePts, PAL.pewterMid, 195, 0.02, 0.22, 0.2);

  // Left & right bevel planes on the spoon handle
  let leftHandleFacet = [
    [cx - 4.2, neckY],
    [cx, neckY],
    [cx, handleTipY],
    [cx - 6.5, handleTipY - 4],
    [cx - 9.2, handleTipY - 16],
    [cx - 5.2, neckY + 45]
  ];
  washPoly(leftHandleFacet, PAL.pewterLight, 175);

  let rightHandleFacet = [
    [cx, neckY],
    [cx + 4.2, neckY],
    [cx + 5.2, neckY + 45],
    [cx + 9.2, handleTipY - 16],
    [cx + 6.5, handleTipY - 4],
    [cx, handleTipY]
  ];
  washPoly(rightHandleFacet, PAL.pewterDark, 130);

  // Specular highlight along handle ridge
  ruledLine(cx - 0.6, neckY + 4, cx - 0.6, handleTipY - 3, "cpencil", PAL.steelSpec, 0.55);
  ruledLine(cx, neckY + 2, cx, handleTipY - 1, "2H", PAL.graphiteMid, 0.35);
  strokePoly(handlePts, "2H", PAL.graphiteDark, 0.45);

  // 3. Oval Spoon Bowl (concentric metallic reflections)
  let bowlOuter = ellipsePts(cx, bowlCY, rx, ry, 28);
  fillPoly(bowlOuter, PAL.pewterMid, 205, 0.02, 0.25, 0.2);

  // Deep steel-grey concavity reflection in upper half of bowl
  let crescentDark = [];
  for (let a = 195; a <= 345; a += 12) {
    crescentDark.push([cx + cos(a) * (rx - 3.5), bowlCY + sin(a) * (ry - 4)]);
  }
  for (let a = 345; a >= 195; a -= 12) {
    crescentDark.push([cx + cos(a) * (rx - 10), bowlCY + 5 + sin(a) * (ry - 13)]);
  }
  washPoly(crescentDark, PAL.pewterDeep, 185);

  // Subtle reflected boxwood-green glaze on lateral curves of bowl
  let greenGlazeL = [
    [cx - rx + 3, bowlCY - 8],
    [cx - rx + 7, bowlCY - 6],
    [cx - rx + 6, bowlCY + 14],
    [cx - rx + 2.5, bowlCY + 10]
  ];
  let greenGlazeR = [
    [cx + rx - 3, bowlCY - 8],
    [cx + rx - 7, bowlCY - 6],
    [cx + rx - 6, bowlCY + 14],
    [cx + rx - 2.5, bowlCY + 10]
  ];
  washPoly(greenGlazeL, PAL.steelGreen, 115);
  washPoly(greenGlazeR, PAL.steelGreen, 115);

  // Bright pale-linen / ice-white specular crescent at lower inner bowl & outer lip
  let specCrescent = [];
  for (let a = 25; a <= 155; a += 12) {
    specCrescent.push([cx + cos(a) * (rx - 5), bowlCY + sin(a) * (ry - 6)]);
  }
  for (let a = 155; a >= 25; a -= 12) {
    specCrescent.push([cx + cos(a) * (rx - 11), bowlCY - 3 + sin(a) * (ry - 13)]);
  }
  washPoly(specCrescent, PAL.steelSpec, 210);

  // Top rim bright specular arc
  let rimArc = [];
  for (let a = 210; a <= 330; a += 12) {
    rimArc.push([cx + cos(a) * (rx - 1.5), bowlCY + sin(a) * (ry - 1.5)]);
  }
  ruledSpline(rimArc, "cpencil", PAL.steelSpec, 0.65, 0.5);

  // Inner & outer ruled graphite edges of spoon bowl
  strokePoly(bowlOuter, "2H", PAL.graphiteDark, 0.5);
  strokePoly(ellipsePts(cx, bowlCY + 1, rx - 3, ry - 3.5, 24), "2H", PAL.graphiteMid, 0.32);
}

function drawStackedTeaspoonInverted(cx, bowlCY, isFirst) {
  let rx = 14.5;
  let ry = 21.5;
  let neckY = bowlCY - ry + 2;
  let handleTopY = bowlCY - 155;

  // Shadow
  washPoly(ellipsePts(cx, bowlCY + 3.5, rx + 2, ry + 2, 20), PAL.feltShadow, 130);

  // Handle extending upward (drawn fully on first spoon, partially visible under bowls on subsequent)
  let hPts = [
    [cx - 3, neckY + 2],
    [cx + 3, neckY + 2],
    [cx + 6.2, handleTopY + 12],
    [cx, handleTopY],
    [cx - 6.2, handleTopY + 12]
  ];
  washPoly(hPts, PAL.pewterMid, 195);
  washPoly([
    [cx - 3, neckY],
    [cx, neckY],
    [cx, handleTopY],
    [cx - 6.2, handleTopY + 12]
  ], PAL.pewterLight, 180);
  ruledLine(cx, neckY, cx, handleTopY + 2, "2H", PAL.graphiteMid, 0.32);
  strokePoly(hPts, "2H", PAL.graphiteDark, 0.4);

  // Teaspoon oval bowl
  let bowlPts = ellipsePts(cx, bowlCY, rx, ry, 22);
  fillPoly(bowlPts, PAL.pewterMid, 200, 0.02, 0.22, 0.2);

  // Dark steel reflection crescent
  let darkBand = [];
  for (let a = 200; a <= 340; a += 15) {
    darkBand.push([cx + cos(a) * (rx - 3), bowlCY + sin(a) * (ry - 3.5)]);
  }
  for (let a = 340; a >= 200; a -= 15) {
    darkBand.push([cx + cos(a) * (rx - 7.5), bowlCY + 3 + sin(a) * (ry - 9)]);
  }
  washPoly(darkBand, PAL.pewterDeep, 180);

  // Lower specular highlight arc
  let specBand = [];
  for (let a = 30; a <= 150; a += 15) {
    specBand.push([cx + cos(a) * (rx - 3.5), bowlCY + sin(a) * (ry - 4)]);
  }
  ruledSpline(specBand, "cpencil", PAL.steelSpec, 0.6, 0.5);

  strokePoly(bowlPts, "2H", PAL.graphiteDark, 0.46);
  strokePoly(ellipsePts(cx, bowlCY, rx - 2.5, ry - 2.5, 18), "2H", PAL.graphiteMid, 0.28);
}

