// 5B. NORTH & SOUTH AXIAL PARTERRE CUTLERY (Strictly Symmetric Across x = 600)
// =============================================================================

function drawNorthAxialCutlery() {
  // Compartment y: 128..304, x: 476..724
  // 1. Central Pierced Berry / Sugar Sifter Spoon on x = 600
  let cx = 600;
  let bowlY = 186;
  let r = 24;
  let tipY = 282;

  // Shadow
  washPoly(ellipsePts(cx, bowlY + 3.5, r + 2.5, r + 2, 24), PAL.feltShadow, 140);
  washPoly(rectPts(cx - 5, bowlY + r, 10, tipY - bowlY - r + 2), PAL.feltShadow, 120);

  // Sifter handle
  let hPts = [
    [cx - 3.8, bowlY + r - 2],
    [cx + 3.8, bowlY + r - 2],
    [cx + 8, tipY - 12],
    [cx, tipY],
    [cx - 8, tipY - 12]
  ];
  fillPoly(hPts, PAL.pewterMid, 195, 0.02, 0.2, 0.2);
  washPoly([[cx - 3.8, bowlY + r], [cx, bowlY + r], [cx, tipY], [cx - 8, tipY - 12]], PAL.steelSpec, 170);
  ruledLine(cx, bowlY + r, cx, tipY - 1, "2H", PAL.graphiteMid, 0.35);
  strokePoly(hPts, "2H", PAL.graphiteDark, 0.45);

  // Scalloped / circular sifter bowl
  let bowlPts = ellipsePts(cx, bowlY, r, r - 1, 28);
  fillPoly(bowlPts, PAL.pewterLight, 205, 0.02, 0.22, 0.2);
  washPoly(ellipsePts(cx, bowlY - 2, r - 5, r - 6, 22), PAL.pewterMid, 180);

  // Symmetrical rosette of 19 pierced holes showing dark boxwood felt through the silver!
  let holes = [[0, 0]];
  for (let a = 0; a < 360; a += 60) {
    holes.push([cos(a) * 7, sin(a) * 7]);
  }
  for (let a = 0; a < 360; a += 30) {
    holes.push([cos(a) * 14, sin(a) * 14]);
  }
  for (let [hx, hy] of holes) {
    washPoly(ellipsePts(cx + hx, bowlY + hy, 1.9, 1.9, 8), PAL.feltShadow, 220);
    resetBrushState();
    brush.set("2H", PAL.steelSpec, 0.32);
    brush.arc(cx + hx, bowlY + hy, 2.1, 20, 160);
  }

  strokePoly(bowlPts, "2H", PAL.graphiteDark, 0.5);
  strokePoly(ellipsePts(cx, bowlY, r - 3, r - 4, 24), "2H", PAL.graphiteMid, 0.32);

  // 2. Flanking Pair of Salt / Condiment Spoons at x = 532 and x = 668
  for (let side of [-1, 1]) {
    let sx = 600 + side * 68;
    let sy = 182;
    let sr = 14;
    let sTipY = 276;

    washPoly(ellipsePts(sx, sy + 3, sr + 1.5, sr + 1.5, 18), PAL.feltShadow, 135);
    let sh = [
      [sx - 2.6, sy + sr - 1],
      [sx + 2.6, sy + sr - 1],
      [sx + 5.5, sTipY - 8],
      [sx, sTipY],
      [sx - 5.5, sTipY - 8]
    ];
    washPoly(sh, PAL.pewterMid, 195);
    washPoly([[sx - 2.6, sy + sr], [sx, sy + sr], [sx, sTipY], [sx - 5.5, sTipY - 8]], PAL.steelSpec, 170);
    ruledLine(sx, sy + sr, sx, sTipY - 1, "2H", PAL.graphiteMid, 0.32);
    strokePoly(sh, "2H", PAL.graphiteDark, 0.42);

    // Deep round salt bowl with pale gold / vermeil pastel wash inside
    let sbPts = ellipsePts(sx, sy, sr, sr, 20);
    fillPoly(sbPts, PAL.pewterMid, 200, 0.02, 0.2, 0.2);
    washPoly(ellipsePts(sx, sy, sr - 3, sr - 3, 16), "#d9c69e", 160);
    washPoly(ellipsePts(sx, sy - 3, sr - 6, sr - 7, 12), PAL.pewterDeep, 140);
    ruledSpline([
      [sx - 8, sy + 7],
      [sx, sy + 10],
      [sx + 8, sy + 7]
    ], "cpencil", PAL.steelSpec, 0.55, 0.5);
    strokePoly(sbPts, "2H", PAL.graphiteDark, 0.46);
    strokePoly(ellipsePts(sx, sy, sr - 2.5, sr - 2.5, 16), "2H", PAL.graphiteMid, 0.3);
  }
}

function drawSouthAxialCutlery() {
  // Compartment y: 864..1044, x: 476..724
  // 1. Central Symmetrical Pierced Pastry / Asparagus Server on x = 600
  let cx = 600;
  let bladeTopY = 890;
  let bladeBotY = 962;
  let handleBotY = 1022;

  let bladePts = [
    [cx, bladeTopY],
    [cx + 25, bladeTopY + 26],
    [cx + 22, bladeBotY - 10],
    [cx + 5, bladeBotY],
    [cx - 5, bladeBotY],
    [cx - 22, bladeBotY - 10],
    [cx - 25, bladeTopY + 26]
  ];
  // Shadow
  washPoly(bladePts.map(p => [p[0], p[1] + 4]), PAL.feltShadow, 140);

  // Blade fill & symmetrical bevels
  fillPoly(bladePts, PAL.pewterLight, 205, 0.02, 0.25, 0.2);
  washPoly([
    [cx, bladeTopY + 2],
    [cx + 23, bladeTopY + 26],
    [cx + 20, bladeBotY - 11],
    [cx, bladeBotY - 2]
  ], PAL.pewterMid, 165);

  // Symmetrical pierced lattice slots in server blade
  let slots = [
    [cx, bladeTopY + 18, 3, 14],
    [cx - 9, bladeTopY + 24, 3, 18],
    [cx + 9, bladeTopY + 24, 3, 18],
    [cx, bladeTopY + 38, 3, 16],
    [cx - 16, bladeTopY + 32, 2.5, 12],
    [cx + 16, bladeTopY + 32, 2.5, 12]
  ];
  for (let [sx, sy, sw, sh] of slots) {
    washPoly(rectPts(sx - sw / 2, sy, sw, sh), PAL.feltShadow, 210);
    strokePoly(rectPts(sx - sw / 2, sy, sw, sh), "2H", PAL.graphiteDark, 0.3);
  }

  ruledLine(cx, bladeTopY + 2, cx, bladeBotY, "2H", PAL.graphiteMid, 0.35);
  strokePoly(bladePts, "2H", PAL.graphiteDark, 0.5);

  // Server handle (faceted pale linen / bone handle matching knives)
  let hPts = chamferRectPts(cx - 7, bladeBotY + 4, 14, handleBotY - bladeBotY - 4, 3);
  washPoly(rectPts(cx - 5, bladeBotY, 10, 5), PAL.pewterDark, 195);
  fillPoly(hPts, PAL.linenLight, 205, 0.02, 0.2, 0.2);
  washPoly(rectPts(cx + 2.5, bladeBotY + 5, 4, handleBotY - bladeBotY - 6), PAL.linenDark, 160);
  strokePoly(hPts, "2H", PAL.graphiteDark, 0.45);

  // 2. Flanking Mirror-Symmetric Spouted Cream Ladles at x = 532 and x = 668
  for (let side of [-1, 1]) {
    let lx = 600 + side * 68;
    let ly = 922;
    // Spout points inward toward x = 600!
    let spoutDir = -side;
    let ladleBowl = [];
    for (let a = 0; a < 360; a += 15) {
      let rx = 18;
      let ry = 16;
      // Pull spout slightly inward at angle 0 (for left) or 180 (for right)
      let px = lx + cos(a) * rx;
      let py = ly + sin(a) * ry;
      if ((spoutDir === 1 && (a <= 30 || a >= 330)) || (spoutDir === -1 && a >= 150 && a <= 210)) {
        px += spoutDir * 6 * pow(cos(a), 2);
      }
      ladleBowl.push([px, py]);
    }
    washPoly(ladleBowl.map(p => [p[0], p[1] + 3.5]), PAL.feltShadow, 135);

    // Stem extending down to y = 1018
    let stem = [
      [lx - 3, ly + 15],
      [lx + 3, ly + 15],
      [lx + 6.5, 1010],
      [lx, 1018],
      [lx - 6.5, 1010]
    ];
    washPoly(stem, PAL.pewterMid, 195);
    ruledLine(lx, ly + 15, lx, 1016, "2H", PAL.graphiteMid, 0.34);
    strokePoly(stem, "2H", PAL.graphiteDark, 0.44);

    fillPoly(ladleBowl, PAL.pewterMid, 205, 0.02, 0.22, 0.2);
    washPoly(ellipsePts(lx, ly - 2, 11, 9, 16), PAL.pewterDeep, 175);
    washPoly(ellipsePts(lx, ly + 4, 10, 5, 14), PAL.steelSpec, 200);
    strokePoly(ladleBowl, "2H", PAL.graphiteDark, 0.48);
  }
}

