function drawWingForkColonnades() {
  // 6 Dinner Forks on Left (x = 204..404) and 6 on Right (x = 796..996)
  let leftXs = [204, 244, 284, 324, 364, 404];
  let rightXs = [796, 836, 876, 916, 956, 996];

  for (let x of leftXs) {
    drawVerticalDinnerFork(x, 166, 1);
  }
  for (let x of rightXs) {
    drawVerticalDinnerFork(x, 166, -1);
  }
}

function drawVerticalDinnerFork(cx, topY, mirrorSide) {
  // Total fork length: topY (166) to 476 (310 px)
  // Tines: 166 .. 252 (86 px)
  // Head/throat: 252 .. 288
  // Neck in felt slot: 288 .. 334
  // Stem & Hanoverian handle: 334 .. 476
  let tineBaseY = topY + 86; // 252
  let throatBotY = topY + 122; // 288
  let handleBotY = topY + 310; // 476
  let halfW = 12.2; // Fork head half-width (24.4 px total)

  // 1. Cast shadow onto boxwood-green felt
  // Shadow of the 4 individual tines
  let tineCenters = [-9.6, -3.2, 3.2, 9.6];
  for (let tc of tineCenters) {
    let tx = cx + tc;
    washPoly([
      [tx - 0.6, topY + 3],
      [tx + 0.6, topY + 3],
      [tx + 1.8, tineBaseY + 3],
      [tx - 1.8, tineBaseY + 3]
    ], PAL.feltShadow, 145);
  }
  // Shadow of fork head and handle
  washPoly([
    [cx - halfW - 1, tineBaseY + 3],
    [cx + halfW + 1, tineBaseY + 3],
    [cx + 4.5, throatBotY + 4],
    [cx + 9.5, handleBotY - 12],
    [cx, handleBotY + 4],
    [cx - 9.5, handleBotY - 12],
    [cx - 4.5, throatBotY + 4]
  ], PAL.feltShadow, 135);

  // 2. Fork Head, Neck & Handle Silhouette
  let bodyPts = [
    [cx - halfW, tineBaseY],
    [cx + halfW, tineBaseY],
    [cx + halfW - 1, tineBaseY + 14],
    [cx + 4.0, throatBotY],
    [cx + 3.8, throatBotY + 42],
    [cx + 8.6, handleBotY - 15],
    [cx + 6.0, handleBotY - 4],
    [cx, handleBotY],
    [cx - 6.0, handleBotY - 4],
    [cx - 8.6, handleBotY - 15],
    [cx - 3.8, throatBotY + 42],
    [cx - 4.0, throatBotY],
    [cx - halfW + 1, tineBaseY + 14]
  ];
  fillPoly(bodyPts, PAL.pewterMid, 200, 0.02, 0.22, 0.2);

  // Handle longitudinal bevel planes (mirror-symmetric across x = 600)
  let lightSide = -mirrorSide; // Inward bevel catches bright specular light
  let lightFacet = [
    [cx, throatBotY],
    [cx + lightSide * 3.8, throatBotY],
    [cx + lightSide * 3.8, throatBotY + 42],
    [cx + lightSide * 8.6, handleBotY - 15],
    [cx + lightSide * 6.0, handleBotY - 4],
    [cx, handleBotY]
  ];
  let shadeFacet = [
    [cx, throatBotY],
    [cx - lightSide * 3.8, throatBotY],
    [cx - lightSide * 3.8, throatBotY + 42],
    [cx - lightSide * 8.6, handleBotY - 15],
    [cx - lightSide * 6.0, handleBotY - 4],
    [cx, handleBotY]
  ];
  washPoly(lightFacet, PAL.pewterLight, 185);
  washPoly(shadeFacet, PAL.pewterDark, 145);

  // Dark steel reflection band across the concave fork bridge (y: 254..274)
  washPoly([
    [cx - halfW + 2, tineBaseY + 3],
    [cx + halfW - 2, tineBaseY + 3],
    [cx + 6.5, tineBaseY + 21],
    [cx - 6.5, tineBaseY + 21]
  ], PAL.pewterDeep, 185);

  // Subtle green felt reflection along the curved shoulders of the fork throat
  washPoly([
    [cx - halfW + 1.5, tineBaseY + 12],
    [cx - 4.2, throatBotY - 2],
    [cx - 6.2, throatBotY - 4]
  ], PAL.steelGreen, 130);
  washPoly([
    [cx + halfW - 1.5, tineBaseY + 12],
    [cx + 4.2, throatBotY - 2],
    [cx + 6.2, throatBotY - 4]
  ], PAL.steelGreen, 130);

  // Bright specular highlight band across the bridge root & down handle spine
  ruledLine(cx - halfW + 2.5, tineBaseY + 2, cx + halfW - 2.5, tineBaseY + 2, "cpencil", PAL.steelSpec, 0.65);
  ruledLine(cx + lightSide * 0.7, throatBotY, cx + lightSide * 0.7, handleBotY - 2, "cpencil", PAL.steelSpec, 0.55);
  ruledLine(cx, throatBotY - 4, cx, handleBotY - 1, "2H", PAL.graphiteMid, 0.36);

  strokePoly(bodyPts, "2H", PAL.graphiteDark, 0.46);

  // 3. The 4 Individual Fork Tines (each throwing a precise steel-grey reflection)
  for (let i = 0; i < 4; i++) {
    let tc = tineCenters[i];
    // Slight inward taper toward tip
    let tipX = cx + tc * 0.9;
    let baseX = cx + tc;
    let baseHalfW = 1.95;

    // Bright bevel half of tine
    let tineLight = [
      [tipX, topY],
      [baseX + lightSide * baseHalfW, tineBaseY + 1],
      [baseX, tineBaseY + 1]
    ];
    // Steel-grey reflection bevel half of tine
    let tineSteel = [
      [tipX, topY],
      [baseX, tineBaseY + 1],
      [baseX - lightSide * baseHalfW, tineBaseY + 1]
    ];
    washPoly(tineLight, PAL.steelSpec, 225);
    washPoly(tineSteel, PAL.pewterDeep, 195);

    // Specular glint line along bright edge
    ruledLine(tipX, topY + 2, baseX + lightSide * 1.1, tineBaseY, "cpencil", PAL.steelSpec, 0.45);

    // Crisp graphite outline of tine & arched crotch between tines
    let tineOutline = [
      [baseX - baseHalfW, tineBaseY + 1],
      [tipX - 0.35, topY],
      [tipX + 0.35, topY],
      [baseX + baseHalfW, tineBaseY + 1]
    ];
    strokePoly(tineOutline, "2H", PAL.graphiteDark, 0.38, 0, false);
  }
}

