function drawMiddleHorizontalForks() {
  // Compartment y: 536..680
  // 2 horizontal 3-tined pastry forks on Left (pointing right toward x = 600)
  // and 2 on Right (pointing left toward x = 600) at y = 584 and y = 632
  for (let fy of [584, 632]) {
    drawHorizontalPastryFork(188, 420, fy, 1);   // Left wing, pointing right (+1)
    drawHorizontalPastryFork(1012, 780, fy, -1); // Right wing, pointing left (-1)
  }
}

function drawHorizontalPastryFork(handleEndX, tineTipX, cy, dir) {
  let tineBaseX = tineTipX - dir * 58;
  let throatX = tineBaseX - dir * 24;
  let halfH = 9.5;

  // Shadow
  washPoly([
    [handleEndX, cy - 6 + 3],
    [throatX, cy - 3.5 + 3],
    [tineBaseX, cy - halfH + 3],
    [tineTipX, cy - halfH + 4],
    [tineTipX, cy + halfH + 2],
    [tineBaseX, cy + halfH + 3],
    [throatX, cy + 3.5 + 3],
    [handleEndX, cy + 6 + 3]
  ], PAL.feltShadow, 130);

  // Body & handle
  let bodyPts = [
    [tineBaseX, cy - halfH],
    [tineBaseX - dir * 10, cy - halfH + 1],
    [throatX, cy - 3.2],
    [handleEndX + dir * 12, cy - 6.8],
    [handleEndX, cy],
    [handleEndX + dir * 12, cy + 6.8],
    [throatX, cy + 3.2],
    [tineBaseX - dir * 10, cy + halfH - 1],
    [tineBaseX, cy + halfH]
  ];
  fillPoly(bodyPts, PAL.pewterMid, 200, 0.02, 0.2, 0.2);

  // Top half of horizontal handle catches overhead light
  washPoly([
    [tineBaseX, cy],
    [throatX, cy - 3.2],
    [handleEndX + dir * 12, cy - 6.8],
    [handleEndX, cy]
  ], PAL.steelSpec, 175);

  // Dark steel throat band
  washPoly([
    [tineBaseX - dir * 2, cy - halfH + 1.5],
    [tineBaseX - dir * 14, cy - 4.5],
    [tineBaseX - dir * 14, cy + 4.5],
    [tineBaseX - dir * 2, cy + halfH - 1.5]
  ], PAL.pewterDeep, 180);

  ruledLine(handleEndX + dir * 2, cy, tineBaseX, cy, "2H", PAL.graphiteMid, 0.34);
  strokePoly(bodyPts, "2H", PAL.graphiteDark, 0.44);

  // 3 Horizontal Tines (outer top tine slightly wider like a pastry fork bevel!)
  let tOffsets = [-6.8, 0, 6.8];
  for (let tyOff of tOffsets) {
    let by = cy + tyOff;
    let ty = cy + tyOff * 0.92;
    let th = 1.9;
    washPoly([
      [tineBaseX, by - th],
      [tineTipX, ty],
      [tineBaseX, by]
    ], PAL.steelSpec, 220);
    washPoly([
      [tineBaseX, by],
      [tineTipX, ty],
      [tineBaseX, by + th]
    ], PAL.pewterDeep, 195);
    strokePoly([
      [tineBaseX, by - th],
      [tineTipX, ty - 0.3],
      [tineTipX, ty + 0.3],
      [tineBaseX, by + th]
    ], "2H", PAL.graphiteDark, 0.36, 0, false);
  }
}

