function drawWingKnifeColonnades() {
  // 6 Table Knives on Left (x = 204..404) and 6 on Right (x = 796..996)
  let leftXs = [204, 244, 284, 324, 364, 404];
  let rightXs = [796, 836, 876, 916, 956, 996];

  for (let x of leftXs) {
    drawVerticalTableKnife(x, 730, 1);  // Cutting bevel faces inward (+1, right)
  }
  for (let x of rightXs) {
    drawVerticalTableKnife(x, 730, -1); // Cutting bevel faces inward (-1, left)
  }
}

function drawVerticalTableKnife(cx, tipY, edgeDir) {
  // Total length: tipY (730) to 1012 (282 px)
  // Blade: 730 .. 894 (164 px)
  // Turned silver bolster: 894 .. 912 (18 px, resting in felt rack slot)
  // Faceted pale-linen bone handle: 912 .. 1006 (94 px) + pewter pommel cap (1006..1012)
  let bolsterTopY = tipY + 164; // 894
  let bolsterBotY = bolsterTopY + 18; // 912
  let handleBotY = tipY + 276; // 1006
  let pommelBotY = tipY + 282; // 1012

  let spineSide = -edgeDir; // Spine is on outward side, cutting edge bevel is on inward side
  let spineX = cx + spineSide * 9.0;
  let edgeX = cx + edgeDir * 9.5;
  let bevelLineX = cx + spineSide * 2.8; // Crisp longitudinal grind ridge

  // 1. Cast Shadow on Boxwood Felt
  let shPts = [
    [cx + spineSide * 2, tipY + 3],
    [edgeX + edgeDir * 1.5, tipY + 42],
    [edgeX + edgeDir * 1.5, bolsterTopY + 3],
    [cx + 8.5, pommelBotY + 3],
    [cx - 8.5, pommelBotY + 3],
    [spineX + spineSide * 1.5, bolsterTopY + 3],
    [spineX + spineSide * 1.5, tipY + 18]
  ];
  washPoly(shPts, PAL.feltShadow, 140);

  // 2. Knife Blade Contour
  let bladePts = [
    [cx + spineSide * 3.5, tipY],
    [cx + edgeDir * 2.0, tipY + 5],
    [cx + edgeDir * 6.8, tipY + 20],
    [edgeX, tipY + 42],
    [edgeX, bolsterTopY - 6],
    [cx + edgeDir * 6.5, bolsterTopY],
    [cx + spineSide * 6.5, bolsterTopY],
    [spineX, bolsterTopY - 4],
    [spineX, tipY + 14],
    [cx + spineSide * 6.8, tipY + 4]
  ];
  fillPoly(bladePts, PAL.pewterMid, 205, 0.02, 0.25, 0.2);

  // 3. The Two Precision Blade Planes:
  // Plane A: Narrow Spine Flat (satin pewter + bright spine highlight)
  let spinePlane = [
    [cx + spineSide * 3.5, tipY],
    [bevelLineX, tipY + 26],
    [bevelLineX, bolsterTopY],
    [cx + spineSide * 6.5, bolsterTopY],
    [spineX, bolsterTopY - 4],
    [spineX, tipY + 14],
    [cx + spineSide * 6.8, tipY + 4]
  ];
  washPoly(spinePlane, PAL.pewterLight, 185);

  // Plane B: Wide Hollow-Ground Cutting Bevel (deep steel-grey reflection!)
  let bevelPlane = [
    [cx + spineSide * 3.5, tipY],
    [cx + edgeDir * 2.0, tipY + 5],
    [cx + edgeDir * 6.8, tipY + 20],
    [edgeX, tipY + 42],
    [edgeX, bolsterTopY - 6],
    [cx + edgeDir * 6.5, bolsterTopY],
    [bevelLineX, bolsterTopY],
    [bevelLineX, tipY + 26]
  ];
  washPoly(bevelPlane, PAL.pewterDeep, 185);

  // Diagonal overhead specular reflection bands across the steel-grey bevel
  let band1Y = tipY + 58;
  washPoly([
    [bevelLineX + edgeDir * 0.5, band1Y],
    [edgeX - edgeDir * 0.8, band1Y + 14],
    [edgeX - edgeDir * 0.8, band1Y + 34],
    [bevelLineX + edgeDir * 0.5, band1Y + 20]
  ], PAL.pewterLight, 175);

  let band2Y = tipY + 112;
  washPoly([
    [bevelLineX + edgeDir * 0.5, band2Y],
    [edgeX - edgeDir * 0.8, band2Y + 12],
    [edgeX - edgeDir * 0.8, band2Y + 22],
    [bevelLineX + edgeDir * 0.5, band2Y + 10]
  ], PAL.steelSpec, 195);

  // Subtle green felt reflection along the lower plunge line near bolster
  washPoly([
    [bevelLineX, bolsterTopY - 28],
    [edgeX - edgeDir * 1.5, bolsterTopY - 22],
    [cx + edgeDir * 6.5, bolsterTopY],
    [bevelLineX, bolsterTopY]
  ], PAL.steelGreen, 115);

  // Razor-sharp specular highlight along the honed cutting edge & bevel ridge
  ruledLine(bevelLineX, tipY + 26, bevelLineX, bolsterTopY, "cpencil", PAL.steelSpec, 0.55);
  ruledLine(bevelLineX + edgeDir * 0.6, tipY + 24, bevelLineX + edgeDir * 0.6, bolsterTopY, "2H", PAL.graphiteDark, 0.36);
  ruledLine(edgeX - edgeDir * 0.5, tipY + 42, edgeX - edgeDir * 0.5, bolsterTopY - 6, "cpencil", PAL.steelSpec, 0.6);

  strokePoly(bladePts, "2H", PAL.graphiteDark, 0.48);

  // 4. Turned Silver Bolster / Ferrule (y: 894..912)
  let bolsterPts = chamferRectPts(cx - 7.5, bolsterTopY, 15, 18, 3);
  fillPoly(bolsterPts, PAL.pewterMid, 210, 0.01, 0.2, 0.2);
  washPoly(rectPts(cx - 6.5, bolsterTopY + 3, 13, 4), PAL.steelSpec, 215);
  washPoly(rectPts(cx - 6.5, bolsterTopY + 9, 13, 5), PAL.pewterDeep, 185);
  ruledLine(cx - 7, bolsterTopY + 7, cx + 7, bolsterTopY + 7, "2H", PAL.graphiteMid, 0.35);
  ruledLine(cx - 7, bolsterTopY + 14, cx + 7, bolsterTopY + 14, "2H", PAL.graphiteMid, 0.35);
  strokePoly(bolsterPts, "2H", PAL.graphiteDark, 0.46);

  // 5. Three-Faceted Pale-Linen / Bone Handle (y: 912..1006)
  let hw = 7.6; // Half-width (15.2 px total)
  let handlePts = [
    [cx - hw + 0.8, bolsterBotY],
    [cx + hw - 0.8, bolsterBotY],
    [cx + hw, handleBotY],
    [cx - hw, handleBotY]
  ];
  fillPoly(handlePts, PAL.linenLight, 210, 0.02, 0.25, 0.2);

  // Left chamfer, center flat, right chamfer
  let chamferW = 4.2;
  // Outward chamfer (lightest linen)
  washPoly([
    [cx + spineSide * (hw - 0.8), bolsterBotY],
    [cx + spineSide * (hw - chamferW), bolsterBotY],
    [cx + spineSide * (hw - chamferW), handleBotY],
    [cx + spineSide * hw, handleBotY]
  ], PAL.steelSpec, 150);

  // Inward chamfer (shaded warm linen)
  washPoly([
    [cx + edgeDir * (hw - chamferW), bolsterBotY],
    [cx + edgeDir * (hw - 0.8), bolsterBotY],
    [cx + edgeDir * hw, handleBotY],
    [cx + edgeDir * (hw - chamferW), handleBotY]
  ], PAL.linenDark, 175);

  // Ruled chamfer lines down the bone handle
  ruledLine(cx - hw + chamferW, bolsterBotY, cx - hw + chamferW, handleBotY, "2H", PAL.woodEdge, 0.34);
  ruledLine(cx + hw - chamferW, bolsterBotY, cx + hw - chamferW, handleBotY, "2H", PAL.woodEdge, 0.34);

  // Two tiny silver tang pins on the handle centerline
  for (let py of [bolsterBotY + 26, bolsterBotY + 66]) {
    washPoly(ellipsePts(cx, py, 1.8, 1.8, 8), PAL.pewterDark, 200);
    resetBrushState();
    brush.set("2H", PAL.graphiteDark, 0.32);
    brush.circle(cx, py, 1.8, 0.02);
  }

  strokePoly(handlePts, "2H", PAL.graphiteDark, 0.46);

  // 6. Pewter Pommel End-Cap (y: 1006..1012)
  let pommelPts = [
    [cx - hw, handleBotY],
    [cx + hw, handleBotY],
    [cx + hw - 3, pommelBotY],
    [cx - hw + 3, pommelBotY]
  ];
  washPoly(pommelPts, PAL.pewterMid, 210);
  washPoly(rectPts(cx - 4, handleBotY + 1, 8, 3), PAL.steelSpec, 200);
  strokePoly(pommelPts, "2H", PAL.graphiteDark, 0.45);
}

