// ============================================================================
// CORE DRAWING HELPERS (Guaranteed safe brush state)
// ============================================================================

function strokeLine(x1, y1, x2, y2, bName = "rotring", col = PAL.ink, w = 0.35) {
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.set(bName, col, w);
  brush.line(x1, y1, x2, y2);
}

function strokeSpline(pts, curv = 0.5, bName = "rotring", col = PAL.ink, w = 0.35) {
  if (pts.length < 2) return;
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.set(bName, col, w);
  brush.spline(pts, curv);
}

function drawPoly(pts, opts = {}) {
  const {
    fillCol = null,
    fillAlpha = 140,
    washCol = null,
    washAlpha = 210,
    bleed = 0.04,
    tex = 0.25,
    border = 0.2,
    hatchDist = null,
    hatchAngle = 45,
    hatchCol = PAL.inkSoft,
    hatchBrush = "2H",
    hatchWeight = 0.25,
    hatchRand = 0.02,
    strokeCol = PAL.ink,
    strokeBrush = "rotring",
    strokeW = 0.35
  } = opts;

  if (washCol) {
    brush.noFill();
    brush.wash(washCol, washAlpha);
  } else if (fillCol) {
    brush.noWash();
    brush.fill(fillCol, fillAlpha);
    brush.fillBleed(bleed, "in");
    brush.fillTexture(tex, border);
  } else {
    brush.noFill();
    brush.noWash();
  }

  if (hatchDist !== null) {
    brush.hatchStyle(hatchBrush, hatchCol, hatchWeight);
    brush.hatch(hatchDist, hatchAngle, { rand: hatchRand });
  } else {
    brush.noHatch();
  }

  if (strokeCol) {
    brush.set(strokeBrush, strokeCol, strokeW);
  } else {
    brush.noStroke();
  }

  brush.beginShape(0);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);

  brush.noFill();
  brush.noWash();
  brush.noHatch();
}

// Bilinear interpolation on a 4-point quad [TL, TR, BR, BL]
function quadPt(q, u, v) {
  const xTop = lerp(q[0][0], q[1][0], u);
  const yTop = lerp(q[0][1], q[1][1], u);
  const xBot = lerp(q[3][0], q[2][0], u);
  const yBot = lerp(q[3][1], q[2][1], u);
  return [lerp(xTop, xBot, v), lerp(yTop, yBot, v)];
}

function subQuad(q, u0, v0, u1, v1) {
  return [
    quadPt(q, u0, v0),
    quadPt(q, u1, v0),
    quadPt(q, u1, v1),
    quadPt(q, u0, v1)
  ];
}

