function drawTchiCloud(cx, cy, sc, flip) {
  const dir = flip ? -1 : 1;
  // Soft ivory wash puff
  const puffs = [
    [0, 0, 16], [18 * dir, -5, 13], [-18 * dir, 3, 12],
    [35 * dir, 2, 10], [-36 * dir, 6, 9], [52 * dir, 5, 7]
  ];
  brush.noStroke();
  brush.wash(PAL.ivory, 195);
  for (let p of puffs) {
    brush.circle(cx + p[0] * sc, cy + p[1] * sc, p[2] * sc, 0.08);
  }
  brush.noWash();

  // Intricate curling ribbon contours in lapis & gold
  for (let p of puffs) {
    const px = cx + p[0] * sc;
    const py = cy + p[1] * sc;
    const pr = p[2] * sc;
    brush.set("rotring", PAL.lapis, 0.3);
    brush.arc(px, py, pr, 180, 355);
    brush.set("rotring", PAL.goldLeaf, 0.25);
    brush.arc(px, py, pr * 0.72, 195, 340);
  }
  // Trailing tail
  const tail = [
    [cx + 45 * dir * sc, cy + 6 * sc],
    [cx + 75 * dir * sc, cy + 12 * sc],
    [cx + 98 * dir * sc, cy + 3 * sc],
    [cx + 115 * dir * sc, cy + 9 * sc]
  ];
  strokeSpline(tail, 0.6, "rotring", PAL.lapis, 0.28);
}

