function drawPersianDome(cx, baseY, rx, h) {
  // Drum (cylindrical base with Kufic tile frieze)
  const drumH = 24;
  drawPoly([
    [cx - rx * 0.88, baseY - drumH],
    [cx + rx * 0.88, baseY - drumH],
    [cx + rx * 0.88, baseY + 15],
    [cx - rx * 0.88, baseY + 15]
  ], {
    washCol: PAL.lapis,
    washAlpha: 220,
    strokeCol: PAL.ink,
    strokeW: 0.35
  });

  // Kufic geometric gold & ivory band on drum
  for (let x = cx - rx * 0.82; x < cx + rx * 0.78; x += 7) {
    drawPoly([
      [x, baseY - drumH + 4],
      [x + 4.5, baseY - drumH + 4],
      [x + 4.5, baseY - 4],
      [x, baseY - 4]
    ], {
      washCol: ((Math.round(x) % 2 === 0) ? PAL.ivory : PAL.saffron),
      washAlpha: 210,
      strokeCol: PAL.ink,
      strokeW: 0.2
    });
  }

  // Bulbous pointed dome profile
  const domePts = [];
  const steps = 28;
  for (let i = 0; i <= steps; i++) {
    const t = i / steps; // 0 (left base) to 1 (right base)
    const ang = t * 180;
    // Pointed ogee dome math
    let u = (t - 0.5) * 2; // -1 to 1
    let bulge = sin(acos(constrain(u, -1, 1)));
    let pinch = 1 - pow(abs(u), 1.35);
    let x = cx + u * rx * (1 + 0.12 * sin( (1 - abs(u)) * 180 ));
    let y = (baseY - drumH) - (bulge * 0.65 + pinch * 0.35) * h;
    domePts.push([x, y]);
  }

  drawPoly(domePts, {
    fillCol: PAL.turquoise,
    fillAlpha: 210,
    bleed: 0.04,
    tex: 0.3,
    hatchDist: 3.5,
    hatchAngle: 85,
    hatchCol: PAL.lapisDeep,
    hatchBrush: "2H",
    hatchWeight: 0.25,
    strokeCol: PAL.ink,
    strokeW: 0.4
  });

  // Spiral chevron arabesque tile pattern on dome
  for (let ring = 0.18; ring < 0.9; ring += 0.16) {
    const ry = (baseY - drumH) - ring * h;
    const halfW = rx * sin(acos(constrain(ring * 1.8 - 0.75, -0.98, 0.98))) * 0.95;
    if (halfW > 6) {
      let zigPts = [];
      let nZ = Math.max(4, Math.floor(halfW / 4.5));
      for (let k = 0; k <= nZ; k++) {
        let zx = lerp(cx - halfW, cx + halfW, k / nZ);
        let zy = ry + ((k % 2 === 0) ? -3.5 : 3.5);
        zigPts.push([zx, zy]);
      }
      strokeSpline(zigPts, 0.1, "rotring", PAL.ivory, 0.28);
      for (let k = 0; k <= nZ; k += 2) {
        let zx = lerp(cx - halfW, cx + halfW, k / nZ);
        brush.noStroke();
        brush.wash((k % 4 === 0) ? PAL.saffron : PAL.lapisDeep, 220);
        brush.circle(zx, ry, 2.2);
      }
      brush.noWash();
    }
  }

  // Golden finial (Alam) at peak
  const peakY = (baseY - drumH) - h;
  strokeLine(cx, peakY, cx, peakY - 26, "rotring", PAL.ink, 0.4);
  for (let r of [[6, 3.8], [13, 2.8], [19, 2.0]]) {
    brush.noStroke();
    brush.wash(PAL.saffron, 240);
    brush.circle(cx, peakY - r[0], r[1]);
    brush.set("rotring", PAL.ink, 0.25);
    brush.circle(cx, peakY - r[0], r[1]);
  }
}

function drawBadgir(x, y, w, h, vents, wallCol) {
  // Tilted top cap
  const tilt = 7;
  drawPoly([
    [x, y],
    [x + w, y - tilt],
    [x + w, y + h],
    [x, y + h + tilt]
  ], {
    washCol: wallCol,
    washAlpha: 235,
    hatchDist: 4,
    hatchAngle: -8,
    hatchCol: PAL.sandBrick,
    hatchBrush: "2H",
    hatchWeight: 0.22,
    strokeCol: PAL.ink,
    strokeW: 0.35
  });

  // Side return wall for 3D isometric depth
  const sideW = 16;
  drawPoly([
    [x - sideW, y - 5],
    [x, y],
    [x, y + h + tilt],
    [x - sideW, y + h]
  ], {
    washCol: PAL.parchmentDark,
    washAlpha: 235,
    hatchDist: 3.5,
    hatchAngle: 18,
    hatchCol: PAL.inkSoft,
    hatchBrush: "2H",
    hatchWeight: 0.2,
    strokeCol: PAL.ink,
    strokeW: 0.35
  });

  // Deep lapis vertical wind-shaft slots
  const pad = 4;
  const slotW = (w - pad * (vents + 1)) / vents;
  for (let i = 0; i < vents; i++) {
    const sx = x + pad + i * (slotW + pad);
    const sy = lerp(y, y - tilt, (sx - x) / w) + 9;
    const sh = h - 18;
    drawPoly([
      [sx, sy + 3],
      [sx + slotW * 0.5, sy],
      [sx + slotW, sy + 3],
      [sx + slotW, sy + sh],
      [sx, sy + sh]
    ], {
      washCol: PAL.lapisDeep,
      washAlpha: 240,
      strokeCol: PAL.ink,
      strokeW: 0.28
    });
    // Wooden cross-baffles inside wind shaft
    strokeLine(sx, sy + sh * 0.35, sx + slotW, sy + sh * 0.35, "rotring", PAL.sandBrick, 0.25);
    strokeLine(sx, sy + sh * 0.7, sx + slotW, sy + sh * 0.7, "rotring", PAL.sandBrick, 0.25);
  }

  // Decorative turquoise & vermilion cornice band at top
  drawPoly([
    [x - sideW - 2, y - 8],
    [x, y - 3],
    [x + w + 2, y - tilt - 3],
    [x + w + 2, y - tilt + 2],
    [x, y + 2],
    [x - sideW - 2, y - 3]
  ], {
    washCol: PAL.lapisBright,
    washAlpha: 230,
    strokeCol: PAL.ink,
    strokeW: 0.3
  });
}

function drawCypress(cx, baseY, rx, h) {
  const pts = [];
  const n = 20;
  for (let i = 0; i <= n; i++) {
    const t = i / n;
    const y = baseY - t * h;
    const w = rx * sin(pow(t, 0.65) * 180) * (1 - 0.15 * t);
    pts.push([cx - w, y]);
  }
  for (let i = n; i >= 0; i--) {
    const t = i / n;
    const y = baseY - t * h;
    const w = rx * sin(pow(t, 0.65) * 180) * (1 - 0.15 * t);
    pts.push([cx + w, y]);
  }
  drawPoly(pts, {
    fillCol: PAL.malachiteDeep,
    fillAlpha: 225,
    bleed: 0.03,
    hatchDist: 2.5,
    hatchAngle: 65,
    hatchCol: PAL.lapisDeep,
    hatchBrush: "2H",
    hatchWeight: 0.25,
    strokeCol: PAL.ink,
    strokeW: 0.3
  });
  // Delicate foliage scales in malachite & gold-green
  for (let i = 2; i < n - 1; i += 2) {
    const t = i / n;
    const y = baseY - t * h;
    const w = rx * sin(pow(t, 0.65) * 180) * 0.65;
    brush.set("rotring", PAL.malachiteLight, 0.22);
    brush.arc(cx - w * 0.3, y, w * 0.5, 200, 340);
    brush.arc(cx + w * 0.3, y + 2, w * 0.5, 200, 340);
  }
}

