// ============================================================================
// TERRACE ARCHITECTURE ENGINE
// ============================================================================

function renderTerraceComplex(t) {
  const { x, y, w, d, wallH, skewX, skewY } = t;

  // Compute the 4 corners of the tilted rooftop floor quad: [TL, TR, BR, BL]
  // Front edge is BL -> BR at y + d; Back edge is TL -> TR shifted by skewX, skewY
  const BL = [x, y + d];
  const BR = [x + w, y + d + skewY];
  const TL = [x + skewX, y];
  const TR = [x + w + skewX, y + skewY];
  const floorQuad = [TL, TR, BR, BL];

  // 1. SIDE RETURN WALL (Left if skewX < 0, Right if skewX > 0)
  if (skewX > 0) {
    const rightSideWall = [
      BR,
      TR,
      [TR[0], TR[1] + wallH],
      [BR[0], BR[1] + wallH]
    ];
    drawFacadeWall(rightSideWall, t.sideCol, t, true);
  } else {
    const leftSideWall = [
      TL,
      BL,
      [BL[0], BL[1] + wallH],
      [TL[0], TL[1] + wallH]
    ];
    drawFacadeWall(leftSideWall, t.sideCol, t, true);
  }

  // 2. FRONT VERTICAL FACADE WALL (below front edge BL -> BR)
  const frontWall = [
    BL,
    BR,
    [BR[0], BR[1] + wallH],
    [BL[0], BL[1] + wallH]
  ];
  drawFacadeWall(frontWall, t.wallCol, t, false);

  // 3. TILTED ROOFTOP TERRACE FLOOR (Full flat-lit overhead view)
  drawTerraceFloor(floorQuad, t);

  // 4. BACK & SIDE PARAPET WALLS (Surrounding the roof)
  drawBackParapet(TL, TR, t);
  if (skewX > 0) {
    drawSideParapet(TL, BL, t);
  } else {
    drawSideParapet(BR, TR, t);
  }

  // 5. ROOFTOP NARRATIVE PROPS (Stairwells, tanks, coolers, laundry, figures, dishes)
  drawTerraceProps(floorQuad, frontWall, t);

  // 6. FRONT PARAPET & DRAPED CARPETS (Drawn after floor props so front parapet & hanging rugs overlap)
  drawFrontParapet(BL, BR, t);
  drawDrapedWallCarpets(frontWall, floorQuad, t);
}

function drawFacadeWall(wallQ, col, t, isSide) {
  // Base masonry wash + brick course hatching
  drawPoly(wallQ, {
    washCol: col,
    washAlpha: 245,
    hatchDist: 5.5,
    hatchAngle: isSide ? (t.skewX > 0 ? -25 : 25) : -3,
    hatchCol: PAL.sandBrick,
    hatchBrush: "2H",
    hatchWeight: 0.24,
    strokeCol: PAL.ink,
    strokeW: 0.4
  });

  // Individual weathered bricks scattered on wall
  for (let i = 0; i < (isSide ? 10 : 24); i++) {
    const u = random(0.08, 0.88);
    const v = random(0.18, 0.85);
    const bq = subQuad(wallQ, u, v, u + (isSide ? 0.12 : 0.055), v + 0.045);
    drawPoly(bq, {
      washCol: (i % 3 === 0) ? PAL.sandBrick : PAL.parchmentDark,
      washAlpha: 180,
      strokeCol: PAL.inkSoft,
      strokeW: 0.2
    });
  }

  // Decorative Glazed Tile Frieze Band (Kashi) near top of facade
  const friezeQ = subQuad(wallQ, 0.0, 0.03, 1.0, 0.13);
  drawPoly(friezeQ, {
    washCol: t.friezeCol,
    washAlpha: 235,
    strokeCol: PAL.ink,
    strokeW: 0.32
  });

  // Geometric Kufic/Rosette motifs inside frieze band
  const nMotifs = isSide ? 6 : Math.floor(t.w / 18);
  for (let m = 0; m < nMotifs; m++) {
    const u0 = (m + 0.2) / nMotifs;
    const u1 = (m + 0.8) / nMotifs;
    const mq = subQuad(wallQ, u0, 0.05, u1, 0.11);
    const mCol = (m % 3 === 0) ? PAL.saffron : (m % 2 === 0 ? PAL.ivory : PAL.lapisDeep);
    drawPoly(mq, {
      washCol: mCol,
      washAlpha: 220,
      strokeCol: PAL.ink,
      strokeW: 0.2
    });
  }

  // Pointed Persian Arches / Orosi Lattice Windows on Front Facade
  if (!isSide && t.windows > 0) {
    const nW = t.windows;
    for (let i = 0; i < nW; i++) {
      const uCenter = (i + 0.5) / nW;
      const halfU = 0.26 / nW;
      const wq = subQuad(wallQ, uCenter - halfU, 0.22, uCenter + halfU, 0.78);
      drawOrosiWindow(wq, i % 2 === 0);
    }
  } else if (isSide) {
    // Small arched niche on side wall
    const nq = subQuad(wallQ, 0.32, 0.26, 0.68, 0.68);
    drawOrosiWindow(nq, false);
  }
}

function drawOrosiWindow(wq, hasShutters) {
  // Outer rectangular tiled spandrel frame
  drawPoly(wq, {
    washCol: PAL.lapis,
    washAlpha: 230,
    strokeCol: PAL.ink,
    strokeW: 0.32
  });

  // Pointed arch inset
  const pBL = quadPt(wq, 0.08, 0.96);
  const pBR = quadPt(wq, 0.92, 0.96);
  const pML = quadPt(wq, 0.08, 0.38);
  const pMR = quadPt(wq, 0.92, 0.38);
  const pSL = quadPt(wq, 0.24, 0.15);
  const pSR = quadPt(wq, 0.76, 0.15);
  const pPeak = quadPt(wq, 0.5, 0.05);

  const archPts = [pBL, pML, pSL, pPeak, pSR, pMR, pBR];
  drawPoly(archPts, {
    washCol: PAL.lapisDeep,
    washAlpha: 245,
    hatchDist: 3.2,
    hatchAngle: 45,
    hatchCol: PAL.sandBrick,
    hatchBrush: "rotring",
    hatchWeight: 0.22,
    strokeCol: PAL.ivory,
    strokeW: 0.28
  });

  // Cross-hatch wooden mashrabiya lattice
  drawPoly(archPts, {
    hatchDist: 3.2,
    hatchAngle: -45,
    hatchCol: PAL.sandBrick,
    hatchBrush: "rotring",
    hatchWeight: 0.22,
    strokeCol: PAL.ink,
    strokeW: 0.32
  });

  // Stained glass jewel specks inside the Orosi window (vermilion, saffron, malachite)
  for (let k = 0; k < 5; k++) {
    const gu = random(0.25, 0.75);
    const gv = random(0.28, 0.82);
    const gp = quadPt(wq, gu, gv);
    const gCol = (k % 3 === 0) ? PAL.vermilionBright : (k % 2 === 0 ? PAL.saffron : PAL.malachiteLight);
    brush.noStroke();
    brush.wash(gCol, 230);
    brush.circle(gp[0], gp[1], 2.2);
  }
  brush.noWash();
}

function drawTerraceFloor(floorQ, t) {
  // Base watercolor wash + primary geometric hatch
  let hDist = 6, hAng = 25, hCol = PAL.sandBrick;
  if (t.tileStyle === "lapis_hex") {
    hDist = 5; hAng = 60; hCol = PAL.cobalt;
  } else if (t.tileStyle === "star_cross_lapis") {
    hDist = 6.5; hAng = 35; hCol = PAL.lapis;
  } else if (t.tileStyle === "brick_herring") {
    hDist = 4.5; hAng = -15; hCol = PAL.sandBrick;
  }

  drawPoly(floorQ, {
    fillCol: t.floorCol,
    fillAlpha: 195,
    bleed: 0.03,
    tex: 0.3,
    border: 0.25,
    hatchDist: hDist,
    hatchAngle: hAng,
    hatchCol: hCol,
    hatchBrush: "2H",
    hatchWeight: 0.24,
    strokeCol: PAL.ink,
    strokeW: 0.4
  });

  // Cross-grid lines for tiled courtyard look
  const uSteps = Math.floor(t.w / 22);
  const vSteps = Math.floor(t.d / 16);
  for (let i = 1; i < uSteps; i++) {
    const u = i / uSteps;
    const p0 = quadPt(floorQ, u, 0);
    const p1 = quadPt(floorQ, u, 1);
    strokeLine(p0[0], p0[1], p1[0], p1[1], "2H", hCol, 0.22);
  }
  for (let j = 1; j < vSteps; j++) {
    const v = j / vSteps;
    const p0 = quadPt(floorQ, 0, v);
    const p1 = quadPt(floorQ, 1, v);
    strokeLine(p0[0], p0[1], p1[0], p1[1], "2H", hCol, 0.22);
  }

  // Accent glazed turquoise/lapis star tiles at grid intersections for ornate floors
  if (t.tileStyle === "star_cross_lapis" || t.tileStyle === "lapis_hex") {
    for (let i = 1; i < uSteps; i += 2) {
      for (let j = 1; j < vSteps; j += 2) {
        const pt = quadPt(floorQ, i / uSteps, j / vSteps);
        brush.noStroke();
        brush.wash((i + j) % 4 === 0 ? PAL.saffron : PAL.lapis, 210);
        brush.circle(pt[0], pt[1], 2.5);
      }
    }
    brush.noWash();
  }
}

function drawBackParapet(TL, TR, t) {
  const ph = 18;
  drawParapetSegment(TL, TR, ph, t.parapet, t.wallCol, t.friezeCol);
}

function drawSideParapet(P0, P1, t) {
  const ph = 18;
  drawParapetSegment(P0, P1, ph, "solid_tile", t.sideCol, t.friezeCol);
}

function drawFrontParapet(BL, BR, t) {
  const ph = 16;
  drawParapetSegment(BL, BR, ph, t.parapet, t.wallCol, t.friezeCol);
}

function drawParapetSegment(A, B, ph, style, wallCol, copingCol) {
  const distAB = dist(A[0], A[1], B[0], B[1]);
  if ( style === "crenellated" ) {
    // Base low wall
    const baseH = ph * 0.48;
    drawPoly([
      [A[0], A[1] - baseH],
      [B[0], B[1] - baseH],
      B,
      A
    ], {
      washCol: wallCol,
      washAlpha: 240,
      strokeCol: PAL.ink,
      strokeW: 0.32
    });
    // Stepped Persian merlons (crenellations)
    const nM = Math.max(4, Math.floor(distAB / 24));
    for (let i = 0; i < nM; i++) {
      const u0 = (i + 0.1) / nM;
      const u1 = (i + 0.9) / nM;
      const uM0 = (i + 0.28) / nM;
      const uM1 = (i + 0.72) / nM;
      const x0 = lerp(A[0], B[0], u0), y0 = lerp(A[1], B[1], u0) - baseH;
      const x1 = lerp(A[0], B[0], u1), y1 = lerp(A[1], B[1], u1) - baseH;
      const xm0 = lerp(A[0], B[0], uM0), ym0 = lerp(A[1], B[1], uM0) - ph;
      const xm1 = lerp(A[0], B[0], uM1), ym1 = lerp(A[1], B[1], uM1) - ph;

      drawPoly([
        [x0, y0],
        [x0, y0 - ph * 0.25],
        [xm0, ym0 + ph * 0.2],
        [xm0, ym0],
        [xm1, ym1],
        [xm1, ym1 + ph * 0.2],
        [x1, y1 - ph * 0.25],
        [x1, y1]
      ], {
        washCol: wallCol,
        washAlpha: 245,
        strokeCol: PAL.ink,
        strokeW: 0.3
      });
      // Tiny turquoise tile center inside merlon
      brush.noStroke();
      brush.wash(copingCol, 220);
      brush.circle((xm0 + xm1) * 0.5, (ym0 + y0) * 0.5, 2.0);
    }
    brush.noWash();
  } else if (style === "jali_screen") {
    // Pierced brick lattice parapet
    const pq = [
      [A[0], A[1] - ph],
      [B[0], B[1] - ph],
      B,
      A
    ];
    drawPoly(pq, {
      washCol: wallCol,
      washAlpha: 235,
      hatchDist: 4,
      hatchAngle: 45,
      hatchCol: PAL.lapisDeep,
      hatchBrush: "rotring",
      hatchWeight: 0.25,
      strokeCol: PAL.ink,
      strokeW: 0.35
    });
    drawPoly(pq, {
      hatchDist: 4,
      hatchAngle: -45,
      hatchCol: PAL.lapisDeep,
      hatchBrush: "rotring",
      hatchWeight: 0.25,
      strokeCol: PAL.ink,
      strokeW: 0.35
    });
    // Glazed coping rail along top
    drawPoly([
      [A[0], A[1] - ph - 3],
      [B[0], B[1] - ph - 3],
      [B[0], B[1] - ph],
      [A[0], A[1] - ph]
    ], {
      washCol: copingCol,
      washAlpha: 240,
      strokeCol: PAL.ink,
      strokeW: 0.3
    });
  } else {
    // Solid parapet with glazed turquoise/lapis coping tiles
    drawPoly([
      [A[0], A[1] - ph],
      [B[0], B[1] - ph],
      B,
      A
    ], {
      washCol: wallCol,
      washAlpha: 240,
      hatchDist: 5,
      hatchAngle: 0,
      hatchCol: PAL.sandBrick,
      hatchBrush: "2H",
      hatchWeight: 0.2,
      strokeCol: PAL.ink,
      strokeW: 0.35
    });
    drawPoly([
      [A[0], A[1] - ph - 3.5],
      [B[0], B[1] - ph - 3.5],
      [B[0], B[1] - ph],
      [A[0], A[1] - ph]
    ], {
      washCol: copingCol,
      washAlpha: 240,
      strokeCol: PAL.ink,
      strokeW: 0.3
    });
  }
}

