function drawTerraceProps(floorQ, frontWall, t) {
  for (let prop of t.props) {
    if (prop === "dishes_cluster") {
      const p1 = quadPt(floorQ, 0.22, 0.25);
      const p2 = quadPt(floorQ, 0.42, 0.22);
      const p3 = quadPt(floorQ, 0.62, 0.28);
      drawSatelliteDish(p1[0], p1[1], 22, 1, t.id);
      drawSatelliteDish(p2[0], p2[1], 26, 1, t.id);
      drawSatelliteDish(p3[0], p3[1], 19, -1, t.id);
    }
    else if (prop === "dishes_pair") {
      const p1 = quadPt(floorQ, 0.28, 0.30);
      const p2 = quadPt(floorQ, 0.55, 0.26);
      drawSatelliteDish(p1[0], p1[1], 24, -1, t.id);
      drawSatelliteDish(p2[0], p2[1], 21, -1, t.id);
