      drawSatelliteDish(p2[0], p2[1], 27, 1, t.id);
    }
    else if (prop === "dishes_fg_right") {
      const p1 = quadPt(floorQ, 0.68, 0.72);
      const p2 = quadPt(floorQ, 0.85, 0.62);
