// --- 1. PERSIAN CARPETS (Flat on Floor & Draped Over Parapets) ---

function drawPersianCarpetQuad(cq, fieldCol, medCol, borderCol, hasFringes) {
  // Outer guard border
  drawPoly(cq, {
    fillCol: borderCol,
    fillAlpha: 235,
    bleed: 0.02,
    tex: 0.35,
    strokeCol: PAL.ink,
    strokeW: 0.35
  });

  // Main Herati border band
  const bq = subQuad(cq, 0.07, 0.07, 0.93, 0.93);
  drawPoly(bq, {
    washCol: medCol,
    washAlpha: 240,
    strokeCol: PAL.ivory,
    strokeW: 0.25
  });

  // Inner field
  const fq = subQuad(cq, 0.16, 0.16, 0.84, 0.84);
  drawPoly(fq, {
    fillCol: fieldCol,
    fillAlpha: 240,
    bleed: 0.02,
    tex: 0.4,
    hatchDist: 2.8,
    hatchAngle: 15,
    hatchCol: PAL.carmine,
    hatchBrush: "2H",
    hatchWeight: 0.2,
    strokeCol: PAL.ivory,
    strokeW: 0.28
  });

  // Corner spandrels (Lachak)
  const spSize = 0.16;
  const corners = [
    [quadPt(fq, 0, 0), quadPt(fq, spSize, 0), quadPt(fq, 0, spSize)],
    [quadPt(fq, 1, 0), quadPt(fq, 1 - spSize, 0), quadPt(fq, 1, spSize)],
    [quadPt(fq, 1, 1), quadPt(fq, 1 - spSize, 1), quadPt(fq, 1, 1 - spSize)],
    [quadPt(fq, 0, 1), quadPt(fq, spSize, 1), quadPt(fq, 0, 1 - spSize)]
  ];
  for (let tri of corners) {
    drawPoly(tri, {
      washCol: borderCol,
      washAlpha: 235,
      strokeCol: PAL.ink,
      strokeW: 0.22
    });
  }

  // Central Star/Diamond Medallion (Toranj)
  const mPts = [
    quadPt(fq, 0.5, 0.18),
    quadPt(fq, 0.68, 0.35),
    quadPt(fq, 0.82, 0.5),
    quadPt(fq, 0.68, 0.65),
    quadPt(fq, 0.5, 0.82),
    quadPt(fq, 0.32, 0.65),
    quadPt(fq, 0.18, 0.5),
    quadPt(fq, 0.32, 0.35)
  ];
  drawPoly(mPts, {
    washCol: medCol,
    washAlpha: 245,
    strokeCol: PAL.saffronLight,
    strokeW: 0.3
  });

  // Inner rosette of medallion
  const mInner = [
    quadPt(fq, 0.5, 0.34),
    quadPt(fq, 0.66, 0.5),
    quadPt(fq, 0.5, 0.66),
    quadPt(fq, 0.34, 0.5)
  ];
  drawPoly(mInner, {
    washCol: borderCol,
    washAlpha: 245,
    strokeCol: PAL.ink,
    strokeW: 0.25
  });

  // Tiny floral knots along main border
  for (let t = 0.12; t <= 0.88; t += 0.11) {
    for (let p of [
      quadPt(cq, t, 0.115),
      quadPt(cq, t, 0.885),
      quadPt(cq, 0.115, t),
      quadPt(cq, 0.885, t)
    ]) {
      brush.noStroke();
      brush.wash((Math.round(t * 20) % 2 === 0) ? PAL.vermilionBright : PAL.ivory, 235);
      brush.circle(p[0], p[1], 1.8);
    }
  }
  brush.noWash();

  // Individual white warp fringes at ends
  if (hasFringes) {
    for (let s = 0.03; s <= 0.97; s += 0.045) {
      const pL = quadPt(cq, 0, s);
      const pR = quadPt(cq, 1, s);
      strokeLine(pL[0], pL[1], pL[0] - 6, pL[1] + 2, "rotring", PAL.ivory, 0.25);
      strokeLine(pR[0], pR[1], pR[0] + 6, pR[1] - 2, "rotring", PAL.ivory, 0.25);
    }
  }
}

function drawDrapedCarpet(frontWall, floorQ, u0, u1, vDrop, fieldCol, medCol, borderCol) {
  // Top lip folded over parapet
  const pBL = quadPt(frontWall, u0, 0);
  const pBR = quadPt(frontWall, u1, 0);
  const ph = 18;
  const topLip = [
    [pBL[0], pBL[1] - ph - 3],
    [pBR[0], pBR[1] - ph - 3],
    [pBR[0], pBR[1]],
    [pBL[0], pBL[1]]
  ];
  drawPoly(topLip, {
    washCol: fieldCol,
    washAlpha: 240,
    strokeCol: PAL.ink,
    strokeW: 0.32
  });

  // Main hanging vertical rug plane on the facade wall
  const hangQ = subQuad(frontWall, u0, 0.0, u1, vDrop);
  drawPersianCarpetQuad(hangQ, fieldCol, medCol, borderCol, false);

  // Crisp fold line at parapet top & bottom hanging warp fringes
  strokeLine(pBL[0], pBL[1] - ph, pBR[0], pBR[1] - ph, "rotring", PAL.ivory, 0.35);
  for (let u = u0 + 0.02; u <= u1 - 0.02; u += 0.025) {
    const pf = quadPt(frontWall, u, vDrop);
    strokeLine(pf[0], pf[1], pf[0], pf[1] + 7, "rotring", PAL.ivory, 0.26);
    strokeLine(pf[0] + 1, pf[1], pf[0] + 1, pf[1] + 6, "rotring", PAL.inkSoft, 0.18);
  }
}

// --- 2. SATELLITE DISHES (Parabolic Antennas with LNB & Coax) ---

function drawSatelliteDish(cx, cy, r, dir, seedStr) {
  // Galvanized steel mounting mast & base plate
  drawPoly([
    [cx - 8, cy + 2],
    [cx + 8, cy + 2],
    [cx + 10, cy + 6],
    [cx - 10, cy + 6]
  ], {
    washCol: PAL.steelDark,
    washAlpha: 240,
    strokeCol: PAL.ink,
    strokeW: 0.3
  });
  strokeLine(cx - 2, cy + 3, cx - 2, cy - r * 0.65, "rotring", PAL.ink, 0.5);
  strokeLine(cx + 2, cy + 3, cx + 2, cy - r * 0.65, "rotring", PAL.steelBlue, 0.4);
  // Diagonal brace strut
  strokeLine(cx - 6 * dir, cy + 3, cx, cy - r * 0.45, "rotring", PAL.ink, 0.35);

  // Dish center elevated above mount
  const dx = cx + 3 * dir;
  const dy = cy - r * 0.85;
  const rx = r * 0.68;
  const ry = r * 0.95;
  const tiltAng = -18 * dir;

  // Generate tilted elliptical dish points
  const dishPts = [];
  const backPts = [];
  const n = 24;
  for (let i = 0; i < n; i++) {
    const a = (i / n) * 360;
    const ex = cos(a) * rx;
    const ey = sin(a) * ry;
    const tx = ex * cos(tiltAng) - ey * sin(tiltAng);
    const ty = ex * sin(tiltAng) + ey * cos(tiltAng);
    dishPts.push([dx + tx, dy + ty]);
    backPts.push([dx + tx - 3.5 * dir, dy + ty + 1.5]);
  }

  // Back structural rim
  drawPoly(backPts, {
    washCol: PAL.steelBlue,
    washAlpha: 235,
    strokeCol: PAL.ink,
    strokeW: 0.3
  });

  // Concave dish face
  drawPoly(dishPts, {
    fillCol: PAL.steelLight,
    fillAlpha: 230,
    bleed: 0.02,
    tex: 0.25,
    hatchDist: 3.5,
    hatchAngle: 30,
    hatchCol: PAL.paleBlue,
    hatchBrush: "2H",
    hatchWeight: 0.2,
    strokeCol: PAL.ink,
    strokeW: 0.38
  });

  // Inner concentric stamped ring & radial ribs
  const innerPts = [];
  for (let i = 0; i < n; i++) {
    const a = (i / n) * 360;
    const ex = cos(a) * rx * 0.55;
    const ey = sin(a) * ry * 0.55;
    const tx = ex * cos(tiltAng) - ey * sin(tiltAng);
    const ty = ex * sin(tiltAng) + ey * cos(tiltAng);
    innerPts.push([dx + tx + 1.5 * dir, dy + ty]);
  }
  drawPoly(innerPts, {
    washCol: PAL.ivory,
    washAlpha: 140,
    strokeCol: PAL.steelBlue,
    strokeW: 0.22
  });

  // Center mounting boss & tiny vermilion stencil logo on dish face
  brush.noStroke();
  brush.wash(PAL.steelDark, 230);
  brush.circle(dx - 1 * dir, dy, 2.5);
  brush.wash(PAL.vermilion, 200);
  brush.circle(dx + 2 * dir, dy - ry * 0.38, 2.2);
  brush.noWash();

  // Tripod feedhorn struts converging to LNB receiver head
  const lnbX = dx + (rx * 0.95) * dir;
  const lnbY = dy - ry * 0.18;
  const strutAnchors = [
    dishPts[Math.floor(n * 0.22)],
    dishPts[Math.floor(n * 0.78)],
    [dx - rx * 0.25 * dir, dy + ry * 0.65]
  ];
  for (let sa of strutAnchors) {
    strokeLine(sa[0], sa[1], lnbX, lnbY, "rotring", PAL.ink, 0.28);
  }

  // LNB feedhorn head (ivory & vermilion cap)
  drawPoly([
    [lnbX - 3, lnbY - 2.5],
    [lnbX + 3, lnbY - 2.5],
    [lnbX + 3, lnbY + 2.5],
    [lnbX - 3, lnbY + 2.5]
  ], {
    washCol: PAL.lapisDeep,
    washAlpha: 245,
    strokeCol: PAL.ink,
    strokeW: 0.28
  });
  brush.noStroke();
  brush.wash(PAL.vermilionBright, 240);
  brush.circle(lnbX - 2 * dir, lnbY, 2.0);
  brush.noWash();

  // Coaxial cable snaking down mast and across roof
  const coaxPts = [
    [lnbX, lnbY + 2],
    [dx + 4 * dir, dy + ry * 0.75],
    [cx, cy + 4],
    [cx - 14 * dir, cy + 8],
    [cx - 26 * dir, cy + 5]
  ];
  strokeSpline(coaxPts, 0.5, "rotring", PAL.ink, 0.25);
}

// --- 3. WATER TANKS (Ribbed Galvanized & Polyethylene Barrels with Valves) ---

function drawHorizontalWaterTank(cx, cy, w, h, tankCol) {
  // Angle-iron welded steel frame stand
  const standH = 16;
  const xL = cx - w * 0.42, xR = cx + w * 0.42;
  strokeLine(xL, cy, xL - 4, cy + standH, "rotring", PAL.ink, 0.45);
  strokeLine(xR, cy, xR + 4, cy + standH, "rotring", PAL.ink, 0.45);
  strokeLine(xL + 6, cy - 3, xL + 4, cy + standH - 3, "rotring", PAL.ink, 0.35);
  strokeLine(xR - 6, cy - 3, xR - 4, cy + standH - 3, "rotring", PAL.ink, 0.35);
  // X-bracing
  strokeLine(xL - 2, cy + 2, xR + 2, cy + standH - 2, "rotring", PAL.ink, 0.28);
  strokeLine(xR + 2, cy + 2, xL - 2, cy + standH - 2, "rotring", PAL.ink, 0.28);

  // Tank cylinder body (tilted slightly)
  const ty = cy - h * 0.65;
  const bodyQ = [
    [cx - w * 0.5, ty - h * 0.5],
    [cx + w * 0.5, ty - h * 0.5 - 4],
    [cx + w * 0.5, ty + h * 0.5 - 4],
    [cx - w * 0.5, ty + h * 0.5]
  ];
  drawPoly(bodyQ, {
    fillCol: tankCol,
    fillAlpha: 225,
    bleed: 0.02,
    tex: 0.3,
    hatchDist: 3.5,
    hatchAngle: -5,
    hatchCol: PAL.lapisDeep,
    hatchBrush: "2H",
    hatchWeight: 0.22,
    strokeCol: PAL.ink,
    strokeW: 0.38
  });

  // Structural ribs around barrel
  for (let u = 0.18; u <= 0.84; u += 0.22) {
    const pT = quadPt(bodyQ, u, 0);
    const pB = quadPt(bodyQ, u, 1);
    const ribPts = [
      pT,
      [lerp(pT[0], pB[0], 0.3) - 3, lerp(pT[1], pB[1], 0.3)],
      [lerp(pT[0], pB[0], 0.7) - 3, lerp(pT[1], pB[1], 0.7)],
      pB
    ];
    strokeSpline(ribPts, 0.4, "rotring", PAL.ink, 0.32);
    strokeSpline(ribPts.map(p => [p[0] + 1.2, p[1]]), 0.4, "rotring", PAL.ivory, 0.22);
  }

  // Elliptical end cap on left
  const endPts = [];
  for (let i = 0; i < 16; i++) {
    const a = (i / 16) * 360;
    endPts.push([
      cx - w * 0.5 + cos(a) * (h * 0.24),
      ty + sin(a) * (h * 0.5)
    ]);
  }
  drawPoly(endPts, {
    washCol: PAL.ivory,
    washAlpha: 160,
    strokeCol: PAL.ink,
    strokeW: 0.35
  });

  // Top inspection manhole hatch & float-valve breather pipe
  const mhX = cx, mhY = ty - h * 0.5 - 2;
  drawPoly([
    [mhX - 6, mhY - 3],
    [mhX + 6, mhY - 3],
    [mhX + 6, mhY + 1],
    [mhX - 6, mhY + 1]
  ], {
    washCol: PAL.steelDark,
    washAlpha: 245,
    strokeCol: PAL.ink,
    strokeW: 0.3
  });
  strokeLine(mhX + 10, mhY, mhX + 10, mhY - 12, "rotring", PAL.ink, 0.3);
  strokeLine(mhX + 10, mhY - 12, mhX + 14, mhY - 12, "rotring", PAL.ink, 0.3);

  // Outflow pipe & red vermilion gate valve wheel
  const vx = cx - w * 0.35, vy = cy + 6;
  strokeLine(vx, ty + h * 0.4, vx, vy + 8, "rotring", PAL.ink, 0.4);
  strokeLine(vx, vy + 8, vx - 18, vy + 10, "rotring", PAL.ink, 0.4);
  brush.noStroke();
  brush.wash(PAL.vermilionBright, 245);
  brush.circle(vx, vy, 3.5);
  brush.set("rotring", PAL.ink, 0.25);
  brush.circle(vx, vy, 3.5);
}

function drawVerticalWaterTank(cx, cy, w, h, tankCol, legH) {
  // Elevated truss legs
  const xL = cx - w * 0.42, xR = cx + w * 0.42;
  if (legH > 0) {
    strokeLine(xL, cy, xL - 3, cy + legH, "rotring", PAL.ink, 0.45);
    strokeLine(xR, cy, xR + 3, cy + legH, "rotring", PAL.ink, 0.45);
    strokeLine(cx, cy + 2, cx, cy + legH + 2, "rotring", PAL.ink, 0.4);
    // Cross truss bars
    strokeLine(xL - 1, cy + legH * 0.5, xR + 1, cy + legH * 0.5, "rotring", PAL.ink, 0.3);
    strokeLine(xL, cy, xR + 2, cy + legH * 0.5, "rotring", PAL.ink, 0.25);
    strokeLine(xR, cy, xL - 2, cy + legH * 0.5, "rotring", PAL.ink, 0.25);
  }

  // Vertical cylinder body
  const topY = cy - h;
  const bodyQ = [
    [xL, topY],
    [xR, topY],
    [xR, cy],
    [xL, cy]
  ];
  drawPoly(bodyQ, {
    fillCol: tankCol,
    fillAlpha: 230,
    bleed: 0.02,
    tex: 0.3,
    hatchDist: 3.5,
    hatchAngle: 88,
    hatchCol: PAL.lapisDeep,
    hatchBrush: "2H",
    hatchWeight: 0.22,
    strokeCol: PAL.ink,
    strokeW: 0.38
  });

  // Horizontal reinforcement ribs
  for (let v = 0.2; v <= 0.85; v += 0.2) {
    const ry = lerp(topY, cy, v);
    const ribPts = [
      [xL - 1, ry],
      [cx, ry + 3.5],
      [xR + 1, ry]
    ];
    strokeSpline(ribPts, 0.4, "rotring", PAL.ink, 0.32);
    strokeSpline(ribPts.map(p => [p[0], p[1] - 1.2]), 0.4, "rotring", PAL.ivory, 0.22);
  }

  // Domed top cap & manhole turret
  const topPts = [];
  for (let i = 0; i < 16; i++) {
    const a = (i / 16) * 360;
    topPts.push([
      cx + cos(a) * (w * 0.42),
      topY + sin(a) * (w * 0.16)
    ]);
  }
  drawPoly(topPts, {
    washCol: PAL.ivory,
    washAlpha: 170,
    strokeCol: PAL.ink,
    strokeW: 0.35
  });
  drawPoly([
    [cx - 5, topY - 6],
    [cx + 5, topY - 6],
    [cx + 5, topY],
    [cx - 5, topY]
  ], {
    washCol: PAL.lapisDeep,
    washAlpha: 245,
    strokeCol: PAL.ink,
    strokeW: 0.3
  });

  // Plumbing pipe & vermilion valve wheel
  strokeLine(xR, topY + 6, xR + 6, topY + 6, "rotring", PAL.ink, 0.35);
  strokeLine(xR + 6, topY + 6, xR + 6, cy + legH, "rotring", PAL.ink, 0.35);
  brush.noStroke();
  brush.wash(PAL.vermilionBright, 245);
  brush.circle(xR + 6, cy - 6, 3.2);
  brush.set("rotring", PAL.ink, 0.25);
  brush.circle(xR + 6, cy - 6, 3.2);
}

