// --- 7. LAUNDRY LINES & FLUTTERING GARMENTS ---

function drawLaundryLine(x1, y1, x2, y2, nItems) {
  const postH = 44;
  // Wooden/Iron laundry posts
  strokeLine(x1, y1, x1, y1 - postH, "rotring", PAL.ink, 0.45);
  strokeLine(x2, y2, x2, y2 - postH, "rotring", PAL.ink, 0.45);
  // Crossbars at top of posts
  strokeLine(x1 - 5, y1 - postH + 4, x1 + 5, y1 - postH - 2, "rotring", PAL.ink, 0.35);
  strokeLine(x2 - 5, y2 - postH + 4, x2 + 5, y2 - postH - 2, "rotring", PAL.ink, 0.35);

  // Sagging catenary cord
  const midX = (x1 + x2) * 0.5;
  const midY = (y1 + y2) * 0.5 - postH + 9;
  const cordPts = [
    [x1, y1 - postH],
    [lerp(x1, midX, 0.5), lerp(y1 - postH, midY, 0.7)],
    [midX, midY],
    [lerp(midX, x2, 0.5), lerp(midY, y2 - postH, 0.3)],
    [x2, y2 - postH]
  ];
  strokeSpline(cordPts, 0.5, "rotring", PAL.ink, 0.28);

  // Hanging garments along the catenary curve
  const colors = [PAL.vermilionBright, PAL.ivory, PAL.saffron, PAL.lapisBright, PAL.turquoise, PAL.ivory, PAL.vermilion];
  for (let i = 0; i < nItems; i++) {
    const t = (i + 0.65) / (nItems + 0.3);
    const gx = lerp(x1, x2, t);
    const sag = sin(t * 180) * 9;
    const gy = lerp(y1 - postH, y2 - postH, t) + sag;
    const col = colors[i % colors.length];
    const sway = 4; // gentle breeze to the right

    if (i % 3 === 0) {
      // Tunic / Shirt with sleeves
      const w = 13, h = 21;
      drawPoly([
        [gx - w * 0.5, gy],
        [gx - w * 0.85, gy + 7],
        [gx - w * 0.55, gy + 10],
        [gx - w * 0.4, gy + 6],
        [gx - w * 0.4 + sway, gy + h],
        [gx + w * 0.4 + sway, gy + h - 1],
        [gx + w * 0.4, gy + 6],
        [gx + w * 0.55, gy + 10],
        [gx + w * 0.85, gy + 6],
        [gx + w * 0.5, gy]
      ], {
        washCol: col,
        washAlpha: 240,
        strokeCol: PAL.ink,
        strokeW: 0.26
      });
      // Collar & hem stripe
      strokeLine(gx - w * 0.35 + sway, gy + h - 3, gx + w * 0.35 + sway, gy + h - 4, "rotring", PAL.saffron, 0.28);
    } else if (i % 3 === 1) {
      // Patterned sheet / chador cloth
      const w = 15, h = 25;
      const sQ = [
        [gx - w * 0.5, gy],
        [gx + w * 0.5, gy],
        [gx + w * 0.5 + sway, gy + h],
        [gx - w * 0.5 + sway, gy + h + 1]
      ];
      drawPoly(sQ, {
        washCol: col,
        washAlpha: 240,
        hatchDist: 3.5,
        hatchAngle: 12,
        hatchCol: (col === PAL.ivory ? PAL.lapis : PAL.ivory),
        hatchBrush: "2H",
        hatchWeight: 0.2,
        strokeCol: PAL.ink,
        strokeW: 0.26
      });
      // Decorative border stripe
      strokeLine(gx - w * 0.46 + sway, gy + h - 3, gx + w * 0.46 + sway, gy + h - 4, "rotring", PAL.vermilion, 0.3);
    } else {
      // Trousers / Sirwal
      const w = 11, h = 22;
      drawPoly([
        [gx - w * 0.5, gy],
        [gx + w * 0.5, gy],
        [gx + w * 0.48 + sway, gy + h],
        [gx + w * 0.12 + sway, gy + h],
        [gx + sway * 0.4, gy + h * 0.42],
        [gx - w * 0.12 + sway, gy + h],
        [gx - w * 0.48 + sway, gy + h]
      ], {
        washCol: col,
        washAlpha: 240,
        strokeCol: PAL.ink,
        strokeW: 0.26
      });
    }

    // Tiny wooden clothespins on the wire
    strokeLine(gx - 4, gy - 2.5, gx - 4, gy + 2, "rotring", PAL.vermilion, 0.32);
    strokeLine(gx + 4, gy - 2.5, gx + 4, gy + 2, "rotring", PAL.vermilion, 0.32);
  }
}

