// --- 9. MINIATURE FIGURES (Expressive Persian Miniature Postures & Robes) ---

function drawMiniatureFigure(x, y, opts) {
  const {
    robeCol = PAL.lapis,
    sashCol = PAL.vermilion,
    turbanCol = PAL.ivory,
    pose = "standing",
    scale = 1.0
  } = opts;

  const s = scale;
  const isSeated = pose.startsWith("seated");
  const h = (isSeated ? 24 : 34) * s;
  const headY = y - h;

  // Boots / slippers
  if (!isSeated) {
    strokeLine(x - 3 * s, y, x - 6 * s, y + 1.5 * s, "rotring", PAL.ink, 0.55);
    strokeLine(x + 3 * s, y, x + 6 * s, y + 1.5 * s, "rotring", PAL.ink, 0.55);
  }

  // Flowing Qaba / Coat robe
  let robePts;
  if (isSeated) {
    const dir = pose.includes("right") ? 1 : -1;
    robePts = [
      [x - 5 * s, headY + 6 * s],
      [x + 5 * s, headY + 6 * s],
      [x + 9 * s * dir, y - 3 * s],
      [x + 11 * s * dir, y + 2 * s],
      [x - 7 * s * dir, y + 2 * s],
      [x - 6 * s, headY + 14 * s]
    ];
  } else {
    robePts = [
      [x - 5.5 * s, headY + 6 * s],
      [x + 5.5 * s, headY + 6 * s],
      [x + 7.5 * s, y - 2 * s],
      [x - 7.5 * s, y - 2 * s]
    ];
  }
  drawPoly(robePts, {
    washCol: robeCol,
    washAlpha: 245,
    strokeCol: PAL.ink,
    strokeW: 0.32
  });

  // Diagonal lapel & waist sash (Kamarband)
  const waistY = headY + 16 * s;
  strokeLine(x, headY + 6 * s, x - 2 * s, waistY, "rotring", PAL.ivory, 0.25);
  drawPoly([
    [x - 6 * s, waistY - 1.5 * s],
    [x + 6 * s, waistY - 1.5 * s],
    [x + 6.5 * s, waistY + 2 * s],
    [x - 6.5 * s, waistY + 2 * s]
  ], {
    washCol: sashCol,
    washAlpha: 245,
    strokeCol: PAL.ink,
    strokeW: 0.24
  });

  // Gesturing Arms & Narrative Tools
  const shY = headY + 8 * s;
  if (pose === "beating_rug_right") {
    strokeLine(x + 4 * s, shY, x + 13 * s, shY + 5 * s, "rotring", robeCol, 0.7);
    strokeLine(x + 4 * s, shY, x + 13 * s, shY + 5 * s, "rotring", PAL.ink, 0.3);
    // Woven carpet beater stick
    strokeLine(x + 12 * s, shY + 5 * s, x + 26 * s, shY + 14 * s, "rotring", PAL.saffron, 0.4);
    brush.set("rotring", PAL.saffron, 0.3);
    brush.circle(x + 27 * s, shY + 15 * s, 3.5 * s);
  }
  else if (pose === "beating_rug_left") {
    strokeLine(x - 4 * s, shY, x - 13 * s, shY - 3 * s, "rotring", robeCol, 0.7);
    strokeLine(x - 12 * s, shY - 3 * s, x - 24 * s, shY - 10 * s, "rotring", PAL.saffron, 0.4);
    brush.set("rotring", PAL.saffron, 0.3);
    brush.circle(x - 25 * s, shY - 11 * s, 3.5 * s);
  }
  else if (pose === "flag_pole") {
    strokeLine(x + 4 * s, shY, x + 11 * s, shY - 6 * s, "rotring", PAL.ink, 0.4);
    // Long bamboo pigeon-guiding pole with vermilion pennant
    strokeLine(x + 10 * s, shY + 8 * s, x + 28 * s, headY - 46 * s, "rotring", PAL.ink, 0.32);
    drawPoly([
      [x + 28 * s, headY - 46 * s],
      [x + 44 * s, headY - 42 * s],
      [x + 26 * s, headY - 36 * s]
    ], {
      washCol: PAL.vermilionBright,
      washAlpha: 245,
      strokeCol: PAL.ink,
      strokeW: 0.25
    });
  }
  else if (pose === "hanging_laundry") {
    strokeLine(x - 4 * s, shY, x - 9 * s, headY - 5 * s, "rotring", PAL.ink, 0.45);
    strokeLine(x + 4 * s, shY, x + 9 * s, headY - 5 * s, "rotring", PAL.ink, 0.45);
  }
  else if (pose === "reaching_left") {
    strokeLine(x - 4 * s, shY, x - 15 * s, shY - 4 * s, "rotring", PAL.ink, 0.45);
  }
  else if (pose === "pointing_right") {
    strokeLine(x + 4 * s, shY, x + 15 * s, shY - 4 * s, "rotring", PAL.ink, 0.45);
  }
  else if (pose === "watering") {
    strokeLine(x - 4 * s, shY, x - 12 * s, shY + 4 * s, "rotring", PAL.ink, 0.45);
    // Copper ewer (Aftabeh) pouring water
    brush.noStroke();
    brush.wash(PAL.saffron, 245);
    brush.circle(x - 14 * s, shY + 6 * s, 3.5 * s);
    strokeLine(x - 14 * s, shY + 6 * s, x - 21 * s, shY + 12 * s, "rotring", PAL.cerulean, 0.28);
  }

  // Three-quarter moon-faced head (classic Persian miniature facial convention)
  brush.noStroke();
  brush.wash("#f5dfc1", 245);
  brush.circle(x, headY, 4.2 * s);
  brush.set("rotring", PAL.ink, 0.28);
  brush.circle(x, headY, 4.2 * s);
  // Tiny eye & arched eyebrow dot
  strokeLine(x - 1.5 * s, headY - 0.8 * s, x + 1.5 * s, headY - 0.8 * s, "rotring", PAL.ink, 0.22);

  // Turban / Headscarf wrap
  drawPoly([
    [x - 5.2 * s, headY - 1.5 * s],
    [x - 3 * s, headY - 6.2 * s],
    [x + 3.5 * s, headY - 6.2 * s],
    [x + 5.2 * s, headY - 1.5 * s]
  ], {
    washCol: turbanCol,
    washAlpha: 245,
    strokeCol: PAL.ink,
    strokeW: 0.28
  });
  // Turban feather/kula tip
  strokeLine(x, headY - 6 * s, x + 1.5 * s, headY - 9.5 * s, "rotring", sashCol, 0.32);
}

// ============================================================================
// 5. ELEMENTS BREAKING THE UPPER MANUSCRIPT BORDER
// ============================================================================

function drawFrameBreakingElements() {
  // 1. Tall Cypress tip & Dome finial on left breaking above y = M_TOP (115)
  drawCypress(485, 152, 14, 78);

  // 2. A rooftop stairwell tower & satellite dish on the upper center-right breaking into the top margin
  drawStairPenthouse(785, 142, 46, 54, 1);
  drawSatelliteDish(802, 92, 24, 1, "top_break");

  // 3. Flock of white & slate-blue tumbler pigeons soaring out of the dovecote across the upper border
  const flock = [
    [435, 195, 1.0, -15], [462, 168, 1.1, -22], [498, 142, 1.05, -18],
    [535, 118, 1.15, -12], [568, 96, 1.1, -8], [608, 86, 1.0, 5],
    [518, 92, 0.95, -25], [472, 108, 1.0, -20], [648, 105, 0.95, 12]
  ];
  for (let i = 0; i < flock.length; i++) {
    const [bx, by, bsc, bang] = flock[i];
    drawFlyingPigeon(bx, by, bsc, (i % 3 === 0) ? PAL.paleBlue : PAL.ivory);
  }
}

function drawFlyingPigeon(x, y, sc, col) {
  const wPts = [
    [x - 9 * sc, y - 5 * sc],
    [x - 2 * sc, y - 1 * sc],
    [x + 8 * sc, y - 6 * sc],
    [x + 3 * sc, y + 1 * sc],
    [x + 6 * sc, y + 4 * sc],
    [x, y + 2 * sc],
    [x - 5 * sc, y + 4 * sc],
    [x - 2 * sc, y + 1 * sc]
  ];
  drawPoly(wPts, {
    washCol: col,
    washAlpha: 245,
    strokeCol: PAL.ink,
    strokeW: 0.26
  });
  // Wing primary feather ticks
  strokeLine(x - 9 * sc, y - 5 * sc, x - 11 * sc, y - 3 * sc, "rotring", PAL.lapisDeep, 0.22);
  strokeLine(x + 8 * sc, y - 6 * sc, x + 10 * sc, y - 4 * sc, "rotring", PAL.lapisDeep, 0.22);
}

// ============================================================================
// 6. DELICATE PERSIAN MANUSCRIPT BORDERS (Jadwal & Illuminated Margin)
// ============================================================================

function drawManuscriptBorders() {
  // Mask strips around outer perimeter to ensure crisp side & bottom edges
  // (Leaving a gap at the top where the dome/cypress/dish/pigeons break the frame!)
  drawPoly([[0, 0], [M_LEFT, 0], [M_LEFT, 1200], [0, 1200]], {
    washCol: PAL.parchment, washAlpha: 245, strokeCol: null
  });
  drawPoly([[M_RIGHT, 0], [1200, 0], [1200, 1200], [M_RIGHT, 1200]], {
    washCol: PAL.parchment, washAlpha: 245, strokeCol: null
  });
  drawPoly([[0, M_BOTTOM], [1200, M_BOTTOM], [1200, 1200], [0, 1200]], {
    washCol: PAL.parchment, washAlpha: 245, strokeCol: null
  });

  // Multi-ruled Jadwal border lines:
  // Rule 1: Inner black hairline + gold ribbon + vermilion hairline
  drawBrokenTopRect(M_LEFT, M_TOP, M_RIGHT, M_BOTTOM, "rotring", PAL.ink, 0.45);
  drawBrokenTopRect(M_LEFT - 4, M_TOP - 4, M_RIGHT + 4, M_BOTTOM + 4, "rotring", PAL.saffron, 0.85);
  drawBrokenTopRect(M_LEFT - 7, M_TOP - 7, M_RIGHT + 7, M_BOTTOM + 7, "rotring", PAL.vermilion, 0.45);

  // Rule 2: Lapis blue illuminated floral band (`offset 14..28`)
  drawIlluminatedBorderBand();

  // Rule 3: Outer vermilion & lapis frame (`offset 34` and `52`)
  drawRectFrame(M_LEFT - 34, M_TOP - 34, M_RIGHT + 34, M_BOTTOM + 34, "rotring", PAL.lapisDeep, 0.55);
  drawRectFrame(M_LEFT - 38, M_TOP - 38, M_RIGHT + 38, M_BOTTOM + 38, "rotring", PAL.vermilion, 0.35);
  drawRectFrame(M_LEFT - 56, M_TOP - 56, M_RIGHT + 56, M_BOTTOM + 56, "rotring", PAL.lapis, 0.35);

  // Delicate gold & lapis floral sprays (Tash'ir) in the outer parchment margin
  drawMarginArabesques();

  // Re-stamp the breaking top elements on top of the inner rule so they cleanly overlap the border
  drawCypress(485, 152, 14, 78);
  drawSatelliteDish(802, 92, 24, 1, "top_break");
  drawFlyingPigeon(535, 118, 1.15, PAL.ivory);
  drawFlyingPigeon(568, 96, 1.1, PAL.paleBlue);
}

function drawRectFrame(x1, y1, x2, y2, bName, col, w) {
  strokeLine(x1, y1, x2, y1, bName, col, w);
  strokeLine(x2, y1, x2, y2, bName, col, w);
  strokeLine(x2, y2, x1, y2, bName, col, w);
  strokeLine(x1, y2, x1, y1, bName, col, w);
}

function drawBrokenTopRect(x1, y1, x2, y2, bName, col, w) {
  // Top rule broken around cypress (470..500) and stair/dish (765..825)
  strokeLine(x1, y1, 468, y1, bName, col, w);
  strokeLine(502, y1, 762, y1, bName, col, w);
  strokeLine(828, y1, x2, y1, bName, col, w);
  // Sides & bottom
  strokeLine(x2, y1, x2, y2, bName, col, w);
  strokeLine(x2, y2, x1, y2, bName, col, w);
  strokeLine(x1, y2, x1, y1, bName, col, w);
}

function drawIlluminatedBorderBand() {
  const bIn = 12, bOut = 26;
  const strips = [
    // Left band
    [[M_LEFT - bOut, M_TOP - bOut], [M_LEFT - bIn, M_TOP - bOut], [M_LEFT - bIn, M_BOTTOM + bOut], [M_LEFT - bOut, M_BOTTOM + bOut]],
    // Right band
    [[M_RIGHT + bIn, M_TOP - bOut], [M_RIGHT + bOut, M_TOP - bOut], [M_RIGHT + bOut, M_BOTTOM + bOut], [M_RIGHT + bIn, M_BOTTOM + bOut]],
    // Bottom band
    [[M_LEFT - bOut, M_BOTTOM + bIn], [M_RIGHT + bOut, M_BOTTOM + bIn], [M_RIGHT + bOut, M_BOTTOM + bOut], [M_LEFT - bOut, M_BOTTOM + bOut]],
    // Top band (left section)
    [[M_LEFT - bOut, M_TOP - bOut], [468, M_TOP - bOut], [468, M_TOP - bIn], [M_LEFT - bOut, M_TOP - bIn]],
    // Top band (middle section)
    [[502, M_TOP - bOut], [762, M_TOP - bOut], [762, M_TOP - bIn], [502, M_TOP - bIn]],
    // Top band (right section)
    [[828, M_TOP - bOut], [M_RIGHT + bOut, M_TOP - bOut], [M_RIGHT + bOut, M_TOP - bIn], [828, M_TOP - bIn]]
  ];

  for (let s of strips) {
    drawPoly(s, {
      washCol: PAL.lapisDeep,
      washAlpha: 245,
      strokeCol: PAL.goldLeaf,
      strokeW: 0.32
    });
  }

  // Alternating vermilion, saffron, and turquoise jewel rosettes along the lapis border
  const midOff = (bIn + bOut) * 0.5;
  for (let y = M_TOP - midOff; y <= M_BOTTOM + midOff; y += 26) {
    drawBorderRosette(M_LEFT - midOff, y, (Math.round(y) % 2 === 0) ? PAL.vermilionBright : PAL.saffron);
    drawBorderRosette(M_RIGHT + midOff, y, (Math.round(y) % 2 === 0) ? PAL.saffron : PAL.vermilionBright);
  }
  for (let x = M_LEFT - midOff + 26; x < M_RIGHT + midOff - 10; x += 26) {
    drawBorderRosette(x, M_BOTTOM + midOff, (Math.round(x) % 2 === 0) ? PAL.vermilionBright : PAL.saffron);
    if ((x < 462) || (x > 508 && x < 756) || (x > 834)) {
      drawBorderRosette(x, M_TOP - midOff, (Math.round(x) % 2 === 0) ? PAL.saffron : PAL.vermilionBright);
    }
  }

  // 4 Illuminated Corner Medallions
  const corners = [
    [M_LEFT - midOff, M_TOP - midOff],
    [M_RIGHT + midOff, M_TOP - midOff],
    [M_RIGHT + midOff, M_BOTTOM + midOff],
    [M_LEFT - midOff, M_BOTTOM + midOff]
  ];
  for (let c of corners) {
    drawPoly([
      [c[0] - 10, c[1] - 10],
      [c[0] + 10, c[1] - 10],
      [c[0] + 10, c[1] + 10],
      [c[0] - 10, c[1] + 10]
    ], {
      washCol: PAL.vermilion,
      washAlpha: 245,
      strokeCol: PAL.saffronLight,
      strokeW: 0.35
    });
    drawBorderRosette(c[0], c[1], PAL.saffronLight);
  }
}

function drawBorderRosette(x, y, col) {
  brush.noStroke();
  brush.wash(col, 240);
  brush.circle(x, y, 3.2);
  brush.wash(PAL.ivory, 245);
  brush.circle(x, y, 1.3);
  brush.noWash();
}

function drawMarginArabesques() {
  // Delicate gold & lapis scrolling vine tendrils in the outer margin band
  const marginMid = 34;
  for (let y = 140; y <= 1060; y += 95) {
    // Left margin scroll
    strokeSpline([
      [marginMid - 8, y - 35],
      [marginMid + 8, y - 12],
      [marginMid - 8, y + 12],
      [marginMid + 8, y + 35]
    ], 0.6, "rotring", PAL.goldLeaf, 0.28);
    drawBorderRosette(marginMid + 6, y - 12, PAL.lapisBright);
    drawBorderRosette(marginMid - 6, y + 12, PAL.vermilion);

    // Right margin scroll
    const rx = 1200 - marginMid;
    strokeSpline([
      [rx + 8, y - 35],
      [rx - 8, y - 12],
      [rx + 8, y + 12],
      [rx - 8, y + 35]
    ], 0.6, "rotring", PAL.goldLeaf, 0.28);
    drawBorderRosette(rx - 6, y - 12, PAL.lapisBright);
    drawBorderRosette(rx + 6, y + 12, PAL.vermilion);
  }

  // Bottom manuscript cartouche (Ketabeh)
  const cx = 600, cy = 1166;
  drawPoly([
    [cx - 110, cy - 12],
    [cx - 95, cy - 16],
    [cx + 95, cy - 16],
    [cx + 110, cy - 12],
    [cx + 110, cy + 4],
    [cx + 95, cy + 8],
    [cx - 95, cy + 8],
    [cx - 110, cy + 4]
  ], {
    washCol: PAL.ivory,
    washAlpha: 240,
    strokeCol: PAL.lapisDeep,
    strokeW: 0.38
  });
  // Pseudo-Nastaliq calligraphy flourish in cartouche
  strokeSpline([
    [cx - 75, cy - 2], [cx - 55, cy - 6], [cx - 38, cy],
    [cx - 18, cy - 7], [cx, cy - 1], [cx + 22, cy - 6],
    [cx + 45, cy], [cx + 68, cy - 5], [cx + 80, cy - 2]
  ], 0.5, "rotring", PAL.ink, 0.35);
  drawBorderRosette(cx - 92, cy - 4, PAL.vermilion);
  drawBorderRosette(cx + 92, cy - 4, PAL.vermilion);
}

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(4271);
  noiseSeed(4271);

  // Custom brush for soft luminous thermal glazes and flame edges
  brush.add("softWash", {
    type: "default",
    weight: 14,
