}

function draw() {
  translate(-width / 2, -height / 2);

  // Cool pale slate-paper background
  background("#dce2ea");
  brush.set("HB", "#111318", 1);

  // =========================================================================
  // 1. OUTER COOL PAPER GROUND & SUBTLE CARD SHADOW
  // =========================================================================
  drawPaperMargin();

  // Label geometry (upright safety-match label centered on canvas)
  const L = {
    x0: 210, y0: 90,  w0: 780, h0: 1020, // Outer brick-red frame
    x1: 282, y1: 162, w1: 636, h1: 876,  // Mustard inner band
    x2: 318, y2: 198, w2: 564, h2: 804   // Inner black keyline & ultramarine field
  };

  // =========================================================================
  // 2. FLAT PRINTED SAFETY-MATCH LABEL BORDER
  //    Brick-red outer frame, mustard inner band, black keyline
  // =========================================================================
  drawPrintedFrame(L);

  // =========================================================================
  // 3. DEEP FLAT ULTRAMARINE INNER FIELD
  // =========================================================================
  drawUltramarineField(L);

  // =========================================================================
  // 4. CURLED TONGUE OF FLAME (SOFT LAYERED WASHES)
  //    Passing from white-yellow through orange to blue at its root
  // =========================================================================
  brush.clip([L.x2 + 2, L.y2 + 2, L.x2 + L.w2 - 2, L.y2 + L.h2 - 2]);
  drawCurledFlameWashes();

  // =========================================================================
  // 5. HYPERREAL WOODEN SPLINT (SPLITTING WOOD GRAIN & CHAR)
  // =========================================================================
  drawSplittingMatchstick(L);

  // =========================================================================
  // 6. MICROSCOPIC MATCH HEAD AT THE INSTANT OF STRIKING
  // =========================================================================
  drawHyperrealMatchHead();

  // =========================================================================
  // 7. INNER FLAME FILAMENTS, BLUE ROOT GLAZE & COOL SMOKE RIBBONS
  // =========================================================================
  drawFlameFilamentsAndSmoke();
  brush.noClip();

  // =========================================================================
  // 8. CRISP PRINTED BLACK KEYLINES (DRAWN BEFORE BREAKOUT CRUMBS)
  // =========================================================================
  drawBlackKeylines(L);

  // =========================================================================
  // 9. EXPLODING PHOSPHORUS CRUMBS, INCANDESCENT SPARKS & VAPOR TRAILS
  // =========================================================================
  drawExplodingPhosphorusCrumbs(L);

  noLoop();
}

// ---------------------------------------------------------------------------
// Helper: Draw a filled/washed rectangle via 4 vertices for consistent bleed
// ---------------------------------------------------------------------------
function drawQuadBox(x, y, w, h, curv = 0.02) {
  brush.beginShape(curv);
  brush.vertex(x, y);
  brush.vertex(x + w, y);
  brush.vertex(x + w, y + h);
  brush.vertex(x, y + h);
  brush.endShape(true);
}

// ---------------------------------------------------------------------------
// Helper: Draw a smooth closed organic wash polygon from point array
// ---------------------------------------------------------------------------
function drawOrganicShape(pts, curv = 0.65) {
  brush.beginShape(curv);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
}

// ---------------------------------------------------------------------------
// 1. OUTER PAPER GROUND
// ---------------------------------------------------------------------------
function drawPaperMargin() {
  brush.noStroke();
  brush.noHatch();

  // Subtle cool-toned vintage card wash around the margins
  brush.fillBleed(0.25, "out");
  brush.fillTexture(0.35, 0.12);
  brush.fill("#cfd7e2", 55);
  drawQuadBox(30, 30, 1140, 1140, 0.01);

  // Fine paper fibers on outer margin
  brush.set("2H", "#b8c3d1", 0.35);
  for (let i = 0; i < 95; i++) {
    let px = random(40, 1160);
    let py = random(40, 1160);
    if (px > 195 && px < 1005 && py > 75 && py < 1125) continue;
    let ang = random(-25, 25);
    let len = random(18, 55);
    brush.line(px, py, px + cos(ang) * len, py + sin(ang) * len);
  }

  // Subtle physical step-shadow under the matchbox label card
  brush.noStroke();
  brush.wash("#aeb8c7", 85);
  drawQuadBox(215, 96, 780, 1020, 0.0);
  brush.wash("#9aa6b8", 65);
  drawQuadBox(213, 93, 780, 1020, 0.0);
}

// ---------------------------------------------------------------------------
// 2. FLAT PRINTED FRAME (BRICK-RED & MUSTARD BANDS)
// ---------------------------------------------------------------------------
function drawPrintedFrame(L) {
  brush.noStroke();
  brush.noHatch();

  const bThick = L.x1 - L.x0; // 72px brick-red width
  const mThick = L.x2 - L.x1; // 36px mustard width

  // --- Flat Brick-Red Frame (4 slabs) ---
  // Cool vintage brick-red ink base
  brush.wash("#9a3228", 248);
  drawQuadBox(L.x0, L.y0, L.w0, bThick, 0.0);                         // Top
  drawQuadBox(L.x0, L.y0 + L.h0 - bThick, L.w0, bThick, 0.0);         // Bottom
  drawQuadBox(L.x0, L.y0 + bThick, bThick, L.h0 - 2 * bThick, 0.0);   // Left
  drawQuadBox(L.x0 + L.w0 - bThick, L.y0 + bThick, bThick, L.h0 - 2 * bThick, 0.0); // Right

  // Second matte print pass for tactile block-printed density
  brush.fillBleed(0.015, "in");
  brush.fillTexture(0.32, 0.18);
  brush.fill("#8c2920", 75);
  drawQuadBox(L.x0, L.y0, L.w0, bThick, 0.01);
  drawQuadBox(L.x0, L.y0 + L.h0 - bThick, L.w0, bThick, 0.01);
  drawQuadBox(L.x0, L.y0 + bThick, bThick, L.h0 - 2 * bThick, 0.01);
  drawQuadBox(L.x0 + L.w0 - bThick, L.y0 + bThick, bThick, L.h0 - 2 * bThick, 0.01);

  // Subtle cheap-print ink grain across brick-red frame
  brush.hatchStyle("2H", "#7d221a", 0.35);
  brush.hatch(9, 0, { rand: 0.04 });
  brush.noFill();
  brush.noWash();
  drawQuadBox(L.x0 + 2, L.y0 + 2, L.w0 - 4, bThick - 4, 0.0);
  drawQuadBox(L.x0 + 2, L.y0 + L.h0 - bThick + 2, L.w0 - 4, bThick - 4, 0.0);
  brush.noHatch();

  // --- Flat Mustard Inner Band (4 slabs) ---
  brush.noStroke();
  brush.wash("#cc9b2b", 250);
  drawQuadBox(L.x1, L.y1, L.w1, mThick, 0.0);                         // Top
  drawQuadBox(L.x1, L.y1 + L.h1 - mThick, L.w1, mThick, 0.0);         // Bottom
  drawQuadBox(L.x1, L.y1 + mThick, mThick, L.h1 - 2 * mThick, 0.0);   // Left
  drawQuadBox(L.x1 + L.w1 - mThick, L.y1 + mThick, mThick, L.h1 - 2 * mThick, 0.0); // Right

  // Second pass on mustard band for flat vintage print character
  brush.fillBleed(0.012, "in");
  brush.fillTexture(0.28, 0.15);
  brush.fill("#b8861e", 65);
  drawQuadBox(L.x1, L.y1, L.w1, mThick, 0.01);
  drawQuadBox(L.x1, L.y1 + L.h1 - mThick, L.w1, mThick, 0.01);
  drawQuadBox(L.x1, L.y1 + mThick, mThick, L.h1 - 2 * mThick, 0.01);
  drawQuadBox(L.x1 + L.w1 - mThick, L.y1 + mThick, mThick, L.h1 - 2 * mThick, 0.01);

  // Tiny registration/wear flecks on the printed border
  brush.set("2H", "#dfd6c3", 0.4);
  for (let i = 0; i < 45; i++) {
    let side = floor(random(4));
    let rx, ry;
    if (side === 0) { rx = random(L.x0 + 6, L.x0 + L.w0 - 6); ry = random(L.y0 + 6, L.y1 - 6); }
    else if (side === 1) { rx = random(L.x0 + 6, L.x0 + L.w0 - 6); ry = random(L.y1 + L.h1 + 6, L.y0 + L.h0 - 6); }
    else if (side === 2) { rx = random(L.x0 + 6, L.x1 - 6); ry = random(L.y1, L.y1 + L.h1); }
    else { rx = random(L.x1 + L.w1 + 6, L.x0 + L.w0 - 6); ry = random(L.y1, L.y1 + L.h1); }
    brush.line(rx, ry, rx + random(-3, 3), ry + random(-2, 2));
  }
}

// ---------------------------------------------------------------------------
// 3. DEEP FLAT ULTRAMARINE INNER FIELD
// ---------------------------------------------------------------------------
function drawUltramarineField(L) {
  brush.noStroke();
  brush.noHatch();

  // Deep flat ultramarine base
  brush.wash("#0b183d", 255);
  drawQuadBox(L.x2, L.y2, L.w2, L.h2, 0.0);

  // Rich second ultramarine pigment layer
  brush.wash("#102257", 210);
  drawQuadBox(L.x2 + 2, L.y2 + 2, L.w2 - 4, L.h2 - 4, 0.0);

  // Velvety ultramarine wash texture in the deep field
  brush.fillBleed(0.04, "in");
  brush.fillTexture(0.42, 0.18);
  brush.fill("#142b6e", 95);
  drawQuadBox(L.x2 + 6, L.y2 + 6, L.w2 - 12, L.h2 - 12, 0.01);

  // Darker cool abyssal indigo vignette near corners of the inner window
  brush.fillBleed(0.25, "in");
  brush.fill("#07102b", 110);
  drawQuadBox(L.x2, L.y2, L.w2, 130, 0.02);
  drawQuadBox(L.x2, L.y2 + L.h2 - 140, L.w2, 140, 0.02);
}

