// ---------------------------------------------------------------------------
// 5. HYPERREAL WOODEN SPLINT (SPLITTING WOOD GRAIN & CHAR)
// ---------------------------------------------------------------------------
function drawSplittingMatchstick(L) {
  // Matchstick runs from bottom-left (345, 1015) up-right at ~60 degrees to neck (545, 668)
  // Axis unit vector U = (0.5, -0.866025), Normal vector V = (0.866025, 0.5)
  const xStart = 345, yStart = 1015;
  const ux = 0.5, uy = -0.866025;
  const vx = 0.866025, vy = 0.5;
  const stickLen = 402;

  function stickPt(s, n) {
    return [xStart + ux * s + vx * n, yStart + uy * s + vy * n];
  }

  brush.noStroke();
  brush.noHatch();

  // --- A. Top-Left Wooden Face (Warmly lit near neck, cool slate-ivory lower down) ---
  // Lower shaft section (cool palette reflection)
  const topFaceLower = [
    stickPt(-10, -40),
    stickPt(235, -39),
    stickPt(235, 3),
    stickPt(-10, 4)
  ];
  brush.wash("#9aa8bd", 245);
  drawOrganicShape(topFaceLower, 0.05);

  // Upper shaft section (warm golden illumination from the ignition)
  const topFaceUpper = [
    stickPt(210, -39),
    stickPt(395, -36),
    stickPt(395, 3),
    stickPt(210, 3)
  ];
  brush.wash("#dfb47c", 245);
  drawOrganicShape(topFaceUpper, 0.05);

  // Brightest thermal glare just below the charred collar
  const topFaceGlow = [
    stickPt(285, -38),
    stickPt(375, -36),
    stickPt(375, 2),
    stickPt(285, 2)
  ];
  brush.fillBleed(0.18, "in");
  brush.fill("#f7dcb0", 180);
  drawOrganicShape(topFaceGlow, 0.08);

  // --- B. Bottom-Right Wooden Face (In deep cool shadow + electric blue flame-root rim) ---
  const sideFaceLower = [
    stickPt(-10, 3),
    stickPt(250, 3),
    stickPt(250, 34),
    stickPt(-10, 36)
  ];
  brush.wash("#28354a", 250);
  drawOrganicShape(sideFaceLower, 0.05);

  const sideFaceUpper = [
    stickPt(230, 3),
    stickPt(395, 2),
    stickPt(395, 31),
    stickPt(230, 34)
  ];
  brush.wash("#334c73", 248);
  drawOrganicShape(sideFaceUpper, 0.05);

  // Blue flame-root reflection on the upper shadowed face
  const sideBlueReflect = [
    stickPt(305, 4),
    stickPt(392, 3),
    stickPt(392, 30),
    stickPt(305, 32)
  ];
  brush.fillBleed(0.15, "in");
  brush.fill("#4b83cc", 145);
  drawOrganicShape(sideBlueReflect, 0.08);

  // --- C. Charred Collar Zone (Where wood meets the burning match head) ---
  const charZone = [
    stickPt(348, -37),
    stickPt(405, -35),
    stickPt(405, 30),
    stickPt(348, 32)
  ];
  brush.wash("#1c1414", 240);
  drawOrganicShape(charZone, 0.15);

  // --- D. Microscopic Longitudinal Wood Grain Fibers ---
  brush.noFill();
  brush.noWash();

  // Lit top-left face grain (140 fibers)
  for (let i = 0; i < 140; i++) {
    let nOff = random(-38, 1.5);
    let s0 = random(-5, 330);
    let s1 = min(385, s0 + random(35, 130));
    let isUpper = (s0 + s1) * 0.5 > 225;

    // Split displacement near the neck (wood fibers prying apart under thermal shock)
    let splitPush = 0;
    if (s1 > 260 && nOff < -18) {
      splitPush = map(s1, 260, 385, 0, -9) * map(nOff, -18, -38, 0.2, 1.2);
    }

    let p0 = stickPt(s0, nOff);
    let pm = stickPt((s0 + s1) * 0.5, nOff + random(-0.8, 0.8) + splitPush * 0.4);
    let p1 = stickPt(s1, nOff + splitPush);

    let col;
    if (s1 > 345) {
      col = random(["#3b2214", "#1f1410", "#6e3b1e", "#b86b35"]);
    } else if (isUpper) {
      col = random(["#f5e3c4", "#c98e52", "#a86b34", "#ebd0a7", "#875125"]);
    } else {
      col = random(["#b8c5d6", "#7e8fa6", "#64748c", "#d0dae6", "#8c7b6b"]);
    }

    brush.set("woodFiber", col, random(0.45, 0.95));
    brush.spline([[p0[0], p0[1], 0.4], [pm[0], pm[1], 0.9], [p1[0], p1[1], 0.4]], 0.35);
  }

  // Shadowed bottom-right face grain (95 fibers)
  for (let i = 0; i < 95; i++) {
    let nOff = random(3.5, 32.5);
    let s0 = random(-5, 335);
    let s1 = min(390, s0 + random(30, 115));
    let p0 = stickPt(s0, nOff);
    let pm = stickPt((s0 + s1) * 0.5, nOff + random(-0.6, 0.6));
    let p1 = stickPt(s1, nOff + (s1 > 290 && nOff > 22 ? random(1, 5) : 0));

    let col;
    if (s1 > 340) {
      col = random(["#141218", "#242c42", "#4775b8", "#1a1820"]);
    } else if (s0 > 240) {
      col = random(["#2d4469", "#466da3", "#1d2c45", "#6395d6"]);
    } else {
      col = random(["#1b2433", "#2d3b52", "#3e4f69", "#141b26"]);
    }

    brush.set("woodFiber", col, random(0.45, 0.9));
    brush.spline([[p0[0], p0[1], 0.4], [pm[0], pm[1], 0.8], [p1[0], p1[1], 0.3]], 0.3);
  }

  // --- E. Deep Splitting Fissures & Lifting Splinters ("the wood grain splits") ---
  // Dark structural cracks where the wood grain splits open near the strike zone
  const splits = [
    { s0: 235, n0: -26, s1: 372, n1: -34, w: 1.5, glow: true },
    { s0: 268, n0: -14, s1: 382, n1: -19, w: 1.8, glow: true },
    { s0: 195, n0: -35, s1: 335, n1: -44, w: 1.3, glow: false },
    { s0: 285, n0: -4,  s1: 388, n1: -6,  w: 1.6, glow: true },
    { s0: 250, n0: 12,  s1: 378, n1: 17,  w: 1.4, glow: true },
    { s0: 215, n0: 24,  s1: 348, n1: 35,  w: 1.2, glow: false }
  ];

  for (let sp of splits) {
    let pA = stickPt(sp.s0, sp.n0);
    let pB = stickPt((sp.s0 + sp.s1) * 0.5, (sp.n0 + sp.n1) * 0.5 + random(-2, 2));
    let pC = stickPt(sp.s1, sp.n1);

    // Dark split crevice
    brush.set("rotring", "#140b08", sp.w);
    brush.spline([[pA[0], pA[1], 0.2], [pB[0], pB[1], 1.0], [pC[0], pC[1], 1.3]], 0.4);

    // Bright lit wood lip along one edge of the split
    brush.set("2H", sp.n0 < 0 ? "#fae6c3" : "#73a6e6", 0.65);
    brush.spline([[pA[0] + 1, pA[1] - 1, 0.2], [pB[0] + 1.5, pB[1] - 1, 0.9], [pC[0] + 1, pC[1] - 1, 0.5]], 0.4);

    // Glowing orange-yellow ember deep inside the split wood fissure
    if (sp.glow) {
      brush.set("rotring", "#ff6d1a", 0.9);
      brush.spline([[pB[0], pB[1], 0.4], [pC[0], pC[1], 1.1]], 0.35);
      brush.set("rotring", "#ffde66", 0.5);
      brush.line(pB[0] * 0.35 + pC[0] * 0.65, pB[1] * 0.35 + pC[1] * 0.65, pC[0], pC[1]);
    }
  }

  // Peeling, jagged wood splinters lifting off the top-left edge, central ridge, and lower edge
  const splinters = [
    // Top-left edge splinters flaring outward
    { sBase: 255, nBase: -38, len: 68, flare: -16, colBase: "#e8c48e", colTip: "#2b160c", ember: true },
    { sBase: 288, nBase: -37, len: 76, flare: -24, colBase: "#f5dba8", colTip: "#1c100b", ember: true },
    { sBase: 318, nBase: -36, len: 58, flare: -29, colBase: "#d99b5e", colTip: "#170d0a", ember: true },
    { sBase: 185, nBase: -39, len: 54, flare: -11, colBase: "#c2cbd9", colTip: "#6e5c4f", ember: false },
    { sBase: 130, nBase: -39, len: 46, flare: -8,  colBase: "#b0bdd0", colTip: "#59687d", ember: false },
    // Central ridge splinters
    { sBase: 270, nBase: 2,   len: 62, flare: -9,  colBase: "#f7e3ba", colTip: "#422111", ember: true },
    { sBase: 312, nBase: 2,   len: 52, flare: -12, colBase: "#e0a363", colTip: "#1f110c", ember: true },
    // Bottom-right shadowed edge splinters catching blue root light
    { sBase: 265, nBase: 33,  len: 58, flare: 14,  colBase: "#3c5e8f", colTip: "#78b5ff", ember: false },
    { sBase: 305, nBase: 31,  len: 64, flare: 21,  colBase: "#4c7bc2", colTip: "#ff8c2b", ember: true },
    { sBase: 205, nBase: 34,  len: 48, flare: 9,   colBase: "#2b3c57", colTip: "#506d99", ember: false }
  ];

  for (let sp of splinters) {
    let p0 = stickPt(sp.sBase, sp.nBase);
    let p1 = stickPt(sp.sBase + sp.len * 0.55, sp.nBase + sp.flare * 0.45);
    let p2 = stickPt(sp.sBase + sp.len, sp.nBase + sp.flare);

    // Shadow under the lifted splinter
    brush.set("rotring", "#120d10", 1.1);
    brush.spline([[p0[0], p0[1], 0.8], [p1[0] + 2, p1[1] + 2, 0.6], [p2[0] + 1, p2[1] + 2, 0.1]], 0.4);

    // Main wood splinter body
    brush.set("cpencil", sp.colBase, 1.15);
    brush.spline([[p0[0], p0[1], 1.1], [p1[0], p1[1], 0.75], [p2[0], p2[1], 0.15]], 0.45);

    // Scorched/highlighted tip of the splinter
    brush.set("rotring", sp.colTip, 0.75);
    brush.spline([[p1[0], p1[1], 0.7], [p2[0], p2[1], 0.15]], 0.4);

    // Incandescent glowing tip on splinters closest to the flame
    if (sp.ember) {
      brush.set("rotring", "#ff6e1a", 0.95);
      brush.line(p2[0] - ux * 6, p2[1] - uy * 6, p2[0], p2[1]);
      brush.set("rotring", "#fff2a6", 0.6);
      brush.line(p2[0] - ux * 2.5, p2[1] - uy * 2.5, p2[0], p2[1]);
    }
  }

  // Crisp central ridge (arriss) of the square-cut matchstick
  for (let s = 0; s < 350; s += 28) {
    let pA = stickPt(s, 2.5);
    let pB = stickPt(s + 30, 2.5 + random(-0.5, 0.5));
    let ridgeCol = s > 235 ? "#fff0cf" : "#dce5f2";
    brush.set("2H", ridgeCol, s > 235 ? 0.9 : 0.65);
    brush.line(pA[0], pA[1], pB[0], pB[1]);
  }

  // Translucent melted paraffin wax sheen & tiny boiling wax beads near the neck (s = 290..365)
  for (let i = 0; i < 18; i++) {
    let ws = random(285, 368);
    let wn = random(-32, 26);
    let wp = stickPt(ws, wn);
    let wCol = wn < 2 ? "#fff6dc" : "#99ccff";
    brush.set("rotring", wCol, random(0.5, 1.1));
    brush.line(wp[0], wp[1], wp[0] + ux * random(3, 9), wp[1] + uy * random(3, 9));
  }
}

