// ---------------------------------------------------------------------------
// Utility: 2D Euclidean distance
// ---------------------------------------------------------------------------
function dist2D(x1, y1, x2, y2) {
  return sqrt((x2 - x1) * (x2 - x1) + (y2 - y1) * (y2 - y1));
}

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(8472);
  noiseSeed(8472);

  brush.addField("slateFlow", (t, field) => {
    for (let col = 0; col < field.length; col++) {
      for (let row = 0; row < field[0].length; row++) {
        let nx = col * 0.07;
        let ny = row * 0.07;
        field[col][row] = -8 + (noise(nx, ny) - 0.5) * 22;
      }
    }
    return field;
  });
}

// ============================================================================
// GEOMETRY & 3D EGG SURFACE HELPERS
// ============================================================================

function clipPolygonHalfPlane(poly, px, py, nx, ny) {
  if (!poly || poly.length === 0) return [];
  let out = [];
  let n = poly.length;
  for (let i = 0; i < n; i++) {
    let cur = poly[i];
    let nxt = poly[(i + 1) % n];
    let dCur = (cur.u - px) * nx + (cur.v - py) * ny;
    let dNxt = (nxt.u - px) * nx + (nxt.v - py) * ny;
    let curIn = dCur <= 0;
    let nxtIn = dNxt <= 0;

    if (curIn && nxtIn) {
      out.push({ u: cur.u, v: cur.v, nb: cur.nb });
    } else if (curIn && !nxtIn) {
      out.push({ u: cur.u, v: cur.v, nb: cur.nb });
      let t = dCur / (dCur - dNxt);
      out.push({
        u: cur.u + t * (nxt.u - cur.u),
        v: cur.v + t * (nxt.v - cur.v),
        nb: -2 // marker for newly cut edge
      });
    } else if (!curIn && nxtIn) {
      let t = dCur / (dCur - dNxt);
      out.push({
        u: cur.u + t * (nxt.u - cur.u),
        v: cur.v + t * (nxt.v - cur.v),
        nb: cur.nb
      });
    }
  }
  return out;
}

// Map unwrapped hemisphere disk (u, v) with r <= 1 onto 3D egg + 2D canvas
function projectEggPoint(egg, u, v, lift = 0) {
  let r = sqrt(u * u + v * v);
  let rClamped = min(1.0, r);
  let alpha = rClamped * 90; // 0 at top dome, 90 deg at silhouette rim
  let rProj = sin(alpha);
  let zSph = cos(alpha);

  let xi = r > 1e-5 ? (u / r) * rProj : 0;
  let rho = r > 1e-5 ? (v / r) * rProj : 0;

  // Avian ovoid taper along major axis xi
  let sXi = xi * egg.pointDir;
  let taper = 1.0 - 0.175 * sXi - 0.045 * xi * xi;
  let eta = rho * taper;
  let z = zSph * taper;

  // Approximate local 3D surface normal before rotation
  let nxLocal = -xi * 0.85 + 0.14 * egg.pointDir;
  let nyLocal = -rho * 0.95;
  let nzLocal = max(0.08, zSph * 1.05);
  let nLen = sqrt(nxLocal * nxLocal + nyLocal * nyLocal + nzLocal * nzLocal);
  nxLocal /= nLen;
  nyLocal /= nLen;
  nzLocal /= nLen;

  // Rotate into world/canvas space by egg.rot
  let c = cos(egg.rot);
  let s = sin(egg.rot);

  let xLocal = egg.a * xi;
  let yLocal = egg.b * eta;

  let wx = egg.cx + xLocal * c - yLocal * s;
  let wy = egg.cy + xLocal * s + yLocal * c;
  let wz = egg.b * z;

  let wnx = nxLocal * c - nyLocal * s;
  let wny = nxLocal * s + nyLocal * c;
  let wnz = nzLocal;

  // Apply physical shard lift outward along normal
  wx += wnx * lift * 0.85;
  wy += wny * lift * 0.85;
  wz += wnz * lift;

  return {
    x: wx,
    y: wy,
    z: wz,
    nx: wnx,
    ny: wny,
    nz: wnz,
    xi: xi,
    eta: eta,
    r: rClamped
  };
}

function computeEggLighting(pt, shardTiltX = 0, shardTiltY = 0) {
  // Low sideways light from the left / slightly upper-left
  let lx = -0.89;
  let ly = -0.18;
  let lz = 0.42;

  let nx = pt.nx + shardTiltX;
  let ny = pt.ny + shardTiltY;
  let nz = pt.nz;
  let len = sqrt(nx * nx + ny * ny + nz * nz);
  nx /= len;
  ny /= len;
  nz /= len;

  let ndotl = nx * lx + ny * ly + nz * lz;
  let direct = max(0, ndotl);

  // Specular half-vector (viewer is at (0, 0, 1))
  let hx = lx;
  let hy = ly;
  let hz = lz + 1.0;
  let hLen = sqrt(hx * hx + hy * hy + hz * hz);
  hx /= hLen;
  hy /= hLen;
  hz /= hLen;
  let ndoth = max(0, nx * hx + ny * hy + nz * hz);
  let spec = pow(ndoth, 24);

  // Reflected bounce light from slate & adjacent egg on right-lower side
  let bounce = max(0, nx * 0.65 + ny * 0.45 - nz * 0.2) * 0.28;

  return {
    direct: direct,
    spec: spec,
    bounce: bounce,
    ndotl: ndotl,
    nx: nx,
    ny: ny,
    nz: nz
  };
}

// Build Voronoi crackle shard mesh on unit disk (u, v)
function buildEggShardMesh(egg, eggIdx) {
  let seeds = [];
  let tu = egg.tapU;
  let tv = egg.tapV;

  // Seed 0: exact tap center
  seeds.push({
    u: tu,
    v: tv,
    ring: 0,
    ang: 0,
    radDist: 0
  });

  // Concentric jittered rings around tap center for realistic impact radial + cross fractures
  let ringRadii = [0.068, 0.145, 0.235, 0.345, 0.475, 0.625, 0.79, 0.96, 1.15];
  let ringCounts = [6, 11, 15, 19, 22, 25, 28, 30, 32];

  for (let rIdx = 0; rIdx < ringRadii.length; rIdx++) {
    let rad = ringRadii[rIdx];
    let cnt = ringCounts[rIdx];
    let phaseOff = (rIdx % 2) * (180 / cnt) + eggIdx * 23;
    for (let k = 0; k < cnt; k++) {
      let baseAng = (k * 360) / cnt + phaseOff;
      let ang = baseAng + random(-11, 11);
      let rr = rad * (1 + random(-0.12, 0.12));
      let su = tu + rr * cos(ang);
      let sv = tv + rr * sin(ang);
      if (su * su + sv * sv <= 1.28) {
        seeds.push({
          u: su,
          v: sv,
          ring: rIdx + 1,
          ang: ang,
          radDist: rr
        });
      }
    }
  }

  // Base bounding circle polygon (unit disk r = 0.992)
  let baseCircle = [];
  let circleSteps = 56;
  for (let i = 0; i < circleSteps; i++) {
    let a = (i * 360) / circleSteps;
    baseCircle.push({
      u: 0.992 * cos(a),
      v: 0.992 * sin(a),
      nb: -1 // outer silhouette boundary
    });
  }

  let cells = [];
  for (let i = 0; i < seeds.length; i++) {
    let si = seeds[i];
    let poly = baseCircle.map((p) => ({ u: p.u, v: p.v, nb: p.nb }));

    for (let j = 0; j < seeds.length; j++) {
      if (i === j) continue;
      let sj = seeds[j];
      let dx = sj.u - si.u;
      let dy = sj.v - si.v;
      let distSq = dx * dx + dy * dy;
      if (distSq > 0.65) continue; // fast cull for distant seeds
      let mx = 0.5 * (si.u + sj.u);
      let my = 0.5 * (si.v + sj.v);
      poly = clipPolygonHalfPlane(poly, mx, my, dx, dy);
      for (let v = 0; v < poly.length; v++) {
        if (poly[v].nb === -2) poly[v].nb = j;
      }
      if (poly.length === 0) break;
    }

    if (poly.length < 3) continue;

    // Centroid in (u, v)
    let cu = 0;
    let cv = 0;
    for (let p of poly) {
      cu += p.u;
      cv += p.v;
    }
    cu /= poly.length;
    cv /= poly.length;

    let du = cu - tu;
    let dv = cv - tv;
    let tapDist = sqrt(du * du + dv * dv);
    let tapAng = atan2(dv, du);

    // Angle-dependent crazing boundary ("half-tapped" shell)
    let lobeNoise = noise(eggIdx * 10 + cos(tapAng) * 1.3 + 2, sin(tapAng) * 1.3 + 2);
    let asymFactor = cos(tapAng - egg.crazeDir) * 0.16;
    let crazeRadius = egg.crazeBase * (0.72 + 0.55 * lobeNoise + asymFactor);

    let isCrazed = tapDist < crazeRadius;
    let crazeStrength = isCrazed
      ? constrain(1.0 - tapDist / crazeRadius, 0, 1)
      : 0;

    // Physical buckling / lifting of each crazed shard
    let lift = 0;
    let tiltX = 0;
    let tiltY = 0;
    let isMissing = false;

    if (isCrazed) {
      // Impact center is slightly depressed; surrounding ring is buckled/lifted
      if (tapDist < 0.085) {
        lift = -1.2 + random(-0.4, 0.6);
        if (egg.hasExposedMembrane && si.ring === 0) {
          isMissing = true;
        }
      } else {
        let buckleEnv = sin(constrain((tapDist - 0.05) / (crazeRadius * 0.9), 0, 1) * 180);
        lift = (1.2 + buckleEnv * 3.2) * random(0.35, 1.25);
      }
      let tiltMag = (0.12 + 0.26 * crazeStrength) * random(0.5, 1.35);
      let tiltAngle = tapAng + random(-55, 55);
      tiltX = cos(tiltAngle) * tiltMag;
      tiltY = sin(tiltAngle) * tiltMag;
    }

    cells.push({
      id: i,
      seedIdx: i,
      poly: poly,
      cu: cu,
      cv: cv,
      tapDist: tapDist,
      tapAng: tapAng,
      crazeRadius: crazeRadius,
      isCrazed: isCrazed,
      crazeStrength: crazeStrength,
      lift: lift,
      tiltX: tiltX,
      tiltY: tiltY,
      isMissing: isMissing
    });
  }

  // Map seed index -> cell object
  let seedToCell = new Map();
  for (let c of cells) seedToCell.set(c.seedIdx, c);

  // Extract unique internal fracture edges
  let edges = [];
  let edgeSet = new Set();

  for (let cellA of cells) {
    let n = cellA.poly.length;
    for (let k = 0; k < n; k++) {
      let p1 = cellA.poly[k];
      let p2 = cellA.poly[(k + 1) % n];
      let nbSeed = p1.nb;
      if (nbSeed < 0) continue; // outer boundary
      let cellB = seedToCell.get(nbSeed);
      if (!cellB) continue;

      let minId = min(cellA.seedIdx, cellB.seedIdx);
      let maxId = max(cellA.seedIdx, cellB.seedIdx);
      let key = minId + "_" + maxId;
      if (edgeSet.has(key)) continue;
      edgeSet.add(key);

      let mu = 0.5 * (p1.u + p2.u);
      let mv = 0.5 * (p1.v + p2.v);
      let du = mu - tu;
      let dv = mv - tv;
      let distTap = sqrt(du * du + dv * dv);

      // Check radial alignment of the edge relative to tap point
      let eu = p2.u - p1.u;
      let ev = p2.v - p1.v;
      let eLen = sqrt(eu * eu + ev * ev);
      if (eLen < 0.008) continue;
      let rLen = max(1e-5, distTap);
      let radialDot = abs((eu * du + ev * dv) / (eLen * rLen));

      let localCrazeRad = 0.5 * (cellA.crazeRadius + cellB.crazeRadius);
      let inCraze = cellA.isCrazed || cellB.isCrazed;
      // Radial primary cracks propagate further into the un-tapped side of the shell
      let isExtendedRadial =
        !inCraze &&
        distTap < localCrazeRad * 1.48 &&
        radialDot > 0.68 &&
        noise(eggIdx * 30 + mu * 4, mv * 4) > 0.36;

      if (!inCraze && !isExtendedRadial) continue;

      let strength = inCraze
        ? constrain(1.05 - distTap / (localCrazeRad * 1.15), 0.18, 1.0)
        : constrain(1.0 - (distTap - localCrazeRad) / (localCrazeRad * 0.5), 0.08, 0.35);

      // Subdivide edge into brittle micro-deflected fracture segments in (u, v)
      let steps = inCraze ? 4 : 3;
      let subPtsUv = [];
      let nxUv = -ev / eLen;
      let nyUv = eu / eLen;
      for (let s = 0; s <= steps; s++) {
        let t = s / steps;
        let bu = p1.u + t * eu;
        let bv = p1.v + t * ev;
        if (s > 0 && s < steps) {
          let jag = (noise(eggIdx * 50 + bu * 18, bv * 18) - 0.5) * eLen * 0.22;
          bu += nxUv * jag;
          bv += nyUv * jag;
        }
        subPtsUv.push({ u: bu, v: bv });
      }

      edges.push({
        p1: p1,
        p2: p2,
        subPtsUv: subPtsUv,
        cellA: cellA,
        cellB: cellB,
        mu: mu,
        mv: mv,
        distTap: distTap,
        strength: strength,
        inCraze: inCraze,
        radialDot: radialDot
      });
    }
  }

  return { cells, edges };
}

// ============================================================================
// COLOR MIXING HELPERS
// ============================================================================

function lerpRgb(c1, c2, t) {
  t = constrain(t, 0, 1);
  return [
    round(c1[0] + (c2[0] - c1[0]) * t),
    round(c1[1] + (c2[1] - c1[1]) * t),
    round(c1[2] + (c2[2] - c1[2]) * t)
  ];
}

function rgbHex(rgb) {
  let r = constrain(round(rgb[0]), 0, 255).toString(16).padStart(2, "0");
  let g = constrain(round(rgb[1]), 0, 255).padStart ? constrain(round(rgb[1]), 0, 255).toString(16).padStart(2, "0") : "00";
  let b = constrain(round(rgb[2]), 0, 255).toString(16).padStart(2, "0");
  return "#" + r + g + b;
}

