// ============================================================================
// LAYER 1: SMOKY BLACKENED SLATE & IRIDESCENT FLASH
// ============================================================================

function drawSmokySlateGround(eggs) {
  brush.noStroke();
  brush.noHatch();
  brush.noFill();

  // Deep atmospheric slate slabs (fast solid washes)
  let slateSlabs = [
    { pts: [[0, 0], [1200, 0], [1200, 520], [0, 620]], col: "#10151e", op: 190 },
    { pts: [[0, 420], [1200, 310], [1200, 920], [0, 1040]], col: "#141b24", op: 170 },
    { pts: [[0, 720], [1200, 610], [1200, 1200], [0, 1200]], col: "#0d1016", op: 210 },
    { pts: [[60, 480], [920, 380], [1080, 760], [120, 880]], col: "#1b1620", op: 110 }
  ];

  for (let s of slateSlabs) {
    brush.wash(s.col, s.op);
    brush.beginShape(0.2);
    for (let p of s.pts) brush.vertex(p[0], p[1]);
    brush.endShape(true);
  }

  // Luminous under-washes for the coppery-iridescent flash on the slate
  // (Essential on dark grounds so subsequent watercolor fills glow vividly)
  let flashUnder = [
    { x: 560, y: 705, rx: 280, ry: 95, rot: -10, col: "#4a2014", op: 145 },
    { x: 590, y: 715, rx: 215, ry: 72, rot: -8, col: "#7c3114", op: 155 },
    { x: 470, y: 690, rx: 145, ry: 54, rot: -14, col: "#114b52", op: 140 },
    { x: 695, y: 735, rx: 165, ry: 58, rot: -6, col: "#6b1d36", op: 130 },
    { x: 575, y: 700, rx: 135, ry: 44, rot: -9, col: "#b84a16", op: 140 },
    { x: 240, y: 695, rx: 130, ry: 45, rot: -12, col: "#2b2f1c", op: 95 }
  ];

  for (let f of flashUnder) {
    brush.wash(f.col, f.op);
    brush.beginShape(0.45);
    for (let a = 0; a < 360; a += 30) {
      let rMod = 0.85 + 0.3 * noise(f.x * 0.01 + cos(a), f.y * 0.01 + sin(a));
      let lx = f.rx * rMod * cos(a);
      let ly = f.ry * rMod * sin(a);
      let wx = f.x + lx * cos(f.rot) - ly * sin(f.rot);
      let wy = f.y + lx * sin(f.rot) + ly * cos(f.rot);
      brush.vertex(wx, wy);
    }
    brush.endShape(true);
  }
  brush.noWash();

  // Watercolor blooms on the slate (batched by color for performance & texture)
  let slateWatercolors = [
    // Deep smoky Prussian & charcoal blooms
    { x: 310, y: 390, rx: 260, ry: 110, rot: -9, col: "#182534", op: 95, bleed: 0.42 },
    { x: 860, y: 340, rx: 280, ry: 115, rot: -11, col: "#182534", op: 90, bleed: 0.42 },
    { x: 260, y: 890, rx: 290, ry: 110, rot: -7, col: "#141e2b", op: 105, bleed: 0.38 },
    // Iridescent Peacock / Verdigris Teal flash on slate
    { x: 455, y: 692, rx: 145, ry: 52, rot: -12, col: "#159a9c", op: 135, bleed: 0.38 },
    { x: 650, y: 670, rx: 115, ry: 42, rot: -8, col: "#1eb5b0", op: 120, bleed: 0.35 },
    // Vivid Copper & Molten Amber flash on slate
    { x: 565, y: 708, rx: 210, ry: 66, rot: -9, col: "#e65317", op: 155, bleed: 0.42 },
    { x: 615, y: 722, rx: 150, ry: 48, rot: -6, col: "#f7881f", op: 150, bleed: 0.36 },
    { x: 525, y: 685, rx: 95, ry: 34, rot: -11, col: "#ffb627", op: 135, bleed: 0.3 },
    // Rose-Bronze & Magenta iridescence
    { x: 705, y: 738, rx: 135, ry: 45, rot: -5, col: "#c22957", op: 125, bleed: 0.38 }
  ];

  for (let w of slateWatercolors) {
    brush.fill(w.col, w.op);
    brush.fillBleed(w.bleed, "out");
    brush.fillTexture(0.85, 0.78);
    brush.beginShape(0.45);
    for (let a = 0; a < 360; a += 30) {
      let rMod = 0.82 + 0.35 * noise(w.x * 0.02 + cos(a) * 1.2, w.y * 0.02 + sin(a) * 1.2);
      let lx = w.rx * rMod * cos(a);
      let ly = w.ry * rMod * sin(a);
      let wx = w.x + lx * cos(w.rot) - ly * sin(w.rot);
      let wy = w.y + lx * sin(w.rot) + ly * cos(w.rot);
      brush.vertex(wx, wy);
    }
    brush.endShape(true);
  }
  brush.noFill();

  // Foliated slate mineral grain using vector field
  brush.field("slateFlow");
  for (let i = 0; i < 190; i++) {
    let sx = random(20, 1180);
    let sy = random(20, 1180);
    let len = random(65, 220);

    // Check proximity to the coppery flash zone
    let dFlash = dist(sx, sy, 575, 705);
    if (dFlash < 230 && random() < 0.55) {
      let colChoice = random(["#e85d1a", "#f79d28", "#1caba8", "#c93860"]);
      brush.set("cpencil", colChoice, random(0.45, 0.95));
    } else {
      let colChoice = random(["#080a0e", "#1c2633", "#263342", "#141820", "#2b2329"]);
      brush.set("charcoal", colChoice, random(0.5, 1.35));
    }
    brush.flowLine(sx, sy, len, random(-12, 4));
  }
  brush.noField();

  // Stepped geological cleavage ledges across the blackened slate
  let ledges = [
    { yStart: 245, yEnd: 135, steps: 28, flash: false },
    { yStart: 430, yEnd: 315, steps: 32, flash: false },
    { yStart: 735, yEnd: 605, steps: 36, flash: true },
    { yStart: 885, yEnd: 760, steps: 34, flash: true },
    { yStart: 1060, yEnd: 945, steps: 28, flash: false }
  ];

  for (let lIdx = 0; lIdx < ledges.length; lIdx++) {
    let lg = ledges[lIdx];
    let pts = [];
    for (let s = 0; s <= lg.steps; s++) {
      let t = s / lg.steps;
      let x = t * 1200;
      let stepJump = floor(noise(lIdx * 10 + t * 6) * 4) * 9;
      let jitterY = (noise(lIdx * 20 + t * 18) - 0.5) * 22;
      let y = lerp(lg.yStart, lg.yEnd, t) + stepJump + jitterY;
      pts.push([x, y]);
    }

    // Crisp dark drop shadow under the slate cleavage step
    brush.set("rotring", "#050608", 1.15);
    brush.spline(pts.map((p) => [p[0], p[1] + 2.5, random(0.6, 1.2)]), 0.15);

    // Smoky charcoal rub along the ledge
    brush.set("charcoal", "#090b0f", 0.95);
    brush.spline(pts.map((p) => [p[0], p[1] + 4.5, random(0.4, 0.9)]), 0.2);

    // Raking sideways light catching the top/left edge of the slate step
    for (let s = 0; s < pts.length - 1; s++) {
      let p1 = pts[s];
      let p2 = pts[s + 1];
      let mx = 0.5 * (p1[0] + p2[0]);
      let my = 0.5 * (p1[1] + p2[1]);
      let dFlash = dist(mx, my, 575, 705);

      if (lg.flash && dFlash < 260) {
        let hCol = dFlash < 140 ? "#ff9f38" : random(["#e05819", "#28c2bd", "#d94169"]);
        brush.set("cpencil", hCol, random(0.55, 1.05));
      } else {
        let lightFade = map(mx, 0, 1200, 1.0, 0.35);
        let hCol = random() < 0.6 ? "#3c4e61" : "#56453e";
        brush.set("2H", hCol, 0.55 * lightFade);
      }
      brush.line(p1[0], p1[1] - 1.2, p2[0], p2[1] - 1.2);
    }
  }
}

// ============================================================================
// LAYER 2: LONG SIDEWAYS CAST SHADOWS ON THE SLATE
// ============================================================================

function drawSlateCastShadows(eggs) {
  brush.noStroke();
  brush.noHatch();
  brush.noFill();

  // Because light is low and sideways from the left (-0.89, -0.18),
  // each egg casts a long elliptical shadow to the right (+x, +y*0.18)
  for (let i = 0; i < eggs.length; i++) {
    let egg = eggs[i];

    // Soft outer penumbra
    for (let pass = 3; pass >= 0; pass--) {
      let stretchX = 145 + pass * 34;
      let stretchY = 58 + pass * 11;
      let offX = 88 + pass * 22;
      let offY = 24 + pass * 5;
      let col = pass >= 2 ? "#090b10" : "#040507";
      let op = pass === 3 ? 85 : pass === 2 ? 125 : pass === 1 ? 175 : 225;

      // On the focal egg, imbue the outer shadow penumbra with a warm copper caustic
      if (i === 2 && pass === 3) {
        col = "#36150c";
        op = 95;
      }

      brush.wash(col, op);
      brush.beginShape(0.4);
      for (let a = 0; a < 360; a += 20) {
        let sx = egg.cx + offX + stretchX * cos(a);
        let sy = egg.cy + offY + stretchY * sin(a);
        let rotA = 11;
        let rx = egg.cx + (sx - egg.cx) * cos(rotA) - (sy - egg.cy) * sin(rotA);
        let ry = egg.cy + (sx - egg.cx) * sin(rotA) + (sy - egg.cy) * cos(rotA);
        brush.vertex(rx, ry);
      }
      brush.endShape(true);
    }

    // Tight dark occlusion crease directly beneath the egg's resting contact patch
    brush.wash("#020304", 245);
    brush.beginShape(0.35);
    for (let a = 0; a < 360; a += 24) {
      let cx = egg.cx + 12 + egg.a * 0.72 * cos(a);
      let cy = egg.cy + 26 + egg.b * 0.36 * sin(a);
      brush.vertex(cx, cy);
    }
    brush.endShape(true);
  }
  brush.noWash();
}

// ============================================================================
// LAYER 3: 3D FACETED EGGSHELL SHARD BASES & EXPOSED MEMBRANES
// ============================================================================

function drawEggShardBases(eggs, eggMeshes) {
  brush.noStroke();
  brush.noHatch();
  brush.noFill();

  for (let eIdx = 0; eIdx < eggs.length; eIdx++) {
    let egg = eggs[eIdx];
    let mesh = eggMeshes[eIdx];

    // 1. Solid dark-warm under-silhouette so no background leaks through fissures
    brush.wash("#1b1512", 245);
    brush.beginShape(0.2);
    for (let a = 0; a < 360; a += 6) {
      let u = 0.992 * cos(a);
      let v = 0.992 * sin(a);
      let pt = projectEggPoint(egg, u, v, 0);
      brush.vertex(pt.x, pt.y);
    }
    brush.endShape(true);

    // 2. Check if adjacent left egg casts a sideways shadow onto this egg's left-lower flank
    let leftEgg = eIdx > 0 ? eggs[eIdx - 1] : null;

    // 3. Render every shard polygon with its exact 3D ovoid + tilted-facet illumination
    for (let cell of mesh.cells) {
      let ptC = projectEggPoint(egg, cell.cu, cell.cv, cell.lift);
      let light = computeEggLighting(ptC, cell.tiltX, cell.tiltY);

      // Shadow cast from the neighbor egg to the left
      let neighborShadow = 0;
      if (leftEgg) {
        let shadowCx = leftEgg.cx + 125;
        let shadowCy = leftEgg.cy + 24;
        let dSh = dist(ptC.x, ptC.y, shadowCx, shadowCy);
        if (dSh < 92) {
          neighborShadow = constrain(map(dSh, 35, 92, 0.58, 0), 0, 0.58);
        }
      }

      if (cell.isMissing) {
        // Exposed hard-boiled inner membrane / tea-smoked albumen where shard flaked away
        let memCol = eIdx === 2 ? "#d6b898" : "#DFCAAE";
        brush.wash(memCol, 240);
        brush.beginShape(0.15);
        for (let p of cell.poly) {
          let vp = projectEggPoint(egg, p.u, p.v, 0);
          brush.vertex(vp.x, vp.y);
        }
        brush.endShape(true);
        continue;
      }

      // Regional shell color variation in (u, v)
      let nOlive = noise(eIdx * 15 + cell.cu * 2.2 + 5, cell.cv * 2.2 + 5);
      let nCocoa = noise(eIdx * 25 + cell.cu * 2.8 + 15, cell.cv * 2.8 + 15);

      // Base warm cream-parchment, olive, and cocoa tones
      let litCream = [248, 236, 212];
      let midOlive = [138, 146, 68];
      let midCocoa = [134, 78, 48];
      let shadSlate = [32, 34, 38];
      let bounceCopper = eIdx === 2 ? [218, 92, 34] : [142, 82, 44];

      // Mix local pigment tint
      let baseTint = lerpRgb(litCream, midOlive, constrain((nOlive - 0.35) * 1.4 * egg.oliveBias, 0, 0.72));
      baseTint = lerpRgb(baseTint, midCocoa, constrain((nCocoa - 0.42) * 1.3 * egg.cocoaBias, 0, 0.58));

      // Apply 3D direct light, shadow roll-off, and neighbor shadow
      let effLight = constrain(light.direct * (1.0 - neighborShadow), 0, 1);
      let shadedRgb = lerpRgb(shadSlate, baseTint, pow(effLight, 0.72));

      // Add warm reflected bounce light on the lower-right shadow side
      shadedRgb = lerpRgb(shadedRgb, bounceCopper, light.bounce * (0.65 + 0.6 * egg.iridescence));

      // If this egg has the coppery-iridescent flash, tint the upper-left/mid crazed shards
      if (egg.iridescence > 0.2) {
        let dFlashUv = dist(cell.cu, cell.cv, -0.18, -0.08);
        if (dFlashUv < 0.75) {
          let iridAmt = constrain(1.0 - dFlashUv / 0.75, 0, 1) * egg.iridescence;
          let iridCol =
            cell.cu + cell.cv < -0.15
              ? [242, 108, 32] // glowing burnt copper
              : cell.cv > 0.1
              ? [32, 178, 172] // verdigris peacock glint
              : [248, 162, 48]; // molten amber-gold
          shadedRgb = lerpRgb(shadedRgb, iridCol, iridAmt * 0.52);
        }
      }

      // Darken slightly right inside the smoked crazed impact basin
      if (cell.isCrazed) {
        let smokeAmt = cell.crazeStrength * 0.24;
        shadedRgb = lerpRgb(shadedRgb, [36, 26, 22], smokeAmt);
      }

      // Specular sheen on lit facets
      shadedRgb = lerpRgb(shadedRgb, [255, 250, 238], light.spec * 0.55);

      let hexCol = rgbHex(shadedRgb);
      brush.wash(hexCol, 235);
      brush.beginShape(0);
      for (let p of cell.poly) {
        // Shrink shard polygon slightly when crazed so dark smoked fissure shows between shards
        let shrink = cell.isCrazed ? 0.965 : 1.0;
        let su = cell.cu + (p.u - cell.cu) * shrink;
        let sv = cell.cv + (p.v - cell.cv) * shrink;
        let vp = projectEggPoint(egg, su, sv, cell.lift);
        brush.vertex(vp.x, vp.y);
      }
      brush.endShape(true);
    }
  }
  brush.noWash();
}

// ============================================================================
// LAYER 4: WATERCOLOR WASHES ON SHELLS (CREAM, OLIVE, COCOA & IRIDESCENCE)
// ============================================================================

function drawEggWatercolorWashes(eggs) {
  brush.noStroke();
  brush.noHatch();
  brush.noWash();

  // Build batched watercolor wash shapes across the 5 shells
  let creamWashes = [];
  let oliveWashes = [];
  let cocoaWashes = [];
  let copperFlashWashes = [];
  let tealFlashWashes = [];

  for (let i = 0; i < eggs.length; i++) {
    let egg = eggs[i];
    creamWashes.push({ egg, u: -0.36, v: -0.18, rad: 0.42 });
    oliveWashes.push({ egg, u: 0.08, v: -0.22, rad: 0.48 });
    cocoaWashes.push({ egg, u: 0.24, v: 0.22, rad: 0.46 });

    if (egg.iridescence > 0.25) {
      copperFlashWashes.push({
        egg,
        u: -0.15,
        v: -0.12,
        rad: egg.iridescence > 0.8 ? 0.56 : 0.36,
        op: egg.iridescence > 0.8 ? 140 : 90
      });
      tealFlashWashes.push({
        egg,
        u: 0.05,
        v: 0.22,
        rad: egg.iridescence > 0.8 ? 0.44 : 0.28,
        op: egg.iridescence > 0.8 ? 125 : 80
      });
    }
  }

  function drawShellWashBatch(list, col, defaultOp, bleed) {
    for (let item of list) {
      brush.fill(col, item.op || defaultOp);
      brush.fillBleed(bleed, "out");
      brush.fillTexture(0.82, 0.72);
      brush.beginShape(0.4);
      for (let a = 0; a < 360; a += 30) {
        let rMod = item.rad * (0.78 + 0.38 * noise(item.egg.cx * 0.02 + cos(a), sin(a) + item.u));
        let u = constrain(item.u + rMod * cos(a), -0.95, 0.95);
        let v = constrain(item.v + rMod * sin(a), -0.95, 0.95);
        if (u * u + v * v > 0.92) {
          let sc = 0.95 / sqrt(u * u + v * v);
          u *= sc;
          v *= sc;
        }
        let pt = projectEggPoint(item.egg, u, v, 1.5);
        brush.vertex(pt.x, pt.y);
      }
      brush.endShape(true);
    }
  }

  // Execute batched watercolor passes
  drawShellWashBatch(creamWashes, "#f7ebd2", 85, 0.32);
  drawShellWashBatch(oliveWashes, "#758722", 95, 0.36);
  drawShellWashBatch(cocoaWashes, "#73371c", 95, 0.36);
  drawShellWashBatch(copperFlashWashes, "#eb5817", 135, 0.4);
  drawShellWashBatch(tealFlashWashes, "#17a8a3", 115, 0.36);

  // Extra molten gold & rose-bronze glint along the hero egg (#3)
  let heroEgg = eggs[2];
  drawShellWashBatch([{ egg: heroEgg, u: -0.26, v: -0.05, rad: 0.36, op: 130 }], "#ffa629", 130, 0.34);
  drawShellWashBatch([{ egg: heroEgg, u: 0.14, v: -0.04, rad: 0.32, op: 110 }], "#c92c5c", 110, 0.35);

  brush.noFill();
}

// ============================================================================
// LAYER 5: QUAIL EGG SPECKLES, BLOTCHES & CALCIUM SHELL GRAIN
// ============================================================================

function drawEggSpecklesAndTexture(eggs, eggMeshes) {
  brush.noStroke();
  brush.noHatch();
  brush.noFill();

  for (let eIdx = 0; eIdx < eggs.length; eIdx++) {
    let egg = eggs[eIdx];
    let mesh = eggMeshes[eIdx];

    // 1. Sub-surface muted olive-taupe & warm umber blotches
    let numSubBlotches = 26;
    for (let b = 0; b < numSubBlotches; b++) {
      let ang = random(360);
      let rad = sqrt(random(0.02, 0.88));
      let bu = rad * cos(ang);
      let bv = rad * sin(ang);

      // Skip blotch if it lands on a missing shard
      if (egg.hasExposedMembrane && dist(bu, bv, egg.tapU, egg.tapV) < 0.09) continue;

      let ptCenter = projectEggPoint(egg, bu, bv, 1.0);
      let light = computeEggLighting(ptCenter);

      let bRad = random(0.06, 0.16);
      let isOlive = random() < 0.55;
      let litCol = isOlive ? [112, 122, 42] : [118, 72, 46];
      let shdCol = isOlive ? [34, 38, 16] : [36, 20, 14];
      let blotchRgb = lerpRgb(shdCol, litCol, pow(light.direct, 0.75));

      brush.wash(rgbHex(blotchRgb), random(115, 165));
      brush.beginShape(0.35);
      let steps = 10;
      for (let s = 0; s < steps; s++) {
        let a = (s * 360) / steps;
        let rVar = bRad * (0.65 + 0.65 * noise(eIdx * 40 + b * 7 + cos(a) * 1.4, sin(a) * 1.4));
        let pu = bu + rVar * cos(a);
        let pv = bv + rVar * sin(a);
        if (pu * pu + pv * pv > 0.96) {
          let sc = 0.96 / sqrt(pu * pu + pv * pv);
          pu *= sc;
          pv *= sc;
        }
        let vp = projectEggPoint(egg, pu, pv, 1.2);
        brush.vertex(vp.x, vp.y);
      }
      brush.endShape(true);
    }

    // 2. Crisp surface quail blotches & organic archipelagos in deep cocoa, russet & espresso
    let numMainBlotches = 44;
    for (let b = 0; b < numMainBlotches; b++) {
      // Quail eggs often have denser band of blotches near the blunt crown and mid-equator
      let ang = random(360);
      let rad = sqrt(random(0.01, 0.94));
      let bu = rad * cos(ang);
      let bv = rad * sin(ang);

      if (egg.hasExposedMembrane && dist(bu, bv, egg.tapU, egg.tapV) < 0.095) continue;

      let ptCenter = projectEggPoint(egg, bu, bv, 1.4);
      let light = computeEggLighting(ptCenter);

      let bRad = random(0.032, 0.125);
      let tonePick = random();
      let litCol =
        tonePick < 0.45
          ? [78, 36, 20] // deep rich cocoa
          : tonePick < 0.78
          ? [108, 48, 24] // warm russet-cocoa
          : [58, 66, 22]; // dark olive-umber
      let shdCol = [16, 9, 7];
      let blotchRgb = lerpRgb(shdCol, litCol, pow(light.direct, 0.8));

      // On the hero shell, some cocoa blotches catch a coppery sheen at their rim
      if (egg.iridescence > 0.5 && dist(bu, bv, -0.15, -0.1) < 0.45) {
        blotchRgb = lerpRgb(blotchRgb, [175, 68, 22], 0.28);
      }

      brush.wash(rgbHex(blotchRgb), random(175, 235));
      brush.beginShape(0.3);
      let steps = 12;
      for (let s = 0; s < steps; s++) {
        let a = (s * 360) / steps;
        let rVar = bRad * (0.55 + 0.8 * noise(eIdx * 70 + b * 11 + cos(a) * 1.7, sin(a) * 1.7));
        let pu = bu + rVar * cos(a);
        let pv = bv + rVar * sin(a);
        if (pu * pu + pv * pv > 0.97) {
          let sc = 0.97 / sqrt(pu * pu + pv * pv);
          pu *= sc;
          pv *= sc;
        }
        let vp = projectEggPoint(egg, pu, pv, 1.5);
        brush.vertex(vp.x, vp.y);
      }
      brush.endShape(true);
    }
    brush.noWash();

    // 3. Fine peppered cocoa/espresso speckles & porous calcium shell texture
    for (let sp = 0; sp < 135; sp++) {
      let ang = random(360);
      let rad = sqrt(random(0.01, 0.96));
      let su = rad * cos(ang);
      let sv = rad * sin(ang);
      if (egg.hasExposedMembrane && dist(su, sv, egg.tapU, egg.tapV) < 0.09) continue;

      let pt = projectEggPoint(egg, su, sv, 1.6);
      let light = computeEggLighting(pt);

      let spCol =
        light.direct > 0.45
          ? random(["#3b1a0e", "#542714", "#4a541b", "#261109"])
          : random(["#170b07", "#24120b", "#0f0806"]);

      brush.set("rotring", spCol, random(0.45, 1.35));
      let jitterLen = random(0.8, 3.2);
      let jitterAng = random(360);
      brush.line(
        pt.x,
        pt.y,
        pt.x + jitterLen * cos(jitterAng),
        pt.y + jitterLen * sin(jitterAng)
      );
    }

    // 4. Delicate form-following colored pencil contour grain on lit and shadow hemispheres
    for (let g = 0; g < 55; g++) {
      let ang = random(360);
      let rad = random(0.15, 0.94);
      let gu = rad * cos(ang);
      let gv = rad * sin(ang);
      let pt1 = projectEggPoint(egg, gu, gv, 1.5);
      let light = computeEggLighting(pt1);

      let stepAng = ang + 14;
      let pt2 = projectEggPoint(egg, rad * cos(stepAng), rad * sin(stepAng), 1.5);

      if (light.direct > 0.62) {
        let lCol = egg.iridescence > 0.6 && gu < 0 ? random(["#ffba66", "#fff6e0"]) : "#f7ebd4";
        brush.set("cpencil", lCol, random(0.35, 0.7));
        brush.line(pt1.x, pt1.y, pt2.x, pt2.y);
      } else if (light.direct < 0.25) {
        let sCol = egg.iridescence > 0.4 ? random(["#163b3d", "#2e1610"]) : "#121317";
        brush.set("2B", sCol, random(0.4, 0.75));
        brush.line(pt1.x, pt1.y, pt2.x, pt2.y);
      }
    }
  }
}

// ============================================================================
// LAYER 6: SMOKED FISSURES, LIFTED SHARD SHADOWS, RIM HIGHLIGHTS & RAKU INK
// ============================================================================

function drawCrazedRakuNetwork(eggs, eggMeshes) {
  for (let eIdx = 0; eIdx < eggs.length; eIdx++) {
    let egg = eggs[eIdx];
    let mesh = eggMeshes[eIdx];

    // Pre-project each fracture edge's subdivided points
    let projectedEdges = [];
    for (let edge of mesh.edges) {
      let avgLift = 0.5 * (edge.cellA.lift + edge.cellB.lift);
      let pts2d = edge.subPtsUv.map((uv) => projectEggPoint(egg, uv.u, uv.v, avgLift));
      projectedEdges.push({
        edge: edge,
        pts2d: pts2d
      });
    }

    // ------------------------------------------------------------------------
    // PASS A: SMOKED FISSURES (Soft dark tea/soot bleed along cracks)
    // ------------------------------------------------------------------------
    for (let pe of projectedEdges) {
      let edge = pe.edge;
      let pts = pe.pts2d;
      if (edge.strength < 0.2) continue;

      let smokeCol = random() < 0.6 ? "#1c1512" : "#2b1d16";
      let smokeW = (0.65 + 1.15 * edge.strength) * (edge.inCraze ? 1.0 : 0.55);
      brush.set("charcoal", smokeCol, smokeW);
      for (let k = 0; k < pts.length - 1; k++) {
        brush.line(pts[k].x, pts[k].y, pts[k + 1].x, pts[k + 1].y);
      }
    }

    // ------------------------------------------------------------------------
    // PASS B: TINY CRISP SIDEWAYS SHADOWS CAST BY EACH LIFTED SHARD
    // (Low light from the left means every lifted shard / left fissure lip
    // casts a crisp shadow displaced slightly to the right: +dx, +dy)
    // ------------------------------------------------------------------------
    for (let pe of projectedEdges) {
      let edge = pe.edge;
      let pts = pe.pts2d;
      if (!edge.inCraze) continue;

      // Measure how perpendicular the crack is to the low sideways light (-0.97, -0.22)
      let pStart = pts[0];
      let pEnd = pts[pts.length - 1];
      let tx = pEnd.x - pStart.x;
      let ty = pEnd.y - pStart.y;
      let tLen = max(1e-4, sqrt(tx * tx + ty * ty));
      tx /= tLen;
      ty /= tLen;

      // Normal to the crack in screen space
      let nx = -ty;
      let ny = tx;
      let lightCatch = abs(nx * -0.97 + ny * -0.22);

      // Height step between the two neighboring shards
      let liftDiff = abs(edge.cellA.lift - edge.cellB.lift);
      let shadowShift = (1.3 + 1.8 * edge.strength + 0.45 * liftDiff) * (0.45 + 0.55 * lightCatch);

      // For strongly lifted shards near the tap zone, draw a crisp shadow wedge
      if (edge.strength > 0.42 && lightCatch > 0.35) {
        brush.noStroke();
        brush.noHatch();
        brush.wash("#050608", 215);
        brush.beginShape(0);
        for (let k = 0; k < pts.length; k++) {
          brush.vertex(pts[k].x, pts[k].y);
        }
        for (let k = pts.length - 1; k >= 0; k--) {
          let taper = k === 0 || k === pts.length - 1 ? 0.4 : 1.0;
          brush.vertex(
            pts[k].x + shadowShift * 1.15 * taper,
            pts[k].y + shadowShift * 0.28 * taper
          );
        }
        brush.endShape(true);
        brush.noWash();
      }

      // Crisp dark shadow line cast by the lifted shard lip
      brush.set("rotring", "#060709", (0.45 + 0.75 * edge.strength) * (0.5 + 0.5 * lightCatch));
      for (let k = 0; k < pts.length - 1; k++) {
        brush.line(
          pts[k].x + shadowShift * 0.75,
          pts[k].y + shadowShift * 0.2,
          pts[k + 1].x + shadowShift * 0.75,
          pts[k + 1].y + shadowShift * 0.2
        );
      }
    }

    // Also cast a crisp overhanging rim shadow inside any exposed membrane pocket
    for (let cell of mesh.cells) {
      if (!cell.isMissing) continue;
      brush.noStroke();
      brush.wash("#070608", 220);
      brush.beginShape(0.1);
      for (let p of cell.poly) {
        let vp = projectEggPoint(egg, p.u, p.v, 0);
        brush.vertex(vp.x, vp.y);
      }
      brush.endShape(true);

      // Re-expose the lit right portion of the membrane to leave a crisp crescent shadow on its left
      let memCol = eIdx === 2 ? "#e0c2a0" : "#e8d5b9";
      brush.wash(memCol, 240);
      brush.beginShape(0.15);
      for (let p of cell.poly) {
        let vp = projectEggPoint(egg, p.u, p.v, 0);
        brush.vertex(vp.x + 3.2, vp.y + 0.8);
      }
      brush.endShape(true);
      brush.noWash();
    }

    // ------------------------------------------------------------------------
    // PASS C: RAZOR-SHARP FRACTURED SHELL RIM HIGHLIGHTS
    // (The exposed chalky-cream or coppery-iridescent thickness of each lifted
    // shard facing left into the low sideways light!)
    // ------------------------------------------------------------------------
    for (let pe of projectedEdges) {
      let edge = pe.edge;
      let pts = pe.pts2d;
      if (!edge.inCraze) continue;

      let pStart = pts[0];
      let pEnd = pts[pts.length - 1];
      let tx = pEnd.x - pStart.x;
      let ty = pEnd.y - pStart.y;
      let tLen = max(1e-4, sqrt(tx * tx + ty * ty));
      tx /= tLen;
      ty /= tLen;

      let nx = -ty;
      let ny = tx;
      let lightCatch = abs(nx * -0.97 + ny * -0.22);
      if (lightCatch < 0.22) continue;

      let midPt = pts[floor(pts.length / 2)];
      let light = computeEggLighting(midPt);
      if (light.direct < 0.08 && egg.iridescence < 0.3) continue;

      // Determine highlight color (warm chalky cream, or glinting copper/verdigris on the hero shell)
      let rimCol = light.direct > 0.5 ? "#fff9eb" : "#e8d2ae";
      if (egg.iridescence > 0.3) {
        let dFlash = dist(edge.mu, edge.mv, -0.14, -0.1);
        if (dFlash < 0.62) {
          rimCol =
            edge.mv > 0.08
              ? "#72f5ed" // iridescent verdigris-cyan glint
              : random() < 0.55
              ? "#ffb85c" // molten copper-gold glint
              : "#fff3d6";
        }
      }

      let rimW = (0.38 + 0.62 * edge.strength) * lightCatch * (0.55 + 0.6 * light.direct);
      let rimOffX = 1.35 + 0.9 * edge.strength;
      let rimOffY = 0.32;

      brush.set("rotring", rimCol, rimW);
      for (let k = 0; k < pts.length - 1; k++) {
        brush.line(
          pts[k].x + rimOffX,
          pts[k].y + rimOffY,
          pts[k + 1].x + rimOffX,
          pts[k + 1].y + rimOffY
        );
      }
    }

    // ------------------------------------------------------------------------
    // PASS D: CARBON-BLACK PEN CRACKLE LINES, RAKU JUNCTION FILLS & BRANCHES
    // ------------------------------------------------------------------------
    let vertexMap = new Map();

    for (let pe of projectedEdges) {
      let edge = pe.edge;
      let pts = pe.pts2d;

      // Carbon-black pen line weight tapers from tap impact zone outward
      let baseW = edge.inCraze
        ? 0.42 + 0.88 * pow(edge.strength, 0.85)
        : 0.22 + 0.35 * edge.strength;

      brush.set("rotring", "#040507", baseW);
      for (let k = 0; k < pts.length - 1; k++) {
        brush.line(pts[k].x, pts[k].y, pts[k + 1].x, pts[k + 1].y);
      }

      // Second crisp pen pass on deep primary fissures
      if (edge.strength > 0.52 && edge.inCraze) {
        brush.set("pen", "#090a0d", baseW * 0.72);
        for (let k = 0; k < pts.length - 1; k++) {
          brush.line(
            pts[k].x - 0.4,
            pts[k].y - 0.15,
            pts[k + 1].x - 0.4,
            pts[k + 1].y - 0.15
          );
        }
      }

      // Collect 3-way Voronoi vertices for raku crackle triangular ink pooling
      if (edge.inCraze && edge.strength > 0.28) {
        let ends = [
          { pt: pts[0], other: pts[1], uv: edge.p1 },
          { pt: pts[pts.length - 1], other: pts[pts.length - 2], uv: edge.p2 }
        ];
        for (let en of ends) {
          let vk = round(en.uv.u * 250) + "_" + round(en.uv.v * 250);
          if (!vertexMap.has(vk)) {
            vertexMap.set(vk, {
              x: en.pt.x,
              y: en.pt.y,
              strength: edge.strength,
              dirs: []
            });
          }
          let vEntry = vertexMap.get(vk);
          let dx = en.other.x - en.pt.x;
          let dy = en.other.y - en.pt.y;
          let dl = max(1e-4, sqrt(dx * dx + dy * dy));
          vEntry.dirs.push({ dx: dx / dl, dy: dy / dl });
        }
      }

      // Micro-branching raku dendrites sprouting off primary cracks
      if (edge.inCraze && edge.strength > 0.35 && random() < 0.42) {
        let midPt = pts[floor(pts.length / 2)];
        let dx = pts[pts.length - 1].x - pts[0].x;
        let dy = pts[pts.length - 1].y - pts[0].y;
        let baseAng = atan2(dy, dx) + (random() < 0.5 ? 52 : -52);
        let bLen = random(4, 11) * edge.strength;
        let bx = midPt.x + bLen * cos(baseAng);
        let by = midPt.y + bLen * sin(baseAng);
        brush.set("rotring", "#06070a", 0.32 * edge.strength);
        brush.line(midPt.x, midPt.y, bx, by);
      }
    }

    // Fill triangular raku crackle ink pools at 3-way fracture junctions
    brush.noStroke();
    brush.noHatch();
    for (let vEntry of vertexMap.values()) {
      if (vEntry.dirs.length < 3) continue;
      let poolR = (2.2 + 3.6 * vEntry.strength) * random(0.75, 1.2);
      brush.wash("#040507", 240);
      brush.beginShape(0);
      for (let d of vEntry.dirs) {
        brush.vertex(vEntry.x + d.dx * poolR, vEntry.y + d.dy * poolR);
      }
      brush.endShape(true);
    }
    brush.noWash();

    // Propagate branching hairline pen cracks from the crazed border into the intact half of the shell
    for (let b = 0; b < 11; b++) {
      let branchAng = egg.crazeDir + 180 + random(-85, 85);
      let lobeNoise = noise(eIdx * 10 + cos(branchAng) * 1.3 + 2, sin(branchAng) * 1.3 + 2);
      let asymFactor = cos(branchAng - egg.crazeDir) * 0.16;
      let startRad = egg.crazeBase * (0.68 + 0.52 * lobeNoise + asymFactor) * 0.88;

      let u0 = egg.tapU + startRad * cos(branchAng);
      let v0 = egg.tapV + startRad * sin(branchAng);
      if (u0 * u0 + v0 * v0 > 0.88) continue;

      drawBranchingHairlineCrack(egg, u0, v0, branchAng, random(0.18, 0.34), 0.52, 3);
    }

    // Crisp silhouette contour enhancement (luminous left rim + carbon-black shadow rim)
    for (let a = 0; a < 360; a += 5) {
      let p1 = projectEggPoint(egg, 0.992 * cos(a), 0.992 * sin(a), 0);
      let p2 = projectEggPoint(egg, 0.992 * cos(a + 5), 0.992 * sin(a + 5), 0);
      let dx = p1.x - egg.cx;
      let dy = p1.y - egg.cy;
      let rLen = max(1, sqrt(dx * dx + dy * dy));
      let lightDot = (dx / rLen) * -0.92 + (dy / rLen) * -0.22;

      if (lightDot > 0.45) {
        let rimLightCol = egg.iridescence > 0.6 ? "#ffd280" : "#fff7e2";
        brush.set("rotring", rimLightCol, 0.58 * lightDot);
        brush.line(p1.x, p1.y, p2.x, p2.y);
      } else if (lightDot < -0.15) {
        brush.set("rotring", "#040507", 0.72 * abs(lightDot));
        brush.line(p1.x, p1.y, p2.x, p2.y);
      }
    }
  }
}

function drawBranchingHairlineCrack(egg, u, v, ang, lenUv, weight, depth) {
  if (depth <= 0 || u * u + v * v > 0.95) return;

  let steps = 5;
  let stepLen = lenUv / steps;
  let curU = u;
  let curV = v;
  let curAng = ang;

  for (let s = 0; s < steps; s++) {
    curAng += random(-16, 16);
    let nxtU = curU + stepLen * cos(curAng);
    let nxtV = curV + stepLen * sin(curAng);
    if (nxtU * nxtU + nxtV * nxtV > 0.96) break;

    let p1 = projectEggPoint(egg, curU, curV, 0.4);
    let p2 = projectEggPoint(egg, nxtU, nxtV, 0.4);

    let segW = weight * map(s, 0, steps, 1.0, 0.45);

    // Subtle smoked shadow under hairline
    if (segW > 0.25) {
      brush.set("2B", "#211915", segW * 1.1);
      brush.line(p1.x, p1.y, p2.x, p2.y);
    }

    // Crisp carbon-black hairline
    brush.set("rotring", "#050608", segW);
    brush.line(p1.x, p1.y, p2.x, p2.y);

    // Occasional secondary fork
    if (s === 2 && depth > 1 && random() < 0.65) {
      let forkAng = curAng + (random() < 0.5 ? random(24, 44) : random(-44, -24));
      drawBranchingHairlineCrack(egg, nxtU, nxtV, forkAng, lenUv * 0.58, segW * 0.72, depth - 1);
    }

    curU = nxtU;
    curV = nxtV;
  }
}

// ============================================================================
// LAYER 7: FALLEN SHELL CRUMBS ON SLATE & FINAL SPECULAR GLINTS
// ============================================================================

function drawFallenShellCrumbsAndGlints(eggs, eggMeshes) {
  // 1. Moist specular catch-lights on exposed inner membranes & lifted shard ridges
  for (let eIdx = 0; eIdx < eggs.length; eIdx++) {
    let egg = eggs[eIdx];
    let mesh = eggMeshes[eIdx];

    for (let cell of mesh.cells) {
      if (cell.isMissing) {
        let pt = projectEggPoint(egg, cell.cu, cell.cv, 0);
        brush.set("rotring", "#ffffff", 1.15);
        brush.line(pt.x - 1.5, pt.y - 1.5, pt.x + 2.5, pt.y - 0.5);
        brush.set("rotring", "#fff4d9", 0.75);
        brush.line(pt.x - 3.0, pt.y + 1.5, pt.x - 0.5, pt.y + 2.2);
      } else if (cell.isCrazed && cell.crazeStrength > 0.45) {
        let pt = projectEggPoint(egg, cell.cu, cell.cv, cell.lift);
        let light = computeEggLighting(pt, cell.tiltX, cell.tiltY);
        if (light.spec > 0.35) {
          let glintCol = egg.iridescence > 0.5 ? "#ffe39e" : "#ffffff";
          brush.set("rotring", glintCol, 0.85);
          brush.line(pt.x - 1.8, pt.y - 0.8, pt.x + 1.8, pt.y + 0.4);
        }
      }
    }
  }

  // 2. Tiny detached eggshell shards / crumbs scattered on the blackened slate
  // (Each casts a long, crisp sideways shadow to its right from the low left light!)
  let crumbs = [
    { x: 355, y: 702, sz: 7.5, col: "#f2e2c6", hasSpot: false },
    { x: 378, y: 718, sz: 4.5, col: "#e6d2b0", hasSpot: true },
    { x: 422, y: 696, sz: 9.0, col: "#f5e8ce", hasSpot: true },
    { x: 446, y: 724, sz: 3.8, col: "#ead8b8", hasSpot: false },
    { x: 528, y: 678, sz: 6.5, col: "#ffbe73", hasSpot: false },
    { x: 552, y: 695, sz: 10.5, col: "#f7dec0", hasSpot: true },
    { x: 576, y: 716, sz: 5.2, col: "#ffaa52", hasSpot: false },
    { x: 612, y: 682, sz: 8.2, col: "#f4e1c1", hasSpot: true },
    { x: 638, y: 704, sz: 4.2, col: "#76f0e8", hasSpot: false },
    { x: 662, y: 728, sz: 6.0, col: "#ebd6b5", hasSpot: false },
    { x: 758, y: 652, sz: 7.0, col: "#e5d4b3", hasSpot: true },
    { x: 785, y: 668, sz: 4.0, col: "#f2e4c9", hasSpot: false },
    { x: 822, y: 648, sz: 5.5, col: "#d9c8a7", hasSpot: false },
    { x: 245, y: 728, sz: 5.8, col: "#efe0c4", hasSpot: true },
    { x: 942, y: 622, sz: 4.8, col: "#e6d5b8", hasSpot: false }
  ];

  for (let c of crumbs) {
    let poly = [];
    let sides = 5;
    let baseRot = random(360);
    for (let k = 0; k < sides; k++) {
      let a = baseRot + (k * 360) / sides + random(-18, 18);
      let r = c.sz * random(0.55, 1.15);
      poly.push([c.x + r * cos(a), c.y + r * sin(a) * 0.68]);
    }

    // Crisp elongated sideways shadow cast onto the slate to the right
    let shLen = c.sz * 2.4;
    brush.noStroke();
    brush.noHatch();
    brush.wash("#030406", 230);
    brush.beginShape(0);
    brush.vertex(c.x, c.y - c.sz * 0.45);
    brush.vertex(c.x + shLen, c.y + shLen * 0.16);
    brush.vertex(c.x + shLen * 0.85, c.y + c.sz * 0.55 + shLen * 0.16);
    brush.vertex(c.x - c.sz * 0.3, c.y + c.sz * 0.5);
    brush.endShape(true);

    // Body of the fallen shell shard
    brush.wash(c.col, 240);
    brush.beginShape(0);
    for (let p of poly) brush.vertex(p[0], p[1]);
    brush.endShape(true);
    brush.noWash();

    // Optional tiny cocoa speckle on the fallen shard
    if (c.hasSpot) {
      brush.set("rotring", "#3d1c10", 0.85);
      brush.line(c.x - 1, c.y, c.x + 1.5, c.y + 0.5);
    }

    // Crisp carbon-black shadow outline on the right edge & bright catch-light on the left edge
    brush.set("rotring", "#050608", 0.55);
    brush.line(poly[0][0], poly[0][1], poly[1][0], poly[1][1]);
    brush.set("rotring", "#ffffff", 0.65);
    brush.line(poly[2][0], poly[2][1], poly[3][0], poly[3][1]);
  }
}

