// ============================================================================
// GEOMETRY & ANALYTICAL CLIPPING ENGINE (100% KNIFE-SHARP EDGES, NO OUTLINES)
// ============================================================================

function computeBBox(pts) {
  let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
  for (let i = 0; i < pts.length; i++) {
    let x = pts[i][0], y = pts[i][1];
    if (x < minX) minX = x;
    if (y < minY) minY = y;
    if (x > maxX) maxX = x;
    if (y > maxY) maxY = y;
  }
  return { minX, minY, maxX, maxY };
}

function makePoly(pts) {
  let poly = pts.slice();
  poly.bbox = computeBBox(poly);
  return poly;
}

function pointInPoly(x, y, poly) {
  let b = poly.bbox;
  if (b && (x < b.minX || x > b.maxX || y < b.minY || y > b.maxY)) return false;
  let inside = false;
  for (let i = 0, j = poly.length - 1; i < poly.length; j = i++) {
    let xi = poly[i][0], yi = poly[i][1];
    let xj = poly[j][0], yj = poly[j][1];
    let intersect = ((yi > y) !== (yj > y)) &&
      (x < (xj - xi) * (y - yi) / ((yj - yi) || 1e-12) + xi);
    if (intersect) inside = !inside;
  }
  return inside;
}

function bboxOverlapsSeg(b, x1, y1, x2, y2) {
  if (!b) return true;
  let sMinX = x1 < x2 ? x1 : x2;
  let sMaxX = x1 > x2 ? x1 : x2;
  if (sMaxX < b.minX || sMinX > b.maxX) return false;
  let sMinY = y1 < y2 ? y1 : y2;
  let sMaxY = y1 > y2 ? y1 : y2;
  if (sMaxY < b.minY || sMinY > b.maxY) return false;
  return true;
}

function collectPolyIntersections(x1, y1, rx, ry, poly, tList) {
  if (!bboxOverlapsSeg(poly.bbox, x1, y1, x1 + rx, y1 + ry)) return;
  let n = poly.length;
  for (let i = 0, j = n - 1; i < n; j = i++) {
    let ax = poly[j][0], ay = poly[j][1];
    let bx = poly[i][0], by = poly[i][1];
    let sx = bx - ax, sy = by - ay;
    let denom = rx * sy - ry * sx;
    if (Math.abs(denom) > 1e-9) {
      let qpx = ax - x1, qpy = ay - y1;
      let t = (qpx * sy - qpy * sx) / denom;
      if (t > 1e-5 && t < 1 - 1e-5) {
        let u = (qpx * ry - qpy * rx) / denom;
        if (u >= -1e-4 && u <= 1 + 1e-4) {
          tList.push(t);
        }
      }
    }
  }
}

// Draws a segment on the left half and its exact bilateral mirror on the right half
function drawMirroredSeg(x1, y1, x2, y2) {
  let dx = x2 - x1, dy = y2 - y1;
  if (dx * dx + dy * dy < 0.35) return;
  brush.line(x1, y1, x2, y2);
  brush.line(2 * CX - x1, y1, 2 * CX - x2, y2);
}

// Analytically clips segment (x1,y1)->(x2,y2) to stay inside includePoly,
// outside all excludePolys, and strictly on the left side x <= CX before mirroring.
function drawClippedMirroredSeg(x1, y1, x2, y2, includePoly, excludePolys) {
  if (includePoly && !bboxOverlapsSeg(includePoly.bbox, x1, y1, x2, y2)) return;
  let rx = x2 - x1, ry = y2 - y1;
  let totalLen = Math.hypot(rx, ry);
  if (totalLen < 0.45) return;

  let tList = [0, 1];

  // Symmetry fold plane x = CX
  if ((x1 - CX) * (x2 - CX) < 0) {
    let tc = (CX - x1) / rx;
    if (tc > 1e-5 && tc < 1 - 1e-5) tList.push(tc);
  }

  if (includePoly) {
    collectPolyIntersections(x1, y1, rx, ry, includePoly, tList);
  }
  if (excludePolys && excludePolys.length > 0) {
    for (let k = 0; k < excludePolys.length; k++) {
      collectPolyIntersections(x1, y1, rx, ry, excludePolys[k], tList);
    }
  }

  tList.sort((a, b) => a - b);

  for (let i = 0; i < tList.length - 1; i++) {
    let t0 = tList[i], t1 = tList[i + 1];
    if ((t1 - t0) * totalLen < 0.45) continue;
    let tm = 0.5 * (t0 + t1);
    let mx = x1 + tm * rx;
    let my = y1 + tm * ry;

    if (mx > CX + 0.02) continue;
    if (includePoly && !pointInPoly(mx, my, includePoly)) continue;

    let excluded = false;
    if (excludePolys) {
      for (let k = 0; k < excludePolys.length; k++) {
        if (pointInPoly(mx, my, excludePolys[k])) {
          excluded = true;
          break;
        }
      }
    }
    if (excluded) continue;

    drawMirroredSeg(x1 + t0 * rx, y1 + t0 * ry, x1 + t1 * rx, y1 + t1 * ry);
  }
}

function drawClippedMirroredCurve(pts, includePoly, excludePolys) {
  for (let i = 0; i < pts.length - 1; i++) {
    drawClippedMirroredSeg(
      pts[i][0], pts[i][1],
      pts[i + 1][0], pts[i + 1][1],
      includePoly, excludePolys
    );
  }
}

// Fills or hatches a polygon with parallel lines at angleDeg (in degrees)
function hatchPolyClipped(poly, excludePolys, angleDeg, spacing, brushName, jitter = 0) {
  brush.set(brushName, CINNABAR_HEX, 1);
  let b = poly.bbox;
  let cx = 0.5 * (b.minX + b.maxX);
  let cy = 0.5 * (b.minY + b.maxY);
  let rad = angleDeg * Math.PI / 180;
  let dx = Math.cos(rad), dy = Math.sin(rad);
  let nx = -dy, ny = dx;
  let halfDiag = 0.55 * Math.hypot(b.maxX - b.minX, b.maxY - b.minY) + 4;

  for (let d = -halfDiag; d <= halfDiag; d += spacing) {
    let off = d + (jitter > 0 ? random(-jitter, jitter) : 0);
    let px = cx + nx * off;
    let py = cy + ny * off;
    let x1 = px - dx * halfDiag, y1 = py - dy * halfDiag;
    let x2 = px + dx * halfDiag, y2 = py + dy * halfDiag;
    drawClippedMirroredSeg(x1, y1, x2, y2, poly, excludePolys);
  }
}

//Chaikin corner-smoothing / Catmull-Rom subdivision helper
function smoothClosedPoly(pts, iterations = 2, tension = 0.25) {
  let curr = pts.slice();
  for (let it = 0; it < iterations; it++) {
    let next = [];
    let n = curr.length;
    for (let i = 0; i < n; i++) {
      let p0 = curr[i];
      let p1 = curr[(i + 1) % n];
      next.push([
        (1 - tension) * p0[0] + tension * p1[0],
        (1 - tension) * p0[1] + tension * p1[1]
      ]);
      next.push([
        tension * p0[0] + (1 - tension) * p1[0],
        tension * p0[1] + (1 - tension) * p1[1]
      ]);
    }
    curr = next;
  }
  return makePoly(curr);
}

function smoothOpenCurve(pts, iterations = 2) {
  let curr = pts.slice();
  for (let it = 0; it < iterations; it++) {
    let next = [curr[0]];
    for (let i = 0; i < curr.length - 1; i++) {
      let p0 = curr[i], p1 = curr[i + 1];
      next.push([0.75 * p0[0] + 0.25 * p1[0], 0.75 * p0[1] + 0.25 * p1[1]]);
      next.push([0.25 * p0[0] + 0.75 * p1[0], 0.25 * p0[1] + 0.75 * p1[1]]);
    }
    next.push(curr[curr.length - 1]);
    curr = next;
  }
  return curr;
}

// Sutherland-Hodgman half-plane clipper for Voronoi cell construction
// Keeps points where (x - px)*nx + (y - py)*ny >= 0
function clipPolyHalfPlane(poly, px, py, nx, ny) {
  let out = [];
  let n = poly.length;
  if (n === 0) return out;
  for (let i = 0; i < n; i++) {
    let A = poly[i];
    let B = poly[(i + 1) % n];
    let da = (A[0] - px) * nx + (A[1] - py) * ny;
    let db = (B[0] - px) * nx + (B[1] - py) * ny;
    if (da >= 0) {
      out.push(A);
      if (db < 0) {
        let t = da / (da - db);
        out.push([A[0] + t * (B[0] - A[0]), A[1] + t * (B[1] - A[1])]);
      }
    } else if (db >= 0) {
      let t = da / (da - db);
      out.push([A[0] + t * (B[0] - A[0]), A[1] + t * (B[1] - A[1])]);
    }
  }
  return out;
}

function polyCentroid(pts) {
  let sx = 0, sy = 0, a = 0;
  let n = pts.length;
  for (let i = 0; i < n; i++) {
    let p0 = pts[i], p1 = pts[(i + 1) % n];
    let cross = p0[0] * p1[1] - p1[0] * p0[1];
    a += cross;
    sx += (p0[0] + p1[0]) * cross;
    sy += (p0[1] + p1[1]) * cross;
  }
  if (Math.abs(a) < 1e-5) {
    sx = 0; sy = 0;
    for (let p of pts) { sx += p[0]; sy += p[1]; }
    return [sx / n, sy / n];
  }
  a *= 3;
  return [sx / a, sy / a];
}

// ============================================================================
// ANATOMICAL GEOMETRY OF THE SPLIT POMEGRANATE
// ============================================================================

function buildPomegranateAnatomy() {
  // 1. OUTER SILHOUETTE (Left half: Crown -> Neck -> Hexagonal-bulged Body -> Base)
  const crownOuter = [
    [600, 148],
    [586, 122], [568, 92], [554, 72],   // Dorsal inner sepal tip
    [544, 96], [532, 118],              // First sinus notch
    [514, 102], [492, 86], [472, 78],   // Principal flared sepal tip
    [468, 104], [464, 134],             // Second sinus notch
    [444, 124], [424, 116], [412, 114], // Lateral outer sepal tip
    [418, 144], [430, 174], [436, 202]  // Constricted calyx neck
  ];

  const bodyOuterRaw = [
