}

// ============================================================================
// GENERATE PACKED FACETED JEWEL ARILS INSIDE EACH CHAMBER
// ============================================================================

function generateChamberArils(chamberPoly, chamberIdx, targetDist) {
  let b = chamberPoly.bbox;
  let seeds = [];

  // Deterministic stratified hex-grid + jitter seed placement inside chamber
  let rowH = targetDist * 0.86;
  let rowIdx = 0;
  for (let y = b.minY + targetDist * 0.42; y <= b.maxY - targetDist * 0.38; y += rowH) {
    let xOffset = (rowIdx % 2 === 1) ? targetDist * 0.5 : 0;
    for (let x = b.minX + targetDist * 0.42 + xOffset; x <= b.maxX - targetDist * 0.38; x += targetDist) {
      let sx = x + random(-targetDist * 0.16, targetDist * 0.16);
      let sy = y + random(-targetDist * 0.16, targetDist * 0.16);
      if (pointInPoly(sx, sy, chamberPoly)) {
        seeds.push([sx, sy]);
      }
    }
    rowIdx++;
  }

  // Filter out seeds too close to each other
  let filtered = [];
  for (let s of seeds) {
    let ok = true;
    for (let f of filtered) {
      if (Math.hypot(s[0] - f[0], s[1] - f[1]) < targetDist * 0.68) {
        ok = false;
        break;
      }
    }
    if (ok) filtered.push(s);
  }
  seeds = filtered;

  // 3 iterations of Lloyd relaxation clipped to chamber for authentic pressure-packing
  for (let iter = 0; iter < 3; iter++) {
    for (let i = 0; i < seeds.length; i++) {
      let cell = computeVoronoiCellInChamber(i, seeds, chamberPoly);
      if (cell.length >= 3) {
        let c = polyCentroid(cell);
        if (pointInPoly(c[0], c[1], chamberPoly)) {
          seeds[i] = [
            0.35 * seeds[i][0] + 0.65 * c[0],
            0.35 * seeds[i][1] + 0.65 * c[1]
          ];
        }
      }
    }
  }

  // Construct final faceted aril objects
  let arils = [];
  for (let i = 0; i < seeds.length; i++) {
    let rawCell = computeVoronoiCellInChamber(i, seeds, chamberPoly);
    if (rawCell.length < 4) continue;

    let center = polyCentroid(rawCell);
    let cx = center[0], cy = center[1];

    // Check if this is a recessed empty socket cavity (1 per large chamber for hyperrealism)
    let isSocket = (chamberIdx === 2 && i === 4) || (chamberIdx === 3 && i === 6);

    // Inset vertices slightly to create crisp dark interstitial crevices between arils,
    // and bevel corners while keeping flat pressed facets along shared edges!
    let n = rawCell.length;
    let facetedPts = [];
    let sumR = 0;
    for (let k = 0; k < n; k++) {
      let pPrev = rawCell[(k - 1 + n) % n];
      let pCurr = rawCell[k];
      let pNext = rawCell[(k + 1) % n];
      sumR += Math.hypot(pCurr[0] - cx, pCurr[1] - cy);

      // Corner bevel points (preserve flat facet middle between c1 and c2)
      let c1 = [0.78 * pCurr[0] + 0.22 * pPrev[0], 0.78 * pCurr[1] + 0.22 * pPrev[1]];
      let cMid = [
        0.58 * pCurr[0] + 0.21 * pPrev[0] + 0.21 * pNext[0],
        0.58 * pCurr[1] + 0.21 * pPrev[1] + 0.21 * pNext[1]
      ];
      let c2 = [0.78 * pCurr[0] + 0.22 * pNext[0], 0.78 * pCurr[1] + 0.22 * pNext[1]];
      let eMid = [0.5 * (pCurr[0] + pNext[0]), 0.5 * (pCurr[1] + pNext[1])];
      // Slight outward cushion bulge on edge midpoint
      let ex = eMid[0] - cx, ey = eMid[1] - cy;
      let eBulge = [cx + ex * 1.03, cy + ey * 1.03];

      facetedPts.push(c1, cMid, c2, eBulge);
    }

    let avgR = sumR / n;
    let insetScale = isSocket ? 0.88 : 0.945;
    let finalPts = facetedPts.map(p => [
      cx + (p[0] - cx) * insetScale,
      cy + (p[1] - cy) * insetScale
    ]);

    let arilPoly = makePoly(finalPts);
    arils.push(buildArilOptics(arilPoly, rawCell, cx, cy, avgR, isSocket, chamberIdx, i));
  }

  return arils;
}

function computeVoronoiCellInChamber(idx, seeds, chamberPoly) {
  let sx = seeds[idx][0], sy = seeds[idx][1];
  let b = chamberPoly.bbox;
  let cell = [
    [b.minX - 10, b.minY - 10],
    [b.maxX + 10, b.minY - 10],
    [b.maxX + 10, b.maxY + 10],
    [b.minX - 10, b.maxY + 10]
  ];

  for (let j = 0; j < seeds.length; j++) {
    if (j === idx) continue;
    let ox = seeds[j][0], oy = seeds[j][1];
    let dx = sx - ox, dy = sy - oy;
    let dist = Math.hypot(dx, dy);
    if (dist < 1e-4 || dist > 160) continue;
    let mx = 0.5 * (sx + ox), my = 0.5 * (sy + oy);
    cell = clipPolyHalfPlane(cell, mx, my, dx / dist, dy / dist);
    if (cell.length < 3) break;
  }

  // Clamp any vertices that extend outside chamberPoly back along ray toward (sx, sy)
  let clamped = [];
  for (let k = 0; k < cell.length; k++) {
    let p0 = cell[k];
    let p1 = cell[(k + 1) % cell.length];
    let sub = [p0, [0.5 * (p0[0] + p1[0]), 0.5 * (p0[1] + p1[1])]];
    for (let pt of sub) {
      if (pointInPoly(pt[0], pt[1], chamberPoly)) {
        clamped.push(pt);
      } else {
        // Ray from (sx, sy) to pt: find first intersection with chamberPoly
        let rx = pt[0] - sx, ry = pt[1] - sy;
        let tList = [];
        collectPolyIntersections(sx, sy, rx, ry, chamberPoly, tList);
        if (tList.length > 0) {
          tList.sort((a, b) => a - b);
          let tHit = Math.max(0.1, tList[0] - 0.02);
          clamped.push([sx + tHit * rx, sy + tHit * ry]);
        } else {
          clamped.push([0.5 * (sx + pt[0]), 0.5 * (sy + pt[1])]);
        }
      }
    }
  }
  return clamped;
}

// Constructs the internal 3D crystal facets, bare-paper highlight slits,
// pinprick white glint, caustic exit slit, and translucent seed pip for one aril.
function buildArilOptics(arilPoly, rawCell, cx, cy, R, isSocket, chamberIdx, seedIdx) {
  // Light comes from upper-inner-front (symmetrical across x = 600)
  let lightDirX = 0.32, lightDirY = -0.94;

  // Crown table plateau shifted slightly toward the upper-inner highlight
  let tx = cx + R * random(0.06, 0.16);
  let ty = cy - R * random(0.14, 0.24);
  let tableScale = random(0.48, 0.56);

  let tablePts = arilPoly.map(p => [
    tx + (p[0] - cx) * tableScale,
    ty + (p[1] - cy) * tableScale
  ]);
  let tablePoly = makePoly(tablePts);

  // Build trapezoidal side facets from rawCell edges
  // Since arilPoly has 4 points per rawCell vertex, group in steps of 4
  let facets = [];
  let numSides = rawCell.length;
  for (let k = 0; k < numSides; k++) {
    let i0 = (k * 4 + 1) % arilPoly.length;
    let i1 = (k * 4 + 2) % arilPoly.length;
    let i2 = (k * 4 + 3) % arilPoly.length;
    let i3 = (k * 4 + 4) % arilPoly.length;
    let i4 = (k * 4 + 5) % arilPoly.length;

    let fPoly = makePoly([
      arilPoly[i0], arilPoly[i1], arilPoly[i2], arilPoly[i3], arilPoly[i4],
      tablePts[i4], tablePts[i3], tablePts[i2], tablePts[i1], tablePts[i0]
    ]);

    let fc = polyCentroid(fPoly);
    let nx = fc[0] - cx, ny = fc[1] - cy;
    let nLen = Math.hypot(nx, ny) || 1;
    nx /= nLen; ny /= nLen;

    let ex = arilPoly[i4][0] - arilPoly[i0][0];
    let ey = arilPoly[i4][1] - arilPoly[i0][1];
    let edgeAngle = Math.atan2(ey, ex) * 180 / Math.PI;

    let dotL = nx * lightDirX + ny * lightDirY; // -1 (deep bottom shadow) to +1 (top lit)
    facets.push({ poly: fPoly, nx, ny, edgeAngle, dotL, fc });
  }

  // Highlight exclusions (reserved bare paper slits + pinprick white glint)
  let holes = [];
  if (!isSocket) {
    // 1. Primary Bare-Paper Highlight Slit along the upper-inner crown ridge
    let slitAngle = random(-28, -12) * Math.PI / 180;
    let ux = Math.cos(slitAngle), uy = Math.sin(slitAngle);
    let vx = -uy, vy = ux;
    let sx = tx + R * 0.04, sy = ty - R * 0.22;
    let sLen = R * random(0.36, 0.48);
    let sWid = Math.max(1.9, R * random(0.095, 0.13));

    let slit1 = makePoly([
      [sx - ux * sLen, sy - uy * sLen],
      [sx - ux * sLen * 0.35 - vx * sWid, sy - uy * sLen * 0.35 - vy * sWid],
      [sx + ux * sLen * 0.35 - vx * sWid * 0.85, sy + uy * sLen * 0.35 - vy * sWid * 0.85],
      [sx + ux * sLen, sy + uy * sLen],
      [sx + ux * sLen * 0.35 + vx * sWid * 0.75, sy + uy * sLen * 0.35 + vy * sWid * 0.75],
      [sx - ux * sLen * 0.35 + vx * sWid * 0.85, sy - uy * sLen * 0.35 + vy * sWid * 0.85]
    ]);
    holes.push(slit1);

    // 2. Pinprick White Glint (photographically crisp specular point near apex)
    let gx = sx - ux * (sLen + R * 0.16) + vx * R * 0.06;
    let gy = sy - uy * (sLen + R * 0.16) + vy * R * 0.06;
    let gRad = Math.max(2.3, R * 0.115);
    let glintPts = [];
    for (let a = 0; a < 8; a++) {
      let ang = a * Math.PI / 4;
      let r = (a % 2 === 0) ? gRad * 1.18 : gRad * 0.72;
      glintPts.push([gx + Math.cos(ang) * r, gy + Math.sin(ang) * r]);
    }
    holes.push(makePoly(glintPts));

    // 3. Secondary Facet Ridge Bare-Paper Slit (angled along lateral facet)
    let s2Angle = random(22, 48) * Math.PI / 180;
    let u2x = Math.cos(s2Angle), u2y = Math.sin(s2Angle);
    let v2x = -u2y, v2y = u2x;
    let s2x = tx + R * 0.28, s2y = ty - R * 0.02;
    let s2Len = R * random(0.22, 0.32);
    let s2Wid = Math.max(1.3, R * 0.065);
    let slit2 = makePoly([
      [s2x - u2x * s2Len, s2y - u2y * s2Len],
      [s2x - v2x * s2Wid, s2y - v2y * s2Wid],
      [s2x + u2x * s2Len, s2y + u2y * s2Len],
      [s2x + v2x * s2Wid, s2y + v2y * s2Wid]
    ]);
    holes.push(slit2);

    // 4. Lower Subsurface Caustic Exit Slit (internal ruby glow near bottom-inner rim)
    let cAngle = random(-18, 12) * Math.PI / 180;
    let ucx = Math.cos(cAngle), ucy = Math.sin(cAngle);
    let vcx = -ucy, vcy = ucx;
    let caustX = cx - R * 0.12, caustY = cy + R * 0.56;
    let cLen = R * 0.26, cWid = Math.max(1.15, R * 0.052);
    let causticSlit = makePoly([
      [caustX - ucx * cLen, caustY - ucy * cLen],
      [caustX - vcx * cWid, caustY - vcy * cWid],
      [caustX + ucx * cLen, caustY + ucy * cLen],
      [caustX + vcx * cWid, caustY + vcy * cWid]
    ]);
    holes.push(causticSlit);
  }

  // Internal translucent seed kernel (endosperm pip)
  let pipAngle = Math.atan2(cy - 580, cx - 480) + random(-0.25, 0.25);
  let pipLen = R * 0.34, pipWid = R * 0.16;
  let pipPts = [];
  for (let a = 0; a < 12; a++) {
    let ang = (a / 12) * Math.PI * 2;
    let lx = Math.cos(ang) * pipLen;
    let ly = Math.sin(ang) * pipWid;
    pipPts.push([
      cx + lx * Math.cos(pipAngle) - ly * Math.sin(pipAngle),
      cy + lx * Math.sin(pipAngle) + ly * Math.cos(pipAngle)
    ]);
  }
  let pipPoly = makePoly(pipPts);

  return {
    poly: arilPoly,
    tablePoly,
    facets,
    holes,
    pipPoly,
     pipAngle: pipAngle * 180 / Math.PI,
    cx, cy, tx, ty, R,
    isSocket
  };
}

// ============================================================================
// BUILD LACY CUT-OUT FILIGREE MEMBRANE VEILS (OVERLAPPING ARIL EDGES)
// ============================================================================

function buildLacyMembraneVeils() {
  // Thin translucent endocarp membrane veils that stretch partly over chamber junctions.
  // Each veil is a bare-paper filigree web with polygonal tissue windows.
  const veilCenters = [
    { cx: 345, cy: 382, rx: 46, ry: 26, angle: 24 },
    { cx: 338, cy: 615, rx: 48, ry: 28, angle: -22 },
    { cx: 525, cy: 438, rx: 38, ry: 24, angle: 12 },
    { cx: 515, cy: 738, rx: 44, ry: 26, angle: 18 },
    { cx: 248, cy: 638, rx: 38, ry: 24, angle: -8 }
  ];

  let veilRibPolys = [];
  let veilWindowPolys = [];

  for (let v of veilCenters) {
    let rad = v.angle * Math.PI / 180;
    let ca = Math.cos(rad), sa = Math.sin(rad);

    // Outer boundary of the membrane veil patch
    let patchPts = [];
    for (let i = 0; i < 18; i++) {
      let a = (i / 18) * Math.PI * 2;
      let rMod = 1 + 0.12 * Math.sin(i * 3);
      let lx = Math.cos(a) * v.rx * rMod;
      let ly = Math.sin(a) * v.ry * rMod;
      patchPts.push([
        v.cx + lx * ca - ly * sa,
        v.cy + lx * sa + ly * ca
      ]);
    }
    let patchPoly = makePoly(patchPts);

    // Generate Voronoi windows inside the patch so the ribs form lacy filigree
    let wSeeds = [];
    for (let wy = -v.ry * 0.75; wy <= v.ry * 0.75; wy += 10.5) {
      for (let wx = -v.rx * 0.78; wx <= v.rx * 0.78; wx += 11.5) {
        let jx = wx + random(-2.5, 2.5);
        let jy = wy + random(-2.5, 2.5);
        if ((jx * jx) / (v.rx * v.rx) + (jy * jy) / (v.ry * v.ry) < 0.78) {
          wSeeds.push([
            v.cx + jx * ca - jy * sa,
            v.cy + jx * sa + jy * ca
          ]);
        }
      }
    }

    let windows = [];
    for (let i = 0; i < wSeeds.length; i++) {
      let cell = computeVoronoiCellInChamber(i, wSeeds, patchPoly);
      if (cell.length >= 4) {
        let c = polyCentroid(cell);
        let shrunk = cell.map(p => [
          c[0] + (p[0] - c[0]) * 0.68,
          c[1] + (p[1] - c[1]) * 0.68
        ]);
        windows.push(makePoly(shrunk));
      }
    }

    veilRibPolys.push({ patchPoly, windows, v });
    for (let w of windows) veilWindowPolys.push(w);
  }

  return veilRibPolys;
}

// ============================================================================
// RENDERING PASSES — PURE SINGLE CINNABAR RED DENSITY
// ============================================================================

function renderSplitPomegranate() {
  brush.noField();
  brush.noFill();
  brush.noWash();
  brush.noHatch();

  const anat = buildPomegranateAnatomy();
  const veilData = buildLacyMembraneVeils();

  // Generate arils for all 4 chambers
  const targetDists = [48, 49, 51, 52];
  let allArils = [];
  let chamberArils = [];
  for (let c = 0; c < 4; c++) {
    let arils = generateChamberArils(anat.chambers[c], c, targetDists[c]);
    chamberArils.push(arils);
    for (let a of arils) allArils.push(a);
  }

  // Also build detached festive cut-paper jewel arils & droplets outside main fruit
  const detachedArils = buildDetachedJewels();

  // --------------------------------------------------------------------------
  // PASS 1: DEEP CHAMBER INTERSTITIAL CAVITIES (100% Solid Marker Mass)
  // Fills the deep crevices between arils while reserving the aril interiors
  // and any lacy membrane ribs.
  // --------------------------------------------------------------------------
  for (let c = 0; c < 4; c++) {
    let chPoly = anat.chambers[c];
    let excludeList = [];

    // Exclude non-socket aril bodies so crevices between them are solid red
    for (let a of chamberArils[c]) {
      if (!a.isSocket) excludeList.push(a.poly);
    }
    // Also exclude lacy membrane ribs (so ribs stay bare paper, windows show red)
    for (let vd of veilData) {
      excludeList.push(vd.patchPoly);
    }

    hatchPolyClipped(chPoly, excludeList, 35, 1.55, "c_solid", 0);
    hatchPolyClipped(chPoly, excludeList, -55, 2.2, "c_heavy", 0);
  }

  // Fill deep red inside the open windows of the lacy membrane veils where crevices lie
  for (let vd of veilData) {
    for (let winPoly of vd.windows) {
      let ex = [];
      for (let a of allArils) {
        if (!a.isSocket) ex.push(a.poly);
      }
      hatchPolyClipped(winPoly, ex, 35, 1.6, "c_solid", 0);
    }
  }

  // --------------------------------------------------------------------------
  // PASS 2: EVERY ARIL AS A GLOSSY, PHOTOGRAPHICALLY CORRECT JEWEL
  // Solid marker mass in shadow facets & Fresnel rims -> finer and finer
  // facet-aligned and dome-curved hatching -> bare paper slits & pinprick glint
  // --------------------------------------------------------------------------
  for (let a of [...allArils, ...detachedArils]) {
    renderSingleJewelAril(a, veilData);
  }

  // --------------------------------------------------------------------------
  // PASS 3: OUTER LEATHERY RIND (EXOCARP) BEVEL & BASAL STEM SCAR
  // Knife-sharp outer edge with no outline; solid marker mass at the inner cut
  // epidermis and outer terminator, graduating to bare paper highlight slits
  // and lenticel pores along the cheek swell.
  // --------------------------------------------------------------------------
  renderOuterRindAndBase(anat);

  // --------------------------------------------------------------------------
  // PASS 4: ROYAL CALYX CROWN & FILIGREE STAMENS IN THE SPLIT THROAT
  // --------------------------------------------------------------------------
  renderCalyxCrownAndStamens(anat);

  // --------------------------------------------------------------------------
  // PASS 5: LACY CUT-OUT FILIGREE PITH (MESOCARP, SEPTA, COLUMELLA & VEILS)
  // Cellular parenchyma lace, vascular bundles, central cleft trabeculae,
  // and scalloped alveolar sockets cradling the arils.
  // --------------------------------------------------------------------------
  renderLacyPithFiligree(anat, allArils, veilData);
}

// ============================================================================
// RENDER SINGLE JEWEL ARIL (OR RECESSED SOCKET)
// ============================================================================

function renderSingleJewelAril(aril, veilData) {
  // Collect exclusion polygons for this aril: its own highlight slits & pinprick glint,
  // plus any lacy membrane ribs that overlap it (while allowing drawing inside veil windows)
  let exclusions = aril.holes.slice();

  if (aril.isSocket) {
    // Empty concave aril socket: deep solid marker rim + dense curved ribs inside
    hatchPolyClipped(aril.poly, [aril.tablePoly], 25, 1.5, "c_solid", 0);
    hatchPolyClipped(aril.poly, [], -40, 2.0, "c_heavy", 0);
    hatchPolyClipped(aril.tablePoly, [], 50, 2.6, "c_mid", 0);
    // Funicle attachment scar in center of socket
    hatchPolyClipped(aril.pipPoly, [], 0, 1.4, "c_solid", 0);
    return;
  }

  // 1. SIDE FACETS (Crystal polyhedral bevels around the aril)
  for (let f of aril.facets) {
    let L = 0.5 * (f.dotL + 1); // 0 = bottom-outer shadow, 1 = upper-inner highlight

    // Top-most rim above the glint/slit has a dark Fresnel internal-reflection band!
    let isFresnelTop = (f.ny < -0.58 && f.dotL > 0.45);

    if (L < 0.30) {
      // Deep shadow facet: solid marker mass + tight heavy cross-hatch
      hatchPolyClipped(f.poly, exclusions, f.edgeAngle, 1.45, "c_solid", 0);
      hatchPolyClipped(f.poly, exclusions, f.edgeAngle + 65, 2.1, "c_heavy", 0);
    } else if (L < 0.52) {
      // Mid-dark facet: solid marker along outer crease + dense heavy hatching
      hatchPolyClipped(f.poly, exclusions, f.edgeAngle, 1.95, "c_heavy", 0);
      hatchPolyClipped(f.poly, exclusions, f.edgeAngle + 50, 3.1, "c_mid", 0);
    } else if (isFresnelTop) {
      // High-contrast Fresnel dark rim right above the pinprick white glint!
      hatchPolyClipped(f.poly, exclusions, f.edgeAngle, 1.55, "c_solid", 0);
      hatchPolyClipped(f.poly, exclusions, f.edgeAngle + 40, 2.3, "c_heavy", 0);
    } else if (L < 0.76) {
      // Mid-light facet: crisp pen hatching aligned with facet plane
      hatchPolyClipped(f.poly, exclusions, f.edgeAngle, 2.9, "c_mid", 0);
      hatchPolyClipped(f.poly, exclusions, f.edgeAngle + 35, 4.8, "c_fine", 0);
    } else {
      // Bright upper facet: delicate fine & hairline hatching stopping at bare paper slits
      hatchPolyClipped(f.poly, exclusions, f.edgeAngle, 4.2, "c_fine", 0);
      hatchPolyClipped(f.poly, exclusions, f.edgeAngle + 90, 6.2, "c_hair", 0);
    }
  }

  // 2. CROWN TABLE DOME (Graduated 3D curved contour hatching from shadow to slit)
  let b = aril.poly.bbox;
  let numSteps = Math.floor((aril.R * 2.1) / 1.9);
  let baseAngle = -22 * Math.PI / 180;
  let ux = Math.cos(baseAngle), uy = Math.sin(baseAngle);
  let nx = -uy, ny = ux; // Points from upper-left highlight toward lower-right shadow

  let dMin = -aril.R * 0.95;
  let dMax = aril.R * 1.05;
  let dCurr = dMax;

  while (dCurr >= dMin) {
    // Normalized position u: 0 at bottom shadow, 1 at top highlight slit
    let u = (dMax - dCurr) / (dMax - dMin);

    // Graduated spacing & brush selection
    let step, bName;
    if (u < 0.22) {
      step = 1.45;
      bName = "c_solid";
    } else if (u < 0.42) {
      step = 1.85;
      bName = "c_heavy";
    } else if (u < 0.64) {
      step = 2.55;
      bName = "c_mid";
    } else if (u < 0.82) {
      step = 3.55;
      bName = "c_fine";
    } else {
      step = 4.85;
      bName = "c_hair";
    }

    brush.set(bName, CINNABAR_HEX, 1);

    // Construct gently curved 3D dome contour chord across the aril
    let curvePts = [];
    let span = aril.R * 1.15;
    let archBow = (u - 0.45) * aril.R * 0.26;
    for (let s = -5; s <= 5; s++) {
      let t = s / 5;
      let bend = (1 - t * t) * archBow;
      let px = aril.cx + nx * (dCurr - bend) + ux * (t * span);
      let py = aril.cy + ny * (dCurr - bend) + uy * (t * span);
      curvePts.push([px, py]);
    }
    drawClippedMirroredCurve(curvePts, aril.poly, exclusions);

    dCurr -= step;
  }

  // 3. HIGH-CONTRAST SPECULAR CONTRAST COLLAR AROUND PINPRICK GLINT & PRIMARY SLIT
  // Surrounds the pinprick white glint with rich dark red internal refraction so it gleams
  if (aril.holes.length >= 2) {
    let glintPoly = aril.holes[1];
    let gc = polyCentroid(glintPoly);
    let collarPts = glintPoly.map(p => [
      gc[0] + (p[0] - gc[0]) * 2.15,
      gc[1] + (p[1] - gc[1]) * 2.15
    ]);
    let collarPoly = makePoly(collarPts);
    let collarClip = [glintPoly, aril.holes[0]];
    hatchPolyClipped(collarPoly, collarClip, -25, 1.35, "c_heavy", 0);
    hatchPolyClipped(collarPoly, collarClip, 65, 1.75, "c_mid", 0);
  }

  // 4. INTERNAL TRANSLUCENT SEED KERNEL (ENDOSPERM PIP)
  // Subtle subsurface oval inside the ruby pulp
  let pipCenter = polyCentroid(aril.pipPoly);
  let pipCore = makePoly(aril.pipPoly.map(p => [
    pipCenter[0] + (p[0] - pipCenter[0]) * 0.52,
    pipCenter[1] + (p[1] - pipCenter[1]) * 0.52
  ]));
  let pipExclusions = [...exclusions, pipCore];
  hatchPolyClipped(aril.pipPoly, pipExclusions, aril.pipAngle + 45, 2.1, "c_fine", 0);
  hatchPolyClipped(aril.pipPoly, pipExclusions, aril.pipAngle - 45, 2.6, "c_hair", 0);
}

// ============================================================================
// RENDER OUTER RIND BEVEL & BASAL STEM SCAR
// ============================================================================

function renderOuterRindAndBase(anat) {
  let outerCurve = [...anat.bodyOuterCurve, ...anat.baseOuter.slice(1)];
  let innerCurve = [...anat.innerRindCurve, [600, 1016]];

  // Build bare-paper highlight slits & lenticel speckles along the cheek of the rind
  let rindHoles = [];

  // Long bare-paper specular highlight slits along the upper shoulder and equatorial swell
  const rindSlitSpecs = [
    { tStart: 0.14, tEnd: 0.28, uMid: 0.42, wid: 0.11 },
    { tStart: 0.33, tEnd: 0.52, uMid: 0.44, wid: 0.13 },
    { tStart: 0.36, tEnd: 0.48, uMid: 0.27, wid: 0.07 },
    { tStart: 0.56, tEnd: 0.68, uMid: 0.45, wid: 0.09 }
  ];

  for (let sp of rindSlitSpecs) {
    let topEdge = [], botEdge = [];
    let steps = 14;
    for (let i = 0; i <= steps; i++) {
      let s = i / steps;
      let t = sp.tStart + s * (sp.tEnd - sp.tStart);
      let taper = Math.sin(s * Math.PI);
      let pIn = samplePolylineAt(innerCurve, t);
      let pOut = samplePolylineAt(outerCurve, t);
      let u1 = sp.uMid - sp.wid * taper;
      let u2 = sp.uMid + sp.wid * taper;
      topEdge.push([pIn[0] + (pOut[0] - pIn[0]) * u1, pIn[1] + (pOut[1] - pIn[1]) * u1]);
      botEdge.push([pIn[0] + (pOut[0] - pIn[0]) * u2, pIn[1] + (pOut[1] - pIn[1]) * u2]);
    }
    rindHoles.push(makePoly([...topEdge, ...botEdge.reverse()]));
  }

  // Natural pomegranate skin lenticels (tiny bare-paper diamond speckles)
  for (let i = 0; i < 42; i++) {
    let t = random(0.06, 0.88);
    let u = random(0.22, 0.72);
    let pIn = samplePolylineAt(innerCurve, t);
    let pOut = samplePolylineAt(outerCurve, t);
    let lx = pIn[0] + (pOut[0] - pIn[0]) * u;
    let ly = pIn[1] + (pOut[1] - pIn[1]) * u;
    let rx = random(1.4, 2.8), ry = random(1.8, 3.6);
    rindHoles.push(makePoly([
      [lx - rx, ly], [lx, ly - ry], [lx + rx, ly], [lx, ly + ry]
    ]));
  }

  // 1. Longitudinal contour curves sweeping from neck to base across the rind bevel
  const numLong = 24;
  for (let k = 0; k <= numLong; k++) {
    let u = k / numLong; // 0 = inner cut edge, 1 = outer silhouette edge

    // Determine density & brush weight across the bevel cross-section:
    // u in [0, 0.14]: dark cut-epidermis rim (solid/heavy)
    // u in [0.25, 0.55]: bright cheek highlight zone (fine/hair)
    // u in [0.72, 0.96]: deep form shadow terminator (solid/heavy)
    let bName = "c_mid";
    if (u <= 0.14 || (u >= 0.74 && u <= 0.96)) {
      bName = "c_solid";
    } else if (u <= 0.22 || u >= 0.64) {
      bName = "c_heavy";
    } else if (u >= 0.32 && u <= 0.52) {
      bName = "c_hair";
    } else {
      bName = "c_fine";
    }

    brush.set(bName, CINNABAR_HEX, 1);
    let pts = [];
    for (let s = 0; s <= 64; s++) {
      let t = s / 64;
      let pIn = samplePolylineAt(innerCurve, t);
      let pOut = samplePolylineAt(outerCurve, t);
      pts.push([
        pIn[0] + (pOut[0] - pIn[0]) * u,
        pIn[1] + (pOut[1] - pIn[1]) * u
      ]);
    }
    drawClippedMirroredCurve(pts, anat.rindBevelPoly, rindHoles);
  }

  // 2. Transverse cross-contour strokes wrapping around the 3D curvature of the rind
  const numTrans = 210;
  for (let i = 0; i <= numTrans; i++) {
    let t = i / numTrans;
    let pIn = samplePolylineAt(innerCurve, t);
    let pOut = samplePolylineAt(outerCurve, t);

    // Build arched cross-contour from pIn to pOut
    let dx = pOut[0] - pIn[0], dy = pOut[1] - pIn[1];
    let nx = -dy * 0.16, ny = dx * 0.16;

    // Outer terminator solid pass (u = 0.70..1.0)
    brush.set("c_solid", CINNABAR_HEX, 1);
    drawClippedMirroredSeg(
      pIn[0] + dx * 0.72, pIn[1] + dy * 0.72,
      pOut[0], pOut[1],
      anat.rindBevelPoly, rindHoles
    );

    // Inner cut epidermis solid rim (u = 0.0..0.15)
    drawClippedMirroredSeg(
      pIn[0], pIn[1],
      pIn[0] + dx * 0.15, pIn[1] + dy * 0.15,
      anat.rindBevelPoly, rindHoles
    );

    // Full cross-contour curve (rarer in the highlight cheek zone, denser at neck & base)
    let inHighlightCheek = (t > 0.12 && t < 0.68);
    if (!inHighlightCheek || i % 2 === 0) {
      let bName = (t > 0.75 || t < 0.10) ? "c_heavy" : (i % 4 === 0 ? "c_mid" : "c_fine");
      brush.set(bName, CINNABAR_HEX, 1);
      let cPts = [];
      for (let m = 0; m <= 6; m++) {
        let u = m / 6;
        let arch = Math.sin(u * Math.PI);
        cPts.push([
          pIn[0] + dx * u + nx * arch,
          pIn[1] + dy * u + ny * arch
        ]);
      }
      drawClippedMirroredCurve(cPts, anat.rindBevelPoly, rindHoles);
    }
  }

  // 3. Sculptural woody striations inside the basal umbo / stem scar
  let baseScarPoly = makePoly([
    [512, 1038], [522, 1056], [514, 1072], [534, 1082],
    [554, 1098], [568, 1084], [584, 1094], [600, 1074],
    [600, 1024], [555, 1026]
  ]);
  hatchPolyClipped(baseScarPoly, rindHoles, 75, 1.65, "c_solid", 0);
  hatchPolyClipped(baseScarPoly, rindHoles, -45, 2.2, "c_heavy", 0);
}

function samplePolylineAt(pts, t) {
  let clamped = Math.max(0, Math.min(1, t));
  let idxFloat = clamped * (pts.length - 1);
  let i0 = Math.floor(idxFloat);
  let i1 = Math.min(pts.length - 1, i0 + 1);
  let frac = idxFloat - i0;
  return [
    pts[i0][0] + (pts[i1][0] - pts[i0][0]) * frac,
    pts[i0][1] + (pts[i1][1] - pts[i0][1]) * frac
  ];
}

// ============================================================================
// RENDER ROYAL CALYX CROWN & CURLED FILIGREE STAMENS
// ============================================================================

function renderCalyxCrownAndStamens(anat) {
  // 1. Generate 28 delicate curled stamen filaments & bilobed anthers inside the throat
  let stamenPolys = [];
  let stamenCurves = [];

  for (let i = 0; i < 28; i++) {
    let u = i / 27;
    let bx = 462 + u * 134 + random(-2, 2);
    let by = 206 - Math.sin(u * Math.PI) * 18 + random(-3, 3);
    let len = random(34, 68);
    let baseAng = (-95 + (u - 0.5) * 55) * Math.PI / 180;
    let curl = random(-0.95, 0.95);

    let spine = [];
    let leftEdge = [], rightEdge = [];
    let steps = 8;
    for (let s = 0; s <= steps; s++) {
      let t = s / steps;
      let ang = baseAng + curl * t * t;
      let prev = s === 0 ? [bx, by] : spine[s - 1];
      let stepLen = len / steps;
      let px = s === 0 ? bx : prev[0] + Math.cos(ang) * stepLen;
      let py = s === 0 ? by : prev[1] + Math.sin(ang) * stepLen;
      spine.push([px, py]);

      let nx = -Math.sin(ang), ny = Math.cos(ang);
      let w = (1 - 0.55 * t) * 1.65;
      leftEdge.push([px + nx * w, py + ny * w]);
      rightEdge.push([px - nx * w, py - ny * w]);
    }

    let filamentPoly = makePoly([...leftEdge, ...rightEdge.reverse()]);
    stamenPolys.push(filamentPoly);

    // Tiny oval anther at tip of stamen
    let tip = spine[spine.length - 1];
    let antherPts = [];
    for (let a = 0; a < 8; a++) {
      let ang = (a / 8) * Math.PI * 2;
      antherPts.push([tip[0] + Math.cos(ang) * 3.2, tip[1] + Math.sin(ang) * 2.2]);
    }
    let antherPoly = makePoly(antherPts);
    stamenPolys.push(antherPoly);
    stamenCurves.push({ spine, antherPoly, filamentPoly });
  }

  // 2. Fill the deep calyx throat cavity with 100% solid marker mass,
  // reserving the stamen filaments & anthers as crisp bare-paper filigree!
  hatchPolyClipped(anat.calyxThroatPoly, stamenPolys, 40, 1.45, "c_solid", 0);
  hatchPolyClipped(anat.calyxThroatPoly, stamenPolys, -50, 1.95, "c_heavy", 0);

  // Shade each stamen with a delicate centerline hairline and anther shadow
  for (let st of stamenCurves) {
    brush.set("c_hair", CINNABAR_HEX, 1);
    drawClippedMirroredCurve(st.spine, anat.calyxThroatPoly, []);
    hatchPolyClipped(st.antherPoly, [], 30, 1.4, "c_fine", 0);
  }

  // 3. Sculpt the outer calyx sepal walls around the throat
  // Bare-paper highlight slits along the outer ridges of the 3 crown sepal lobes
  let crownSlits = [
    makePoly([[554, 76], [562, 118], [555, 122], [548, 86]]),
    makePoly([[474, 82], [492, 128], [484, 134], [469, 94]]),
    makePoly([[416, 118], [438, 162], [431, 168], [414, 128]])
  ];
  let crownExclusions = [anat.calyxThroatPoly, ...crownSlits];

  hatchPolyClipped(anat.calyxWallPoly, crownExclusions, 68, 2.2, "c_heavy", 0);
  hatchPolyClipped(anat.calyxWallPoly, crownExclusions, -25, 3.1, "c_mid", 0);

  // Solid shadow at the base of the sepal sinuses and neck fold
  let neckShadowPoly = makePoly([
    [418, 144], [436, 202], [472, 214], [456, 152]
  ]);
  hatchPolyClipped(neckShadowPoly, crownExclusions, 20, 1.5, "c_solid", 0);
}

// ============================================================================
// RENDER LACY CUT-OUT FILIGREE PITH (MESOCARP, SEPTA, COLUMELLA & VEILS)
// ============================================================================

function renderLacyPithFiligree(anat, allArils, veilData) {
  // The pith occupies anat.pithDomainPoly OUTSIDE the 4 chambers and central cleft
  let pithExclusions = [...anat.chambers, anat.centralCleftPoly];

  // 1. CENTRAL SPINDLE CLEFT (Along fold axis x = 600)
  // Deep shadow inside the split cleft spanned by torn horizontal trabecular pith bridges!
  let cleftBridges = [];
  for (let by = 485; by <= 725; by += 18) {
    let hw = random(1.8, 3.4);
    cleftBridges.push(makePoly([
      [572, by - hw], [600, by - hw * 0.7],
      [600, by + hw * 0.7], [572, by + hw]
    ]));
  }
  hatchPolyClipped(anat.centralCleftPoly, cleftBridges, 30, 1.45, "c_solid", 0);
  hatchPolyClipped(anat.centralCleftPoly, cleftBridges, -60, 1.9, "c_heavy", 0);

  // Delicate tissue striations on the horizontal cleft bridges
  brush.set("c_hair", CINNABAR_HEX, 1);
  for (let br of cleftBridges) {
    let c = polyCentroid(br);
    drawClippedMirroredSeg(575, c[1], 600, c[1], anat.centralCleftPoly, []);
  }

  // 2. VORONOI / CELLULAR PARENCHYMA LACE INSIDE THE PITH DOMAIN
  // Creates the lacy cut-out filigree that simultaneously reads as real spongy tissue
  let b = anat.pithDomainPoly.bbox;
  let cellSeeds = [];

  for (let y = b.minY + 8; y <= b.maxY - 8; y += 13.5) {
    for (let x = b.minX + 8; x <= 596; x += 13.5) {
      let px = x + random(-4.2, 4.2);
      let py = y + random(-4.2, 4.2);
      if (!pointInPoly(px, py, anat.pithDomainPoly)) continue;
      let inChamber = false;
      for (let ch of pithExclusions) {
        if (pointInPoly(px, py, ch)) {
          inChamber = true;
          break;
        }
      }
      if (!inChamber) cellSeeds.push([px, py]);
    }
  }

  // Render cellular pores and vascular bundles across the pith
  for (let i = 0; i < cellSeeds.length; i++) {
    let sx = cellSeeds[i][0], sy = cellSeeds[i][1];

    // Find nearest neighbors to form a small polygonal pore
    let nPts = [];
    for (let a = 0; a < 7; a++) {
      let ang = (a / 7) * Math.PI * 2 + (i % 5) * 0.2;
      let distToCenter = Math.abs(600 - sx);
      // Larger lacy cut-out fenestrations in the central columella and septum junctions
      let baseR = (distToCenter < 42) ? random(3.2, 5.8) : random(1.8, 4.2);
      nPts.push([sx + Math.cos(ang) * baseR, sy + Math.sin(ang) * baseR]);
    }
    let porePoly = makePoly(nPts);

    // Check that pore stays inside pith
    let validPore = true;
    for (let pt of porePoly) {
      if (!pointInPoly(pt[0], pt[1], anat.pithDomainPoly)) { validPore = false; break; }
      for (let ch of pithExclusions) {
        if (pointInPoly(pt[0], pt[1], ch)) { validPore = false; break; }
      }
      if (!validPore) break;
    }
    if (!validPore) continue;

    // Shade the interior of the cellular pore with micro-hatching (no outline!)
    // Deeper pores along the central vascular axis get denser red; peripheral pores get hairline lace
    let distAxis = Math.abs(600 - sx);
    if (distAxis < 26 && i % 2 === 0) {
      hatchPolyClipped(porePoly, [], 45, 1.35, "c_mid", 0);
      hatchPolyClipped(porePoly, [], -45, 1.85, "c_fine", 0);
    } else if (i % 3 === 0) {
      hatchPolyClipped(porePoly, [], 30, 1.55, "c_fine", 0);
    } else {
      hatchPolyClipped(porePoly, [], -35, 1.85, "c_hair", 0);
    }
  }

  // 3. FIBROVASCULAR BUNDLE TRACES (Branching anatomical veins through the columella & septa)
  const vascularPaths = [
    [[588, 222], [584, 320], [578, 425], [568, 520], [566, 650], [574, 755], [580, 880], [586, 1005]],
    [[576, 430], [520, 424], [445, 405], [362, 376], [292, 338], [225, 315]],
    [[352, 374], [352, 455], [344, 545], [332, 618]],
    [[568, 745], [495, 728], [412, 695], [335, 646], [252, 642], [176, 648]]
  ];

  brush.set("c_fine", CINNABAR_HEX, 1);
  for (let path of vascularPaths) {
    let smoothVein = smoothOpenCurve(path, 3);
    drawClippedMirroredCurve(smoothVein, anat.pithDomainPoly, pithExclusions);
    // Companion vascular hairlines
    brush.set("c_hair", CINNABAR_HEX, 1);
    let offset1 = smoothVein.map(p => [p[0] - 2.6, p[1] + 1.4]);
    let offset2 = smoothVein.map(p => [p[0] + 2.6, p[1] - 1.4]);
    drawClippedMirroredCurve(offset1, anat.pithDomainPoly, pithExclusions);
    drawClippedMirroredCurve(offset2, anat.pithDomainPoly, pithExclusions);
  }

  // 4. SCALLOPED ALVEOLAR CRADLE BEVELS (Where pith walls meet the 4 chambers)
  // Short, fine radial shading lines feathering 4-9px into the pith around every chamber rim
  brush.set("c_hair", CINNABAR_HEX, 1);
  for (let ch of anat.chambers) {
    let cCenter = polyCentroid(ch);
    let n = ch.length;
    for (let i = 0; i < n; i++) {
      let p0 = ch[i], p1 = ch[(i + 1) % n];
      for (let s = 0; s < 3; s++) {
        let f = s / 3;
        let bx = p0[0] + (p1[0] - p0[0]) * f;
        let by = p0[1] + (p1[1] - p0[1]) * f;
        let dx = bx - cCenter[0], dy = by - cCenter[1];
        let dLen = Math.hypot(dx, dy) || 1;
        let featherLen = random(4.5, 9.5);
        drawClippedMirroredSeg(
          bx, by,
          bx + (dx / dLen) * featherLen,
          by + (dy / dLen) * featherLen,
          anat.pithDomainPoly, pithExclusions
        );
      }
    }
  }

  // 5. LACY MEMBRANE VEILS (Delicate tissue shading on the bare-paper filigree ribs)
  for (let vd of veilData) {
    hatchPolyClipped(vd.patchPoly, vd.windows, vd.v.angle, 3.8, "c_hair", 0);
  }
}

// ============================================================================
// DETACHED FESTIVE JEWEL ARILS & DROPLETS (BILATERALLY MIRRORED ACCENTS)
// ============================================================================

function buildDetachedJewels() {
  const specs = [
    // Flanking the upper split crown
    { cx: 342, cy: 118, r: 22, rot: -18 },
    { cx: 304, cy: 158, r: 15, rot: 25 },
    // Flanking the lower hip swell
    { cx: 142, cy: 912, r: 25, rot: 14 },
    { cx: 188, cy: 974, r: 19, rot: -22 },
    // Tiny jewel juice droplets near crown and base
    { cx: 382, cy: 84, r: 9.5, rot: -35 },
    { cx: 238, cy: 1018, r: 10.5, rot: 30 },
    { cx: 462, cy: 1078, r: 12.5, rot: -15 }
  ];

  let list = [];
  for (let idx = 0; idx < specs.length; idx++) {
    let sp = specs[idx];
    let rawCell = [];
    let sides = sp.r > 14 ? 6 : 5;
    for (let k = 0; k < sides; k++) {
      let ang = (k / sides) * Math.PI * 2 + (sp.rot * Math.PI / 180);
      let rMod = sp.r * (0.92 + 0.14 * ((k % 2 === 0) ? 1 : -0.5));
      rawCell.push([
        sp.cx + Math.cos(ang) * rMod,
        sp.cy + Math.sin(ang) * rMod * 1.08
      ]);
    }

    let n = rawCell.length;
    let facetedPts = [];
    for (let k = 0; k < n; k++) {
      let pPrev = rawCell[(k - 1 + n) % n];
      let pCurr = rawCell[k];
      let pNext = rawCell[(k + 1) % n];
      let c1 = [0.76 * pCurr[0] + 0.24 * pPrev[0], 0.76 * pCurr[1] + 0.24 * pPrev[1]];
      let cMid = [
        0.56 * pCurr[0] + 0.22 * pPrev[0] + 0.22 * pNext[0],
        0.56 * pCurr[1] + 0.22 * pPrev[1] + 0.22 * pNext[1]
      ];
      let c2 = [0.76 * pCurr[0] + 0.24 * pNext[0], 0.76 * pCurr[1] + 0.24 * pNext[1]];
      let eMid = [0.5 * (pCurr[0] + pNext[0]), 0.5 * (pCurr[1] + pNext[1])];
      facetedPts.push(c1, cMid, c2, eMid);
    }

    let poly = makePoly(facetedPts);
    list.push(buildArilOptics(poly, rawCell, sp.cx, sp.cy, sp.r, false, 99, idx));
  }

  return list;
}

